# ── DB-backed arm audit persistence (critical events only; fail-open) ─────────
# In-memory _ARM_AUDIT_LOG is always written first (fast, never raises).
# _persist_arm_audit_critical() additionally writes CRITICAL arm events to the
# execution_arm_audit table so they survive a restart. The table is created via
# the database tool (no DDL in app.py); this probe just checks it is available.
# ─────────────────────────────────────────────────────────────────────────────
EXECUTION_ARM_AUDIT_DB_READY = False

_CRITICAL_ARM_ACTIONS = frozenset({
    "arm", "disarm", "safety_lock", "reset_safety_lock",
    "candidate_authorized", "candidate_blocked_final",
    "enable", "disable",
})


def _probe_execution_arm_audit_table():
    """Probe the execution_arm_audit table (no DDL). Fail-open."""
    global EXECUTION_ARM_AUDIT_DB_READY
    try:
        _conn = get_db_connection()
        if _conn is None:
            raise RuntimeError("get_db_connection() returned None")
        with _conn:
            with _conn.cursor() as _cur:
                _cur.execute("SELECT 1 FROM execution_arm_audit LIMIT 0")
        _conn.close()
        EXECUTION_ARM_AUDIT_DB_READY = True
        logger.info("execution_arm_audit table ready")
    except Exception as _exc:
        logger.warning(
            "execution_arm_audit table unavailable (arm audit DB persistence disabled): %s", _exc)


def _persist_arm_audit_critical(record: dict):
    """Write critical arm-state change events to DB (fail-open, never raises)."""
    if not EXECUTION_ARM_AUDIT_DB_READY:
        return
    if record.get("action") not in _CRITICAL_ARM_ACTIONS:
        return
    try:
        import json as _jj
        _extra = {k: v for k, v in record.items()
                  if k not in ("action", "reason", "session_id", "by",
                               "new_effective", "ts", "arm_session_id")}
        _conn = get_db_connection()
        if _conn is None:
            return
        with _conn:
            with _conn.cursor() as _cur:
                _cur.execute(
                    """INSERT INTO execution_arm_audit
                           (action, reason, arm_session_id, by_actor, effective_state, extra)
                       VALUES (%s, %s, %s, %s, %s, %s::jsonb)""",
                    (record.get("action"),
                     str(record.get("reason") or "")[:500],
                     record.get("session_id") or record.get("arm_session_id"),
                     str(record.get("by") or "")[:100],
                     record.get("new_effective"),
                     _jj.dumps(_extra, default=str))
                )
        _conn.close()
    except Exception as _exc:
        logger.debug("arm audit DB persist failed (fail-open): %s", _exc)

# Reason code constants for arm/disarm audit
RC_DISARMED                  = "RC_DISARMED"
RC_ARM_EXPIRED               = "RC_ARM_EXPIRED"
RC_ARM_SESSION_MISMATCH      = "RC_ARM_SESSION_MISMATCH"
RC_ARM_INSTRUMENT_NOT_ALLOWED = "RC_ARM_INSTRUMENT_NOT_ALLOWED"
RC_ARM_CONTRACTS_EXCEEDED    = "RC_ARM_CONTRACTS_EXCEEDED"
RC_ARM_STRATEGY_NOT_ALLOWED  = "RC_ARM_STRATEGY_NOT_ALLOWED"
RC_ARM_TRADE_LIMIT           = "RC_ARM_TRADE_LIMIT"
RC_ARM_SESSION_LOSS_LIMIT    = "RC_ARM_SESSION_LOSS_LIMIT"
RC_ARM_DIRECTION_RESTRICTED  = "RC_ARM_DIRECTION_RESTRICTED"
RC_SAFETY_LOCKED             = "RC_SAFETY_LOCKED"
RC_EXECUTION_DISABLED        = "RC_EXECUTION_DISABLED"


def _effective_execution_state(arm_state=None):
    """Return the 5-value effective execution state string.

    Order of precedence (most severe first):
      1. safety_locked — always reported regardless of execution mode
      2. mode check    — disabled / paper short-circuits the arm state
      3. arm state     — live_armed / live_available_disarmed
    """
    st = arm_state
    if st is None:
        with _ARM_STATE_LOCK:
            st = dict(_ARM_STATE)

    # Safety lock always wins, regardless of execution mode
    if st.get("safety_locked"):
        return "safety_locked"

    mode = resolve_execution_mode()
    if mode == "disabled":
        return "disabled"
    if not execution_is_live(mode):
        return "paper"

    # Live-capable mode (traderspost / pickmytrade)
    if not st.get("armed"):
        return "live_available_disarmed"
    exp = st.get("expires_at")
    if exp:
        try:
            if now_utc() > datetime.fromisoformat(exp):
                return "live_available_disarmed"
        except Exception:
            return "live_available_disarmed"
    return "live_armed"


def _record_arm_audit(action, prev_state, new_state, **kwargs):
    """Append an arm-state-change audit record (fail-open, never raises).
    Critical events (arm/disarm/safety_lock/reset) are also persisted to the
    execution_arm_audit DB table via _persist_arm_audit_critical()."""
    try:
        record = {
            "ts":             now_utc().isoformat(),
            "action":         action,
            "prev_armed":     (prev_state or {}).get("armed"),
            "new_armed":      (new_state or {}).get("armed"),
            "prev_effective": _effective_execution_state(prev_state),
            "new_effective":  _effective_execution_state(new_state),
            "session_id":     (new_state or {}).get("arm_session_id"),
            "expires_at":     (new_state or {}).get("expires_at"),
            "limits": {
                "instruments":    (new_state or {}).get("allowed_instruments"),
                "max_contracts":  (new_state or {}).get("max_contracts"),
                "max_trades":     (new_state or {}).get("max_trades"),
                "max_session_loss": (new_state or {}).get("max_session_loss"),
            },
            "configured_mode": _configured_execution_mode(),
        }
        record.update({k: v for k, v in kwargs.items()
                       if k not in ("password", "token", "webhook_url", "secret")})
        with _ARM_AUDIT_LOCK:
            _ARM_AUDIT_LOG.append(record)
        # Persist critical events to DB (fail-open; deque already written above)
        _persist_arm_audit_critical(record)
    except Exception:
        pass


def _disarm(reason="operator_manual", by="system"):
    """Thread-safe disarm. Always succeeds. Returns previous state snapshot."""
    with _ARM_STATE_LOCK:
        prev = dict(_ARM_STATE)
        _ARM_STATE["armed"]           = False
        _ARM_STATE["arm_session_id"]  = None
        _ARM_STATE["armed_by"]        = None
        _ARM_STATE["armed_at"]        = None
        _ARM_STATE["expires_at"]      = None
        _ARM_STATE["disarm_reason"]   = reason
        _ARM_STATE["last_changed_at"] = now_utc().isoformat()
        _ARM_STATE["last_changed_by"] = by
        new = dict(_ARM_STATE)
    _record_arm_audit("disarm", prev, new, reason=reason, by=by)
    logger.info("Execution DISARMED by %s — reason: %s", by, reason)
    return prev


def _enable_execution(by="operator"):
    """Enable the execution software switch.
    Sets execution_enabled=True; leaves armed unchanged (still requires ARM).
    Persisted via execution_arm_audit (action='enable').
    Returns (prev_state, new_state).
    """
    with _ARM_STATE_LOCK:
        prev = dict(_ARM_STATE)
        _ARM_STATE["execution_enabled"] = True
        _ARM_STATE["last_changed_at"]   = now_utc().isoformat()
        _ARM_STATE["last_changed_by"]   = by
        new = dict(_ARM_STATE)
    _record_arm_audit("enable", prev, new, by=by)
    logger.info("Execution ENABLED by %s", by)
    return prev, new


def _disable_execution(reason="operator_manual", by="operator"):
    """Disable the execution software switch and immediately disarm.
    Sets execution_enabled=False + armed=False.
    Existing active-trade protective orders are NOT affected.
    Persisted via execution_arm_audit (action='disable').
    Returns (prev_state, new_state).
    """
    with _ARM_STATE_LOCK:
        prev = dict(_ARM_STATE)
        _ARM_STATE["execution_enabled"] = False
        _ARM_STATE["armed"]             = False
        _ARM_STATE["arm_session_id"]    = None
        _ARM_STATE["armed_by"]          = None
        _ARM_STATE["armed_at"]          = None
        _ARM_STATE["expires_at"]        = None
        _ARM_STATE["disarm_reason"]     = reason
        _ARM_STATE["last_changed_at"]   = now_utc().isoformat()
        _ARM_STATE["last_changed_by"]   = by
        new = dict(_ARM_STATE)
    _record_arm_audit("disable", prev, new, reason=reason, by=by)
    logger.info("Execution DISABLED by %s — reason: %s", by, reason)
    return prev, new


def _restore_execution_enabled_from_db():
    """Restore execution_enabled from the last enable/disable audit record.
    Called at boot AFTER _probe_execution_arm_audit_table() succeeds.
    Fail-open: any error leaves execution_enabled=False (safe default).
    """
    if not EXECUTION_ARM_AUDIT_DB_READY:
        return
    try:
        _conn = get_db_connection()
        if _conn is None:
            return
        with _conn:
            with _conn.cursor() as _cur:
                _cur.execute(
                    """SELECT action FROM execution_arm_audit
                       WHERE action IN ('enable', 'disable')
                       ORDER BY recorded_at DESC LIMIT 1"""
                )
                row = _cur.fetchone()
        _conn.close()
        if row and row[0] == "enable":
            with _ARM_STATE_LOCK:
                _ARM_STATE["execution_enabled"] = True
            logger.info("execution_enabled restored: True (last action=enable)")
        else:
            logger.info("execution_enabled boot default: False (no prior enable or last=disable)")
    except Exception as _exc:
        logger.warning(
            "execution_enabled restore failed (fail-open, staying False): %s", _exc)


def _safety_lock(reason="emergency_kill_switch", by="system"):
    """Thread-safe safety lock. Sets safety_locked=True + disarms immediately."""
    with _ARM_STATE_LOCK:
        prev = dict(_ARM_STATE)
        _ARM_STATE["armed"]            = False
        _ARM_STATE["arm_session_id"]   = None
        _ARM_STATE["armed_by"]         = None
        _ARM_STATE["armed_at"]         = None
        _ARM_STATE["expires_at"]       = None
        _ARM_STATE["disarm_reason"]    = reason
        _ARM_STATE["safety_locked"]    = True
        _ARM_STATE["safety_lock_reason"] = reason
        _ARM_STATE["safety_lock_at"]   = now_utc().isoformat()
        _ARM_STATE["last_changed_at"]  = now_utc().isoformat()
        _ARM_STATE["last_changed_by"]  = by
        new = dict(_ARM_STATE)
    _record_arm_audit("safety_lock", prev, new, reason=reason, by=by)
    logger.critical("Execution SAFETY LOCKED by %s — reason: %s", by, reason)
    return prev


def _reset_safety_lock(by="operator"):
    """Reset the safety lock so arming is possible again.
    Requires no open positions with unknown protective-order state.
    Returns (ok, error_message).
    """
    # Check for unknown protective-order state
    try:
        for inst_c in list(ASSETS.keys()):
            at = active_trade_for(inst_c)
            if at and at.get("protective_order_state") == "unknown":
                return False, (f"{inst_c} has an open position with unknown protective-order "
                               "state. Reconcile before resetting the safety lock.")
    except Exception as _e:
        logger.warning("Safety-lock reset: active-trade check failed (%s) — proceeding", _e)
    with _ARM_STATE_LOCK:
        if not _ARM_STATE.get("safety_locked"):
            return True, "Not locked"
        prev = dict(_ARM_STATE)
        _ARM_STATE["safety_locked"]     = False
        _ARM_STATE["safety_lock_reason"] = None
        _ARM_STATE["safety_lock_at"]    = None
        _ARM_STATE["last_changed_at"]   = now_utc().isoformat()
        _ARM_STATE["last_changed_by"]   = by
        new = dict(_ARM_STATE)
    _record_arm_audit("reset_safety_lock", prev, new, by=by)
    logger.info("Safety lock RESET by %s", by)
    return True, "ok"


def _arm_preflight_check(data):
    """Run all pre-arm checks. Returns (ok: bool, errors: list[str]).
    FAIL-CLOSED: any uncaught exception is treated as a failed check.
    """
    errors = []

    # 1. EXECUTION_MODE must be live-capable
    mode = resolve_execution_mode()
    if not execution_is_live(mode):
        errors.append(f"EXECUTION_MODE must be live-capable (traderspost/pickmytrade); "
                      f"current effective mode is {mode!r}.")

    # 2. Not safety-locked
    with _ARM_STATE_LOCK:
        if _ARM_STATE.get("safety_locked"):
            errors.append(f"System is safety-locked ({_ARM_STATE.get('safety_lock_reason')}). "
                          "Reset the safety lock before arming.")

    # 3. TradersPost URL configured
    if mode == "traderspost":
        if not (TRADERSPOST_WEBHOOK_URL or "").strip():
            errors.append("TradersPost webhook URL not configured "
                          "(TRADERSPOST_WEBHOOK_URL env var missing).")

    # 4. Databento health (if enabled; fail-closed on exception)
    #    At arm time we check connectivity/tick freshness only.  Data-staleness codes
    #    (STALE_VWAP, STALE_BAR) are NOT arm-blockers — they resolve on the next bar/push
    #    and are re-checked hard at actual execution time inside _maybe_auto_execute().
    _ARM_DATA_STALE_OK = {RC_STALE_VWAP, RC_STALE_BAR, "STALE_VWAP", "STALE_BAR",
                          "databento_bar_stale", "vwap_stale", "vwap_unavailable",
                          "vwap_missing", "vwap_ok"}
    if DATABENTO_ENABLED:
        instruments = data.get("instruments") or list(ASSETS.keys())
        _probe_inst = instruments[0] if instruments else None
        if _probe_inst and _probe_inst in ASSETS:
            try:
                db_ok, db_reason, _ = _check_databento_execution_health(_probe_inst)
                if not db_ok and db_reason not in _ARM_DATA_STALE_OK:
                    errors.append(f"Databento feed unhealthy: {db_reason}")
                elif not db_ok:
                    logger.info("Arm preflight: Databento data-staleness (%s) — "
                                "allowed at arm time, will be re-checked at execution.", db_reason)
            except Exception as _db_e:
                errors.append(f"Databento health check failed: {type(_db_e).__name__}")

    # 5. Daily loss lockout
    try:
        instruments = data.get("instruments") or list(ASSETS.keys())
        for inst_c in instruments:
            if inst_c not in ASSETS:
                continue
            _loss_cap = max_losses_per_day(inst_c)
            if _loss_cap is not None:
                _losses = _losses_today(inst_c)
                if _losses >= _loss_cap:
                    errors.append(f"{inst_c} has hit its daily loss limit "
                                  f"({_losses}/{_loss_cap} losing trades today).")
    except Exception as _dl_e:
        errors.append(f"Daily loss limit check failed: {type(_dl_e).__name__}")

    # 6. No unprotected active positions
    try:
        for inst_c in list(ASSETS.keys()):
            at = active_trade_for(inst_c)
            if at:
                if not at.get("stop_loss") and not at.get("target1"):
                    errors.append(f"{inst_c} has an open position with no protective stop — "
                                  "cannot arm until the position is protected or closed.")
                if at.get("protective_order_state") == "unknown":
                    errors.append(f"{inst_c} has an open position with unknown protective-order "
                                  "state — cannot arm until reconciliation completes.")
    except Exception as _at_e:
        logger.debug("Preflight active-trade check failed (fail-open): %s", _at_e)

    # 7. Requested instruments are in the approved registry
    for inst_c in (data.get("instruments") or []):
        if inst_c not in ASSETS:
            errors.append(f"Unknown instrument: {inst_c!r}. Allowed: {list(ASSETS.keys())}")

    # 8. Contract limits within hard backend limits
    for inst_c, req_c in (data.get("max_contracts") or {}).items():
        if inst_c not in ASSETS:
            continue
        hard_limit = max_contracts(inst_c)
        try:
            if int(req_c) > hard_limit:
                errors.append(f"{inst_c}: requested {req_c} contracts exceeds hard limit "
                              f"({hard_limit}).")
        except (ValueError, TypeError):
            errors.append(f"{inst_c}: max_contracts must be an integer.")

    return len(errors) == 0, errors


def _check_arm_for_transmission(instrument, contracts, strategy=None, arm_session_id=None,
                                direction=None):
    """Final arm gate immediately before any live broker transmission.

    Returns (ok: bool, reason_code: str, diagnostics: dict).
    FAIL-CLOSED: any exception returns (False, RC_DISARMED, {...}).
    Must be called with the execution lock ALREADY HELD when applicable.

    Checks the raw arm state dict directly so it is testable without patching
    resolve_execution_mode().  Callers are already gated on execution_is_live(mode)
    so we do not re-derive the effective execution state here.
    """
    try:
        with _ARM_STATE_LOCK:
            st = dict(_ARM_STATE)   # snapshot under lock

        diag = {
            "instrument":        instrument,
            "contracts":         contracts,
            "strategy":          strategy,
            "direction":         direction,
            "check_session_id":  arm_session_id,
            "active_session_id": st.get("arm_session_id"),
            "armed":             st.get("armed"),
            "safety_locked":     st.get("safety_locked"),
            "trades_used":       st.get("trades_used", 0),
            "max_trades":        st.get("max_trades"),
            "session_pnl":       st.get("session_pnl", 0.0),
            "max_session_loss":  st.get("max_session_loss"),
            "time_remaining_sec": None,
        }

        # Check 0: execution software switch must be enabled.
        # FAIL-CLOSED: absent key treated as disabled.
        if not st.get("execution_enabled"):
            return False, RC_EXECUTION_DISABLED, {**diag,
                "reason": "execution is disabled — call POST /execution/enable first",
                "effective_state": "execution_disabled"}

        # Check 1: safety lock (highest priority among armed checks)
        if st.get("safety_locked"):
            return False, RC_SAFETY_LOCKED, {**diag, "reason": "system is safety-locked",
                                              "effective_state": "safety_locked"}

        # Check 2: must be actively armed
        if not st.get("armed"):
            return False, RC_DISARMED, {**diag, "reason": "system is not armed",
                                         "effective_state": "disarmed"}

        # Check 3: session not expired
        exp_raw = st.get("expires_at")
        if exp_raw:
            try:
                exp_dt = datetime.fromisoformat(exp_raw)
                remaining = (exp_dt - now_utc()).total_seconds()
                diag["time_remaining_sec"] = round(remaining, 1)
                if remaining <= 0:
                    return False, RC_ARM_EXPIRED, {**diag, "reason": "arm session expired",
                                                    "effective_state": "live_available_disarmed"}
            except Exception:
                return False, RC_ARM_EXPIRED, {**diag, "reason": "expires_at malformed"}

        # Check 3: arm-session ID match (if candidate was approved under a session)
        if arm_session_id is not None and st.get("arm_session_id") != arm_session_id:
            return False, RC_ARM_SESSION_MISMATCH, {
                **diag, "reason": "arm-session ID mismatch — system was re-armed since approval"}

        # Check 4: instrument allowed
        allowed_insts = st.get("allowed_instruments") or []
        if allowed_insts and instrument not in allowed_insts:
            return False, RC_ARM_INSTRUMENT_NOT_ALLOWED, {
                **diag, "reason": f"{instrument} not in allowed instruments {allowed_insts}"}

        # Check 5: contracts within session limit
        max_c_map = st.get("max_contracts") or {}
        max_c = max_c_map.get(instrument, ARM_DEFAULT_MAX_CONTRACTS)
        if contracts > max_c:
            return False, RC_ARM_CONTRACTS_EXCEEDED, {
                **diag, "reason": f"{contracts} contracts > session limit {max_c} for {instrument}"}

        # Check 6: strategy allowed (if a restriction is set)
        allowed_strats = st.get("allowed_strategies")
        if allowed_strats is not None and strategy and strategy not in allowed_strats:
            return False, RC_ARM_STRATEGY_NOT_ALLOWED, {
                **diag, "reason": f"strategy {strategy!r} not in allowed list {allowed_strats}"}

        # Check 7: direction restriction
        dir_restr = st.get("direction_restriction")
        if dir_restr and direction:
            if dir_restr.lower() != (direction or "").lower():
                return False, RC_ARM_DIRECTION_RESTRICTED, {
                    **diag, "reason": f"direction {direction!r} restricted to {dir_restr!r}"}

        # Check 8: session trade count
        trades_used = st.get("trades_used", 0)
        max_trades  = st.get("max_trades", ARM_DEFAULT_MAX_TRADES)
        if trades_used >= max_trades:
            return False, RC_ARM_TRADE_LIMIT, {
                **diag, "reason": f"session trade limit reached ({trades_used}/{max_trades})"}

        # Check 9: session loss limit
        max_loss = st.get("max_session_loss")
        if max_loss is not None:
            pnl = st.get("session_pnl", 0.0)
            if pnl <= -abs(float(max_loss)):
                return False, RC_ARM_SESSION_LOSS_LIMIT, {
                    **diag, "reason": f"session loss limit reached (P&L ${pnl:+.2f}, limit $-{abs(max_loss):.2f})"}

        return True, "armed", diag

    except Exception as _arm_exc:
        logger.error("_check_arm_for_transmission EXCEPTION (fail-closed): %s", _arm_exc)
        return False, RC_DISARMED, {"error": type(_arm_exc).__name__, "instrument": instrument}


def _arm_increment_trades_used():
    """Increment the session trade counter after a confirmed send. Thread-safe."""
    with _ARM_STATE_LOCK:
        _ARM_STATE["trades_used"] = _ARM_STATE.get("trades_used", 0) + 1


def _arm_update_session_pnl(pnl_delta):
    """Update session P&L by delta (negative = loss). Thread-safe."""
    with _ARM_STATE_LOCK:
        _ARM_STATE["session_pnl"] = _ARM_STATE.get("session_pnl", 0.0) + pnl_delta


# ── Databento watcher grace-period state ─────────────────────────────────────
# Counts consecutive 30-second ticks where the feed is hard-unhealthy.
# A brief reconnect (<60 s) will not disarm; only a sustained outage will.
_DB_WATCHER_UNHEALTHY_TICKS = 0
_DB_WATCHER_GRACE_TICKS     = 2   # require 2 consecutive bad ticks (~60 s) to disarm
# Only these reason codes are treated as "hard" connectivity failures by the
# watcher.  Data-staleness codes (STALE_VWAP, STALE_BAR, stale tick age) are
# NOT watcher-level disarm triggers — they are re-checked at execution time.
_DB_WATCHER_HARD_CODES = frozenset({
    "databento_disconnected",
    "databento_instrument_not_subscribed",
    "databento_tick_timestamp_missing",
})


def _auto_disarm_watcher():
    """Daemon thread: auto-disarm on arm expiry, Databento disconnect, daily loss, etc.
    Runs every 30 seconds. Fail-open: exceptions are swallowed to keep the thread alive.
    """
    global _DB_WATCHER_UNHEALTHY_TICKS
    while True:
        try:
            time.sleep(30)
            with _ARM_STATE_LOCK:
                armed     = _ARM_STATE.get("armed", False)
                exp_raw   = _ARM_STATE.get("expires_at")
                insts     = list(_ARM_STATE.get("allowed_instruments") or ASSETS.keys())
                max_loss  = _ARM_STATE.get("max_session_loss")
                sess_pnl  = _ARM_STATE.get("session_pnl", 0.0)
                safety_locked = _ARM_STATE.get("safety_locked", False)
            if not armed:
                _DB_WATCHER_UNHEALTHY_TICKS = 0   # reset grace counter when not armed
                continue

            # (A) Arm expired
            if exp_raw:
                try:
                    if now_utc() > datetime.fromisoformat(exp_raw):
                        _disarm("arm_expired", by="auto_watcher")
                        _DB_WATCHER_UNHEALTHY_TICKS = 0
                        continue
                except Exception:
                    _disarm("arm_expired", by="auto_watcher")
                    _DB_WATCHER_UNHEALTHY_TICKS = 0
                    continue

            # (B) Databento hard connectivity failure — with grace period.
            #     Transient reconnects (~10 s) should NOT disarm; only a sustained
            #     outage (≥ GRACE_TICKS × 30 s ≈ 60 s) triggers disarm.
            #     Data-staleness reasons (STALE_VWAP, stale bar/tick age) are
            #     intentionally excluded — they are re-checked at trade time.
            if DATABENTO_ENABLED and insts:
                try:
                    db_ok, db_reason, _ = _check_databento_execution_health(insts[0])
                    is_hard_fail = (not db_ok
                                    and db_reason in _DB_WATCHER_HARD_CODES
                                    and "disabled" not in db_reason.lower())
                    if is_hard_fail:
                        _DB_WATCHER_UNHEALTHY_TICKS += 1
                        logger.warning(
                            "Databento watcher: hard failure (%s) — grace %d/%d%s",
                            db_reason, _DB_WATCHER_UNHEALTHY_TICKS, _DB_WATCHER_GRACE_TICKS,
                            " — disarming now" if _DB_WATCHER_UNHEALTHY_TICKS >= _DB_WATCHER_GRACE_TICKS else " — holding",
                        )
                        if _DB_WATCHER_UNHEALTHY_TICKS >= _DB_WATCHER_GRACE_TICKS:
                            _disarm("databento_disconnected", by="auto_watcher")
                            _DB_WATCHER_UNHEALTHY_TICKS = 0
                            continue
                    else:
                        if _DB_WATCHER_UNHEALTHY_TICKS > 0:
                            logger.info("Databento watcher: feed recovered — resetting grace counter")
                        _DB_WATCHER_UNHEALTHY_TICKS = 0
                except Exception:
                    _DB_WATCHER_UNHEALTHY_TICKS = 0   # fail-open for watcher

            # (C) Daily loss limit breached for any allowed instrument
            try:
                for inst_c in insts:
                    if inst_c not in ASSETS:
                        continue
                    _loss_cap = max_losses_per_day(inst_c)
                    if _loss_cap is not None:
                        _losses = _losses_today(inst_c)
                        if _losses >= _loss_cap:
                            _disarm("daily_loss_limit", by="auto_watcher")
                            break
            except Exception:
                pass

            # (D) Session loss limit
            if max_loss is not None and sess_pnl <= -abs(float(max_loss)):
                _disarm("session_loss_limit", by="auto_watcher")
                continue

            # (E) LRE blocking error state (high error count)
            try:
                if _get_lre_error_count() >= 10:
                    _disarm("lre_failure", by="auto_watcher")
                    continue
            except Exception:
                pass

        except Exception as _watcher_exc:
            logger.debug("auto_disarm_watcher error (fail-open): %s", _watcher_exc)


_arm_watcher_thread = threading.Thread(target=_auto_disarm_watcher, daemon=True, name="arm-watcher")
_arm_watcher_thread.start()

# ── Shared Trade Memory weighting (display-only; governor + analyst single source).
# STRATEGY_VERSION is bumped MANUALLY whenever the trade LOGIC (filters / indicators
# / rules) changes; prior-version closed trades are then heavily down-weighted so
# stale logic stops dragging current confidence. Stamped on every new closed trade.
STRATEGY_VERSION       = 1
# Recency tiers (rank 1 = most-recently closed). Newest block full weight, the next
# ~100 half, everything older one-fifth — recent results dominate the lens.
GOV_RECENCY_TIER1_N    = 25
GOV_RECENCY_TIER1_W    = 1.0
GOV_RECENCY_TIER2_N    = 125            # cumulative cutoff: ranks 26..125 == the "next 100"
GOV_RECENCY_TIER2_W    = 0.5
GOV_RECENCY_OLDER_W    = 0.2
# Version factor: current-version trades full weight, prior-version heavily reduced.
GOV_VERSION_CURRENT_W  = 1.0
GOV_VERSION_PRIOR_W    = 0.2
# Source factor: the bot's OWN live trades carry full weight; imported TradeZella journal
# trades are an external, DOWN-WEIGHTED source so historical journal data can NEVER dominate
# the bot's own live history (stacks multiplicatively with the version factor for safety).
GOV_SOURCE_LIVE_W       = 1.0
GOV_SOURCE_TRADEZELLA_W = 0.25
# Similarity gates: minimum scored-dimension matches per trade + minimum comparable
# trades before the historical lens is "ready" (else it stays neutral / 50).
GOV_SIM_MIN_SCORE      = 3
GOV_SIM_MIN_MATCHES    = 5
# Component nudge caps — the CURRENT-setup anchor dominates; Live / AI / Historical
# can each only nudge it within these bounds, so history can NEVER single-handedly
# drag a strong live setup below the READY threshold (non-domination floor).
GOV_HIST_CAP           = 12
GOV_LIVE_CAP           = 8
GOV_AI_CAP             = 8

# ── Unified Analyst Report (DISPLAY-ONLY) ────────────────────────────────────
# ONE cohesive thesis that CONSUMES the already-assembled analyst / trade_debate /
# confidence_governor / trade_memory / volatility / news blocks (it never recomputes
# them and has NO money-path veto of its own). The open-position loop pushes a fresh
# thesis to the JOURNAL channel every ANALYST_REPORT_INTERVAL while a trade is live.
ANALYST_REPORT_INTERVAL     = int(os.environ.get("ANALYST_REPORT_INTERVAL", 900))  # open-position thesis cadence (s)
ANALYST_REPORT_CONF_EPS     = 1     # min |Δ| (pts) to call a confidence move non-flat
ANALYST_REPORT_BASELINE_TTL = 600   # re-baseline the confidence delta after this many s
ANALYST_REPORT_PREV_CONF    = {}    # inst -> {"score": int, "components": {name: score}, "ts": datetime}
ANALYST_REPORT_LAST_SENT    = {}    # inst -> datetime of last journal push (loop thread only)
ANALYST_REPORT_LOCK         = threading.Lock()
_ANALYST_REPORT_DISCLAIMER  = (
    "Unified read over the existing analyst, debate, governor, memory, volatility & "
    "news engines. DISPLAY-ONLY — never places or changes a trade. Outcome "
    "probabilities are a derived heuristic estimate."
)

# Opening-range + Opening-Drive window (Eastern Time, decimal hours).
OPENING_RANGE_START_ET      = 8.0    # OR builds from 08:00 ET
OPENING_RANGE_BUILD_MIN     = 30     # ...over the first 30 minutes
OPENING_DRIVE_WINDOW_END_ET = 10.0   # Opening Drive is only eligible 08:00–10:00 ET

# Detection thresholds (FAIL-OPEN; tuned conservatively).
STRAT_VWAP_PULLBACK_ATR  = 0.6     # price within 0.6*ATR of VWAP == "pullback into VWAP"
STRAT_RANGE_TIGHT_ATR    = 1.5     # consolidation width <= 1.5*ATR == "tight range"
STRAT_OB_ZONE_PROXIMITY_ATR = 1.0  # within 1 ATR of supply/demand == "price at order-block zone"
STRAT_MOVE_THRESH_PCT    = 0.0015  # +/-0.15% session move == directional session bias
RANGE_LOOKBACK_MIN       = 30      # rolling window for the consolidation range
BREAKOUT_RECENT_SEC      = 180     # exclude the last 3 min so a breakout tick isn't in its own range

# ── 9:30 ET Breakout Mode (DISPLAY-ONLY advisory) ────────────────────────────
# A professional opening-range breakout model anchored to the 09:30 ET EQUITY cash
# open — deliberately SEPARATE from the 08:00 strategy-engine opening range above
# (which is left untouched so the goldens stay byte-identical). FLAG-GATED,
# DEFAULT-OFF: when OFF nothing is tracked and result["breakout_mode"] is never set.
# It NEVER touches the strict gate, verdict, directions, sizing or money path.
BREAKOUT_MODE_ENABLED   = _env_flag_on("BREAKOUT_MODE_ENABLED", default_on=False)
BREAKOUT_OR_START_ET    = 9.5     # opening range builds from 09:30 ET (equity cash open)
BREAKOUT_OR_BUILD_MIN   = 15      # ...over the first 15 minutes (09:30–09:45 ET)
BREAKOUT_WATCH_END_ET   = 11.0    # stop hunting fresh breakouts after 11:00 ET
BREAKOUT_QUALITY_READY  = 70      # min breakout-quality score (0–100) to call a side READY
BREAKOUT_BUFFER_ATR     = 0.05    # price must clear the OR edge by this * ATR to count as a break
BREAKOUT_EXT_ATR        = 1.5     # > this many ATR beyond the OR edge == overextended (no chase)
BREAKOUT_WALL_ATR       = 1.0     # an opposing S/D level within this * ATR == a wall directly in front
BREAKOUT_OR_LOCK        = threading.Lock()
BREAKOUT_OR_BY_TICKER   = {}
_BREAKOUT_DISCLAIMER    = (
    "9:30 ET opening-range breakout advisory. DISPLAY-ONLY — it never places, sizes or "
    "changes a trade; the strict gate stays authoritative. Targets are a dynamic R:R "
    "estimate; prop / daily-loss limits are enforced by the existing safety controls."
)


# Per-instrument intraday tracker (opening range + per-session OHLC + rolling
