def _score_range_expansion_breakout(ctx):
    if ctx["broke_range_high"]:
        direction = "Long"
    elif ctx["broke_range_low"]:
        direction = "Short"
    else:
        direction = None
    if direction == "Long":
        conditions = [
            ("ATR contraction (squeeze)", ctx["atr_contraction"]),
            ("Tight consolidation range", ctx["range_tight"]),
            ("Volume spike", ctx["volume_ok"]),
            ("Breakout above range", ctx["broke_range_high"]),
            ("Breakout close confirmed", ctx["has_bull_confirm"]),
        ]
    elif direction == "Short":
        conditions = [
            ("ATR contraction (squeeze)", ctx["atr_contraction"]),
            ("Tight consolidation range", ctx["range_tight"]),
            ("Volume spike", ctx["volume_ok"]),
            ("Breakout below range", ctx["broke_range_low"]),
            ("Breakout close confirmed", ctx["has_bear_confirm"]),
        ]
    else:
        conditions = [("Range breakout in progress", False)]
    return {"direction": direction, "conditions": conditions, "target_r": 2.0}


def _score_opening_range_breakout(ctx):
    """Post-opening-range breakout: price closes beyond the COMPLETED opening range on
    a volume push with a confirming candle. Distinct from Opening Drive — which also
    requires VWAP-side alignment + CVD momentum and only fires inside the opening
    window — ORB is the plain range break and targets a wider, fixed 1:4 (the one
    sanctioned exception to the 1:1 rule, applied to the trade plan downstream)."""
    long_break  = bool(ctx["or_complete"] and ctx["or_high"] is not None
                       and ctx["price"] is not None and ctx["price"] > ctx["or_high"])
    short_break = bool(ctx["or_complete"] and ctx["or_low"] is not None
                       and ctx["price"] is not None and ctx["price"] < ctx["or_low"])
    if long_break:
        direction = "Long"
    elif short_break:
        direction = "Short"
    else:
        direction = None
    if direction == "Long":
        conditions = [
            ("Opening range complete", ctx["or_complete"]),
            ("Break above opening-range high", long_break),
            ("Volume push", ctx["volume_ok"]),
            ("Breakout close confirmed", ctx["has_bull_confirm"]),
        ]
    elif direction == "Short":
        conditions = [
            ("Opening range complete", ctx["or_complete"]),
            ("Break below opening-range low", short_break),
            ("Volume push", ctx["volume_ok"]),
            ("Breakout close confirmed", ctx["has_bear_confirm"]),
        ]
    else:
        conditions = [("Opening-range breakout in progress", False)]
    return {"direction": direction, "conditions": conditions, "target_r": 4.0}


def _score_compression_breakout(ctx):
    """Volatility coil + volume expansion breakout. Direction driven by which range
    edge price exits. Proxy: range_tight + broke_range_high/low + volume_ok."""
    if ctx["broke_range_high"]:
        direction = "Long"
    elif ctx["broke_range_low"]:
        direction = "Short"
    else:
        direction = None
    if direction == "Long":
        conditions = [
            ("ATR contraction / tight coil",  ctx["atr_contraction"] or ctx["range_tight"]),
            ("Tight consolidation range",      ctx["range_tight"]),
            ("Break above coil",               ctx["broke_range_high"]),
            ("Volume on breakout",             ctx["volume_ok"]),
            ("Bullish breakout close",         ctx["has_bull_confirm"]),
        ]
    elif direction == "Short":
        conditions = [
            ("ATR contraction / tight coil",  ctx["atr_contraction"] or ctx["range_tight"]),
            ("Tight consolidation range",      ctx["range_tight"]),
            ("Breakdown below coil",           ctx["broke_range_low"]),
            ("Volume on breakdown",            ctx["volume_ok"]),
            ("Bearish breakdown close",        ctx["has_bear_confirm"]),
        ]
    else:
        conditions = [("Range break in progress", False)]
    return {"direction": direction, "conditions": conditions, "target_r": 2.0}


def _score_vwap_pullback_continuation(ctx):
    """Established trend pulls back to VWAP then resumes. Direction from VWAP side.
    Distinct from VWAP_TREND_CONTINUATION — this requires the near_vwap pullback
    touch whereas VTC measures the broader trend + any bar."""
    if ctx["price_above_vwap"]:
        direction = "Long"
    elif ctx["price_below_vwap"]:
        direction = "Short"
    else:
        direction = None
    if direction == "Long":
        conditions = [
            ("Uptrend structure (BOS/CHOCH)", ctx["structure_long"]),
            ("Price above VWAP",              ctx["price_above_vwap"]),
            ("Pullback near VWAP",            ctx["near_vwap"]),
            ("Continuation candle",           ctx["has_bull_confirm"]),
            ("Volume expansion",              ctx["volume_ok"]),
        ]
    elif direction == "Short":
        conditions = [
            ("Downtrend structure (BOS/CHOCH)", ctx["structure_short"]),
            ("Price below VWAP",               ctx["price_below_vwap"]),
            ("Pullback near VWAP",             ctx["near_vwap"]),
            ("Continuation candle",            ctx["has_bear_confirm"]),
            ("Volume expansion",               ctx["volume_ok"]),
        ]
    else:
        conditions = [("Price on one side of VWAP", False)]
    return {"direction": direction, "conditions": conditions, "target_r": 1.8}


def _score_order_block_rejection(ctx):
    """Price taps a supply/demand order-block zone and rejects.
    Primary signal: price is within STRAT_OB_ZONE_PROXIMITY_ATR of the nearest
    supply (for shorts) or demand (for longs) level — sourced from get_nearest_levels(),
    the same authoritative zone data used by the main analysis engine.
    CHOCH/BOS presence is kept as a tiebreaker for direction when price is
    simultaneously close to both zones, but it is NOT the primary gate."""
    at_supply = ctx.get("at_supply_zone", False)
    at_demand = ctx.get("at_demand_zone", False)
    has_supply_struct = ctx["has_choch_supply"] or ctx["has_bos_supply"]
    has_demand_struct = ctx["has_choch_demand"] or ctx["has_bos_demand"]

    sup_dist = ctx.get("zone_dist_supply_atr")
    dem_dist = ctx.get("zone_dist_demand_atr")
    nearest_supply = ctx.get("nearest_supply")
    nearest_demand = ctx.get("nearest_demand")

    # Direction: prefer zone actually touched; use structure as tiebreaker
    if at_supply and at_demand:
        # Both zones close — use structural signals as tiebreaker
        direction = "Short" if has_supply_struct else ("Long" if has_demand_struct else "Short")
    elif at_supply:
        direction = "Short"
    elif at_demand:
        direction = "Long"
    elif has_supply_struct and not has_demand_struct:
        direction = "Short"   # fallback: structure only, no zone proximity
    elif has_demand_struct and not has_supply_struct:
        direction = "Long"
    else:
        direction = None

    sup_label = (f"Supply zone at {nearest_supply:.1f}"
                 if nearest_supply is not None else "Supply zone present")
    dem_label = (f"Demand zone at {nearest_demand:.1f}"
                 if nearest_demand is not None else "Demand zone present")
    sup_dist_label = (f" ({sup_dist:.2f} ATR away)" if sup_dist is not None else "")
    dem_dist_label = (f" ({dem_dist:.2f} ATR away)" if dem_dist is not None else "")

    if direction == "Short":
        conditions = [
            (f"Price at supply zone{sup_dist_label}",       at_supply),
            ("Supply zone present (fallback)",              not at_supply and has_supply_struct),
            (sup_label,                                     nearest_supply is not None),
            ("Price on supply side of VWAP",                ctx["price_below_vwap"] or ctx["structure_short"]),
            ("Rejection candle at zone",                    ctx["has_bear_confirm"]),
            ("Volume confirms rejection",                   ctx["volume_ok"]),
        ]
    elif direction == "Long":
        conditions = [
            (f"Price at demand zone{dem_dist_label}",       at_demand),
            ("Demand zone present (fallback)",               not at_demand and has_demand_struct),
            (dem_label,                                      nearest_demand is not None),
            ("Price on demand side of VWAP",                ctx["price_above_vwap"] or ctx["structure_long"]),
            ("Rejection candle at zone",                    ctx["has_bull_confirm"]),
            ("Volume confirms rejection",                   ctx["volume_ok"]),
        ]
    else:
        conditions = [("Price within 1 ATR of supply or demand zone", False)]
    return {"direction": direction, "conditions": conditions, "target_r": 2.0}


def _score_vwap_reclaim_fail(ctx):
    """Price crosses back through VWAP after trading on the other side.
    Proxy: fresh CHOCH back across VWAP + volume confirms the cross."""
    if ctx["has_choch_demand"] and ctx["price_above_vwap"]:
        direction = "Long"
    elif ctx["has_choch_supply"] and ctx["price_below_vwap"]:
        direction = "Short"
    else:
        direction = None
    if direction == "Long":
        conditions = [
            ("VWAP data available",           ctx["vwap_ok"]),
            ("Bullish CHOCH (reclaim proxy)", ctx["has_choch_demand"]),
            ("Price reclaimed above VWAP",    ctx["price_above_vwap"]),
            ("Volume on reclaim",             ctx["volume_ok"]),
        ]
    elif direction == "Short":
        conditions = [
            ("VWAP data available",        ctx["vwap_ok"]),
            ("Bearish CHOCH (fail proxy)", ctx["has_choch_supply"]),
            ("Price lost VWAP",            ctx["price_below_vwap"]),
            ("Volume on failure",          ctx["volume_ok"]),
        ]
    else:
        conditions = [("CHOCH across VWAP required", False)]
    return {"direction": direction, "conditions": conditions, "target_r": 1.8}


