def _main_brain_judge_neutral(reason, threshold=None):
    """Stable neutral schema for the Main Brain Judge (DISPLAY-ONLY)."""
    thr = threshold if threshold is not None else EDGE_READY_THRESHOLD
    return {
        "available":             False,
        "final_label":           "WAIT",
        "final_reason":          reason,
        "direction":             None,
        "hierarchy":             [],
        "score":                 {"current": 0, "threshold": thr, "max": EDGE_SCORE_MAX,
                                  "points_needed": thr, "components": []},
        "missing_confirmations": [],
        "source_verdict":        None,
        "source_status":         None,
    }


def compute_main_brain_judge(result):
    """The 'Judge' — ONE consolidated, DISPLAY-ONLY verdict view.

    Resolves the already-assembled blocks on `result` into a single explained
    decision: (1) one final label (READY LONG / READY SHORT / WAIT / SKIP /
    MANAGE OPEN TRADE), (2) the evidence hierarchy with each layer's current
    reading, (3) the weighted Edge Score breakdown, and (4) which confirmations are
    still missing and how many points each adds. It ONLY READS `result` (plus the
    read-only cross-market snapshot); it NEVER recomputes a decision and NEVER
    touches the gate, scoring, sizing, dedupe or the money path. The final label
    MIRRORS the bot's authoritative `verdict` + direction + live position, so it can
    never diverge from what the bot actually does. FAIL-OPEN to a neutral schema."""
    try:
        thr = int(cfg("EDGE_READY_THRESHOLD"))
    except Exception:
        thr = EDGE_READY_THRESHOLD
    try:
        market_open = (result.get("market_open") is not False)
        verdict     = result.get("verdict") or ""
        actionable  = is_actionable(verdict)
        tp          = result.get("trade_plan") or {}
        direction   = (result.get("strict_direction") or tp.get("direction")
                       or result.get("dominant_direction"))
        bias        = result.get("bias")
        gd          = result.get("gate_debug") or {}
        mb          = result.get("main_brain") or {}

        # Live / manual position for this instrument → MANAGE (same precedence the
        # Main Brain uses: a user-entered manual trade wins over the bot's own).
        # Resolved BEFORE the closed-market check so an OPEN position is still shown as
        # MANAGE OPEN TRADE while the market is paused — never hidden behind SKIP.
        inst       = instrument_of(result.get("active_ticker"))
        manual_pos = _newest_manual_trade_for(inst) if inst else None
        pos        = manual_pos or (active_trade_for(inst) if inst else None)

        # ── Weighted Edge Score breakdown (THE canonical display computation) ──
        # _analysis_edge_breakdown is the SAME read-only helper that produced
        # result["edge_score"], so the Judge's number always matches the rest of the
        # dashboard. We surface the real scoring components (EDGE_COMPONENTS); zone /
        # FVG / OB / index / room / RR / news / prop deliberately do NOT score, so they
        # are presented as filters in the hierarchy, never as fabricated points. While
        # the market is CLOSED the live tape is paused (result["edge_score"] is 0), so
        # we mirror that exactly: score 0 with every confluence absent.
        if not market_open:
            cur        = 0
            components = [{"key": k, "label": l, "points": p, "present": False}
                         for k, l, p in EDGE_COMPONENTS]
            missing    = [{"label": l, "points": p} for k, l, p in EDGE_COMPONENTS]
        else:
            try:
                eb = _analysis_edge_breakdown(result)
            except Exception:
                eb = {}
            cur = int(eb.get("score") or 0)
            earned_labels = {it.get("label") for it in (eb.get("score_breakdown") or []) if it.get("label")}
            components, missing = [], []
            for key, label, pts in EDGE_COMPONENTS:
                present = label in earned_labels
                components.append({"key": key, "label": label, "points": pts, "present": present})
                if not present:
                    missing.append({"label": label, "points": pts})
        score_blk = {"current": cur, "threshold": thr, "max": EDGE_SCORE_MAX,
                     "points_needed": max(0, thr - cur), "components": components}

        # ── Decision hierarchy: each evidence layer's current reading ──
        hierarchy = []
        if bias == "Bullish":
            hierarchy.append({"layer": "Market structure", "reading": "Bullish", "state": "bullish"})
        elif bias == "Bearish":
            hierarchy.append({"layer": "Market structure", "reading": "Bearish", "state": "bearish"})
        else:
            hierarchy.append({"layer": "Market structure", "reading": "Neutral / unclear", "state": "neutral"})

        cvd_state = result.get("cvd_state")
        cvd_dir   = result.get("cvd_direction")
        if cvd_state == "bullish":
            hierarchy.append({"layer": "Short-term order flow",
                              "reading": "Bullish" + ((" (%s)" % cvd_dir) if cvd_dir else ""),
                              "state": "bullish"})
        elif cvd_state == "bearish":
            hierarchy.append({"layer": "Short-term order flow",
                              "reading": "Bearish" + ((" (%s)" % cvd_dir) if cvd_dir else ""),
                              "state": "bearish"})
        else:
            hierarchy.append({"layer": "Short-term order flow", "reading": "No clear delta", "state": "neutral"})

        adv   = result.get("scalp_strategy_advisory") or {}
        votes = adv.get("votes") or adv.get("strategies") or []
        if votes:
            longs  = sum(1 for v in votes if str(v.get("direction") or v.get("signal") or "").lower().startswith("long"))
            shorts = sum(1 for v in votes if str(v.get("direction") or v.get("signal") or "").lower().startswith("short"))
            st = "bullish" if longs > shorts else "bearish" if shorts > longs else "neutral"
            hierarchy.append({"layer": "Strategy signals",
                              "reading": "%d long / %d short" % (longs, shorts), "state": st})
        else:
            hierarchy.append({"layer": "Strategy signals", "reading": "n/a", "state": "na"})

        risk_bits = []
        if gd.get("volatility_block") is None:
            risk_bits.append("Volatility: unknown"); risk_state = "na"
        elif gd.get("volatility_block"):
            risk_bits.append("Volatility: blocked"); risk_state = "fail"
        else:
            risk_bits.append("Volatility: OK"); risk_state = "pass"
        eq       = result.get("entry_quality") or {}
        eq_grade = eq.get("grade") or eq.get("label")
        if eq_grade:
            risk_bits.append("Location: %s" % eq_grade)
            _eqs = eq.get("score")
            if risk_state == "pass" and isinstance(_eqs, (int, float)) and _eqs < 70:
                risk_state = "warn"
        hierarchy.append({"layer": "Risk filters", "reading": " \u00b7 ".join(risk_bits), "state": risk_state})

        try:
            xm = _cross_market_snapshot() or {}
        except Exception:
            xm = {}
        xstate, xdir = xm.get("state"), xm.get("direction")
        if xstate == "Aligned" and xdir in ("Long", "Short"):
            hierarchy.append({"layer": "Cross-market alignment", "reading": "Aligned %s" % xdir,
                              "state": "bullish" if xdir == "Long" else "bearish"})
        elif xstate:
            hierarchy.append({"layer": "Cross-market alignment", "reading": str(xstate), "state": "neutral"})
        else:
            hierarchy.append({"layer": "Cross-market alignment", "reading": "n/a", "state": "na"})

        # ── Final label: MIRROR the authoritative verdict + live position ──
        # Precedence: an open position (MANAGE) outranks everything; then a closed
        # market (SKIP); then the live READY / SKIP / WAIT verdict.
        if pos:
            label  = "MANAGE OPEN TRADE"
            fdir   = (pos.get("direction") or pos.get("side") if isinstance(pos, dict) else None) or direction
            reason = "A position is open — managing it, not seeking new entries."
        elif not market_open:
            label  = "SKIP"
            fdir   = direction
            reason = "Market closed — no live setups until it reopens."
        elif actionable and direction in ("Long", "Short"):
            label  = "READY LONG" if direction == "Long" else "READY SHORT"
            fdir   = direction
            reason = "Setup is READY: %s confluence at Edge %d/%d." % (direction.lower(), cur, EDGE_SCORE_MAX)
        elif bool(gd.get("volatility_block")):
            label  = "SKIP"
            fdir   = direction
            reason = "Volatility regime blocks new trades right now."
        else:
            label = "WAIT"
            fdir  = direction
            need  = max(0, thr - cur)
            if need > 0 and missing:
                reason = "Building — need +%d Edge (e.g. %s) to reach READY (%d)." % (need, missing[0]["label"], thr)
            else:
                reason = "Waiting for a clean, aligned setup."

        return {
            "available":             True,
            "final_label":           label,
            "final_reason":          reason,
            "direction":             fdir,
            "hierarchy":             hierarchy,
            "score":                 score_blk,
            "missing_confirmations": missing,
            "source_verdict":        verdict,
            "source_status":         mb.get("status"),
        }
    except Exception as exc:
        return _main_brain_judge_neutral("Judge unavailable (%s)." % exc, threshold=thr)


# ══════════════════════════════════════════════════════════════════════════════
# UNIFIED LEARNING BRAIN — observation bus + reconciliation layer
# ══════════════════════════════════════════════════════════════════════════════
# Every specialist engine produces a normalised observation (stance / confidence /
# key_finding / veto / weight).  _mb_reconcile() performs weighted voting,
# detects conflicts, names the active playbook and emits ONE recommendation +
# ONE narrative.  DISPLAY-ONLY; fail-open at every stage; never touches the gate,
# sizing, dedupe or the money path.

def _mb_observe(engine, stance, confidence, key_finding, veto=False, weight=1.0):
    """Normalise any engine output to a standard observation dict."""
    return {
        "engine":      engine,
        "stance":      stance,      # "bullish"|"bearish"|"neutral"|"caution"
        "confidence":  min(100.0, max(0.0, float(confidence or 0))),
        "key_finding": str(key_finding or "")[:200],
        "veto":        bool(veto),
        "weight":      float(weight or 1.0),
    }


def _emit_observation(source, market, mode, observation, direction, confidence, evidence):
    """Structured specialist observation for the Main Brain bus.

    Every specialist engine emits ONE of these per poll; the Main Brain collects them all
    and uses them as the single source of truth for its user-facing synthesis.

    source      — engine name (e.g. 'stalk_mode')
    market      — instrument symbol (e.g. 'MES')
    mode        — TRADING_MODE at emit time (e.g. 'MICRO_SCALP')
    observation — machine-readable state code (e.g. 'high_sweep_detected')
    direction   — 'Long' / 'Short' / None
    confidence  — 0.0..1.0 scalar
    evidence    — list of ≤8 human-readable supporting facts (strings)
    """
    return {
        "source":      str(source),
        "market":      str(market or ""),
        "mode":        str(mode or ""),
        "observation": str(observation),
        "direction":   direction if direction in ("Long", "Short") else None,
        "confidence":  round(min(1.0, max(0.0, float(confidence or 0))), 3),
        "evidence":    [str(e) for e in (evidence or [])][:8],
        "timestamp":   now_utc().isoformat(),
    }


def _mb_collect_observations(result):
    """Read every specialist engine block in *result* and return a normalised
    observation list.  Never recomputes anything; fail-open per engine."""
    obs    = []
    verdict = str(result.get("verdict") or "")
    is_act  = bool(result.get("is_actionable"))
    edge    = float(result.get("edge_score") or 0)
    strict  = str(result.get("strict_reason") or "")
    dirn    = str(result.get("direction") or result.get("dominant_direction") or "")

    # 1. Authoritative gate (weight 2x — ground truth for the reconciler)
    if is_act:
        g_stance = ("bullish" if "LONG" in verdict else
                    "bearish" if "SHORT" in verdict else "neutral")
        g_find   = verdict
    else:
        g_stance = "neutral"
        g_find   = ("WAIT — " + strict) if strict else "WAIT"
    obs.append(_mb_observe("gate", g_stance, min(edge, 100), g_find, weight=2.0))

    # 2. Analyst reasoning engine
    try:
        an = result.get("analyst") or {}
        if an and isinstance(an, dict):
            ep    = an.get("entry_probability") or {}
            prob  = float(ep.get("probability", 50)) if isinstance(ep, dict) else 50.0
            veto  = bool(an.get("veto_would_fire"))
            ph    = an.get("market_phase") or {}
            phase = str(ph.get("phase") if isinstance(ph, dict) else ph or "")
            out   = an.get("analyst_outlook") or {}
            ctrl  = str(out.get("control") if isinstance(out, dict) else out or "")
            lo    = ctrl.lower()
            stance = ("bullish" if ("bullish" in lo or ("long" in lo and "long-term" not in lo))
                      else "bearish" if ("bearish" in lo or "short" in lo)
                      else "caution"  if veto else "neutral")
            obs.append(_mb_observe("analyst", stance, prob,
                                   phase or ctrl[:100], veto=veto, weight=0.8))
    except Exception:
        pass

    # 3. Trade debate engine  (stored as "trade_debate" in full_analysis result)
    try:
        td = result.get("trade_debate") or {}
        if td and isinstance(td, dict):
            fv   = str(td.get("final_verdict") or "WAIT")
            conf = float(td.get("confidence") or 50)
            summ = str(td.get("judge_summary") or td.get("reasoning") or fv)[:120]
            veto = bool(td.get("veto_would_fire") or (fv == "WAIT" and is_act))
            stance = ("bullish" if fv == "TAKE" and "LONG"  in dirn else
                      "bearish" if fv == "TAKE" and "SHORT" in dirn else
                      "caution" if veto else "neutral")
            obs.append(_mb_observe("debate", stance, conf, summ, veto=veto, weight=0.9))
    except Exception:
        pass

    # 4. Professional review
    try:
        pr = result.get("pro_review") or {}
        if pr and isinstance(pr, dict):
            score = float(pr.get("score") or 50)
            grade = str(pr.get("grade") or "C")
            veto  = bool(pr.get("veto_would_fire"))
            summ  = str(pr.get("summary") or pr.get("reasoning") or ("Grade " + grade))[:120]
            stance = ("bullish" if grade in ("A+", "A") and not veto else
                      "neutral" if grade in ("B+", "B") else "caution")
            obs.append(_mb_observe("pro_review", stance, score, summ, veto=veto, weight=0.7))
    except Exception:
        pass

    # 5. Confidence governor  (stored as "confidence_governor" in full_analysis result)
    try:
        gov = result.get("confidence_governor") or {}
        if gov and isinstance(gov, dict):
            allow = gov.get("allow_trade", True)
            adj   = float(gov.get("confidence_adjustment") or 0)
            rsn   = str(gov.get("reasoning") or gov.get("primary_lesson") or "")[:120]
            veto  = bool(gov.get("veto_would_fire") or (not allow and is_act))
            obs.append(_mb_observe("governor",
                                   "neutral" if allow else "caution",
                                   min(100, max(0, 50 + adj)),
                                   rsn or ("Allow: %s" % allow),
                                   veto=veto, weight=0.6))
    except Exception:
        pass

    # 6. Entry quality
    try:
        eq = result.get("entry_quality") or {}
        if eq and isinstance(eq, dict):
            sc    = float(eq.get("score") or 0)
            veto  = bool(eq.get("veto_would_fire"))
            lbl   = str(eq.get("location_label") or eq.get("verdict_label")
                        or eq.get("grade") or ("Score %d" % int(sc)))[:100]
            chase = bool(eq.get("chasing_warning"))
            stance = ("bullish" if sc >= 75 and not veto and not chase else
                      "caution" if veto or chase or sc < 50 else "neutral")
            obs.append(_mb_observe("entry_quality", stance, sc, lbl,
                                   veto=veto, weight=0.7))
    except Exception:
        pass

    # 7. Volatility / regime
    try:
        vol = result.get("volatility") or {}
        if vol and isinstance(vol, dict):
            regime = str(vol.get("regime") or "normal").lower()
            block  = bool(vol.get("blocks_trade") or vol.get("brake_applied")
                          or vol.get("blocked"))
            stance = "neutral" if regime in ("normal", "low", "quiet") else "caution"
            obs.append(_mb_observe("volatility", stance, 50,
                                   "Regime: %s" % regime, veto=block, weight=0.5))
    except Exception:
        pass

    return obs


def _mb_build_structured_observations(result):
    """Collect ONE structured _emit_observation per specialist engine.

    This is the Main Brain's structured observation bus: each specialist emits a
    machine-readable {source, market, mode, observation, direction, confidence,
    evidence, timestamp} dict and the Main Brain is the sole author of all
    user-facing prose. Pure read, FAIL-OPEN per engine, DISPLAY-ONLY."""
    obs   = []
    inst  = result.get("active_ticker") or result.get("instrument") or ""
    mkt   = instrument_of(inst) if inst else ""
    mode  = TRADING_MODE

    # ── 1. Market Intelligence ────────────────────────────────────────────────
    try:
        mi = result.get("market_intelligence") or {}
        if mi and isinstance(mi, dict):
            conf_raw = mi.get("directional_confidence") or {}
            bias     = str(conf_raw.get("bias") or "Neutral")
            dom_l    = float(conf_raw.get("long")  or 0)
            dom_s    = float(conf_raw.get("short") or 0)
            dom_score = dom_l if bias == "Long" else dom_s if bias == "Short" else max(dom_l, dom_s)
            decay    = mi.get("confidence_decay") or {}
            decayed  = float(decay.get("decayed") or dom_score)
            regime   = mi.get("regime") or {}
            rname    = str(regime.get("regime") if isinstance(regime, dict) else regime or "")
            if bias == "Long":
                obs_code = "trending_bullish"
            elif bias == "Short":
                obs_code = "trending_bearish"
            else:
                obs_code = "ranging"
            dirn = "Long" if bias == "Long" else "Short" if bias == "Short" else None
            ev   = []
            if rname:
                ev.append("regime: %s" % rname)
            htf = mi.get("htf") or {}
            if htf.get("aligned_long"):
                ev.append("htf: aligned long")
            elif htf.get("aligned_short"):
                ev.append("htf: aligned short")
            mom = mi.get("momentum") or {}
            if isinstance(mom, dict):
                mst = mom.get("state") or mom.get("direction")
                if mst:
                    ev.append("momentum: %s" % mst)
            obs.append(_emit_observation("market_intelligence", mkt, mode, obs_code, dirn,
                                         decayed / 100.0, ev))
    except Exception:
        pass

    # ── 2. Strategy Engine ────────────────────────────────────────────────────
    try:
        se = result.get("strategy_engine") or {}
        if se and isinstance(se, dict):
            ready = bool(se.get("ready"))
            dirn  = se.get("direction")
            strat = str(se.get("active_strategy") or "None")
            conf  = float(se.get("confidence") or 0)
            if ready and dirn == "Long":
                obs_code = "strategy_ready_long"
            elif ready and dirn == "Short":
                obs_code = "strategy_ready_short"
            elif strat != "None" and dirn:
                obs_code = "strategy_forming"
            else:
                obs_code = "no_strategy"
            ev = [strat]
            for m in (se.get("missing") or [])[:3]:
                ev.append("missing: %s" % m)
            obs.append(_emit_observation("strategy_engine", mkt, mode, obs_code,
                                         dirn if ready else None, conf / 100.0, ev))
    except Exception:
        pass

    # ── 3. Stalk Mode ─────────────────────────────────────────────────────────
    try:
        sm = result.get("stalk_mode") or {}
        if sm and isinstance(sm, dict):
            state = str(sm.get("state") or "idle")
            dirn  = sm.get("direction")
            if state == "stalking" and dirn == "Long":
                obs_code = "stalking_long"
            elif state == "stalking" and dirn == "Short":
                obs_code = "stalking_short"
            elif state == "engine_entering":
                obs_code = "engine_entering"
            elif state == "in_trade":
                obs_code = "in_trade"
            elif state == "market_closed":
                obs_code = "market_closed"
            else:
                obs_code = "idle"
            conf = 0.55 if state in ("stalking", "engine_entering") else 0.25
            ev   = []
            for w in (sm.get("why_waiting") or [])[:2]:
                ev.append(str(w))
            iz = sm.get("ideal_entry_zone")
            if iz is not None:
                try:
                    ev.append("entry_zone: %.2f" % float(iz))
                except (TypeError, ValueError):
                    pass
            obs.append(_emit_observation("stalk_mode", mkt, mode, obs_code, dirn, conf, ev))
    except Exception:
        pass

    # ── 4. Breakout Mode ──────────────────────────────────────────────────────
    try:
        bm = result.get("breakout_mode") or {}
        if bm and isinstance(bm, dict) and bm.get("enabled"):
            entry_status = str(bm.get("entry_status") or "WAIT")
            setup_kind   = str(bm.get("setup_kind")   or "None")
            qs   = float(bm.get("quality_score") or 0)
            if entry_status == "READY LONG":
                obs_code = "breakout_long" if setup_kind == "Breakout" else "sweep_reversal_long"
                dirn     = "Long"
            elif entry_status == "READY SHORT":
                obs_code = "breakout_short" if setup_kind == "Breakout" else "sweep_reversal_short"
                dirn     = "Short"
            elif bm.get("in_build"):
                obs_code = "building_range";  dirn = None
            elif bm.get("active"):
                obs_code = "watching";        dirn = None
            else:
                obs_code = "off";             dirn = None
            ev = [setup_kind]
            for c in (bm.get("confirmations") or [])[:4]:
                if isinstance(c, dict):
                    ev.append("%s: %s" % (c.get("label", ""), "yes" if c.get("met") else "no"))
            obs.append(_emit_observation("breakout_mode", mkt, mode, obs_code, dirn,
                                         qs / 100.0, ev))
    except Exception:
        pass

    # ── 5. Entry Quality ──────────────────────────────────────────────────────
    try:
        eq = result.get("entry_quality") or {}
        if eq and isinstance(eq, dict):
            score = float(eq.get("score") or 0)
            chase = bool(eq.get("chasing_warning"))
            veto  = bool(eq.get("veto_would_fire"))
            if chase:
                obs_code = "chasing"
            elif score >= 75:
                obs_code = "clean_location"
            elif score >= 55:
                obs_code = "good_location"
            else:
                obs_code = "poor_location"
            dirn = result.get("strict_direction")
            ev   = [str(eq.get("location_label") or eq.get("verdict_label")
                        or ("score: %d" % int(score)))]
            if veto:
                ev.append("veto: active")
            obs.append(_emit_observation("entry_quality", mkt, mode, obs_code,
                                         dirn if dirn in ("Long", "Short") else None,
                                         score / 100.0, ev))
    except Exception:
        pass

    # ── 6. Analyst Reasoning ──────────────────────────────────────────────────
    try:
        an = result.get("analyst") or {}
        if an and isinstance(an, dict):
            stronger = an.get("stronger_side") or an.get("final_direction")
            conf     = float(an.get("confidence") or 50)
            veto     = bool(an.get("veto_would_fire"))
            if veto:
                obs_code = "veto_active"
            elif stronger == "Long":
                obs_code = "bullish_thesis"
            elif stronger == "Short":
                obs_code = "bearish_thesis"
            else:
                obs_code = "neutral_thesis"
            dirn = stronger if stronger in ("Long", "Short") else None
            ev   = [str(b) for b in (an.get("bull_case") or [])[:2] if b]
            ph   = an.get("market_phase") or {}
            if isinstance(ph, dict) and ph.get("phase"):
                ev.append("phase: %s" % ph["phase"])
            obs.append(_emit_observation("analyst_reasoning", mkt, mode, obs_code, dirn,
                                         conf / 100.0, ev))
    except Exception:
        pass

    # ── 7. Trade Debate ───────────────────────────────────────────────────────
    try:
        td = result.get("trade_debate") or {}
        if td and isinstance(td, dict):
            judge    = td.get("judge") or {}
            ws       = str(judge.get("winning_side") or "Balanced")
            fv       = str(judge.get("final_verdict") or td.get("final_verdict") or "WAIT")
            too_bal  = bool(judge.get("too_balanced"))
            veto     = bool(td.get("veto_would_fire"))
            gap      = float(judge.get("confidence_gap") or 0)
            if too_bal:
                obs_code = "balanced"
            elif ws == "Bull" and fv == "TAKE":
                obs_code = "decisive_bull"
            elif ws == "Bear" and fv == "TAKE":
                obs_code = "decisive_bear"
            elif veto:
                obs_code = "veto_active"
            else:
                obs_code = "balanced"
            dirn = "Long" if ws == "Bull" else "Short" if ws == "Bear" else None
            ev   = [str(judge.get("reason_winner_won") or ("gap: %d" % int(gap)))]
            obs.append(_emit_observation("trade_debate", mkt, mode, obs_code, dirn,
                                         min(1.0, gap / 100.0), ev))
    except Exception:
        pass

    # ── 8. Professional Review ────────────────────────────────────────────────
    try:
        pr = result.get("pro_review") or {}
        if pr and isinstance(pr, dict):
            active = pr.get("active") or {}
            if isinstance(active, dict):
                grade    = str(active.get("grade") or "—")
                decision = str(active.get("professional_decision") or "WAIT")
                eff      = float(active.get("entry_efficiency") or 0)
                if grade in ("A+", "S"):
                    obs_code = "grade_excellent"
                elif grade == "A":
                    obs_code = "grade_good"
                elif grade == "B":
                    obs_code = "grade_fair"
                else:
                    obs_code = "grade_poor"
                dirn = result.get("strict_direction")
                ev   = ["grade: %s" % grade, "decision: %s" % decision,
                        "efficiency: %d" % int(eff)]
                obs.append(_emit_observation("pro_review", mkt, mode, obs_code,
                                             dirn if dirn in ("Long", "Short") else None,
                                             eff / 100.0, ev))
    except Exception:
        pass

    # ── 9. Confidence Governor ────────────────────────────────────────────────
    try:
        gov = result.get("confidence_governor") or {}
        if gov and isinstance(gov, dict):
            allow      = bool(gov.get("allow_trade", True))
            final_conf = float(gov.get("confidence") or gov.get("confidence_score") or 50)
            veto       = bool(gov.get("veto_would_fire"))
            if not allow or veto:
                obs_code = "confidence_block"
            elif final_conf >= 70:
                obs_code = "confidence_allow"
            else:
                obs_code = "confidence_caution"
            ev = []
            for comp in (gov.get("confidence_components") or [])[:4]:
                if isinstance(comp, dict):
                    ev.append("%s: %d" % (comp.get("label") or comp.get("name") or "?",
                                          int(comp.get("score") or 0)))
            obs.append(_emit_observation("confidence_governor", mkt, mode, obs_code,
                                         None, final_conf / 100.0, ev))
    except Exception:
        pass

    # ── 10. Scalp Quality ─────────────────────────────────────────────────────
    try:
        sq = result.get("scalp_quality") or {}
        if sq and isinstance(sq, dict) and sq.get("enabled"):
            overall = sq.get("overall_pass")
            qscore  = float(sq.get("setup_quality_score") or 0)
            if overall is True:
                obs_code = "scalp_pass"
            elif overall is False:
                obs_code = "scalp_fail"
            else:
                obs_code = "scalp_caution"
            dirn = sq.get("direction")
            ev   = ["quality_score: %d" % int(qscore)]
            ev.extend([str(n) for n in (sq.get("notes") or [])[:2]])
            obs.append(_emit_observation("scalp_quality", mkt, mode, obs_code,
                                         dirn if dirn in ("Long", "Short") else None,
                                         qscore / 100.0, ev))
    except Exception:
        pass

    # ── 11. Liquidity Sweep Focus ─────────────────────────────────────────────
    try:
        lsf = result.get("liquidity_sweep_focus") or {}
        if lsf and isinstance(lsf, dict) and lsf.get("enabled"):
            state = str(lsf.get("state") or "NO SWEEP")
            cdelta = float(lsf.get("confidence_delta") or 0)
            dirn   = lsf.get("sweep_direction")
            state_map = {
                "SWEEP CONFIRMED":             "sweep_confirmed",
                "SWEEP FORMING":               "sweep_forming",
                "SWEEP FAILED":                "sweep_failed",
                "CONTINUATION THROUGH LIQUIDITY": "continuation",
                "NO SWEEP":                    "no_sweep",
            }
            obs_code = state_map.get(state, "no_sweep")
            ev = []
            voice = lsf.get("voice") or lsf.get("trader_read")
            if voice:
                ev.append(str(voice)[:80])
            obs.append(_emit_observation("liquidity_sweep_focus", mkt, mode, obs_code,
                                         dirn if dirn in ("Long", "Short") else None,
                                         max(0.0, min(1.0, 0.5 + cdelta / 100.0)), ev))
    except Exception:
        pass

    return obs


# ─────────────────────────────────────────────────────────────────────────────
# Main Brain SYNTHESIS — structured HUNTING/READY/MANAGING narrative
# ─────────────────────────────────────────────────────────────────────────────
_MB_SYNTHESIS_NOTE = "Main Brain synthesis — display only, not financial advice."


def _mb_synthesis_neutral(reason="Synthesis unavailable."):
    """Stable neutral schema for the synthesis report. Every key must exist here
    so downstream consumers never raise on a missing key."""
    return {
        "available":         False,
        "status_headline":   "WATCHING",
        "instrument":        None,
        "direction":         None,
        "opening_line":      reason,
        "what_happened":     [],
        "what_supports":     [],
        "why_not_entering":  [],
        "what_happens_next": [],
        "what_cancels":      [],
        "learning_memory":   None,
        "decision":          "WAIT",
        "next_action":       "Continue monitoring.",
        "note":              _MB_SYNTHESIS_NOTE,
        "reason":            reason,
    }


def _mb_synthesis_report(result, observations):
    """Produce a structured HUNTING/READY/MANAGING narrative from the specialist
    observation bus and assembled result.  Pure + fail-open (every section
    individually guarded).  DISPLAY-ONLY — never reads the gate or money path."""
    try:
        # Index observations by source for O(1) lookup.
        obs_by_src = {}
        for _o in (observations or []):
            if isinstance(_o, dict) and _o.get("source"):
                obs_by_src[_o["source"]] = _o

        inst       = result.get("active_ticker") or result.get("instrument") or ""
        verdict    = str(result.get("verdict") or "WAIT")
        dirn       = ready_direction(verdict) or result.get("strict_direction")
        mode       = TRADING_MODE
        mode_label = mode.replace("_", " ").title() if mode else "trade"
        an         = result.get("analyst") or {}
        sm         = result.get("stalk_mode") or {}
        lsf        = result.get("liquidity_sweep_focus") or {}
        mem        = result.get("trade_memory") or {}
        pos        = result.get("active_trade") or result.get("managed_trade")

        # ── Status headline ───────────────────────────────────────────────────
        if pos is not None:
            status_headline = "MANAGING"
        elif "READY" in verdict:
            status_headline = "READY"
        elif "BUILDING" in verdict:
            status_headline = "BUILDING"
        elif "INVALIDAT" in verdict.upper():
            status_headline = "INVALIDATED"
        else:
            has_thesis = dirn in ("Long", "Short") and (
                sm.get("state") in ("stalking", "engine_entering") or
                obs_by_src.get("analyst_reasoning", {}).get("observation") in
                    ("bullish_thesis", "bearish_thesis") or
                obs_by_src.get("stalk_mode", {}).get("observation") in
                    ("stalking_long", "stalking_short", "engine_entering")
            )
            status_headline = "HUNTING" if has_thesis else "WATCHING"

        # ── Opening line ──────────────────────────────────────────────────────
        opening_line = "Monitoring %s for a %s opportunity." % (inst, mode_label)
        try:
            dirn_label = dirn if dirn in ("Long", "Short") else None
            if status_headline == "MANAGING":
                side = (pos or {}).get("direction") or dirn_label or ""
                opening_line = "I am managing an open %s %s position." % (mode_label, side)
            elif status_headline == "READY":
                opening_line = "Setup is READY — a %s %s is in play." % (
                    mode_label, (dirn_label or ""))
            elif status_headline == "HUNTING":
                opening_line = "I am watching %s for a %s %s." % (
                    inst, mode_label, (dirn_label or "trade"))
            elif status_headline == "BUILDING":
                opening_line = "A %s setup is building on %s — no entry yet." % (
                    mode_label, inst)
            elif status_headline == "INVALIDATED":
                opening_line = "The prior setup on %s has been invalidated." % inst
        except Exception:
            pass

        # ── What happened ─────────────────────────────────────────────────────
        what_happened = []
        try:
            lsf_code = obs_by_src.get("liquidity_sweep_focus", {}).get("observation", "")
            voice    = lsf.get("voice") or lsf.get("trader_read")
            if lsf_code == "sweep_confirmed" and voice:
                what_happened.append(str(voice))
            elif lsf_code == "sweep_forming":
                what_happened.append("Liquidity sweep forming — watching for confirmation.")
            elif lsf_code == "sweep_failed":
                what_happened.append("Sweep failed — price reclaimed against the expected move.")
            elif lsf_code == "continuation":
                what_happened.append("Price is continuing through liquidity, not reversing.")
            bm_code = obs_by_src.get("breakout_mode", {}).get("observation", "")
            if bm_code in ("breakout_long", "breakout_short"):
                what_happened.append("Opening-range breakout in play.")
            elif bm_code in ("sweep_reversal_long", "sweep_reversal_short"):
                what_happened.append("Opening-range sweep reversal detected.")
            elif bm_code == "building_range":
                what_happened.append("Building the opening range.")
        except Exception:
            pass
        if not what_happened:
            try:
                mi_code = obs_by_src.get("market_intelligence", {}).get("observation", "")
                if mi_code == "trending_bullish":
                    what_happened.append("Market is showing bullish directional bias.")
                elif mi_code == "trending_bearish":
                    what_happened.append("Market is showing bearish directional bias.")
                else:
                    what_happened.append("Market is ranging without a clear directional bias.")
            except Exception:
                what_happened.append("Monitoring market conditions.")

        # ── What supports the idea ────────────────────────────────────────────
        what_supports = []
        try:
            lsf_code = obs_by_src.get("liquidity_sweep_focus", {}).get("observation", "")
            if lsf_code == "sweep_confirmed":
                what_supports.append("Liquidity sweep confirmed.")
                nearby = lsf.get("nearby_liquidity") or {}
                if isinstance(nearby, dict):
                    if nearby.get("side") == "above" and dirn == "Long":
                        what_supports.append("Price is above the reclaimed level.")
                    elif nearby.get("side") == "below" and dirn == "Short":
                        what_supports.append("Price is below the reclaimed level.")
            case_key = ("bear_case" if dirn == "Short" else
                        "bull_case" if dirn == "Long" else None)
            if case_key:
                for line in (an.get(case_key) or [])[:3]:
                    s = str(line).strip()
                    if s and s != "—":
                        what_supports.append(s)
            if mem.get("ready"):
                ar = mem.get("average_r")
                n  = int(mem.get("similar_trades_found") or 0)
                if ar is not None and n >= 5:
                    ar_val = float(ar)
                    sign   = "+" if ar_val >= 0 else ""
                    what_supports.append(
                        "Similar %s %s %ss have %s expectancy (%s%.2fR, %d samples)." % (
                            inst, mode_label, (dirn or "trade"),
                            "positive" if ar_val >= 0 else "negative",
                            sign, ar_val, n))
            cvd_dir = str(result.get("cvd_direction") or result.get("cvd_state") or "").lower()
            if (cvd_dir == "bullish" and dirn == "Long") or \
               (cvd_dir == "bearish" and dirn == "Short"):
                what_supports.append("CVD order flow agrees with the thesis.")
        except Exception:
            pass
        if not what_supports:
            what_supports.append("No strong supporting evidence yet — monitoring.")

        # ── Why not entering ──────────────────────────────────────────────────
        why_not = []
        try:
            if status_headline not in ("MANAGING", "READY"):
                for w in (sm.get("why_waiting") or [])[:3]:
                    s = str(w).strip()
                    if s:
                        why_not.append(s)
                if not why_not:
                    sr = str(result.get("strict_reason") or "")
                    if sr and sr.lower() not in ("none", "wait", ""):
                        for chunk in sr.replace(";", "|").replace(",", "|").split("|"):
                            chunk = chunk.strip()
                            if len(chunk) > 8 and "WAIT" not in chunk.upper():
                                why_not.append(chunk.rstrip(".") + ".")
                            if len(why_not) >= 3:
                                break
                cvd_dir = str(result.get("cvd_direction") or
                              result.get("cvd_state") or "").lower()
                if (cvd_dir == "bearish" and dirn == "Long") or \
                   (cvd_dir == "bullish" and dirn == "Short"):
                    why_not.append("Order flow (CVD) has not turned in the required direction.")
        except Exception:
            pass
        if not why_not and status_headline in ("HUNTING", "WATCHING", "BUILDING"):
            why_not.append("Waiting for all gate conditions to align.")

        # ── What happens next ─────────────────────────────────────────────────
        what_next = []
        try:
            gp       = an.get("game_plan") or {}
            next_opp = gp.get("next_opportunity") or {}
            if isinstance(next_opp, dict):
                for wf in (next_opp.get("waiting_for") or [])[:3]:
                    s = str(wf).strip()
                    if s:
                        what_next.append(s)
                trig = next_opp.get("label") or next_opp.get("trigger")
                if trig and str(trig) not in what_next:
                    what_next.append(str(trig))
            elif isinstance(next_opp, str) and next_opp.strip():
                what_next.append(next_opp.strip())
            if not what_next:
                for w in (sm.get("why_waiting") or [])[:2]:
                    s = str(w).strip()
                    if s and s not in what_next:
                        what_next.append(s)
        except Exception:
            pass
        if not what_next:
            what_next.append("Continue monitoring for a clean setup confirmation.")

        # ── What cancels it ───────────────────────────────────────────────────
        what_cancels = []
        try:
            inv = str(an.get("invalidation") or "")
            if not inv or inv in ("—", "None", ""):
                gp      = an.get("game_plan") or {}
                outlook = an.get("analyst_outlook") or {}
                inv = str(outlook.get("invalidates") or gp.get("invalidation") or "")
            if inv and inv not in ("—", "None", ""):
                what_cancels.append(inv)
            if dirn == "Short":
                sup = result.get("nearest_supply")
                if sup is not None:
                    try:
                        what_cancels.append(
                            "A sustained reclaim above %.2f." % float(sup))
                    except (TypeError, ValueError):
                        pass
            elif dirn == "Long":
                dem = result.get("nearest_demand")
                if dem is not None:
                    try:
                        what_cancels.append(
                            "A sustained break below %.2f." % float(dem))
                    except (TypeError, ValueError):
                        pass
        except Exception:
            pass
        if not what_cancels:
            what_cancels.append("Sustained price action against the setup thesis.")

        # ── Learning memory ───────────────────────────────────────────────────
        learning_memory = None
        try:
            if mem and isinstance(mem, dict) and mem.get("ready"):
                n  = int(mem.get("similar_trades_found") or 0)
                wr = mem.get("similar_win_rate")
                ar = mem.get("average_r")
                cf = mem.get("most_common_failure")
                if n > 0:
                    learning_memory = {
                        "similar_samples":     n,
                        "expectancy_r":        round(float(ar), 2) if ar is not None else None,
                        "win_rate_pct":        (int(round(float(wr) * 100))
                                                if wr is not None else None),
                        "most_common_failure": str(cf) if cf else None,
                        "recommendation":      str(mem.get("memory_recommendation") or ""),
                    }
        except Exception:
            pass

        # ── Decision & next action ────────────────────────────────────────────
        if status_headline == "MANAGING":
            decision = "MANAGE"
        elif status_headline == "READY":
            decision = "TAKE" if dirn in ("Long", "Short") else "READY"
        elif status_headline == "INVALIDATED":
            decision = "STAND ASIDE"
        else:
            decision = "WAIT"

        next_action = "Continue monitoring."
        try:
            if status_headline == "HUNTING":
                next_action = "Continue stalking; do not chase."
            elif status_headline == "READY":
                next_action = "Execute %s %s per trade plan." % (
                    (dirn or ""), mode_label)
            elif status_headline == "MANAGING":
                next_action = "Manage the open position; protect capital first."
            elif status_headline == "BUILDING":
                next_action = "Monitor for breakout or breakdown signal."
            elif status_headline == "INVALIDATED":
                next_action = "Stand aside — thesis invalidated; reset and wait."
        except Exception:
            pass

        return {
            "available":         True,
            "status_headline":   status_headline,
            "instrument":        inst or None,
            "direction":         dirn if dirn in ("Long", "Short") else None,
            "opening_line":      opening_line,
            "what_happened":     [s for s in what_happened  if s][:5],
            "what_supports":     [s for s in what_supports  if s][:6],
            "why_not_entering":  [s for s in why_not        if s][:4],
            "what_happens_next": [s for s in what_next      if s][:4],
            "what_cancels":      [s for s in what_cancels   if s][:3],
            "learning_memory":   learning_memory,
            "decision":          decision,
            "next_action":       next_action,
            "note":              _MB_SYNTHESIS_NOTE,
            "reason":            None,
        }
    except Exception as exc:
        try:
            logger.debug("mb_synthesis_report error (non-fatal): %s", exc)
        except Exception:
            pass
        return _mb_synthesis_neutral("Synthesis error: %s" % exc)


# ─────────────────────────────────────────────────────────────────────────────
# BRAIN CONFLICT RESOLVER — priority-ordered conflict analysis (DISPLAY-ONLY)
#
# Checks 10 priority layers in strict order. Hard vetoes immediately produce a
# BLOCK verdict. Soft disagreements accumulate confidence penalties — they reduce
# confidence or produce WAIT, but never split the conclusion into competing
# alternatives. Pure reads from the assembled result dict; each layer is
# individually guarded so one bad key never cascades. Fail-open throughout.
# ─────────────────────────────────────────────────────────────────────────────

def _bcr_neutral(reason="Conflict resolver unavailable."):
    """Stable neutral schema — used as the fail-open fallback."""
    return {
        "available":          False,
        "verdict":            "ALLOW",
        "hard_vetoes":        [],
        "soft_disagreements": [],
        "confidence_adj":     0.0,
        "priority_trace":     [],
        "reason":             reason,
    }


def compute_brain_conflict_resolver(result):
    """Priority-ordered conflict resolver for the Main Brain (DISPLAY-ONLY).

    Ten priority layers checked in strict order:
      1  Data freshness        — stale VWAP / market data  → hard veto
      2  Market-open status    — closed market             → no-trade (soft WAIT)
      3  Broker / exec health  — live mode unreachable     → hard veto
      4  Risk veto             — kill switch / loss limit  → hard veto
      5  Prop-rule veto        — prop account misconfigured→ hard veto
      6  Open-position state   — invalid position          → hard veto
      7  Learning eligibility  — GHOST_ONLY instrument     → hard veto
      8  Mode-specific rules   — strategy-engine gate      → soft WAIT
      9  Market evidence       — CVD vs structure / LTF vs HTF → soft penalty
     10  Research suggestions  — SCALP vs MICRO_SCALP dir → soft penalty

    Soft disagreements reduce confidence (confidence_adj < 0) or produce WAIT
    when they exceed the 30-pt threshold. They never create competing conclusions.
    Hard vetoes drive a BLOCK; the highest-priority (lowest number) veto wins.

    Never touches gate / sizing / dedupe / money path. Never raises."""
    try:
        hard_vetoes        = []
        soft_disagreements = []
        confidence_penalty = 0.0
        priority_trace     = []

        def _layer(priority, key, passed, veto_type=None, reason="", penalty=0.0):
            """Append one layer to the trace; accumulate vetoes / penalties."""
            entry = {"priority": priority, "layer": key,
                     "passed": bool(passed), "reason": reason}
            if not passed:
                if veto_type == "hard":
                    entry["veto_type"] = "hard"
                    hard_vetoes.append({"priority": priority,
                                        "layer": key, "reason": reason})
                elif veto_type == "soft":
                    entry["veto_type"] = "soft"
                    entry["penalty"]   = penalty
                    soft_disagreements.append({"priority": priority, "layer": key,
                                               "reason": reason, "penalty": penalty})
            priority_trace.append(entry)

        inst = str(result.get("active_ticker") or result.get("instrument") or "")

        # ── Priority 1: Data freshness ─────────────────────────────────────────
        try:
            vwap_status = str(result.get("vwap_status") or "").lower()
            vwap_val    = result.get("vwap_value")
            stale = "stale" in vwap_status or "unavailable" in vwap_status
            if not stale and vwap_val is None:
                stale = True
            md = result.get("market_data") or {}
            if isinstance(md, dict) and md.get("stale"):
                stale = True
            _layer(1, "data_freshness", not stale,
                   veto_type="hard" if stale else None,
                   reason=("Critical data is stale or unavailable — cannot assess setup."
                           if stale else "Data fresh."))
        except Exception:
            _layer(1, "data_freshness", True, reason="Freshness check skipped (non-fatal).")

        # ── Priority 2: Market-open status ────────────────────────────────────
        try:
            mkt_open = bool(result.get("market_open", True))
            _layer(2, "market_open", mkt_open,
                   reason=("Market is closed — no new entries." if not mkt_open
                           else "Market is open."))
        except Exception:
            _layer(2, "market_open", True, reason="Market status check skipped.")

        # ── Priority 3: Broker and execution health ───────────────────────────
        try:
            exec_mode    = str(result.get("execution_mode") or "").lower()
            exec_enabled = result.get("execution_enabled", True)
            exec_live    = result.get("execution_live", True)
            live_modes   = ("traderspost", "pickmytrade")
            broker_ok    = True
            broker_reason = "Execution healthy (%s)." % (exec_mode or "manual_only")
            if exec_mode in live_modes and exec_enabled and not exec_live:
                broker_ok     = False
                broker_reason = ("Broker mode is '%s' but live execution is not "
                                 "reachable — no orders can be sent." % exec_mode)
            _layer(3, "broker_health", broker_ok,
                   veto_type="hard" if not broker_ok else None,
                   reason=broker_reason)
        except Exception:
            _layer(3, "broker_health", True, reason="Broker health check skipped.")

        # ── Priority 4: Risk veto ─────────────────────────────────────────────
        try:
            risk_block  = False
            risk_reason = "Risk within limits."
            try:
                sc = get_safety_cfg(inst)
                if isinstance(sc, dict) and sc.get("kill_switch"):
                    risk_block  = True
                    risk_reason = "Kill switch is active — all execution halted."
            except Exception:
                pass
            if not risk_block:
                l_ok = result.get("longs_allowed", True)
                s_ok = result.get("shorts_allowed", True)
                if l_ok is False and s_ok is False:
                    risk_block  = True
                    risk_reason = ("Both directions are blocked — daily risk limit "
                                   "likely reached.")
            _layer(4, "risk_veto", not risk_block,
                   veto_type="hard" if risk_block else None,
                   reason=risk_reason)
        except Exception:
            _layer(4, "risk_veto", True, reason="Risk check skipped.")

        # ── Priority 5: Prop-rule veto ────────────────────────────────────────
        try:
            prop         = result.get("prop_firm") or {}
            prop_enabled = isinstance(prop, dict) and bool(prop.get("enabled"))
            prop_blocked = False
            prop_reason  = ("Prop rules satisfied (protection %s)."
                            % ("active" if prop_enabled else "off"))
            if prop_enabled:
                aid   = prop.get("active_id")
                accts = prop.get("accounts") or []
                if aid and accts:
                    active = next((a for a in accts if a.get("id") == aid), None)
                    if active is None:
                        prop_blocked = True
                        prop_reason  = ("Prop active account '%s' not found in "
                                        "account list." % aid)
            _layer(5, "prop_veto", not prop_blocked,
                   veto_type="hard" if prop_blocked else None,
                   reason=prop_reason)
        except Exception:
            _layer(5, "prop_veto", True, reason="Prop check skipped.")

        # ── Priority 6: Open-position management ──────────────────────────────
        try:
            pos        = result.get("active_trade") or result.get("managed_trade")
            pos_bad    = False
            pos_reason = "No open position conflicts."
            if isinstance(pos, dict):
                ps = str(pos.get("status") or "open").lower()
                if ps in ("error", "invalid", "orphaned"):
                    pos_bad    = True
                    pos_reason = ("Open position is in an invalid state (%s) — "
                                  "manual review required." % ps)
                else:
                    pos_reason = "Open position tracked normally (status: %s)." % ps
            _layer(6, "position_state", not pos_bad,
                   veto_type="hard" if pos_bad else None,
                   reason=pos_reason)
        except Exception:
            _layer(6, "position_state", True, reason="Position state check skipped.")

        # ── Priority 7: Learning eligibility ──────────────────────────────────
        try:
            lre        = result.get("learning_rule_engine") or {}
            ghost_only = False
            lre_reason = "Learning rule engine not active — no eligibility constraint."
            if isinstance(lre, dict) and lre.get("enabled"):
                instruments_map = lre.get("instruments") or {}
                inst_data       = instruments_map.get(inst) or {}
                inst_status     = inst_data.get("status", "GHOST_ONLY")
                disabled        = inst_data.get("disabled_setups") or []
                rule_triggered  = str(inst_data.get("rule_triggered") or "")
                if inst_status == "GHOST_ONLY":
                    ghost_only = True
                    lre_reason = ("Setup historically disabled for live execution "
                                  "on %s: %s." % (
                                      inst or "this instrument",
                                      rule_triggered or "insufficient sample size"))
                elif disabled:
                    ghost_only = True
                    lre_reason = ("Some setups disabled on %s: %s." % (
                        inst, ", ".join(str(d) for d in disabled[:3])))
                else:
                    lre_reason = ("Learning rule engine: %s is LIVE_ELIGIBLE." % inst)
            _layer(7, "learning_eligibility", not ghost_only,
                   veto_type="hard" if ghost_only else None,
                   reason=lre_reason)
        except Exception:
            _layer(7, "learning_eligibility", True,
                   reason="Learning eligibility check skipped.")

        # ── Priority 8: Mode-specific setup rules ─────────────────────────────
        # Not a hard veto — an incomplete mode setup produces WAIT, not BLOCK.
        try:
            se          = result.get("strategy_engine") or {}
            mode_ok     = True
            mode_reason = "Mode-specific setup rules satisfied."
            if isinstance(se, dict) and se.get("enabled") and se.get("ready") is False:
                missing = [str(m) for m in (se.get("missing") or [])[:3] if m]
                if missing:
                    mode_ok     = False
                    mode_reason = "Mode gate not met: %s." % "; ".join(missing)
                else:
                    mode_ok     = False
                    mode_reason = "Mode-specific setup requirements not met."
            _layer(8, "mode_setup_rules", mode_ok,
                   reason=mode_reason)
        except Exception:
            _layer(8, "mode_setup_rules", True, reason="Mode rules check skipped.")

        # ── Priority 9: Market evidence (soft disagreements) ──────────────────
        try:
            cvd_dir  = str(result.get("cvd_direction") or
                           result.get("cvd_state") or "").lower()
            strict_d = str(result.get("strict_direction") or "").lower()

            # 9a. CVD vs structure conflict
            cvd_norm = ("long"  if "bull" in cvd_dir else
                        "short" if "bear" in cvd_dir else None)
            if cvd_norm and strict_d in ("long", "short"):
                if cvd_norm != strict_d:
                    _layer(9, "cvd_vs_structure", False, veto_type="soft",
                           reason=("CVD is %s but structure favors %s — "
                                   "order flow / structure conflict." % (
                                       cvd_dir, strict_d)),
                           penalty=15.0)
                else:
                    _layer(9, "cvd_vs_structure", True,
                           reason="CVD and structure agree (%s)." % strict_d)
            else:
                _layer(9, "cvd_vs_structure", True,
                       reason="CVD alignment check skipped (insufficient data).")

            # 9b. LTF vs HTF directional conflict (via analyst context)
            htf_ctx  = ((result.get("analyst") or {}).get("context") or {})
            htf_bias = str(htf_ctx.get("htf_bias") or "").lower()
            htf_norm = ("long"  if "bull" in htf_bias else
                        "short" if "bear" in htf_bias else None)
            if htf_norm and strict_d in ("long", "short") and htf_norm != strict_d:
                _layer(9, "ltf_vs_htf", False, veto_type="soft",
                       reason=("Setup is %s but higher-timeframe bias is %s — "
                               "fighting the trend." % (strict_d, htf_bias)),
                       penalty=20.0)
            else:
                _layer(9, "ltf_vs_htf", True,
                       reason="LTF/HTF alignment: %s / %s." % (
                           strict_d or "none", htf_norm or "none"))
        except Exception:
            _layer(9, "market_evidence", True, reason="Market evidence check skipped.")

        # ── Priority 10: Research suggestions (soft) ──────────────────────────
        try:
            if TRADING_MODE == "MICRO_SCALP":
                ms_dirn = strict_d if "strict_d" in dir() else str(
                    result.get("strict_direction") or "").lower()
                dual    = result.get("dual_tf") or {}
                sc_bias = str(
                    dual.get("bias") or dual.get("scalp_direction") or "").lower()
                if (ms_dirn and sc_bias and
                        ms_dirn != sc_bias and
                        sc_bias not in ("", "neutral", "none")):
                    _layer(10, "scalp_vs_micro_conflict", False, veto_type="soft",
                           reason=("Micro Scalp prefers %s but broader Scalp "
                                   "framework leans %s." % (ms_dirn, sc_bias)),
                           penalty=10.0)
                else:
                    _layer(10, "scalp_vs_micro_conflict", True,
                           reason="Scalp and Micro Scalp directional agreement "
                                  "(%s)." % (ms_dirn or "undetermined"))
            else:
                _layer(10, "research_suggestions", True,
                       reason="Research layer: no cross-mode conflict in "
                              "%s mode." % TRADING_MODE)
        except Exception:
            _layer(10, "research_suggestions", True,
                   reason="Research suggestions check skipped.")

        # ── Final verdict ──────────────────────────────────────────────────────
        # Hard vetoes: the highest-priority (lowest priority number) hard veto wins.
        # Soft disagreements: accumulated penalty → WAIT at >= 30 pts, else ALLOW
        # with confidence_adj reflecting the total reduction.
        if hard_vetoes:
            top       = min(hard_vetoes, key=lambda v: v["priority"])
            verdict   = "BLOCK"
            final_rsn = ("Hard veto at priority %d [%s]: %s" % (
                top["priority"], top["layer"], top["reason"]))
        elif soft_disagreements:
            total_penalty      = sum(d.get("penalty", 0.0)
                                     for d in soft_disagreements)
            confidence_penalty = round(total_penalty, 1)
            mkt_open           = bool(result.get("market_open", True))
            if confidence_penalty >= 30.0 or not mkt_open:
                verdict   = "WAIT"
                final_rsn = ("Soft disagreements exceed confidence threshold "
                             "(%.0f pts penalty) — WAIT for alignment."
                             % total_penalty)
            else:
                verdict   = "ALLOW"
                final_rsn = ("Soft disagreements noted; confidence reduced by "
                             "%.0f pts — proceed with caution." % total_penalty)
        else:
            confidence_penalty = 0.0
            verdict   = "ALLOW"
            final_rsn = "All priority layers passed — no conflicts detected."

        return {
            "available":          True,
            "verdict":            verdict,
            "hard_vetoes":        hard_vetoes,
            "soft_disagreements": soft_disagreements,
            "confidence_adj":     -round(confidence_penalty, 1),
            "priority_trace":     priority_trace,
            "reason":             final_rsn,
        }
    except Exception as exc:
        try:
            logger.debug("brain_conflict_resolver error (non-fatal): %s", exc)
        except Exception:
            pass
        return _bcr_neutral("Conflict resolver error: %s" % exc)


# ─────────────────────────────────────────────────────────────────────────────
# VERDICT BOARD — every important fact in one of four plain-English buckets
#
# The operator should never need to combine two panels to understand the
# decision. compute_verdict_board() reads observations from the structured bus,
# hard vetoes from the conflict resolver, gate signals from result, and
# expresses every measurement as one of:
#   supports  — evidence for the trade
#   opposes   — evidence against the trade
#   missing   — condition not yet present
#   vetoes    — hard block (entry cannot happen regardless of signals)
#
# Every item is a single plain-English sentence. DISPLAY-ONLY; fail-open per
# section; never touches gate / sizing / dedupe / money path.
# ─────────────────────────────────────────────────────────────────────────────

def _vb_neutral(reason="Verdict board unavailable."):
    """Stable neutral schema — fail-open fallback."""
    return {
        "available":  False,
        "supports":   [],
        "opposes":    [],
        "missing":    [],
        "vetoes":     [],
        "direction":  None,
        "summary":    reason,
        "reason":     reason,
    }


def compute_verdict_board(result, observations=None, conflict_resolver=None):
    """Classify every important measurement into one of four plain-English buckets.

    Supports   — evidence that favors entering this trade right now.
    Opposes    — evidence working against this trade.
    Missing    — conditions not yet present that would tip the balance.
    Vetoes     — hard blocks; entry cannot happen regardless of other signals.

    The direction of the current setup (long / short) is used to classify
    directional signals — e.g. a bullish CVD supports a long and opposes a
    short. When direction is unknown every directional signal becomes Missing.

    DISPLAY-ONLY; fail-open per section; never touches money path. Never raises.
    """
    try:
        supports  = []
        opposes   = []
        missing   = []
        vetoes    = []

        direction = str(result.get("strict_direction") or "").lower()
        is_long   = (direction == "long")
        is_short  = (direction == "short")
        dir_known = (direction in ("long", "short"))

        def _dir(long_favored, long_text, short_text, neutral_text=None):
            """Classify one directional measurement into the right bucket."""
            if not dir_known:
                missing.append(neutral_text or long_text)
                return
            if long_favored:
                (supports if is_long  else opposes).append(
                    long_text  if is_long  else short_text)
            else:
                (supports if is_short else opposes).append(
                    short_text if is_short else long_text)

        # ── Section 1: Hard vetoes from the conflict resolver ─────────────────
        try:
            cr = conflict_resolver or {}
            for hv in (cr.get("hard_vetoes") or []):
                r = str(hv.get("reason") or "A hard condition blocks this setup.")
                vetoes.append(r)
        except Exception:
            pass

        # ── Section 2: Edge score (the single most important gate number) ─────
        try:
            edge     = float(result.get("edge_score") or 0)
            thr      = float(EDGE_READY_THRESHOLD)
            edge_max = float(EDGE_SCORE_MAX)
            needed   = max(0, int(thr - edge))
            if edge >= thr:
                supports.append(
                    "Edge score is %d/%d — the entry threshold of %d has been cleared."
                    % (int(edge), int(edge_max), int(thr)))
            elif edge >= thr * 0.65:
                missing.append(
                    "Edge score is %d/%d — %d more points needed to reach the entry "
                    "threshold of %d."
                    % (int(edge), int(edge_max), needed, int(thr)))
            else:
                opposes.append(
                    "Edge score is %d/%d — well below the %d-point threshold. Multiple "
                    "confirmations are absent."
                    % (int(edge), int(edge_max), int(thr)))
        except Exception:
            pass

        # ── Section 3: Classify specialist observations ───────────────────────
        # Each observation emits one sentence into exactly one bucket.
        try:
            for obs in (observations or []):
                code = str(obs.get("observation") or "").lower()
                src  = str(obs.get("source")      or "")

                # ── market_intelligence ───────────────────────────────────────
                if src == "market_intelligence":
                    if code == "trending_bullish":
                        _dir(True,
                             "Market regime is bullish — aligns with the long setup.",
                             "Market regime is bullish — works against the short.")
                    elif code == "trending_bearish":
                        _dir(False,
                             "Market regime is bearish — works against the long.",
                             "Market regime is bearish — aligns with the short setup.")
                    elif code == "ranging":
                        missing.append(
                            "Market is ranging without a clear trend — directional "
                            "bias is not yet established.")

                # ── strategy_engine ───────────────────────────────────────────
                elif src == "strategy_engine":
                    if code == "strategy_ready_long":
                        _dir(True,
                             "Strategy engine has a complete long setup ready.",
                             "Strategy engine is set up long — conflicts with the "
                             "current short.")
                    elif code == "strategy_ready_short":
                        _dir(False,
                             "Strategy engine is set up short — conflicts with the "
                             "current long.",
                             "Strategy engine has a complete short setup ready.")
                    elif code == "strategy_forming":
                        missing.append(
                            "A strategy pattern is forming but has not yet completed "
                            "all its conditions.")
                    elif code == "no_strategy":
                        missing.append(
                            "No active strategy pattern detected at current price.")

                # ── stalk_mode ────────────────────────────────────────────────
                elif src == "stalk_mode":
                    if code == "stalking_long":
                        _dir(True,
                             "System is actively stalking for a long entry.",
                             "System is stalking long — opposite to the current "
                             "short bias.")
                    elif code == "stalking_short":
                        _dir(False,
                             "System is stalking short — opposite to the current "
                             "long bias.",
                             "System is actively stalking for a short entry.")
                    elif code == "engine_entering":
                        supports.append(
                            "Entry trigger just fired — the system is entering now.")
                    elif code == "idle":
                        missing.append(
                            "System is idle — no setup is actively being stalked.")
                    # in_trade / market_closed handled by other sections

                # ── breakout_mode ─────────────────────────────────────────────
                elif src == "breakout_mode":
                    if code == "breakout_long":
                        _dir(True,
                             "Opening-range breakout signal is long.",
                             "Opening-range breakout is long — conflicts with the "
                             "short.")
                    elif code == "sweep_reversal_long":
                        _dir(True,
                             "Sweep-reversal breakout signal is long.",
                             "Sweep-reversal is long — conflicts with the short.")
                    elif code == "breakout_short":
                        _dir(False,
                             "Opening-range breakout is short — conflicts with the "
                             "long.",
                             "Opening-range breakout signal is short.")
                    elif code == "sweep_reversal_short":
                        _dir(False,
                             "Sweep-reversal is short — conflicts with the long.",
                             "Sweep-reversal breakout signal is short.")
                    elif code == "building_range":
                        missing.append(
                            "Opening range is still building — no breakout signal "
                            "has printed yet.")
                    # watching / off: not surfaced (breakout mode passive)

                # ── entry_quality ─────────────────────────────────────────────
                elif src == "entry_quality":
                    if code == "clean_location":
                        supports.append(
                            "Entry location is ideal — price is at a key level with "
                            "strong risk/reward.")
                    elif code == "good_location":
                        supports.append(
                            "Entry location is good — price has a solid setup point.")
                    elif code == "poor_location":
                        opposes.append(
                            "Entry location is poor — price is in the middle of "
                            "range with limited reward potential.")
                    elif code == "chasing":
                        opposes.append(
                            "Entry would be chasing — price has already extended "
                            "significantly from the ideal entry point.")

                # ── analyst_reasoning ─────────────────────────────────────────
                elif src == "analyst_reasoning":
                    if code == "bullish_thesis":
                        _dir(True,
                             "Analyst reasoning confirms a bullish thesis.",
                             "Analyst sees a bullish thesis — conflicts with the "
                             "short.")
                    elif code == "bearish_thesis":
                        _dir(False,
                             "Analyst sees a bearish thesis — conflicts with the "
                             "long.",
                             "Analyst reasoning confirms a bearish thesis.")
                    elif code == "neutral_thesis":
                        missing.append(
                            "Analyst sees no clear directional edge — thesis is "
                            "neutral.")
                    elif code == "veto_active":
                        opposes.append(
                            "Analyst reasoning has rejected this setup.")

                # ── trade_debate ──────────────────────────────────────────────
                elif src == "trade_debate":
                    if code == "decisive_bull":
                        _dir(True,
                             "Bull vs. Bear debate: bulls have the decisive edge.",
                             "Bull vs. Bear debate leans bullish — conflicts with "
                             "the short.")
                    elif code == "decisive_bear":
                        _dir(False,
                             "Bull vs. Bear debate leans bearish — conflicts with "
                             "the long.",
                             "Bull vs. Bear debate: bears have the decisive edge.")
                    elif code == "balanced":
                        missing.append(
                            "Bull vs. Bear debate is balanced — no clear winner yet.")
                    elif code == "veto_active":
                        opposes.append(
                            "The trade debate judge has vetoed this setup.")

                # ── pro_review ────────────────────────────────────────────────
                elif src == "pro_review":
                    if code == "grade_excellent":
                        supports.append(
                            "Professional review: A+ — this is a high-quality setup.")
                    elif code == "grade_good":
                        supports.append(
                            "Professional review: A — setup meets professional "
                            "entry criteria.")
                    elif code == "grade_fair":
                        missing.append(
                            "Professional review: B — setup is marginal and not yet "
                            "a high-conviction entry.")
                    elif code == "grade_poor":
                        opposes.append(
                            "Professional review: failing grade — this setup does "
                            "not meet the entry standard.")

                # ── confidence_governor ───────────────────────────────────────
                elif src == "confidence_governor":
                    if code == "confidence_allow":
                        supports.append(
                            "Historical pattern: similar setups have performed well "
                            "— confidence is high.")
                    elif code == "confidence_caution":
                        opposes.append(
                            "Historical pattern: similar setups have needed caution "
                            "— the edge here is marginal.")
                    elif code == "confidence_block":
                        vetoes.append(
                            "Confidence governor is blocking this setup — the "
                            "historical edge for this setup type is too poor to "
                            "enter.")

                # ── scalp_quality ─────────────────────────────────────────────
                elif src == "scalp_quality":
                    if code == "scalp_pass":
                        supports.append(
                            "Scalp quality check passed — intraday conditions meet "
                            "the quality bar.")
                    elif code == "scalp_caution":
                        missing.append(
                            "Scalp quality is borderline — one or more intraday "
                            "filters are not fully met.")
                    elif code == "scalp_fail":
                        opposes.append(
                            "Scalp quality check failed — intraday conditions do "
                            "not support a clean entry right now.")

                # ── liquidity_sweep_focus ─────────────────────────────────────
                elif src == "liquidity_sweep_focus":
                    if code == "sweep_confirmed":
                        supports.append(
                            "Liquidity sweep confirmed — trapped traders are fueling "
                            "the move.")
                    elif code == "sweep_forming":
                        supports.append(
                            "Liquidity sweep is forming — a potential reversal is "
                            "building as stops are hunted.")
                    elif code == "sweep_failed":
                        opposes.append(
                            "Liquidity sweep failed — institutional order flow did "
                            "not follow through.")
                    elif code == "continuation":
                        supports.append(
                            "Price is continuing through liquidity — momentum is "
                            "genuine, not a fake-out.")
                    elif code == "no_sweep":
                        missing.append(
                            "No liquidity sweep detected — the move lacks the "
                            "stop-hunt catalyst typically seen before a strong move.")
        except Exception:
            pass

        # ── Section 4: Soft disagreements from conflict resolver → Opposes ────
        try:
            cr = conflict_resolver or {}
            for sd in (cr.get("soft_disagreements") or []):
                r = str(sd.get("reason") or "")
                if r:
                    opposes.append(r)
        except Exception:
            pass

        # ── Section 5: Gate waiting reason → Missing ──────────────────────────
        try:
            verdict  = str(result.get("verdict") or "")
            strict_r = str(result.get("strict_reason") or "")
            if "READY" not in verdict.upper() and strict_r:
                missing.append("Gate is waiting: %s" % strict_r)
        except Exception:
            pass

        # ── Section 6: Market closed informational ────────────────────────────
        try:
            if result.get("market_open") is False:
                already = any("closed" in v.lower() or "market" in v.lower()
                              for v in vetoes)
                if not already:
                    missing.append(
                        "Market is currently closed — signals will resume at "
                        "the next open.")
        except Exception:
            pass

        # ── Summary sentence ──────────────────────────────────────────────────
        try:
            nv = len(vetoes)
            ns = len(supports)
            no = len(opposes)
            nm = len(missing)
            if nv:
                summary = ("%d hard veto%s block%s this trade."
                           % (nv, "s" if nv > 1 else "",
                              "" if nv > 1 else "s"))
            elif ns == 0 and no == 0:
                summary = ("%d condition%s still missing — gathering signals."
                           % (nm, "s" if nm != 1 else ""))
            elif no > ns:
                summary = ("%d signal%s oppose this trade vs. %d in support."
                           % (no, "s" if no != 1 else "", ns))
            elif ns > 0 and no == 0 and nm == 0:
                summary = ("All %d signal%s support this trade — no opposition."
                           % (ns, "s" if ns != 1 else ""))
            elif ns > 0 and no > 0:
                summary = ("%d signal%s support, %d oppose, %d missing."
                           % (ns, "s" if ns != 1 else "", no, nm))
            else:
                summary = ("%d supporting, %d opposing, %d missing."
                           % (ns, no, nm))
        except Exception:
            summary = "Verdict board computed."

        return {
            "available":  True,
            "supports":   supports,
            "opposes":    opposes,
            "missing":    missing,
            "vetoes":     vetoes,
            "direction":  direction or None,
            "summary":    summary,
            "reason":     "ok",
        }
    except Exception as exc:
        try:
            logger.debug("verdict_board error (non-fatal): %s", exc)
        except Exception:
            pass
        return _vb_neutral("Verdict board error: %s" % exc)


def _mb_reconcile(observations, result):
    """Weighted vote across all engine observations -> ONE recommendation + ONE narrative.
    Stored at result['main_brain']['unified']. DISPLAY-ONLY; fail-open."""
    try:
        if not observations:
            return {"available": False, "recommendation": "WAIT", "confidence": 0,
                    "narrative": "No engine observations.", "conflicts": [],
                    "playbook": None, "supporting_engines": [], "opposing_engines": [],
                    "engine_count": 0, "veto_count": 0}

        verdict  = str(result.get("verdict") or "")
        is_act   = bool(result.get("is_actionable"))
        dirn     = str(result.get("direction") or result.get("dominant_direction") or "")
        edge     = float(result.get("edge_score") or 0)
        ticker   = str(result.get("active_ticker") or result.get("ticker") or "")
        strict_r = str(result.get("strict_reason") or "")

        vetoes     = [o for o in observations if o["veto"]]
        supporters = [o for o in observations if not o["veto"]]
        non_gate   = [o for o in observations if o["engine"] != "gate"]

        def _ws(stance):
            return sum(o["weight"] * o["confidence"] / 100.0
                       for o in supporters if o["stance"] == stance)

        bull_w = _ws("bullish")
        bear_w = _ws("bearish")

        # Conflict detection
        conflicts  = []
        ng_stances = set(o["stance"] for o in non_gate if o["stance"] != "neutral")
        if "bullish" in ng_stances and "bearish" in ng_stances:
            conflicts.append("Direction disagreement between advisory engines")
        if vetoes:
            conflicts.append("%d veto(s): %s"
                             % (len(vetoes), ", ".join(o["engine"] for o in vetoes)))
        if is_act and len([o for o in non_gate if o["veto"]]) >= 2:
            gate_dir = ("bullish" if "LONG" in dirn else "bearish" if "SHORT" in dirn else None)
            if gate_dir:
                conflicts.append("Gate %s but advisors block" % gate_dir)

        # Recommendation
        if vetoes:
            recommendation = "WAIT"
            confidence     = max(10, 40 - len(vetoes) * 8)
            why = "Blocked by %s" % ", ".join(o["engine"] for o in vetoes[:2])
        elif is_act and not conflicts:
            recommendation = "TAKE"
            confidence     = min(95, int(edge * 0.55 + (bull_w + bear_w) * 22))
            n_sup = len([o for o in non_gate if o["stance"] in ("bullish", "bearish")])
            why = ("All %d advisory engine(s) aligned" % n_sup) if n_sup else "Gate signal met"
        elif is_act and conflicts:
            recommendation = "CAUTION"
            confidence     = max(20, int(edge * 0.35))
            why = "; ".join(conflicts[:2])
        else:
            recommendation = "WAIT"
            confidence     = max(10, int(edge * 0.25))
            why = strict_r or "Gate conditions not met"

        # Active playbook — read from strategy_engine (display-only)
        playbook = None
        try:
            se = result.get("strategy_engine") or {}
            if isinstance(se, dict):
                playbook = se.get("active_strategy") or se.get("strategy")
            if not playbook:
                le = result.get("learning_engine") or {}
                if isinstance(le, dict):
                    playbook = (le.get("selected_playbook") or
                                le.get("recommended_strategy") or
                                le.get("best_strategy"))
        except Exception:
            pass

        # One narrative
        sym = ticker.replace("1!", "") if ticker else "this instrument"
        n   = len(observations)
        if recommendation == "TAKE":
            narrative = ("%d engines consulted \u2014 aligned on %s %s. %s."
                         % (n, dirn.lower() or "the", sym, why))
        elif recommendation == "CAUTION":
            narrative = ("%d engines consulted \u2014 gate signals %s but conflicts detected. %s."
                         % (n, dirn.lower() or "a setup", why))
        elif vetoes:
            narrative = ("%d engines consulted \u2014 %d veto(s): %s."
                         % (n, len(vetoes), why))
        else:
            narrative = ("%d engines consulted \u2014 standing aside. %s."
                         % (n, why))

        return {
            "available":          True,
            "recommendation":     recommendation,
            "confidence":         confidence,
            "narrative":          narrative,
            "conflicts":          conflicts,
            "why":                why,
            "playbook":           playbook,
            "supporting_engines": [o["engine"] for o in supporters
                                   if o["stance"] in ("bullish", "bearish")
                                   and o["engine"] != "gate"],
            "opposing_engines":   [o["engine"] for o in vetoes],
            "all_observations":   [{"engine": o["engine"], "stance": o["stance"],
                                    "veto": o["veto"], "finding": o["key_finding"][:80]}
                                   for o in observations],
            "engine_count":       len(observations),
            "veto_count":         len(vetoes),
            "bull_weight":        round(bull_w, 2),
            "bear_weight":        round(bear_w, 2),
        }
    except Exception:
        return {"available": False, "recommendation": "WAIT", "confidence": 0,
                "narrative": "Reconciliation unavailable.", "conflicts": [],
                "playbook": None, "supporting_engines": [], "opposing_engines": [],
                "engine_count": 0, "veto_count": 0}


# ─────────────────────────────────────────────────────────────────────────────
# SHARED LEARNING MEMORY — one source of truth for all historical signals
#
# Every consumer inside compute_main_brain reads from _mb_learning_snapshot();
# none of them access trade_memory / confidence_governor / learning_rule_engine
# / learning_engine independently. This prevents the four learning blocks from
# being read in different ways by different parts of the Main Brain.
# ─────────────────────────────────────────────────────────────────────────────

def _mb_learning_snapshot_neutral():
    """Stable neutral schema for the shared learning memory."""
    return {
        "available":           False,
        "similar_samples":     0,
        "avg_r":               None,
        "win_rate_pct":        None,
        "most_common_failure": None,
        "recommendation":      None,
        "confidence":          None,
        "allow":               True,
        "governor_veto":       False,
        "eligibility":         "UNKNOWN",
        "disabled_setups":     [],
        "le_today":            None,
        "note":                None,
    }


def _mb_learning_snapshot(result):
    """Single source of truth for all historical learning signals.

    Reads trade_memory, confidence_governor, learning_rule_engine, and
    learning_engine exactly ONCE and folds them into ONE block. Every Main
    Brain consumer reads from here; none of them access the source blocks
    directly. DISPLAY-ONLY; fail-open; never raises."""
    try:
        inst = str(result.get("active_ticker") or result.get("instrument") or "")

        # ── Trade memory (historical pattern performance) ─────────────────────
        tm      = result.get("trade_memory") or {}
        similar = int(tm.get("similar_samples") or tm.get("similar_count") or 0)
        avg_r   = _mb_num(tm.get("expectancy_r"))
        wr_pct  = _mb_num(tm.get("win_rate_pct"))
        failure = str(tm.get("most_common_failure") or "") or None
        mem_rec = str(tm.get("recommendation") or "") or None

        # ── Confidence governor (historical win-rate driven confidence) ────────
        gov      = result.get("confidence_governor") or {}
        allow    = bool(gov.get("allow_trade", True))
        gov_conf = _mb_num(gov.get("confidence") or gov.get("confidence_score"))
        gov_veto = bool(gov.get("veto_would_fire"))

        # ── Learning rule engine (live-eligibility per instrument) ─────────────
        lre             = result.get("learning_rule_engine") or {}
        lre_enabled     = bool(lre.get("enabled"))
        instruments_map = lre.get("instruments") or {}
        inst_data       = (instruments_map.get(inst) or {}) if lre_enabled else {}
        eligibility     = inst_data.get("status", "UNKNOWN")
        disabled_setups = inst_data.get("disabled_setups") or []
        rule_triggered  = str(inst_data.get("rule_triggered") or "") or None

        # ── Learning engine (today's session stats; optional) ─────────────────
        le       = result.get("learning_engine") or {}
        le_today = le.get("today") if isinstance(le, dict) else None

        # ── One-sentence memory note ──────────────────────────────────────────
        note = None
        if similar >= 3 and avg_r is not None and wr_pct is not None:
            if avg_r > 0.3:
                note = ("Last %d similar setups: %.1fR average, %.0f%% wins."
                        % (similar, avg_r, wr_pct))
            elif avg_r < -0.1:
                note = ("Last %d similar setups averaged a loss (%.1fR, %.0f%% wins) "
                        "— proceed with extra caution." % (similar, avg_r, wr_pct))
            else:
                note = ("Last %d similar setups: breakeven (%.1fR, %.0f%% wins)."
                        % (similar, avg_r, wr_pct))
        elif lre_enabled and eligibility == "GHOST_ONLY":
            note = ("Setup historically disabled for live execution on "
                    "%s" % (inst or "this instrument"))
            if rule_triggered:
                note += ": %s." % rule_triggered

        return {
            "available":           True,
            "similar_samples":     similar,
            "avg_r":               avg_r,
            "win_rate_pct":        wr_pct,
            "most_common_failure": failure,
            "recommendation":      mem_rec,
            "confidence":          gov_conf,
            "allow":               allow,
            "governor_veto":       gov_veto,
            "eligibility":         eligibility,
            "disabled_setups":     disabled_setups,
            "le_today":            le_today,
            "note":                note,
        }
    except Exception as exc:
        try:
            logger.debug("mb_learning_snapshot error (non-fatal): %s", exc)
        except Exception:
            pass
        return _mb_learning_snapshot_neutral()


# ─────────────────────────────────────────────────────────────────────────────
# ORCHESTRATION LAYER — reads every engine once; returns pure structured data
#
# The Main Brain calls _mb_orchestrate() exactly once per poll. It never
# synthesises, never produces user-facing text, and never calls any engine
# more than once. Every specialist result flows through this single gateway.
# ─────────────────────────────────────────────────────────────────────────────

def _mb_orchestrate(result):
    """Read every specialist engine once and return a unified structured packet.

    Returns:
      observations     — list of _emit_observation dicts (one per engine)
      conflict_resolver — BCR 10-priority verdict block
      verdict_board    — 4-bucket Supports/Opposes/Missing/Vetoes block
      learning_memory  — unified learning snapshot (one read of all 4 sources)

    No synthesis, no scoring, no user-facing text produced here.
    Each engine read is individually fail-open. Never raises."""
    obs = []
    bcr = _bcr_neutral("Orchestration initialising.")
    vb  = _vb_neutral("Orchestration initialising.")
    lm  = _mb_learning_snapshot_neutral()
    try:
        obs = _mb_build_structured_observations(result)
    except Exception:
        pass
    try:
        bcr = compute_brain_conflict_resolver(result)
    except Exception:
        pass
    try:
        vb = compute_verdict_board(result, obs, bcr)
    except Exception:
        pass
    try:
        lm = _mb_learning_snapshot(result)
    except Exception:
        pass
    return {
        "observations":      obs,
        "conflict_resolver": bcr,
        "verdict_board":     vb,
        "learning_memory":   lm,
    }


def compute_main_brain(result):
    """Plain-English 'Main Brain' synthesis (DISPLAY-ONLY).

    Combines the already-assembled analyst / analyst_report / trade_debate /
    entry_quality / volatility / structure / zone / VWAP / edge / verdict /
    trade_plan blocks (and the live active position) into FOUR conversational
    'brain' views — Market / Strategy / Risk / Trade Manager — plus one combined
    summary and a status badge. It only READS `result`; it NEVER recomputes
    anything and NEVER touches the gate, sizing, dedupe or the money path. Fail-open
    to a stable neutral schema."""
    try:
        if not result.get("market_open", True):
            nb = _main_brain_neutral(
                "Market is closed — no live setups. I'll resume watching when it reopens.",
                status="WAIT")
            nb["summary"] = ("Market closed (%s). Standing down until the next session."
                             % (result.get("market_status") or "paused"))
            return nb

        inst       = instrument_of(result.get("active_ticker"))
        # A user-entered manual trade takes priority over the bot's own active trade
        # for this instrument: it is the explicit position the user asked the copilot
        # to manage. Falls back to the bot's live position when none exists.
        manual_pos = _newest_manual_trade_for(inst) if inst else None
        pos        = manual_pos or (active_trade_for(inst) if inst else None)
        pos_is_manual = manual_pos is not None
        verdict    = result.get("verdict") or ""
        actionable = is_actionable(verdict)

        ar   = result.get("analyst_report") or {}
        an   = result.get("analyst") or {}
        eq   = result.get("entry_quality") or {}
        vol  = result.get("volatility") or {}
        plan = result.get("trade_plan") or {}

        price  = result.get("current_price")
        vwap   = result.get("vwap_value")
        struct = result.get("structure_label") or "mixed"
        bias   = result.get("bias") or "Neutral"
        edge   = result.get("edge_score")
        grade  = result.get("edge_grade")
        n_dem  = result.get("nearest_demand")
        n_sup  = result.get("nearest_supply")
        cvd    = (result.get("cvd_state") or "").lower()
        regime = (vol.get("regime") or "").lower()
        atr_s  = _mb_fmt(vol.get("atr_pts"))

        fav = (ar.get("favored_direction") or result.get("strict_direction")
               or result.get("dominant_direction"))
        if fav not in ("Long", "Short"):
            fav = None

        # ── Market Brain ─────────────────────────────────────────────────
        market = []
        p_s = _mb_fmt(price)
        if p_s:
            market.append("Price is at %s; structure reads %s (%s bias)."
                          % (p_s, struct, str(bias).lower()))
        else:
            market.append("Structure reads %s (%s bias)." % (struct, str(bias).lower()))
        # VWAP side is derived from price-vs-value (vwap_status is freshness, NOT direction).
        v_s, pv, vv = _mb_fmt(vwap), _mb_num(price), _mb_num(vwap)
        if v_s and pv is not None and vv is not None:
            if pv >= vv:
                market.append("Trading above VWAP (%s) — that supports longs." % v_s)
            else:
                market.append("Trading below VWAP (%s) — that favours shorts." % v_s)
        elif v_s:
            market.append("VWAP is at %s." % v_s)
        d_s, s_s = _mb_fmt(n_dem), _mb_fmt(n_sup)
        if d_s or s_s:
            zbits = []
            if d_s:
                zbits.append("demand near %s" % d_s)
            if s_s:
                zbits.append("supply near %s" % s_s)
            market.append("Key zones: " + ", ".join(zbits) + ".")
        if cvd in ("bullish", "bearish"):
            market.append("Order-flow (CVD) is %s right now." % cvd)
        if regime:
            tag = {"normal": "normal", "elevated": "elevated", "extreme": "risky / extreme",
                   "low": "quiet", "quiet": "quiet"}.get(regime, regime)
            market.append(("Volatility is %s (ATR ~%s)." % (tag, atr_s)) if atr_s
                          else ("Volatility is %s." % tag))

        # ── Strategy Brain ───────────────────────────────────────────────
        strategy = []
        if fav:
            strategy.append(("A %s setup is READY and fits the playbook." % fav.lower())
                            if actionable else
                            ("A %s setup is forming, but it isn't ready yet." % fav.lower()))
        else:
            strategy.append("No clean directional setup yet — staying patient.")
        eq_chase = eq.get("chasing_warning")
        eq_label = eq.get("verdict_label") or eq.get("grade")
        if eq_chase:
            strategy.append("Entry timing: %s" % eq_chase)
        elif eq_label:
            strategy.append("Entry location looks %s." % str(eq_label).lower())
        what_next = []
        for src in (ar.get("what_increases_confidence"), an.get("what_needs_next")):
            if isinstance(src, list):
                for it in src:
                    s = str(it).strip()
                    if s and s not in what_next:
                        what_next.append(s)
        what_next = what_next[:4]
        if not actionable:
            if what_next:
                strategy.append("Still missing: " + "; ".join(what_next) + ".")
            else:
                wr = result.get("strict_reason") or an.get("reason_for_waiting")
                if wr:
                    strategy.append("Waiting because: %s" % wr)

        # ── Risk Brain ───────────────────────────────────────────────────
        risk = []
        risk_blk = an.get("risk") or {}
        rr = plan.get("rr") or risk_blk.get("rr")
        if rr:
            risk.append("Risk/reward on the working idea is about %s." % rr)
        stop_s = _mb_fmt(plan.get("stop_loss"))
        if stop_s:
            logical = risk_blk.get("stop_logical")
            if logical is True:
                risk.append("Stop at %s sits behind structure — sensible." % stop_s)
            elif logical is False:
                risk.append("Stop at %s — keep it behind the protecting zone." % stop_s)
            else:
                risk.append("Planned stop: %s." % stop_s)
        if regime in ("elevated", "extreme"):
            risk.append("Elevated volatility — size down and expect wider swings.")
        elif regime in ("normal", "low", "quiet"):
            risk.append("Volatility is contained — standard sizing is fine.")
        if edge is not None:
            risk.append("Edge Score is %s%s." % (edge, (" (%s)" % grade) if grade else ""))

        # ── Trade Manager (only meaningful with an open position) ─────────
        manager = []
        managing = invalidated = False
        if isinstance(pos, dict) and pos:
            managing = True
            pdir = pos.get("direction") or "?"
            pen  = _mb_num(pos.get("entry_price") if pos.get("entry_price") is not None
                           else pos.get("entry"))
            pst  = _mb_num(pos.get("stop_loss") if pos.get("stop_loss") is not None
                           else pos.get("stop"))
            manager.append("Managing an open %s position%s."
                           % (str(pdir).lower(),
                              (" from %s" % _mb_fmt(pen)) if pen is not None else ""))
            pv2 = _mb_num(price)
            if pv2 is not None and pst is not None:
                is_long = str(pdir).lower().startswith("l")
                if (is_long and pv2 <= pst) or ((not is_long) and pv2 >= pst):
                    invalidated = True
                    manager.append("Price has reached the stop — thesis invalidated, protect capital.")
            if pst is not None and not invalidated:
                manager.append("Stop is at %s — hold while it's respected." % _mb_fmt(pst))
        else:
            manager.append("No open position — I'll take over the moment a trade is entered.")

        # ── Status badge ─────────────────────────────────────────────────
        if invalidated:
            status = "INVALIDATED"
        elif managing:
            status = "MANAGING"
        elif actionable:
            status = "READY"
        elif fav and isinstance(edge, (int, float)) and edge >= 50:
            status = "BUILDING"
        else:
            status = "WATCHING"

        # ── Combined Main Brain read ─────────────────────────────────────
        if status == "READY" and fav:
            summary = ("Everything lines up for a %s — entry, location and risk all check out. "
                       "This is the one I've been building toward." % fav.lower())
        elif status == "INVALIDATED":
            summary = "The trade thesis just broke — protecting the position comes first."
        elif status == "MANAGING":
            summary = manager[0]
        elif status == "BUILDING" and fav:
            need = "; ".join(what_next) if what_next else (
                result.get("strict_reason") or "confirmation")
            summary = ("I'm building a %s case. Not in yet — I still want %s before I commit."
                       % (fav.lower(), need))
        else:
            summary = ("Watching and waiting — no clean edge right now. I'd rather miss a "
                       "trade than force a bad one.")

        # ── Confidence / Bias / Quality / Risk — READ existing blocks only ──
        dirs = result.get("directions") or {}
        le = _mb_num((dirs.get("Long")  or {}).get("edge_score"))
        se = _mb_num((dirs.get("Short") or {}).get("edge_score"))
        long_pct = short_pct = None
        if le is not None and se is not None and (le + se) > 0:
            long_pct  = int(round(le / (le + se) * 100))
            short_pct = 100 - long_pct
        conf_pct = _mb_num(an.get("confidence"))
        if conf_pct is None:
            _arc = ar.get("confidence")
            if isinstance(_arc, dict):
                conf_pct = _mb_num(_arc.get("score"))
        if conf_pct is None and edge is not None:
            conf_pct = _mb_num(edge)
        conf_pct = int(round(conf_pct)) if conf_pct is not None else None
        quality = grade or eq.get("grade") or eq.get("verdict_label")
        stop_logical = (an.get("risk") or {}).get("stop_logical")
        if regime in ("elevated", "extreme") or stop_logical is False:
            risk_level = "High"
        elif regime in ("normal", "low", "quiet") and not eq.get("chasing_warning"):
            risk_level = "Low"
        else:
            risk_level = "Medium"
        bull_case = [str(x).strip() for x in (an.get("bull_case") or []) if str(x).strip()][:5]
        bear_case = [str(x).strip() for x in (an.get("bear_case") or []) if str(x).strip()][:5]

        # ── Management read (advisory) — only when a position is open. Pass a COPY
        #    (compute_manual_trade_management writes min_r/max_r back onto the dict it is
        #    handed) and the already-assembled `result` as the analysis so it NEVER
        #    recomputes full_analysis (which would re-enter this function). Display-only;
        #    fail-open; touches no gate / sizing / dedupe / broker path. ──
        management_read = None
        if managing and isinstance(pos, dict):
            try:
                _mr_mirror = {
                    "id":          pos.get("id") or ("mb-%s" % (inst or "pos")),
                    "symbol":      pos.get("symbol") or inst,
                    "direction":   pos.get("direction", "Long"),
                    "entry_price": (pos.get("entry_price") if pos.get("entry_price") is not None
                                    else pos.get("entry")),
                    "stop_loss":   (pos.get("stop_loss") if pos.get("stop_loss") is not None
                                    else pos.get("stop")),
                    "target1":     pos.get("target1"),
                    "target2":     pos.get("target2"),
                    "target3":     pos.get("target3"),
                    "contracts":   pos.get("contracts"),
                    "mode":        pos.get("mode") or TRADING_MODE,
                    "reason":      (pos.get("reason") or "") if pos_is_manual else "",
                    "entry_time":  ((pos.get("entry_time") or pos.get("opened_at"))
                                    if pos_is_manual else pos.get("opened_at")) or None,
                    "opened_at":   pos.get("opened_at") or now_utc().isoformat(),
                    "status":      "open",
                }
                management_read = compute_manual_trade_management(_mr_mirror, analysis=result)
                if management_read is not None:
                    # Tag the source so the UI can label a user trade vs the bot's own,
                    # and surface the stored copilot timeline for a manual position.
                    management_read["origin"] = "manual" if pos_is_manual else "bot"
                    if pos_is_manual:
                        management_read["timeline"] = list(pos.get("timeline") or [])
            except Exception:
                management_read = None

        # ── Current Mission — conditions before READY (derived from reads only) ──
        mission = []
        if fav:
            is_long = (fav == "Long")
            if pv is not None and vv is not None:
                mission.append({"label": ("Above VWAP" if is_long else "Below VWAP"),
                                "done": bool((pv >= vv) if is_long else (pv <= vv))})
            _zone = n_dem if is_long else n_sup
            mission.append({"label": ("Demand zone in play" if is_long else "Supply zone in play"),
                            "done": _zone is not None})
            _sl = (struct or "").lower()
            mission.append({"label": ("Bullish structure (CHOCH/BOS)" if is_long
                                      else "Bearish structure (CHOCH/BOS)"),
                            "done": ("bull" in _sl) if is_long else ("bear" in _sl)})
            mission.append({"label": ("CVD supporting longs" if is_long else "CVD supporting shorts"),
                            "done": (cvd == "bullish") if is_long else (cvd == "bearish")})
            _eqlbl = str(eq.get("verdict_label") or eq.get("grade") or "").lower()
            mission.append({"label": "Clean entry (not chasing)",
                            "done": bool((not eq.get("chasing_warning"))
                                         and _eqlbl not in ("avoid", "poor"))})
        mission_progress = (int(round(sum(1 for m in mission if m["done"]) / len(mission) * 100))
                            if mission else 0)

        # ── Signals snapshot — the FRONTEND diffs this for the What-Changed feed ──
        signals = {
            "status":      status,
            "favored":     fav or "none",
            "vwap_side":   ("above" if (pv is not None and vv is not None and pv >= vv)
                            else "below" if (pv is not None and vv is not None) else "unknown"),
            "cvd":         cvd or "unknown",
            "structure":   struct,
            "zone":        ("demand" if (fav == "Long" and n_dem is not None)
                            else "supply" if (fav == "Short" and n_sup is not None) else "none"),
            "rr":          (str(rr) if rr else None),
            "confidence":  conf_pct,
            "edge":        (int(edge) if isinstance(edge, (int, float)) else None),
            "risk":        risk_level,
            "invalidated": bool(invalidated),
        }

        # ── Performance Review & deterministic lessons (DISPLAY-ONLY) ─────────
        # A trimmed snapshot of the cached resolved-event review plus plain-English
        # lessons for THIS exact (instrument | mode | setup). Drawn entirely from
        # history; never feeds the gate / sizing / dedupe / money path. Fail-open.
        performance_review = _main_brain_review_snapshot()
        lessons            = _main_brain_lessons(inst, TRADING_MODE,
                                                 result.get("market_regime"), fav)

        head_dir = (" %s" % fav) if (fav and status in ("BUILDING", "WATCHING", "READY")) else ""
        mb_out = {
            "status":            status,
            "headline":          "%s%s" % (status, head_dir),
            "summary":           summary,
            "market_brain":      market,
            "strategy_brain":    strategy,
            "risk_brain":        risk,
            "trade_manager":     manager,
            "favored_direction": fav,
            "edge_score":        edge,
            "edge_grade":        grade,
            "what_now":          what_next,
            "invalidation":      ar.get("invalidation") or an.get("invalidation") or "—",
            "mission":           mission,
            "mission_progress":  mission_progress,
            "signals":           signals,
            "confidence_pct":    conf_pct,
            "long_bias_pct":     long_pct,
            "short_bias_pct":    short_pct,
            "trade_quality":     quality,
            "risk_level":        risk_level,
            "bull_case":         bull_case,
            "bear_case":         bear_case,
            "management_read":   management_read,
            "performance_review": performance_review,
            "lessons":           lessons,
            "prop_rule":         _prop_main_brain_line(),
            "disclaimer":        _MAIN_BRAIN_DISCLAIMER,
            "reason":            None,
        }
        # Fold in the scalp-strategy advisory ONLY when it's present + enabled (flag ON);
        # otherwise the Main Brain dict stays byte-identical to today. DISPLAY-ONLY.
        _adv = result.get("scalp_strategy_advisory")
        if isinstance(_adv, dict) and _adv.get("enabled"):
            try:
                mb_out["potential_trades"] = _mb_potential_trades_summary(_adv)
            except Exception:
                pass
        # ── Orchestration: one call reads every engine → pure structured packet ──
        # No engine is read more than once. No synthesis happens here.
        _packet                    = _mb_orchestrate(result)
        mb_out["observations"]     = _packet["observations"]
        mb_out["conflict_resolver"] = _packet["conflict_resolver"]
        mb_out["verdict_board"]    = _packet["verdict_board"]
        mb_out["learning_memory"]  = _packet["learning_memory"]

        # ── Synthesis: Main Brain is the sole author of user-facing narrative ─
        try:
            mb_out["synthesis"] = _mb_synthesis_report(
                result, mb_out.get("observations") or [])
        except Exception:
            mb_out["synthesis"] = _mb_synthesis_neutral("Synthesis unavailable.")

        # ── Unified reconcile (legacy weighted vote; backward-compatible) ──────
        try:
            _obs     = _mb_collect_observations(result)
            _unified = _mb_reconcile(_obs, result)
            mb_out["unified"] = _unified
            if _unified.get("available") and _unified.get("narrative"):
                mb_out["summary"] = _unified["narrative"]
        except Exception:
            mb_out["unified"] = {"available": False}
        # V1 Partner Interface version field — additive, no behavior change.
        mb_out["_version"] = "v1"
        return mb_out
    except Exception as exc:
        try:
            logger.error("Main Brain compute error (non-fatal): %s", exc)
        except Exception:
            pass
        return _main_brain_neutral("Main Brain unavailable (%s)." % exc)


# ══════════════════════════════════════════════════════════════════════════════
# MAIN BRAIN COGNITIVE UPGRADE — continuous-analyst READ layer (DISPLAY-ONLY)
# ══════════════════════════════════════════════════════════════════════════════
# A family of pure, FAIL-OPEN synthesizers that turn the per-poll Main Brain into a
# continuous analyst: a forward PREDICTION engine, a natural conversational VOICE,
# CONFIDENCE-over-time, a continuous session NARRATIVE + events TIMELINE, and a
# session/day-type + learning-stats read. Every helper:
#   • only CONSUMES the already-assembled `result` (+ the confidence/event history via
#     capped, short-TTL-cached SELECTs) — it NEVER recomputes an engine, NEVER writes,
#     and NEVER touches the strict gate, scoring, sizing, dedupe or /traderspost path;
#   • has a fully-populated neutral block (the schema contract) and a try/except that
#     degrades to it, so the 4 goldens stay byte-identical and the money path is safe;
#   • is state-aware (neutral / limited when the market is closed) so attaching the
#     whole family ONCE at the final full_analysis seam covers open / vetoed / closed
#     without a separate mirror.
_MB_PRED_NOTE = "Estimated odds — a heuristic read of the current tape, not a guarantee."


def _mb_pf(x):
    """Parse to float or None. Never raises."""
    try:
        return float(x)
    except (TypeError, ValueError):
        return None


def _mb_pi(x):
    """Parse to int or 0. Never raises."""
    try:
        return int(round(float(x)))
    except (TypeError, ValueError):
        return 0


def _mb_clamp_odds(x):
    """Round to the nearest 5% and clamp to [5, 85] — honest, low-precision odds."""
    try:
        v = int(round(float(x) / 5.0)) * 5
        return max(5, min(85, v))
    except (TypeError, ValueError):
        return 35


def _mb_downsample(pts, n):
    """Evenly thin a [(t, v), ...] series to <= n points, always keeping the last."""
    if not pts or len(pts) <= n:
        return pts
    step = len(pts) / float(n)
    out = [pts[int(i * step)] for i in range(n)]
    if out and out[-1] != pts[-1]:
        out[-1] = pts[-1]
    return out


def _mb_segment_for(dt_utc):
    """Map an instant to its ET narrative segment (Overnight / London / NY Open /
    NY Session). Display grouping only — never raises."""
    try:
        h = (dt_utc or now_utc()).astimezone(ET_TZ).hour
        if 8 <= h < 11:
            return "NY Open"
        if 11 <= h < 16:
            return "NY Session"
        if 2 <= h < 8:
            return "London"
        return "Overnight"
    except Exception:
        return "Overnight"


# Tiny TTL cache so the DB-backed reads (confidence timeline / narrative / events)
# never run per-3s-poll SQL: a ~10-15s memo per (block, instrument) bounds DB load
# while staying fresher than the ~60s write cadence. In-memory + bounded + fail-open.
_MB_READ_CACHE      = {}
_MB_READ_CACHE_LOCK = threading.Lock()


def _mb_cached(key, ttl_secs, producer):
    nowts = time.time()
    try:
        with _MB_READ_CACHE_LOCK:
            ent = _MB_READ_CACHE.get(key)
            if ent and (nowts - ent[0]) < ttl_secs:
                return ent[1]
        val = producer()
        with _MB_READ_CACHE_LOCK:
            _MB_READ_CACHE[key] = (nowts, val)
            if len(_MB_READ_CACHE) > 200:
                for k in sorted(_MB_READ_CACHE, key=lambda kk: _MB_READ_CACHE[kk][0])[:50]:
                    _MB_READ_CACHE.pop(k, None)
        return val
    except Exception:
        try:
            return producer()
        except Exception:
            return None


# ── (1) Prediction engine ─────────────────────────────────────────────────────
def _main_brain_predictions_neutral(reason="Predictions unavailable."):
    return {
        "available":         False,
        "favored_direction": "Neither",
        "horizon":           "—",
        "predictions":       [],
        "note":              _MB_PRED_NOTE,
        "reason":            reason,
    }


def compute_main_brain_predictions(result):
    """Forward, HEURISTIC odds for the next few candles (bullish/bearish break,
    VWAP reclaim/hold, liquidity sweep, favored-side continuation). Anchored to the
    analyst's OWN scenario probabilities + market phase, nudged by live structure /
    CVD / VWAP location, then clamped to honest 5-85% / 5%-rounded bands. Pure +
    FAIL-OPEN; DISPLAY-ONLY."""
    try:
        if not result.get("market_open", True):
            return _main_brain_predictions_neutral("Market closed — no live tape to project.")
        analyst   = result.get("analyst") if isinstance(result.get("analyst"), dict) else {}
        gp        = analyst.get("game_plan") if isinstance(analyst.get("game_plan"), dict) else {}
        phase_blk = analyst.get("market_phase") if isinstance(analyst.get("market_phase"), dict) else {}
        p_long    = _mb_pi(gp.get("prob_long"))
        p_short   = _mb_pi(gp.get("prob_short"))
        nem       = gp.get("next_expected_move") if isinstance(gp.get("next_expected_move"), dict) else {}
        move_conf = _mb_pi(nem.get("confidence"))
        phase     = str(phase_blk.get("phase") or "—")
        dirs      = result.get("directions") if isinstance(result.get("directions"), dict) else {}
        d_long    = _mb_pi((dirs.get("Long")  or {}).get("edge_score"))
        d_short   = _mb_pi((dirs.get("Short") or {}).get("edge_score"))
        cvd_dir   = str(result.get("cvd_direction") or "").lower()
        struct    = str(result.get("structure_label") or "").lower()
        price     = _mb_pf(result.get("display_price"))
        if price is None:
            price = _mb_pf(result.get("current_price"))
        vwap       = _mb_pf(result.get("vwap_value"))
        above_vwap = (price is not None and vwap is not None and price >= vwap)
        below_vwap = (price is not None and vwap is not None and price < vwap)
        favored = "Long" if p_long > p_short else ("Short" if p_short > p_long else "Neither")
        trend_phases = ("Trend Beginning", "Trend Developing", "Breakout")

        preds = []

        # 1) Bullish break / continuation up
        b = []
        odds = p_long if p_long else 35
        if "bull" in cvd_dir:
            odds += 6; b.append("CVD bullish")
        if "bull" in struct or "uptrend" in struct:
            odds += 5; b.append("structure bullish")
        if phase in trend_phases and favored == "Long":
            odds += 5; b.append("phase: %s" % phase)
        if below_vwap:
            odds -= 6; b.append("price below VWAP (headwind)")
        if d_long:
            b.append("Long edge %d" % d_long)
        preds.append({"event": "Bullish break / continuation up", "direction": "Long",
                      "odds_pct": _mb_clamp_odds(odds), "basis": b[:4]})

        # 2) Bearish break / continuation down
        b = []
        odds = p_short if p_short else 35
        if "bear" in cvd_dir:
            odds += 6; b.append("CVD bearish")
        if "bear" in struct or "downtrend" in struct:
            odds += 5; b.append("structure bearish")
        if phase in trend_phases and favored == "Short":
            odds += 5; b.append("phase: %s" % phase)
        if above_vwap:
            odds -= 6; b.append("price above VWAP (headwind)")
        if d_short:
            b.append("Short edge %d" % d_short)
        preds.append({"event": "Bearish break / continuation down", "direction": "Short",
                      "odds_pct": _mb_clamp_odds(odds), "basis": b[:4]})

        # 3) VWAP interaction (side-aware)
        if vwap is not None and price is not None:
            if below_vwap:
                b = ["price below VWAP"]
                odds = (p_long if p_long else 40) - 5
                if "bull" in cvd_dir:
                    odds += 6; b.append("CVD bullish")
                preds.append({"event": "Reclaim VWAP from below", "direction": "Long",
                              "odds_pct": _mb_clamp_odds(odds), "basis": b[:4]})
            else:
                b = ["price above VWAP"]
                odds = (p_long if p_long else 45)
                if favored == "Long":
                    odds += 5; b.append("buyers in control")
                preds.append({"event": "Hold above VWAP (shallow pullback)", "direction": "Long",
                              "odds_pct": _mb_clamp_odds(odds), "basis": b[:4]})

        # 4) Liquidity sweep of a near-side level
        b = []
        if phase in ("Consolidation", "Reversal Watch"):
            odds = 50; b.append("phase favours a sweep")
        else:
            odds = 35; b.append("trending — sweep less likely")
        preds.append({"event": "Liquidity sweep of a near-side level", "direction": "Either",
                      "odds_pct": _mb_clamp_odds(odds), "basis": b[:3]})

        # 5) Favored-side continuation toward target (analyst's own next-move read)
        if favored != "Neither":
            b = []
            odds = move_conf if move_conf else max(p_long, p_short)
            if move_conf:
                b.append("analyst next-move confidence %d" % move_conf)
            mv = (nem.get("moves") or [])
            if mv:
                b.append(str(mv[-1]))
            preds.append({"event": "%s continuation toward target" % favored, "direction": favored,
                          "odds_pct": _mb_clamp_odds(odds), "basis": b[:3]})

        horizon = (gp.get("time_horizon") or {}).get("setup") or "the next few candles"
        return {"available": True, "favored_direction": favored, "horizon": horizon,
                "predictions": preds, "note": _MB_PRED_NOTE, "reason": None}
    except Exception:
        return _main_brain_predictions_neutral()


# ── (2) Conversational analyst voice ──────────────────────────────────────────
def _main_brain_voice_neutral(reason="Watching the tape — no clear read yet."):
    return {"available": False, "headline": "Watching", "narration": reason, "reason": reason}


def compute_main_brain_voice(result):
    """One natural, evolving paragraph — what I see / what changed / why / what I'm
    waiting for / what invalidates it — synthesized from the already-assembled blocks
    (Main Brain, analyst phase/outlook, edge, confidence trend). Pure + FAIL-OPEN."""
    try:
        mb      = result.get("main_brain") if isinstance(result.get("main_brain"), dict) else {}
        analyst = result.get("analyst") if isinstance(result.get("analyst"), dict) else {}
        inst    = result.get("active_ticker") or "the market"
        verdict = str(result.get("verdict") or "")
        if not result.get("market_open", True):
            return {"available": True, "headline": "Market closed",
                    "narration": ("The market's closed for %s right now, so I'm standing down. "
                                  "I'll pick the read back up when it reopens." % inst),
                    "reason": None}
        phase    = str(((analyst.get("market_phase") or {}).get("phase")) or "—")
        outlook  = analyst.get("analyst_outlook") if isinstance(analyst.get("analyst_outlook"), dict) else {}
        control  = str(outlook.get("control") or "")
        fav      = str(mb.get("favored_direction") or "Neither")
        edge     = _mb_pi(mb.get("edge_score") or result.get("edge_score"))
        grade    = str(result.get("edge_grade") or mb.get("edge_grade") or "")
        what_now = mb.get("what_now") if isinstance(mb.get("what_now"), list) else []
        inval    = str(mb.get("invalidation") or "")
        ct       = result.get("confidence_timeline") if isinstance(result.get("confidence_timeline"), dict) else {}
        trend    = str(ct.get("trend") or "")

        parts = []
        phase_desc = phase.lower() if phase != "—" else "a developing tape"
        see = "%s's in %s right now" % (inst, phase_desc)
        if control:
            see += " — %s" % control.rstrip(".").lower()
        parts.append(see + ".")

        if edge:
            c = "Edge is at %d%s" % (edge, (" — grade %s" % grade if grade else ""))
            if fav and fav != "Neither":
                c += ", leaning %s" % fav.lower()
            if trend in ("rising", "falling"):
                c += ", and it's been %s" % trend
            parts.append(c + ".")

        if is_actionable(verdict):
            parts.append("The pieces are there — this is actionable.")
        elif what_now:
            nx = what_now[0] if isinstance(what_now[0], str) else str(what_now[0])
            parts.append("Still need %s before I'd pull the trigger." % nx.rstrip("."))
        else:
            parts.append("No clean trigger yet, so I'm staying patient.")

        if inval and inval != "—":
            parts.append("Thesis is out if %s." % inval.rstrip(".").lower())

        narration = " ".join(p for p in parts if p)
        if edge:
            headline = "%s · edge %d%s" % ((fav if fav != "Neither" else "Neutral"), edge,
                                           (" %s" % grade if grade else ""))
        else:
            headline = (fav if fav and fav != "Neither" else "Watching")
        return {"available": True, "headline": headline, "narration": narration, "reason": None}
    except Exception:
        return _main_brain_voice_neutral()


# ── (3) Confidence over time ──────────────────────────────────────────────────
def _confidence_timeline_neutral(reason="No confidence history yet today."):
    return {"available": False, "current": None, "grade": None, "verdict": None,
            "direction": None, "high": None, "low": None, "trend": "flat",
            "delta": None, "samples": 0, "series": [], "reason": reason}


def compute_confidence_timeline(inst):
    """Per-instrument Edge-Score time series for the CURRENT ET session-day:
    current / high / low / trend (+ a thinned series for a sparkline). Capped,
    short-TTL-cached SELECT. Pure + FAIL-OPEN; DISPLAY-ONLY."""
    def _produce():
        if not CONFIDENCE_SNAPSHOTS_DB_READY or not inst:
            return _confidence_timeline_neutral("Confidence history unavailable.")
        conn = _learning_conn()
        if conn is None:
            return _confidence_timeline_neutral("Confidence history unavailable.")
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT edge_score, grade, verdict, direction, snapshot_at
                       FROM confidence_snapshots
                       WHERE instrument=%s
                         AND (snapshot_at AT TIME ZONE 'America/New_York')::date
                             = (now() AT TIME ZONE 'America/New_York')::date
                       ORDER BY snapshot_at ASC LIMIT 500""", (inst,))
                rows = cur.fetchall()
            edges = [(float(r[0]), r) for r in rows if r[0] is not None]
            if not edges:
                return _confidence_timeline_neutral()
            vals    = [e for e, _r in edges]
            current = vals[-1]
            hi      = max(vals)
            lo      = min(vals)
            latest  = edges[-1][1]
            base    = vals[max(0, len(vals) - 10)] if len(vals) >= 4 else vals[0]
            delta   = current - base
            trend   = "rising" if delta >= 5 else ("falling" if delta <= -5 else "flat")
            series  = _mb_downsample([(r[4].isoformat(), e) for e, r in edges], 40)
            return {"available": True, "current": round(current, 1),
                    "grade": latest[1], "verdict": latest[2], "direction": latest[3],
                    "high": round(hi, 1), "low": round(lo, 1), "trend": trend,
                    "delta": round(delta, 1), "samples": len(vals),
                    "series": [{"t": t, "edge": round(e, 1)} for t, e in series],
                    "reason": None}
        except Exception as exc:
            return _confidence_timeline_neutral("Confidence history unavailable (%s)." % exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass
    res = _mb_cached(("conf_tl", inst), 12.0, _produce)
    return res if isinstance(res, dict) else _confidence_timeline_neutral("Confidence history unavailable.")


# ── (4) Continuous session narrative + events timeline ────────────────────────
def _market_narrative_neutral(reason="No session story yet."):
    return {"available": False, "segments": [], "current": reason,
            "expectation": "—", "reason": reason}


def _mb_segment_summary(seg, evs):
    """One-line plain-English summary of a segment's events (kind counts + edge range)."""
    try:
        from collections import Counter
        c     = Counter(k for (k, _h, _t, _e) in evs)
        edges = [float(e) for (_k, _h, _t, e) in evs if e is not None]
        label = {"vwap_reclaim": "VWAP reclaim", "vwap_loss": "VWAP loss",
                 "cvd_flip": "CVD flip", "sweep": "liquidity sweep",
                 "structure": "structure break", "phase": "phase shift",
                 "edge_move": "edge swing"}
        bits = []
        for kind, cnt in c.most_common():
            nm = label.get(kind, kind)
            bits.append(("%d× %s" % (cnt, nm)) if cnt > 1 else nm)
        s = ", ".join(bits[:4])
        if edges:
            s += "; edge %d–%d" % (int(min(edges)), int(max(edges)))
        return s or "quiet"
    except Exception:
        return "—"


def _mb_narrative_current(result, inst):
    try:
        if not result.get("market_open", True):
            return "Market closed — session paused."
        analyst = result.get("analyst") or {}
        phase   = str(((analyst.get("market_phase") or {}).get("phase")) or "developing")
        mb      = result.get("main_brain") or {}
        fav     = str(mb.get("favored_direction") or "Neither")
        edge    = _mb_pi(mb.get("edge_score") or result.get("edge_score"))
        grade   = str(result.get("edge_grade") or "")
        verdict = str(result.get("verdict") or "")
        s = "%s now reading %s" % (inst, phase.lower())
        if edge:
            s += ", edge %d%s" % (edge, (" %s" % grade if grade else ""))
        if fav and fav != "Neither":
            s += " leaning %s" % fav.lower()
        if verdict:
            s += " — %s" % verdict
        return s + "."
    except Exception:
        return "—"


def _mb_narrative_expectation(result):
    try:
        preds = result.get("main_brain_predictions") or {}
        plist = preds.get("predictions") or []
        if plist:
            top = max(plist, key=lambda p: p.get("odds_pct") or 0)
            return "Most likely next: %s (~%d%%)." % (top.get("event", "—"),
                                                      int(top.get("odds_pct") or 0))
        analyst = result.get("analyst") or {}
        nem     = ((analyst.get("game_plan") or {}).get("next_expected_move")) or {}
        moves   = nem.get("moves") or []
        if moves:
            return "Expecting: %s." % moves[0]
        return "Waiting for the tape to commit."
    except Exception:
        return "—"


_PHASE_ANALYST_MEANINGS = {
    "Trend Mature":     "The trend is established but extended. Continuation entries carry more risk from here — prefer pullbacks into VWAP or structure for better R:R.",
    "Trend Exhausted":  "The move has already traveled far enough that chasing entries is low quality. Wait for a clean pullback, liquidity sweep, or CHOCH before entering.",
    "Trend Beginning":  "A fresh directional move is starting. Structure has broken and the trade is early — better R:R is available now than later.",
    "Trend Developing": "A directional lean is building but not yet fully confirmed. The setup is forming — watch for structure + volume agreement.",
    "Consolidation":    "Price is compressing with no clear directional edge. The market is building energy before a breakout or breakdown — wait for a decisive move.",
    "Pullback":         "The market is pulling back against the primary trend. This is often the highest-quality entry zone — look for absorption and a directional hold.",
    "Reversal Watch":   "A liquidity sweep with change of character suggests the prior move may be ending. Caution on continuation — watch for the new direction to confirm.",
    "Breakout":         "Price is expanding structure with volume. Trade the follow-through, not the anticipation.",
    "Ranging":          "Price is oscillating between defined levels with no trend. Fade the extremes; avoid breakout entries without strong volume confirmation.",
    "Mean Reversion":   "Price has extended and is snapping back to value. Aggressive trend entries are lower probability here.",
    "Developing":       "The session is still establishing its character. Patterns are not yet clear enough to commit to a strong directional bias.",
}


def _mb_analyst_notebook(result, inst, all_rows=None):
    """Generate the 8-section AI Analyst Notebook from the assembled result.
    DISPLAY-ONLY + FAIL-OPEN: returns an empty dict on any error so the panel
    simply shows its defaults. Never touches the gate / scoring / sizing."""
    try:
        analyst   = result.get("analyst")   or {}
        phase_blk = analyst.get("market_phase") or {}
        outlook   = analyst.get("analyst_outlook") or {}
        game_plan = analyst.get("game_plan") or {}
        mb        = result.get("main_brain") or {}
        preds_blk = result.get("main_brain_predictions") or {}

        # ── 1. Current Bias ──────────────────────────────────────────────────────────────
        fav  = str(mb.get("favored_direction") or "Neither")
        dyn  = game_plan.get("dynamic_confidence") or {}
        def _pc(k):
            try:    return max(0, min(100, int(round(float(dyn.get(k) or 0)))))
            except: return 0
        c_long, c_short, c_neut = _pc("long"), _pc("short"), _pc("neutral")
        total_dyn = c_long + c_short + c_neut
        if total_dyn <= 0:
            c_long = c_short = c_neut = 33
            total_dyn = 99
        # Derive bias direction; clamp probability so a lean shows >=30%
        control   = str(outlook.get("control") or "").strip()
        if fav == "Long":
            bias_dir = "Bullish"
            bias_pct = max(30, int(round(c_long * 100 / total_dyn))) if c_long > 0 else 50
        elif fav == "Short":
            bias_dir = "Bearish"
            bias_pct = max(30, int(round(c_short * 100 / total_dyn))) if c_short > 0 else 50
        else:
            if "buyers" in control.lower():
                bias_dir = "Bullish"; bias_pct = max(30, int(round(c_long * 100 / total_dyn)))
            elif "sellers" in control.lower():
                bias_dir = "Bearish"; bias_pct = max(30, int(round(c_short * 100 / total_dyn)))
            else:
                bias_dir = "Neutral"; bias_pct = 50
        wait_list  = list(outlook.get("wait_reasoning") or [])
        bias_parts = [control] + [w for w in wait_list[:2] if w and not w.lower().startswith("wait")]
        bias_reason = " ".join(p for p in bias_parts if p).strip() or "Building a directional case."

        # ── 2. Market Character ────────────────────────────────────────────────────────
        phase        = str(phase_blk.get("phase") or "Developing")
        phase_detail = "; ".join((phase_blk.get("reasons") or [])[:3])
        phase_meaning = _PHASE_ANALYST_MEANINGS.get(
            phase, "The market is establishing its character — observe before acting.")

        # ── 3. Current Thesis ─────────────────────────────────────────────────────────
        thesis = str(game_plan.get("thesis") or "").strip()
        if not thesis:
            intent = str(outlook.get("market_intent") or "").strip()
            cvr    = str(outlook.get("continuation_vs_reversal") or "").strip()
            thesis = " ".join(filter(None, [intent, cvr])).strip() or "Thesis developing."

        # ── 4. Most Likely Next Move ──────────────────────────────────────────────────
        pred_list = list(preds_blk.get("predictions") or [])
        if pred_list:
            next_moves = [{"label": str(p.get("event", "—")),
                           "pct":   int(p.get("odds_pct") or 0)}
                          for p in sorted(pred_list, key=lambda x: -(x.get("odds_pct") or 0))[:3]]
        else:
            pct_l = int(round(c_long  * 100 / total_dyn))
            pct_s = int(round(c_short * 100 / total_dyn))
            pct_n = 100 - pct_l - pct_s
            if fav == "Long":
                next_moves = [{"label": "Bullish continuation", "pct": pct_l},
                              {"label": "Range / chop",         "pct": pct_n},
                              {"label": "Bearish reversal",     "pct": pct_s}]
            elif fav == "Short":
                next_moves = [{"label": "Bearish continuation", "pct": pct_s},
                              {"label": "Range / chop",          "pct": pct_n},
                              {"label": "Bullish reversal",      "pct": pct_l}]
            else:
                next_moves = [{"label": "Bullish breakout",  "pct": pct_l},
                              {"label": "Range / chop",       "pct": pct_n},
                              {"label": "Bearish breakdown",  "pct": pct_s}]

        # ── 5. Key Memory From Today ─────────────────────────────────────────────────────
        key_memory = []
        if all_rows:
            try:
                from collections import Counter, defaultdict as _dd
                kinds = Counter(r[0] for r in all_rows)
                edges_for = _dd(list)
                for kind, _h, _t, edge in all_rows:
                    if edge is not None:
                        try: edges_for[kind].append(float(edge))
                        except Exception: pass
                vr, vl = kinds.get("vwap_reclaim", 0), kinds.get("vwap_loss", 0)
                if vr > 0 and vl > 0:
                    if vl > vr:
                        key_memory.append("VWAP reclaims have failed %d time%s today — buyers keep losing the level." % (vl, "s" if vl > 1 else ""))
                    else:
                        key_memory.append("Buyers have reclaimed VWAP %d time%s — the level is being defended." % (vr, "s" if vr > 1 else ""))
                elif vl > 1:
                    key_memory.append("Price has lost VWAP %d times today — sellers keep pushing back in." % vl)
                elif vr > 1:
                    key_memory.append("Multiple VWAP reclaims today — buyers are consistently defending the level.")
                cf = kinds.get("cvd_flip", 0)
                if cf >= 2:
                    key_memory.append("Delta has flipped %d times — two-sided activity; avoid heavy directional bias." % cf)
                ph = kinds.get("phase", 0)
                if ph >= 2:
                    key_memory.append("Market character has shifted %d times — not a clean trending session." % ph)
                em_vals = edges_for.get("edge_move", [])
                if len(em_vals) >= 2:
                    avg_em = sum(em_vals) / len(em_vals)
                    if avg_em > 60:
                        key_memory.append("Edge has been building strength today — momentum is accumulating.")
                    elif avg_em < 40:
                        key_memory.append("Edge has been declining today — setups are not cleanly developing.")
                all_edges = [float(e) for (_k, _h, _t, e) in all_rows if e is not None]
                if len(all_edges) >= 4:
                    mx, mn = max(all_edges), min(all_edges)
                    if mx - mn > 35:
                        key_memory.append("Edge has swung widely today (%.0f–%.0f) — volatile setup quality." % (mn, mx))
            except Exception:
                pass
        if not key_memory:
            key_memory = ["Session is early — not enough history to extract clear lessons yet."]

        # ── 6. Trade Instructions ──────────────────────────────────────────────────────────
        verdict_str = str(result.get("verdict") or "WAIT").upper()
        is_ready    = verdict_str.startswith("READY")
        nhe         = str(outlook.get("next_high_probability_entry") or "").strip()
        gp_wait     = list((game_plan.get("next_opportunity") or {}).get("waiting_for") or [])
        wait_for    = []
        if not is_ready:
            if nhe:
                wait_for.append(nhe)
            for w in gp_wait[:3]:
                if w and w not in wait_for:
                    wait_for.append(str(w))
        invalid_raw = str(outlook.get("invalidates") or game_plan.get("invalidation") or "").strip()
        cancels     = str(outlook.get("cancels_setup") or "").strip()
        invalid_if  = []
        if invalid_raw and invalid_raw not in ("—", ""):
            invalid_if.append(invalid_raw)
        if cancels and cancels not in invalid_if:
            invalid_if.append(cancels)
        if is_ready:
            instruction = "Setup is active — the edge qualifies for entry now."
        elif fav == "Long":
            instruction = "Do not chase the long. Wait for price to pull back to value."
        elif fav == "Short":
            instruction = "Do not short weakness. Wait for a rally into resistance."
        else:
            instruction = "Stay flat. Wait for one side to take clear control."

        # ── 8. Analyst Note (first-person) ──────────────────────────────────────────────────
        cvr    = str(outlook.get("continuation_vs_reversal") or "").strip()
        wait_r = str(wait_list[0]) if wait_list else ""
        if is_ready:
            note = "The setup meets my criteria. I am ready to act with the plan."
        elif fav == "Long":
            note = "I am leaning long but I need a better entry. " + (wait_r or "Patience improves entry quality.")
        elif fav == "Short":
            note = "I am leaning short but I do not want to chase a mature move. " + (wait_r or "Patience improves entry quality.")
        else:
            note = "No clear directional edge yet. " + (cvr or "I am watching for one side to take control.")

        return {
            "bias":               {"direction": bias_dir, "probability": bias_pct, "reason": bias_reason},
            "market_character":   {"phase": phase, "meaning": phase_meaning, "detail": phase_detail},
            "thesis":             thesis,
            "next_moves":         next_moves,
            "key_memory":         key_memory,
            "trade_instructions": {
                "verdict":     verdict_str,
                "is_ready":    is_ready,
                "instruction": instruction,
                "wait_for":    wait_for[:5],
                "invalid_if":  invalid_if[:3],
            },
            "analyst_note": note.strip(),
        }
    except Exception as exc:
        logger.debug("_mb_analyst_notebook failed (fail-open): %s", exc)
        return {}



def compute_market_narrative(result, inst):
    """Synthesize the session story at READ time from persisted market_events grouped
    Overnight / London / NY Open / NY Session, plus a live Current + Expectation line.
    Facts persisted, prose generated here. Capped, short-TTL-cached. Pure + FAIL-OPEN."""
    def _produce():
        segments = []
        all_rows_for_nb = []
        if MARKET_EVENTS_DB_READY and inst:
            conn = _learning_conn()
            if conn is not None:
                try:
                    with conn.cursor() as cur:
                        cur.execute(
                            """SELECT segment, kind, headline, event_ts, edge_score
                               FROM market_events
                               WHERE instrument=%s
                                 AND (event_ts AT TIME ZONE 'America/New_York')::date
                                     = (now() AT TIME ZONE 'America/New_York')::date
                               ORDER BY event_ts ASC LIMIT 300""", (inst,))
                        rows = cur.fetchall()
                    grouped = {}
                    all_rows_for_nb = [(kind, headline, ts, edge)
                                       for _seg, kind, headline, ts, edge in rows]
                    for seg, kind, headline, ts, edge in rows:
                        grouped.setdefault(seg or "Overnight", []).append((kind, headline, ts, edge))
                    for seg in ("Overnight", "London", "NY Open", "NY Session"):
                        evs = grouped.get(seg)
                        if not evs:
                            continue
                        heads = [h for (_k, h, _t, _e) in evs][-6:]
                        segments.append({"segment": seg,
                                         "summary": _mb_segment_summary(seg, evs),
                                         "events": heads})
                except Exception:
                    pass
                finally:
                    try:
                        conn.close()
                    except Exception:
                        pass
        current     = _mb_narrative_current(result, inst)
        expectation = _mb_narrative_expectation(result)
        avail       = bool(segments) or bool(result.get("market_open", True))
        notebook    = _mb_analyst_notebook(result, inst, all_rows=all_rows_for_nb)
        return {"available": avail, "segments": segments, "current": current,
                "expectation": expectation, "notebook": notebook,
                "reason": None if avail else "No session story yet."}
    res = _mb_cached(("narr", inst), 12.0, _produce)
    return res if isinstance(res, dict) else _market_narrative_neutral()


def compute_market_events_timeline(inst):
    """Recent curated tape events (newest first) for the events feed. Capped,
    short-TTL-cached SELECT. Pure + FAIL-OPEN; DISPLAY-ONLY."""
    def _produce():
        if not MARKET_EVENTS_DB_READY or not inst:
            return {"available": False, "events": [], "reason": "Events unavailable."}
        conn = _learning_conn()
        if conn is None:
            return {"available": False, "events": [], "reason": "Events unavailable."}
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT event_ts, segment, kind, headline, edge_score
                       FROM market_events WHERE instrument=%s
                       ORDER BY event_ts DESC LIMIT 25""", (inst,))
                rows = cur.fetchall()
            evs = [{"t": (r[0].isoformat() if r[0] else None), "segment": r[1],
                    "kind": r[2], "headline": r[3],
                    "edge_score": (round(float(r[4]), 1) if r[4] is not None else None)}
                   for r in rows]
            return {"available": bool(evs), "events": evs,
                    "reason": None if evs else "No events recorded yet."}
        except Exception as exc:
            return {"available": False, "events": [], "reason": "Events unavailable (%s)." % exc}
        finally:
            try:
                conn.close()
            except Exception:
                pass
    res = _mb_cached(("evts", inst), 10.0, _produce)
    return res if isinstance(res, dict) else {"available": False, "events": [], "reason": "Events unavailable."}


# ── (5) Session / day-type classifier + learning stats ────────────────────────
def _session_day_type_neutral(reason="Day type forming."):
    return {"available": False, "day_type": "—", "confidence": 0, "reasons": [], "reason": reason}


def compute_session_day_type(result):
    """Classify today's character (Trending / Range-bound / Two-sided / Volatile)
    from the live phase + volatility read. Pure + FAIL-OPEN; DISPLAY-ONLY."""
    try:
        if not result.get("market_open", True):
            return _session_day_type_neutral("Market closed.")
        analyst = result.get("analyst") or {}
        phase   = str(((analyst.get("market_phase") or {}).get("phase")) or "")
        vol     = result.get("volatility") if isinstance(result.get("volatility"), dict) else {}
        vol_lbl = str((vol.get("label") if isinstance(vol, dict) else "") or "")
        mult    = _mb_pf(result.get("volatility_multiplier"))
        reasons = []
        if phase in ("Trend Developing", "Trend Mature", "Breakout", "Trend Beginning"):
            day = "Trending"; reasons.append("Phase: %s" % phase)
        elif phase == "Consolidation":
            day = "Range-bound"; reasons.append("Phase: consolidation / rotation")
        elif phase in ("Reversal Watch", "Trend Exhausted"):
            day = "Two-sided / reversal-prone"; reasons.append("Phase: %s" % phase)
        else:
            day = "Developing"
        if mult is not None and mult >= 1.3:
            if day in ("Trending", "Developing"):
                day = "Volatile"
            reasons.append("Volatility %.1f× baseline" % mult)
        elif mult is not None and mult <= 0.7:
            reasons.append("Below-average volatility")
        if vol_lbl:
            reasons.append("Volatility: %s" % vol_lbl)
        conf = 55
        if phase and phase != "—":
            conf += 10
        if mult is not None:
            conf += 5
        conf = max(30, min(85, conf))
        return {"available": True, "day_type": day, "confidence": conf,
                "reasons": reasons[:4], "reason": None}
    except Exception:
        return _session_day_type_neutral()


def compute_cross_mode_stats(inst=None):
    """Per-mode (SWING/SCALP/MICRO_SCALP) aggregate stats from the PER_MODE_STATS cache.
    Returns {mode: {n, win_rate, avg_r, expectancy, top_setup}} — only includes modes
    that have actual closed-trade samples. DISPLAY-ONLY, FAIL-OPEN."""
    try:
        with LEARNING_LOCK:
            pms = dict(PER_MODE_STATS)
        out = {}
        for m in ["SWING", "SCALP", "MICRO_SCALP"]:
            s = pms.get(m) or {}
            if s.get("n", 0) > 0:
                out[m] = {
                    "n":          s["n"],
                    "win_rate":   s.get("win_rate"),
                    "avg_r":      s.get("avg_r"),
                    "expectancy": s.get("expectancy"),
                    "top_setup":  s.get("top_setup"),
                }
        return out if out else None
    except Exception:
        return None


def compute_main_brain_learning_stats():
    """Curated deeper learning stats (most common losing pattern, most common skip
    reason, best setup / best+worst windows, win-rate, avg-R) sourced from the
    IN-MEMORY Performance Review cache — no per-request SQL. Pure + FAIL-OPEN."""
    base = {"available": False, "reason": "Not enough trade history yet.",
            "win_rate": None, "avg_r": None, "sample": 0, "losing_pattern": None,
            "losing_pattern_n": None, "skip_pattern": None, "best_setup": None,
            "best_window": None, "worst_window": None}
    try:
        r = _main_brain_review_snapshot()
        if not r or not r.get("ready"):
            return base
        cl = r.get("common_loss") or {}
        cr = r.get("common_rejection") or {}
        return {"available": True, "reason": None,
                "win_rate": r.get("win_rate"), "avg_r": r.get("avg_r"),
                "sample": r.get("decided_trades") or 0,
                "losing_pattern": (cl.get("reason") if cl else None),
                "losing_pattern_n": (cl.get("n") if cl else None),
                "skip_pattern": (cr.get("reason") if cr else None),
                "best_setup": r.get("best_setup"),
                "best_window": r.get("best_window"),
                "worst_window": r.get("worst_window"),
                "mode_comparison": compute_cross_mode_stats()}
    except Exception:
        base["reason"] = "Learning stats unavailable."
        return base


# ── BrainState: unified structured snapshot per instrument (DISPLAY-ONLY) ───────────
# Assembled at the end of full_analysis() from ALL specialist engine outputs.
# Consumed by the AI character, chat assistant, and any dashboard panel.
# NEVER recomputes — pure assembly/reshape. FAIL-OPEN (try/except wraps everything).
# Never touches gate / scoring / sizing / dedup / traderspost / money path.

_BRAIN_STATE_EVENTS = {}   # inst -> list[dict] newest-first, max 20 entries
_BRAIN_STATE_LAST   = {}   # inst -> snapshot dict for meaningful-change detection

def _bs_get(d, *keys, default=None):
    """Safe nested dict accessor: returns default if any key absent or value non-dict."""
    for k in keys:
        if not isinstance(d, dict):
            return default
        d = d.get(k)
        if d is None:
            return default
    return d

def _bs_record_events(inst, result):
    """Diff current brain snapshot against last; append only meaningful state changes."""
    cur = {
        "verdict":  result.get("verdict"),
        "bias":     result.get("bias"),
        "struct":   result.get("structure_class"),
        "has_pos":  bool(result.get("active_trade")),
        "rec":      _bs_get(result, "unified", "recommendation"),
        "missing":  result.get("strict_missing"),
    }
    prev = _BRAIN_STATE_LAST.get(inst, {})
    if inst not in _BRAIN_STATE_EVENTS:
        _BRAIN_STATE_EVENTS[inst] = []
    try:
        import datetime as _dtime
        _ts = _dtime.datetime.utcnow().strftime("%H:%M")
    except Exception:
        _ts = ""

    def _evt(kind, detail):
        _BRAIN_STATE_EVENTS[inst].insert(0, {"kind": kind, "detail": detail, "ts": _ts})
        if len(_BRAIN_STATE_EVENTS[inst]) > 20:
            _BRAIN_STATE_EVENTS[inst] = _BRAIN_STATE_EVENTS[inst][:20]

    if prev.get("verdict") and cur["verdict"] != prev["verdict"]:
        _evt("verdict_change", "%s → %s" % (prev["verdict"], cur["verdict"]))
    if prev.get("bias") and cur["bias"] and cur["bias"] != prev["bias"]:
        _evt("bias_flip", "%s → %s" % (prev["bias"], cur["bias"]))
    if prev.get("struct") and cur["struct"] and cur["struct"] != prev["struct"]:
        _evt("structure_flip", "%s → %s" % (prev["struct"], cur["struct"]))
    if prev.get("has_pos") is not None and cur["has_pos"] != prev["has_pos"]:
        _evt("position_opened" if cur["has_pos"] else "position_closed",
             result.get("verdict", ""))
    if cur["missing"] and cur["missing"] != prev.get("missing"):
        _evt("blocker_changed", str(cur["missing"]))
    _BRAIN_STATE_LAST[inst] = cur

def _build_brain_state(result):
    """Assemble the full BrainState snapshot from full_analysis output (DISPLAY-ONLY)."""
    try:
        inst = result.get("active_ticker") or "MGC"

        # ── Learning eligibility ──────────────────────────────────────────
        try:
            _elig_status, _elig_reason = _check_learning_eligibility(inst, mode=TRADING_MODE)
        except Exception:
            _elig_status, _elig_reason = "LIVE_ELIGIBLE", None

        # ── Record meaningful state changes ───────────────────────────────
        _bs_record_events(inst, result)

        # ── Veto sources (engines that would block a live trade) ──────────
        _veto_srcs = []
        if _bs_get(result, "trade_debate",        "veto_would_fire"): _veto_srcs.append("Trade Debate")
        if _bs_get(result, "analyst",             "veto_would_fire"): _veto_srcs.append("Analyst")
        if _bs_get(result, "pro_review",          "veto_would_fire"): _veto_srcs.append("Pro Review")
        if _bs_get(result, "confidence_governor", "allow_trade") is False: _veto_srcs.append("Confidence")
        if _bs_get(result, "entry_quality",       "veto_would_fire"): _veto_srcs.append("Entry Quality")
        if _bs_get(result, "volatility",          "blocked"):         _veto_srcs.append("Volatility")

        # ── Active position summary ───────────────────────────────────────
        _at = result.get("active_trade") or result.get("managed_trade")
        _pos = None
        if _at:
            _r = _at.get("current_r")
            _pos = {
                "direction": _at.get("direction"),
                "entry":     _at.get("entry"),
                "current_r": _r,
                "pnl_label": ("%s%.2fR" % ("+" if (_r or 0) >= 0 else "", _r)) if _r is not None else None,
                "opened_at": _at.get("opened_at_et") or _at.get("opened_at"),
            }

        # ── Trade plan summary ────────────────────────────────────────────
        _tp = result.get("trade_plan") or {}
        _plan = None
        if _tp.get("trade_plan"):
            _plan = {
                "direction":  _tp.get("direction"),
                "entry_zone": _tp.get("entry_zone"),
                "stop_loss":  _tp.get("stop_loss"),
                "target1":    _tp.get("target1"),
                "rr":         _tp.get("rr"),
                "invalidation": _tp.get("invalidation"),
            }

        # ── VWAP state string ─────────────────────────────────────────────
        _price = result.get("current_price") or 0
        _vwap  = result.get("vwap_value") or 0
        _side  = "above" if _price > _vwap > 0 else "below" if _price < _vwap > 0 else "at"
        _fresh = result.get("vwap_status") != "stale"
        _vwap_str = "%s VWAP (%s)%s" % (_side, _vwap, "" if _fresh else " [stale]")

        # ── Order flow string ─────────────────────────────────────────────
        _ad   = result.get("alert_diagnostics") or {}
        _cvd  = _ad.get("cvd_state") or "unknown"
        _rvol = _ad.get("rvol_value")
        _of_str = "CVD %s" % _cvd + (" · RVOL %.1fx" % _rvol if isinstance(_rvol, (int, float)) else "")

        # ── Volatility string ─────────────────────────────────────────────
        _vol = result.get("volatility") or {}
        _vreg = _vol.get("regime") or "Normal"
        _vrat = _vol.get("atr_ratio")
        _vol_str = _vreg + (" (%.2fx)" % _vrat if isinstance(_vrat, (int, float)) else "")

        # ── Entry quality string ──────────────────────────────────────────
        _eq = result.get("entry_quality") or {}
        _eq_str = ("%s (%s/100)" % (_eq.get("location_label", ""), _eq.get("score", 0))
                   if _eq.get("available") else None)

        # ── Prop firm status ──────────────────────────────────────────────
        try:
            _prop = prop_firm_status_view()
            _prop_str = "Violation" if _prop.get("violation") else "Protected" if _prop.get("enabled") else "Off"
        except Exception:
            _prop_str = "Unknown"

        # ── Important zones ───────────────────────────────────────────────
        _zones = []
        if result.get("nearest_demand"):
            _zones.append({"type": "demand", "level": result["nearest_demand"]})
        if result.get("nearest_supply"):
            _zones.append({"type": "supply", "level": result["nearest_supply"]})

        # ── Recent events snapshot (display-only, newest first) ───────────
        _events = list(_BRAIN_STATE_EVENTS.get(inst, []))[:10]

        return {
            "available": True,
            "identity": {
                "market":         inst,
                "timestamp":      result.get("as_of_et") or result.get("last_updated"),
                "data_freshness": _bs_get(result, "data_feed", "freshness_label"),
                "session":        _bs_get(result, "session", "window") or result.get("session_window"),
                "market_open":    result.get("market_open", True),
            },
            "market_read": {
                "phase":           _bs_get(result, "market_narrative", "phase") or _bs_get(result, "analyst", "market_phase"),
                "structure":       result.get("structure_label"),
                "structure_class": result.get("structure_class"),
                "trend":           result.get("bias"),
                "liquidity_state": _bs_get(result, "main_brain", "liquidity_focus", "state"),
                "vwap_state":      _vwap_str,
                "vwap_value":      _vwap or None,
                "price":           _price or None,
                "order_flow":      _of_str,
                "volatility":      _vol_str,
                "important_zones": _zones,
                "market_character": _bs_get(result, "session_day_type", "day_type"),
            },
            "playbooks": {
                "swing_opinion":        _bs_get(result, "dual_sim",     "swing", "verdict"),
                "scalp_opinion":        _bs_get(result, "dual_sim",     "scalp", "verdict"),
                "micro_scalp_opinion":  _bs_get(result, "main_brain",   "micro_scalp", "phase"),
                "selected_playbook":    TRADING_MODE,
                "rejected_playbooks":   _bs_get(result, "playbook_selector", "rejected") or [],
                "reason_selected":      _bs_get(result, "playbook_selector", "why"),
                "final_decision":       _bs_get(result, "playbook_selector", "final_decision"),
            },
            "setup": {
                "direction":          result.get("stage_direction") or result.get("strict_direction"),
                "setup_fingerprint":  result.get("setup_stage"),
                "detected_strategy":  _bs_get(result, "strategy_engine", "active_strategy"),
                "trigger_status":     result.get("alert_level"),
                "missing_conditions": result.get("strict_missing"),
                "invalidation":       result.get("stage_invalidation"),
                "target_liquidity":   _bs_get(result, "main_brain", "liquidity_focus", "target"),
                "entry_quality":      _eq_str,
                "entry_quality_score": _eq.get("score") if _eq.get("available") else None,
                "chase_risk":         _bs_get(result, "entry_quality", "chasing_warning"),
            },
            "learning": {
                "similar_samples":        _bs_get(result, "trade_memory",             "sample_count"),
                "expectancy":             _bs_get(result, "main_brain_learning_stats", "expectancy"),
                "win_rate":               _bs_get(result, "main_brain_learning_stats", "win_rate"),
                "average_r":              _bs_get(result, "main_brain_learning_stats", "avg_r"),
                "common_failure":         _bs_get(result, "main_brain_learning_stats", "top_failure"),
                "active_learning_rules":  _elig_status,
                "blocked_rules":          _elig_reason,
                "validated_findings":     _bs_get(result, "scalp_strategy_advisory",   "consensus"),
                "confidence_adjustment":  _bs_get(result, "confidence_governor",        "confidence_adjustment"),
                "sample_quality":         _bs_get(result, "confidence_governor",        "sample_quality"),
            },
            "execution": {
                "live_eligibility":  _elig_status == "LIVE_ELIGIBLE",
                "ghost_eligibility": _elig_status == "GHOST_ONLY",
                "armed_status":      AUTO_TRADE.get(inst, False),
                "broker_status":     resolve_execution_mode(),
                "open_position":     _pos,
                "trade_plan":        _plan,
                "management_recommendation": _bs_get(result, "active_trade_thinking", "recommendation"),
            },
            "safety": {
                "risk_status":     result.get("risk_label"),
                "prop_status":     _prop_str,
                "daily_loss_room": None,
                "blocker":         result.get("strict_reason"),
                "veto_source":     _veto_srcs or None,
            },
            "decision": {
                "brain_state":          _bs_get(result, "main_brain", "status"),
                "verdict":              result.get("verdict"),
                "is_actionable":        result.get("is_actionable", False),
                "confidence":           _bs_get(result, "unified", "confidence"),
                "edge_score":           result.get("edge_score"),
                "plain_english_reason": (_bs_get(result, "unified", "narrative") or result.get("strict_reason")),
                "next_requirement":     result.get("stage_next_step"),
                "invalidation":         result.get("stage_invalidation"),
                "recommended_action":   _bs_get(result, "unified", "recommendation"),
            },
            "recent_events": _events,
        }
    except Exception as _bse:
        return {"available": False, "reason": str(_bse)}


# ── Decision Pipeline V2 (2026-07-17) ────────────────────────────────────────
# Shadow-mode 5-stage decision architecture: OBSERVE → INTERPRET → PRIORITIZE
# → VALIDATE → DECIDE. Runs at the single full_analysis return seam AFTER the
# production system has produced its final verdict. Builds its own verdict
# independently from raw signal stores, then compares with live for diagnostic
# interest. DISPLAY-ONLY; never mutates global state, never calls full_analysis
# recursively. Flag OFF → returns None → key not attached → goldens byte-identical.
# All CAN_* flags default False; money-path influence is future-proofing only.
#
# Stage contracts:
#   OBSERVE    → raw snapshot from global stores (no signal interpretation)
#   INTERPRET  → bias + alignment from observations (no gate logic)
#   PRIORITIZE → ranked, weighted signal list (no verdict)
#   VALIDATE   → per-gate PASS/FAIL/INSUFFICIENT (no combining)
#   DECIDE     → pipeline verdict + comparison against live system

# ── Decision Pipeline V2: Infrastructure (Phase 1B) ─────────────────────────
_DPV2_AGREEMENT_HISTORY = deque(maxlen=200)   # bounded, GIL-safe for reads
_DPV2_SHADOW_TRADES     = {}                  # instrument -> shadow-trade dict
_DPV2_AGREEMENT_LOCK    = threading.Lock()
DPV2_DB_READY           = False               # boot probe (INSERT/SELECT only; no DDL)


def _dpv2_store_agreement_record(record):
    """Thread-safe append to the bounded agreement-history deque."""
    try:
        with _DPV2_AGREEMENT_LOCK:
            _DPV2_AGREEMENT_HISTORY.appendleft(record)
    except Exception:
        pass


def _dpv2_compute_better_decision(record):
    """Given a completed outcome record, determine which system was more correct.

    Returns (better_decision, reason) where better_decision is one of:
    PRODUCTION / V2 / BOTH / NEITHER / INCONCLUSIVE
    """
    prod_ok   = is_actionable(record.get("production_verdict") or "WAIT")
    v2_ok     = (record.get("shadow_verdict") == "READY")
    outcome   = record.get("final_outcome")

    if not outcome:
        return "INCONCLUSIVE", "No outcome data yet"

    WIN_OUTCOMES  = {"TARGET_REACHED", "TP1_REACHED", "PARTIAL_WIN"}
    LOSS_OUTCOMES = {"STOPPED_OUT", "STOPPED"}

    if prod_ok and v2_ok:
        if outcome in WIN_OUTCOMES:   return "BOTH",    "Both approved — trade won"
        if outcome in LOSS_OUTCOMES:  return "NEITHER", "Both approved — trade lost"
        return "INCONCLUSIVE", "Both approved — outcome unclear"

    if prod_ok and not v2_ok:
        if outcome in WIN_OUTCOMES:  return "PRODUCTION", "Production captured a winner V2 skipped"
        if outcome in LOSS_OUTCOMES: return "V2",         "V2 avoided a losing trade"
        return "INCONCLUSIVE", "Outcome unclear"

    if not prod_ok and v2_ok:
        if outcome in WIN_OUTCOMES:  return "V2",         "V2 correctly identified a missed winner"
        if outcome in LOSS_OUTCOMES: return "PRODUCTION", "Production correctly avoided a losing trade"
        return "INCONCLUSIVE", "Outcome unclear"

    # Both waited
    return "INCONCLUSIVE", "Both waited — no comparable outcome"


def _dpv2_compute_scorecard():
    """Aggregate agreement history into a read-only scorecard. Fail-open."""
    try:
        records = list(_DPV2_AGREEMENT_HISTORY)   # GIL-safe snapshot
        total   = len(records)
        if total == 0:
            return {"total_evaluations": 0, "message": "No evaluations yet",
                    "shadow_mode_note": "SHADOW MODE — NO LIVE AUTHORITY"}

        agrees   = sum(1 for r in records if r.get("agreement_status") == "AGREE")
        disagrees = total - agrees
        prod_wins = sum(1 for r in records if r.get("better_decision") == "PRODUCTION")
        v2_wins   = sum(1 for r in records if r.get("better_decision") == "V2")
        both_ok   = sum(1 for r in records if r.get("better_decision") == "BOTH")
        neither   = sum(1 for r in records if r.get("better_decision") == "NEITHER")
        inconc    = sum(1 for r in records
                        if r.get("better_decision") in (None, "INCONCLUSIVE"))
        prod_app_v2_wait = sum(1 for r in records
                               if r.get("agreement_status") == "PRODUCTION_APPROVED_V2_WAITED")
        v2_app_prod_wait = sum(1 for r in records
                               if r.get("agreement_status") == "PRODUCTION_WAITED_V2_APPROVED")
        avoided_loss  = sum(1 for r in records
                            if r.get("better_decision") == "V2"
                            and r.get("final_outcome") in ("STOPPED_OUT", "STOPPED"))
        missed_winner = sum(1 for r in records
                            if r.get("better_decision") == "PRODUCTION"
                            and r.get("final_outcome") in ("TARGET_REACHED", "TP1_REACHED"))

        mfes = [r["mfe_pts"] for r in records if r.get("mfe_pts") is not None]
        maes = [r["mae_pts"] for r in records if r.get("mae_pts") is not None]

        def _group(key):
            out = {}
            for r in records:
                k = r.get(key) or "UNKNOWN"
                out.setdefault(k, {"total": 0, "agree": 0,
                                   "prod_wins": 0, "v2_wins": 0})
                out[k]["total"] += 1
                if r.get("agreement_status") == "AGREE":
                    out[k]["agree"] += 1
                if r.get("better_decision") == "PRODUCTION":
                    out[k]["prod_wins"] += 1
                if r.get("better_decision") == "V2":
                    out[k]["v2_wins"] += 1
            return out

        # Minimum thresholds (display-only; do NOT auto-enable anything)
        scalp_ct = sum(1 for r in records if r.get("mode") == "SCALP")
        swing_ct = sum(1 for r in records if r.get("mode") == "SWING")
        meets_min = (total >= 100 and disagrees >= 30
                     and scalp_ct >= 20 and swing_ct >= 20)

        return {
            "total_evaluations":             total,
            "agreement_rate_pct":            round(agrees / total * 100, 1),
            "disagree_count":                disagrees,
            "production_wins":               prod_wins,
            "v2_wins":                       v2_wins,
            "both_correct":                  both_ok,
            "neither_correct":               neither,
            "inconclusive":                  inconc,
            "production_approved_v2_waited": prod_app_v2_wait,
            "v2_approved_production_waited": v2_app_prod_wait,
            "avoided_loss_count":            avoided_loss,
            "missed_winner_count":           missed_winner,
            "avg_mfe_pts":    round(sum(mfes)/len(mfes), 2) if mfes else None,
            "avg_mae_pts":    round(sum(maes)/len(maes), 2) if maes else None,
            "by_symbol":      _group("symbol"),
            "by_mode":        _group("mode"),
            "by_regime":      _group("regime"),
            "by_driver":      _group("primary_driver"),
            "meets_minimum_thresholds": meets_min,
            "shadow_mode_note": "SHADOW MODE — NO LIVE AUTHORITY",
        }
    except Exception as _e:
        return {"available": False, "error": str(_e),
                "shadow_mode_note": "SHADOW MODE — NO LIVE AUTHORITY"}


# ── Decision Pipeline V2: Stage Functions (Phase 1B) ────────────────────────

# ─ Regime / driver / instrument-type constants ────────────────────────────────
_DPV2_REGIME_VALUES      = {"RISK_ON", "RISK_OFF", "NEUTRAL", "MIXED", "UNKNOWN"}
_DPV2_DRIVER_VALUES      = {
    "GEOPOLITICAL", "FED_POLICY", "INFLATION", "EMPLOYMENT", "ECONOMIC_GROWTH",
    "EARNINGS", "ENERGY", "LIQUIDITY", "TECHNICAL", "MULTIPLE", "NONE", "UNKNOWN",
}
