_DPV2_EQUITY_TECH_INSTS  = {"MNQ", "NQ"}
_DPV2_EQUITY_BROAD_INSTS = {"MES", "ES", "MYM", "YM"}

_DPV2_PREF_MATRIX = {
    ("RISK_OFF", "SAFE_HAVEN"):     ("STRONGLY_FAVORED",    "BULLISH"),
    ("RISK_OFF", "EQUITY_TECH"):    ("STRONGLY_DISFAVORED", "BEARISH"),
    ("RISK_OFF", "EQUITY_BROAD"):   ("DISFAVORED",          "BEARISH"),
    ("RISK_ON",  "SAFE_HAVEN"):     ("DISFAVORED",          "BEARISH"),
    ("RISK_ON",  "EQUITY_TECH"):    ("STRONGLY_FAVORED",    "BULLISH"),
    ("RISK_ON",  "EQUITY_BROAD"):   ("FAVORED",             "BULLISH"),
    ("NEUTRAL",  "SAFE_HAVEN"):     ("NEUTRAL",             "NEUTRAL"),
    ("NEUTRAL",  "EQUITY_TECH"):    ("NEUTRAL",             "NEUTRAL"),
    ("NEUTRAL",  "EQUITY_BROAD"):   ("NEUTRAL",             "NEUTRAL"),
    ("MIXED",    "SAFE_HAVEN"):     ("NEUTRAL",             "NEUTRAL"),
    ("MIXED",    "EQUITY_TECH"):    ("NEUTRAL",             "NEUTRAL"),
    ("MIXED",    "EQUITY_BROAD"):   ("NEUTRAL",             "NEUTRAL"),
    ("UNKNOWN",  "SAFE_HAVEN"):     ("INSUFFICIENT_DATA",   "UNKNOWN"),
    ("UNKNOWN",  "EQUITY_TECH"):    ("INSUFFICIENT_DATA",   "UNKNOWN"),
    ("UNKNOWN",  "EQUITY_BROAD"):   ("INSUFFICIENT_DATA",   "UNKNOWN"),
}
_DPV2_PREF_ORDER = {
    "STRONGLY_FAVORED": 0, "FAVORED": 1, "NEUTRAL": 2,
    "DISFAVORED": 3, "STRONGLY_DISFAVORED": 4, "INSUFFICIENT_DATA": 5,
}
_DPV2_KNOWN_INSTRUMENTS = ["MGC", "MNQ", "MES", "MYM"]


def _dpv2_inst_type(inst):
    u = (inst or "").upper()
    if u in _DPV2_SAFE_HAVEN_INSTS:    return "SAFE_HAVEN"
    if u in _DPV2_EQUITY_TECH_INSTS:   return "EQUITY_TECH"
    if u in _DPV2_EQUITY_BROAD_INSTS:  return "EQUITY_BROAD"
    return "UNKNOWN"


def _dpv2_stage_observe(instrument):
    """Stage 1 — What facts are currently available?

    Collects price, VWAP, CVD, volume, ATR, market structure, prior-day levels,
    recent alerts, existing news/sector data, account state, position state,
    prop-rule state, and data freshness.

    Does NOT classify the market, create a directional bias, rank markets,
    or produce a trade verdict. Read-only, fail-open.
    """
    _now = now_utc()
    _STRUCT_TYPES = {"BOS", "CHOCH", "HH", "HL", "LH", "LL"}
    _SWEEP_TYPES  = {"LIQUIDITY_SWEEP", "SWEEP", "SWEEP_HIGH", "SWEEP_LOW",
                     "SWEEP_LONG", "SWEEP_SHORT"}

    # Price
    auto_rec  = AUTO_PRICE_BY_TICKER.get(instrument) or {}
    price     = auto_rec.get("value")
    price_ts  = auto_rec.get("ts")
    price_age = None
    if price_ts:
        try: price_age = (_now - datetime.fromisoformat(price_ts)).total_seconds()
        except Exception: pass

    # VWAP
    vwap_rec   = VWAP_BY_TICKER.get(instrument) or {}
    vwap_value = vwap_rec.get("value")
    vwap_ts    = vwap_rec.get("ts")
    vwap_age   = None
    if vwap_ts:
        try: vwap_age = (_now - datetime.fromisoformat(vwap_ts)).total_seconds()
        except Exception: pass
    price_above_vwap = None
    if price is not None and vwap_value is not None:
        try: price_above_vwap = float(price) > float(vwap_value)
        except Exception: pass

    # CVD
    cvd_rec   = CVD_BY_TICKER.get(instrument) or {}
    cvd_state = cvd_rec.get("state")
    cvd_ts    = cvd_rec.get("ts")
    cvd_age   = None
    if cvd_ts:
        try: cvd_age = (_now - datetime.fromisoformat(cvd_ts)).total_seconds()
        except Exception: pass

    # RVOL
    rvol_rec   = RVOL_BY_TICKER.get(instrument) or {}
    rvol_value = rvol_rec.get("value")

    # Volume spike
    vol_rec         = VOLUME_SPIKE_BY_TICKER.get(instrument) or {}
    vol_spike_ts    = vol_rec.get("ts")
    vol_spike_age   = None
    vol_spike_fresh = False
    if vol_spike_ts:
        try:
            vol_spike_age   = (_now - datetime.fromisoformat(vol_spike_ts)).total_seconds()
            vol_spike_fresh = vol_spike_age <= float(cfg("VOLUME_SPIKE_TTL_MIN")) * 60
        except Exception: pass

    # ATR / Volatility
    vol_state = VOLATILITY_BY_TICKER.get(instrument) or {}
    atr_pts   = vol_state.get("atr_pts")
    vol_ratio = vol_state.get("ratio")

    # Structure + sweep alerts (last 30 min, per-instrument)
    horizon_s         = 30 * 60
    structure_signals = []
    sweep_signals     = []
    for _ah in list(ALERT_HISTORY):    # list() for GIL-safe snapshot
        try:
            a_inst = (_ah.get("instrument") or
                      instrument_of(_ah.get("ticker") or ""))
            if a_inst != instrument: continue
            a_type = (_ah.get("alert_type") or "").upper()
            a_ts   = _ah.get("ts") or _ah.get("timestamp")
            a_age  = None
            if a_ts:
                try: a_age = (_now - datetime.fromisoformat(a_ts)).total_seconds()
                except Exception: pass
            if a_age is not None and a_age > horizon_s: continue
            direction = (_ah.get("direction") or "").upper()
            if any(s in a_type for s in _STRUCT_TYPES):
                structure_signals.append({
                    "type":      a_type,
                    "direction": direction,
                    "age_s":     round(a_age, 1) if a_age is not None else None,
                })
            elif any(s in a_type for s in _SWEEP_TYPES):
                sweep_signals.append({
                    "type":      a_type,
                    "direction": direction,
                    "age_s":     round(a_age, 1) if a_age is not None else None,
                })
        except Exception: pass

    structure_signals.sort(key=lambda x: x.get("age_s") or 9999)
    sweep_signals.sort(key=lambda x:     x.get("age_s") or 9999)

    # Active position state (lock-free read; display-only)
    has_position = False
    active_trade = None
    try:
        _at = ACTIVE_TRADES_BY_INST.get(instrument)
        if _at:
            has_position = True
            active_trade = {"direction": _at.get("direction"),
                            "opened_at": _at.get("opened_at")}
    except Exception: pass

    # Market session
    market_open = None
    try:
        sess = market_session_status()
        market_open = sess.get("open", False)
    except Exception: pass

    # Daily loss cap
    daily_loss_cap = None
    try: daily_loss_cap = max_daily_loss(instrument)
    except Exception: pass

    # Market Environment snapshot (read-only; never recomputed here)
    me_snapshot = None
    try:
        with _ME_LOCK:
            me_snapshot = _ME_LAST_SNAPSHOT
    except Exception: pass

    data_coverage = sum([
        price is not None,
        vwap_value is not None,
        cvd_state is not None,
        bool(structure_signals),
    ]) / 4.0

    return {
        "status":              "OK",
        "instrument":          instrument,
        "price":               price,
        "price_age_s":         round(price_age, 1) if price_age is not None else None,
        "vwap_value":          vwap_value,
        "vwap_age_s":          round(vwap_age, 1) if vwap_age is not None else None,
        "price_above_vwap":    price_above_vwap,
        "cvd_state":           cvd_state,
        "cvd_age_s":           round(cvd_age, 1) if cvd_age is not None else None,
        "rvol_value":          rvol_value,
        "vol_spike_fresh":     vol_spike_fresh,
        "vol_spike_age_s":     round(vol_spike_age, 1) if vol_spike_age is not None else None,
        "atr_pts":             atr_pts,
        "vol_ratio":           vol_ratio,
        "structure_signals":   structure_signals[:5],
        "sweep_signals":       sweep_signals[:3],
        "has_position":        has_position,
        "active_trade":        active_trade,
        "market_open":         market_open,
        "daily_loss_cap":      daily_loss_cap,
        "market_env_snapshot": me_snapshot,
        "data_coverage":       round(data_coverage, 2),
    }


def _dpv2_stage_interpret(obs):
    """Stage 2 — What type of market environment is present, and what drives it?

    MUST NOT output LONG, SHORT, BUY, SELL, APPROVE, REJECT, or trade direction.
    Regime = WHAT the market is doing (RISK_ON / RISK_OFF / NEUTRAL / MIXED / UNKNOWN).
    Driver = WHY it is doing it (GEOPOLITICAL / TECHNICAL / etc.).
    These are INDEPENDENT fields. Directional context belongs in Stage 3 PRIORITIZE.
    """
    instrument = obs.get("instrument", "")

    # Use authoritative MktEnv snapshot if available and valid
    me = obs.get("market_env_snapshot") or {}
    me_regime = me.get("regime") if isinstance(me, dict) else None
    if me_regime and me_regime in _DPV2_REGIME_VALUES and me_regime != "UNKNOWN":
        dq    = me.get("data_quality") or {}
        level = dq.get("level", "UNKNOWN") if isinstance(dq, dict) else str(dq)
        drv   = me.get("primary_driver") or "UNKNOWN"
        if drv not in _DPV2_DRIVER_VALUES: drv = "UNKNOWN"
        sec   = me.get("secondary_theme") or ""
        sec_drivers = [sec] if sec and sec not in ("NONE", "UNKNOWN", "") else []
        return {
            "status":               "OK",
            "source":               "market_environment",
            "regime":               me_regime,
            "regime_confidence":    me.get("confidence", 50),
            "primary_driver":       drv,
            "secondary_drivers":    sec_drivers,
            "risk_state":           me.get("risk_state", "UNKNOWN"),
            "dominant_theme":       me.get("dominant_theme", "UNKNOWN"),
            "supporting_evidence":  me.get("supporting_evidence") or [],
            "conflicting_evidence": me.get("conflicting_evidence") or [],
            "data_quality":         level,
        }

    # Derive regime from instrument-specific signals (no MktEnv available)
    pav      = obs.get("price_above_vwap")
    cvd      = obs.get("cvd_state")
    structs  = obs.get("structure_signals") or []
    coverage = obs.get("data_coverage", 0)

    inst_type = _dpv2_inst_type(instrument)

    bullish_ev = []
    bearish_ev = []
    if pav is True:       bullish_ev.append("price_above_vwap")
    elif pav is False:    bearish_ev.append("price_below_vwap")
    if cvd == "bullish":  bullish_ev.append("cvd_bullish")
    elif cvd == "bearish":bearish_ev.append("cvd_bearish")
    for s in structs[:2]:
        d = (s.get("direction") or "").upper()
        t = (s.get("type") or "").upper()
        bull = (d in ("LONG", "BULLISH", "DEMAND") or t in ("HH", "HL")
                or any(k in t for k in ("BULL", "_UP", "DEMAND")))
        bear = (d in ("SHORT", "BEARISH", "SUPPLY") or t in ("LH", "LL")
                or any(k in t for k in ("BEAR", "_DOWN", "SUPPLY")))
        if bull and not bear:  bullish_ev.append("struct_" + t)
        elif bear and not bull:bearish_ev.append("struct_" + t)

    n_bull = len(bullish_ev)
    n_bear = len(bearish_ev)

    if inst_type == "UNKNOWN" or coverage < 0.25:
        regime = "UNKNOWN"; regime_confidence = 0; risk_state = "UNKNOWN"
        dominant_theme = "UNKNOWN"; primary_driver = "UNKNOWN"
        supporting_ev = []; conflicting_ev = []
        data_quality = "INSUFFICIENT"
    elif n_bull >= 2 and n_bear == 0:
        if inst_type == "SAFE_HAVEN":
            regime = "RISK_OFF"; risk_state = "DEFENSIVE"
            dominant_theme = "SAFE_HAVEN_DEMAND"
        elif inst_type == "EQUITY_TECH":
            regime = "RISK_ON"; risk_state = "AGGRESSIVE"
            dominant_theme = "TECHNOLOGY_STRENGTH"
        else:
            regime = "RISK_ON"; risk_state = "AGGRESSIVE"
            dominant_theme = "BROAD_MARKET_STRENGTH"
        regime_confidence = min(40 + n_bull * 12, 72); primary_driver = "TECHNICAL"
        supporting_ev = bullish_ev; conflicting_ev = []
        data_quality = "MODERATE" if coverage >= 0.5 else "LOW"
    elif n_bear >= 2 and n_bull == 0:
        if inst_type == "SAFE_HAVEN":
            regime = "RISK_ON"; risk_state = "AGGRESSIVE"
            dominant_theme = "BROAD_MARKET_STRENGTH"
        else:
            regime = "RISK_OFF"; risk_state = "DEFENSIVE"
            dominant_theme = "RISK_AVERSION"
        regime_confidence = min(35 + n_bear * 10, 68); primary_driver = "TECHNICAL"
        supporting_ev = bearish_ev; conflicting_ev = []
        data_quality = "MODERATE" if coverage >= 0.5 else "LOW"
    elif n_bull > 0 and n_bear > 0:
        regime = "MIXED"; risk_state = "BALANCED"; dominant_theme = "MIXED"
        regime_confidence = 20; primary_driver = "TECHNICAL"
        supporting_ev = bullish_ev; conflicting_ev = bearish_ev
        data_quality = "LOW"
    else:
        regime = "NEUTRAL"; risk_state = "BALANCED"; dominant_theme = "NEUTRAL"
        regime_confidence = 25; primary_driver = "NONE"
        supporting_ev = []; conflicting_ev = []
        data_quality = "LOW" if coverage >= 0.25 else "INSUFFICIENT"

    return {
        "status":               "OK",
        "source":               "instrument_derived",
        "regime":               regime,
        "regime_confidence":    regime_confidence,
        "primary_driver":       primary_driver,
        "secondary_drivers":    [],
        "risk_state":           risk_state,
        "dominant_theme":       dominant_theme,
        "supporting_evidence":  supporting_ev,
        "conflicting_evidence": conflicting_ev,
        "data_quality":         data_quality,
    }


def _dpv2_stage_prioritize(obs, interp, mode):
    """Stage 3 — Which traded markets deserve the most attention in this environment?

    Ranks supported instruments (MGC, MNQ, MES, MYM) by regime-contextual preference
    and may assign directional_context per instrument.
    MUST NOT create a trade or route orders.
    Priority is NOT a trade command. A disfavored market may still contain a valid setup.
    """
    regime     = interp.get("regime", "UNKNOWN")
    driver     = interp.get("primary_driver", "UNKNOWN")
    focus_inst = obs.get("instrument", "")

    ranked = []
    for inst in _DPV2_KNOWN_INSTRUMENTS:
        itype        = _dpv2_inst_type(inst)
        pref, dir_ctx = _DPV2_PREF_MATRIX.get(
            (regime, itype), ("INSUFFICIENT_DATA", "UNKNOWN"))

        reasons   = []
        conflicts = []
        if regime != "UNKNOWN":
            reasons.append("%s regime" % regime.replace("_", "-"))
        if driver not in ("UNKNOWN", "NONE"):
            reasons.append("%s driver" % driver.replace("_", " ").title())
        if itype == "SAFE_HAVEN" and regime == "RISK_OFF":
            reasons.append("Safe-haven demand benefits gold")
        if itype.startswith("EQUITY") and regime == "RISK_ON":
            reasons.append("Risk-on supports equities")

        ctx_conf = int(interp.get("regime_confidence", 0) * 0.8)
        if inst == focus_inst:
            pav = obs.get("price_above_vwap")
            cvd = obs.get("cvd_state")
            if pav is True:         reasons.append("Price above VWAP")
            elif pav is False:      conflicts.append("Price below VWAP")
            if cvd == "bullish":    reasons.append("CVD bullish")
            elif cvd == "bearish":  conflicts.append("CVD bearish")
            ctx_conf = min(ctx_conf + 15, 90)

        ranked.append({
            "symbol":              inst,
            "priority":            0,
            "preference":          pref,
            "directional_context": dir_ctx,
            "context_confidence":  ctx_conf,
            "reasons":             reasons,
            "conflicts":           conflicts,
            "is_focus":            (inst == focus_inst),
        })

    ranked.sort(key=lambda x: (
        _DPV2_PREF_ORDER.get(x["preference"], 5),
        0 if x["is_focus"] else 1,
    ))
    for i, r in enumerate(ranked):
        r["priority"] = i + 1

    focus_entry  = next((r for r in ranked if r["is_focus"]), ranked[0] if ranked else {})
    focus_pref   = focus_entry.get("preference", "INSUFFICIENT_DATA")
    focus_dir_ctx = focus_entry.get("directional_context", "UNKNOWN")

    return {
        "status":              "OK",
        "ranked_instruments":  ranked,
        "focus_instrument":    focus_inst,
        "focus_preference":    focus_pref,
        "focus_direction_ctx": focus_dir_ctx,
        "regime_used":         regime,
        "driver_used":         driver,
        "mode_used":           mode,
    }


def _dpv2_stage_validate(obs, interp, prio, instrument, mode):
    """Stage 4 — Does a technical setup exist, and does it pass all safety rules?

    Reuses existing production-equivalent signal logic. Does NOT duplicate or
    rewrite existing strategy code — it reads from the same signal stores.
    Produces technical_validation with passed_checks / failed_checks /
    risk_checks / account_checks / production_verdict.
    First stage where setup direction is technically validated.
    """
    focus_dir     = prio.get("focus_direction_ctx", "UNKNOWN")
    regime_conf   = interp.get("regime_confidence", 0)
    passed_checks = []
    failed_checks = []
    risk_checks   = {}
    acct_checks   = {}

    # Structure gate
    structs = obs.get("structure_signals") or []
    fresh_s = [s for s in structs if (s.get("age_s") or 9999) <= 20 * 60]
    if fresh_s:
        passed_checks.append("Fresh structure: %s %ds ago"
                             % (fresh_s[0]["type"], int(fresh_s[0].get("age_s") or 0)))
    elif structs:
        failed_checks.append("Structure stale (%ds)" % int(structs[0].get("age_s") or 0))
    else:
        failed_checks.append("No structure signal in last 30 min")

    # VWAP alignment
    pav      = obs.get("price_above_vwap")
    vwap_age = obs.get("vwap_age_s")
    if obs.get("vwap_value") is None:
        failed_checks.append("VWAP unavailable")
    elif vwap_age is not None and vwap_age > 3600:
        failed_checks.append("VWAP stale (%ds)" % int(vwap_age))
    elif focus_dir == "BULLISH" and pav is True:
        passed_checks.append("Price above VWAP — bullish aligned")
    elif focus_dir == "BEARISH" and pav is False:
        passed_checks.append("Price below VWAP — bearish aligned")
    elif focus_dir in ("NEUTRAL", "UNKNOWN"):
        passed_checks.append("VWAP present — neutral context")
    else:
        failed_checks.append("Price on wrong VWAP side for %s context" % focus_dir)

    # CVD alignment (fail-open when unknown or stale)
    cvd     = obs.get("cvd_state")
    cvd_age = obs.get("cvd_age_s")
    if cvd is None or (cvd_age is not None and cvd_age > 3600):
        passed_checks.append("CVD unknown — fail-open")
    elif focus_dir == "BULLISH" and cvd == "bullish":
        passed_checks.append("CVD bullish — aligned")
    elif focus_dir == "BEARISH" and cvd == "bearish":
        passed_checks.append("CVD bearish — aligned")
    elif focus_dir == "BULLISH" and cvd == "bearish":
        failed_checks.append("CVD bearish opposes bullish context")
    elif focus_dir == "BEARISH" and cvd == "bullish":
        failed_checks.append("CVD bullish opposes bearish context")
    else:
        passed_checks.append("CVD %s — neutral context" % cvd)

    # Regime confidence
    if regime_conf >= 60:
        passed_checks.append("Regime confidence %d%% — strong" % regime_conf)
    elif regime_conf >= 35:
        passed_checks.append("Regime confidence %d%% — moderate" % regime_conf)
    elif regime_conf == 0:
        failed_checks.append("Insufficient regime data")
    else:
        failed_checks.append("Regime confidence %d%% — weak" % regime_conf)

    # Directional conflict
    focus_entry  = next((r for r in (prio.get("ranked_instruments") or [])
                         if r.get("is_focus")), {})
    conflicts_ct = len(focus_entry.get("conflicts") or [])
    if conflicts_ct == 0:
        passed_checks.append("No directional conflicts")
    else:
        failed_checks.append("%d conflict(s): %s"
                             % (conflicts_ct, focus_entry.get("conflicts")))

    # Risk checks
    atr_pts   = obs.get("atr_pts")
    vol_ratio = obs.get("vol_ratio")
    risk_checks["atr_available"] = atr_pts is not None
    if atr_pts is not None: risk_checks["atr_pts"] = float(atr_pts)
    if vol_ratio is not None:
        r_f = float(vol_ratio)
        risk_checks["vol_ratio"]    = round(r_f, 2)
        risk_checks["vol_elevated"] = r_f > 2.0
        if r_f > 3.0:
            failed_checks.append("Extreme volatility ratio %.1f" % r_f)
    else:
        risk_checks["vol_ratio"] = None

    # Account / session checks
    acct_checks["daily_loss_cap"] = obs.get("daily_loss_cap")
    acct_checks["market_open"]    = obs.get("market_open")
    acct_checks["has_position"]   = obs.get("has_position", False)
    if obs.get("market_open") is False:
        failed_checks.append("Market closed")
    if obs.get("has_position"):
        failed_checks.append("Instrument already has an open position")

    n_pass = len(passed_checks)
    n_fail = len(failed_checks)
    pass_rate = round(n_pass / max(n_pass + n_fail, 1) * 100)

    # Technical status
    critical = [c for c in failed_checks if any(
        k in c for k in ("No structure", "stale", "opposes",
                         "closed", "open position", "unavailable"))]
    if n_fail == 0 and n_pass >= 3:
        technical_status = "READY"
    elif critical:
        technical_status = "WAIT"
    elif n_fail <= 1 and n_pass >= 3:
        technical_status = "READY"
    else:
        technical_status = "WAIT"

    technical_confidence = round(pass_rate * 0.65 + regime_conf * 0.35)

    return {
        "status":               "OK",
        "symbol":               instrument,
        "strategy":             "DECISION_PIPELINE_V2",
        "technical_status":     technical_status,
        "technical_confidence": technical_confidence,
        "passed_checks":        passed_checks,
        "failed_checks":        failed_checks,
        "risk_checks":          risk_checks,
        "account_checks":       acct_checks,
        "pass_rate":            pass_rate,
    }


def _dpv2_stage_decide(obs, interp, prio, validate,
                        live_verdict, live_direction, instrument):
    """Stage 5 — Given environment, priority, technical setup, and risk, what is
    the final shadow conclusion?

    Assembles decision_pipeline_v2_result with a full plain-language explanation.
    Computes agreement_status using the extended 9-value enum.
    NEVER changes production behavior. shadow_mode is always True.
    """
    regime      = interp.get("regime", "UNKNOWN")
    driver      = interp.get("primary_driver", "UNKNOWN")
    regime_conf = interp.get("regime_confidence", 0)
    tech_status = validate.get("technical_status", "WAIT")
    tech_conf   = validate.get("technical_confidence", 0)
    focus_pref  = prio.get("focus_preference", "INSUFFICIENT_DATA")
    dir_ctx     = prio.get("focus_direction_ctx", "UNKNOWN")
    passed      = validate.get("passed_checks") or []
    failed      = validate.get("failed_checks") or []

    # Pipeline verdict
    if focus_pref == "INSUFFICIENT_DATA" or regime == "UNKNOWN":
        pipeline_verdict   = "INSUFFICIENT_DATA"
        pipeline_direction = None
        reasoning = ["Insufficient environmental data (regime: %s, pref: %s)"
                     % (regime, focus_pref)]
    elif tech_status == "READY":
        pipeline_verdict   = "READY"
        pipeline_direction = ("LONG"  if dir_ctx == "BULLISH" else
                               "SHORT" if dir_ctx == "BEARISH" else None)
        reasoning = [
            "Technical confirmed (%d passed, %d failed)" % (len(passed), len(failed)),
            "Regime: %s, focus: %s" % (regime, focus_pref),
        ]
    else:
        pipeline_verdict   = "WAIT"
        pipeline_direction = None
        reasoning = [
            "Gate failed: %s" % (failed[:2] if failed else ["unknown"]),
            "Regime: %s (conf %d%%)" % (regime, regime_conf),
        ]

    pipeline_confidence = round(tech_conf * 0.6 + regime_conf * 0.4)
    live_is_ready       = is_actionable(live_verdict or "WAIT")
    pipeline_is_ready   = (pipeline_verdict == "READY")

    # Extended agreement_status enum
    if live_is_ready and pipeline_is_ready:
        agreement_status = "AGREE"
    elif not live_is_ready and not pipeline_is_ready:
        agreement_status = "AGREE"
    elif live_is_ready and not pipeline_is_ready:
        if (live_direction or "").upper() == "LONG":
            agreement_status = "PRODUCTION_MORE_BULLISH"
        elif (live_direction or "").upper() == "SHORT":
            agreement_status = "PRODUCTION_MORE_BEARISH"
        else:
            agreement_status = "PRODUCTION_APPROVED_V2_WAITED"
    elif not live_is_ready and pipeline_is_ready:
        if pipeline_direction == "LONG":
            agreement_status = "V2_MORE_BULLISH"
        elif pipeline_direction == "SHORT":
            agreement_status = "V2_MORE_BEARISH"
        else:
            agreement_status = "PRODUCTION_WAITED_V2_APPROVED"
    else:
        agreement_status = "INCOMPARABLE"

    agreement_bool    = live_is_ready == pipeline_is_ready
    divergence_reason = None
    if not agreement_bool:
        divergence_reason = (
            "Pipeline READY but live says %s" % live_verdict
            if pipeline_is_ready else
            "Pipeline WAIT but live says %s" % live_verdict
        )

    # Plain-language explanation block
    _regime_desc = {
        "RISK_ON":  "The market is in a risk-on environment.",
        "RISK_OFF": "The market is in a risk-off environment.",
        "NEUTRAL":  "The market appears neutral with no clear directional bias.",
        "MIXED":    "The market is showing mixed signals with no clear regime.",
        "UNKNOWN":  "Insufficient data to classify the current market environment.",
    }
    _driver_desc = {
        "GEOPOLITICAL":    "Geopolitical escalation appears to be the primary driver.",
        "FED_POLICY":      "Federal Reserve policy appears to be the primary driver.",
        "INFLATION":       "Inflation dynamics appear to be the primary driver.",
        "EMPLOYMENT":      "Labor market conditions appear to be the primary driver.",
        "ECONOMIC_GROWTH": "Economic growth expectations appear to be the primary driver.",
        "EARNINGS":        "Corporate earnings appear to be the primary driver.",
        "ENERGY":          "Energy market conditions appear to be the primary driver.",
        "LIQUIDITY":       "Liquidity conditions appear to be the primary driver.",
        "TECHNICAL":       "Technical factors and price action are the primary driver.",
        "MULTIPLE":        "Multiple macro drivers are in play simultaneously.",
        "NONE":            "No clear macro driver has been identified.",
        "UNKNOWN":         "The driver cannot be determined from available data.",
    }
    _rel_desc = {
        "SAFE_HAVEN":    "Gold is a classic safe-haven asset that benefits from risk-off conditions.",
        "EQUITY_TECH":   "Technology futures typically outperform in risk-on, underperform in risk-off.",
        "EQUITY_BROAD":  "Broad equity futures reflect overall market risk appetite.",
        "UNKNOWN":       "Instrument type unclassified; regime alignment is uncertain.",
    }
    itype = _dpv2_inst_type(instrument)
    what_is_happening  = _regime_desc.get(regime, "Market environment unknown.")
    why_it_is_happening = _driver_desc.get(driver, "Driver unknown.")
    why_relevant = _rel_desc.get(itype, "")
    if focus_pref not in ("INSUFFICIENT_DATA", "NEUTRAL"):
        why_relevant += " In this regime, %s is %s." % (
            instrument, focus_pref.lower().replace("_", " "))
    what_found = "Technical engine: %s." % tech_status
    if passed: what_found += " Confirmed: %s." % "; ".join(passed[:2])
    if failed: what_found += " Missing: %s." % "; ".join(failed[:2])
    if pipeline_verdict == "READY":
        what_next = ("Shadow verdict is READY for a %s setup. "
                     "Wait for production system to confirm." % (pipeline_direction or "directional"))
    elif pipeline_verdict == "WAIT" and failed:
        what_next = "Resolve: %s." % "; ".join(failed[:2])
    else:
        what_next = "Gather more data before evaluating a setup."
    pav = obs.get("price_above_vwap")
    what_invalidates = "Loss of %s structure" % dir_ctx.lower()
    if pav is not None:
        what_invalidates += " and a sustained move %s VWAP" % (
            "below" if dir_ctx == "BULLISH" else "above")
    if regime not in ("UNKNOWN", "NEUTRAL"):
        what_invalidates += "; regime shift from %s would also invalidate." % regime

    return {
        "status":              "OK",
        "symbol":              instrument,
        "market_regime":       regime,
        "primary_driver":      driver,
        "market_priority":     focus_pref,
        "directional_context": dir_ctx,
        "technical_verdict":   tech_status,
        "production_verdict":  live_verdict,
        "shadow_verdict":      pipeline_verdict,
        "agreement_status":    agreement_status,
        "changed_production_behavior": False,
        "explanation": {
            "what_is_happening":              what_is_happening,
            "why_it_is_happening":            why_it_is_happening,
            "why_this_market_is_relevant":    why_relevant,
            "what_the_technical_engine_found": what_found,
            "what_must_happen_next":          what_next,
            "what_invalidates_the_idea":      what_invalidates,
        },
        "shadow_mode":             True,
        # backward-compat fields (keep for existing JS consumers)
        "pipeline_verdict":        pipeline_verdict,
        "pipeline_direction":      pipeline_direction,
        "pipeline_confidence":     pipeline_confidence,
        "pipeline_reasoning":      reasoning,
        "agreement_with_live":     agreement_bool,
        "live_verdict":            live_verdict,
        "live_direction":          live_direction,
        "divergence_reason":       divergence_reason,
    }


def _dpv2_analyst_briefing(s1, s2, s3, s4, s5, instrument, mode):
    """Phase 2 — AI Analyst Layer: one concise market briefing from DPv2 stage outputs.

    Answers 8 questions in order:
      1. What is happening?        (regime narrative)
      2. Why is it happening?      (primary driver)
      3. Where is money flowing?   (leading/weak asset classes)
      4. Which market is strongest?(ranked instruments + top reason)
      5. Technical engine verdict? (production verdict — NEVER recomputed)
      6. What is preventing trade? (failed checks → blocking factors)
      7. What must happen next?    (from explain block)
      8. What would invalidate?    (from explain block)

    DISPLAY-ONLY. Consumes stage dicts only. Never calls full_analysis, never
    recomputes any signals, never produces trade commands. Fail-open.
    """
    try:
        regime       = (s2 or {}).get("regime",         "UNKNOWN") or "UNKNOWN"
        driver       = (s2 or {}).get("primary_driver","UNKNOWN") or "UNKNOWN"
        ranked       = (s3 or {}).get("ranked_instruments") or []
        passed       = (s4 or {}).get("passed_checks")   or []
        failed       = (s4 or {}).get("failed_checks")   or []
        expl         = (s5 or {}).get("explanation")     or {}
        live_verdict = (s5 or {}).get("production_verdict") or "WAIT"

        # ── 1 & 2. Regime + driver ────────────────────────────────────────────
        _REGIME_LABEL = {
            "RISK_ON":  "Risk On",
            "RISK_OFF": "Risk Off",
            "NEUTRAL":  "Neutral",
            "MIXED":    "Mixed",
            "UNKNOWN":  "Unknown",
        }
        _DRIVER_LABEL = {
            "GEOPOLITICAL":    "Geopolitical Escalation",
            "FED_POLICY":      "Federal Reserve Policy",
            "INFLATION":       "Inflation Concerns",
            "EMPLOYMENT":      "Labor Market Conditions",
            "ECONOMIC_GROWTH": "Economic Growth Expectations",
            "EARNINGS":        "Corporate Earnings",
            "ENERGY":          "Energy Market Conditions",
            "LIQUIDITY":       "Liquidity Conditions",
            "TECHNICAL":       "Technical Price Action",
            "MULTIPLE":        "Multiple Macro Drivers",
            "NONE":            "No Clear Macro Driver",
            "UNKNOWN":         "Undetermined",
        }
        regime_label = _REGIME_LABEL.get(regime, regime.replace("_", " ").title())
        driver_label = _DRIVER_LABEL.get(driver, driver.replace("_", " ").title())

        # ── 3. Money flow ─────────────────────────────────────────────────────
        _ASSET_CLASS = {
            "SAFE_HAVEN":    "Gold",
            "EQUITY_TECH":   "Technology",
            "EQUITY_BROAD":  "Broad Equity",
        }
        leading, weak = [], []
        for r in ranked:
            pref  = r.get("preference", "")
            sym   = r.get("symbol", "")
            itype = _dpv2_inst_type(sym)
            asset = _ASSET_CLASS.get(itype, sym)
            if pref in ("STRONGLY_FAVORED", "FAVORED"):
                if asset not in leading: leading.append(asset)
            elif pref in ("DISFAVORED", "STRONGLY_DISFAVORED"):
                if asset not in weak: weak.append(asset)
        if regime == "RISK_OFF":
            flow_narrative = "Safe-haven assets are absorbing capital." if leading else "Risk-off conditions with no clear leading asset."
        elif regime == "RISK_ON":
            flow_narrative = "Risk assets are attracting capital." if leading else "Risk-on conditions with no clear leading asset."
        else:
            flow_narrative = "No dominant capital flow direction identified."

        # ── 4. Highest priority market ────────────────────────────────────────
        top        = ranked[0] if ranked else {}
        top_symbol = top.get("symbol", instrument)
        top_prefs  = top.get("reasons") or []
        top_reason = top_prefs[0] if top_prefs else ("Highest priority for %s regime" % regime_label)
        market_ranking = [
            {"priority":     r["priority"],
             "symbol":       r["symbol"],
             "preference":   r.get("preference", "INSUFFICIENT_DATA"),
             "direction_ctx":r.get("directional_context", "UNKNOWN")}
            for r in ranked
        ]

        # ── 5. Technical verdict (production engine — never recomputed) ───────
        verdict_display = live_verdict or "WAIT"

        # ── 6. Blocking factors (from VALIDATE failed checks) ─────────────────
        blocking = [f for f in failed if f][:3]
        if not blocking and "WAIT" in (verdict_display or ""):
            blocking = ["Insufficient technical confirmation"]

        # ── 7. Next action ────────────────────────────────────────────────────
        next_action = expl.get("what_must_happen_next", "")
        if not next_action:
            next_action = ("Resolve: %s." % "; ".join(failed[:2])
                           if failed else "Monitor current conditions.")

        # ── 8. Invalidation ───────────────────────────────────────────────────
        invalidation = expl.get("what_invalidates_the_idea", "")
        if not invalidation:
            invalidation = "Loss of structure and sustained break of VWAP."

        # ── Plain-text briefing (display-ready) ───────────────────────────────
        _nl = "\n"
        parts = [
            "Market Environment",  regime_label,      _nl,
            "Primary Driver",      driver_label,      _nl,
            "Money Flow",
        ]
        parts.append("Leading: " + (", ".join(leading) if leading else "None"))
        parts.append("Weak: "    + (", ".join(weak)    if weak    else "None"))
        parts += [
            _nl,
            "Highest Priority Market", top_symbol,
            "Reason: " + top_reason,  _nl,
            "Technical Verdict",       verdict_display,
        ]
        if blocking:
            parts.append("Blocking: " + "; ".join(blocking))
        parts += [_nl, "Next Action", next_action, _nl, "Invalidation", invalidation]
        briefing_text = "\n".join(p for p in parts if p != _nl or True)

        # ── Narrative summary (assembled from existing briefing fields only) ─────
        # Max 90 words. Template-based, deterministic. No external calls.
        # narrative_summary_source: dpv2_existing_fields
        _ns_parts = []
        if regime_label and regime_label.lower() != "unknown":
            _ns_parts.append(
                "%s conditions are being driven by %s." % (regime_label, driver_label.lower())
            )
        else:
            _ns_parts.append("Market conditions are currently undetermined.")
        if leading and weak:
            _ns_ls = " and ".join(leading[:2])
            _ns_ws = " and ".join(weak[:2])
            _ns_lv = "are" if " and " in _ns_ls else "is"
            _ns_wv = "are" if " and " in _ns_ws else "is"
            _ns_parts.append(
                "%s %s showing the strongest relative flow "
                "while %s %s weak." % (_ns_ls, _ns_lv, _ns_ws.lower(), _ns_wv)
            )
        elif leading:
            _ns_ls = " and ".join(leading[:2])
            _ns_lv = "are" if " and " in _ns_ls else "is"
            _ns_parts.append("%s %s showing the strongest relative flow." % (_ns_ls, _ns_lv))
        else:
            _ns_parts.append("No dominant capital flow direction has been identified.")
        _ns_parts.append("%s is currently the highest-priority market." % top_symbol)
        _ns_generic_block = ["Insufficient technical confirmation"]
        if verdict_display in ("LONG READY", "SHORT READY"):
            _ns_parts.append("The production engine verdict is %s." % verdict_display)
        elif blocking and blocking != _ns_generic_block:
            _ns_block = blocking[0].lower().rstrip(".")
            _ns_parts.append(
                "The production engine verdict is %s because %s." % (verdict_display, _ns_block)
            )
        else:
            _ns_parts.append(
                "The production engine verdict is %s; "
                "technical confirmation is still pending." % verdict_display
            )
        _ns_na = next_action.rstrip(".")
        if _ns_na and _ns_na.lower() not in ("monitor current conditions",):
            if _ns_na[0].isupper():
                _ns_na = _ns_na[0].lower() + _ns_na[1:]
            _ns_parts.append("Next, %s." % _ns_na)
        else:
            _ns_parts.append("Monitor current conditions.")
        _ns_generic_inv = "Loss of structure and sustained break of VWAP."
        if invalidation and invalidation != _ns_generic_inv:
            _ns_inv = invalidation.strip()
            if not _ns_inv.endswith("."):
                _ns_inv += "."
            _ns_parts.append(_ns_inv)
        narrative_summary = " ".join(_ns_parts)
        _ns_words = narrative_summary.split()
        if len(_ns_words) > 90:
            narrative_summary = " ".join(_ns_words[:90])
            if not narrative_summary.endswith("."):
                narrative_summary = narrative_summary.rsplit(" ", 1)[0] + "."

        return {
            "available":       True,
            "display_only":    True,
            "shadow_mode_note":"SHADOW MODE — NO LIVE AUTHORITY",
            "market_environment": {
                "regime":        regime_label,
                "raw_regime":    regime,
                "primary_driver":driver_label,
                "raw_driver":    driver,
                "narrative":     expl.get("what_is_happening", ""),
                "driver_detail": expl.get("why_it_is_happening", ""),
            },
            "money_flow": {
                "leading":   leading,
                "weak":      weak,
                "narrative": flow_narrative,
            },
            "market_priority": {
                "ranked":         market_ranking,
                "top_market":     top_symbol,
                "top_reason":     top_reason,
                "focus_context":  expl.get("why_this_market_is_relevant", ""),
            },
            "technical_verdict": {
                "verdict":           verdict_display,
                "source":            "production_engine",
                "note":              "Production engine verdict — not recomputed by analyst",
                "blocking_factors":  blocking,
                "confirming_factors":passed[:3],
                "technical_found":   expl.get("what_the_technical_engine_found", ""),
            },
            "next_action":             next_action,
            "invalidation":            invalidation,
            "briefing_text":           briefing_text,
            "narrative_summary":       narrative_summary,
            "narrative_summary_source":"dpv2_existing_fields",
        }
    except Exception as _ae:
        return {
            "available":       False,
            "error":           str(_ae),
            "display_only":    True,
            "shadow_mode_note":"SHADOW MODE — NO LIVE AUTHORITY",
        }


def compute_decision_pipeline_v2(instrument, mode, live_verdict, live_direction,
                                  trade_plan=None):
    """
    Shadow 5-stage decision pipeline: OBSERVE -> INTERPRET -> PRIORITIZE -> VALIDATE -> DECIDE.

    Phase 1B: Corrected stage responsibilities + outcome-comparison agreement tracking.
    Phase 2:  AI Analyst Layer — one plain-English briefing consuming stage outputs.
    DISPLAY-ONLY in shadow mode. Never mutates global state, never calls full_analysis
    recursively. Fail-open at every stage. Flag OFF -> returns None -> key not attached
    -> goldens byte-identical. All CAN_* flags default False.
    """
    if not DECISION_PIPELINE_V2_ENABLED:
        return None
    try:
        flags = {
            "enabled":               DECISION_PIPELINE_V2_ENABLED,
            "shadow_mode":           _DPV2_SHADOW_MODE,
            "can_change_verdict":    _DPV2_CAN_CHANGE_VERDICT,
            "can_change_confidence": _DPV2_CAN_CHANGE_CONFIDENCE,
            "can_change_risk":       _DPV2_CAN_CHANGE_RISK,
            "can_pause_entries":     _DPV2_CAN_PAUSE_ENTRIES,
            "can_route_orders":      _DPV2_CAN_ROUTE_ORDERS,
        }

        def _safe(fn, *args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except Exception as _e:
                return {"status": "ERROR", "error": str(_e)}

        s1 = _safe(_dpv2_stage_observe, instrument)
        s2 = (_safe(_dpv2_stage_interpret, s1)
               if s1.get("status") == "OK" else {"status": "SKIPPED"})
        s3 = (_safe(_dpv2_stage_prioritize, s1, s2, mode)
               if s2.get("status") == "OK" else {"status": "SKIPPED"})
        s4 = (_safe(_dpv2_stage_validate, s1, s2, s3, instrument, mode)
               if s3.get("status") == "OK" else {"status": "SKIPPED"})
        s5 = (_safe(_dpv2_stage_decide, s1, s2, s3, s4,
                    live_verdict, live_direction, instrument)
               if s4.get("status") == "OK" else {"status": "SKIPPED"})

        pipeline_verdict = (s5 or {}).get("pipeline_verdict", "INSUFFICIENT_DATA")
        agreement_status = (s5 or {}).get("agreement_status", "INCOMPARABLE")
        agreement_bool   = (s5 or {}).get("agreement_with_live")

        logger.info(
            "[DPv2 shadow] inst=%s mode=%s pipeline=%s live=%s agree=%s",
            instrument, mode, pipeline_verdict, live_verdict, agreement_status,
        )

        # Agreement record
        import uuid as _uuid
        record_id = str(_uuid.uuid4())[:8]
        record = {
            "id":                    record_id,
            "ts":                    datetime.now(timezone.utc).isoformat(),
            "symbol":                instrument,
            "mode":                  mode,
            "strategy":              "DPV2",
            "production_verdict":    live_verdict,
            "shadow_verdict":        pipeline_verdict,
            "agreement_status":      agreement_status,
            "production_confidence": None,
            "pipeline_confidence":   (s5 or {}).get("pipeline_confidence"),
            "technical_confidence":  (s4 or {}).get("technical_confidence"),
            "regime":                (s2 or {}).get("regime", "UNKNOWN"),
            "primary_driver":        (s2 or {}).get("primary_driver", "UNKNOWN"),
            "market_priority":       (s3 or {}).get("focus_preference", "INSUFFICIENT_DATA"),
            "entry_price":           None,
            "stop_price":            None,
            "target_price":          None,
            "trade_triggered":       is_actionable(live_verdict or "WAIT"),
            "tp1_reached":           None,
            "final_target_reached":  None,
            "stop_reached":          None,
            "mfe_pts":               None,
            "mae_pts":               None,
            "final_outcome":         None,
            "better_decision":       None,
        }
        if record["trade_triggered"] and isinstance(trade_plan, dict):
            record["entry_price"]  = trade_plan.get("entry")
            record["stop_price"]   = trade_plan.get("stop")
            record["target_price"] = (trade_plan.get("target2")
                                      or trade_plan.get("target1"))
        _dpv2_store_agreement_record(record)

        # Shadow trade tracking: V2 approved, production waited
        prod_ready = is_actionable(live_verdict or "WAIT")
        v2_ready   = (pipeline_verdict == "READY")
        shadow_trade = None
        if v2_ready and not prod_ready:
            obs_price = (s1 or {}).get("price")
            shad_dir  = (s5 or {}).get("pipeline_direction")
            if obs_price is not None and shad_dir is not None:
                if instrument not in _DPV2_SHADOW_TRADES:
                    _DPV2_SHADOW_TRADES[instrument] = {
                        "record_id":   record_id,
                        "symbol":      instrument,
                        "mode":        mode,
                        "direction":   shad_dir,
                        "entry_price": float(obs_price),
                        "stop_price":  None,
                        "target_price":None,
                        "ts":          record["ts"],
                        "mfe_pts":     0.0,
                        "mae_pts":     0.0,
                        "outcome":     None,
                        "label":       "HYPOTHETICAL",
                        "note":        "V2 shadow trade — never routes an order",
                    }
            st = _DPV2_SHADOW_TRADES.get(instrument)
            if st is not None:
                entry  = st.get("entry_price")
                cur_p  = (s1 or {}).get("price")
                st_dir = st.get("direction")
                if entry is not None and cur_p is not None:
                    try:
                        diff = float(cur_p) - float(entry)
                        exc  = diff if st_dir == "LONG" else -diff
                        st["mfe_pts"] = max(st.get("mfe_pts", 0.0), exc)
                        st["mae_pts"] = max(st.get("mae_pts", 0.0), -exc)
                    except Exception:
                        pass
            shadow_trade = _DPV2_SHADOW_TRADES.get(instrument)
        elif prod_ready and instrument in _DPV2_SHADOW_TRADES:
            st = _DPV2_SHADOW_TRADES.pop(instrument, None)
            if st:
                st["outcome"] = "PRODUCTION_APPROVED"

        scorecard = _dpv2_compute_scorecard()

        # Phase 2: AI Analyst briefing — consumes stage outputs, never recomputes
        analyst_briefing = _dpv2_analyst_briefing(s1, s2, s3, s4, s5, instrument, mode)

        return {
            "available":           True,
            "shadow_mode":         True,
            "instrument":          instrument,
            "mode":                mode,
            "flags":               flags,
            "stages": {
                "observe":    s1,
                "interpret":  s2,
                "prioritize": s3,
                "validate":   s4,
                "decide":     s5,
            },
            "pipeline_verdict":    pipeline_verdict,
            "pipeline_direction":  (s5 or {}).get("pipeline_direction"),
            "pipeline_confidence": (s5 or {}).get("pipeline_confidence"),
            "agreement_status":    agreement_status,
            "agreement_with_live": agreement_bool,
            "divergence_reason":   (s5 or {}).get("divergence_reason"),
            "shadow_trade":        shadow_trade,
            "scorecard":           scorecard,
            "analyst_briefing":    analyst_briefing,
            "record_id":           record_id,
        }
    except Exception as _exc:
        logger.warning("[DPv2] orchestrator error (fail-open): %s", _exc)
        return {"available": False, "reason": str(_exc), "shadow_mode": True}


# ── Phase 5B strict instrument resolver (DIAGNOSTICS-ONLY) ─────────────────
# Returns the canonical instrument name ONLY when a recognized alias is present.
# Returns None for unknown, blank, or malformed input — prevents an unrecognized
# ticker from silently overwriting the legitimate MGC cache slot (MGC is the
# lenient global default; this function never defaults). Do NOT use in any money
# path, gate, scoring, or sizing; instrument_of() is the correct resolver there.

def _dt_instrument_of(ticker):
    """Diagnostics-only strict resolver for the decision-trace cache.

    Unlike instrument_of() this never defaults to MGC. It returns None
    whenever the ticker does not explicitly match a known alias, so an
    unknown ticker cannot overwrite the legitimate MGC cache entry.
    """
    if not ticker:
        return None
    s = str(ticker).upper().strip()
    if not s:
        return None
    for inst in _ALERT_INSTRUMENTS:
        if any(alias in s for alias in ASSETS[inst]["aliases"]):
            return inst
    return None


# ── Phase 5B: Decision Trace adapter (DISPLAY/DIAGNOSTICS-ONLY) ──────────────
# Pure read-only adapter: maps the FINAL assembled result from full_analysis into
# a compact, human-readable snapshot showing WHAT the system decided and WHY.
# NEVER recomputes — only reads from the completed result dict.
# NEVER touches gate / scoring / sizing / dedup / traderspost / money path.
# Exposed ONLY via the owner-only /decision-trace endpoint when
# DECISION_TRACE_SHADOW_ENABLED is ON. Flag OFF => cache stays empty and the
# endpoint returns {enabled: false}. Fail-open (try/except on every access).

def build_legacy_decision_trace(result, instrument, generated_at=None):
    """Return a compact decision-trace snapshot derived purely from `result`.

    Args:
        result      : completed full_analysis() return dict (NOT mutated).
        instrument  : canonical instrument string (e.g. "MGC", "MNQ").
        generated_at: optional ISO timestamp string; defaults to utcnow().

    Returns a dict with keys:
        schema_version, generated_at, instrument,
        domain, state, tier, direction,
        edge_score, edge_grade, strict_score, strict_label,
        strict_reason, strict_missing,
        has_active_trade, has_trade_plan, next_action.
    """
    try:
        import datetime as _dtime
        ts = generated_at or _dtime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

        verdict = result.get("verdict") or ""
        market_closed = (
            verdict == "MARKET CLOSED"
            or not result.get("market_open", True)
        )

        active_trade = result.get("active_trade")
        has_active   = bool(active_trade)
        tp           = result.get("trade_plan") or {}
        has_plan     = bool(tp.get("trade_plan"))

        # ── Domain ────────────────────────────────────────────────────────────
        if market_closed:
            domain = "WAIT"
        elif has_active:
            domain = "MANAGEMENT"
        elif is_actionable(verdict):
            domain = "ENTRY"
        else:
            domain = "WAIT"

        # ── State + Tier ──────────────────────────────────────────────────────
        if market_closed:
            state, tier = "MARKET_CLOSED", None
        elif has_active:
            state, tier = "MANAGE", None
        elif verdict in FULL_READY_VERDICTS:
            state, tier = "READY", "FULL"
        elif verdict in EARLY_READY_VERDICTS:
            state, tier = "READY", "EARLY"
        elif result.get("strict_direction"):
            state, tier = "SETUP_FORMING", None
        else:
            state, tier = "MONITOR", None

        # ── Direction ─────────────────────────────────────────────────────────
        direction = ready_direction(verdict) or result.get("strict_direction")

        # ── Scores ────────────────────────────────────────────────────────────
        edge_score   = result.get("edge_score")
        edge_grade   = result.get("edge_grade")
        strict_score = result.get("strict_score")
        strict_label = result.get("strict_label")

        # ── Why WAIT ──────────────────────────────────────────────────────────
        strict_reason  = result.get("strict_reason")
        strict_missing = result.get("strict_missing")

        # ── Next action from Main Brain (display only, fail-open) ─────────────
        next_action = None
        try:
            next_action = (
                (result.get("main_brain") or {})
                .get("decision", {})
                .get("next_action")
            )
        except Exception:
            pass

        # ── Phase 5C: Diagnostic truthfulness additions (DISPLAY/DIAGNOSTICS-ONLY)
        # All five blocks are individually fail-open: an exception leaves the new key
        # None without touching ANY existing key. Reads ONLY from the already-assembled
        # `result` (gate_debug, edge_breakdown, volatility); no recomputation and no
        # money-path access. ─────────────────────────────────────────────────────────

        # Change 2 — Full edge score math breakdown ───────────────────────────
        _5c_edge_detail = None
        try:
            _5c_eb  = result.get("edge_breakdown") or {}
            _5c_gd  = result.get("gate_debug") or {}
            _5c_vol = result.get("volatility") or {}
            _5c_comps = _5c_eb.get("components") or []
            _5c_key_map = {
                "bos_confirmed": "bos", "choch_confirmed": "choch",
                "vwap_confirmed": "vwap", "liquidity_sweep": "sweep",
                "volume_confirmed": "volume", "cvd_confirmed": "cvd",
                "preferred_session": "session",
            }
            _5c_cpts = {
                _5c_key_map.get(c.get("key", ""), c.get("key", "")):
                (c.get("points", 0) if c.get("present") else 0)
                for c in _5c_comps if c.get("key")
            }
            _5c_raw   = int(_5c_eb.get("raw_score") or 0)
            _5c_final = int(_5c_eb.get("score") or edge_score or 0)
            _5c_ls    = int(_5c_gd.get("learning_score_delta") or 0)
            _5c_sb    = _5c_eb.get("score_breakdown") or []
            _5c_soft  = sum(it.get("points", 0) for it in _5c_sb
                            if (it.get("points") or 0) < 0
                            and "Learning" not in (it.get("label") or ""))
            _5c_vcfg  = (int(_5c_vol.get("score_adj") or 0)
                         if _5c_vol.get("status") == "ok" else 0)
            _5c_thr   = int(
                _5c_gd.get("full_ready_threshold")
                or _5c_gd.get("ready_threshold")
                or EDGE_READY_THRESHOLD
            )
            _5c_edge_detail = {
                "component_points":               _5c_cpts,
                "raw_component_score":            _5c_raw,
                "soft_modifier_total":            _5c_soft,
                "learning_delta":                 _5c_ls,
                "volatility_configured_adjustment": _5c_vcfg,
                "volatility_applied_adjustment":  0,
                "final_score":                    _5c_final,
                "threshold":                      _5c_thr,
                "gap_to_threshold":               max(0, _5c_thr - _5c_final),
                "passes":                         _5c_final >= _5c_thr,
            }
        except Exception:
            pass

        # Change 3 — Zone role disclosure ──────────────────────────────────────
        _5c_zone_role = None
        try:
            _5c_gd  = result.get("gate_debug") or {}
            _5c_req = bool(_5c_gd.get("require_zone"))
            _5c_zst = _5c_gd.get("zoneState") or None
            _5c_zvl = bool(_5c_gd.get("zone_valid"))
            _5c_zone_role = {
                "state":                    _5c_zst,
                "required_by_current_mode": _5c_req,
                # null when zone is not required — avoid a misleading "false" gate label
                "hard_gate_pass":           bool(_5c_zvl) if _5c_req else None,
                "edge_points":              0,
                "affects_verdict":          _5c_req,
            }
        except Exception:
            pass

        # Change 4 — Failure summary (human-readable, categorized) ─────────────
        _5c_failure = None
        if domain == "WAIT" and not market_closed and not has_active:
            try:
                _5c_gd    = result.get("gate_debug") or {}
                _5c_vol   = result.get("volatility") or {}
                _5c_fails = list(_5c_gd.get("failed_conditions") or [])
                _5c_ef    = [f for f in _5c_fails if f.startswith("edge_score")]
                _5c_nef   = [f for f in _5c_fails if not f.startswith("edge_score")]
                if _5c_ef and not _5c_nef:
                    _5c_cur = int(_5c_gd.get("edge_score") or 0)
                    _5c_thr = int(
                        _5c_gd.get("full_ready_threshold")
                        or _5c_gd.get("ready_threshold")
                        or EDGE_READY_THRESHOLD
                    )
                    _5c_hreason = ("Edge score %d is below the required %d."
                                   % (_5c_cur, _5c_thr))
                else:
                    _5c_hreason = (", ".join(_5c_fails)) if _5c_fails else None
                _5c_il = (True if direction == "Long"
                          else (False if direction == "Short" else None))
                def _5c_dl(lg, sh):
                    if _5c_il is True:  return lg
                    if _5c_il is False: return sh
                    return lg
                _5c_opt_map = [
                    ("bos",              _5c_dl("Bullish BOS",       "Bearish BOS"),        20),
                    ("choch",            _5c_dl("Bullish CHOCH",     "Bearish CHOCH"),      20),
                    ("vwap_confirmed",   _5c_dl("VWAP Reclaim",      "VWAP Rejection"),     15),
                    ("liquidity_sweep",  "Liquidity Sweep",                                 15),
                    ("volume_confirmed", "Volume Confirmation",                             15),
                    ("cvd_confirmed",    _5c_dl("CVD Confirms Long", "CVD Confirms Short"), 15),
                    ("session_pref",     "Session Bonus",                                   10),
                ]
                _5c_hard_keys = {"zone_valid", "vwap_confirmed", "structure_confirmed",
                                 "volume_unconfirmed", "cvd_conflict", "location"}
                _5c_actual_hard = [f for f in _5c_fails if f in _5c_hard_keys]
                _5c_miss_opt = [
                    {"name": lbl, "points": pts}
                    for gk, lbl, pts in _5c_opt_map
                    if gk not in _5c_hard_keys and not _5c_gd.get(gk)
                ]
                _5c_ctx = []
                if not _5c_gd.get("require_zone") and _5c_gd.get("zoneState"):
                    _5c_ctx.append(
                        'Zone state "%s" is informational — zone is not a gate '
                        "requirement in this mode (GATE_REQUIRE_ZONE=False)"
                        % _5c_gd.get("zoneState")
                    )
                _5c_vc = int(_5c_vol.get("score_adj") or 0)
                if _5c_vol.get("status") == "ok" and _5c_vc:
                    _5c_ctx.append(
                        "Volatility configuredAdj=%+d is a policy value — "
                        "it is NOT applied to the edge score (appliedAdj=0)" % _5c_vc
                    )
                _5c_failure = {
                    "human_reason":                   _5c_hreason,
                    "hard_blockers":                  _5c_actual_hard or _5c_nef or _5c_ef,
                    "missing_optional_confirmations": _5c_miss_opt,
                    "context_only":                   _5c_ctx,
                }
            except Exception:
                pass

        # Change 5 — Score gap: points needed and which absent components add them ─
        # Labels in edge_breakdown.components are already direction-aware (set by
        # compute_edge_breakdown / _analysis_edge_breakdown). Use them as-is; no
        # secondary remapping needed or correct here.
        _5c_score_gap = None
        try:
            _5c_eb    = result.get("edge_breakdown") or {}
            _5c_gd    = result.get("gate_debug") or {}
            _5c_comps = _5c_eb.get("components") or []
            _5c_final = int(_5c_eb.get("score") or edge_score or 0)
            _5c_thr   = int(
                _5c_gd.get("full_ready_threshold")
                or _5c_gd.get("ready_threshold")
                or EDGE_READY_THRESHOLD
            )
            _5c_gap      = max(0, _5c_thr - _5c_final)
            _5c_available = [
                {"name": c.get("label", ""), "points": c.get("points", 0)}
                for c in _5c_comps if not c.get("present")
            ]
            _5c_score_gap = {
                "points_needed":                _5c_gap,
                "available_missing_components": _5c_available,
            }
        except Exception:
            pass

        # Change 6 — Structure alert verification status ────────────────────────
        _5c_struct_alert = None
        try:
            _5c_gd     = result.get("gate_debug") or {}
            _5c_bos    = bool(_5c_gd.get("bos"))
            _5c_choch  = bool(_5c_gd.get("choch"))
            _5c_struct = bool(_5c_gd.get("structure_confirmed"))
            _5c_struct_alert = {
                "status":         "VERIFIED" if _5c_struct else "NOT VERIFIED",
                "bos_received":   _5c_bos,
                "choch_received": _5c_choch,
                "note": (
                    "Structure alert received and confirmed in current session."
                    if _5c_struct
                    else "No full BOS/CHOCH webhook received in the current session. "
                         "Manual TradingView configuration check required before "
                         "declaring a production defect."
                ),
                "tradingview_check": {
                    "script_loaded":           None,
                    "correct_symbol":          None,
                    "intended_timeframe":      None,
                    "alert_exists":            None,
                    "any_alert_function_call": None,
                    "webhook_enabled":         None,
                    "correct_webhook_url":     None,
                    "message_blank":           None,
                    "active":                  None,
                    "expired":                 None,
                    "recent_chart_labels":     None,
                },
            }
        except Exception:
            pass

        return {
            "schema_version":   1,
            "generated_at":     ts,
            "instrument":       instrument,
            "domain":           domain,
            "state":            state,
            "tier":             tier,
            "direction":        direction,
            "edge_score":       edge_score,
            "edge_grade":       edge_grade,
            "strict_score":     strict_score,
            "strict_label":     strict_label,
            "strict_reason":    strict_reason,
            "strict_missing":   strict_missing,
            "has_active_trade": has_active,
            "has_trade_plan":   has_plan,
            # plan_available: plan dict is populated with entry/stop/target.
            # plan_executable: plan_available AND a FULL (candle-close) READY verdict.
            "plan_available":   has_plan and bool(
                                    (tp.get("entry_zone") or tp.get("entry"))
                                    and tp.get("stop_loss") and tp.get("target1")),
            "plan_executable":  has_plan and verdict in FULL_READY_VERDICTS,
            "next_action":      next_action,
            # ── Phase 5C diagnostic truthfulness (Changes 2-6, display-only) ──
            "edge_score_detail": _5c_edge_detail,
            "zone_role":         _5c_zone_role,
            "failure_summary":   _5c_failure,
            "score_gap":         _5c_score_gap,
            "structure_alert":   _5c_struct_alert,
        }
    except Exception as _exc:
        import datetime as _dtime2
        return {
            "schema_version":   1,
            "generated_at":     generated_at or _dtime2.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
            "instrument":       instrument or "",
            "domain":           "WAIT",
            "state":            "INVALID_DATA",
            "tier":             None,
            "direction":        None,
            "edge_score":       None,
            "edge_grade":       None,
            "strict_score":     None,
            "strict_label":     None,
            "strict_reason":    "Decision trace build failed: %s" % _exc,
            "strict_missing":   None,
            "has_active_trade": False,
            "has_trade_plan":   False,
            "plan_available":   False,
            "plan_executable":  False,
            "next_action":      None,
            # ── Phase 5C diagnostic truthfulness (fail-open defaults) ──────────
            "edge_score_detail": None,
            "zone_role":         None,
            "failure_summary":   None,
            "score_gap":         None,
            "structure_alert":   None,
        }


# ─────────────────────────────────────────────────────────────────────────────
# V1 Canonical Interface Builders — Manager Interface v1 + Coach Interface v1
# (ARCH §7; additive read-only aggregators; never call the gateway, never write)
# ─────────────────────────────────────────────────────────────────────────────

def build_manager_interface(result, instrument=None):
    """Canonical Manager Interface v1.

    Read-only aggregation of execution state, active/managed trade snapshots,
    training gate enabled status, and per-instrument auto-trade arm map.

    Never calls the execution gateway, never triggers a recompute, never writes
    to the database.  Guaranteed to return the ARCH §7 Manager output contract
    dict (with neutral stubs on partial failure).

    Mutability guarantee: active_trade and managed_trade are shallow-copied so
    consumers cannot mutate global ACTIVE_TRADES_BY_INST or MANAGED_TRADES_BY_KEY
    through this interface.

    Fields:
      gateway_debug      per-gate PASS/FAIL outcome from Expert result
                         (ARCH field name; code key is "gate_debug")
      active_trade       shallow copy of ACTIVE_TRADES_BY_INST[inst] (None if no trade)
      managed_trade      shallow copy of first open MANAGED_TRADES_BY_KEY entry for
                         instrument (None if no paper/managed trade open)
      training_gate      Bot Training Mode arm status {"enabled": bool}
      auto_trade_enabled per-instrument arm state map {instrument: bool}
      _version           "v1"
    """
    inst = instrument or (result.get("active_ticker") if result else None) or ""
    try:
        # gateway_debug: per-gate PASS/FAIL outcome carried in Expert result.
        # Read-only; does not expose secrets or broker payloads.
        gateway_debug = (result.get("gate_debug") or {}) if result else {}

        # active_trade: shallow copy of ACTIVE_TRADES_BY_INST entry for instrument.
        # active_trade_snapshot() shallow-copies the outer dict but inner trade dicts
        # are shared references; dict() here prevents consumer mutation of global state.
        at_snap      = active_trade_snapshot()
        _at_raw      = at_snap.get(inst) if inst else None
        active_trade = dict(_at_raw) if _at_raw is not None else None

        # managed_trade: shallow copy of first open MANAGED_TRADES_BY_KEY entry.
        # Lock-free list snapshot (same pattern as display blocks throughout app).
        # dict() prevents consumer mutation of the live managed-trade object.
        managed_trade = None
        for _mt in list(MANAGED_TRADES_BY_KEY.values()):
            if _mt.get("instrument") == inst and not _mt.get("closed"):
                managed_trade = dict(_mt)
                break

        # training_gate: Bot Training Mode arm status — pure env-var read.
        # Represents whether training mode is armed, not the per-call gate verdict.
        training_gate = {"enabled": training_mode_enabled()}

        # auto_trade_enabled: per-instrument arm state map (AUTO_TRADE under lock).
        auto_map = {_a: auto_trade_enabled(_a) for _a in ASSETS}

        return {
            "gateway_debug":      gateway_debug,
            "active_trade":       active_trade,
            "managed_trade":      managed_trade,
            "training_gate":      training_gate,
            "auto_trade_enabled": auto_map,
            "_version":           "v1",
        }
    except Exception as _mgr_exc:
        logger.debug("build_manager_interface fail-open: %s", _mgr_exc)
        return {
            "gateway_debug":      {},
            "active_trade":       None,
            "managed_trade":      None,
            "training_gate":      {"enabled": False},
            "auto_trade_enabled": {},
            "_version":           "v1",
        }


def build_coach_interface(result, instrument=None, mode=None):
    """Canonical Coach Interface v1.

    Read-only aggregation of learning subsystem status for the given instrument
    + mode.  Never triggers a learning update, database write, or scoring change.
    Guaranteed to return the ARCH §7 Coach output contract dict (with neutral
    stubs on partial failure).

    Semantic notes:
      weight_updated    — True ONLY when _recompute_learning() completed
                         successfully at least once in this session (authoritative
                         signal: LEARNING_ANALYTICS["updated_at"] is present and
                         non-None, set at recompute completion, not at boot or
                         mere DB availability).  NOT a readiness or enablement flag.

      thesis_resolved   — True when _resolve_open_theses() successfully committed at
                         least one thesis snapshot resolution in this process session
                         (_THESIS_LAST_RESOLVED_AT is not None).  False at boot and
                         during any full_analysis() call before a trade-close
                         resolution runs.  DB readiness alone does NOT imply True.

      thesis_last_resolved_at — ISO-8601 UTC timestamp string of the most recent
                         thesis resolution event, or None when no resolution has
                         run in this session.  Mirrors _THESIS_LAST_RESOLVED_AT;
                         always None at boot and after a module reload.  The
                         Coach dashboard panel uses this to show "Last resolved:
                         HH:MM ET" so the operator can confirm the learning loop
                         is healthy without inspecting logs.

      learning_influence — ±15 Edge Score modifier from result's per-direction
                          learning_score_influence.  The active direction carries a
                          non-zero delta; the inactive direction is 0.  Reads
                          result["learning_score_influence"][dir]["delta"] which is
                          the actual learning_score_delta applied during scoring
                          (gd.get("learning_score_delta", 0) from _ls_dir_summary).

      rule_engine_eligibility — pure cache read from LEARNING_ELIGIBILITY via
                               _check_learning_eligibility(); no writes, no
                               counters, no DB call, no recompute.

    Fields:
      weight_updated              True if _recompute_learning() ran in this session
      thesis_resolved             True if _resolve_open_theses() ran in this session
      thesis_last_resolved_at     ISO-8601 UTC str | None — timestamp of last resolution
      learning_influence          float: active-direction learning_score_delta
      rule_engine_eligibility     "GHOST_ONLY" | "LIVE_ELIGIBLE"
      _version                    "v1"
    """
    inst  = instrument or (result.get("active_ticker") if result else None) or ""
    _mode = mode or TRADING_MODE
    try:
        # weight_updated: True ONLY when _recompute_learning() has run successfully.
        # LEARNING_ANALYTICS["updated_at"] is set at line ~12590 inside the
        # recompute body, NOT at boot and NOT by DB availability probes.  The boot
        # default is {"enabled":…, "ready": False, "total_trades": 0} — no "updated_at".
        # This correctly distinguishes "recompute ran" from "system ready/enabled."
        with LEARNING_LOCK:
            weight_updated = bool(LEARNING_ANALYTICS.get("updated_at"))

        # thesis_resolved: True when _resolve_open_theses() committed at least one
        # thesis snapshot resolution in this session (_THESIS_LAST_RESOLVED_AT set).
        # False at boot and whenever no trade-close resolution has run yet (no DB,
        # no eligible rows, or process just started).  THESIS_TRACKER_DB_READY alone
        # does NOT imply True — DB readiness ≠ a resolution event having occurred.
        thesis_resolved = _THESIS_LAST_RESOLVED_AT is not None
        # thesis_last_resolved_at: ISO-8601 UTC string of the most recent resolution
        # event, or None.  Mirrors the same _THESIS_LAST_RESOLVED_AT global so the
        # Coach dashboard panel can show "Last resolved: HH:MM ET" without the
        # operator needing to inspect logs.
        thesis_last_resolved_at = (
            _THESIS_LAST_RESOLVED_AT.isoformat()
            if _THESIS_LAST_RESOLVED_AT is not None else None
        )

        # learning_influence: active direction ±15 delta from result's LSI block.
        # _ls_dir_summary (line ~23454) builds Long/Short from gate_debug per direction:
        # "delta": gd.get("learning_score_delta", 0) — the actual adjustment applied.
        # Only the active direction is non-zero; the inactive direction is 0.
        _lsi        = (result.get("learning_score_influence") or {}) if result else {}
        _long_d     = float((_lsi.get("Long")  or {}).get("delta") or 0.0)
        _short_d    = float((_lsi.get("Short") or {}).get("delta") or 0.0)
        learning_influence = _long_d if _long_d != 0.0 else _short_d

        # rule_engine_eligibility: pure in-memory LEARNING_ELIGIBILITY cache read.
        # _check_learning_eligibility() acquires LEARNING_ELIGIBILITY_LOCK read-only;
        # no writes, no counters, no timestamps, no DB, no recompute triggered.
        _elig_status, _ = _check_learning_eligibility(inst, mode=_mode)
        rule_engine_eligibility = _elig_status  # "GHOST_ONLY" | "LIVE_ELIGIBLE"

        # ── Learning diagnostics (Phase 7I.1 — canonical key + win-rate fix) ───────
        # Exposes full pipeline state including lookup_status (CANONICAL | LEGACY_COMPAT
        # | NOT_FOUND), canonical key, aggregate win/loss counts, and win-rate after the
        # lower(trim(result))='win' fix. No DB call, no recompute, no write.
        try:
            _se         = (result.get("strategy_engine") or {}) if result else {}
            _active_key = _se.get("active_key")          # STRATEGY_PRIORITY key or None
            _canon_key, _canon_status = (_canonical_learning_key(_active_key)
                                         if _active_key else (None, "NOT_FOUND"))

            with LEARNING_LOCK:
                _la = dict(LEARNING_ANALYTICS)

            # Use the updated _strategy_weight_for (now returns 3-tuple + legacy compat).
            # No LEARNING_LOCK held here — _strategy_weight_for acquires it internally.
            if _active_key:
                _dw, _dn, _lookup_status = _strategy_weight_for(
                    _active_key, mode=_mode, instrument=inst,
                    direction=_se.get("direction"))
            else:
                # No active strategy: find the highest-sample key for this mode
                with LEARNING_LOCK:
                    _prefix  = "%s::" % _mode
                    _mkeys   = {k: v for k, v in LEARNING_SAMPLE_BY_KEY.items()
                                if k.startswith(_prefix)}
                    _best_k  = max(_mkeys, key=lambda k: _mkeys[k]) if _mkeys else None
                    _dn      = int(_mkeys.get(_best_k, 0))
                    _dw      = float(STRATEGY_WEIGHTS.get(_best_k, 1.0)) if _best_k else 1.0
                _lookup_status = "NOT_FOUND"

            _score_enabled = _learning_score_gate_enabled()
            _recompute_ran = bool(_la.get("updated_at"))
            _total_trades  = int(_la.get("total_trades") or 0)

            # Derive per-strategy aggregate counts from LEARNING_ANALYTICS ranking
            # (populated by _recompute_learning after the win-rate SQL fix).
            _ranking     = _la.get("ranking") or []
            _strat_entry = next((r for r in _ranking
                                 if r.get("strategy_key") == _active_key
                                 and r.get("trading_mode") == _mode), None)
            if _strat_entry:
                _n_strat    = int(_strat_entry.get("n") or 0)
                _wr_strat   = float(_strat_entry.get("win_rate") or 0) / 100.0
                _agg_wins   = round(_n_strat * _wr_strat)
                _agg_losses = _n_strat - _agg_wins
                _agg_wr     = round(_wr_strat, 4)
            else:
                _n_strat = _agg_wins = _agg_losses = 0
                _agg_wr  = None

            # Precise weight_status label.
            # KEY_NOT_FOUND is only meaningful when there IS an active canonical key to
            # look up. When _active_key is None (no current strategy) we fall through to
            # the INSUFFICIENT_SAMPLES / NO_CHANGE / UPDATED paths using the best-sample
            # fallback key so the panel still shows useful information.
            if not _score_enabled:
                _weight_status, _blocked = "DISABLED",             "DISABLED"
                _applied = False
            elif not LEARNING_DB_ENABLED:
                _weight_status, _blocked = "DISABLED",             "DB_DISABLED"
                _applied = False
            elif not _recompute_ran:
                _weight_status, _blocked = "NOT_ELIGIBLE",         "NOT_ELIGIBLE"
                _applied = False
            elif _active_key and _lookup_status == "NOT_FOUND" and _canon_status == "NOT_FOUND":
                # Key format is genuinely unrecognised — not in any known strategy list.
                # (Valid strategies with 0 trades return CANONICAL via _strategy_weight_for
                # step 4, so they fall through to INSUFFICIENT_SAMPLES below.)
                _weight_status, _blocked = "KEY_NOT_FOUND",        "KEY_NOT_FOUND"
                _applied = False
            elif _dn < LEARNING_MIN_SAMPLE:
                _weight_status, _blocked = "INSUFFICIENT_SAMPLES", "INSUFFICIENT_SAMPLES"
                _applied = False
            elif abs(float(_dw) - 1.0) < 0.001:
                _weight_status, _blocked = "NO_CHANGE",            None
                _applied = learning_influence != 0.0
            else:
                _weight_status, _blocked = "UPDATED",              None
                _applied = learning_influence != 0.0

            _ns_key = _ns_learning_key(_active_key, _mode) if _active_key else None
            learning_diagnostics = {
                # Existing fields (preserved for CoachPanel back-compat)
                "enabled":               LEARNING_DB_ENABLED,
                "influence_enabled":     _score_enabled,
                "mode":                  _mode,
                "eligible":              rule_engine_eligibility not in ("DISABLED",),
                "strategy_key":          _ns_key,
                "sample_count":          int(_dn),
                "minimum_samples":       LEARNING_MIN_SAMPLE,
                "closed_trade_count":    _total_trades,
                "current_weight":        round(float(_dw), 4),
                "previous_weight":       None,
                "weight_delta":          round(float(_dw) - 1.0, 4),
                "influence_points":      float(learning_influence),
                "last_sample_at":        None,
                "last_weight_update_at": _la.get("updated_at"),
                "applied_to_live_score": _applied,
                "blocked_reason":        _blocked,
                "weight_status":         _weight_status,
                "source":                "learning_db",
                # New fields (Phase 7I.1)
                "canonical_strategy_key":    _canon_key,
                "stored_strategy_key":       _active_key,
                "lookup_status":             _lookup_status,
                "result_normalization_status": "FIXED",   # lower(trim(result))='win'
                "aggregate_win_count":       int(_agg_wins),
                "aggregate_loss_count":      int(_agg_losses),
                "aggregate_win_rate":        _agg_wr,
                # Task #41 — session lesson counters (reset to 0 on restart; display-only)
                "recomputes_this_session":   _LEARNING_SESSION_RECOMPUTES,
                "weights_changed_last_run":  _LEARNING_LAST_CHANGED_COUNT,
            }
        except Exception as _ld_exc:
            logger.debug("build_coach_interface diagnostics fail-open: %s", _ld_exc)
            learning_diagnostics = {
                "enabled":           LEARNING_DB_ENABLED,
                "influence_enabled": False,
                "sample_count":      0,
                "minimum_samples":   LEARNING_MIN_SAMPLE,
                "blocked_reason":    "DIAGNOSTIC_BUILD_FAILED",
                "weight_status":     "DISABLED",
                "source":            "learning_db",
                "lookup_status":     "NOT_FOUND",
                "result_normalization_status": "FIXED",
            }

        return {
            "weight_updated":            weight_updated,
            "thesis_resolved":           thesis_resolved,
            "thesis_last_resolved_at":   thesis_last_resolved_at,
            "learning_influence":        learning_influence,
            "rule_engine_eligibility":   rule_engine_eligibility,
            "learning_diagnostics":      learning_diagnostics,
            "_version":                  "v1",
        }
    except Exception as _cch_exc:
        logger.debug("build_coach_interface fail-open: %s", _cch_exc)
        return {
            "weight_updated":            False,
            "thesis_resolved":           False,
            "thesis_last_resolved_at":   None,
            "learning_influence":        0.0,
            "rule_engine_eligibility":   "LIVE_ELIGIBLE",
            "learning_diagnostics":      {
                "enabled": LEARNING_DB_ENABLED, "influence_enabled": False,
                "sample_count": 0, "minimum_samples": LEARNING_MIN_SAMPLE,
                "blocked_reason": "COACH_BUILD_FAILED", "weight_status": "DISABLED",
                "source": "learning_db",
            },
            "_version":                  "v1",
        }


# ── Main Brain read-only payload builder (Phase 7B) ──────────────────────────
# Assembles the versioned Main Brain dashboard payload from existing canonical
# interfaces and in-memory stores.  Never invokes full_analysis(), the execution
# gateway, Journal writers, learning updaters, or any DB writes.
# Each section helper is isolated: a single section failure never propagates.

_MB_MAIN_ENGINE_KEYS = frozenset({
    "OPENING_DRIVE", "LIQUIDITY_SWEEP_REVERSAL", "VWAP_TREND_CONTINUATION",
    "RANGE_EXPANSION_BREAKOUT", "OPENING_RANGE_BREAKOUT",
    # Research-library graduates:
    "COMPRESSION_BREAKOUT", "VWAP_PULLBACK_CONTINUATION",
    "ORDER_BLOCK_REJECTION", "VWAP_RECLAIM_FAIL",
})
_MB_STRATEGY_LABELS = {
    "OPENING_DRIVE":              "Opening Drive",
    "LIQUIDITY_SWEEP_REVERSAL":   "Liquidity Sweep Reversal",
    "VWAP_TREND_CONTINUATION":    "VWAP Trend Continuation",
    "RANGE_EXPANSION_BREAKOUT":   "Range Expansion Breakout",
    "OPENING_RANGE_BREAKOUT":     "Opening Range Breakout",
    # Research-library graduates:
    "COMPRESSION_BREAKOUT":       "Compression Breakout",
    "VWAP_PULLBACK_CONTINUATION": "VWAP Pullback Continuation",
    "ORDER_BLOCK_REJECTION":      "Order Block Rejection",
    "VWAP_RECLAIM_FAIL":          "VWAP Reclaim/Fail",
}


def _mb_safe_num(v):
    """Return v as float if finite and representable, else None. JSON-safe."""
    if v is None:
        return None
    try:
        f = float(v)
        if f != f or f == float("inf") or f == float("-inf"):  # NaN / ±Inf
            return None
        return f
    except (TypeError, ValueError):
        return None


def _mb_iso(v):
    """Return ISO-8601 str from a datetime/aware-datetime or pass through str. None-safe."""
    if v is None:
        return None
    if hasattr(v, "isoformat"):
        return v.isoformat()
    if isinstance(v, str):
        return v
    return None


def _mb_err(errors, source, code):
    """Append a stable, secrets-free error entry to the errors list."""
    errors.append({"source": source, "code": code,
                   "recoverable": True, "ts": now_utc().isoformat()})


def _mb_has_err(errors, code):
    return any(e["code"] == code for e in errors)


