def _dq_has_active_trade(inst, direction):
    """Return True if an active trade for `inst` matches `direction`.

    Read-only — never mutates production state. When `direction` is empty the
    check is inst-only (conservatively returns True when a trade exists so we
    never drop an association we cannot verify). FAIL-SAFE: returns False on
    any error. DIAGNOSTICS-ONLY."""
    try:
        if not inst:
            return False
        with ACTIVE_TRADES_LOCK:
            at = ACTIVE_TRADES_BY_INST.get(inst)
        if at is None:
            return False
        if not direction:
            return True  # trade exists; direction unknown — preserve conservatively
        return (at.get("direction") or "").strip().lower() == direction.strip().lower()
    except Exception:
        return False


def _dq_attach_to_trade(inst, trade):
    """Inject diagnostics-only DQ reference keys onto a newly-registered trade dict.

    Called from set_active_trade so that _resolve_decision_snapshot can use
    Level-1 exact snapshot_key matching instead of fingerprint reconstruction.
    Keys written: _dq_snapshot_key, _dq_fingerprint, _dq_mode.

    DIAGNOSTICS-ONLY — keys are prefixed `_dq_` and ignored by all production
    logic (broker payloads, embeds, scoring, execution). FAIL-OPEN."""
    try:
        if not isinstance(trade, dict) or not inst:
            return
        direction = (trade.get("direction") or "").strip()
        mode      = TRADING_MODE
        fp        = _dq_fingerprint(inst, direction, mode)
        entry     = _DQ_PENDING_BY_SETUP.get(fp)
        if entry:
            trade["_dq_snapshot_key"] = entry["snapshot_key"]
            trade["_dq_fingerprint"]  = fp
            trade["_dq_mode"]         = mode
    except Exception:
        pass  # must never raise into set_active_trade


def _dq_fingerprint(inst, direction, mode):
    """Build a stable diagnostics fingerprint for setup identity.

    Uses inst + direction + mode so Long/Short and SCALP/SWING are tracked
    independently. Sequential same-direction setups share the same fingerprint
    but are distinguished by the WAIT-clearing hook in full_analysis.
    DIAGNOSTICS-ONLY — never touches the money path.

    SC1 KNOWN LIMITATION: two distinct untraded setups on the same
    inst+direction+mode lane (e.g. different strategy, entry, or stop) share
    this fingerprint until a WAIT, abandon, expiry, or restart separates them.
    A future phase may extend the fingerprint to include strategy key + rounded
    entry + rounded stop — see Phase 5F.1A audit for the proposed design."""
    return f"{inst}::{direction}::{mode}"


def _dq_expire_old_entries():
    """Remove stale untraded candidates from _DQ_PENDING_BY_SETUP.

    Evicts entries older than _DQ_SETUP_TTL_MIN, but EXEMPTS any entry whose
    fingerprint corresponds to an active trade (SC4 fix — active SWING trades
    must not lose their analytics association because of the candidate TTL).
    Enforces _DQ_MAX_PENDING cap with the same active-trade exemption.
    Called before each INSERT to keep memory bounded. FAIL-OPEN."""
    global _DQ_PENDING_BY_SETUP, _DQ_EXPIRED_UNTRADED, _DQ_PRESERVED_ACTIVE
    try:
        from datetime import timedelta as _td
        cutoff  = now_utc() - _td(minutes=_DQ_SETUP_TTL_MIN)
        stale   = [k for k, v in _DQ_PENDING_BY_SETUP.items()
                   if v.get("created_at", now_utc()) < cutoff]
        for k in stale:
            entry = _DQ_PENDING_BY_SETUP.get(k)
            if not entry:
                continue
            if _dq_has_active_trade(entry.get("inst"), entry.get("direction")):
                _DQ_PRESERVED_ACTIVE += 1  # active trade — do not expire
                continue
            _DQ_PENDING_BY_SETUP.pop(k, None)
            _DQ_EXPIRED_UNTRADED += 1

        if len(_DQ_PENDING_BY_SETUP) > _DQ_MAX_PENDING:
            by_age  = sorted(_DQ_PENDING_BY_SETUP.items(),
                             key=lambda x: x[1].get("created_at", now_utc()))
            to_trim = []
            for k, v in by_age:
                if len(to_trim) >= len(_DQ_PENDING_BY_SETUP) - _DQ_MAX_PENDING:
                    break
                if _dq_has_active_trade(v.get("inst"), v.get("direction")):
                    _DQ_PRESERVED_ACTIVE += 1  # never evict active-trade entries for cap
                    continue
                to_trim.append(k)
            for k in to_trim:
                _DQ_PENDING_BY_SETUP.pop(k, None)
                _DQ_EXPIRED_UNTRADED += 1
    except Exception as exc:
        logger.debug("_dq_expire_old_entries fail-open: %s", exc)


def _dq_abandon_setup(fp):
    """Remove a pending DQ entry when its setup reverts to WAIT and no trade is active.

    Only called after _dq_has_active_trade confirms no matching open trade exists
    (SC3 fix — the WAIT branch in full_analysis guards the call). Purely in-memory
    — no DB call. Ensures the next READY setup on the same fingerprint is captured
    fresh rather than skipped as a heartbeat. FAIL-OPEN — must never block trading."""
    global _DQ_ABANDONED_COUNT
    try:
        popped = _DQ_PENDING_BY_SETUP.pop(fp, None)
        if popped is not None:
            _DQ_ABANDONED_COUNT += 1
    except Exception as exc:
        logger.debug("_dq_abandon_setup fail-open: %s", exc)


def _capture_decision_snapshot(inst, direction, mode, result):
    """INSERT a pending decision snapshot when a READY verdict is first detected.

    Deduped via _DQ_PENDING_BY_SETUP fingerprint: skips if the same
    inst+direction+mode setup is already pending (heartbeat re-evaluation).
    Long/Short and SCALP/SWING are tracked independently. A new READY after WAIT
    is captured cleanly once _dq_abandon_setup clears the prior entry.
    FAIL-OPEN — never touches scoring, gate, or any money-path variable."""
    global _DQ_PENDING_BY_SETUP
    if not DQ_DB_READY or not inst or not direction:
        return
    try:
        fp = _dq_fingerprint(inst, direction, mode)
        if fp in _DQ_PENDING_BY_SETUP:
            return  # heartbeat dedup — same setup still pending

        _dq_expire_old_entries()  # bounded cleanup before inserting

        import json as _json
        _now   = now_utc()
        key    = f"{inst}::{direction}::{_now.strftime('%Y%m%dT%H%M%SZ')}"
        attr   = result.get("source_attribution") or []
        audit  = result.get("source_audit") or {}
        plan   = result.get("trade_plan") or {}

        components = [
            {"component": c.get("component"), "points": c.get("points"),
             "source": c.get("source", "unknown"), "age_s": c.get("age_seconds")}
            for c in attr
        ]

        entry_price = stop_price = None
        targets     = None
        try:
            entry_price = float(plan.get("entry") or 0) or None
            stop_price  = float(plan.get("stop")  or 0) or None
            targets     = {k: plan.get(k) for k in ("t1", "t2", "runner") if plan.get(k)}
        except Exception:
            pass

        dc_count = len(audit.get("double_counting_warnings") or [])

        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """INSERT INTO decision_snapshots
               (snapshot_key, created_at, inst, direction, mode, session_name,
                edge_score, verdict, components, entry_price, stop_price,
                targets, dc_warnings_count)
               VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
               ON CONFLICT (snapshot_key) DO NOTHING""",
            (key, _now, inst, direction, mode,
             result.get("session"),
             result.get("edge_score"),
             result.get("verdict"),
             _json.dumps(components),
             entry_price, stop_price,
             _json.dumps(targets) if targets else None,
             dc_count),
        )
        conn.commit()
        cur.close()
        conn.close()
        _DQ_PENDING_BY_SETUP[fp] = {
            "snapshot_key": key,
            "inst":         inst,
            "direction":    direction,
            "mode":         mode,
            "created_at":   _now,
        }
        logger.debug("DQ snapshot captured: %s (fp=%s)", key, fp)
    except Exception as exc:
        logger.debug("_capture_decision_snapshot fail-open: %s", exc)


def _resolve_decision_snapshot(inst, mt):
    """UPDATE the pending decision snapshot for `inst` with trade outcome data.

    Matching hierarchy (Phase 5F.1B SC2 fix — unsafe first-match fallback removed):

    Level 1 — exact snapshot_key stored on the managed trade (_dq_snapshot_key).
              Populated by _dq_attach_to_trade at trade registration; never guesses.
    Level 2 — exact fingerprint reconstructed from inst + direction + _dq_mode.
              Uses capture-time mode when available; falls back to current TRADING_MODE.
    Level 3 — unmatched closure: increment counter, log, return without any DB write.

    The in-memory entry is ALWAYS popped before any DB call, so DQ_DB_READY=False
    never leaves a blocking pending entry.  FAIL-OPEN — never touches the money path."""
    global _DQ_PENDING_BY_SETUP, _DQ_UNMATCHED_CLOSURES, _DQ_RESOLVED_COUNT
    if not inst:
        return
    try:
        direction = (mt.get("direction") or "").strip()
        mode      = mt.get("_dq_mode") or TRADING_MODE

        entry = None

        # Level 1: exact snapshot_key stored on the managed trade at registration.
        snap_ref = (mt.get("_dq_snapshot_key") or "").strip()
        if snap_ref:
            for k in list(_DQ_PENDING_BY_SETUP.keys()):
                if _DQ_PENDING_BY_SETUP[k].get("snapshot_key") == snap_ref:
                    entry = _DQ_PENDING_BY_SETUP.pop(k, None)
                    break

        # Level 2: exact fingerprint reconstruction (requires non-empty direction).
        if entry is None and direction:
            fp    = _dq_fingerprint(inst, direction, mode)
            entry = _DQ_PENDING_BY_SETUP.pop(fp, None)

        # Level 3: unmatched closure — never guess.
        if entry is None:
            _DQ_UNMATCHED_CLOSURES += 1
            logger.debug(
                "DQ resolve: no match for inst=%s direction=%s mode=%s snap_ref=%s"
                " — unmatched closure #%d",
                inst, direction, mode, snap_ref or "(none)", _DQ_UNMATCHED_CLOSURES,
            )
            return

        snap_key = entry["snapshot_key"]
        _DQ_RESOLVED_COUNT += 1

        if not DQ_DB_READY:
            logger.debug("DQ resolve: DB unavailable — entry cleared, no DB write for %s",
                         snap_key)
            return

        outcome   = (mt.get("outcome") or "").strip()
        outcome_r = mt.get("r_multiple")
        mfe_r     = mt.get("mfe_r")
        mae_r     = mt.get("mae_r")

        time_min = None
        try:
            _op = mt.get("opened_at"); _cl = mt.get("closed_at")
            if _op and _cl:
                time_min = round((_cl - _op).total_seconds() / 60.0, 1)
        except Exception:
            pass

        is_win  = "Win"       in outcome
        is_loss = "Loss"      in outcome
        is_be   = "Breakeven" in outcome or "Break" in outcome
        exit_reason = ("target_reached" if is_win
                       else "stop_hit"  if is_loss
                       else "be"        if is_be
                       else "manual")
        manual_exit = bool(mt.get("manual_close") or mt.get("stop_managing"))

        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """UPDATE decision_snapshots
               SET outcome=%s, outcome_r=%s, mfe_r=%s, mae_r=%s,
                   time_in_trade_min=%s, exit_reason=%s,
                   target_reached=%s, stop_hit=%s, manual_exit=%s,
                   resolved_at=%s
               WHERE snapshot_key=%s AND outcome IS NULL""",
            (outcome, outcome_r, mfe_r, mae_r, time_min, exit_reason,
             is_win, is_loss, manual_exit, now_utc(), snap_key),
        )
        conn.commit()
        cur.close()
        conn.close()
        logger.debug("DQ snapshot resolved: %s → %s", snap_key, outcome)
    except Exception as exc:
        logger.debug("_resolve_decision_snapshot fail-open: %s", exc)


def _build_decision_quality_report():
    """Compute the Phase 5F decision quality & signal calibration report.

    SELECT-only from decision_snapshots. Computes per-component win rates
    (present vs absent), duplicate-evidence impact, and text recommendations.
    FAIL-OPEN — returns an error dict on any exception."""
    import json as _json

    if not DQ_DB_READY:
        return {"enabled": False,
                "message": "Decision Quality DB not ready.",
                "generated_at": now_utc().isoformat()}

    conn = _learning_conn()
    if conn is None:
        return {"enabled": True, "error": "db_unavailable",
                "generated_at": now_utc().isoformat()}

    try:
        cur = conn.cursor()
        cur.execute(
            """SELECT inst, direction, edge_score, verdict, components,
                      dc_warnings_count, outcome, outcome_r, mfe_r, mae_r,
                      time_in_trade_min, exit_reason, created_at
               FROM decision_snapshots
               WHERE outcome IS NOT NULL
               ORDER BY created_at DESC LIMIT 500"""
        )
        rows = cur.fetchall()
        cur.execute("SELECT COUNT(*) FROM decision_snapshots")
        total_captured = (cur.fetchone() or [0])[0]
        cur.close()
        conn.close()
    except Exception as exc:
        try:
            conn.close()
        except Exception:
            pass
        return {"enabled": True, "error": str(exc),
                "generated_at": now_utc().isoformat()}

    total_resolved = len(rows)
    MIN_SAMPLES    = 5

    if total_resolved == 0:
        return {
            "enabled":           True,
            "total_captured":    total_captured,
            "pending":           len(_DQ_PENDING_BY_SETUP),
            "unmatched_closures": _DQ_UNMATCHED_CLOSURES,
            "resolved":          0,
            "message":           ("No resolved trades yet — snapshots populate as "
                                  "READY setups are evaluated, outcomes attach when "
                                  "trades close."),
            "component_performance": {},
            "duplicate_impact":      {},
            "recommendations":       [],
            "generated_at":          now_utc().isoformat(),
        }

    # ── Parse rows ────────────────────────────────────────────────────────────
    COMP_NAMES = ("BOS", "CHOCH", "Sweep", "VWAP", "Volume", "CVD", "Session")

    wins   = 0; losses = 0; r_vals = []
    comp_stats: dict = {
        c: {"pw": 0, "pt": 0, "aw": 0, "at": 0, "r_vals": []}
        for c in COMP_NAMES
    }
    rows_dup    = []   # rows with dc_warnings_count > 0
    rows_no_dup = []   # rows with dc_warnings_count == 0

    for row in rows:
        # JSONB → Python: psycopg2 may return a string or a parsed object
        comps_raw = row[4]
        if isinstance(comps_raw, str):
            try:
                comps_raw = _json.loads(comps_raw)
            except Exception:
                comps_raw = []
        comps_raw = comps_raw or []

        outcome  = (row[6] or "").strip()
        r_val    = row[7]
        dc_count = row[5] or 0

        is_win  = "Win"  in outcome
        is_loss = "Loss" in outcome
        if is_win:
            wins += 1
        elif is_loss:
            losses += 1
        if r_val is not None:
            try:
                r_vals.append(float(r_val))
            except Exception:
                pass

        present = set(
            c.get("component")
            for c in comps_raw
            if c.get("component") and (c.get("points") or 0) > 0
        )

        for comp in COMP_NAMES:
            if comp in present:
                comp_stats[comp]["pt"] += 1
                if is_win:
                    comp_stats[comp]["pw"] += 1
                if r_val is not None:
                    try:
                        comp_stats[comp]["r_vals"].append(float(r_val))
                    except Exception:
                        pass
            else:
                comp_stats[comp]["at"] += 1
                if is_win:
                    comp_stats[comp]["aw"] += 1

        if dc_count > 0:
            rows_dup.append(row)
        else:
            rows_no_dup.append(row)

    # ── Component performance table ───────────────────────────────────────────
    def _pct(wins, total):
        return round(100 * wins / total, 1) if total > 0 else None

    component_performance: dict = {}
    for comp, s in comp_stats.items():
        wp = _pct(s["pw"], s["pt"])
        wa = _pct(s["aw"], s["at"])
        ar = round(sum(s["r_vals"]) / len(s["r_vals"]), 2) if s["r_vals"] else None
        delta = round(wp - wa, 1) if (wp is not None and wa is not None) else None
        component_performance[comp] = {
            "win_rate_present": wp, "win_rate_absent": wa,
            "avg_r_present": ar,   "present_count": s["pt"],
            "absent_count":  s["at"], "predictive_delta": delta,
        }

    # Sort by predictive_delta (highest first)
    ranked = sorted(
        [(c, v) for c, v in component_performance.items()
         if v["predictive_delta"] is not None and v["present_count"] >= MIN_SAMPLES],
        key=lambda x: x[1]["predictive_delta"] or 0, reverse=True,
    )
    top_components    = [{"component": c, **v} for c, v in ranked[:3]]
    bottom_components = [{"component": c, **v} for c, v in ranked[-3:]]

    # ── Duplicate impact ──────────────────────────────────────────────────────
    def _wr(rlist):
        if not rlist:
            return None
        w = sum(1 for r in rlist if "Win" in (r[6] or ""))
        return round(100 * w / len(rlist), 1)

    duplicate_impact = {
        "with_warnings":    {"count": len(rows_dup),    "win_rate": _wr(rows_dup)},
        "without_warnings": {"count": len(rows_no_dup), "win_rate": _wr(rows_no_dup)},
    }
    dup_delta = None
    wd  = duplicate_impact["with_warnings"]["win_rate"]
    wod = duplicate_impact["without_warnings"]["win_rate"]
    if wd is not None and wod is not None:
        dup_delta = round(wd - wod, 1)

    # ── Recommendations ───────────────────────────────────────────────────────
    recommendations: list = []

    for comp, perf in component_performance.items():
        d = perf.get("predictive_delta"); pt = perf.get("present_count", 0)
        if d is None or pt < MIN_SAMPLES:
            continue
        if d >= 15:
            recommendations.append({
                "priority": "high", "component": comp,
                "text": (f"{comp}: +{d:.0f}pp win-rate lift when present "
                         f"(n={pt}). Strong predictor."),
            })
        elif d <= -15:
            recommendations.append({
                "priority": "review", "component": comp,
                "text": (f"{comp}: {d:.0f}pp win-rate when present "
                         f"(n={pt}). Weak/negative — review weighting."),
            })

    if dup_delta is not None and abs(dup_delta) >= 10:
        nd = min(len(rows_dup), len(rows_no_dup))
        if nd >= MIN_SAMPLES:
            txt = ("higher" if dup_delta > 0 else "lower")
            recommendations.append({
                "priority": "info", "component": "duplicate_evidence",
                "text": (f"Duplicate-evidence warnings correlate with {txt} "
                         f"win rate ({dup_delta:+.0f}pp). Review double-counting."),
            })

    if not recommendations:
        need = max(0, 20 - total_resolved)
        recommendations.append({
            "priority": "info",
            "text": (f"No strong signals yet. "
                     f"{'Collect more data (' + str(need) + '+ more trades needed).' if need > 0 else 'Model appears calibrated — keep monitoring.'}"),
        })

    # ── Overall stats ─────────────────────────────────────────────────────────
    overall_win_rate = _pct(wins, total_resolved)
    avg_r = round(sum(r_vals) / len(r_vals), 2) if r_vals else None

    return {
        "enabled":            True,
        "total_captured":     total_captured,
        "pending":            len(_DQ_PENDING_BY_SETUP),
        "unmatched_closures": _DQ_UNMATCHED_CLOSURES,
        "resolved":           total_resolved,
        "wins":               wins,
        "losses":             losses,
        "overall_win_rate":   overall_win_rate,
        "avg_r":              avg_r,
        "component_performance": component_performance,
        "top_components":     top_components,
        "bottom_components":  bottom_components,
        "duplicate_impact":   duplicate_impact,
        "dup_delta":          dup_delta,
        "recommendations":    recommendations,
        "generated_at":       now_utc().isoformat(),
    }


def _make_tfa_ready_id(inst, direction, ts):
    """Build a collision-resistant ready_id from instrument, direction, and UTC ts."""
    return "%s::%s::%s" % (inst, direction, ts.strftime("%Y%m%dT%H%M%SZ"))


def _record_ready_decision(inst, direction, mode, edge_score, eq_score, strategy,
                            bias, structure_ok, zone_ok, vwap_ok, cvd_ok,
                            session, vol_regime, price):
    """INSERT a new TFA row when the final READY verdict fires (post-all-vetoes).
    Deduplicates repeated webhooks: same instrument + direction within 5 minutes
    = same setup still active, skip.  FAIL-OPEN."""
    if not TFA_DB_READY:
        return
    try:
        ts    = datetime.now(timezone.utc)
        _last = LAST_TFA_BY_INST.get(inst)
        if _last:
            age_s = (ts - _last["ts"]).total_seconds()
            if _last["direction"] == direction and age_s < 300:
                return
        ready_id = _make_tfa_ready_id(inst, direction, ts)
        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """INSERT INTO trade_failure_analysis
               (ready_id, instrument, direction, mode, edge_score, entry_quality_score,
                strategy, bias, structure_ok, zone_ok, vwap_ok, cvd_ok, session,
                vol_regime, price_at_ready, ready_at, schema_version)
               VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,1)
               ON CONFLICT (ready_id) DO NOTHING""",
            (ready_id, inst, direction, mode, edge_score, eq_score, strategy, bias,
             structure_ok, zone_ok, vwap_ok, cvd_ok, session, vol_regime, price, ts),
        )
        conn.commit()
        cur.close()
        conn.close()
        PENDING_TFA_BY_INST[inst] = ready_id
        LAST_TFA_BY_INST[inst]    = {"ready_id": ready_id, "direction": direction, "ts": ts}
        logger.debug("TFA READY recorded %s → %s", ready_id, inst)
    except Exception as exc:
        logger.debug("_record_ready_decision fail-open: %s", exc)


def _mark_tfa_triggered(inst, source, entry_price=None):
    """UPDATE the TFA row as triggered when the gateway confirms send/simulated.
    Stores the ready_id in LIVE_TFA_BY_INST so _complete_tfa_record can find it
    at close time even if a new READY fires for the same instrument first.
    FAIL-OPEN."""
    if not TFA_DB_READY:
        return
    try:
        ready_id = PENDING_TFA_BY_INST.get(inst)
        if not ready_id:
            return
        ts_now  = datetime.now(timezone.utc)
        lag_sec = None
        _last   = LAST_TFA_BY_INST.get(inst)
        if _last and _last.get("ts"):
            lag_sec = round((ts_now - _last["ts"]).total_seconds(), 1)
        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """UPDATE trade_failure_analysis
               SET triggered=TRUE, triggered_at=%s, trigger_source=%s,
                   trigger_lag_sec=%s, entry_price=%s
               WHERE ready_id=%s AND triggered=FALSE""",
            (ts_now, source, lag_sec, entry_price, ready_id),
        )
        conn.commit()
        cur.close()
        conn.close()
        LIVE_TFA_BY_INST[inst] = ready_id
        logger.debug("TFA TRIGGERED %s src=%s lag=%.1fs", ready_id, source, lag_sec or 0)
    except Exception as exc:
        logger.debug("_mark_tfa_triggered fail-open: %s", exc)


def _classify_failure_mode_tfa(mt, ctx, bias=None, vol_regime=None, eq_score=None):
    """Extended failure classifier for the TFA.  Calls _derive_trade_label for the
    standard categories then overlays TFA-specific modes: WRONG_BIAS, POOR_LOCATION,
    VOLATILITY_MISMATCH.  Returns (failure_mode, failure_detail | None).
    When mfe_r and mae_r are both absent from mt (price-poll close path), a
    'partial: mfe/mae unavailable' suffix is appended to failure_detail so
    downstream consumers know the record has incomplete analytics.  NULL is never
    treated as zero — _derive_trade_label handles None correctly.
    FAIL-OPEN: returns ('UNCATEGORIZED', None) on any error."""
    def _partial_flag(fm, fd):
        """Annotate records where MFE/MAE were unavailable at close time."""
        if mt.get("mfe_r") is None and mt.get("mae_r") is None:
            sfx = "partial: mfe/mae unavailable"
            fd  = (fd + "; " + sfx) if fd else sfx
        return fm, fd
    try:
        base_label = _derive_trade_label(mt, ctx)
        outcome    = (mt.get("outcome") or "").strip()
        is_win     = "Win" in outcome or base_label == "WIN"
        if is_win or base_label in ("TP1_THEN_BE", "BREAKEVEN"):
            return _partial_flag(base_label, None)
        direction = (mt.get("direction") or "").strip()
        _bias     = (bias or "").upper()
        if _bias and direction:
            if direction == "Long"  and "BEAR" in _bias:
                return _partial_flag("WRONG_BIAS", "Bias was %s at entry" % bias)
            if direction == "Short" and "BULL" in _bias:
                return _partial_flag("WRONG_BIAS", "Bias was %s at entry" % bias)
        if eq_score is not None:
            try:
                if float(eq_score) < 60:
                    return _partial_flag("POOR_LOCATION", "Entry quality %d at entry" % round(float(eq_score)))
            except Exception:
                pass
        if vol_regime and "EXTREME" in str(vol_regime).upper():
            return _partial_flag("VOLATILITY_MISMATCH", "Vol regime: %s" % vol_regime)
        return _partial_flag(base_label, None)
    except Exception:
        return "UNCATEGORIZED", None


def _complete_tfa_record(ready_id, mt, bias=None, vol_regime=None, eq_score=None):
    """UPDATE the TFA row with the final outcome + failure classification when
    a managed trade closes.  Fires a 25-trade Discord summary every 25 completions.
    FAIL-OPEN: any DB error is swallowed and logged at DEBUG."""
    if not TFA_DB_READY or not ready_id:
        return
    try:
        ctx        = mt.get("learning_ctx") or {}
        outcome    = mt.get("outcome")
        exit_price = mt.get("exit_price")
        mfe_r      = mt.get("mfe_r")
        mae_r      = mt.get("mae_r")
        r_multiple = mt.get("r_multiple")
        opened_at  = mt.get("registered_at")
        closed_at  = mt.get("closed_at")
        duration_min = None
        try:
            if opened_at and closed_at:
                duration_min = round(
                    (datetime.fromisoformat(closed_at) -
                     datetime.fromisoformat(opened_at)).total_seconds() / 60.0, 1)
        except Exception:
            pass
        failure_mode, failure_detail = _classify_failure_mode_tfa(
            mt, ctx, bias=bias, vol_regime=vol_regime, eq_score=eq_score)
        ts_now = datetime.now(timezone.utc)
        conn   = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """UPDATE trade_failure_analysis
               SET outcome=%s, exit_price=%s, mfe_r=%s, mae_r=%s, r_multiple=%s,
                   duration_min=%s, completed_at=%s, failure_mode=%s, failure_detail=%s
               WHERE ready_id=%s""",
            (outcome, exit_price, mfe_r, mae_r, r_multiple,
             duration_min, ts_now, failure_mode, failure_detail, ready_id),
        )
        conn.commit()
        cur.execute(
            "SELECT COUNT(*) FROM trade_failure_analysis WHERE completed_at IS NOT NULL")
        row   = cur.fetchone()
        total = int((row[0] if row else 0) or 0)
        cur.close()
        conn.close()
        logger.debug("TFA COMPLETE %s fm=%s r=%.2f", ready_id, failure_mode, float(r_multiple or 0))
        if total and total % 25 == 0:
            _enqueue_slow(_generate_failure_summary, total)
    except Exception as exc:
        logger.debug("_complete_tfa_record fail-open: %s", exc)


def _expire_stale_tfa_records():
    """Mark READY decisions older than 2 hours with no trigger as NOT_TRIGGERED.
    Called from the 60-second snapshot daemon (every 30 iterations = every 30 min).
    FAIL-OPEN."""
    if not TFA_DB_READY:
        return
    try:
        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """UPDATE trade_failure_analysis
               SET failure_mode='NOT_TRIGGERED', outcome='not_triggered',
                   completed_at=NOW()
               WHERE triggered=FALSE AND completed_at IS NULL
                 AND ready_at < NOW() - INTERVAL '2 hours'""")
        conn.commit()
        cur.close()
        conn.close()
    except Exception as exc:
        logger.debug("_expire_stale_tfa_records fail-open: %s", exc)


def _generate_failure_summary(total_count=None):
    """Query all completed TFA records, compute failure-mode distribution, and post
    a Discord summary.  Called every 25 completions via _enqueue_slow.  FAIL-OPEN."""
    if not TFA_DB_READY:
        return
    try:
        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor()
        cur.execute(
            """SELECT failure_mode, COUNT(*) AS cnt,
                      ROUND(AVG(r_multiple)::numeric, 2) AS avg_r,
                      ROUND(AVG(mfe_r)::numeric, 2)      AS avg_mfe,
                      SUM(CASE WHEN outcome='Win' THEN 1 ELSE 0 END) AS wins
               FROM trade_failure_analysis
               WHERE completed_at IS NOT NULL
               GROUP BY failure_mode
               ORDER BY cnt DESC
               LIMIT 15""")
        rows   = cur.fetchall()
        cur.execute(
            """SELECT COUNT(*),
                      SUM(CASE WHEN outcome='Win' THEN 1 ELSE 0 END)
               FROM trade_failure_analysis WHERE completed_at IS NOT NULL""")
        totrow = cur.fetchone() or (0, 0)
        cur.close()
        conn.close()
        total = int(totrow[0] or 0)
        wins  = int(totrow[1] or 0)
        if not total:
            return
        header = "**Trade Failure Analyzer \u2014 %d Completed Trades**" % total
        wr_str = "Win Rate: **%d/%d (%d%%)**" % (wins, total, round(100 * wins / total))
        sep    = "-" * 56
        col    = "%-26s %5s %7s %8s %6s" % ("Mode", "Count", "AvgR", "AvgMFE", "WinR")
        rows_s = [header, wr_str, "", "```", col, sep]
        for mode, cnt, avg_r, avg_mfe, w in rows:
            wr = "%d%%" % round(100 * w / cnt) if cnt else "-"
            rows_s.append("%-26s %5d %7.2f %8.2f %6s" % (
                (mode or "unknown")[:26], cnt,
                float(avg_r or 0), float(avg_mfe or 0), wr))
        rows_s.append("```")
        msg = "\n".join(rows_s)
        url = os.environ.get("DISCORD_WEBHOOK_URL", "")
        if url and DISCORD_LIVE_ENABLED:
            try:
                requests.post(url, json={"content": msg[:1990]}, timeout=8)
            except Exception:
                pass
        logger.info("TFA 25-trade summary posted: %d completed, %d/%d wins", total, wins, total)
    except Exception as exc:
        logger.debug("_generate_failure_summary fail-open: %s", exc)


def _check_market_state_cache_db_ready():
    """Probe the market_state_cache table (no DDL) and set MARKET_STATE_CACHE_DB_READY.
    FAIL-OPEN: a missing table / unavailable DB disables all market-state persistence."""
    global MARKET_STATE_CACHE_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM market_state_cache LIMIT 1")
            cur.fetchone()
        MARKET_STATE_CACHE_DB_READY = True
        logger.info("market_state_cache table ready")
    except Exception as exc:
        logger.warning(
            "market_state_cache table unavailable (market-state persistence disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _save_market_state(key, data):
    """Upsert one entry in market_state_cache. Called from the fast / data-only
    webhook arms and from the slow-task worker — NOT inside shared locks. FAIL-OPEN."""
    if not MARKET_STATE_CACHE_DB_READY:
        return
    try:
        import json as _json
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO market_state_cache (key, data, schema_version, updated_at)
                       VALUES (%s, %s::jsonb, %s, NOW())
                       ON CONFLICT (key) DO UPDATE
                         SET data           = EXCLUDED.data,
                             schema_version = EXCLUDED.schema_version,
                             updated_at     = EXCLUDED.updated_at""",
                    (key, _json.dumps(data, default=str), _MSC_SCHEMA_VERSION),
                )
        finally:
            conn.close()
    except Exception as exc:
        logger.debug("_save_market_state(%r) fail-open: %s", key, exc)


def _load_market_state(key, max_age_sec=None):
    """Return the data dict for `key` if it exists and is within `max_age_sec` seconds
    of its last update. Returns None if absent, stale, or on any error. FAIL-OPEN."""
    if not MARKET_STATE_CACHE_DB_READY:
        return None
    try:
        import json as _json
        conn = _learning_conn()
        if conn is None:
            return None
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT data, updated_at FROM market_state_cache WHERE key = %s",
                    (key,),
                )
                row = cur.fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        data_raw, updated_at = row
        if max_age_sec is not None and updated_at:
            age_sec = (now_utc() - updated_at).total_seconds()
            if age_sec > max_age_sec:
                return None
        return (data_raw if isinstance(data_raw, dict) else _json.loads(data_raw or "{}"))
    except Exception as exc:
        logger.debug("_load_market_state(%r) fail-open: %s", key, exc)
        return None


def _restore_market_state_from_db():
    """Boot restore: load CVD state, volume-spike timestamps, TradersPost dedup
    fingerprints, AUTO_FIRED_KEYS, and the ALERT_HISTORY snapshot from
    market_state_cache if each entry is within its freshness window.

    Safety invariants (enforced unconditionally):
    - NEVER submits a TradersPost / broker order.
    - NEVER sends a Discord message or creates a journal entry.
    - NEVER creates a thesis transition or shadow evaluation.
    - NEVER marks any verdict as actionable.
    - Restored READY state is intentionally NOT restored — only new post-restart
      market evidence can create an actionable READY event.
    FAIL-OPEN throughout."""
    if not MARKET_STATE_CACHE_DB_READY:
        return
    restored_cvd = restored_vol = restored_tp = restored_auto = restored_alerts = 0

    # ── CVD committed state (MAY RESTORE IF FRESH) ────────────────────────────
    for inst in _ALERT_INSTRUMENTS:
        try:
            data = _load_market_state("cvd::" + inst, _MSC_CVD_MAX_AGE_SEC)
            if data and data.get("state") and data.get("ts"):
                CVD_BY_TICKER[inst] = data
                restored_cvd += 1
                logger.info("Market-state restore: CVD %s state=%s (from cache)",
                            inst, data.get("state"))
        except Exception as exc:
            logger.debug("CVD restore fail-open [%s]: %s", inst, exc)

    # ── Volume-spike timestamps (MAY RESTORE IF FRESH) ────────────────────────
    for inst in _ALERT_INSTRUMENTS:
        try:
            data = _load_market_state("volume_spike::" + inst, _MSC_VOLUME_SPIKE_MAX_AGE_SEC)
            if data and data.get("ts"):
                VOLUME_SPIKE_BY_TICKER[inst] = {"ts": data["ts"]}
                restored_vol += 1
                logger.info("Market-state restore: volume spike %s ts=%s (from cache)",
                            inst, data["ts"])
        except Exception as exc:
            logger.debug("Volume-spike restore fail-open [%s]: %s", inst, exc)

    # ── TradersPost duplicate-send guard (MUST PERSIST) ───────────────────────
    for inst in _ALERT_INSTRUMENTS:
        try:
            data = _load_market_state("traderspost_last::" + inst, _MSC_TP_DEDUP_MAX_AGE_SEC)
            if data and data.get("fingerprint") and data.get("epoch"):
                with _TRADERSPOST_LOCK:
                    _TRADERSPOST_LAST[inst] = (data["fingerprint"], float(data["epoch"]))
                restored_tp += 1
                logger.info("Market-state restore: TradersPost dedup %s (from cache)", inst)
        except Exception as exc:
            logger.debug("TradersPost dedup restore fail-open [%s]: %s", inst, exc)

    # ── AUTO_FIRED_KEYS — fire-once auto-trade dedup (MUST PERSIST) ───────────
    try:
        data = _load_market_state("auto_fired_keys", _MSC_AUTO_FIRED_MAX_AGE_SEC)
        if data:
            today_et = now_utc().astimezone(ET_TZ).strftime("%Y-%m-%d")
            if data.get("date_et") == today_et:
                raw_keys = data.get("keys", [])
                with AUTO_TRADE_LOCK:
                    for raw_key in raw_keys:
                        try:
                            k = tuple(raw_key) if isinstance(raw_key, list) else raw_key
                            AUTO_FIRED_KEYS.add(k)
                            restored_auto += 1
                        except Exception:
                            pass
                if restored_auto:
                    logger.info("Market-state restore: %d AUTO_FIRED_KEYS date=%s",
                                restored_auto, today_et)
            else:
                logger.info(
                    "Market-state restore: AUTO_FIRED_KEYS skipped — stale date "
                    "(stored=%s today=%s)", data.get("date_et"), today_et)
    except Exception as exc:
        logger.debug("AUTO_FIRED_KEYS restore fail-open: %s", exc)

    # ── ALERT_HISTORY snapshot (MAY RESTORE IF FRESH) ─────────────────────────
    try:
        data = _load_market_state("alert_history_snapshot", _MSC_ALERT_HISTORY_MAX_AGE_SEC)
        if data and isinstance(data.get("alerts"), list):
            alerts = data["alerts"]
            ALERT_HISTORY.clear()
            ALERT_HISTORY.extend(alerts[-100:])
            restored_alerts = len(ALERT_HISTORY)
            logger.info("Market-state restore: ALERT_HISTORY %d entries (from cache)",
                        restored_alerts)
    except Exception as exc:
        logger.debug("ALERT_HISTORY restore fail-open: %s", exc)

    # ── Execution gateway mode override (PERSIST ACROSS RESTARTS) ────────────
    try:
        global _EXECUTION_MODE_RUNTIME_OVERRIDE, TRADING_MODE
        data = _load_market_state("exec_mode_override")
        saved_mode = (data or {}).get("mode", "")
        if saved_mode in _VALID_EXECUTION_MODES:
            with _EXECUTION_MODE_OVERRIDE_LOCK:
                _EXECUTION_MODE_RUNTIME_OVERRIDE = saved_mode
            logger.info("Market-state restore: execution mode=%s (from cache)", saved_mode)
    except Exception as exc:
        logger.debug("Exec mode restore fail-open: %s", exc)

    # ── Trading mode (SCALP / SWING) ──────────────────────────────────────────
    try:
        data = _load_market_state("trading_mode_override")
        saved_tm = str((data or {}).get("mode", "")).upper()
        if saved_tm in MODES:
            TRADING_MODE = saved_tm
            logger.info("Market-state restore: trading_mode=%s (from cache)", TRADING_MODE)
    except Exception as exc:
        logger.debug("Trading mode restore fail-open: %s", exc)

    logger.info(
        "Market-state restore complete: CVD=%d vol=%d tp_dedup=%d "
        "auto_keys=%d alerts=%d",
        restored_cvd, restored_vol, restored_tp, restored_auto, restored_alerts,
    )


def _persist_auto_fired_key(key):
    """Persist the full AUTO_FIRED_KEYS set after a new key is added.
    Snapshots the set under AUTO_TRADE_LOCK then writes outside the lock. FAIL-OPEN."""
    if not MARKET_STATE_CACHE_DB_READY:
        return
    try:
        today_et = now_utc().astimezone(ET_TZ).strftime("%Y-%m-%d")
        with AUTO_TRADE_LOCK:
            keys_snapshot = list(AUTO_FIRED_KEYS)
        serialized = [list(k) if isinstance(k, tuple) else k for k in keys_snapshot]
        _save_market_state("auto_fired_keys", {"keys": serialized, "date_et": today_et})
    except Exception as exc:
        logger.debug("_persist_auto_fired_key fail-open: %s", exc)


def _alert_history_snapshot_loop():
    """Background daemon: snapshot the last 100 ALERT_HISTORY entries to
    market_state_cache every 60 seconds so boot-restore has fresh scoring context.
    Sleeps first so a restart doesn't immediately overwrite a good snapshot. FAIL-OPEN."""
    import time as _t
    _tfa_expire_ticks = 0
    while True:
        try:
            _t.sleep(60)
            if MARKET_STATE_CACHE_DB_READY:
                snapshot = list(ALERT_HISTORY)[-100:]
                _save_market_state("alert_history_snapshot", {"alerts": snapshot})
            _tfa_expire_ticks += 1
            if _tfa_expire_ticks % 30 == 0:
                _expire_stale_tfa_records()
        except Exception as exc:
            logger.debug("_alert_history_snapshot_loop fail-open: %s", exc)


# throughout: when the table / DB is unavailable the manager runs in-memory only and
# a restart simply clears the (display-only) monitor.
MANUAL_TRADE_DB_READY = False
MANUAL_TRADES         = {}                       # id -> trade dict (open working set)
MANUAL_TRADES_LOCK    = threading.RLock()
MANUAL_TRADE_MODES    = ("SCALP", "SWING")


def _check_manual_trade_db_ready():
    """Probe the manual_trades table (no DDL) and set MANUAL_TRADE_DB_READY. FAIL-OPEN:
    a missing table / unavailable DB disables persistence (the monitor runs in-memory
    only)."""
    global MANUAL_TRADE_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM manual_trades LIMIT 1")
            cur.fetchone()
        MANUAL_TRADE_DB_READY = True
        logger.info("manual_trades table ready")
    except Exception as exc:
        logger.warning("manual_trades table unavailable (manual-trade persistence disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _persist_manual_trade(trade):
    """Upsert a manual trade snapshot by id. FAIL-OPEN; the DB write is offloaded to
    the slow-task worker so a stall never delays the dashboard. The snapshot is
    captured synchronously so a later mutation can't corrupt this write. DISPLAY /
    local-tracking ONLY — never the money path."""
    if not MANUAL_TRADE_DB_READY or not trade or not trade.get("id"):
        return
    tid        = trade["id"]
    snapshot   = {k: v for k, v in trade.items() if k not in ("min_r", "max_r")}
    status     = trade.get("status", "open")
    instrument = trade.get("symbol")

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO manual_trades (id, payload, status, instrument)
                       VALUES (%s, %s, %s, %s)
                       ON CONFLICT (id)
                       DO UPDATE SET payload    = EXCLUDED.payload,
                                     status     = EXCLUDED.status,
                                     instrument = EXCLUDED.instrument,
                                     updated_at = now()""",
                    (tid, psycopg2.extras.Json(snapshot), status, instrument),
                )
        except Exception as exc:
            logger.warning("manual trade persist failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _load_manual_trades_from_db():
    """Rehydrate OPEN manual trades from Postgres at boot so the advisory monitor
    survives a restart. FAIL-OPEN; INERT — only repopulates the in-memory cache (no
    alert / journal / broker side-effect)."""
    if not MANUAL_TRADE_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT payload FROM manual_trades WHERE status = 'open' ORDER BY updated_at DESC")
            rows = cur.fetchall()
        restored = 0
        with MANUAL_TRADES_LOCK:
            for (payload,) in rows:
                if isinstance(payload, dict) and payload.get("id"):
                    MANUAL_TRADES[payload["id"]] = dict(payload)
                    restored += 1
        logger.info("Manual trades restored from DB: %d open", restored)
    except Exception as exc:
        logger.warning("manual trade load failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _manual_px(x):
    """Format a price / points value for advisory text (2dp); '—' when missing."""
    try:
        return "%.2f" % float(x)
    except (TypeError, ValueError):
        return "—"


def _manual_coerce_float(v):
    try:
        f = float(v)
        if math.isfinite(f):
            return f
    except (TypeError, ValueError):
        pass
    return None


def _parse_manual_entry_time(value):
    """Best-effort parse of a user-supplied entry time to a UTC ISO string. Accepts
    ISO-8601 (tz-aware or naive) or a datetime-local 'YYYY-MM-DDTHH:MM'. A naive value
    is treated as Eastern Time (the dashboard's display zone). Returns (iso|None, raw).
    DISPLAY-ONLY — the entry time never drives the gate or money path."""
    raw = "" if value is None else str(value).strip()
    if not raw:
        return None, ""
    try:
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=ET_TZ)
        return dt.astimezone(timezone.utc).isoformat(), raw
    except (ValueError, TypeError):
        return None, raw


def _build_manual_trade(data):
    """Strictly validate a manual-trade creation payload. Returns (trade, None) on
    success or (None, error_message). ADVISORY-ONLY input — never a money path, so
    these prices are stored for monitoring and are never sent to a broker."""
    symbol = _instrument_from_text(data.get("symbol"))
    if symbol is None:
        return None, "A valid symbol (MGC, MNQ, MES, or MYM) is required."

    draw = str(data.get("direction", "")).strip().lower()
    if draw.startswith("l"):
        direction = "Long"
    elif draw.startswith("s"):
        direction = "Short"
    else:
        return None, "Direction must be LONG or SHORT."

    entry = _manual_coerce_float(data.get("entry"))
    stop  = _manual_coerce_float(data.get("stop"))
    if entry is None or stop is None:
        return None, "Entry and stop must be valid numbers."
    if entry == stop:
        return None, "Entry and stop cannot be equal."

    t1 = _manual_coerce_float(data.get("target1"))
    t2 = _manual_coerce_float(data.get("target2"))
    if t1 is None or t2 is None:
        return None, "Target 1 and Target 2 must be valid numbers."
    t3 = _manual_coerce_float(data.get("target3"))   # optional

    contracts_raw = _manual_coerce_float(data.get("contracts", 1))
    if contracts_raw is None or contracts_raw != int(contracts_raw):
        return None, "Contracts must be a whole number."   # reject 1.5 etc. (int() would silently truncate)
    contracts = int(contracts_raw)
    if contracts < 1 or contracts > 1000:
        return None, "Contracts must be between 1 and 1000."

    mode = str(data.get("mode", "")).strip().upper()
    if mode not in MANUAL_TRADE_MODES:
        return None, "Mode must be SCALP or SWING."

    # Direction must agree with the stop & target placement (catches transposed inputs).
    if direction == "Long":
        if not (stop < entry):
            return None, "For a LONG, the stop must be below the entry."
        if not (t1 > entry and t2 > entry and (t3 is None or t3 > entry)):
            return None, "For a LONG, targets must be above the entry."
    else:
        if not (stop > entry):
            return None, "For a SHORT, the stop must be above the entry."
        if not (t1 < entry and t2 < entry and (t3 is None or t3 < entry)):
            return None, "For a SHORT, targets must be below the entry."

    entry_iso, entry_raw = _parse_manual_entry_time(data.get("entry_time"))
    reason = str(data.get("reason", "") or "").strip()[:500]

    return {
        "id":             "%s-%d-%s" % (symbol, int(time.time() * 1000), uuid.uuid4().hex[:6]),
        "symbol":         symbol,
        "direction":      direction,
        "entry_price":    entry,
        "stop_loss":      stop,
        "target1":        t1,
        "target2":        t2,
        "target3":        t3,
        "contracts":      contracts,
        "mode":           mode,
        "reason":         reason,
        "entry_time":     entry_iso,
        "entry_time_raw": entry_raw,
        "opened_at":      now_utc().isoformat(),
        "status":         "open",
    }, None


def _manual_next_review(mode, now=None):
    """Next advisory review time. SCALP reviews at the next 5-minute boundary; SWING on
    a ~30-minute cadence. DISPLAY-ONLY."""
    now  = now or now_utc()
    step = 5 if mode == "SCALP" else 30
    nxt  = now.replace(second=0, microsecond=0)
    minute = (now.minute // step + 1) * step
    if minute >= 60:
        nxt = (nxt + timedelta(hours=1)).replace(minute=minute - 60)
    else:
        nxt = nxt.replace(minute=minute)
    return nxt


def _stop_at_or_past_be(direction, stop, entry):
    """True when the stop is already at / beyond breakeven (entry)."""
    return (stop >= entry) if direction == "Long" else (stop <= entry)


def compute_manual_trade_management(trade, analysis=None):
    """ADVISORY-ONLY live management read for one manually-entered position.

    Reuses the existing read-only engines (full_analysis, compute_pnl,
    compute_distances) and NEVER mutates trading state, feeds the gate / sizing /
    dedupe, or sends a broker order. Degrades gracefully: a missing / stale price (or
    a zero-risk trade) yields a 'monitor unavailable' status rather than fabricated
    guidance. The only field it writes back on `trade` is the observed min_r / max_r
    (in-memory only) used for the honest 'poor entry but recovering' read."""
    symbol    = trade.get("symbol")
    direction = trade.get("direction", "Long")
    entry     = trade.get("entry_price")
    stop      = trade.get("stop_loss")
    mode      = trade.get("mode", "SCALP")
    is_long   = (direction == "Long")

    out = {
        "id":            trade.get("id"),
        "symbol":        symbol,
        "direction":     direction,
        "mode":          mode,
        "entry_price":   entry,
        "stop_loss":     stop,
        "target1":       trade.get("target1"),
        "target2":       trade.get("target2"),
        "target3":       trade.get("target3"),
        "contracts":     trade.get("contracts"),
        "reason":        trade.get("reason"),
        "entry_time":    trade.get("entry_time"),
        "entry_time_et": (fmt_et(trade.get("entry_time")) if trade.get("entry_time")
                          else (trade.get("entry_time_raw") or "")),
        "opened_at":     trade.get("opened_at"),
        "opened_at_et":  fmt_et(trade.get("opened_at")),
        "next_review_et": fmt_et(_manual_next_review(mode)),
        "warnings":         [],
        "what_improves":    [],
        "what_invalidates": [],
        "entry_assessment": None,
        "advisory_only":    True,
    }

    # Live analysis (read-only). The caller may pass a shared instance so full_analysis
    # is computed once per distinct symbol per poll and fanned out across its trades.
    if analysis is None:
        try:
            analysis = full_analysis(ticker_override=symbol)
        except Exception as exc:
            analysis = None
            logger.warning("manual-trade analysis failed for %s: %s", symbol, exc)
    a = analysis or {}

    # Current price (display source). No live price -> monitor unavailable.
    price = a.get("display_price")
    psrc  = a.get("price_source")
    if price is None:
        price, psrc = display_price_for(symbol)
    out["current_price"] = price
    out["price_source"]  = psrc

    risk = abs(entry - stop) if (entry is not None and stop is not None) else None
    if price is None or not risk:
        out["status"]                = "unavailable"
        out["thesis_status"]         = "UNKNOWN"
        out["recommendation"]        = "MONITOR"
        out["action"]                = "MONITOR"
        out["invalidated"]           = False
        out["recommendation_reason"] = (
            f"No live price for {symbol} right now — monitoring paused (no guidance fabricated)."
            if price is None else "Entry and stop are equal — cannot compute risk."
        )
        return out

    out["status"] = "ok"

    # ── Live math (reuse the existing read-only helpers) ──
    pnl_trade = {"direction": direction, "entry_price": entry,
                 "contracts": trade.get("contracts", 1), "symbol": symbol}
    dollar_pnl, pts_pnl = compute_pnl(pnl_trade, price)
    fav       = (price - entry) if is_long else (entry - price)
    current_r = fav / risk
    out["unrealized_pnl"]    = round(dollar_pnl, 2)
    out["unrealized_points"] = round(pts_pnl, 2)
    out["current_r"]         = round(current_r, 2)
    out["risk_points"]       = round(risk, 2)

    # compute_distances needs a non-None target2; bot positions (SWING 1:1, or a SCALP
    # before TP2 is set) can carry target2=None. Fall back to target1 for the DISTANCE
    # math only — t2_hit below still reads the real (possibly None) target2, so an
    # absent TP2 honestly reports dist_to_target2=None and target2_hit=False.
    _t2_dist = trade.get("target2")
    dist_trade = {"direction": direction, "target1": trade.get("target1"),
                  "target2": _t2_dist if _t2_dist is not None else trade.get("target1"),
                  "stop_loss": stop}
    to_t1, to_t2, to_stop = compute_distances(dist_trade, price)
    out["dist_to_stop"]    = round(to_stop, 2)
    out["dist_to_target1"] = round(to_t1, 2)
    out["dist_to_target2"] = round(to_t2, 2) if _t2_dist is not None else None
    t3_val = trade.get("target3")
    if t3_val is not None:
        out["dist_to_target3"] = round((t3_val - price) if is_long else (price - t3_val), 2)

    # Track observed extremes (in-memory only) for the 'recovering' read.
    prev_min = trade.get("min_r")
    prev_max = trade.get("max_r")
    trade["min_r"] = current_r if prev_min is None else min(prev_min, current_r)
    trade["max_r"] = current_r if prev_max is None else max(prev_max, current_r)

    # Position vs stop / targets (inclusive — price can sit exactly on a level).
    stop_breached = (price <= stop) if is_long else (price >= stop)
    t1_hit = (price >= trade["target1"]) if is_long else (price <= trade["target1"])
    t2_hit = bool(trade.get("target2") is not None and
                  ((price >= trade["target2"]) if is_long else (price <= trade["target2"])))
    t3_hit = bool(t3_val is not None and
                  ((price >= t3_val) if is_long else (price <= t3_val)))
    out["stop_breached"] = stop_breached
    out["target1_hit"]   = t1_hit
    out["target2_hit"]   = t2_hit
    out["target3_hit"]   = t3_hit

    # ── Live signal reads (all defensive / None-safe) ──
    sc          = str(a.get("structure_class") or "").lower()
    vwap_value  = a.get("vwap_value")
    vwap_status = str(a.get("vwap_status") or "").lower()
    nearest_supply = a.get("nearest_supply")
    nearest_demand = a.get("nearest_demand")
    market_open = a.get("market_open")
    vol = a.get("volatility") or {}

    structure_bullish = ("bullish" in sc)            # Bullish Trend / Bullish Attempt
    structure_bearish = ("bearish" in sc)
    confirmed_trend   = sc in ("bullish trend", "bearish trend")
    # Only an opposite *confirmed* trend (CHOCH-level) is strong enough to invalidate;
    # an Attempt (BOS-only) or a bias flip alone merely weakens the thesis.
    opposite_confirmed = (confirmed_trend and
                          ((is_long and structure_bearish) or ((not is_long) and structure_bullish)))
    opposite_soft = (((is_long and structure_bearish) or ((not is_long) and structure_bullish))
                     and not opposite_confirmed)

    vwap_ok      = (vwap_status == "ok" and vwap_value is not None)
    vwap_against = bool(vwap_ok and ((price < vwap_value) if is_long else (price > vwap_value)))
    near_stop    = (not stop_breached) and (to_stop <= 0.25 * risk)

    # Opposing zone sitting between price and the first target (resistance ahead of a
    # long / support ahead of a short).
    zone_ahead = None
    tgt1 = trade.get("target1")
    if is_long and nearest_supply is not None and tgt1 is not None \
            and price < nearest_supply < tgt1:
        zone_ahead = nearest_supply
    if (not is_long) and nearest_demand is not None and tgt1 is not None \
            and tgt1 < nearest_demand < price:
        zone_ahead = nearest_demand

    # ── Thesis status ──
    if stop_breached or opposite_confirmed:
        thesis = "INVALID"
    elif (current_r < 0) or opposite_soft or vwap_against or near_stop or (zone_ahead is not None):
        thesis = "WEAKENING"
    else:
        thesis = "VALID"

    # ── Warnings ──
    warnings = []
    if stop_breached:
        warnings.append(f"Price has reached or passed your stop at {_manual_px(stop)}.")
    if opposite_confirmed:
        warnings.append(f"Market structure flipped against you ({a.get('structure_class') or 'opposite trend'}).")
    elif opposite_soft:
        warnings.append(f"Early structure pressure against your direction ({a.get('structure_class') or '—'}).")
    if vwap_against and not stop_breached:
        warnings.append(f"Price is on the wrong side of VWAP ({_manual_px(vwap_value)}) for a {'long' if is_long else 'short'}.")
    if near_stop:
        warnings.append(f"Price is within {_manual_px(to_stop)} pts of your stop.")
    if zone_ahead is not None:
        warnings.append(f"An opposing {'supply' if is_long else 'demand'} zone at {_manual_px(zone_ahead)} sits before your first target.")
    if vol.get("status") == "ok" and vol.get("blocked"):
        warnings.append(f"Volatility is elevated ({vol.get('label') or 'high'}) — expect wider swings than normal.")
    out["warnings"] = warnings

    # ── Recommendation ──
    if stop_breached:
        rec, why = "EXIT", f"Your stop at {_manual_px(stop)} has been hit — the trade is invalidated; exit per your plan."
    elif thesis == "INVALID":
        rec = "EXIT"
        why = ("Your thesis is broken but you're in profit — bank it rather than give it back."
               if dollar_pnl > 0 else
               "Your thesis is broken and the trade is offside — cut the loss.")
    elif t3_hit or t2_hit:
        rec, why = "REDUCE", "You've reached a deeper target — scale out and trail your stop to protect the win."
    elif t1_hit:
        rec, why = "MOVE STOP", f"First target reached — take partial profit and move your stop to breakeven ({_manual_px(entry)})."
    elif current_r >= 1.0 and not _stop_at_or_past_be(direction, stop, entry):
        rec, why = "MOVE STOP", f"You're up about {current_r:.1f}R — move your stop to breakeven ({_manual_px(entry)}) to make this risk-free."
    elif thesis == "WEAKENING":
        if near_stop or current_r <= -0.5:
            rec, why = "REDUCE", "Momentum is against you and price is pressing your stop — consider trimming risk."
        else:
            rec, why = "HOLD", "Thesis is weakening but your stop is intact — hold and watch the listed risks closely."
    else:
        rec = "HOLD"
        why = (f"Thesis intact and the trade is working ({current_r:.1f}R) — let it run toward your targets."
               if current_r > 0 else
               "Thesis intact — give the trade room to your stop; no action needed yet.")

    # Market closed: pause and extend the review to the next open — never invalidate
    # a held position just because the session is shut.
    if market_open is False:
        out["next_review_et"] = a.get("next_open") or out["next_review_et"]
        if not stop_breached:
            # A held position is PAUSED while the session is shut — never invalidated by
            # (often stale) closed-market structure. Only a real stop-out keeps INVALID/EXIT.
            rec, why = "HOLD", "Market is closed — monitoring paused; reassess at the next session open."
            thesis = "PAUSED"

    out["thesis_status"]         = thesis
    out["recommendation"]        = rec
    out["recommendation_reason"] = why

    # ── Canonical advisory ACTION (display-only copilot verb) ──────────────────
    # Maps the existing state booleans onto the fixed action vocabulary the Main Brain
    # copilot surfaces: HOLD / REDUCE / TAKE PARTIAL / MOVE STOP TO BE / EXIT. This is
    # ADDITIVE — `recommendation` / `recommendation_reason` above are left untouched so
    # the legacy Manual Trade Manager card stays byte-stable. `invalidated` is True only
    # when the thesis is broken (stop hit or confirmed structure flip); a market-closed
    # PAUSE never invalidates a held position.
    at_be = _stop_at_or_past_be(direction, stop, entry)
    if thesis == "PAUSED":
        action_v, invalid_v = "HOLD", False
    elif stop_breached or opposite_confirmed:
        action_v, invalid_v = "EXIT", True
    elif t3_hit or t2_hit:
        action_v, invalid_v = "REDUCE", False
    elif t1_hit and not at_be:
        action_v, invalid_v = "TAKE PARTIAL", False
    elif current_r >= 1.0 and not at_be:
        action_v, invalid_v = "MOVE STOP TO BE", False
    elif thesis == "WEAKENING" and (near_stop or current_r <= -0.5):
        action_v, invalid_v = "REDUCE", False
    else:
        action_v, invalid_v = "HOLD", False
    out["action"]      = action_v
    out["invalidated"] = invalid_v

    # ── What would improve / invalidate the thesis ──
    improves, invalidates = [], []
    if is_long:
        if vwap_against:
            improves.append(f"Reclaim and hold above VWAP ({_manual_px(vwap_value)}).")
        improves.append("A bullish CHOCH / BOS confirming higher highs in your favor.")
        improves.append(f"Volume expansion driving price toward {_manual_px(tgt1)}.")
        invalidates.append(f"A decisive close below your stop at {_manual_px(stop)}.")
        invalidates.append("A confirmed bearish CHOCH (structure flips down).")
        if nearest_demand is not None:
            invalidates.append(f"Price accepting below the demand zone at {_manual_px(nearest_demand)}.")
    else:
        if vwap_against:
            improves.append(f"Lose and hold below VWAP ({_manual_px(vwap_value)}).")
        improves.append("A bearish CHOCH / BOS confirming lower lows in your favor.")
        improves.append(f"Volume expansion driving price toward {_manual_px(tgt1)}.")
        invalidates.append(f"A decisive close above your stop at {_manual_px(stop)}.")
        invalidates.append("A confirmed bullish CHOCH (structure flips up).")
        if nearest_supply is not None:
            invalidates.append(f"Price accepting above the supply zone at {_manual_px(nearest_supply)}.")
    out["what_improves"]    = improves
    out["what_invalidates"] = invalidates

    # ── Entry-quality read (honest, derived from observed action since monitoring) ──
    min_r = trade.get("min_r", current_r)
    recovering = (min_r <= -0.4 and current_r > min_r + 0.3 and current_r > -0.1)
    if recovering and current_r > 0:
        out["entry_assessment"] = (f"This trade went against you (low {min_r:.1f}R) and has recovered to "
                                   f"+{current_r:.1f}R — the entry was poorly timed; favor scaling out into "
                                   f"strength over expecting a clean runner.")
    elif recovering:
        out["entry_assessment"] = (f"Down to {min_r:.1f}R earlier, now {current_r:.1f}R and recovering — the "
                                   f"entry was early; manage risk tightly back toward breakeven.")
    elif current_r < 0:
        out["entry_assessment"] = (f"Currently offside at {current_r:.1f}R (worst {min_r:.1f}R). Hold only while "
                                   f"your stop and thesis are intact.")
    return out


# ── Manual-trade management TIMELINE (advisory / display-only) ────────────────
# A timestamped copilot log stored INSIDE the trade's JSONB payload (trade["timeline"]
# + trade["_tl_flags"] for idempotency) — NO schema change, NO DDL. Each milestone
# fires exactly once. This NEVER touches the gate / sizing / dedupe / broker path; it
# only annotates a manually-entered position. SINGLE WRITER: only call the updater on
# the STORED MANUAL_TRADES object under MANUAL_TRADES_LOCK (never a throwaway copy),
# and persist only when it reports a change.
_MANUAL_TIMELINE_MAX = 80

def _manual_tl_event(trade, code, text, fire_once=True):
    """Append one timeline event to `trade` IN PLACE. Idempotent per `code` when
    fire_once. Returns True iff a new event was appended. DISPLAY-ONLY."""
    if not isinstance(trade, dict):
        return False
    flags = trade.setdefault("_tl_flags", {})
    if fire_once and flags.get(code):
        return False
    tl  = trade.setdefault("timeline", [])
    now = now_utc()
    tl.append({
        "t":    now.isoformat(),
        "t_et": fmt_et(now.isoformat(), fmt="%H:%M"),
        "code": code,
        "text": text,
    })
    if len(tl) > _MANUAL_TIMELINE_MAX:
        del tl[:len(tl) - _MANUAL_TIMELINE_MAX]
    if fire_once:
        flags[code] = True
    return True

def _update_manual_trade_timeline(trade, mgmt):
    """Append milestone events (entry, +R moves, TP1/2/3, move-to-BE, weakening,
    invalidated) to a manual trade's timeline, each ONCE, from a management read.
    Returns True iff anything changed (so the caller persists only on change). Must be
    called on the STORED trade under MANUAL_TRADES_LOCK. DISPLAY-ONLY / fail-open."""
    if not isinstance(trade, dict) or not isinstance(mgmt, dict):
        return False
    changed  = False
    sym      = trade.get("symbol") or "?"
    dir_word = (trade.get("direction") or "").lower() or "trade"

    # 1) Entry — always the first line of the log.
    if not trade.get("timeline"):
        ep = trade.get("entry_price")
        changed |= _manual_tl_event(
            trade, "entered",
            "Entered %s %s at %s" % (dir_word, sym, _manual_px(ep)))

    if mgmt.get("status") != "ok":
        return changed

    cr  = mgmt.get("current_r")
    pts = mgmt.get("unrealized_points")

    # 2) Favorable R milestones (each fires once) + one adverse pullback marker.
    if isinstance(cr, (int, float)):
        for thr, code in ((0.5, "r_up_0_5"), (1.0, "r_up_1"),
                          (2.0, "r_up_2"), (3.0, "r_up_3")):
            if cr >= thr:
                ptxt = ((" (+%s pts)" % _manual_px(pts))
                        if isinstance(pts, (int, float)) and pts > 0 else "")
                changed |= _manual_tl_event(
                    trade, code, "Price moved +%.1fR in your favor%s" % (thr, ptxt))
        if cr <= -0.5:
            changed |= _manual_tl_event(
                trade, "r_dn_0_5", "Price pulled back to -0.5R against you")

    # 3) Target / breakeven milestones.
    if mgmt.get("target1_hit"):
        changed |= _manual_tl_event(trade, "tp1", "TP1 reached — take partial")
    if mgmt.get("target2_hit"):
        changed |= _manual_tl_event(trade, "tp2", "TP2 reached — scale out / trail stop")
    if mgmt.get("target3_hit"):
        changed |= _manual_tl_event(trade, "tp3", "TP3 reached — final target")
    if (isinstance(cr, (int, float)) and cr >= 1.0
            and not _stop_at_or_past_be(trade.get("direction") or "Long",
                                        trade.get("stop_loss"),
                                        trade.get("entry_price"))):
        changed |= _manual_tl_event(trade, "move_be", "Up 1R — move stop to breakeven")

    # 4) Thesis transitions.
    th = mgmt.get("thesis_status")
    if th == "WEAKENING":
        changed |= _manual_tl_event(
            trade, "weakening", "Momentum weakening — consider reducing risk")
    if mgmt.get("invalidated") or th == "INVALID" or mgmt.get("stop_breached"):
        changed |= _manual_tl_event(
            trade, "invalidated", "Thesis invalidated — exit per your plan")

    return changed


def _newest_manual_trade_for(inst):
    """Return a COPY of the newest OPEN manually-entered trade for `inst` (or None).

    Used by the Main Brain so a user-entered position turns the brain into a live
    copilot. Returns a shallow copy so callers never mutate the stored trade (the
    shared `timeline` list is read-only at the call site). DISPLAY-ONLY / fail-open."""
    if not inst:
        return None
    best = None
    try:
        with MANUAL_TRADES_LOCK:
            for t in MANUAL_TRADES.values():
                if instrument_of(t.get("symbol")) != inst:
                    continue
                status = t.get("status")
                if status and status != "open":
                    continue
                if best is None or (t.get("opened_at") or "") > (best.get("opened_at") or ""):
                    best = t
            if best is not None:
                best = dict(best)
    except Exception:
        best = None
    return best


def _bot_trade_mgmt_mirror(inst, at):
    """Throwaway manual-trade-shaped COPY of ONE tracked bot position, for the read-only
    manual-management engine (compute_manual_trade_management writes min_r/max_r back
    onto the dict it is handed). NEVER pass the live ACTIVE_TRADE object in — always this
    copy. DISPLAY-ONLY: shared by the Trade Monitor mirror and the Active Trade Mgmt
    advisory so both feed identical field names."""
    opened = at.get("opened_at") or ""
    return {
        "id":          "bot-%s-%s" % (inst, opened or uuid.uuid4().hex[:8]),
        "symbol":      at.get("symbol") or inst,
        "direction":   at.get("direction", "Long"),
        "entry_price": at.get("entry_price"),
        "stop_loss":   at.get("stop_loss"),
        "target1":     at.get("target1"),
        "target2":     at.get("target2"),
        "target3":     at.get("target3"),
        "contracts":   at.get("contracts"),
        "mode":        at.get("mode") or TRADING_MODE,
        "reason":      "",
        "entry_time":  opened or None,
        "opened_at":   opened or now_utc().isoformat(),
        "status":      "open",
    }


def _bot_active_trade_monitor_items(analysis_cache):
    """ADVISORY DISPLAY mirror of the bot's own OPEN positions (ACTIVE_TRADES_BY_INST),
    rendered in the SAME shape as the manual monitor rows so a bot-executed order shows
    up in the Trade Monitor box automatically.

    READ-ONLY by construction: each row is built from a THROWAWAY copy of the tracked
    trade (compute_manual_trade_management may write min_r/max_r back onto the dict it is
    handed, so the live ACTIVE_TRADE object is never passed in), reuses the same read-only
    full_analysis cache, and feeds NO gate / journal / learning / broker / dedupe path. A
    row appears while the position is open and disappears on the next poll once the bot
    closes it (clear_active_trade) — no open/close hooks and no duplicate storage. The
    "Stop monitoring" control is hidden for these rows in the UI; even if its id were
    POSTed to /manual-trade/close it only pops from MANUAL_TRADES (a no-op here) and can
    never touch the real position. FAIL-OPEN: any error skips that instrument's mirror
    rather than breaking the monitor list."""
    items = []
    for inst, at in active_trade_snapshot().items():
        if not at:
            continue
        try:
            mirror = _bot_trade_mgmt_mirror(inst, at)
            sym = mirror["symbol"]
            if sym not in analysis_cache:
                try:
                    analysis_cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("bot-monitor analysis failed for %s: %s", sym, exc)
                    analysis_cache[sym] = None
            row = compute_manual_trade_management(mirror, analysis=analysis_cache[sym])
            row["origin"]          = "bot"
            row["advisory_mirror"] = True
            items.append(row)
        except Exception as exc:
            logger.warning("bot-monitor mirror failed for %s: %s", inst, exc)
    return items


def _bot_hold_verdict(score):
    """Map a 0-100 bot-hold conviction score to the advisory verdict vocabulary."""
    if score >= 65:
        return "HOLD"
    if score >= 45:
        return "SCALE OUT"
    return "EXIT"


def _compute_bot_hold_score(at, analysis=None):
    """Flag-gated public wrapper around _bot_hold_score_core(). Returns None when
    BOT_HOLD_SCORE_ENABLED is OFF; otherwise the read-only hold-conviction score.
    Kept as a thin wrapper so the Active Trade Management advisory can reuse the SAME
    health blend (_bot_hold_score_core) without requiring the BOT_HOLD_SCORE flag."""
    if not BOT_HOLD_SCORE_ENABLED:
        return None
    return _bot_hold_score_core(at, analysis=analysis)


def _bot_hold_score_core(at, analysis=None):
    """ADVISORY (DISPLAY-only) hold-conviction score for ONE open bot position.

    Blends read-only live signals — VWAP alignment, CVD-delta, structure, volume,
    ATR exhaustion, distance-to-liquidity, time-in-trade and trade progress — into a
    0-100 score + a HOLD / SCALE OUT / EXIT verdict with a per-component breakdown.
    Each component is included only when its data is available (FAIL-OPEN: a missing
    signal is skipped, never guessed). Reads RAW stores (current price, VWAP / CVD)
    plus an OPTIONAL full_analysis snapshot for structure / liquidity / volume.

    STRICTLY advisory: NEVER mutates trading state, gates, scores, sizes, dedupes or
    sends a broker order. Returns None when there is no usable price. NO flag check —
    callers gate as needed (the public _compute_bot_hold_score wrapper checks it)."""
    try:
        direction = at.get("direction", "Long")
        is_long   = (direction == "Long")
        symbol    = at.get("symbol")
        entry     = at.get("entry_price")
        stop      = at.get("stop_loss")
        inst      = _instrument_from_text(symbol) or symbol
        if entry is None or stop is None:
            return None
        price = current_price_for(inst)
        if price is None:
            return None
        risk = abs(entry - stop)
        if not risk:
            return None
        fav       = (price - entry) if is_long else (entry - price)
        current_r = fav / risk
        stop_breached = (price <= stop) if is_long else (price >= stop)

        comps = {}   # name -> (0..1 conviction, human detail)

        # 1) VWAP alignment (RAW store).
        vwap = (VWAP_BY_TICKER.get(inst) or {}).get("value")
        if vwap is not None:
            on_side = (price >= vwap) if is_long else (price <= vwap)
            comps["vwap"] = (1.0 if on_side else 0.0,
                             "price %s VWAP" % ("above" if price >= vwap else "below"))

        # 2) CVD-delta alignment (RAW store).
        cstate = str((CVD_BY_TICKER.get(inst) or {}).get("state") or "").lower()
        if cstate in ("bullish", "bearish"):
            comps["cvd"] = (1.0 if ((cstate == "bullish") == is_long) else 0.0,
                            "CVD %s" % cstate)

        a = analysis or {}
        # 3) Structure alignment (optional full_analysis snapshot).
        sc = str(a.get("structure_class") or "").lower()
        if sc:
            s_bull, s_bear = ("bullish" in sc), ("bearish" in sc)
            confirmed = sc in ("bullish trend", "bearish trend")
            if (s_bull and is_long) or (s_bear and not is_long):
                comps["structure"] = (1.0 if confirmed else 0.7, a.get("structure_class"))
            elif (s_bear and is_long) or (s_bull and not is_long):
                comps["structure"] = (0.0 if confirmed else 0.3, a.get("structure_class"))
            else:
                comps["structure"] = (0.5, a.get("structure_class"))

        # 4) Volume support (optional full_analysis snapshot).
        vstate = str(a.get("volume_state") or "").lower()
        if vstate:
            comps["volume"] = (1.0 if vstate == "confirmed" else 0.5, vstate)

        # 5) ATR exhaustion (volatility regime; extreme / dead = scale-out pressure).
        vol = get_volatility(inst) or {}
        if vol.get("status") == "ok":
            if vol.get("blocked"):
                comps["atr"] = (0.2, vol.get("label"))
            elif vol.get("caution"):
                comps["atr"] = (0.6, vol.get("label"))
            else:
                comps["atr"] = (1.0, vol.get("label"))

        # 6) Distance-to-liquidity — an opposing zone ahead caps the remaining room.
        opp = a.get("nearest_supply") if is_long else a.get("nearest_demand")
        if opp is not None:
            gap = (opp - price) if is_long else (price - opp)
            if gap <= 0:
                comps["liquidity"] = (0.3, "opposing zone at/through price")
            else:
                room_r = gap / risk
                comps["liquidity"] = (max(0.0, min(1.0, room_r)),
                                      "%.2fR to %s" % (room_r, "supply" if is_long else "demand"))

        # 7) Time-in-trade — conviction decays as a position ages toward the max hold.
        opened = at.get("opened_at")
        held_min = None
        try:
            if opened:
                ot = datetime.fromisoformat(str(opened))
                if ot.tzinfo is None:
                    ot = ot.replace(tzinfo=timezone.utc)
                held_min = max(0.0, (now_utc() - ot).total_seconds() / 60.0)
        except Exception:
            held_min = None
        if held_min is not None:
            max_hold = float(LIVE_RUNNER_MAX_HOLD_MIN or 240) or 240.0
            comps["time"] = (max(0.0, 1.0 - min(1.0, held_min / max_hold)),
                             "%.0f min held" % held_min)

        # 8) Trade progress — in profit & off the stop strengthens the hold.
        comps["progress"] = (max(0.0, min(1.0, 0.5 + max(-0.5, min(0.5, current_r / 2.0)))),
                             "%.2fR" % current_r)

        if not comps:
            return None
        score = round(100.0 * sum(v[0] for v in comps.values()) / len(comps), 1)
        verdict = "EXIT" if stop_breached else _bot_hold_verdict(score)
        return {
            "instrument":    inst,
            "symbol":        symbol,
            "direction":     direction,
            "entry":         entry,
            "stop":          stop,
            "price":         price,
            "current_r":     round(current_r, 2),
            "score":         score,
            "verdict":       verdict,
            "stop_breached": bool(stop_breached),
            "opened_at":     opened,
            "held_minutes":  round(held_min, 1) if held_min is not None else None,
            "components":    {k: {"score": round(v[0] * 100.0, 0), "detail": v[1]}
                              for k, v in comps.items()},
            "advisory_only": True,
            "updated_at":    now_utc().isoformat(),
        }
    except Exception as exc:
        logger.warning("bot hold score failed: %s", exc)
        return None


def _bot_hold_status_block(seed_analysis=None, seed_ticker=None):
    """DISPLAY-only /status presenter: a Bot Hold Score for every OPEN bot position.
    Reuses ONE read-only full_analysis per distinct symbol (seeded with the caller's
    already-computed snapshot to avoid a duplicate compute). Returns None when the flag
    is OFF or there are no open positions, so the /status key stays null. FAIL-OPEN."""
    if not BOT_HOLD_SCORE_ENABLED:
        return None
    try:
        snap = active_trade_snapshot()
        if not snap:
            return None
        cache = {}
        if seed_ticker and seed_analysis is not None:
            cache[seed_ticker] = seed_analysis
        rows = []
        for inst, at in snap.items():
            if not at:
                continue
            sym = at.get("symbol") or inst
            if sym not in cache:
                try:
                    cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("bot-hold analysis failed for %s: %s", sym, exc)
                    cache[sym] = None
            sc = _compute_bot_hold_score(at, analysis=cache.get(sym))
            if sc:
                rows.append(sc)
        if not rows:
            return None
        return {
            "enabled":    True,
            "count":      len(rows),
            "positions":  rows,
            "updated_at": now_utc().isoformat(),
        }
    except Exception as exc:
        logger.warning("bot hold status block error: %s", exc)
        return None


def _active_trade_advisory(inst, at, analysis=None):
    """DISPLAY-ONLY active-trade management advisory for ONE open bot position.

    Combines the read-only bot-hold HEALTH score (_bot_hold_score_core) with the
    manual-manager THESIS read (compute_manual_trade_management on a THROWAWAY copy)
    and adds a stateless time-stall / no-progress proxy, mapped to the operator
    vocabulary: thesis_status (VALID/WEAKENING/INVALID/PAUSED/UNKNOWN), suggested_action
    (HOLD / MOVE STOP / EXIT EARLY / TAKE PARTIAL / MONITOR), hold_reason, exit_warning,
    and a per-signal `checks` breakdown. STRICTLY advisory: NEVER mutates trading state,
    gates, scores, sizes, dedupes, or sends a broker order. FAIL-OPEN -> None."""
    try:
        symbol    = at.get("symbol") or inst
        direction = at.get("direction", "Long")

        # Health (flag-independent core) + manual-style thesis read on a COPY —
        # compute_manual_trade_management writes min_r/max_r back onto the dict.
        health = _bot_hold_score_core(at, analysis=analysis)
        mirror = _bot_trade_mgmt_mirror(inst, at)
        mgmt   = compute_manual_trade_management(mirror, analysis=analysis) or {}

        # Held-minutes (computed locally so the stall proxy works even if health is None).
        held_minutes = None
        opened = at.get("opened_at")
        try:
            if opened:
                ot = datetime.fromisoformat(str(opened))
                if ot.tzinfo is None:
                    ot = ot.replace(tzinfo=timezone.utc)
                held_minutes = max(0.0, (now_utc() - ot).total_seconds() / 60.0)
        except Exception:
            held_minutes = None

        health_score = (health or {}).get("score")

        # Monitor unavailable (no live price / zero risk): honest, no fabricated guidance.
        if mgmt.get("status") != "ok":
            return {
                "instrument":       inst,
                "symbol":           symbol,
                "direction":        direction,
                "thesis_status":    mgmt.get("thesis_status") or "UNKNOWN",
                "suggested_action": "MONITOR",
                "health_score":     health_score,
                "hold_reason":      mgmt.get("recommendation_reason")
                                    or "Live monitor unavailable right now — no guidance fabricated.",
                "exit_warning":     None,
                "checks":           [],
                "fired_triggers":   [],
                "current_r":        mgmt.get("current_r"),
                "held_minutes":     round(held_minutes, 1) if held_minutes is not None else None,
                "stop_breached":    bool(mgmt.get("stop_breached")),
                "advisory_only":    True,
                "updated_at":       now_utc().isoformat(),
            }

        current_r     = mgmt.get("current_r")
        thesis        = mgmt.get("thesis_status") or "VALID"
        mgmt_action   = mgmt.get("action") or "HOLD"
        warnings      = list(mgmt.get("warnings") or [])
        stop_breached = bool(mgmt.get("stop_breached"))
        t1_hit        = bool(mgmt.get("target1_hit"))
        paused        = (thesis == "PAUSED")

        # ── Stateless STALL / time-limit proxy (display-only) ──
        # True candle-by-candle progress needs per-position history we do not keep, so
        # this is an honest held-time + current-R proxy. Suppressed while paused/closed.
        stall = time_limit = False
        if (not paused and held_minutes is not None and isinstance(current_r, (int, float))
                and not stop_breached and not t1_hit):
            if held_minutes >= ACTIVE_TRADE_STALL_MIN and abs(current_r) < ACTIVE_TRADE_STALL_R:
                stall = True
            if held_minutes >= LIVE_RUNNER_MAX_HOLD_MIN and current_r <= 0:
                time_limit = True

        # ── Fired exit / weakening triggers (human strings) ──
        fired = list(warnings)
        if stall:
            fired.append("No progress for ~%.0f min (sitting near entry at %.2fR) — the setup has stalled."
                         % (held_minutes, current_r))
        if time_limit:
            fired.append("Open ~%.0f min with no progress — past the time limit; scratch it and free the risk."
                         % held_minutes)

        # ── Thesis escalation from the supplemental triggers (display-only) ──
        if (stall or time_limit) and thesis == "VALID":
            thesis = "WEAKENING"

        # ── Suggested action -> operator vocabulary ──
        _amap = {
            "EXIT":            "EXIT EARLY",
            "REDUCE":          "TAKE PARTIAL",
            "TAKE PARTIAL":    "TAKE PARTIAL",
            "MOVE STOP TO BE": "MOVE STOP",
            "HOLD":            "HOLD",
            "MONITOR":         "MONITOR",
        }
        suggested = _amap.get(mgmt_action, mgmt_action)
        if time_limit and suggested == "HOLD" and (not isinstance(current_r, (int, float)) or current_r <= 0):
            suggested = "EXIT EARLY"

        hold_reason  = mgmt.get("recommendation_reason")
        exit_warning = "; ".join(fired) if fired else None

        # ── Per-signal checks (answers each tracked question) ──
        comps = (health or {}).get("components") or {}
        def _cs(name):
            c = comps.get(name)
            return (c or {}).get("score") if c else None
        def _cd(name):
            c = comps.get(name)
            return (c or {}).get("detail") if c else None
        def _chk(key, label, value, detail):
            return {"key": key, "label": label, "value": bool(value),
                    "detail": detail if detail is not None else "—"}

        vwap_against   = (_cs("vwap") is not None and _cs("vwap") < 50)
        struct_against = (_cs("structure") is not None and _cs("structure") < 50)
        cvd_against    = (_cs("cvd") is not None and _cs("cvd") < 50)
        vol_fading     = (_cs("volume") is not None and _cs("volume") < 100)
        liq_score      = _cs("liquidity")
        opp_zone       = (liq_score is not None and liq_score <= 30)
        toward         = isinstance(current_r, (int, float)) and current_r > 0.1
        rejecting      = bool(vwap_against or struct_against or cvd_against)

        checks = [
            _chk("toward_target", "Moving toward target", toward,
                 ("%.2fR" % current_r) if isinstance(current_r, (int, float)) else "—"),
            _chk("rejecting_entry", "Rejecting entry direction", rejecting,
                 "momentum against position" if rejecting else "no rejection"),
            _chk("vwap_against", "VWAP against position", vwap_against, _cd("vwap")),
            _chk("structure_against", "Structure breaking against", struct_against, _cd("structure")),
            _chk("cvd_against", "CVD flipped against", cvd_against, _cd("cvd")),
            _chk("volume_fading", "Volume fading", vol_fading, _cd("volume")),
            _chk("stalled", "Stalled / no progress", (stall or time_limit),
                 ("%.0f min, %.2fR" % (held_minutes, current_r)) if (stall or time_limit) else "progressing"),
            _chk("opposing_zone_near", "Opposing zone ahead", opp_zone, _cd("liquidity")),
            _chk("thesis_invalidated", "Thesis invalidated", thesis == "INVALID",
                 hold_reason if thesis == "INVALID" else "thesis intact"),
        ]

        return {
            "instrument":       inst,
            "symbol":           mgmt.get("symbol") or symbol,
            "direction":        mgmt.get("direction", direction),
            "entry":            mgmt.get("entry_price"),
            "stop":             mgmt.get("stop_loss"),
            "price":            mgmt.get("current_price"),
            "current_r":        current_r,
            "health_score":     health_score,
            "thesis_status":    thesis,
            "suggested_action": suggested,
            "hold_reason":      hold_reason,
            "exit_warning":     exit_warning,
            "checks":           checks,
            "fired_triggers":   fired,
            "stop_breached":    stop_breached,
            "held_minutes":     round(held_minutes, 1) if held_minutes is not None else None,
            "advisory_only":    True,
            "updated_at":       now_utc().isoformat(),
        }
    except Exception as exc:
        logger.warning("active-trade advisory failed for %s: %s", inst, exc)
        return None


def _active_trade_mgmt_block(seed_analysis=None, seed_ticker=None):
    """DISPLAY-only /status presenter: an Active Trade Management advisory for every
    OPEN bot position. Reuses ONE read-only full_analysis per distinct symbol (seeded
    with the caller's already-computed snapshot to avoid a duplicate compute). Returns
    None when ACTIVE_TRADE_MGMT_ENABLED is OFF or there are no open positions, so the
    /status key stays null and the panel hides. STRICTLY advisory / FAIL-OPEN."""
    if not ACTIVE_TRADE_MGMT_ENABLED:
        return None
    try:
        snap = active_trade_snapshot()
        if not snap:
            return None
        cache = {}
        if seed_ticker and seed_analysis is not None:
            cache[seed_ticker] = seed_analysis
        rows = []
        for inst, at in snap.items():
            if not at:
                continue
            sym = at.get("symbol") or inst
            if sym not in cache:
                try:
                    cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("active-trade-mgmt analysis failed for %s: %s", sym, exc)
                    cache[sym] = None
            adv = _active_trade_advisory(inst, at, analysis=cache.get(sym))
            if adv:
                rows.append(adv)
        if not rows:
            return None
        return {
            "enabled":    True,
            "count":      len(rows),
            "positions":  rows,
            "updated_at": now_utc().isoformat(),
        }
    except Exception as exc:
        logger.warning("active-trade-mgmt status block error: %s", exc)
        return None


@app.route("/manual-trade", methods=["GET", "POST"])
def manual_trade():
    """ADVISORY-ONLY Manual Trade Manager. POST creates a monitored position; GET lists
    every open position with live guidance. Owner-only (auth enforced at the Express
    /api edge; NOT in dashboard-auth OPEN_PATHS). NEVER sends a broker order."""
    if request.method == "POST":
        data = request.get_json(force=True, silent=True) or {}
        trade, err = _build_manual_trade(data)
        if err:
            return jsonify({"status": "error", "reason": err}), 400
        with MANUAL_TRADES_LOCK:
            MANUAL_TRADES[trade["id"]] = trade
            # Seed the management timeline with the entry event immediately so the
            # copilot log starts the moment the trade is logged (display-only).
            _update_manual_trade_timeline(trade, {})
        _persist_manual_trade(trade)
        _emit_manual_entered_event(trade)              # Main Brain learning loop (display-only, fail-open)
        logger.info("Manual trade added (advisory-only): %s %s @ %.2f",
                    trade["symbol"], trade["direction"], trade["entry_price"])
        _added_row = compute_manual_trade_management(trade)
        _added_row["timeline"] = list(trade.get("timeline") or [])
        return jsonify({"status": "added", "id": trade["id"],
                        "trade": _added_row}), 200

    # GET — list open manual trades with live advisory guidance. full_analysis is
    # computed ONCE per distinct symbol then fanned out across that symbol's trades.
    analysis_cache = {}
    items = []
    with MANUAL_TRADES_LOCK:
        trades = list(MANUAL_TRADES.values())
        for t in trades:
            sym = t.get("symbol")
            if sym not in analysis_cache:
                try:
                    analysis_cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("manual-trade list analysis failed for %s: %s", sym, exc)
                    analysis_cache[sym] = None
            _row = compute_manual_trade_management(t, analysis=analysis_cache[sym])
            _row["origin"] = "manual"
            # Advance the copilot timeline on the STORED trade (single writer, under
            # lock) and persist only when a new milestone fired. Display-only.
            try:
                if _update_manual_trade_timeline(t, _row):
                    _persist_manual_trade(t)
            except Exception as exc:
                logger.warning("manual-trade timeline update failed for %s: %s", sym, exc)
            _row["timeline"] = list(t.get("timeline") or [])
            items.append(_row)
    # ADVISORY DISPLAY-ONLY: also surface the bot's own OPEN positions so an
    # auto-executed (or manually-entered) order shows up in this monitor box
    # automatically. Read-only mirror — never a second order, never journaled or
    # learned twice; it clears itself when the bot closes the position. FAIL-OPEN.
    try:
        items.extend(_bot_active_trade_monitor_items(analysis_cache))
    except Exception as exc:
        logger.warning("bot-monitor merge failed: %s", exc)
    items.sort(key=lambda x: x.get("opened_at") or "", reverse=True)
    return jsonify({"status": "ok", "trades": items,
                    "persisted": MANUAL_TRADE_DB_READY, "count": len(items)}), 200


@app.route("/manual-trade/close", methods=["POST"])
def manual_trade_close():
    """Stop monitoring a manual trade. ADVISORY-ONLY — this only removes the row from
    the local monitor (and marks it closed in our table); it NEVER sends a broker
    order or touches a tracked ACTIVE_TRADE."""
    data = request.get_json(force=True, silent=True) or {}
    tid  = str(data.get("id", "")).strip()
    if not tid:
        return jsonify({"status": "error", "reason": "A trade id is required."}), 400
    with MANUAL_TRADES_LOCK:
        trade = MANUAL_TRADES.pop(tid, None)
    if trade is None:
        return jsonify({"status": "error", "reason": "No open manual trade with that id."}), 404
    trade["status"]    = "closed"
    trade["closed_at"] = now_utc().isoformat()
    _persist_manual_trade(trade)
    logger.info("Manual trade monitoring stopped: %s", tid)
    return jsonify({"status": "closed", "id": tid}), 200


def create_journal_entry(record, a, sizing, post_discord=True):
    """Auto-journal every Possible/Strong Trade recommendation, skipping duplicates.

    post_discord=False stores the entry in-memory only and skips the (slow)
    journal-channel Discord embed, so the webhook worker can send the trade alert
    first and offload that embed to the slow-task worker."""
    global JOURNAL, JOURNAL_KEYS

    strict_label = a.get("strict_label", "WAIT")
    if strict_label not in ("Strong Trade", "Possible Trade"):
        return None

    entry      = _build_card_entry(a, record=record)
    ticker     = entry["symbol"]
    direction  = entry["direction"]
    entry_zone = entry["entry_zone"]

    # Dedup key: instrument + direction + entry-zone low rounded to nearest integer.
    dedup_key = _journal_dedup_key(entry)

    if dedup_key in JOURNAL_KEYS:
        logger.info("Journal dedup skip: %s %s @ %.0f", ticker, direction, dedup_key[2])
        return None

    with _timed("journalWriteMs"):
        JOURNAL_KEYS.add(dedup_key)

        entry["id"]      = len(JOURNAL) + 1
        entry["outcome"] = "Pending"
        # ── Thesis fields (Phase 1 — additive; fail-open) ─────────────────────
        _th = a.get("thesis") or {}
        entry["thesisId"]          = _th.get("thesisId")
        entry["thesisCreatedAt"]   = _th.get("createdAt")
        entry["confidenceAtEntry"] = _th.get("confidence")
        entry["thesisAgeAtEntry"]  = _th.get("thesisAgeMs")
        entry["supportingEvidence"]= _th.get("evidenceFor") or []
        entry["opposingEvidence"]  = _th.get("evidenceAgainst") or []
        entry["fastEntryUsed"]     = bool(a.get("fast_entry", {}) and
                                          a.get("fast_entry", {}).get("trigger_fired"))
        # confidenceAtReady and strongestConfidence are populated when the entry
        # becomes READY (or on close) — stamped here as the entry-time values.
        entry["confidenceAtReady"] = (_th.get("confidence")
                                      if _th.get("status") in ("READY_LONG", "READY_SHORT")
                                      else None)
        entry["strongestConfidence"] = _th.get("confidence")   # updated on close
        entry["invalidationReason"]  = _th.get("invalidationReason")
        # Chart screenshot: use a validated public URL when the alert carried one,
        # else keep the legacy placeholder string and continue (no failure).
        if entry.get("screenshot_url"):
            entry["screenshot"] = entry["screenshot_url"]
        else:
            entry["screenshot"] = "[ Screenshot placeholder — add URL or image link ]"
            logger.info("Screenshot unavailable for journal #%d — continuing", entry["id"])

        _ensure_journal_key(entry)
        JOURNAL.insert(0, entry)
        if len(JOURNAL) > 500:
            JOURNAL.pop()

    _persist_journal_entry(entry)  # fail-open Postgres mirror (off the decision worker)
    if post_discord:
        send_journal_discord_embed(entry)
    logger.info("Journal entry #%d created: %s %s %s @ %s",
                entry["id"], ticker, strict_label, direction, entry_zone)
    return entry


def active_trade_field(trade, current_price):
    """Return a single Discord embed field dict showing live trade status (v11)."""
    dollar_pnl, pts_pnl   = compute_pnl(trade, current_price)
    to_t1, to_t2, to_stop = compute_distances(trade, current_price)

    pnl_emoji = "🟢" if dollar_pnl >= 0 else "🔴"
    pnl_str   = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"

    status = trade.get("status", "active")
    state_str = {
        "active":    "🟢  Stage 5 — Entered",
        "breakeven": "🟡  Stage 6 — T1 Hit (Breakeven Active)",
    }.get(status, "🟢  Stage 5 — Entered")

    if status == "active":
        next_action = f"Wait for T1 at `{trade['target1']:.1f}`"
    elif status == "breakeven":
        next_action = (f"Wait for T2 at `{trade['target2']:.1f}`  ·  "
                       f"Stop at breakeven `{trade['entry_price']:.1f}`")
    else:
        next_action = "—"

    value = (
        f"**State:** {state_str}\n"
        f"**Entry:** `{trade['entry_price']:.1f}`  ·  "
        f"**Current Price:** `{current_price:.1f}`\n"
        f"**PnL:** {pnl_emoji} {pnl_str} ({pts_pnl:+.1f} pts)\n"
        f"\n"
        f"**Distance to T1:** `{to_t1:.1f} pts`\n"
        f"**Distance to T2:** `{to_t2:.1f} pts`\n"
        f"**Distance to Stop:** `{to_stop:.1f} pts`\n"
        f"\n"
        f"**Next Action:** {next_action}"
    )

    return {"name": "📊  ACTIVE TRADE MANAGEMENT", "value": value, "inline": False}


# ENTER / CLOSE command alerts for every enabled instrument (registry-driven), so
# MES/MYM command alerts route to the command handler instead of falling through
# to scoring. Built from the same instrument list as the rest of the engine.
_COMMAND_TYPES = {f"{inst} {act}"
                  for inst in enabled_instruments()
                  for act in ("ENTER", "CLOSE")}
# Registry-driven so every enabled instrument's data-only VWAP push takes the fast
# inline ack path (the VWAP store is written synchronously above; no heavy scoring).
# MGC/MNQ membership is unchanged — this is the same set plus MES/MYM.
_DATA_ONLY_TYPES = _per_inst_alert_set("VWAP")


def _handle_command_alert(normalized, data, parsed_price, resolved_inst):
    """Execute ENTER / CLOSE trade commands sent via TradingView webhook.

    Returns a Flask Response to short-circuit the webhook handler, or None
    to fall through to normal alert scoring.
    """
    profile   = str(data.get("profile", DEFAULT_PROFILE))
    is_enter  = normalized.endswith("ENTER")

    # ── ENTER ─────────────────────────────────────────────────────────────
    if is_enter:
        # R:R multiple for the LOCAL tracked TP (Discord-only path). Defaults to 1:1;
        # the plan-sourced fill below lifts it from the authoritative plan so a truly-
        # ready Opening Range Breakout is tracked/announced at its sanctioned 1:4.
        _rr_mult  = 1.0
        _rr_label = "1:1"
        try:
            entry = float(data["entry"]) if data.get("entry") else None
            stop  = float(data["stop"])  if data.get("stop")  else None
            t1    = float(data["t1"])    if data.get("t1")    else None
            t2    = float(data["t2"])    if data.get("t2")    else None
        except (ValueError, TypeError) as exc:
            return jsonify({"status": "error", "reason": str(exc)}), 400

        # Fall back to current trade plan for any missing values
        if None in (entry, stop, t1, t2):
            a  = full_analysis(current_price_override=parsed_price, ticker_override=resolved_inst)
            tp = a["trade_plan"]
            if not tp.get("trade_plan") or not tp.get("entry_zone"):
                return jsonify({"status": "error",
                                "reason": "No ready setup to enter — fill in Entry / Stop / T1 / T2, or wait for a valid Long Ready / Short Ready setup."}), 400
            try:
                if entry is None:
                    zone = str(tp["entry_zone"])
                    if "–" in zone:
                        lo_s, hi_s = zone.split("–")
                        entry = (float(lo_s) + float(hi_s)) / 2
                    else:
                        entry = float(zone)
                if stop is None:
                    stop = float(tp["stop_loss"])
                if t1   is None:
                    t1   = float(tp["target1"])
                if t2   is None:
                    t2   = float(tp["target2"])
            except (ValueError, TypeError, KeyError) as exc:
                return jsonify({"status": "error", "reason": f"Missing trade plan params: {exc}"}), 400
            # Authoritative plan drives the tracked R:R (1:4 only for a truly-ready ORB).
            _rr_mult  = float(tp.get("rr_num", 1.0) or 1.0)
            _rr_label = str(tp.get("rr", "1:1") or "1:1")

        contracts = int(data.get("contracts", 1))
        symbol    = resolved_inst

        # The stop side is the ground truth for a bracket trade (stop below entry =
        # Long, above = Short). Resolve direction from the explicit field when given,
        # else infer it from the stop side; reject a payload whose stated direction
        # contradicts the stop placement. Without this an omitted direction defaults
        # Long, so a Short ENTER would put the 1:1 take-profit on the stop side while
        # announcing "(1:1)" and mis-tag ACTIVE_TRADE for the win/loss watcher.
        if entry == stop:
            return jsonify({"status": "error",
                            "reason": "Entry and stop are equal — cannot place a 1:1 trade."}), 400
        inferred = "Long" if stop < entry else "Short"
        _dir_raw = data.get("direction")
        if _dir_raw and str(_dir_raw)[0].lower() in ("l", "s") \
                and str(_dir_raw)[0].lower() != inferred[0].lower():
            return jsonify({"status": "error",
                            "reason": (f"Direction '{_dir_raw}' contradicts the stop placement "
                                       f"(stop {'below' if stop < entry else 'above'} entry = {inferred}).")}), 400
        direction = inferred

        # Re-derive the tracked take-profit FROM entry/stop at the plan's R:R multiple
        # (_rr_mult is 1.0 everywhere except a truly-ready Opening Range Breakout, which
        # the authoritative plan marks 1:4), rather than trusting client-supplied t1/t2
        # (deeper targets are retired). Keeps the tracked exit consistent with the plan.
        _risk = abs(entry - stop)
        t1 = (entry + _rr_mult * _risk) if direction == "Long" else (entry - _rr_mult * _risk)
        t2 = t1

        # Record the trade for local tracking (one slot per instrument).
        # set_active_trade() serialises the write on ACTIVE_TRADES_LOCK so two
        # concurrent ENTERs can't race on this instrument's record.
        _trade = {
            "direction":   direction,
            "entry_price": entry,
            "stop_loss":   stop,
            "target1":     t1,
            "target2":     t2,
            "contracts":   contracts,
            "profile":     profile,
            "symbol":      symbol,
            "opened_at":   now_utc().isoformat(),
            "t1_hit":      False,
            "t2_hit":      False,
            "status":      "active",
        }
        set_active_trade(symbol, _trade)
        content = (
            f"✅ **TRADE ENTERED — {direction.upper()}**\n"
            f"Entry `{entry:.2f}`  ·  Stop `{stop:.2f}`  ·  "
            f"TP `{t1:.2f}` ({_rr_label})  ·  Contracts `{contracts}`"
        )
        _url = _discord_url(normalized)
        if _url:
            try:
                requests.post(_url, json={"content": content}, timeout=5)
            except Exception:
                pass
        logger.info("ENTER command: %s %s @ %.1f", direction, profile, entry)
        return jsonify({"status": "entered", "trade": _trade}), 200

    # ── CLOSE (per-instrument) ────────────────────────────────────────────
    _at = active_trade_for(resolved_inst)
    if not _at:
        return jsonify({"status": "error", "reason": "No active trade to close."}), 400

    exit_price = parsed_price
    closed     = dict(_at)

    if exit_price is not None:
        dollar_pnl, _ = compute_pnl(_at, exit_price)
        pnl_str    = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"
        content    = (
            f"🏁 **TRADE CLOSED**\n"
            f"{_at['direction']} @ `{_at['entry_price']:.1f}`  ·  "
            f"Exit `{exit_price:.1f}`  ·  PnL **{pnl_str}**"
        )
        outcome_str = (
            f"Win — Closed {pnl_str} ✅" if dollar_pnl >= 0
            else f"Loss — Closed {pnl_str} ❌"
        )
    else:
        dollar_pnl  = None
        content     = (
            f"🏁 **TRADE CLOSED**\n"
            f"{_at['direction']} @ `{_at['entry_price']:.1f}`"
        )
        outcome_str = "Closed Manually"

    clear_active_trade(resolved_inst, opened_at=_at.get("opened_at"))
    _update_journal_outcome(outcome_str, pnl_dollars=dollar_pnl, symbol=resolved_inst)

    _url = _discord_url(normalized)
    if _url:
        try:
            requests.post(_url, json={"content": content}, timeout=5)
        except Exception:
            pass
    logger.info("CLOSE command: %s", outcome_str)
    return jsonify({"status": "closed", "trade": closed}), 200


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Per-webhook gate diagnostics
# ---------------------------------------------------------------------------
# Every scored webhook produces a full PASS/FAIL breakdown of each READY gate so
# the operator can see EXACTLY why a setup is WAIT. Entries are kept in a ring
# buffer (viewable, owner-only, at /diagnostics) and mirrored best-effort to an
# on-disk log. Recording is fail-open — diagnostics must never crash the worker.
GATE_DIAGNOSTICS = deque(maxlen=400)
_DIAG_LOCK       = threading.Lock()
DIAG_LOG_PATH    = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "gate_diagnostics.log")
# Cap the on-disk mirror so a write-on-every-webhook file can never grow without
# bound on a long-running VM. When the live file exceeds the cap it is rotated to
# a single ".1" backup, bounding total disk use to ~2× the cap. The /diagnostics
# ring buffer above is the owner-facing surface; the file is a best-effort mirror.
DIAG_LOG_MAX_BYTES = 2 * 1024 * 1024   # 2 MB per file (≈ a few thousand entries)


def _record_diagnostic(text):
    try:
        GATE_DIAGNOSTICS.append(text)
    except Exception:
        pass
    try:
        with _DIAG_LOCK:
            try:
                if os.path.getsize(DIAG_LOG_PATH) >= DIAG_LOG_MAX_BYTES:
                    os.replace(DIAG_LOG_PATH, DIAG_LOG_PATH + ".1")
            except FileNotFoundError:
                pass
            with open(DIAG_LOG_PATH, "a", encoding="utf-8") as fh:
                fh.write(text.rstrip("\n") + "\n\n")
    except Exception:
        pass


def _pf(flag):
    return "PASS" if flag else "FAIL"


def _vol_diag_summary(gd, vol):
    """One-line volatility status for the diagnostic header."""
    vol = vol or {}
    if gd.get("volatility_block"):
        return "BLOCK (holds setup at WAIT)"
    if vol.get("status") == "ok":
        return vol.get("decision") or "ok"
    return "unavailable (fail-open, no score effect)"


def _vol_diag_detail(vol):
    """Indented volatility fields for the diagnostic: currentATR, baselineATR,
    volatilityMultiplier, volatilityThreshold, volatilityDecision."""
    vol = vol or {}
    if vol.get("status") != "ok":
        return ["    (volatility reading unavailable - fail-open, no effect)"]

    def _n(x):
        try:
            return "%.2f" % float(x)
        except (TypeError, ValueError):
            return "—"
    adj = vol.get("score_adj", 0) or 0
    adj_str = ("+%d" % adj) if adj > 0 else ("%d" % adj)
    return [
        "    currentATR ........... %s pts" % _n(vol.get("atr_pts")),
        "    baselineATR .......... %s pts" % _n(vol.get("baseline_pts")),
        "    volatilityMultiplier . %sx" % _n(vol.get("ratio")),
        "    volatilityThreshold .. elevated >= %sx | extreme >= %sx" % (
            _n(vol.get("threshold_elevated")), _n(vol.get("threshold_extreme"))),
        "    volatilityDecision ... %s" % vol.get("label", "—"),
        "    configuredAdj ........ %s (policy only, NOT applied to edge score)" % adj_str,
        "    appliedAdj ........... 0",
    ]


def _stop_diag_lines(tp):
    """Human-readable ATR dynamic-stop breakdown for the owner-only /diagnostics
    text view. `tp` is a build_strict_trade_plan result dict; lines are emitted
    only when ATR stop metadata is present (additive / display-only — never used
    by the trade decision)."""
    tp = tp or {}

    def _n(x):
        if x is None:
            return "—"
        try:
            return "%g" % float(x)
        except (TypeError, ValueError):
            return str(x)
    return [
        "    currentATR ........... %s pts" % _n(tp.get("atr_pts")),
        "    atrMultiplier ........ %sx" % _n(tp.get("atr_multiplier")),
        "    nearestDemand ........ %s" % _n(tp.get("nearest_demand")),
        "    nearestSupply ........ %s" % _n(tp.get("nearest_supply")),
        "    structureStop ........ %s" % _n(tp.get("structure_stop")),
        "    atrStop .............. %s" % _n(tp.get("atr_stop")),
        "    minStopTicks ......... %s%s" % (
            _n(tp.get("min_stop_ticks")),
            " (FLOOR APPLIED)" if tp.get("min_floor_applied") else ""),
        "    finalStop ............ %s" % _n(tp.get("stop_loss")),
        "    stopDistanceTicks .... %s" % _n(tp.get("stop_distance_ticks")),
        "    riskPerContract ...... $%s" % _n(tp.get("risk_dollars_per_contract")),
        "    riskReward ........... %s" % _n(tp.get("rr")),
    ]


def format_gate_diagnostic(symbol, trigger, candidate, gd, verdict,
                           extra_blockers=None, vol=None):
    """Human-readable per-gate PASS/FAIL block for one scored webhook. `gd` is the
    candidate direction's gate_debug from evaluate_strict_setup (expanded above).
    Structure passes on ANY ONE of BOS/CHOCH/swing; the individual rows are shown
    for visibility while "Structure (any one)" + "Blocked by" reflect the real
    gate, so the breakdown never misreports the cause of a WAIT."""
    gd    = gd or {}
    side  = "Supply" if candidate == "Short" else "Demand"
    ready = is_actionable(verdict)
    cmp_  = "<" if candidate == "Short" else ">"
    fails = list(gd.get("failed_conditions") or [])
    for b in (extra_blockers or []):
        if b and b not in fails:
            fails.append(b)
    lines = [
        "──────── GATE DIAGNOSTIC ────────",
        "%s | %s | Trigger: %s" % (
            symbol, fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), trigger),
        "Candidate direction: %s" % (candidate.upper() if candidate else "NONE"),
        "",
        "  BOS (%s) .............. %s" % (side, _pf(gd.get("bos"))),
        "  CHOCH (%s) ............ %s" % (side, _pf(gd.get("choch"))),
        "  Swing (HH/HL or LH/LL)  %s" % _pf(gd.get("swing")),
        "  Structure (any one) ... %s" % _pf(gd.get("structure_confirmed")),
        "  VWAP (price %s VWAP) ... %s" % (cmp_, _pf(gd.get("vwap_confirmed"))),
        "  %s zone present ...... %s" % (side, _pf(gd.get("zone_present"))),
        "  Zone Mitigated ........ %s" % _pf(gd.get("zone_mitigated")),
        "  Reaction (candle/sweep) %s" % _pf(gd.get("reaction")),
        "  Zone valid (mit+react)  %s" % _pf(gd.get("zone_valid")),
        "  Zone state ............ %s%s" % (
            gd.get("zoneState") or "—",
            " (informational, not required by mode)" if not gd.get("require_zone") else ""),
        "  Zone valid (gate) ..... %s" % _pf(gd.get("zoneValid")),
        "  Trading Session (bonus) %s" % _pf(gd.get("session_pref")),
        "  Conflict .............. %s" % ("YES" if gd.get("conflicting_structure") else "no"),
        "  Volatility ............ %s" % _vol_diag_summary(gd, vol),
    ]
    lines.extend(_vol_diag_detail(vol))
    lines.append("  Edge Score ............ %d / %d" % (gd.get("edge_score", 0), gd.get("ready_threshold", EDGE_READY_THRESHOLD)))
    # Task #18: surface the learning-weight Edge nudge ONLY when the master flag armed
    # this evaluation (display-only; edge_score above is already the adjusted value).
    if gd.get("learning_score_enabled"):
        lines.append("  Learning influence .... base %s -> %s (%+d, w=%.2f, %s)" % (
            gd.get("edge_score_base"), gd.get("edge_score"),
            gd.get("learning_score_delta", 0), gd.get("learning_weight") or 1.0,
            gd.get("learning_strategy_key") or "strategy"))
    lines.extend([
        "",
        "  FINAL READY DECISION: %s" % ("PASS" if ready else "FAIL"),
    ])
    if ready:
        lines.append("  Result: %s" % verdict)
    else:
        lines.append("  Result: WAIT")
        lines.append("  Blocked by: %s" % (", ".join(fails) if fails else "confluence"))
        # ── Human-readable reason when edge_score is the sole hard failure ──────
        _ef  = [f for f in fails if f.startswith("edge_score")]
        _nef = [f for f in fails if not f.startswith("edge_score")]
        if _ef and not _nef:
            _ce = gd.get("edge_score", 0)
            _te = (gd.get("full_ready_threshold") or gd.get("ready_threshold")
                   or EDGE_READY_THRESHOLD)
            lines.append("  Reason: Edge score %d is below the required %d." % (_ce, _te))
        # ── Missing optional confirmations (absent EDGE_COMPONENTS, not hard gates) ──
        _il = True if candidate == "Long" else (False if candidate == "Short" else None)
        def _dl(lg, sh):
            if _il is True:  return lg
            if _il is False: return sh
            return lg
        _opt_map = [
            ("bos",              _dl("Bullish BOS",       "Bearish BOS"),        20),
            ("choch",            _dl("Bullish CHOCH",     "Bearish CHOCH"),      20),
            ("vwap_confirmed",   _dl("VWAP Reclaim",      "VWAP Rejection"),     15),
            ("liquidity_sweep",  "Liquidity Sweep",                              15),
            ("volume_confirmed", "Volume Confirmation",                          15),
            ("cvd_confirmed",    _dl("CVD Confirms Long", "CVD Confirms Short"), 15),
            ("session_pref",     "Session Bonus",                                10),
        ]
        _hard_keys = {"zone_valid", "vwap_confirmed", "structure_confirmed",
                      "volume_unconfirmed", "cvd_conflict", "location"}
        _miss = [(lbl, pts) for gk, lbl, pts in _opt_map
                 if gk not in _hard_keys and not gd.get(gk)]
        if _miss:
            lines.append("")
            lines.append("  Missing optional confirmations (each adds points toward threshold):")
            for lbl, pts in _miss:
                lines.append("    \u2022 %s  (+%d pts)" % (lbl, pts))
        # ── Context only: informational items that are NOT hard gate failures ──
        _ctx = []
        if not gd.get("require_zone") and gd.get("zoneState"):
            _ctx.append('Zone state "%s" \u2014 informational only; zone is not a gate '
                        "requirement in this mode" % gd.get("zoneState"))
        _vv = vol or {}
        if _vv.get("status") == "ok" and _vv.get("score_adj"):
            _ctx.append("Volatility configuredAdj=%+d \u2014 policy value, "
                        "NOT applied to edge score (appliedAdj=0)" % _vv.get("score_adj"))
        if _ctx:
            lines.append("")
            lines.append("  Context only (informational, not hard blockers):")
            for c in _ctx:
                lines.append("    \u2022 %s" % c)
    lines.append("──────── END DIAGNOSTIC ─────────")
    return "\n".join(lines)


def _record_eval_metrics(a, webhook_received_at, eval_started_at, eval_finished_at,
                         eval_duration_ms, alert_sent_at, instrument, tiered_sent=False,
                         trigger="webhook", signal_type=None, is_duplicate=False,
                         signal_cooldown_remaining_ms=None):
    """Append one per-evaluation timing + volatility record to EVAL_METRICS (the
    live Diagnostics page / /eval-metrics read this). Best-effort — it must never
    raise into the worker. Phase timings come from the thread-local accumulator
    populated by the _timed() blocks during this evaluation; a phase that did not
    run for this alert (e.g. no journal write on a WAIT) is left None.

    Also records the gate breakdown (edge / zone / confirmations / blockers), the
    tiered alert_level, and the alert-dispatch + cooldown context so the live
    Diagnostics page can show exactly why a setup did or did not alert."""
    t   = _eval_timing_get() or {}
    vol = (a or {}).get("volatility") or {}
    gd  = (a or {}).get("gate_debug") or {}
    total_delay = None
    if webhook_received_at is not None and alert_sent_at is not None:
        total_delay = round((alert_sent_at - webhook_received_at).total_seconds() * 1000.0, 3)

    # ── Alert dispatch + cooldown context (best-effort, for diagnostics) ─────────
    alert_level = (a or {}).get("alert_level")
    verdict     = (a or {}).get("verdict") or ""
    inst_key    = instrument_of(instrument) if instrument else None
    alert_sent  = bool(alert_sent_at) or bool(tiered_sent)
    # Which throttle governs this level: READY re-posts on TRADE_READY_INTERVAL vs
    # LAST_LIVE_CARD_AT; the early tiers (WATCH / ARMED / WATCH FOR ENTRY) on
    # WATCH_ARMED_COOLDOWN_SEC vs LAST_TIER_AT.
    last_alert_at, cooldown_ms = None, None
    if alert_level == "READY":
        last_alert_at = LAST_LIVE_CARD_AT.get(inst_key) if inst_key else None
        cooldown_ms   = trade_ready_interval() * 1000
    elif alert_level in ("WATCH", "ARMED", "WATCH FOR ENTRY"):
        last_alert_at = LAST_TIER_AT.get(inst_key) if inst_key else None
        cooldown_ms   = int(cfg("WATCH_ARMED_COOLDOWN_SEC")) * 1000
    cooldown_remaining_ms = None
    if last_alert_at is not None and cooldown_ms is not None:
        elapsed_ms = (datetime.now(timezone.utc) - last_alert_at).total_seconds() * 1000.0
        cooldown_remaining_ms = round(max(0.0, cooldown_ms - elapsed_ms), 1)
    suppressed = bool(alert_level and not alert_sent
                      and cooldown_remaining_ms is not None and cooldown_remaining_ms > 0)
    blockers = ", ".join(gd.get("failed_conditions") or [])
    if not blockers:
        blockers = "READY" if is_actionable(verdict) else "-"

    # ── EARLY pre-READY timing (additive diagnostics; never affects the gate) ────
    et_slot         = dict(EARLY_EVENT_TIMES.get(inst_key) or {}) if inst_key else {}
    early_at_iso    = et_slot.get("earlyAlertTime")
    event_start_iso = et_slot.get("eventStartTime")
    event_start_dt  = None
    if event_start_iso:
        try:
            event_start_dt = datetime.fromisoformat(event_start_iso)
        except (ValueError, TypeError):
            event_start_dt = None
    # LAST_READY_SENT_AT is per-instrument and persists across setups. Attribute a
    # READY send to THIS event row ONLY when the current verdict is READY, or the
    # recorded READY happened at/after this event's start — otherwise it's a stale
    # READY from an earlier setup and must not pair with a fresh event.
    ready_dt         = LAST_READY_SENT_AT.get(inst_key) if inst_key else None
    ready_is_current = bool(ready_dt) and (
        is_actionable(verdict)
        or (event_start_dt is not None and ready_dt >= event_start_dt))
    ready_at_iso    = ready_dt.isoformat() if ready_is_current else None
    first_alert_iso = early_at_iso or ready_at_iso   # EARLY if it fired, else READY
    alert_delay_seconds = None
    try:
        if event_start_iso and first_alert_iso:
            delay = (datetime.fromisoformat(first_alert_iso)
                     - datetime.fromisoformat(event_start_iso)).total_seconds()
            if delay >= 0:                       # guard against stale/negative pairs
                alert_delay_seconds = round(delay, 1)
    except (ValueError, TypeError):
        alert_delay_seconds = None
    # False when EARLY caught it first; True when the current verdict is the
    # candle-close READY with no EARLY preceding it; None otherwise (incl. later
    # WAIT re-evaluations after a prior READY, so a stale READY can't read as True).
    if early_at_iso:
        waited_for_candle_close = False
    elif is_actionable(verdict):
        waited_for_candle_close = True
    else:
        waited_for_candle_close = None

    # ── Direction / setup-type / decision + processing-latency aliases (additive,
    # for the per-row latency view). direction prefers the verdict side, then the
    # gate candidate; setupType is the inbound alert_type when known, else the
    # structural stage; totalLatencyMs is webhook->finished (full processing
    # latency) and falls back to the in-eval duration for heartbeat rows. ──
    _candidate = gd.get("candidate") or (a or {}).get("gate_candidate")
    if verdict.startswith("LONG"):
        direction = "Long"
    elif verdict.startswith("SHORT"):
        direction = "Short"
    elif _candidate in ("Long", "Short"):
        direction = _candidate
    else:
        direction = None
    setup_type = signal_type or (a or {}).get("setup_stage") or (a or {}).get("structure_class")
    _eval_tp = (a or {}).get("trade_plan") or {}
    if not isinstance(_eval_tp, dict):
        _eval_tp = {}
    if webhook_received_at is not None and eval_finished_at is not None:
        total_latency_ms = round((eval_finished_at - webhook_received_at).total_seconds() * 1000.0, 3)
    else:
        total_latency_ms = eval_duration_ms

    record = {
        "webhookReceivedAt":    webhook_received_at.isoformat() if webhook_received_at else None,
        "evaluationStartedAt":  eval_started_at.isoformat() if eval_started_at else None,
        "evaluationFinishedAt": eval_finished_at.isoformat() if eval_finished_at else None,
        "evaluationDurationMs": eval_duration_ms,
        "indicatorCalcMs":      t.get("indicatorCalcMs"),
        "volatilityCalcMs":     t.get("volatilityCalcMs"),
        "scoringMs":            t.get("scoringMs"),
        "aiNotesMs":            t.get("aiNotesMs"),
        "screenshotMs":         t.get("screenshotMs"),
        "journalWriteMs":       t.get("journalWriteMs"),
        "alertSentAt":          alert_sent_at.isoformat() if alert_sent_at else None,
        "totalAlertDelayMs":    total_delay,
        # ── Volatility reading used by this evaluation ──
        "currentATR":           vol.get("atr_pts"),
        "baselineATR":          vol.get("baseline_pts"),
        "volatilityMultiplier": vol.get("ratio"),
        "volatilityThreshold":  vol.get("threshold_extreme"),
        "volatilityDecision":   vol.get("decision"),
        # ── ATR dynamic-stop breakdown (single source = this eval's trade plan) ──
        "atrMultiplier":          _eval_tp.get("atr_multiplier"),
        "nearestDemand":          _eval_tp.get("nearest_demand"),
        "nearestSupply":          _eval_tp.get("nearest_supply"),
        "structureStop":          _eval_tp.get("structure_stop"),
        "atrStop":                _eval_tp.get("atr_stop"),
        "minStopTicks":           _eval_tp.get("min_stop_ticks"),
        "stopDistanceTicks":      _eval_tp.get("stop_distance_ticks"),
        "finalStop":              _eval_tp.get("stop_loss"),
        "riskDollarsPerContract": _eval_tp.get("risk_dollars_per_contract"),
        "riskReward":             _eval_tp.get("rr"),
        "minFloorApplied":        _eval_tp.get("min_floor_applied"),
        # ── Context ──
        "instrument":           instrument,
        "verdict":              (a or {}).get("verdict"),
        # ── Per-signal latency view (additive aliases) ──
        "direction":            direction,
        "setupType":            setup_type,
        "decision":             (a or {}).get("verdict"),
        "alertReceivedTime":    webhook_received_at.isoformat() if webhook_received_at else None,
        "processingStartTime":  eval_started_at.isoformat() if eval_started_at else None,
        "processingEndTime":    eval_finished_at.isoformat() if eval_finished_at else None,
        "totalLatencyMs":       total_latency_ms,
        "isDuplicate":          bool(is_duplicate),
        "signalCooldownRemainingMs": signal_cooldown_remaining_ms,
        # ── Gate / decision breakdown ──
        "alertLevel":           alert_level,
        "edgeScore":            gd.get("edge_score"),
        "edgeOk":               gd.get("edge_ok"),
        "zoneValid":            gd.get("zone_valid"),
        "confirmationsPassed":  gd.get("confirmations_passed"),
        "confirmationsNeeded":  gd.get("confirmations_needed"),
        "readyThreshold":       gd.get("ready_threshold"),
        "gateBlockers":         blockers,
        # ── Expanded WAIT diagnostics (additive; surfaced on the Diagnostics page) ──
        "trigger":              trigger,
        "vwapConfirmed":        gd.get("vwap_confirmed"),
        "structureConfirmed":   gd.get("structure_confirmed"),
        "candleConfirmed":      gd.get("candle_confirmed"),
        "liquidityConfirmed":   gd.get("liquidity_sweep"),
        "volatilityConfirmed":  (None if gd.get("volatility_block") is None
                                 else (not gd.get("volatility_block"))),
        "confidenceScore":      (a or {}).get("confidence"),
        "waitReason":           (a or {}).get("strict_reason") or (a or {}).get("reason"),
        # ── Alert dispatch + cooldown ──
        "alertSent":            alert_sent,
        "webhookSent":          bool(alert_sent_at),
        "tieredSent":           bool(tiered_sent),
        "lastAlertAt":          last_alert_at.isoformat() if last_alert_at else None,
        "cooldownMs":           cooldown_ms,
        "cooldownRemainingMs":  cooldown_remaining_ms,
        "suppressedByCooldown": suppressed,
        # ── EARLY pre-READY timing (additive) ──
        "eventStartTime":       event_start_iso,
        "sweepTime":            et_slot.get("sweepTime"),
        "chochTime":            et_slot.get("chochTime"),
        "displacementTime":     et_slot.get("displacementTime"),
        "earlyAlertTime":       early_at_iso,
        "readyAlertTime":       ready_at_iso,
        "alertDelaySeconds":    alert_delay_seconds,
        "waitedForCandleClose": waited_for_candle_close,
    }
    with EVAL_METRICS_LOCK:
        EVAL_METRICS.append(record)

    # ── Cumulative counters (separate lock; NEVER nested in EVAL_METRICS_LOCK) ──
    # Best-effort, like the rest of this function — counter math must never raise
    # into the worker / heartbeat loop.
    try:
        verdict_str = (a or {}).get("verdict") or ""
        is_ready    = is_actionable(verdict_str)
        if (a or {}).get("market_open") is False:
            # Market closed — evaluations are paused. Never tally a quiet tape as
            # an evaluation or a failed/rejected signal (the row is still recorded
            # above for diagnostics; only the counters are skipped).
            return
        with COUNTERS_LOCK:
            COUNTERS["evaluations_run"] += 1
            if alert_sent:
                COUNTERS["alerts_sent"] += 1
            # Webhook (non-duplicate) signal funnel: how many inbound signals
            # passed every filter (READY) vs were rejected (WAIT). Heartbeat
            # re-evals and duplicate repeats are excluded so this tracks real
            # inbound TradingView signals only.
            if trigger == "webhook" and not is_duplicate:
                if is_ready:
                    COUNTERS["signals_passed_filters"] += 1
                else:
                    COUNTERS["signals_rejected"] += 1
            # Count a fresh setup once per non-READY -> READY transition per
            # instrument (NOT on every heartbeat re-eval of a still-READY setup).
            prev_ready = _READY_STATE_BY_INST.get(inst_key, False)
            if is_ready and not prev_ready:
                COUNTERS["ready_setups_detected"] += 1
            if inst_key is not None:
                _READY_STATE_BY_INST[inst_key] = is_ready
            # Tally each failed gate on a WAIT verdict so the operator can see the
            # dominant reasons setups don't fire.
            if not is_ready:
                for _fc in (gd.get("failed_conditions") or []):
                    COUNTERS["wait_reasons_breakdown"][_fc] = \
                        COUNTERS["wait_reasons_breakdown"].get(_fc, 0) + 1
                # Canonical, broken-out rejection reasons (req 6). Scoped to genuine
                # inbound signals (webhook, non-duplicate) so this cleanly decomposes
                # the signals_rejected funnel bucket; duplicates are tallied as
                # cooldown_duplicate in the webhook() dedup path instead. Counted at
                # the CONDITION level (not just the active hard gate) so SCALP
                # confirmation gaps (vwap/structure/candle) are visible even when the
                # raw wait_reasons_breakdown lumps them into "confirmations(N<M)".
                # session_filter is deliberately NEVER bumped: the trading session is
                # a +10 bonus, never a gate, so it can never reject a setup.
                if trigger == "webhook" and not is_duplicate:
                    _rr = COUNTERS["rejection_reasons"]
                    def _bump_rr(_k):
                        _rr[_k] = _rr.get(_k, 0) + 1
                    if not gd.get("zone_valid"):
                        _bump_rr("zone_valid")
                    if gd.get("vwap_confirmed") is False:
                        _bump_rr("vwap_confirmed")
                    if gd.get("structure_confirmed") is False:
                        _bump_rr("structure_confirmed")
                    if gd.get("location_ok") is False:
                        _bump_rr("location")
                    # Volume FAIL-OPEN: only count when data is present but unconfirmed
                    # (volume_ok already encodes "confirmed OR no data" — a missing feed
                    # never rejects a setup, so it must never inflate this counter).
                    if not gd.get("volume_ok"):
                        _bump_rr("volume_unconfirmed")
                    if gd.get("cvd_conflict"):
                        _bump_rr("cvd_conflict")
                    if gd.get("volatility_block"):
                        _bump_rr("volatility_block")
                    if not gd.get("edge_ok"):
                        _bump_rr("edge_score_low")
                    if gd.get("conflicting_structure"):
                        _bump_rr("conflicting_structure")
    except Exception as exc:
        logger.error("Counter update failed (eval still recorded): %s", exc)


# ══════════════════════════════════════════════════════════════════════════════
# THESIS HYSTERESIS ENGINE  (Phase 1)
# ══════════════════════════════════════════════════════════════════════════════
# The thesis layer wraps evaluate_strict_setup(). The strict gate re-runs on
# every alert; the thesis applies confidence inertia so a single bad alert can't
# flip READY↔WAIT.
#
# CONFIDENCE BANDS (0-100):
#   85-100  STRONG_READY  — very high conviction
#   75-84   READY         — all gates pass, promote/maintain READY
#   60-74   VALID         — gates mostly pass; READY is held above 60
#   40-59   FORMING       — setup building, not yet actionable
#    0-39   WEAK          — minimal evidence
#
# VERDICT ADJUSTMENT (the ONLY money-path effect):
#   • Raw READY + conf ≥ 75   → thesis READY_LONG/SHORT (promote)
#   • Thesis READY + conf ≥ 60 → stay READY even if raw gate returns WAIT (hold)
#   • Thesis READY + conf < 60 → demote to FORMING, return raw WAIT
#   • Hard invalidation (zone_broken/structural break) → snap conf=0, INVALIDATED
#   • Opposite direction needs conf ≥ 85 to reverse; weaker signal just weakens
#
# FAIL-OPEN: _apply_thesis() catches all exceptions and returns the raw verdict.
# FLAG-OFF:  THESIS_HYSTERESIS=0 → immediate (raw_verdict, {}) passthrough.
# ──────────────────────────────────────────────────────────────────────────────

def _thesis_new_id():
    """Generate a short unique thesis ID (e.g. 'th_a3f9c12b')."""
    return "th_" + uuid.uuid4().hex[:8]


def _thesis_confidence_label(conf):
    """Map 0-100 confidence to a display label used in Discord/dashboard."""
    if conf >= 85: return "STRONG_READY"
    if conf >= 75: return "READY"
    if conf >= 60: return "VALID"
    if conf >= 40: return "FORMING"
    return "WEAK"


def _thesis_blank(inst, direction, now_dt):
    """Return an empty thesis dict for `inst` in `direction`."""
    status = ("FORMING_LONG"  if direction == "Long"  else
              "FORMING_SHORT" if direction == "Short" else "NEUTRAL")
    return {
        # Identity
        "thesisId":            _thesis_new_id(),
        "instrument":          inst,
        "direction":           direction,
        "status":              status,
        # Timestamps
        "createdAt":           now_dt.isoformat(),
        "lastUpdatedAt":       now_dt.isoformat(),
        "lastStrengthenedAt":  None,
        "lastWeakenedAt":      None,
        # Confidence
        "confidence":          0,
        "previousConfidence":  0,
        "confidenceState":     "WEAK",
        # Gate state (per-evaluation snapshot)
        "structureDirection":  direction,
        "vwapAligned":         False,
        "cvdAligned":          False,
        "cvdState":            "UNKNOWN",
        "sweepConfirmed":      False,
        "volumeConfirmed":     False,
        "sessionPrime":        False,
        # Plan snapshot
        "entry":               None,
        "stop":                None,
        "targets":             [],
        "invalidationReason":  None,
        # Evidence
        "evidenceFor":         [],
        "evidenceAgainst":     [],
        # Timing
        "readyAt":             None,
        "readyAgeMs":          None,
        "thesisAgeMs":         0,
        "cooldownUntil":       None,
        "cooldownRemainingMs": None,
        # Reason codes for dashboard / Discord
        "reasonCodes":         [],
    }


# ══════════════════════════════════════════════════════════════════════════════
# THESIS PHASE 2 — Timeline, Discord Notifications, DB Persistence
# ══════════════════════════════════════════════════════════════════════════════

# ── Evidence code → human-readable label map ──────────────────────────────────
_EV_LABELS = {
    "STRUCTURE_BULLISH":     "Bullish structure",
    "STRUCTURE_BEARISH":     "Bearish structure",
    "STRUCTURE_INVALIDATED": "Structure invalidated",
    "ZONE_ACTIVE":           "Active demand/supply zone",
    "ZONE_CONSUMED":         "Zone consumed",
    "ZONE_INACTIVE":         "No active zone",
    "VWAP_ALIGNED":          "VWAP aligned",
    "VWAP_OPPOSING":         "VWAP opposing",
    "CVD_ALIGNED":           "CVD confirms direction",
    "CVD_OPPOSING":          "CVD opposing direction",
    "SWEEP_CONFIRMED":       "Liquidity sweep confirmed",
    "VOLUME_CONFIRMED":      "Volume confirmed",
    "PRIME_SESSION":         "Prime trading session",
}

def _ev_label(code):
    """Map an internal evidence code to a human-readable label."""
    return _EV_LABELS.get(code, str(code).replace("_", " ").title())

def _ms_to_human(ms):
    """Convert milliseconds to a compact human string, e.g. '14m 32s'."""
    try:
        if not ms or int(ms) < 0:
            return "—"
        s = int(ms) // 1000
        h, rem = divmod(s, 3600)
        m, sec = divmod(rem, 60)
        if h:
            return f"{h}h {m}m"
        if m:
            return f"{m}m {sec}s"
        return f"{sec}s"
    except Exception:
        return "—"

# ── Timeline event recording ───────────────────────────────────────────────────

def _record_thesis_event(inst, prev_snap, new_snap):
    """Append a transition event to THESIS_TIMELINE_BY_INST[inst] (fail-open).
    Capped at 25 events per instrument; guarded by THESIS_LOCK."""
    try:
        event = {
            "ts":               new_snap.get("lastUpdatedAt") or now_utc().isoformat(),
            "thesisId":         new_snap.get("thesisId"),
            "direction":        new_snap.get("direction"),
            "prevStatus":       prev_snap.get("status", "NEUTRAL"),
            "newStatus":        new_snap.get("status", "NEUTRAL"),
            "prevConfidence":   int(prev_snap.get("confidence") or 0),
            "newConfidence":    int(new_snap.get("confidence") or 0),
            "reasonCodes":      list(new_snap.get("reasonCodes") or []),
            "primaryReason":    ((new_snap.get("reasonCodes") or [""])[0]),
            "invalidationReason": new_snap.get("invalidationReason"),
        }
        with THESIS_LOCK:
            if inst not in THESIS_TIMELINE_BY_INST:
                THESIS_TIMELINE_BY_INST[inst] = deque(maxlen=25)
            THESIS_TIMELINE_BY_INST[inst].appendleft(event)
    except Exception as exc:
        logger.debug("_record_thesis_event fail-open [%s]: %s", inst, exc)

# ── Discord notification helpers ───────────────────────────────────────────────

# Important transitions that warrant a Discord push (prev_status, new_status).
_THESIS_NOTIFY_TRANSITIONS = frozenset({
    ("NEUTRAL",       "FORMING_LONG"),
    ("NEUTRAL",       "FORMING_SHORT"),
    ("INVALIDATED",   "FORMING_LONG"),
    ("INVALIDATED",   "FORMING_SHORT"),
    ("COOLDOWN",      "FORMING_LONG"),
    ("COOLDOWN",      "FORMING_SHORT"),
    ("FORMING_LONG",  "READY_LONG"),
    ("FORMING_SHORT", "READY_SHORT"),
    ("READY_LONG",    "INVALIDATED"),
    ("READY_SHORT",   "INVALIDATED"),
    ("READY_LONG",    "COOLDOWN"),
    ("READY_SHORT",   "COOLDOWN"),
    ("READY_LONG",    "FORMING_LONG"),
    ("READY_SHORT",   "FORMING_SHORT"),
})

def _should_notify_thesis(inst, prev_snap, new_snap):
    """Return True iff this transition warrants a Discord alert.
    Dedup: skip if we already sent for this exact (thesisId, prev→new) signature.
    Never raises — fail-open returns False."""
    try:
        prev_st = prev_snap.get("status", "NEUTRAL")
        new_st  = new_snap.get("status", "NEUTRAL")
        tid     = new_snap.get("thesisId", "")
        is_transition = (prev_st, new_st) in _THESIS_NOTIFY_TRANSITIONS
        if not is_transition:
            # Also fire on confirmed direction flip (new thesisId + opposite direction)
            prev_dir = prev_snap.get("direction")
            new_dir  = new_snap.get("direction")
            prev_tid = prev_snap.get("thesisId", "")
            if not (tid and prev_tid and tid != prev_tid
                    and prev_dir and new_dir and prev_dir != new_dir):
                return False
        sig = f"{tid}|{prev_st}|{new_st}"
        last = THESIS_NOTIF_LAST_BY_INST.get(inst) or {}
        return last.get("sig") != sig
    except Exception:
        return False

_THESIS_STATUS_EMOJI = {
    "FORMING_LONG":  "🟢",
    "FORMING_SHORT": "🔴",
    "READY_LONG":    "🚀",
    "READY_SHORT":   "🔻",
    "ACTIVE_LONG":   "📈",
    "ACTIVE_SHORT":  "📉",
    "INVALIDATED":   "❌",
    "COOLDOWN":      "⏳",
    "NEUTRAL":       "⚫",
}

def _thesis_notification_embed(inst, prev_snap, new_snap):
    """Build a compact Discord embed for a thesis transition notification."""
    prev_st   = prev_snap.get("status", "NEUTRAL")
    new_st    = new_snap.get("status", "NEUTRAL")
    direction = new_snap.get("direction", "—")
    conf      = new_snap.get("confidence", 0)
    age_ms    = new_snap.get("thesisAgeMs", 0)
    ready_ms  = new_snap.get("readyAgeMs")
    tid       = (new_snap.get("thesisId") or "")[-6:].upper()
    inv_r     = new_snap.get("invalidationReason")
    if new_st in ("READY_LONG", "READY_SHORT"):
        color = 0x2ECC71
    elif new_st == "INVALIDATED":
        color = 0xE74C3C
    elif new_st == "COOLDOWN":
        color = 0x9B59B6
    elif new_st.startswith("FORMING"):
        color = 0xF39C12
    else:
        color = 0x95A5A6
    emoji = _THESIS_STATUS_EMOJI.get(new_st, "⚫")
    ev_for = [_ev_label(e) for e in (new_snap.get("evidenceFor")  or [])][:6]
    ev_ag  = [_ev_label(e) for e in (new_snap.get("evidenceAgainst") or [])][:4]
    fields = [
        {"name": "📊 Confidence",    "value": f"**{conf}%**",          "inline": True},
        {"name": "🔄 Transition",    "value": f"{prev_st} → **{new_st}**", "inline": True},
        {"name": "⏱️ Age",           "value": _ms_to_human(age_ms),    "inline": True},
        {"name": "✅ Evidence For",  "value": ("\n".join(f"✓ {e}" for e in ev_for) or "—"),
         "inline": False},
        {"name": "⚠️ Against",       "value": ("\n".join(f"• {e}" for e in ev_ag)  or "—"),
         "inline": False},
    ]
    if ready_ms is not None:
        fields.insert(3, {"name": "🚀 READY for",
                          "value": _ms_to_human(ready_ms), "inline": True})
    if inv_r:
        fields.append({"name": "🚫 Invalidation",
                       "value": str(inv_r)[:300], "inline": False})
    e_v  = new_snap.get("entry")
    s_v  = new_snap.get("stop")
    tgts = [t for t in (new_snap.get("targets") or []) if t is not None]
    if e_v and s_v:
        plan_lines = [f"Entry: {e_v}", f"Stop: {s_v}"]
        for i, t in enumerate(tgts[:2], 1):
            plan_lines.append(f"Target {i}: {t}")
        fields.append({"name": "📐 Plan",
                       "value": "\n".join(plan_lines), "inline": False})
    return {
        "title":       f"{emoji} {inst} — {new_st.replace('_', ' ')}",
        "description": f"Direction: **{direction}**  ·  Thesis ID: `{tid}`",
        "color":       color,
        "timestamp":   now_utc().isoformat(),
        "fields":      fields,
        "footer":      {"text": f"Market Thesis · {inst}"},
    }

def _maybe_send_thesis_notification(inst, prev_snap, new_snap):
    """Enqueue a Discord thesis-transition notification (fail-open, deduped).
    Only fires when THESIS_DISCORD_ALERTS_ENABLED + DISCORD_LIVE_ENABLED.
    Dedup stamp is written BEFORE enqueueing to prevent race-condition duplicates."""
    try:
        if not _THESIS_DISCORD_ALERTS_ENABLED:
            return
        if not _should_notify_thesis(inst, prev_snap, new_snap):
            return
        prev_st = prev_snap.get("status", "NEUTRAL")
        new_st  = new_snap.get("status", "NEUTRAL")
        tid     = new_snap.get("thesisId", "")
        sig     = f"{tid}|{prev_st}|{new_st}"
        THESIS_NOTIF_LAST_BY_INST[inst] = {"sig": sig, "ts": now_utc().isoformat()}
        url   = _asset_discord_url(inst)
        embed = _thesis_notification_embed(inst, prev_snap, new_snap)
        def _send():
            try:
                if not DISCORD_LIVE_ENABLED or not url:
                    return
                resp = requests.post(url, json={"embeds": [embed]}, timeout=10)
                if resp.status_code not in (200, 204):
                    logger.warning("Thesis Discord failed [%s]: %s %s",
                                   inst, resp.status_code, resp.text[:200])
            except Exception as exc:
                logger.warning("Thesis Discord send error [%s]: %s", inst, exc)
        _enqueue_slow(_send)
    except Exception as exc:
        logger.debug("_maybe_send_thesis_notification fail-open [%s]: %s", inst, exc)

# ── Database persist / restore ────────────────────────────────────────────────

def _check_hysteresis_thesis_db_ready():
    """Probe the hysteresis_thesis table (no DDL). FAIL-OPEN."""
    global THESIS_DB_READY
    try:
        conn = get_db_connection()
        if not conn:
            return
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM hysteresis_thesis LIMIT 1")
        conn.close()
        THESIS_DB_READY = True
        logger.info("hysteresis_thesis table ready (thesis persistence enabled)")
    except Exception as exc:
        logger.warning("hysteresis_thesis unavailable (thesis DB disabled): %s", exc)
        THESIS_DB_READY = False

def _persist_thesis_state(inst, snap):
    """UPSERT the current thesis snapshot for `inst` (fail-open).
    Runs in the slow-task worker so it never blocks the webhook path."""
    if not THESIS_DB_READY or not inst or not snap:
        return
    try:
        import json as _json
        conn = get_db_connection()
        if not conn:
            return
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO hysteresis_thesis
                       (instrument, thesis_id, direction, status, confidence, data, updated_at)
                   VALUES (%s, %s, %s, %s, %s, %s::jsonb, NOW())
                   ON CONFLICT (instrument)
                   DO UPDATE SET
                       thesis_id  = EXCLUDED.thesis_id,
                       direction  = EXCLUDED.direction,
                       status     = EXCLUDED.status,
                       confidence = EXCLUDED.confidence,
                       data       = EXCLUDED.data,
                       updated_at = NOW()""",
                (inst,
                 snap.get("thesisId"),
                 snap.get("direction"),
                 snap.get("status"),
                 snap.get("confidence"),
                 _json.dumps(snap)),
            )
        conn.commit()
        conn.close()
    except Exception as exc:
        logger.debug("_persist_thesis_state fail-open [%s]: %s", inst, exc)

def _restore_thesis_states():
    """On boot, restore the most-recent thesis snapshot for every instrument.
    Validates age (THESIS_RESTORE_MAX_AGE_MS), status, and schema.
    A stale, malformed, or cooldown-expired row resets that instrument to NEUTRAL.
    NEVER submits a trade — only restores THESIS_BY_INST for display/inertia."""
    if not THESIS_DB_READY:
        return
    try:
        import json as _json
        conn = get_db_connection()
        if not conn:
            return
        now_dt  = now_utc()
        now_ms  = now_dt.timestamp() * 1000
        restored = 0
        with conn.cursor() as cur:
            cur.execute("SELECT instrument, data, updated_at FROM hysteresis_thesis")
            rows = cur.fetchall()
        conn.close()
        for inst, data_raw, updated_at in rows:
            try:
                snap = (data_raw if isinstance(data_raw, dict)
                        else _json.loads(data_raw or "{}"))
                if not snap or not snap.get("thesisId"):
                    continue
                age_ms = (now_ms - updated_at.timestamp() * 1000) if updated_at else float("inf")
                if age_ms > THESIS_RESTORE_MAX_AGE_MS:
                    logger.info("Thesis restore: %s skipped — stale (%d ms old)",
                                inst, int(age_ms))
                    continue
                # Refresh timing fields so dashboard age display starts fresh
                snap["thesisAgeMs"]    = max(0, int(age_ms))
                snap["lastUpdatedAt"]  = now_dt.isoformat()
                # Reject cooldown-expired snapshots
                if snap.get("status") == "COOLDOWN":
                    cu = snap.get("cooldownUntil")
                    if cu:
                        try:
                            from datetime import timezone as _tz
                            cu_dt = datetime.fromisoformat(cu)
                            if cu_dt.tzinfo is None:
                                cu_dt = cu_dt.replace(tzinfo=_tz.utc)
                            if now_dt >= cu_dt:
                                logger.info("Thesis restore: %s cooldown expired — resetting", inst)
                                continue
                        except (ValueError, TypeError):
                            continue
                with THESIS_LOCK:
                    THESIS_BY_INST[inst] = snap
                logger.info("Thesis restored: %s %s conf=%s%%",
                            inst, snap.get("status"), snap.get("confidence"))
                restored += 1
            except Exception as row_exc:
                logger.debug("Thesis restore row error [%s]: %s", inst, row_exc)
        logger.info("Thesis restore complete: %d instrument(s) loaded", restored)
    except Exception as exc:
        logger.warning("_restore_thesis_states fail-open: %s", exc)

# ── Post-update hook ──────────────────────────────────────────────────────────

def _thesis_post_update(inst, prev_snap, new_snap):
    """Called from _apply_thesis after _apply_thesis_inner completes.
    Records timeline events, triggers Discord notifications, and schedules
    a DB persist for any significant change. All three subsystems are fail-open
    and never block the caller."""
    try:
        prev_st   = prev_snap.get("status",     "NEUTRAL")
        new_st    = new_snap.get("status",      "NEUTRAL")
        prev_conf = int(prev_snap.get("confidence") or 0)
        new_conf  = int(new_snap.get("confidence")  or 0)
        status_changed = (prev_st != new_st)
        conf_delta     = abs(new_conf - prev_conf)
        if not (status_changed or conf_delta >= 5):
            return
        _record_thesis_event(inst, prev_snap, new_snap)
        # Phase 3: mark untriggered setups stale on direction flip or invalidation
        _mark_setups_stale_for_inst(inst, prev_snap, new_snap)
        if _THESIS_DISCORD_ALERTS_ENABLED:
            _maybe_send_thesis_notification(inst, prev_snap, new_snap)
        if _THESIS_DB_PERSISTENCE_ENABLED and THESIS_DB_READY:
            _snap_copy = dict(new_snap)
            _enqueue_slow(lambda i=inst, s=_snap_copy: _persist_thesis_state(i, s))
    except Exception as exc:
        logger.debug("_thesis_post_update fail-open [%s]: %s", inst, exc)

# ─────────────────────────────────────────────────────────────────────────────

def _apply_thesis(inst, strict, raw_verdict, trade_plan=None):
    """Apply confidence hysteresis and return (adjusted_verdict, thesis_snapshot).

    FAIL-OPEN: any exception falls back to (raw_verdict, {}) so the money path is
    never blocked by a thesis bug.
    FLAG-OFF:  THESIS_HYSTERESIS=0 → immediate (raw_verdict, {}) passthrough.
    """
    if not _THESIS_ENABLED or not inst:
        return raw_verdict, {}
    try:
        # Snapshot prev state before inner runs (needed for Phase 2 post-update diff)
        with THESIS_LOCK:
            _prev = dict(THESIS_BY_INST.get(inst) or {})
        adj, snap = _apply_thesis_inner(inst, strict, raw_verdict, trade_plan)
        # Phase 2: timeline + Discord + DB (all fail-open; never block money path)
        _thesis_post_update(inst, _prev, snap)
        return adj, snap
    except Exception as _te:
        logger.warning("_apply_thesis fail-open [%s]: %s", inst, _te)
        return raw_verdict, {}


def _apply_thesis_inner(inst, strict, raw_verdict, trade_plan):
    """Core thesis state-machine update. Called only by _apply_thesis()."""
    now    = now_utc()
    now_ms = now.timestamp() * 1000

    # ── Extract gate evidence from evaluate_strict_setup output ──────────────
    raw_score    = int(strict.get("score") or 0)
    raw_dir      = strict.get("direction") or strict.get("candidate")
    gd           = strict.get("gate_debug") or {}
    zone_valid   = bool(gd.get("zone_valid"))
    vwap_valid   = bool(gd.get("vwap_confirmed"))
    struct_valid = bool(gd.get("structure_confirmed"))
    sweep_conf   = bool(gd.get("sweep_confirmed"))
    vol_conf     = bool(gd.get("volume_confirmed"))
    session_ok   = bool(gd.get("session"))
    is_raw_ready = is_actionable(raw_verdict)

    # ── Hard invalidation (zone broken in SWING; structural break with no direction)
    zone_req     = bool(cfg_for(TRADING_MODE, "GATE_REQUIRE_ZONE"))
    zone_broken  = bool(zone_req and (
        strict.get("zone_broken_active")
        or ("zone_valid" in (strict.get("missing") or []))
    ))
    struct_lost  = bool(
        not raw_dir
        and ("structure_confirmed" in (strict.get("missing") or []))
    )
    hard_invalid = zone_broken or struct_lost

    # ── CVD state (direction-relative) ───────────────────────────────────────
    _cvd      = CVD_BY_TICKER.get(inst) or {}
    _cvd_raw  = (_cvd.get("state") or "").lower()
    _cvd_ts   = _cvd.get("ts")
    if not _cvd_raw:
        cvd_label = "UNKNOWN"
    elif _cvd_ts:
        try:
            _age = (now - datetime.fromisoformat(_cvd_ts)).total_seconds()
            cvd_label = "STALE" if _age > 600 else _cvd_raw.upper()
        except (ValueError, TypeError):
            cvd_label = _cvd_raw.upper()
    else:
        cvd_label = _cvd_raw.upper()

    if raw_dir == "Long":
        cvd_aligned = cvd_label in ("BULLISH", "NEUTRAL", "UNKNOWN", "STALE")
    elif raw_dir == "Short":
        cvd_aligned = cvd_label in ("BEARISH", "NEUTRAL", "UNKNOWN", "STALE")
    else:
        cvd_aligned = True

    # ── Evidence lists ────────────────────────────────────────────────────────
    ev_for, ev_against = [], []
    if struct_valid:
        ev_for.append("STRUCTURE_BULLISH" if raw_dir == "Long" else "STRUCTURE_BEARISH")
    else:
        ev_against.append("STRUCTURE_INVALIDATED")
    if zone_valid:    ev_for.append("ZONE_ACTIVE")
    elif zone_broken: ev_against.append("ZONE_CONSUMED")
    else:             ev_against.append("ZONE_INACTIVE")
    if vwap_valid:  ev_for.append("VWAP_ALIGNED")
    else:           ev_against.append("VWAP_OPPOSING")
    if cvd_label == "BULLISH" and raw_dir == "Long":    ev_for.append("CVD_ALIGNED")
    elif cvd_label == "BEARISH" and raw_dir == "Short": ev_for.append("CVD_ALIGNED")
    elif cvd_label in ("BULLISH", "BEARISH"):           ev_against.append("CVD_OPPOSING")
    if sweep_conf:   ev_for.append("SWEEP_CONFIRMED")
    if vol_conf:     ev_for.append("VOLUME_CONFIRMED")
    if session_ok:   ev_for.append("PRIME_SESSION")

    # All required gates (zone gate is mode-dependent)
    all_gates = struct_valid and vwap_valid and (zone_valid if zone_req else True)

    with THESIS_LOCK:
        prev        = THESIS_BY_INST.get(inst)
        prev_dir    = prev["direction"]  if prev else None
        prev_status = prev["status"]     if prev else "NEUTRAL"
        prev_conf   = prev["confidence"] if prev else 0

        # ── Cooldown check ────────────────────────────────────────────────────
        if prev and prev_status == "COOLDOWN":
            cu = prev.get("cooldownUntil")
            if cu:
                try:
                    cu_dt = datetime.fromisoformat(cu)
                    if now < cu_dt:
                        t = dict(prev)
                        t["thesisAgeMs"] = max(0, int(now_ms - datetime.fromisoformat(
                            t["createdAt"]).timestamp() * 1000))
                        t["cooldownRemainingMs"] = max(0, int(
                            (cu_dt.timestamp() - now.timestamp()) * 1000))
                        THESIS_BY_INST[inst] = t
                        return "WAIT", dict(t)
                except (ValueError, TypeError):
                    pass
            # Cooldown expired → reset so a fresh thesis can form
            prev = None
            prev_dir = prev_status = None
            prev_conf = 0

        # ── Reversal protection ───────────────────────────────────────────────
        # An opposite-direction signal below REVERSAL_THRESHOLD only weakens the
        # existing thesis; it does NOT flip direction. The user sees confidence
        # falling while the original direction holds until hard-invalidated.
        is_reversal = (
            prev and raw_dir and prev_dir
            and raw_dir != prev_dir
            and prev_status in ("FORMING_LONG", "FORMING_SHORT",
                                "READY_LONG",   "READY_SHORT")
        )
        if is_reversal and raw_score < _THESIS_REVERSAL_THRESHOLD:
            new_conf  = max(0, prev_conf - _THESIS_MAX_CONF_DROP)
            codes     = ["REVERSAL_THRESHOLD_NOT_REACHED", "CONFIDENCE_DECREASED"]
            t = dict(prev)
            t["previousConfidence"] = prev_conf
            t["confidence"]         = new_conf
            t["confidenceState"]    = _thesis_confidence_label(new_conf)
            t["lastUpdatedAt"]      = now.isoformat()
            t["evidenceFor"]        = ev_for
            t["evidenceAgainst"]    = ev_against
            t["cvdState"]           = cvd_label
            t["reasonCodes"]        = codes
            if new_conf < prev_conf:
                t["lastWeakenedAt"] = now.isoformat()
            # Demote if fell below hold threshold
            if new_conf < _THESIS_HOLD_THRESHOLD and t["status"] in ("READY_LONG", "READY_SHORT"):
                t["status"] = "FORMING_LONG" if t["direction"] == "Long" else "FORMING_SHORT"
            t["thesisAgeMs"] = max(0, int(now_ms - datetime.fromisoformat(
                t["createdAt"]).timestamp() * 1000))
            THESIS_BY_INST[inst] = t
            # Verdict: maintain READY only if still in hold band
            if t["status"] in ("READY_LONG", "READY_SHORT") and new_conf >= _THESIS_HOLD_THRESHOLD:
                adj = "LONG READY" if t["direction"] == "Long" else "SHORT READY"
            else:
                adj = "WAIT"
            return adj, dict(t)

        # ── Decide whether to start a new thesis or update existing ──────────
        # ── Genuine reversal above threshold → treat as a brand-new thesis ────
        # The reversal-protection block above handled score < threshold (weaken +
        # keep direction). When score >= REVERSAL_THRESHOLD the flip is confirmed;
        # we reset `prev` so `needs_new` triggers a fresh blank thesis with a new
        # thesisId — the old direction is gone.
        if is_reversal and raw_score >= _THESIS_REVERSAL_THRESHOLD:
            prev = None

        needs_new = (
            not prev
            or prev_status in ("NEUTRAL", "INVALIDATED")
        )
        if needs_new:
            if not raw_dir:
                t = _thesis_blank(inst, None, now)
                t["status"] = "NEUTRAL"
                THESIS_BY_INST[inst] = t
                return "WAIT", dict(t)
            t          = _thesis_blank(inst, raw_dir, now)
            base_conf  = raw_score   # fresh thesis starts at raw score (no inertia yet)
        else:
            t         = dict(prev)
            base_conf = prev_conf

        # ── Hard invalidation (always overrides the hold band) ────────────────
        if hard_invalid:
            inv_reason = ("Zone consumed"      if zone_broken else
                          "Structure lost"     if struct_lost  else "Hard invalidation")
            t["status"]             = "INVALIDATED"
            t["confidence"]         = 0
            t["previousConfidence"] = base_conf
            t["confidenceState"]    = "INVALIDATED"
            t["invalidationReason"] = inv_reason
            t["lastUpdatedAt"]      = now.isoformat()
            t["lastWeakenedAt"]     = now.isoformat()
            t["evidenceFor"]        = ev_for
            t["evidenceAgainst"]    = ev_against
            t["cvdState"]           = cvd_label
            t["reasonCodes"]        = [
                "ZONE_CONSUMED" if zone_broken else "STRUCTURE_INVALIDATED"
            ]
            t["cooldownUntil"]      = (
                now + timedelta(milliseconds=_THESIS_REVERSAL_COOLDOWN_MS)
            ).isoformat()
            t["thesisAgeMs"] = max(0, int(now_ms - datetime.fromisoformat(
                t["createdAt"]).timestamp() * 1000))
            THESIS_BY_INST[inst] = t
            return "WAIT", dict(t)

        # ── Confidence delta (inertia: fall capped; rise immediate) ──────────
        codes = []
        if raw_score >= base_conf:
            new_conf = raw_score
            codes.append("CONFIDENCE_INCREASED")
        else:
            new_conf = max(raw_score, base_conf - _THESIS_MAX_CONF_DROP)
            codes.append("CONFIDENCE_DECREASED")

        t["previousConfidence"] = base_conf
        t["confidence"]         = new_conf
        t["confidenceState"]    = _thesis_confidence_label(new_conf)
        t["lastUpdatedAt"]      = now.isoformat()
        if new_conf > base_conf:
            t["lastStrengthenedAt"] = now.isoformat()
            codes.append("CONFIDENCE_INCREASED")
        elif new_conf < base_conf:
            t["lastWeakenedAt"] = now.isoformat()

        # ── Snapshot gate state ───────────────────────────────────────────────
        t["vwapAligned"]        = vwap_valid
        t["cvdAligned"]         = cvd_aligned
        t["cvdState"]           = cvd_label
        t["sweepConfirmed"]     = sweep_conf
        t["volumeConfirmed"]    = vol_conf
        t["sessionPrime"]       = session_ok
        t["structureDirection"] = raw_dir or t.get("direction")
        t["direction"]          = raw_dir or t.get("direction")
        t["evidenceFor"]        = ev_for
        t["evidenceAgainst"]    = ev_against

        # Trade plan snapshot (for journal / dashboard)
        if trade_plan and trade_plan.get("trade_plan"):
            t["entry"]   = trade_plan.get("entry_zone")
            t["stop"]    = trade_plan.get("stop_loss")
            t["targets"] = [trade_plan.get("target1"), trade_plan.get("target2")]

        # ── Status machine ────────────────────────────────────────────────────
        prev_was_ready = prev_status in ("READY_LONG", "READY_SHORT")

        if is_raw_ready and all_gates and new_conf >= _THESIS_READY_THRESHOLD:
            # Promote (or re-confirm) READY
            new_status = "READY_LONG" if t["direction"] == "Long" else "READY_SHORT"
            if not prev_was_ready:
                t["readyAt"] = now.isoformat()
                codes.append("READY_THRESHOLD_REACHED")
            else:
                codes.append("HOLD_THRESHOLD_MAINTAINED")
        elif prev_was_ready and new_conf >= _THESIS_HOLD_THRESHOLD:
            # Hysteresis hold — stay READY despite raw WAIT
            new_status = prev_status
            codes.append("HOLD_THRESHOLD_MAINTAINED")
        elif t.get("direction"):
            new_status = "FORMING_LONG" if t["direction"] == "Long" else "FORMING_SHORT"
        else:
            new_status = "NEUTRAL"

        t["status"]      = new_status
        t["reasonCodes"] = codes

        # Ready age
        if new_status in ("READY_LONG", "READY_SHORT") and t.get("readyAt"):
            try:
                t["readyAgeMs"] = max(0, int(
                    (now - datetime.fromisoformat(t["readyAt"])).total_seconds() * 1000
                ))
            except (ValueError, TypeError):
                t["readyAgeMs"] = 0

        # Thesis age
        try:
            t["thesisAgeMs"] = max(0, int(
                (now - datetime.fromisoformat(t["createdAt"])).total_seconds() * 1000
            ))
        except (ValueError, TypeError):
            t["thesisAgeMs"] = 0

        THESIS_BY_INST[inst] = t

        # ── Adjusted verdict ──────────────────────────────────────────────────
        if new_status in ("READY_LONG", "READY_SHORT"):
            adj = "LONG READY" if t["direction"] == "Long" else "SHORT READY"
        else:
            adj = raw_verdict   # WAIT / SETUP BUILDING pass through unchanged

        return adj, dict(t)


def get_thesis_snapshot(inst):
    """Return a copy of the current thesis for `inst` (None if not present)."""
    if not inst:
        return None
    with THESIS_LOCK:
        t = THESIS_BY_INST.get(inst)
        return dict(t) if t else None


