@app.route("/backtest/coverage", methods=["GET"])
def bt_coverage():
    """Owner-only READ-ONLY registry diagnostics. No backtest is executed.
    Returns static registry comparison between the live strategy engine and the
    backtest engine — the authoritative answer to 'why four strategies?'"""
    guard = _bt_guard()
    if guard:
        return guard
    live_keys   = set(STRATEGY_DEFS)
    bt_keys     = set(bt.STRATEGY_DEFS)
    bt_det_keys = set(bt.DETECTORS)
    bt_order    = list(bt.STRATEGY_ORDER)
    bt_disabled = set(bt.DISABLED_STRATEGIES)
    all_keys = sorted(live_keys | bt_keys)
    strategies = []
    for key in all_keys:
        in_live      = key in live_keys and key in STRATEGY_SCORERS
        in_bt_defs   = key in bt_keys
        has_adapter  = key in bt_det_keys
        in_order     = key in bt_order
        disabled     = key in bt_disabled
        eligible     = has_adapter and not disabled and in_order
        label = (STRATEGY_DEFS.get(key) or bt.STRATEGY_DEFS.get(key) or {}).get("label", key)
        if disabled:
            reason = "disabled_by_request"
        elif not in_bt_defs:
            reason = "no_backtest_definition"
        elif not has_adapter:
            reason = "no_historical_adapter"
        elif not in_order:
            reason = "excluded_from_strategy_order"
        else:
            reason = None
        strategies.append({
            "strategy_key":          key,
            "label":                 label,
            "defined":               key in live_keys or in_bt_defs,
            "live_registered":       in_live,
            "backtest_registered":   in_bt_defs,
            "has_historical_adapter": has_adapter,
            "in_strategy_order":     in_order,
            "disabled":              disabled,
            "eligible":              eligible,
            "would_be_dispatched":   eligible,
            "reason":                reason,
        })
    eligible_count = sum(1 for s in strategies if s["eligible"])
    live_only  = sorted(live_keys - bt_keys)
    bt_only    = sorted(bt_keys - live_keys)
    shared     = sorted(live_keys & bt_keys)
    return jsonify({
        "ok": True,
        "live_engine": {
            "defined_count":     len(live_keys),
            "registered_count":  len([k for k in live_keys if k in STRATEGY_SCORERS]),
            "strategies":        sorted(live_keys),
        },
        "backtest_engine": {
            "defined_count":     len(bt_keys),
            "detector_count":    len(bt_det_keys),
            "order_count":       len(bt_order),
            "disabled_count":    len(bt_disabled),
            "eligible_count":    eligible_count,
            "strategy_order":    bt_order,
            "disabled_strategies": sorted(bt_disabled),
        },
        "gaps": {
            "live_only":         live_only,
            "backtest_only":     bt_only,
            "shared_eligible":   [k for k in shared if k not in bt_disabled and k in bt_det_keys and k in bt_order],
        },
        "global_subset": eligible_count < len(live_keys),
        "strategies":    strategies,
    })


@app.route("/backtest/export", methods=["GET"])
def bt_export():
    guard = _bt_guard()
    if guard:
        return guard
    try:
        run_id = int(request.args.get("run_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "run_id required"}), 400
    run = _bt_get_run(run_id)
    if not run or not run.get("result"):
        return jsonify({"ok": False, "error": "no completed run with that id"}), 404
    result = run["result"] or {}
    if result.get("kind") == "optimization":
        buf = _bt_io_mod.StringIO()
        cols = ["rank", "strategy", "management", "score_min", "grade", "session",
                "trend", "volume", "regime", "trades", "win_rate", "profit_factor",
                "net_r", "avg_r", "avg_win_r", "avg_loss_r", "max_dd_r",
                "best_hour", "best_regime"]
        labels = result.get("labels", {})
        w = _bt_csv_mod.writer(buf)
        w.writerow(cols)
        for idx, row in enumerate(result.get("table", []), start=1):
            w.writerow([
                idx,
                labels.get("strategy", {}).get(row.get("strategy"), row.get("strategy")),
                labels.get("mgmt", {}).get(row.get("mgmt"), row.get("mgmt")),
                row.get("score"),
                labels.get("grade", {}).get(row.get("grade"), row.get("grade")),
                labels.get("session", {}).get(row.get("session"), row.get("session")),
                labels.get("trend", {}).get(row.get("trend"), row.get("trend")),
                labels.get("volume", {}).get(row.get("volume"), row.get("volume")),
                row.get("regime", ""),
                row.get("trades"), row.get("win_rate"), row.get("pf"),
                row.get("net_r"), row.get("avg_r"), row.get("avg_win_r"),
                row.get("avg_loss_r"), row.get("max_dd_r"),
                row.get("best_hour_label"), row.get("best_regime"),
            ])
        csv_text = buf.getvalue()
        return Response(csv_text, mimetype="text/csv",
                        headers={"Content-Disposition":
                                 f'attachment; filename="optimization_run_{run_id}.csv"'})
    trades = result.get("trades", [])
    buf = _bt_io_mod.StringIO()
    cols = ["strategy", "direction", "entry_ts", "exit_ts", "entry", "stop", "exit",
            "tp1", "tp3", "risk_points", "gross_points", "pnl_dollars", "r_multiple",
            "regime", "session", "entry_hour_et", "hold_minutes", "entry_reason",
            "exit_reason"]
    w = _bt_csv_mod.writer(buf)
    w.writerow(cols)
    for t in trades:
        w.writerow([t.get(c) for c in cols])
    csv_text = buf.getvalue()
    return Response(csv_text, mimetype="text/csv",
                    headers={"Content-Disposition":
                             f'attachment; filename="backtest_run_{run_id}.csv"'})


