def _scalp_sim_live_ctx(result):
    """Normalize a full_analysis `result` (+ the same live helpers the gate uses)
    into the flat live-context dict the PURE scalp_live_sim detectors consume.
    Read-only; FAIL-OPEN (returns None if the essentials are missing). Never
    mutates `result`."""
    try:
        inst = instrument_of(result.get("active_ticker") or "")
        if not inst:
            return None
        price = result.get("current_price")
        ctx = build_strategy_context(inst, price, result.get("vwap_value"),
                                     result.get("vwap_status"),
                                     result.get("volatility") or {})
        if not isinstance(ctx, dict):
            return None
        try:
            regime = (detect_market_regime(ctx) or {}).get("regime")
        except Exception:
            regime = None
        l = dict(ctx)
        l["atr"]             = ctx.get("atr_pts")
        l["rvol"]            = ctx.get("rvol_value")
        l["regime"]          = regime
        l["price"]           = price if price is not None else ctx.get("price")
        l["nearest_demand"]  = result.get("nearest_demand")
        l["nearest_supply"]  = result.get("nearest_supply")
        l["inst"]            = inst
        _sess_raw            = result.get("session") or {}
        l["session"]         = (_sess_raw.get("window") or _sess_raw.get("status")
                                if isinstance(_sess_raw, dict) else _sess_raw)
        l["edge_score"]      = result.get("edge_score")
        return l
    except Exception:
        return None


def _scalp_strategy_advisory_neutral(reason="Strategy advisory disabled.",
                                     instrument=None, enabled=False):
    """Stable neutral block — the schema contract for the advisory layer. Never raises."""
    return {
        "enabled":      bool(enabled),
        "available":    False,
        "instrument":   instrument,
        "generated_at": now_utc().isoformat(),
        "summary":      reason,
        "candidates":   [],
        "votes":        [],
        "consensus":    {
            "bullish": 0, "bearish": 0, "neutral": 0, "total": 0,
            "strongest_long": None, "strongest_short": None, "bias": "Neutral",
        },
    }


def _strategy_pretty_name(key):
    """'vwap_pullback_continuation' -> 'Vwap Pullback Continuation' (display only)."""
    try:
        return str(key).replace("_", " ").title()
    except Exception:
        return str(key)


def _advisory_dir_from_bias(bias):
    """Map a textual bias to 'Long'/'Short'/None — DISPLAY only, never raises."""
    try:
        b = (bias or "").lower()
    except Exception:
        return None
    if "bull" in b or "long" in b:
        return "Long"
    if "bear" in b or "short" in b:
        return "Short"
    return None


def _analyze_advisory_candidate(cand, result, regime):
    """Derive a DISPLAY-ONLY confluence read for ONE detector candidate, purely from
    fields already computed on `result` (no new scorer, no gate, no money path). Returns
    the candidate enriched with quality/recommendation/confluence/conflicts. The caller
    also guards, but this never raises on missing/None fields."""
    direction = cand.get("direction")
    confluence, conflicts = [], []
    score = 30

    # Favored / dominant direction from the authoritative strict output (read-only).
    favored = result.get("dominant_direction") or _advisory_dir_from_bias(result.get("bias"))
    strict_aligned = bool(favored and direction and favored == direction)
    if strict_aligned:
        confluence.append("Aligned with main bias")
        score += 18
    elif favored and direction and favored != direction:
        conflicts.append("Against main bias (%s)" % favored)
        score -= 16

    # VWAP side (vwap_status is freshness, NOT direction — derive side from price).
    price = result.get("current_price")
    vwap  = result.get("vwap_value")
    if price is not None and vwap is not None:
        try:
            vwap_dir = "Long" if float(price) >= float(vwap) else "Short"
            if vwap_dir == direction:
                confluence.append("Price on VWAP side")
                score += 12
            else:
                conflicts.append("Against VWAP")
                score -= 12
        except Exception:
            pass

    # CVD agreement (read-only directional confirm).
    cvd = result.get("cvd_direction")
    if cvd in ("Long", "Short") and direction in ("Long", "Short"):
        if cvd == direction:
            confluence.append("CVD agrees")
            score += 12
        else:
            conflicts.append("CVD opposes")
            score -= 16

    # Volume participation (RVOL >= 1.5).
    rvol = result.get("rvol_value")
    try:
        if rvol is not None and float(rvol) >= 1.5:
            confluence.append("Volume surge (RVOL %.1f)" % float(rvol))
            score += 8
    except Exception:
        pass

    # Overall Edge Score (read-only; counts only when not pointing the other way).
    edge = result.get("edge_score")
    try:
        if edge is not None and float(edge) >= 70 and (not favored or favored == direction):
            confluence.append("Strong Edge Score (%d)" % int(float(edge)))
            score += 12
    except Exception:
        pass

    # Regime fit (continuation likes trends; mean-reversion likes ranges).
    rkey = regime.upper() if isinstance(regime, str) else ""
    skey = cand.get("strategy_key") or ""
    mean_rev = skey in _ADVISORY_MEAN_REVERSION_KEYS
    if rkey:
        if "TREND" in rkey and not mean_rev:
            confluence.append("Fits trending regime")
            score += 8
        elif ("RANGE" in rkey or "CHOP" in rkey) and mean_rev:
            confluence.append("Fits ranging regime")
            score += 8
        elif "TREND" in rkey and mean_rev:
            conflicts.append("Mean-reversion in a trend")
            score -= 8

    # HTF alignment (SWING context, when present — display only).
    htf_alignment = None
    sc = result.get("swing_context")
    if isinstance(sc, dict):
        htf_bias = _advisory_dir_from_bias(sc.get("bias") or sc.get("htf_bias"))
        if htf_bias and direction:
            if htf_bias == direction:
                htf_alignment = "aligned"
                confluence.append("HTF bias aligned")
                score += 10
            else:
                htf_alignment = "against"
                conflicts.append("Against HTF bias")
                score -= 10

    score = max(0, min(100, score))
    if score >= 75:
        label = "Strong"
    elif score >= 55:
        label = "Moderate"
    elif score >= 40:
        label = "Marginal"
    else:
        label = "Low"

    if conflicts and score < 40:
        rec = "Skip"
    elif score >= 70 and strict_aligned:
        rec = "Consider"
    elif score >= 55:
        rec = "Watch"
    else:
        rec = "Monitor"

    # Display-only status + invalidation (advisory; never a money-path signal).
    if rec == "Skip":
        status = "REJECTED"
    elif rec == "Consider":
        status = "READY"
    else:
        status = "WATCHING"
    invalidation = None
    try:
        _stop = cand.get("stop")
        if _stop is not None:
            _side = "below" if direction == "Long" else "above"
            invalidation = "Invalid on a decisive move %s %.2f (stop)" % (_side, float(_stop))
        elif favored and direction and favored != direction:
            invalidation = "Invalid while the main bias stays %s" % favored
        else:
            invalidation = "Invalid if structure flips against %s" % (direction or "the setup")
    except Exception:
        invalidation = None

    return {
        "strategy_key":     skey,
        "name":             _strategy_pretty_name(skey),
        "direction":        direction,
        "entry_reason":     cand.get("entry_reason"),
        "fidelity":         cand.get("fidelity"),
        "entry":            cand.get("entry"),
        "stop":             cand.get("stop"),
        "target":           cand.get("target"),
        "risk":             cand.get("risk"),
        "rr":               cand.get("rr"),
        "quality_label":    label,
        "quality_score":    score,
        "recommendation":   rec,
        "confluence":       confluence,
        "conflicts":        conflicts,
        "regime":           regime,
        "htf_alignment":    htf_alignment,
        "strict_alignment": strict_aligned,
        "status":           status,
        "invalidation":     invalidation,
    }


def _advisory_strategy_votes(lctx, analyzed, result, regime):
    """DISPLAY-ONLY: the full 16-strategy vote roster. Pass/fail/direction/reason come
    from the PURE detectors (sls.diagnose_strategies); confidence reuses the same
    confluence scorer as the ranked candidates so a passed strategy's number matches
    its card. Failed strategies vote Neutral with confidence 0 + a 'missing' hint.
    FAIL-OPEN — never raises, never touches the money path."""
    try:
        import scalp_live_sim as sls
        raw = sls.diagnose_strategies(lctx) or []
    except Exception:
        raw = []
    score_by_key = {}
    for c in (analyzed or []):
        k = c.get("strategy_key")
        if k is not None:
            score_by_key[k] = c.get("quality_score")
    votes = []
    for v in raw:
        key = v.get("strategy_key")
        passed = bool(v.get("passed"))
        direction = v.get("direction") or "Neutral"
        if passed:
            conf = score_by_key.get(key)
            if conf is None:
                try:
                    conf = _analyze_advisory_candidate(
                        {"strategy_key": key, "direction": direction}, result, regime
                    ).get("quality_score", 0)
                except Exception:
                    conf = 0
        else:
            conf = 0
        votes.append({
            "strategy_key": key,
            "name":         _strategy_pretty_name(key),
            "direction":    direction if passed else "Neutral",
            "passed":       passed,
            "confidence":   conf,
            "reason":       v.get("reason"),
            "missing":      v.get("missing") or [],
            "fidelity":     v.get("fidelity"),
        })
    return votes


def _advisory_consensus(votes):
    """DISPLAY-ONLY consensus across the strategy votes: bullish / bearish / neutral
    counts, the strongest setup on each side, and an overall advisory bias. Never
    raises; counts ONLY passed (firing) votes as directional."""
    votes = votes or []
    bull = [v for v in votes if v.get("passed") and v.get("direction") == "Long"]
    bear = [v for v in votes if v.get("passed") and v.get("direction") == "Short"]
    total = len(votes)
    neutral = total - len(bull) - len(bear)

    def _strongest(group):
        if not group:
            return None
        best = max(group, key=lambda v: (v.get("confidence") or 0))
        return {"name": best.get("name"), "direction": best.get("direction"),
                "confidence": best.get("confidence")}

    if len(bull) > len(bear):
        bias = "Long"
    elif len(bear) > len(bull):
        bias = "Short"
    else:
        sb = sum((v.get("confidence") or 0) for v in bull)
        ss = sum((v.get("confidence") or 0) for v in bear)
        bias = "Long" if sb > ss else ("Short" if ss > sb else "Neutral")
    return {
        "bullish":         len(bull),
        "bearish":         len(bear),
        "neutral":         neutral,
        "total":           total,
        "strongest_long":  _strongest(bull),
        "strongest_short": _strongest(bear),
        "bias":            bias,
    }


# ===========================================================================
# LIQUIDITY SWEEP FOCUS (DISPLAY/ADVISORY-ONLY)
# ===========================================================================
# Flag-gated Main-Brain overlay (see the flag comment for the money-path wall). It
# CONSUMES the assembled `result` plus pure read-only helpers (get_price_context,
# _intraday_or, the intraday session tracker) and reports where liquidity sits, whether
# it was recently swept, and how to read that sweep. It NEVER recomputes the gate, never
# scores the Edge, never sizes, never trades. The advisory_confidence_delta is DISPLAY
# ONLY and is never fed anywhere. FAIL-OPEN (its caller also wraps it -> neutral).
# ---------------------------------------------------------------------------

def _liquidity_sweep_focus_neutral(reason="Liquidity Sweep Focus disabled.",
                                   instrument=None, enabled=False):
    """Stable neutral schema for the Liquidity Sweep Focus overlay. Never raises."""
    return {
        "enabled":                   bool(enabled),
        "available":                 False,
        "instrument":                instrument,
        "generated_at":              now_utc().isoformat(),
        "state":                     "NO SWEEP",
        "state_key":                 "none",
        "direction":                 None,
        "sweep_type":                None,
        "swept":                     False,
        "reclaim":                   False,
        "rejection":                 False,
        "into_opposing_zone":        False,
        "cvd_state":                 None,
        "cvd_confirming":            None,
        "nearby_liquidity":          None,
        "nearby_liquidity_text":     "None nearby",
        "levels":                    [],
        "advisory_confidence_delta": 0,
        "advisory_reasons":          [],
        "warning":                   False,
        "trader_read":               "No liquidity swept yet",
        "questions": {
            "nearby_liquidity":           "None nearby",
            "swept":                      False,
            "rejection_after_sweep":      False,
            "reclaim":                    False,
            "cvd_confirming":             None,
            "true_sweep_vs_continuation": "undecided",
        },
        "voice":                     reason,
        "summary":                   reason,
        "advisory_only":             True,
    }


def compute_liquidity_sweep_focus(result):
    """Liquidity Sweep Focus overlay — see the section header for the money-path wall.

    Builds the nearby liquidity map (session / opening-range / VWAP / zone / swing /
    equal H-L), scans ALERT_HISTORY for a RECENT instrument-scoped sweep, and derives a
    sweep state in {NO SWEEP, SWEEP FORMING, SWEEP CONFIRMED, SWEEP FAILED, CONTINUATION
    THROUGH LIQUIDITY} plus a trader read, a Main-Brain voice line and an ADVISORY-ONLY
    confidence delta. CONSUMES `result` + pure read-only helpers only. FAIL-OPEN."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    out = _liquidity_sweep_focus_neutral("", inst_label, enabled=True)

    # Market closed -> nothing live to read; stay neutral (state-aware, so the single
    # attach at the return seam covers open / vetoed / closed with no separate mirror).
    if not result.get("market_open"):
        out["available"]   = True
        out["state"]       = "NO SWEEP"
        out["trader_read"] = "Market closed"
        out["voice"]       = ("Market closed — no live liquidity to track; will resume at "
                              "the next session open.")
        out["summary"]     = out["voice"]
        return out

    inst = instrument_of(inst_label) if inst_label else None
    price = result.get("current_price")
    try:
        price = float(price) if price is not None else None
    except (TypeError, ValueError):
        price = None
    vwap = result.get("vwap_value")
    ns   = result.get("nearest_supply")
    nd   = result.get("nearest_demand")
    cvd  = str(result.get("cvd_state") or "").lower()
    cvd  = cvd if cvd in ("bullish", "bearish") else None
    out["cvd_state"] = cvd

    # ── Nearby liquidity map (every read is pure / side-effect-free) ─────────
    levels = []
    def _add(label, px):
        try:
            pxf = float(px)
        except (TypeError, ValueError):
            return
        if price is None:
            side = None
        elif pxf > price:
            side = "above"
        elif pxf < price:
            side = "below"
        else:
            side = "at"
        levels.append({"label": label, "price": round(pxf, 2), "side": side})

    # Per-session highs/lows (current + prior), read under the intraday lock.
    try:
        with INTRADAY_LOCK:
            rec = INTRADAY_BY_TICKER.get(inst) or {}
            sessions = {k: dict(v) for k, v in (rec.get("sessions") or {}).items()
                        if isinstance(v, dict)}
        cur_name, _cur_id = _bias_session_for(now_utc().astimezone(ET_TZ))
        for name, s in sessions.items():
            tag = "current" if name == cur_name else "prior"
            _add("%s session high (%s)" % (name, tag), s.get("high"))
            _add("%s session low (%s)"  % (name, tag), s.get("low"))
    except Exception:
        pass

    # Opening range (08:00 ET) high/low.
    try:
        orb = _intraday_or(inst)
        _add("Opening range high", orb.get("high"))
        _add("Opening range low",  orb.get("low"))
    except Exception:
        pass

    # VWAP + nearest supply/demand zones.
    _add("VWAP", vwap)
    _add("Supply zone", ns)
    _add("Demand zone", nd)

    # Previous swing highs/lows from structure (BOS / CHOCH last prices).
    lpt = result.get("last_price_by_type") or {}
    _add("Swing high (BOS supply)",   lpt.get("BOS SUPPLY"))
    _add("Swing low (BOS demand)",    lpt.get("BOS DEMAND"))
    _add("Swing high (CHOCH supply)", lpt.get("CHOCH SUPPLY"))
    _add("Swing low (CHOCH demand)",  lpt.get("CHOCH DEMAND"))

    # Equal highs / lows — a cluster of >=2 near-equal zone prices is a liquidity pool.
    try:
        _lpt2, sup_prices, dem_prices = get_price_context(inst)
    except Exception:
        sup_prices, dem_prices = [], []
    def _equal_cluster(prices, label, tol_pct=0.0007):
        try:
            ps = sorted({round(float(p), 2) for p in prices if p is not None})
        except (TypeError, ValueError):
            return
        for i in range(len(ps)):
            grp = [ps[i]]
            for j in range(i + 1, len(ps)):
                if ps[i] and abs(ps[j] - ps[i]) / ps[i] <= tol_pct:
                    grp.append(ps[j])
            if len(grp) >= 2:
                _add(label, sum(grp) / len(grp))
                return
    _equal_cluster(sup_prices, "Equal highs")
    _equal_cluster(dem_prices, "Equal lows")

    out["levels"] = levels[:12]

    # Nearest liquidity level to price.
    nearby = None
    if price is not None:
        priced = [L for L in levels if isinstance(L.get("price"), (int, float))]
        if priced:
            nearby = min(priced, key=lambda L: abs(L["price"] - price))
            nearby = dict(nearby, distance=round(abs(nearby["price"] - price), 2))
    out["nearby_liquidity"] = nearby

    def _fmt(p):
        return ("%.2f" % p) if isinstance(p, (int, float)) else "—"
    nearby_txt = ("%s @ %s" % (nearby["label"], _fmt(nearby["price"]))) if nearby else "None nearby"
    out["nearby_liquidity_text"] = nearby_txt

    # ── Recent, instrument-scoped sweep scan (NEVER trust stale key presence) ─
    now = datetime.now(timezone.utc)
    cutoff = now - timedelta(minutes=LIQ_SWEEP_RECENCY_MIN)

    def _recent_sweep(side_word):
        want = "%s %s SWEEP" % (inst, side_word)
        for a in reversed(list(ALERT_HISTORY)):
            if a.get("alert_type") != want:
                continue
            if a.get("canonical") is False:    # skip shadow/duplicate sweep events
                continue
            a_inst = (a.get("instrument")
                      or _instrument_from_text(a.get("ticker"))
                      or _instrument_from_text(a.get("alert_type")))
            if a_inst != inst:
                continue
            try:
                ts = datetime.fromisoformat(a["timestamp"])
            except (KeyError, ValueError, TypeError):
                continue
            if ts < cutoff:
                continue
            px = a.get("price")
            try:
                px = float(px) if px is not None else None
            except (TypeError, ValueError):
                px = None
            return ts, px
        return None, None

    bull_ts, bull_px = (_recent_sweep("BULLISH") if inst else (None, None))
    bear_ts, bear_px = (_recent_sweep("BEARISH") if inst else (None, None))

    sweep_type = sweep_px = sweep_ts = None
    if bull_ts and bear_ts:
        if bull_ts >= bear_ts:
            sweep_type, sweep_px, sweep_ts = "bullish", bull_px, bull_ts
        else:
            sweep_type, sweep_px, sweep_ts = "bearish", bear_px, bear_ts
    elif bull_ts:
        sweep_type, sweep_px, sweep_ts = "bullish", bull_px, bull_ts
    elif bear_ts:
        sweep_type, sweep_px, sweep_ts = "bearish", bear_px, bear_ts

    swept = sweep_type is not None
    reclaim = rejection = into_opposing = False
    cvd_confirming = None
    direction = None
    state, state_key = "NO SWEEP", "none"

    if swept:
        if sweep_type == "bullish":
            # Lows swept (stops below taken) -> expect an UP reversal.
            direction = "Long"
            cvd_confirming = (cvd == "bullish") if cvd else None
            if price is not None and sweep_px is not None:
                reclaim = price > sweep_px
                rejection = reclaim
            if nd is not None and sweep_px:
                try:
                    into_opposing = abs(sweep_px - float(nd)) / float(nd) <= 0.0015
                except (TypeError, ValueError, ZeroDivisionError):
                    into_opposing = False
        else:
            # Highs swept (stops above taken) -> expect a DOWN reversal.
            direction = "Short"
            cvd_confirming = (cvd == "bearish") if cvd else None
            if price is not None and sweep_px is not None:
                reclaim = price < sweep_px
                rejection = reclaim
            if ns is not None and sweep_px:
                try:
                    into_opposing = abs(sweep_px - float(ns)) / float(ns) <= 0.0015
                except (TypeError, ValueError, ZeroDivisionError):
                    into_opposing = False

        if reclaim and cvd_confirming is True:
            state, state_key = "SWEEP CONFIRMED", "confirmed"
        elif reclaim:
            # Reclaimed the swept level but CVD is not yet confirming (or unknown) ->
            # forming, NOT confirmed (fail-open must never read as fail-confirmed).
            state, state_key = "SWEEP FORMING", "forming"
        else:
            # No reclaim -> price stayed beyond the swept level. Continuation if CVD
            # agrees with the BREAK direction, else a failed sweep.
            if sweep_type == "bullish":
                cont = (cvd == "bearish")
            else:
                cont = (cvd == "bullish")
            if cont:
                state, state_key = "CONTINUATION THROUGH LIQUIDITY", "continuation"
            else:
                state, state_key = "SWEEP FAILED", "failed"
    else:
        # No recent sweep alert. If price is pressed right up against a level, stops may
        # be about to get taken -> forming; otherwise nothing to anticipate.
        if nearby is not None and price and isinstance(nearby.get("price"), (int, float)):
            if abs(nearby["price"] - price) / price <= 0.0008:
                state, state_key = "SWEEP FORMING", "forming"

    out["direction"]          = direction
    out["sweep_type"]         = sweep_type
    out["swept"]              = bool(swept)
    out["reclaim"]            = bool(reclaim)
    out["rejection"]          = bool(rejection)
    out["into_opposing_zone"] = bool(into_opposing)
    out["cvd_confirming"]     = cvd_confirming
    out["state"]              = state
    out["state_key"]          = state_key
    out["available"]          = True

    # ── ADVISORY-ONLY confidence delta (DISPLAY ONLY — NEVER fed to edge/gate) ─
    delta = 0
    reasons = []
    warning = False
    if state == "SWEEP CONFIRMED" and reclaim:
        delta += 10
        reasons.append("Sweep confirmed with reclaim (+10 advisory)")
    if swept and rejection and into_opposing:
        delta += 10
        reasons.append("Sweep into opposing zone with rejection (+10 advisory)")
    if state in ("SWEEP FAILED", "CONTINUATION THROUGH LIQUIDITY"):
        warning = True
        if delta == 0:
            delta = -10
        reasons.append("Price ran through liquidity without a reversal — do not fade (warning)")
    out["advisory_confidence_delta"] = delta
    out["advisory_reasons"]          = reasons
    out["warning"]                   = warning

    # Trader read.
    if state == "SWEEP CONFIRMED":
        out["trader_read"] = "Stops taken — reversal confirming"
    elif state == "SWEEP FORMING":
        out["trader_read"] = "No confirmation yet"
    elif state in ("SWEEP FAILED", "CONTINUATION THROUGH LIQUIDITY"):
        out["trader_read"] = "Continuation risk"
    else:
        out["trader_read"] = "No liquidity swept yet"

    # Main-Brain voice line.
    if state == "SWEEP CONFIRMED":
        side_word = "below" if sweep_type == "bullish" else "above"
        need = "bullish" if direction == "Long" else "bearish"
        voice = ("Liquidity %s %s was swept and reclaimed — %s idea improves and %s CVD is "
                 "confirming; still want structure to hold before entry."
                 % (side_word, _fmt(sweep_px), direction or "this", need))
    elif state == "SWEEP FORMING" and swept:
        side_word = "below" if sweep_type == "bullish" else "above"
        need = "bullish" if sweep_type == "bullish" else "bearish"
        voice = ("Liquidity %s %s was swept — watching for a clean reclaim and %s CVD before "
                 "trusting the reversal." % (side_word, _fmt(sweep_px), need))
    elif state == "SWEEP FORMING":
        voice = ("Price is pressing into liquidity (%s) — watch for a stop-run before "
                 "committing." % nearby_txt)
    elif state in ("SWEEP FAILED", "CONTINUATION THROUGH LIQUIDITY"):
        side_word = ("below" if sweep_type == "bullish"
                     else "above" if sweep_type == "bearish" else "at")
        voice = ("Price pushed through liquidity %s %s and kept going — this reads as "
                 "continuation, not a reversal; do not fade it."
                 % (side_word, _fmt(sweep_px)))
    else:
        voice = "No liquidity has been swept near price — nothing to anticipate yet."
    out["voice"]   = voice
    out["summary"] = voice

    # The 6 trader-read questions.
    out["questions"] = {
        "nearby_liquidity":           nearby_txt,
        "swept":                      bool(swept),
        "rejection_after_sweep":      bool(rejection),
        "reclaim":                    bool(reclaim),
        "cvd_confirming":             cvd_confirming,
        "true_sweep_vs_continuation": ("sweep" if state in ("SWEEP CONFIRMED", "SWEEP FORMING") and swept
                                       else "continuation" if state == "CONTINUATION THROUGH LIQUIDITY"
                                       else "undecided"),
    }
    return out


# ===========================================================================
# Advisory overlay 1/2 — STALK MODE (pre-entry observation)
# ===========================================================================
# DISPLAY/ADVISORY-ONLY. OBSERVES a forming setup BEFORE the strict engine reaches an
# entry and packages what it is watching. It only CONSUMES values already computed on
# the assembled `result` (per-direction potential_plan, the analyst game-plan / outlook,
# strict_reason, zones, VWAP) — it never recomputes the gate, never scores, never sizes,
# never trades, never affects the Edge Score. Wall identical to the scalp-advisory layer.
# ---------------------------------------------------------------------------

def _stalk_mode_neutral(reason="Stalk Mode disabled.", instrument=None, enabled=False):
    """Stable neutral schema for the Stalk Mode overlay. Never raises."""
    return {
        "enabled":           bool(enabled),
        "available":         False,
        "instrument":        instrument,
        "generated_at":      now_utc().isoformat(),
        "state":             "idle",
        "watching":          False,
        "summary":           reason,
        "direction":         None,
        "bias":              "Neutral",
        "ideal_entry_zone":  None,
        "pullback_area":     None,
        "liquidity_target":  None,
        "stop_reference":    None,
        "target_reference":  None,
        "rr":                None,
        "why_waiting":       [],
        "extension_warning": {"active": False, "label": None, "detail": None,
                              "vwap_extension_atr": None},
        "advisory_only":     True,
    }


def compute_stalk_mode(result):
    """Pre-entry 'stalk' overlay — see the section header for the money-path wall.

    Reports the potential direction, ideal entry zone, expected pullback, liquidity
    target, why the bot is still waiting and an extension warning for a setup that is
    forming but has NOT yet triggered. CONSUMES the assembled `result` only. FAIL-OPEN
    (its caller wraps this in try/except -> neutral block)."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    out = _stalk_mode_neutral("", inst_label, enabled=True)

    # Market closed -> nothing to stalk (paused, quiet).
    if not result.get("market_open"):
        out["state"]   = "market_closed"
        out["summary"] = ("Market closed — nothing to stalk; will resume watching at "
                          "the next session open.")
        return out

    # A position is already open -> Active Trade Thinking owns this phase.
    _inst = instrument_of(inst_label) if inst_label else None
    if _inst and active_trade_for(_inst):
        out["state"]     = "in_trade"
        out["available"] = True
        out["summary"]   = ("A position is open — see Active Trade Thinking for live "
                            "management. Stalk Mode resumes once it is closed.")
        return out

    verdict = result.get("verdict") or "WAIT"

    # Favored direction (purely OBSERVED — never decided here): the strict direction if
    # one is forming, else the dominant live read, else the analyst's next-opportunity
    # bias. Falls through to "idle" when there is no directional edge to watch.
    favored = result.get("strict_direction")
    if favored not in ("Long", "Short"):
        dom = result.get("dominant_direction")
        favored = dom if dom in ("Long", "Short") else None
    analyst = result.get("analyst") if isinstance(result.get("analyst"), dict) else {}
    game_plan = analyst.get("game_plan") if isinstance(analyst.get("game_plan"), dict) else {}
    next_opp  = game_plan.get("next_opportunity") if isinstance(game_plan.get("next_opportunity"), dict) else {}
    if favored not in ("Long", "Short"):
        favored = _advisory_dir_from_bias(next_opp.get("bias"))

    directions = result.get("directions") if isinstance(result.get("directions"), dict) else {}
    blk = directions.get(favored) if (favored and isinstance(directions.get(favored), dict)) else {}
    pp  = blk.get("potential_plan") if isinstance(blk.get("potential_plan"), dict) else {}

    nd = result.get("nearest_demand")
    ns = result.get("nearest_supply")

    out["direction"]       = favored
    out["bias"]            = ("Bullish" if favored == "Long"
                              else "Bearish" if favored == "Short" else "Neutral")
    out["ideal_entry_zone"] = pp.get("entry_zone")
    out["stop_reference"]   = pp.get("stop_loss")
    out["target_reference"] = pp.get("target1")
    out["rr"]               = pp.get("rr")
    if favored == "Long":
        out["pullback_area"]    = pp.get("entry_zone") if pp.get("entry_zone") is not None else nd
        out["liquidity_target"] = pp.get("target1") if pp.get("target1") is not None else ns
    elif favored == "Short":
        out["pullback_area"]    = pp.get("entry_zone") if pp.get("entry_zone") is not None else ns
        out["liquidity_target"] = pp.get("target1") if pp.get("target1") is not None else nd

    # Why the bot is still waiting — the strict reason plus any analyst color.
    reasons = []
    sr = result.get("strict_reason")
    if sr:
        reasons.append(str(sr))
    outlook = analyst.get("outlook") if isinstance(analyst.get("outlook"), dict) else {}
    wr = outlook.get("wait_reasoning")
    if isinstance(wr, (list, tuple)):
        reasons.extend([str(x) for x in wr if x])
    elif wr:
        reasons.append(str(wr))
    wf = next_opp.get("waiting_for")
    if isinstance(wf, (list, tuple)):
        reasons.extend([str(x) for x in wf if x])
    elif wf:
        reasons.append(str(wf))
    _seen, _dedup = set(), []
    for r in reasons:
        if r and r not in _seen:
            _seen.add(r)
            _dedup.append(r)
    out["why_waiting"] = _dedup[:6]

    # Extension warning — reuse the existing risk-zone read (+ the analyst's VWAP
    # extension in ATRs when present). DISPLAY only, never gates.
    bias_word = ("Bullish" if favored == "Long"
                 else "Bearish" if favored == "Short" else "Neutral")
    try:
        rz_label, rz_detail, rz_warn = get_risk_zone(
            bias_word, result.get("current_price"), ns, nd)
    except Exception:
        rz_label, rz_detail, rz_warn = None, None, False
    phase = analyst.get("market_phase") if isinstance(analyst.get("market_phase"), dict) else {}
    ext_atr = phase.get("vwap_extension_atr")
    ext_atr = ext_atr if isinstance(ext_atr, (int, float)) else None
    out["extension_warning"] = {
        "active":  bool(rz_warn) or (ext_atr is not None and ext_atr >= 2.0),
        "label":   rz_label,
        "detail":  rz_detail,
        "vwap_extension_atr": ext_atr,
    }

    # State + summary.
    if is_actionable(verdict):
        out["state"]     = "engine_entering"
        out["available"] = True
        out["summary"]   = ("Engine has reached an entry (%s) — stalk complete; the strict "
                            "engine is acting on it." % (favored or "—"))
    elif favored and (out["ideal_entry_zone"] is not None or out["pullback_area"] is not None):
        out["state"]     = "stalking"
        out["watching"]  = True
        out["available"] = True
        out["summary"]   = ("Stalking a potential %s — waiting for price to pull back into "
                            "the entry zone and the gate to confirm before any trade." % favored)
    else:
        out["state"]     = "idle"
        out["available"] = True
        out["summary"]   = "No setup forming yet — no directional edge to stalk."
    return out


# ===========================================================================
# Advisory overlay 2/2 — ACTIVE TRADE THINKING (in-trade reasoning)
# ===========================================================================
# DISPLAY/ADVISORY-ONLY. Once a position is open it continuously re-grades the original
# thesis and recommends an action — but it NEVER exits, sizes, scores the gate, dedupes
# or sends an order. It REUSES the proven read-only compute_manual_trade_management
# engine on a COPY of the live position (so ACTIVE_TRADES_BY_INST is never mutated) and
# CONSUMES the current analysis `result`. NO auto-exit (a future, separate step).
# ---------------------------------------------------------------------------

ATT_PEAK_BY_KEY = {}                 # display-only running R extremes per open position
ATT_PEAK_LOCK   = threading.Lock()


def _att_trade_key(inst, trade):
    return "%s|%s" % (inst, (trade or {}).get("opened_at") or "")


def _active_trade_thinking_neutral(reason="Active Trade Thinking disabled.",
                                   instrument=None, enabled=False):
    """Stable neutral schema for the Active Trade Thinking overlay. Never raises."""
    return {
        "enabled":            bool(enabled),
        "available":          False,
        "instrument":         instrument,
        "generated_at":       now_utc().isoformat(),
        "state":              "none",
        "has_trade":          False,
        "summary":            reason,
        "direction":          None,
        "thesis_status":      "NONE",
        "thesis_strength":    {"label": "—", "score": 0},
        "trade_health_score": None,
        "momentum":           "neutral",
        "runner_potential":   "low",
        "exit_warning":       {"active": False, "reason": None},
        "scratch_warning":    {"active": False, "reason": None},
        "recommendation":     "HOLD",
        "recommendation_reason": "",
        "reasons":            [],
        "current_r":          None,
        "mfe_r":              None,
        "mae_r":              None,
        "unrealized_pnl":     None,
        "entry_price":        None,
        "stop_loss":          None,
        "target1":            None,
        "target2":            None,
        "advisory_only":      True,
        "auto_exit":          False,
    }


def compute_active_trade_thinking(result):
    """In-trade 'thinking' overlay — see the section header for the money-path wall.

    Grades thesis strength, a 0-100 trade-health score, momentum (improving / fading),
    runner potential, plus exit / scratch warnings, and maps them to ONE advisory verb:
    HOLD / TAKE PARTIAL / MOVE STOP / WATCH CLOSELY / CONSIDER EXIT. Advisory only — it
    NEVER exits the trade. FAIL-OPEN (its caller wraps this in try/except -> neutral)."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    inst = instrument_of(inst_label) if inst_label else None
    out = _active_trade_thinking_neutral("", inst_label, enabled=True)

    trade = active_trade_for(inst) if inst else None
    if not trade:
        out["state"]     = "no_trade"
        out["available"] = True
        out["summary"]   = ("No open position — nothing to manage. Stalk Mode is watching "
                            "for the next setup.")
        return out

    # Work on a COPY — compute_manual_trade_management writes min_r/max_r back onto its
    # input, and the live ACTIVE_TRADES_BY_INST slot must never be mutated by this
    # display overlay. The trade dict is flat (floats/strings/bools), so a shallow copy
    # is enough. Pass analysis=result so the helper does NOT recompute full_analysis.
    tcopy = dict(trade)
    tcopy.setdefault("symbol", inst_label)
    tcopy.setdefault("mode", result.get("mode") or trade.get("mode") or "SCALP")
    try:
        mtm = compute_manual_trade_management(tcopy, analysis=result)
    except Exception as exc:
        out["has_trade"] = True
        out["state"]     = "unavailable"
        out["summary"]   = "Live management read unavailable (%s)." % exc
        return out

    out["has_trade"]  = True
    out["available"]  = True
    out["direction"]  = mtm.get("direction")
    out["entry_price"] = mtm.get("entry_price")
    out["stop_loss"]   = mtm.get("stop_loss")
    out["target1"]     = mtm.get("target1")
    out["target2"]     = mtm.get("target2")
    thesis = mtm.get("thesis_status") or "VALID"
    out["thesis_status"] = thesis

    if mtm.get("status") != "ok":
        out["state"]   = "monitoring"
        out["summary"] = mtm.get("recommendation_reason") or "Live management read unavailable."
        return out

    out["state"] = "managing"
    cur_r = mtm.get("current_r")
    out["current_r"]      = cur_r
    out["unrealized_pnl"] = mtm.get("unrealized_pnl")

    # Persistent (display-only) running R extremes for the momentum / runner reads.
    key = _att_trade_key(inst, trade)
    peak = trough = None
    with ATT_PEAK_LOCK:
        prev = ATT_PEAK_BY_KEY.get(key) or {}
        peak, trough = prev.get("peak_r"), prev.get("trough_r")
        if isinstance(cur_r, (int, float)):
            peak   = cur_r if peak   is None else max(peak, cur_r)
            trough = cur_r if trough is None else min(trough, cur_r)
        ATT_PEAK_BY_KEY[key] = {"peak_r": peak, "trough_r": trough}
        if len(ATT_PEAK_BY_KEY) > 32:                  # keep the dict small
            for _k in list(ATT_PEAK_BY_KEY.keys())[:-32]:
                ATT_PEAK_BY_KEY.pop(_k, None)
    out["mfe_r"] = round(peak, 2) if isinstance(peak, (int, float)) else None
    out["mae_r"] = round(trough, 2) if isinstance(trough, (int, float)) else None

    # Structure agreement (display read).
    sc = str(result.get("structure_class") or "").lower()
    is_long = (out["direction"] == "Long")
    struct_with    = ("bullish" in sc and is_long) or ("bearish" in sc and not is_long)
    struct_against = ("bearish" in sc and is_long) or ("bullish" in sc and not is_long)

    # Momentum: improving when holding near the running R peak, fading when it has given
    # back from the peak (or structure has turned while the thesis is slipping).
    momentum = "neutral"
    if isinstance(cur_r, (int, float)) and isinstance(peak, (int, float)):
        if cur_r >= peak - 0.10 and cur_r > 0:
            momentum = "improving"
        elif cur_r <= peak - 0.30:
            momentum = "fading"
    if momentum == "neutral" and struct_with and isinstance(cur_r, (int, float)) and cur_r > 0:
        momentum = "improving"
    if struct_against and thesis in ("WEAKENING", "INVALID"):
        momentum = "fading"
    out["momentum"] = momentum

    # Trade-health score (0-100) — a composite of thesis, open R, momentum & structure.
    score = 50
    if thesis == "VALID":
        score += 20
    elif thesis == "WEAKENING":
        score -= 15
    elif thesis == "INVALID":
        score -= 40
    if isinstance(cur_r, (int, float)):
        score += max(-20, min(20, int(round(cur_r * 10))))
    if momentum == "improving":
        score += 10
    elif momentum == "fading":
        score -= 10
    if struct_with:
        score += 5
    if struct_against:
        score -= 10
    if mtm.get("stop_breached"):
        score = min(score, 5)
    score = max(0, min(100, score))
    out["trade_health_score"] = score

    # Thesis strength label.
    if thesis == "INVALID" or mtm.get("stop_breached"):
        ts_label = "BROKEN"
    elif score >= 75:
        ts_label = "STRONG"
    elif score >= 50:
        ts_label = "MODERATE"
    else:
        ts_label = "WEAK"
    out["thesis_strength"] = {"label": ts_label, "score": score}

    # Runner potential.
    runner = "low"
    if isinstance(cur_r, (int, float)):
        if cur_r >= 1.5 and momentum == "improving" and thesis == "VALID" and struct_with:
            runner = "increasing"
        elif cur_r >= 0.8 and thesis == "VALID":
            runner = "steady"
    out["runner_potential"] = runner

    # Exit / scratch warnings (advisory only — never auto-acted).
    exit_active = bool(mtm.get("stop_breached") or thesis == "INVALID")
    out["exit_warning"] = {
        "active": exit_active,
        "reason": (mtm.get("recommendation_reason") if exit_active else None),
    }
    scratch_active, scratch_reason = False, None
    if not exit_active and isinstance(cur_r, (int, float)):
        if thesis == "WEAKENING" and momentum == "fading" and cur_r <= 0.3:
            scratch_active = True
            scratch_reason = ("Thesis is weakening and momentum is fading while the trade is "
                              "near entry — consider scratching for a small result rather than "
                              "risking the full stop.")
        elif struct_against and cur_r <= 0.0:
            scratch_active = True
            scratch_reason = ("Structure has turned against you and the trade is offside, but "
                              "the stop is still intact — consider scratching.")
    out["scratch_warning"] = {"active": scratch_active, "reason": scratch_reason}

    # Recommendation — map the proven manual-management action onto the advisory verbs.
    action = str(mtm.get("action") or mtm.get("recommendation") or "HOLD").upper()
    rec = {
        "EXIT":            "CONSIDER EXIT",
        "REDUCE":          "TAKE PARTIAL",
        "TAKE PARTIAL":    "TAKE PARTIAL",
        "MOVE STOP TO BE": "MOVE STOP",
        "MOVE STOP":       "MOVE STOP",
        "HOLD":            "HOLD",
        "MONITOR":         "WATCH CLOSELY",
    }.get(action, "HOLD")
    if rec == "HOLD" and (thesis == "WEAKENING" or scratch_active or momentum == "fading"):
        rec = "WATCH CLOSELY"
    out["recommendation"]        = rec
    out["recommendation_reason"] = mtm.get("recommendation_reason") or ""

    reasons = list(mtm.get("warnings") or [])
    if scratch_active and scratch_reason:
        reasons.append(scratch_reason)
    out["reasons"] = reasons[:8]

    _rtxt = ("%.2fR" % cur_r) if isinstance(cur_r, (int, float)) else "—"
    out["summary"] = ("%s %s — thesis %s (health %d/100), momentum %s, at %s. Advisory: %s."
                      % (out["direction"] or "—", inst_label or "", str(thesis).title(),
                         score, momentum, _rtxt, rec))
    return out


def compute_scalp_strategy_advisory(result):
    """DISPLAY/ADVISORY-ONLY 'potential trades' analysis across all research scalp
    strategies (see the section header for the money-path wall). Reuses the PURE
    scalp_live_sim detectors + the same read-only live context the paper sim uses, and
    ANALYZES (never executes) each detected setup. FAIL-OPEN; the caller only attaches
    this when the flag is ON, so flag-OFF full_analysis stays byte-identical."""
    inst = None
    try:
        inst = instrument_of(result.get("active_ticker") or "") or None
    except Exception:
        inst = None
    if not SCALP_MAIN_BRAIN_ADVISORY_ENABLED:
        return _scalp_strategy_advisory_neutral("Strategy advisory disabled.", inst, enabled=False)
    try:
        lctx = _scalp_sim_live_ctx(result)
        if not lctx:
            return _scalp_strategy_advisory_neutral(
                "No live context yet (waiting on price / ATR).", inst, enabled=True)
        import scalp_live_sim as sls
        raw = sls.build_candidates(lctx) or []
        regime = lctx.get("regime")
        analyzed = []
        for cand in raw:
            try:
                analyzed.append(_analyze_advisory_candidate(cand, result, regime))
            except Exception:
                continue
        # Rank: strict-aligned first, then quality, clean fidelity, R:R, key.
        analyzed.sort(key=lambda c: (
            0 if c.get("strict_alignment") else 1,
            -(c.get("quality_score") or 0),
            0 if c.get("fidelity") == "clean" else 1,
            -(c.get("rr") or 0),
            c.get("strategy_key") or "",
        ))
        if analyzed:
            top = analyzed[0]
            summary = "%d potential setup%s analyzed — top: %s (%s, %s)" % (
                len(analyzed), "" if len(analyzed) == 1 else "s",
                top.get("name"), top.get("direction"), top.get("quality_label"))
        else:
            summary = "No strategy setups detected on the current tape."
        # Full 16-strategy vote roster + consensus (DISPLAY-ONLY). Pass/fail/direction
        # come from the REAL detectors (single source of truth); confidence reuses the
        # same confluence scorer as the ranked candidates so the numbers agree.
        votes = _advisory_strategy_votes(lctx, analyzed, result, regime)
        consensus = _advisory_consensus(votes)
        return {
            "enabled":      True,
            "available":    True,
            "instrument":   inst,
            "generated_at": now_utc().isoformat(),
            "summary":      summary,
            "candidates":   analyzed,
            "votes":        votes,
            "consensus":    consensus,
        }
    except Exception as exc:
        return _scalp_strategy_advisory_neutral(
            "Strategy advisory unavailable (%s)." % exc, inst, enabled=True)


def _mb_potential_trades_summary(adv):
    """Compact Main-Brain view of the scalp-strategy advisory block (display-only).
    Never raises — the compute_main_brain caller also guards."""
    cands = (adv.get("candidates") or []) if isinstance(adv, dict) else []
    top = []
    for c in cands[:3]:
        top.append({
            "name":           c.get("name"),
            "direction":      c.get("direction"),
            "quality_label":  c.get("quality_label"),
            "quality_score":  c.get("quality_score"),
            "recommendation": c.get("recommendation"),
        })
    return {
        "available": bool(adv.get("available")) if isinstance(adv, dict) else False,
        "count":     len(cands),
        "summary":   adv.get("summary") if isinstance(adv, dict) else None,
        "top":       top,
    }


def _scalp_sim_open_insert(sim_key, setup_anchor, strategy_key, inst, direction,
                           cand, session, regime, edge):
    """Idempotent INSERT of an OPEN paper trade. Skips if (a) an identical sim_key
    already exists (duplicate webhook), or (b) a paper trade for this strategy /
    instrument / direction is already open/resolving (one paper position at a
    time). FAIL-OPEN (returns False on any error). INSERT/SELECT ONLY — no DDL, no
    money path."""
    if not SCALP_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        ctx_json = psycopg2.extras.Json({
            "entry_reason": cand.get("entry_reason"), "risk": cand.get("risk"),
            "fidelity": cand.get("fidelity"), "session": session,
            "market_regime": regime, "edge_score": edge})
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM scalp_strategy_sim_trades "
                "WHERE strategy_key=%s AND symbol=%s AND direction=%s "
                "AND status IN ('open','resolving') LIMIT 1",
                (strategy_key, inst, direction))
            if cur.fetchone():
                return False
            cur.execute(
                "INSERT INTO scalp_strategy_sim_trades "
                "(sim_key, strategy_key, symbol, direction, status, entry, stop, target, rr, "
                " session, market_regime, edge_score, fidelity, setup_anchor, opened_at, "
                " entry_epoch, context) "
                "VALUES (%s,%s,%s,%s,'open',%s,%s,%s,%s,%s,%s,%s,%s,%s, now(), %s, %s) "
                "ON CONFLICT (sim_key) DO NOTHING",
                (sim_key, strategy_key, inst, direction, cand["entry"], cand["stop"],
                 cand["target"], cand["rr"], session, regime, edge,
                 (json.dumps(cand["fidelity"]) if isinstance(cand.get("fidelity"), dict) else cand.get("fidelity")),
                 setup_anchor, now_utc().timestamp(), ctx_json))
            inserted = (cur.rowcount == 1)
        conn.commit()
        return inserted
    except Exception as exc:
        logger.warning("scalp live-sim open insert failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _maybe_observe_scalp_live_sim(result, source="webhook"):
    """DISPLAY / RESEARCH-ONLY paper-trade observer. Default OFF. Runs ONLY from
    the webhook analysis path (never the read-only /status or dashboard polls).
    Detects testable research-library scalp setups in the LIVE context and
    idempotently INSERTs an OPEN paper trade. FAIL-OPEN and side-effect-isolated:
    never mutates `result`, never touches the gate / verdict / trade_plan /
    edge_score / money path. Returns the number of paper trades opened (for tests)."""
    if not SCALP_LIVE_SIM_ENABLED or source != "webhook" or not SCALP_SIM_DB_READY:
        return 0
    # Never open paper trades while the futures session is closed.
    try:
        if not market_session_status().get("open", True):
            return 0
    except Exception:
        pass
    try:
        import scalp_live_sim as sls
    except Exception:
        return 0
    l = _scalp_sim_live_ctx(result)
    if not l or not l.get("inst"):
        return 0
    try:
        candidates = sls.build_candidates(l)
    except Exception:
        return 0
    if not candidates:
        return 0
    inst    = l["inst"]
    atr     = l.get("atr") or 0.0
    session = l.get("session")
    regime  = l.get("regime")
    edge    = result.get("edge_score")
    now_mono = time.monotonic()
    et_day   = now_utc().astimezone(ET_TZ).strftime("%Y%m%d")
    bucket   = int(now_utc().timestamp() // 300)   # 5-min idempotency bucket
    opened = 0
    for cand in candidates:
        key = cand["strategy_key"]
        direction = cand["direction"]
        ckey = (key, inst, direction)
        # in-memory cooldown (soft anti-spam; the DB guards are authoritative)
        with _SCALP_SIM_COOLDOWN_LOCK:
            last = _SCALP_SIM_COOLDOWN.get(ckey)
            if last is not None and (now_mono - last) < SCALP_SIM_OPEN_COOLDOWN_SECS:
                continue
        price_bucket = (int(round(cand["entry"] / (0.5 * atr))) if atr
                        else int(round(cand["entry"])))
        setup_anchor = "%s:%d:%d" % (et_day, bucket, price_bucket)
        sim_key = "%s|%s|%s|%s" % (key, inst, direction, setup_anchor)
        if _scalp_sim_open_insert(sim_key, setup_anchor, key, inst, direction,
                                  cand, session, regime, edge):
            opened += 1
            with _SCALP_SIM_COOLDOWN_LOCK:
                _SCALP_SIM_COOLDOWN[ckey] = now_mono
    if opened:
        logger.info("scalp live-sim: opened %d paper trade(s) on %s", opened, inst)
    return opened


def _scalp_sim_outcome(row, bar):
    """Pure stop-first / then target resolver for ONE open paper trade against the
    latest bar. Returns (result_label, exit_price, r_multiple) or None (no level
    hit). Stop is checked before target (worst-case fill), exactly like the live
    managed watcher's idempotent level checks."""
    high, low = bar.get("high"), bar.get("low")
    entry, stop, target = row.get("entry"), row.get("stop"), row.get("target")
    if None in (high, low, entry, stop, target):
        return None
    risk = abs(entry - stop)
    if risk <= 0:
        return None
    if row.get("direction") == "Long":
        if low <= stop:
            return ("loss", stop, round((stop - entry) / risk, 4))
        if high >= target:
            return ("win", target, round((target - entry) / risk, 4))
    else:
        # SHORT: stop is ABOVE entry (loss) and target BELOW entry (win), so R is
        # measured as (entry - exit)/risk to keep losses negative and wins positive.
        if high >= stop:
            return ("loss", stop, round((entry - stop) / risk, 4))
        if low <= target:
            return ("win", target, round((entry - target) / risk, 4))
    return None


def _scalp_sim_close(row_id, result_label, exit_price, r_multiple):
    """Atomically resolve one open paper trade. The conditional `WHERE status IN
    ('open','resolving')` IS the cross-instance status claim — only the first
    writer (dev OR prod) closes it; a concurrent watcher's UPDATE matches 0 rows
    and no-ops. Writes ONLY to scalp_strategy_sim_trades. FAIL-OPEN."""
    if not SCALP_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE scalp_strategy_sim_trades "
                "SET status='closed', result=%s, exit_price=%s, r_multiple=%s, closed_at=now() "
                "WHERE id=%s AND status IN ('open','resolving')",
                (result_label, exit_price, r_multiple, row_id))
            claimed = (cur.rowcount == 1)
        conn.commit()
        return claimed
    except Exception as exc:
        logger.warning("scalp live-sim close failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _watch_scalp_sim_trades():
    """Resolve OPEN paper trades against the latest 1-minute bar (one fetch per
    instrument per cycle) — stop-first then target, ±R only, with the SAME-BAR
    guard (skip a bar that opened at/before entry so a fresh trade can't "instantly
    fill" off its own bar). A stranded trade past SCALP_SIM_MAX_HOLD_HOURS is
    resolved at the latest close as 'expired'. Writes ONLY to
    scalp_strategy_sim_trades — never MANAGED_TRADES, strategy_trades,
    _record_strategy_trade, or the money path. FAIL-OPEN."""
    if not SCALP_SIM_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, symbol, direction, entry, stop, target, rr, entry_epoch, opened_at "
                "FROM scalp_strategy_sim_trades WHERE status IN ('open','resolving') "
                "ORDER BY id ASC LIMIT 500")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "symbol": r[1], "direction": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "target": float(r[5]) if r[5] is not None else None,
                    "rr": float(r[6]) if r[6] is not None else 1.0,
                    "entry_epoch": float(r[7]) if r[7] is not None else None,
                    "opened_at": r[8]})
    except Exception as exc:
        logger.warning("scalp live-sim watcher read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not open_rows:
        return
    bars = {}
    for inst in {r["symbol"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    for row in open_rows:
        bar = bars.get(row["symbol"])
        if not bar:
            continue
        bar_start, entry_epoch = bar.get("start"), row.get("entry_epoch")
        if bar_start is not None and entry_epoch is not None and bar_start <= entry_epoch:
            continue                       # same-bar guard (no look-ahead self-fill)
        outcome = _scalp_sim_outcome(row, bar)
        if outcome is None:
            # max-hold expiry — resolve a stranded paper trade at the latest close.
            opened_at, cl = row.get("opened_at"), bar.get("close")
            if opened_at is not None and cl is not None and row.get("stop") is not None:
                try:
                    oa = opened_at if opened_at.tzinfo else opened_at.replace(tzinfo=timezone.utc)
                    aged = (now_utc() - oa).total_seconds() > SCALP_SIM_MAX_HOLD_HOURS * 3600
                except Exception:
                    aged = False
                risk = abs(row["entry"] - row["stop"])
                if aged and risk > 0:
                    r = ((cl - row["entry"]) / risk if row["direction"] == "Long"
                         else (row["entry"] - cl) / risk)
                    outcome = ("expired", round(cl, 4), round(r, 4))
        if outcome is None:
            continue
        _scalp_sim_close(row["id"], outcome[0], outcome[1], outcome[2])


def _scalp_sim_watch_loop():
    """Parallel PAPER watcher on its own timer. Gated to the LIVE instance
    (DISCORD_LIVE_ENABLED) + flag ON + DB ready, single-flight via
    SCALP_SIM_WATCH_LOCK. FAIL-OPEN — any error just skips this cycle. Never
    touches the money path."""
    try:
        if SCALP_LIVE_SIM_ENABLED and DISCORD_LIVE_ENABLED and SCALP_SIM_DB_READY:
            if SCALP_SIM_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_scalp_sim_trades()
                finally:
                    SCALP_SIM_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("scalp live-sim watch loop error: %s", exc)
    finally:
        threading.Timer(SCALP_SIM_WATCH_INTERVAL, _scalp_sim_watch_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# MICRO SCALP MODE — liquidity-moment hunter (DISPLAY + GHOST TRADING ONLY)
# ════════════════════════════════════════════════════════════════════════════
# Separate, ISOLATED overlay that hunts short-term liquidity "moments" (sweep →
# trap → absorption → micro trigger) instead of full strategy confirmations. The
# detection engine is the PURE module micro_scalp.py (imports nothing from here).
#
# HARD WALLS (identical to the proven scalp_live_sim pattern):
#   * NEVER sends a broker order — verdict TAKE only opens a GHOST row in its own
#     table (micro_scalp_ghost_trades) so the operator can see what it WOULD do.
#   * Never touches the gate / verdict / trade_plan / edge_score / money path.
#   * App-side INSERT/SELECT ONLY — the table is created out-of-band (DB tool in
#     dev, Publish schema-diff in prod); a missing table just disables ghosts.
#   * Toggle OFF (the default) == byte-identical: the main_brain key is never
#     attached, the recorder / observer / watcher all early-return.
# The toggle is IN-MEMORY (resets OFF on restart — fail-safe) with an optional
# MICRO_SCALP_ENABLED env override for a durable prod default.
MICRO_SCALP_MODE       = os.environ.get("MICRO_SCALP_ENABLED", "0").strip().lower() \
                             in ("1", "true", "yes", "on")
MICRO_SCALP_LOCK       = threading.Lock()
MICRO_GHOST_DB_READY   = False
MICRO_GHOST_WATCH_LOCK = threading.Lock()   # single-flight watcher cycles
# ── Profitability Engine — Phase 1 ghost observation ledger ─────────────────
# RESEARCH / DISPLAY-ONLY. Records every READY setup as a ghost observation
# BEFORE the execution gate so research captures setups even when live trading
# is disabled/blocked. Never gates, sizes, or sends orders.
# Table: ghost_observations (created via DB tool / publish schema-diff; no DDL).
GHOST_OBS_DB_READY       = False
EL_DB_READY              = False   # set by _check_edge_ledger_db_ready() — Phase 8A
GRE_DB_READY             = False   # set by _check_gre_db_ready() — Phase 2 Ghost Research Engine
DC_DB_READY              = False   # set by _check_dc_db_ready() — Phase 3 Canonical Decision Contract (shadow)
GATE_AUDIT_DB_READY      = False   # set by _check_gate_audit_db_ready() — Phase 8C Gate Effectiveness Audit
GHOST_OBS_WATCH_LOCK     = threading.Lock()   # single-flight watcher cycle
GHOST_OBS_COOLDOWN_SECS  = max(60, int(os.environ.get("GHOST_OBS_COOLDOWN_SECS", "300")))
_GHOST_OBS_COOLDOWN      = {}                  # (inst, direction, strategy_short) → monotonic ts
_GHOST_OBS_COOLDOWN_LOCK = threading.Lock()
MICRO_GHOST_WATCH_INTERVAL     = max(10, int(os.environ.get("MICRO_GHOST_WATCH_INTERVAL", 30)))
MICRO_GHOST_MAX_HOLD_MIN       = max(10, int(os.environ.get("MICRO_GHOST_MAX_HOLD_MIN", 120)))
MICRO_GHOST_OPEN_COOLDOWN_SECS = max(60, int(os.environ.get("MICRO_GHOST_COOLDOWN_SECS", 600)))
_MICRO_GHOST_COOLDOWN      = {}             # (inst, direction) -> monotonic ts
_MICRO_GHOST_COOLDOWN_LOCK = threading.Lock()

# ── MICRO SCALP LIVE ARM (MONEY PATH; separate second toggle, default OFF) ───
# Arming LIVE makes a micro TAKE fire a REAL order through the SAME audited
# execute_trade_gateway (source="micro_scalp") the main bot uses — every shared
# safety layer applies (live-instance gate, emergency stop, daily caps, risk
# cap, prop guard, training gate, fail-closed send). IN-MEMORY and RESET OFF on
# every restart/republish (fail-safe toward NOT trading, same convention as the
# per-instrument AUTO arm). Arming requires the mode toggle ON; toggling the
# mode OFF force-disarms. Fire-once key = the ghost INSERT (idempotent sim_key
# + per-(inst,dir) cooldown): a skipped/blocked gateway call never retries.
MICRO_LIVE_ARMED     = False
MICRO_LIVE_CONTRACTS = max(1, int(os.environ.get("MICRO_LIVE_CONTRACTS", 1)))
MICRO_LIVE_TARGET    = os.environ.get("MICRO_LIVE_TARGET", "tp1").strip().lower()
if MICRO_LIVE_TARGET not in ("tp1", "tp2"):
    MICRO_LIVE_TARGET = "tp1"
# Default: NEVER stack a micro live entry on an already-tracked open position.
MICRO_LIVE_ALLOW_STACK = os.environ.get("MICRO_LIVE_ALLOW_STACK", "0").strip().lower() \
                             in ("1", "true", "yes", "on")


def _micro_live_armed():
    """True only while BOTH the mode toggle and the LIVE arm are ON."""
    with MICRO_SCALP_LOCK:
        return bool(MICRO_LIVE_ARMED and MICRO_SCALP_MODE)


def _micro_live_disarm(reason=""):
    """Force-disarm LIVE (fail-safe). Used by the gateway wrapper on an
    ambiguous broker response so micro can't keep firing into an uncertain
    broker state — mirrors the AUTO_TRADE disarm convention."""
    global MICRO_LIVE_ARMED
    with MICRO_SCALP_LOCK:
        MICRO_LIVE_ARMED = False
    logger.warning("MICRO SCALP LIVE disarmed%s",
                   (" — " + reason) if reason else "")

