# ── Phase 8B: Research Events Ring Buffer (DISPLAY-ONLY) ─────────────────────
# In-memory ring buffer powering the Operations Readiness panel.
# NEVER touches gate, scoring, sizing, learning, or execution.
# All writes are fail-open (bare try/except).

_RESEARCH_EVENTS: deque = deque(maxlen=500)       # appendleft → newest-first
_RESEARCH_EVENTS_LOCK = threading.Lock()
_RESEARCH_BOOT_TS: str = datetime.utcnow().isoformat() + "Z"
_RESEARCH_FIRST_OBS_KEY = None     # first ghost obs since last restart (str | None)
_RESEARCH_ERROR_COUNT: int = 0                    # count of logged research-path errors


def _re_event(event_type,       # str
              *,
              inst=None,        # str | None
              strategy=None,    # str | None
              verdict=None,     # str | None
              obs_key=None,     # str | None
              net_r=None,       # float | None
              extra=None):      # dict | None
    """Append a research event to the Operations Readiness ring buffer.

    FAIL-OPEN — never raises, never blocks, never touches any money path.
    Called from _ghost_observe_setup, _ghost_obs_watcher_cycle, and EL helpers.
    """
    global _RESEARCH_FIRST_OBS_KEY
    try:
        ev = {
            "ts":         datetime.utcnow().isoformat() + "Z",
            "event_type": event_type,
            "instrument": inst,
            "strategy":   (strategy[:40] if strategy else None),
            "verdict":    verdict,
            "obs_key":    (obs_key[:64]  if obs_key  else None),
            "net_r":      (round(float(net_r), 4) if net_r is not None else None),
            "extra":      extra or {},
        }
        with _RESEARCH_EVENTS_LOCK:
            _RESEARCH_EVENTS.appendleft(ev)
            if event_type == "ghost_created" and obs_key and _RESEARCH_FIRST_OBS_KEY is None:
                _RESEARCH_FIRST_OBS_KEY = obs_key
    except Exception:
        pass


# ── Phase 8A: Edge Ledger helpers (FAIL-OPEN, DISPLAY/ACCOUNTING ONLY) ───────
# These helpers never touch the gate, scoring, sizing, learning, or execution.
# EL_DB_READY=False makes them byte-identical no-ops (fail-safe).

def _el_create_entry(obs_key, result, inst, direction, strategy_key,
                     entry, stop_px, target1, target2, risk_pts,
                     cost_r_est, sess_name, edge_score, now_utc_ts,
                     mtf_snap=None):
    """INSERT an edge_ledger row with frozen signal terms. FAIL-OPEN.

    Called from _ghost_observe_setup immediately after the ghost_obs INSERT
    succeeds — same dedup key (obs_key) ensures 1:1 correspondence.
    Original signal columns are written ONCE and are protected by the
    el_immutability_guard trigger in the DB schema.
    """
    if not EL_DB_READY or not LEARNING_DB_ENABLED:
        return
    try:
        import edge_ledger as _el   # noqa: PLC0415
        terms = _el.extract_frozen_signal_terms(result, inst, INSTRUMENT_SPECS)
        if terms is None:
            return
        edge_id   = _el.build_edge_id(inst, direction, strategy_key, obs_key)
        partition = _el.assign_sample_partition("databento_scan")
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO edge_ledger
                           (edge_id, ghost_obs_key, source, instrument,
                            mode, session, direction,
                            strategy_key, strategy_version, sample_partition,
                            signal_timestamp,
                            original_entry, original_stop, original_tp1, original_tp2,
                            original_targets, original_risk_points, original_risk_dollars,
                            original_rr,
                            edge_score, long_score, short_score, decision_margin,
                            grade, readiness, left_brain_thesis, thesis_alignment,
                            confirmations, blockers, opposing_structure, risk_state,
                            market_context,
                            signal_cost_r, cost_model_version,
                            signal_outcome_status,
                            four_h_trend_at_signal, fifteen_m_trend_at_signal,
                            trend_alignment_at_signal)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                               %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                               %s,%s,%s,%s,%s,%s,%s,%s)
                       ON CONFLICT (edge_id) DO NOTHING""",
                    (
                        edge_id, obs_key, "live_shadow", inst,
                        TRADING_MODE, sess_name, direction,
                        strategy_key, STRATEGY_VERSION, partition,
                        now_utc_ts,
                        terms["original_entry"],   terms["original_stop"],
                        terms["original_tp1"],     terms.get("original_tp2"),
                        json.dumps(terms["original_targets"]),
                        terms["original_risk_points"],
                        terms.get("original_risk_dollars"),
                        terms.get("original_rr"),
                        terms.get("edge_score"),
                        terms.get("long_score"),   terms.get("short_score"),
                        terms.get("decision_margin"),
                        terms.get("grade"),        terms.get("readiness"),
                        terms.get("left_brain_thesis"),
                        terms.get("thesis_alignment"),
                        json.dumps(terms.get("confirmations") or []),
                        json.dumps(terms.get("blockers") or []),
                        terms.get("opposing_structure"),
                        terms.get("risk_state"),
                        json.dumps(terms.get("market_context") or {}),
                        (round(cost_r_est, 4) if cost_r_est is not None else None),
                        _el.COST_MODEL_VERSION,
                        "open",
                        (mtf_snap or {}).get("four_h_trend_at_signal"),
                        (mtf_snap or {}).get("fifteen_m_trend_at_signal"),
                        (mtf_snap or {}).get("trend_alignment_at_signal"),
                    ),
                )
                conn.commit()
        finally:
            try:
                conn.close()
            except Exception:
                pass
        logger.debug(
            "edge_ledger entry created: %s %s sk=%s edge_id=%s",
            inst, direction, strategy_key[:40], edge_id[:40],
        )
        # ── Phase 8B: emit research event (DISPLAY-ONLY) ────────────────────
        _re_event("el_created", inst=inst, strategy=strategy_key,
                  obs_key=obs_key, extra={"edge_id": edge_id[:40]})
    except Exception as exc:
        logger.debug("_el_create_entry fail-open (%s %s): %s", inst, direction, exc)


def _el_update_signal_outcome_conn(conn, obs_key, status, close_reason,
                                   exit_px, gross_r, net_r, cost_r,
                                   mfe_r, mae_r, now_ts):
    """UPDATE edge_ledger signal outcome columns using an existing DB connection.

    Called from _ghost_obs_watcher_cycle when a ghost observation is closed or
    expired.  Uses original frozen terms already on the row — no mutation of
    the immutable signal columns.  FAIL-OPEN.
    """
    if not EL_DB_READY:
        return
    try:
        edge_id = f"el|{obs_key}"
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE edge_ledger
                       SET signal_outcome_status  = %s,
                           signal_first_level_hit = %s,
                           signal_gross_r         = %s,
                           signal_net_r           = %s,
                           signal_cost_r          = COALESCE(signal_cost_r, %s),
                           signal_mfe_r           = %s,
                           signal_mae_r           = %s,
                           signal_resolved_at     = %s,
                           data_complete          = (
                               %s IS NOT NULL
                               AND COALESCE(signal_cost_r, %s) IS NOT NULL
                           ),
                           updated_at             = NOW()
                   WHERE edge_id = %s
                     AND signal_outcome_status = 'open'""",
                (
                    status, close_reason,
                    (round(gross_r, 4) if gross_r is not None else None),
                    (round(net_r,   4) if net_r   is not None else None),
                    (round(cost_r,  4) if cost_r  is not None else None),
                    (round(mfe_r,   4) if mfe_r   is not None else None),
                    (round(mae_r,   4) if mae_r   is not None else None),
                    now_ts,
                    net_r,   # first reference for data_complete boolean
                    (round(cost_r, 4) if cost_r is not None else None),  # second for COALESCE
                    edge_id,
                ),
            )
    except Exception as exc:
        logger.debug("_el_update_signal_outcome_conn fail-open (obs=%s): %s", obs_key, exc)


def _el_try_link_to_journal(iid, instrument, direction):
    """Link the most recent open edge_ledger row to native_journal. FAIL-OPEN.

    Called from _nj_create_from_snapshot after a confirmed send.
    Matches by instrument + direction + signal_timestamp within the last
    10 minutes so ghost_obs and NJ entries for the same setup are joined.
    Also promotes sample_partition from SHADOW → LIVE (a trade actually fired).
    """
    if not EL_DB_READY or not iid:
        return
    try:
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                # Use a CTE to select the target row before updating (ORDER BY + LIMIT)
                cur.execute(
                    """WITH target AS (
                           SELECT edge_id FROM edge_ledger
                           WHERE instrument = %s
                             AND direction  = %s
                             AND internal_trade_id IS NULL
                             AND signal_timestamp > NOW() - INTERVAL '10 minutes'
                           ORDER BY signal_timestamp DESC
                           LIMIT 1
                       )
                       UPDATE edge_ledger
                           SET internal_trade_id = %s,
                               sample_partition  = CASE
                                   WHEN sample_partition = 'SHADOW' THEN 'LIVE'
                                   ELSE sample_partition
                               END,
                               updated_at = NOW()
                       WHERE edge_id = (SELECT edge_id FROM target)""",
                    (instrument, direction, str(iid)),
                )
                conn.commit()
        finally:
            try:
                conn.close()
            except Exception:
                pass
        logger.debug(
            "edge_ledger linked to journal: iid=%.8s %s %s",
            str(iid), instrument, direction,
        )
        # ── Phase 8B: emit research event (DISPLAY-ONLY) ────────────────────
        _re_event("journal_linked", inst=instrument,
                  extra={"iid": str(iid)[:16], "direction": direction})
    except Exception as exc:
        logger.debug(
            "_el_try_link_to_journal fail-open (%.8s %s %s): %s",
            str(iid), instrument, direction, exc,
        )


def _el_update_managed_outcome(internal_trade_id, outcome_dict):
    """UPDATE edge_ledger managed outcome from native_journal close. FAIL-OPEN.

    Called from _nj_set_outcome after the NJ row is committed to CLOSED.
    Sets managed_* columns + triggers comparison computation (SQL-side).
    Never overwrites original signal columns (enforced by DB trigger).
    """
    if not EL_DB_READY or not internal_trade_id:
        return
    try:
        actual_exit = outcome_dict.get("actual_exit")
        net_pnl     = outcome_dict.get("net_pnl")
        realized_r  = outcome_dict.get("realized_r")
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """UPDATE edge_ledger
                           SET managed_outcome_status = 'CLOSED',
                               actual_exit     = %s,
                               managed_net_pnl = %s,
                               managed_net_r   = %s,
                               managed_resolved_at = NOW(),
                               updated_at = NOW()
                       WHERE internal_trade_id = %s
                         AND managed_outcome_status IS DISTINCT FROM 'CLOSED'""",
                    (
                        (float(actual_exit)    if actual_exit is not None else None),
                        (round(float(net_pnl), 2)    if net_pnl is not None else None),
                        (round(float(realized_r), 4) if realized_r is not None else None),
                        str(internal_trade_id),
                    ),
                )
                # Compute comparison in-DB when both sides are available
                cur.execute(
                    """UPDATE edge_ledger
                           SET signal_vs_managed_delta_r = managed_net_r - signal_net_r,
                               comparison_complete = (signal_net_r IS NOT NULL
                                                      AND managed_net_r IS NOT NULL),
                               comparison_reason = CASE
                                   WHEN signal_net_r IS NULL OR managed_net_r IS NULL
                                       THEN 'COMPARISON_UNAVAILABLE'
                                   WHEN ABS(managed_net_r - signal_net_r) <= 0.05
                                       THEN 'MANAGEMENT_NEUTRAL'
                                   WHEN managed_net_r > signal_net_r
                                       THEN 'MANAGEMENT_HELPED'
                                   ELSE 'MANAGEMENT_HURT'
                               END,
                               management_helped = CASE
                                   WHEN signal_net_r IS NULL OR managed_net_r IS NULL
                                       THEN NULL
                                   WHEN ABS(managed_net_r - signal_net_r) <= 0.05
                                       THEN NULL
                                   WHEN managed_net_r > signal_net_r THEN TRUE
                                   ELSE FALSE
                               END,
                               updated_at = NOW()
                       WHERE internal_trade_id = %s
                         AND managed_net_r IS NOT NULL""",
                    (str(internal_trade_id),),
                )
                conn.commit()
        finally:
            try:
                conn.close()
            except Exception:
                pass
        logger.debug(
            "edge_ledger managed outcome: iid=%.8s exit=%s r=%s",
            str(internal_trade_id), actual_exit, realized_r,
        )
        # ── Phase 8B: emit research event (DISPLAY-ONLY) ────────────────────
        _re_event("managed_outcome_updated",
                  net_r=(float(realized_r) if realized_r is not None else None),
                  extra={"iid": str(internal_trade_id)[:16], "actual_exit": actual_exit})
    except Exception as exc:
        logger.debug(
            "_el_update_managed_outcome fail-open (%.8s): %s",
            str(internal_trade_id), exc,
        )


def _get_mtf_snapshot_at_signal(inst):
    """Return frozen MTF trend context at signal time. FAIL-OPEN (Phase 8B.1).
    Returns dict with four_h_trend_at_signal / fifteen_m_trend_at_signal /
    trend_alignment_at_signal — all strings or None.  Never raises.
    """
    try:
        import trend_alignment as _ta   # noqa: PLC0415
        return _ta.get_snapshot_for_signal(inst)
    except Exception:
        return {"four_h_trend_at_signal": None,
                "fifteen_m_trend_at_signal": None,
                "trend_alignment_at_signal": None}


def _mtf_bar_close(instrument, _close_price):
    """Bar-close callback for Phase 8B.1 MTF Trend Alignment. DISPLAY-ONLY.

    DatabentoBrain calls bar-close callbacks as _cb(inst, bars[-1]["close"]),
    so the second argument is the close PRICE (float), not the full bar dict.
    We retrieve the full bar from DATABENTO_BARS_BY_INST (updated before
    callbacks fire) and pass it to trend_alignment.ingest_1m_bar.
    FAIL-OPEN: any exception is silently swallowed.
    """
    try:
        from databento_brain import DATABENTO_BARS_BY_INST  # noqa: PLC0415
        import trend_alignment as _ta                        # noqa: PLC0415
        bars = DATABENTO_BARS_BY_INST.get(instrument)
        if bars:
            _ta.ingest_1m_bar(instrument, bars[-1])
    except Exception:
        pass


def _seed_mtf_from_historical():
    """Background thread: fetch ~48h of 1m OHLCV bars from Databento at boot
    and seed the MTF Trend Alignment engine so trends are available immediately
    after any restart rather than after 2h (15M) / 32h (4H) of cold accumulation.

    DISPLAY-ONLY — never touches gate, scoring, sizing, or execution.
    FAIL-OPEN — any exception is silently logged at debug level.
    Runs once at boot; daemon thread exits when the process does.
    """
    import time as _time  # noqa: PLC0415
    _time.sleep(10)        # let the live connection establish first
    try:
        import databento as _db                              # noqa: PLC0415
        import trend_alignment as _ta                        # noqa: PLC0415
        from databento_brain import DB_DATASET, DB_SYMBOLS  # noqa: PLC0415

        api_key = os.environ.get("DATABENTO_API_KEY", "").strip()
        if not api_key:
            logger.debug("MTFTrend hist-seed: no DATABENTO_API_KEY — skipping")
            return

        hist = _db.Historical(key=api_key)
        now_utc   = datetime.now(timezone.utc)
        # Databento historical API lags ~4 h (not ~5 min as originally assumed).
        # Cap end at now-5h so the query always lands within the available window.
        # The live stream fills the most-recent 5h gap automatically.
        end_utc   = now_utc - timedelta(hours=5)
        start_utc = end_utc  - timedelta(hours=80)   # 80h captures the full weekend (EMA(21) needs 21 closed 15M bars = 315 trading min)
        start_str = start_utc.strftime("%Y-%m-%dT%H:%M")
        end_str   = end_utc.strftime("%Y-%m-%dT%H:%M")

        total_seeded = 0
        for inst, symbol in DB_SYMBOLS.items():
            try:
                logger.info("MTFTrend hist-seed: fetching %s (%s) %s→%s", inst, symbol, start_str, end_str)
                store = hist.timeseries.get_range(
                    dataset=DB_DATASET,
                    symbols=[symbol],
                    schema="ohlcv-1m",
                    stype_in="continuous",
                    start=start_str,
                    end=end_str,
                )
                bars = []
                # to_df() sets ts_event as the DataFrame INDEX (pandas Timestamp).
                # Prices are already floats (not fixed-point int64).
                try:
                    df = store.to_df()
                    logger.info("MTFTrend hist-seed: %s — %d raw rows from Databento", inst, len(df))
                    for ts_idx, row in df.iterrows():
                        try:
                            # ts_idx is the index — a pandas Timestamp nanoseconds
                            import pandas as _pd  # noqa: PLC0415
                            if isinstance(ts_idx, _pd.Timestamp):
                                ts_sec = ts_idx.timestamp()
                            else:
                                ts_sec = float(ts_idx) / 1e9
                            bars.append({
                                "ts":     ts_sec,
                                "open":   float(row.get("open",   0)),
                                "high":   float(row.get("high",   0)),
                                "low":    float(row.get("low",    0)),
                                "close":  float(row.get("close",  0)),
                                "volume": int(row.get("volume", 0)),
                            })
                        except Exception as _row_exc:
                            logger.debug("MTFTrend hist-seed: row parse error — %s", _row_exc)
                            continue
                except Exception as _df_exc:
                    logger.warning("MTFTrend hist-seed: to_df() failed for %s — %s; trying direct iter", inst, _df_exc)
                    # Fallback: direct record iteration (ts_event is nanoseconds int)
                    for rec in store:
                        try:
                            ts_sec = rec.ts_event / 1e9
                            px = lambda v: float(v) / 1e9 if abs(float(v)) > 1_000_000 else float(v)  # noqa: E731
                            bars.append({
                                "ts":     ts_sec,
                                "open":   px(rec.open),
                                "high":   px(rec.high),
                                "low":    px(rec.low),
                                "close":  px(rec.close),
                                "volume": rec.volume,
                            })
                        except Exception:
                            continue

                n = _ta.seed_from_1m_bars(inst, bars)
                total_seeded += n
                state = _ta.get_snapshot_for_signal(inst) if n else {}
                logger.info(
                    "MTFTrend hist-seed: %s — %d 1m bars seeded → 15M:%s 4H:%s",
                    inst, n,
                    state.get("fifteen_m_trend_at_signal", "?"),
                    state.get("four_h_trend_at_signal", "?"),
                )
            except Exception as _inst_exc:
                logger.warning("MTFTrend hist-seed: %s FAILED — %s", inst, _inst_exc)

        logger.info("MTFTrend hist-seed complete — %d total bars seeded", total_seeded)
    except Exception as _outer_exc:
        logger.warning("MTFTrend hist-seed: outer exception — %s", _outer_exc)


def _ghost_observe_setup(result, inst, source="databento_scan"):
    """Create a ghost observation for a READY setup.

    Fires BEFORE the execution gate so every valid READY signal is recorded
    for research, regardless of arm state, execution mode, safety locks, or
    any other live-trading permission check.

    Idempotent: the obs_key dedup (ON CONFLICT DO NOTHING) prevents duplicate
    observations for the same setup within the same session bucket.

    FAIL-OPEN: any exception is logged at debug level only; the caller is
    never affected.  NEVER touches gate, scoring, sizing, arm state, or broker.
    """
    if not GHOST_OBS_DB_READY or not LEARNING_DB_ENABLED:
        return
    try:
        import profitability_engine as _pe  # noqa: PLC0415

        verdict    = result.get("verdict") or ""
        trade_plan = result.get("trade_plan") or {}
        if not is_actionable(verdict):
            return
        direction = ready_direction(verdict)
        if direction not in ("Long", "Short"):
            return

        entry   = trade_plan.get("entry")
        stop_px = trade_plan.get("stop")
        target1 = trade_plan.get("target") or trade_plan.get("tp1")
        target2 = trade_plan.get("target2") or trade_plan.get("tp2")
        if entry is None or stop_px is None or target1 is None:
            return
        try:
            entry   = float(entry)
            stop_px = float(stop_px)
            target1 = float(target1)
            target2 = float(target2) if target2 is not None else None
        except (TypeError, ValueError):
            return
        risk_pts = abs(entry - stop_px)
        if risk_pts <= 0:
            return

        # Build dedup key — stable within one session/entry-bucket bucket
        ctx = result.get("learning_ctx") or {}
        strategy_key = (ctx.get("strategy_key") or
                        (result.get("strategy_scanner") or {}).get("strategy_key") or
                        "UNKNOWN")
        strategy_short = _pe.extract_strategy_short(strategy_key)

        now_et = now_utc().astimezone(ET_TZ)
        et_day = now_et.strftime("%Y%m%d")
        bucket = _pe.entry_bucket_from_price(entry)
        obs_key = _pe.build_obs_key(inst, direction, strategy_short, et_day, bucket)

        # Per-setup cooldown: suppress rapid re-creation for the same (inst, dir, strategy)
        ckey     = (inst, direction, strategy_short)
        now_mono = time.monotonic()
        with _GHOST_OBS_COOLDOWN_LOCK:
            last = _GHOST_OBS_COOLDOWN.get(ckey)
            if last is not None and (now_mono - last) < GHOST_OBS_COOLDOWN_SECS:
                return
            _GHOST_OBS_COOLDOWN[ckey] = now_mono   # optimistic reservation

        # Commission estimate (stored; watcher uses INSTRUMENT_SPECS at resolve time)
        cost_r_est = _pe.compute_commission_r(
            inst, entry, stop_px, INSTRUMENT_SPECS,
            comm_per_side_usd=SIM_REALISM_COMMISSION_PER_SIDE,
            slippage_ticks=SIM_REALISM_SLIPPAGE_TICKS,
        )

        # Context snapshot — frozen at signal time
        sess_name = (ctx.get("session") or _learning_session_name(now_et) or "UNKNOWN")
        vol_block = result.get("volatility") or {}
        cvd_block = CVD_BY_TICKER.get(inst) or {}
        atr_at_sig = vol_block.get("atr_pts") or vol_block.get("current_atr") or None
        cvd_dir    = cvd_block.get("direction") if isinstance(cvd_block, dict) else None
        vwap_val   = VWAP_BY_TICKER.get(inst)
        vwap_side  = (("above" if entry > vwap_val else "below") if vwap_val else None)
        regime     = ctx.get("regime") or "UNKNOWN"
        edge_score = result.get("edge_score")

        # Phase 8B.1: snapshot MTF trend context at signal time (DISPLAY-ONLY)
        _mtf_snap = _get_mtf_snapshot_at_signal(inst)

        conn = _learning_conn()
        if conn is None:
            with _GHOST_OBS_COOLDOWN_LOCK:
                _GHOST_OBS_COOLDOWN.pop(ckey, None)
            return
        inserted = False
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO ghost_observations
                           (obs_key, strategy_key, strategy_version, instrument,
                            direction, signal_time, original_entry, original_stop,
                            original_target1, original_target2, risk_points,
                            session, trading_mode, source, atr_at_signal,
                            cvd_direction, vwap_side, regime, edge_score_at_signal,
                            status, cost_r, holdout_period,
                            four_h_trend_at_signal, fifteen_m_trend_at_signal,
                            trend_alignment_at_signal,
                            it_trend_15m_native, it_context_1h, it_extension_state,
                            it_setup_score, it_entry_state)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                               %s,%s,%s,%s,'open',%s,'training',%s,%s,%s,
                               %s,%s,%s,%s,%s)
                       ON CONFLICT (obs_key) DO NOTHING
                       RETURNING id""",
                    (obs_key, strategy_key, STRATEGY_VERSION, inst,
                     direction, now_utc(), entry, stop_px,
                     target1, target2, risk_pts,
                     sess_name, TRADING_MODE, source, atr_at_sig,
                     cvd_dir, vwap_side, regime,
                     (int(round(float(edge_score))) if edge_score is not None else None),
                     cost_r_est,
                     _mtf_snap.get('four_h_trend_at_signal'),
                     _mtf_snap.get('fifteen_m_trend_at_signal'),
                     _mtf_snap.get('trend_alignment_at_signal'),
                     # IT-native columns (NULL for non-IT modes)
                     *((lambda _itd: (
                         _itd.get('trend_15m_native'),
                         _itd.get('context_1h'),
                         _itd.get('extension_state'),
                         (int(_itd['setup_score']) if isinstance(_itd.get('setup_score'), (int, float)) else None),
                         _itd.get('entry_state'),
                     ))(result.get('intraday_trend_context') or {})),
                    ),
                )
                row = cur.fetchone()
                inserted = row is not None
        finally:
            try:
                conn.close()
            except Exception:
                pass
        if inserted:
            logger.info(
                "ghost_obs opened: %s %s %s @ %.4f strategy=%s key=%s",
                source, inst, direction, entry, strategy_short, obs_key,
            )
            # ── Phase 8A: create Edge Ledger entry with frozen signal terms ──
            # FAIL-OPEN — EL_DB_READY=False or any exception is a no-op.
            # Never touches gate, scoring, sizing, or execution.
            _el_create_entry(
                obs_key=obs_key, result=result, inst=inst,
                direction=direction, strategy_key=strategy_key,
                entry=entry, stop_px=stop_px, target1=target1, target2=target2,
                risk_pts=risk_pts, cost_r_est=cost_r_est,
                sess_name=sess_name, edge_score=edge_score,
                now_utc_ts=now_utc(),
                mtf_snap=_mtf_snap,
            )
            # ── Phase 8B: emit research event (DISPLAY-ONLY) ────────────────
            _re_event("ghost_created", inst=inst, strategy=strategy_key,
                      verdict=str(result.get("verdict", "")),
                      obs_key=obs_key,
                      extra={"entry": entry, "stop": stop_px,
                             "edge_score": edge_score, "session": sess_name})
            # ── IT inter-trade cooldown: start clock on IT ghost obs create ───
            # Per spec §9: 15-min cooldown begins the moment a new IT observation
            # is registered (shadow mode — not on execution).
            if TRADING_MODE == "INTRADAY_TREND":
                _it_register_cooldown(inst)
        else:
            # ON CONFLICT — already exists; undo cooldown reservation
            with _GHOST_OBS_COOLDOWN_LOCK:
                _GHOST_OBS_COOLDOWN.pop(ckey, None)
    except Exception as exc:
        logger.debug("ghost_observe_setup error (%s): %s", inst, exc)


def _ghost_obs_watcher_cycle():
    """Resolve open ghost observations against the latest bar data.

    Called on every bar-close via _ghost_obs_bar_close().  Updates MFE/MAE
    and closes observations when stop, target, or max-hold is reached.

    Conservative resolution: when a bar touches BOTH stop and target, the
    stop-first outcome is recorded (no optimistic fill assumptions).

    FAIL-OPEN — individual row errors are caught and logged; the cycle
    continues.  NEVER touches execution path: writes only to ghost_observations.
    """
    if not GHOST_OBS_DB_READY or not LEARNING_DB_ENABLED:
        return
    try:
        import profitability_engine as _pe  # noqa: PLC0415
    except Exception:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, obs_key, instrument, direction,
                          original_entry, original_stop,
                          original_target1, original_target2,
                          risk_points, bars_held,
                          mfe_r, mae_r, mfe_price, mae_price, cost_r,
                          tp1_hit, tp1_exit_price, tp1_gross_r, exit_model
                   FROM ghost_observations
                   WHERE status = 'open'
                   ORDER BY id ASC LIMIT 500""")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "obs_key": r[1], "instrument": r[2], "direction": r[3],
                    "entry":      float(r[4]) if r[4] is not None else None,
                    "stop_px":    float(r[5]) if r[5] is not None else None,
                    "target1":    float(r[6]) if r[6] is not None else None,
                    "target2":    float(r[7]) if r[7] is not None else None,
                    "risk_pts":   float(r[8]) if r[8] is not None else None,
                    "bars_held":  int(r[9])   if r[9] is not None else 0,
                    "mfe_r":      float(r[10]) if r[10] is not None else 0.0,
                    "mae_r":      float(r[11]) if r[11] is not None else 0.0,
                    "mfe_price":  float(r[12]) if r[12] is not None else None,
                    "mae_price":  float(r[13]) if r[13] is not None else None,
                    "cost_r":     float(r[14]) if r[14] is not None else None,
                    "tp1_hit":        bool(r[15]) if r[15] is not None else False,
                    "tp1_exit_price": float(r[16]) if r[16] is not None else None,
                    "tp1_gross_r":    float(r[17]) if r[17] is not None else None,
                    "exit_model":     (r[18] or _pe.EXIT_MODEL_SINGLE),
                })
    except Exception as exc:
        logger.warning("ghost_obs watcher read failed: %s", exc)
        try:
            conn.close()
        except Exception:
            pass
        return
    if not open_rows:
        try:
            conn.close()
        except Exception:
            pass
        return

    # Fetch latest bar per unique instrument (one lookup per instrument)
    bars: dict = {}
    for inst in {r["instrument"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None

    now_ts = now_utc()
    try:
        for row in open_rows:
            inst = row["instrument"]
            bar  = bars.get(inst)
            if bar is None:
                continue
            try:
                bar_h = float(bar.get("high") or bar.get("h") or 0)
                bar_l = float(bar.get("low")  or bar.get("l") or 0)
            except (TypeError, ValueError):
                continue
            if bar_h <= 0 or bar_l <= 0:
                continue
            entry    = row["entry"]
            stop_px  = row["stop_px"]
            target1  = row["target1"]
            target2  = row["target2"]
            risk_pts = row["risk_pts"]
            if any(v is None for v in (entry, stop_px, target1, risk_pts)):
                continue
            bars_held = row["bars_held"] + 1

            # Update MFE/MAE (every bar, regardless of close)
            mfe_r, mae_r, mfe_price, mae_price = _pe.update_mfe_mae(
                row["direction"], bar_h, bar_l, entry, risk_pts,
                row.get("mfe_price"), row.get("mae_price"),
                row["mfe_r"], row["mae_r"],
            )

            # Check for close condition (conservative stop-first)
            # Pass tp1_hit from DB so TP1-already-hit obs correctly look for TP2
            status, close_reason, exit_px, gross_r = _pe.resolve_bar_outcome(
                row["direction"], bar_h, bar_l, entry, stop_px,
                target1, target2,
                row.get("tp1_hit", False),
                bars_held, _pe.GHOST_MAX_HOLD_BARS,
            )

            if close_reason == _pe.CLOSE_TP1_PARTIAL:
                # ─── Leg 1 of a two-leg trade hit TP1 — keep open for leg 2 ───
                # status is None here (observation stays open)
                try:
                    with conn.cursor() as cur:
                        cur.execute(
                            """UPDATE ghost_observations SET
                                   tp1_hit=TRUE, tp1_exit_price=%s, tp1_gross_r=%s,
                                   exit_model=%s,
                                   mfe_r=%s, mae_r=%s, mfe_price=%s, mae_price=%s,
                                   bars_held=%s WHERE id=%s""",
                            (exit_px,
                             (round(gross_r, 4) if gross_r is not None else None),
                             _pe.EXIT_MODEL_TWO_LEG,
                             round(mfe_r, 4), round(mae_r, 4),
                             mfe_price, mae_price, bars_held, row["id"]))
                    logger.info(
                        "ghost_obs tp1_partial: id=%d %s %s TP1 hit @ %s, staying open for leg 2",
                        row["id"], inst, row["direction"], exit_px)
                    # ── Phase 8B: emit research event (DISPLAY-ONLY) ──────
                    _re_event("tp1_hit", inst=inst,
                              strategy=row.get("strategy_key"),
                              obs_key=row.get("obs_key"),
                              extra={"exit_px": exit_px, "ghost_id": row["id"]})
                except Exception as exc:
                    logger.warning("ghost_obs tp1_partial UPDATE id=%d: %s", row["id"], exc)

            elif status is not None:
                # ─── Observation closing (stop / TP1 single-leg / TP2 / expired) ───
                # For two-leg trades: compute weighted gross_r
                if (row.get("exit_model") == _pe.EXIT_MODEL_TWO_LEG
                        and row.get("tp1_gross_r") is not None
                        and gross_r is not None):
                    gross_r = _pe.compute_two_leg_gross_r(
                        row["tp1_gross_r"], gross_r,
                    )
                cost_r = row["cost_r"]
                if cost_r is None:
                    cost_r = _pe.compute_commission_r(
                        inst, entry, stop_px, INSTRUMENT_SPECS,
                        comm_per_side_usd=SIM_REALISM_COMMISSION_PER_SIDE,
                        slippage_ticks=SIM_REALISM_SLIPPAGE_TICKS,
                    )
                net_r = ((gross_r - cost_r)
                         if (gross_r is not None and cost_r is not None)
                         else gross_r)
                try:
                    with conn.cursor() as cur:
                        cur.execute(
                            """UPDATE ghost_observations SET
                                   status=%s, closed_at=%s, close_reason=%s,
                                   exit_price=%s, gross_r=%s, cost_r=%s, net_r=%s,
                                   mfe_r=%s, mae_r=%s, mfe_price=%s, mae_price=%s,
                                   bars_held=%s
                               WHERE id=%s""",
                            (status, now_ts, close_reason, exit_px,
                             (round(gross_r, 4) if gross_r is not None else None),
                             (round(cost_r,  4) if cost_r  is not None else None),
                             (round(net_r,   4) if net_r   is not None else None),
                             (round(mfe_r,   4) if mfe_r   is not None else None),
                             (round(mae_r,   4) if mae_r   is not None else None),
                             mfe_price, mae_price, bars_held, row["id"]))
                    logger.info(
                        "ghost_obs %s: id=%d %s %s → %s (%s) gross_r=%s net_r=%s",
                        status, row["id"], inst, row["direction"],
                        status, close_reason,
                        (f"{gross_r:+.2f}" if gross_r is not None else "?"),
                        (f"{net_r:+.2f}"   if net_r   is not None else "?"),
                    )
                except Exception as exc:
                    logger.warning("ghost_obs UPDATE failed id=%d: %s", row["id"], exc)
                # ── Phase 8A: update edge_ledger signal outcome ──────────────
                # FAIL-OPEN — EL_DB_READY=False or any exception is a no-op.
                # Uses same conn; _el_update_signal_outcome_conn is its own try/except.
                _el_update_signal_outcome_conn(
                    conn, obs_key=row["obs_key"],
                    status=status, close_reason=close_reason,
                    exit_px=exit_px, gross_r=gross_r, net_r=net_r,
                    cost_r=cost_r, mfe_r=mfe_r, mae_r=mae_r,
                    now_ts=now_ts,
                )
                # ── Phase 8B: emit research event (DISPLAY-ONLY) ────────────
                _re_event(status, inst=inst,
                          strategy=row.get("strategy_key"),
                          obs_key=row.get("obs_key"),
                          net_r=net_r,
                          extra={"close_reason": close_reason, "gross_r": gross_r,
                                 "ghost_id": row["id"]})
                # ── INTRADAY TREND extended ghost analytics ──────────────────
                # Persist IT-specific outcome fields (1R/2R/3R flags, pts,
                # premature-exit flag) when the closed ghost is an IT trade.
                # FAIL-OPEN — swallowed inside _it_ghost_write_extended_fields.
                if row.get("trading_mode") == "INTRADAY_TREND":
                    _it_ghost_write_extended_fields(
                        conn,
                        obs_id      = row["id"],
                        entry_price = row.get("entry_price"),
                        mfe_price   = mfe_price,
                        mae_price   = mae_price,
                        mfe_r       = mfe_r,
                        gross_r     = gross_r,
                    )

            else:
                # Still open — persist updated MFE/MAE and bars_held
                try:
                    with conn.cursor() as cur:
                        cur.execute(
                            """UPDATE ghost_observations SET
                                   mfe_r=%s, mae_r=%s, mfe_price=%s, mae_price=%s,
                                   bars_held=%s WHERE id=%s""",
                            (round(mfe_r, 4), round(mae_r, 4),
                             mfe_price, mae_price, bars_held, row["id"]))
                except Exception as exc:
                    logger.debug("ghost_obs mfe_mae update id=%d: %s", row["id"], exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _ghost_obs_bar_close(inst: str, price: float) -> None:
    """Bar-close callback registered with DatabentoBrain.
    Triggers one ghost-observation watcher cycle.  Single-flight: returns
    immediately if another cycle is already running."""
    if not GHOST_OBS_DB_READY:
        return
    if not GHOST_OBS_WATCH_LOCK.acquire(blocking=False):
        return
    try:
        _ghost_obs_watcher_cycle()
    except Exception as exc:
        logger.debug("ghost_obs bar_close error: %s", exc)
    finally:
        GHOST_OBS_WATCH_LOCK.release()


def _micro_scalp_record_event(normalized, inst, price):
    """Webhook-seam recorder for the Micro Scalp price trail + micro events.
    NO-OP unless the mode toggle is ON (flag-OFF byte-identical). DISPLAY/STATE
    only — never scores, never gates, never raises into the webhook path."""
    if not inst or not _micro_scalp_on():
        return
    try:
        now_ep = time.time()
        cat = direction = None
        if normalized in FAST_MICRO_CHOCH_LONG_TYPES:
            cat, direction = "micro CHOCH", "Long"
        elif normalized in FAST_MICRO_CHOCH_SHORT_TYPES:
            cat, direction = "micro CHOCH", "Short"
        elif normalized in FAST_MICRO_VWAP_RECLAIM_TYPES:
            cat, direction = "micro VWAP reclaim", "Long"
        elif normalized in FAST_MICRO_VWAP_LOSS_TYPES:
            cat, direction = "micro VWAP loss", "Short"
        elif normalized in FAST_DELTA_FLIP_BULL_TYPES:
            cat, direction = "delta flip", "Long"
        elif normalized in FAST_DELTA_FLIP_BEAR_TYPES:
            cat, direction = "delta flip", "Short"
        elif normalized in FAST_SWEEP_RECLAIM_LONG_TYPES:
            cat, direction = "sweep reclaim", "Long"
        elif normalized in FAST_SWEEP_RECLAIM_SHORT_TYPES:
            cat, direction = "sweep reclaim", "Short"
        with MICRO_STORE_LOCK:
            if price is not None:
                try:
                    MICRO_TRAIL_BY_INST.setdefault(inst, deque(maxlen=240)).append(
                        {"price": float(price), "epoch": now_ep})
                except (TypeError, ValueError):
                    pass
            if cat:
                MICRO_EVENTS_BY_INST.setdefault(inst, deque(maxlen=60)).append(
                    {"cat": cat, "direction": direction, "epoch": now_ep})
    except Exception:
        pass


def _micro_scalp_live_ctx(result):
    """Normalize a full_analysis `result` + the live read-only stores into the flat
    context dict the PURE micro_scalp engine consumes. Read-only; FAIL-OPEN
    (returns None if the essentials are missing). Never mutates `result`."""
    try:
        inst = instrument_of(result.get("active_ticker") or "")
        if not inst:
            return None
        now = now_utc()
        now_ep = now.timestamp()
        l = {
            "inst":         inst,
            "generated_at": now.isoformat(),
            "now_epoch":    now_ep,
            "market_open":  bool(result.get("market_open")),
            "price":        result.get("current_price"),
            "vwap":         result.get("vwap_value"),
            "atr_pts":      (result.get("volatility") or {}).get("atr_pts"),
            "specs":        MICRO_SPECS.get(inst) or {},
        }
        # Recent instrument-scoped SWEEP alerts (list() snapshot — never the live
        # deque). "BULLISH SWEEP" = lows swept; "BEARISH SWEEP" = highs swept.
        sweeps = []
        for a in reversed(list(ALERT_HISTORY)):
            at = a.get("alert_type") or ""
            if "SWEEP" not in at or "RECLAIM" in at:
                continue
            a_inst = (a.get("instrument")
                      or _instrument_from_text(a.get("ticker"))
                      or _instrument_from_text(at))
            if a_inst != inst:
                continue
            try:
                ts = datetime.fromisoformat(a["timestamp"])
            except (KeyError, ValueError, TypeError):
                continue
            age = (now - ts).total_seconds()
            if age < 0 or age > 900:
                continue
            d = "low" if "BULLISH" in at else ("high" if "BEARISH" in at else None)
            if d is None:
                continue
            try:
                px = float(a.get("price")) if a.get("price") is not None else None
            except (TypeError, ValueError):
                px = None
            sweeps.append({"direction": d, "price": px, "age_sec": age})
            if len(sweeps) >= 6:
                break
        l["sweeps"] = sweeps
        # Recent range reference: current-session high/low, else opening range.
        rh = rl = None
        try:
            with INTRADAY_LOCK:
                rec = INTRADAY_BY_TICKER.get(inst) or {}
                sessions = {k: dict(v) for k, v in (rec.get("sessions") or {}).items()
                            if isinstance(v, dict)}
            cur_name, _cur_id = _bias_session_for(now.astimezone(ET_TZ))
            s = sessions.get(cur_name) or {}
            rh, rl = s.get("high"), s.get("low")
        except Exception:
            pass
        if rh is None or rl is None:
            try:
                orb = _intraday_or(inst) or {}
                rh = rh if rh is not None else orb.get("high")
                rl = rl if rl is not None else orb.get("low")
            except Exception:
                pass
        l["range_high"], l["range_low"] = rh, rl
        # CVD / volume-spike / RVOL snapshots (ts-aged — set-membership != fresh).
        def _iso_age(iso):
            try:
                return max(0.0, (now - datetime.fromisoformat(iso)).total_seconds())
            except (TypeError, ValueError):
                return None
        cvd = CVD_BY_TICKER.get(inst) or {}
        l["cvd_state"]   = cvd.get("state")
        l["cvd_age_sec"] = _iso_age(cvd.get("ts"))
        vs = VOLUME_SPIKE_BY_TICKER.get(inst) or {}
        l["volume_spike_age_sec"] = _iso_age(vs.get("ts"))
        rv = RVOL_BY_TICKER.get(inst) or {}
        l["rvol"] = rv.get("value")
        # Micro events + price trail (snapshots under the store lock).
        with MICRO_STORE_LOCK:
            evs   = list(MICRO_EVENTS_BY_INST.get(inst) or ())
            trail = list(MICRO_TRAIL_BY_INST.get(inst) or ())
        l["micro_events"] = [{"cat": e.get("cat"), "direction": e.get("direction"),
                              "age_sec": max(0.0, now_ep - (e.get("epoch") or 0))}
                             for e in evs]
        l["price_trail"] = trail
        return l
    except Exception:
        return None


_MICRO_GHOST_STATS_CACHE = {}   # inst-or-"ALL" -> {"ts": monotonic, "data": {...}}
_MICRO_GHOST_STATS_LOCK  = threading.Lock()
MICRO_GHOST_STATS_TTL    = 60


def _micro_ghost_stats(inst=None):
    """Ghost ledger read for the dashboard (recent trades + aggregate). DISPLAY-
    ONLY, FAIL-OPEN, TTL-cached so the /status poll never hammers Postgres."""
    global MICRO_GHOST_DB_READY
    key = inst or "ALL"
    now_mono = time.monotonic()
    with _MICRO_GHOST_STATS_LOCK:
        c = _MICRO_GHOST_STATS_CACHE.get(key)
        if c and (now_mono - c["ts"]) < MICRO_GHOST_STATS_TTL:
            return c["data"]
    out = {"db_ready": bool(MICRO_GHOST_DB_READY), "open": [], "recent": [],
           "stats": {"trades": 0, "wins": 0, "losses": 0, "breakeven": 0,
                     "expired": 0, "win_rate": None, "net_r": 0.0,
                     "avg_time_to_tp1_sec": None}}
    if not MICRO_GHOST_DB_READY:
        _check_micro_ghost_db_ready()
        out["db_ready"] = bool(MICRO_GHOST_DB_READY)
    if not MICRO_GHOST_DB_READY:
        with _MICRO_GHOST_STATS_LOCK:
            _MICRO_GHOST_STATS_CACHE[key] = {"ts": now_mono, "data": out}
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    try:
        with conn.cursor() as cur:
            where = "WHERE symbol = %s" if inst else ""
            args  = (inst,) if inst else ()
            cur.execute(
                "SELECT symbol, direction, setup_type, entry, stop, tp1, tp2, status, "
                "tp1_hit, mfe_points, mae_points, outcome, outcome_reason, result_r, "
                "time_to_tp1_sec, time_to_exit_sec, opened_at, closed_at "
                "FROM micro_scalp_ghost_trades %s "
                "ORDER BY id DESC LIMIT 10" % where, args)
            for r in cur.fetchall():
                rec = {"symbol": r[0], "direction": r[1], "setup_type": r[2],
                       "entry": float(r[3]) if r[3] is not None else None,
                       "stop": float(r[4]) if r[4] is not None else None,
                       "tp1": float(r[5]) if r[5] is not None else None,
                       "tp2": float(r[6]) if r[6] is not None else None,
                       "status": r[7], "tp1_hit": bool(r[8]),
                       "mfe_points": float(r[9]) if r[9] is not None else None,
                       "mae_points": float(r[10]) if r[10] is not None else None,
                       "outcome": r[11], "outcome_reason": r[12],
                       "result_r": float(r[13]) if r[13] is not None else None,
                       "time_to_tp1_sec": r[14], "time_to_exit_sec": r[15],
                       "opened_at": fmt_et(r[16]) if r[16] is not None else None,
                       "closed_at": fmt_et(r[17]) if r[17] is not None else None}
                (out["open"] if r[7] == "open" else out["recent"]).append(rec)
            cur.execute(
                "SELECT outcome, COUNT(*), COALESCE(SUM(result_r),0), "
                "AVG(time_to_tp1_sec) "
                "FROM micro_scalp_ghost_trades %s%s GROUP BY outcome"
                % (where, (" AND" if inst else " WHERE") + " status='closed'"), args)
            tt_tp1 = []
            for oc, n, net_r, avg_tp1 in cur.fetchall():
                out["stats"]["trades"] += int(n)
                out["stats"]["net_r"]  = round(out["stats"]["net_r"] + float(net_r), 2)
                if oc == "win":
                    out["stats"]["wins"] += int(n)
                elif oc == "loss":
                    out["stats"]["losses"] += int(n)
                elif oc == "breakeven":
                    out["stats"]["breakeven"] += int(n)
                elif oc == "expired":
                    out["stats"]["expired"] += int(n)
                if avg_tp1 is not None:
                    tt_tp1.append(float(avg_tp1))
            wl = out["stats"]["wins"] + out["stats"]["losses"]
            if wl:
                out["stats"]["win_rate"] = round(100.0 * out["stats"]["wins"] / wl, 1)
            if tt_tp1:
                out["stats"]["avg_time_to_tp1_sec"] = int(sum(tt_tp1) / len(tt_tp1))
    except Exception as exc:
        logger.warning("micro ghost stats read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    with _MICRO_GHOST_STATS_LOCK:
        _MICRO_GHOST_STATS_CACHE[key] = {"ts": now_mono, "data": out}
    return out


MICRO_LIVE_DB_READY = False
_MICRO_LIVE_ORDERS_CACHE = {}
_MICRO_LIVE_ORDERS_LOCK = threading.Lock()
MICRO_LIVE_ORDERS_TTL = 45.0


def _check_micro_live_db_ready():
    """No-DDL readiness probe for micro_scalp_live_orders (mirrors the ghost-table
    convention: the table is created by the database tool in dev and arrives in prod
    via the Publish schema-diff — the app NEVER runs CREATE TABLE)."""
    global MICRO_LIVE_DB_READY
    conn = _learning_conn()
    if conn is None:
        MICRO_LIVE_DB_READY = False
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM micro_scalp_live_orders LIMIT 1")
            cur.fetchall()
        MICRO_LIVE_DB_READY = True
    except Exception as exc:
        MICRO_LIVE_DB_READY = False
        logger.warning("micro live-order table not ready: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _record_micro_live_order(inst, plan, provider, status):
    """Persist ONE row for a REAL micro-scalp order the gateway just transmitted
    (or paper-simulated). Display-only ledger — INSERT/SELECT only, FAIL-OPEN:
    a ledger failure never touches the send, tracking or dedupe (the order is
    already on its way when this runs)."""
    if not MICRO_LIVE_DB_READY:
        _check_micro_live_db_ready()
    if not MICRO_LIVE_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        def _f(v):
            try:
                return float(v) if v is not None else None
            except (TypeError, ValueError):
                return None
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO micro_scalp_live_orders "
                "(instrument, direction, quantity, entry, stop, target, provider, status) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
                (inst, plan.get("direction"),
                 int(plan.get("quantity")) if plan.get("quantity") is not None else None,
                 _f(plan.get("entry")), _f(plan.get("stopLoss")),
                 _f(plan.get("takeProfit")), provider, status))
        with _MICRO_LIVE_ORDERS_LOCK:
            _MICRO_LIVE_ORDERS_CACHE.clear()
        logger.info("Micro live-order ledger recorded: %s %s x%s (%s)",
                    inst, plan.get("direction"), plan.get("quantity"), status)
    except Exception as exc:
        logger.warning("micro live-order ledger insert failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _micro_live_orders(inst=None):
    """REAL-ORDER ledger read for the dashboard (TTL-cached, fail-open). Returns
    the newest orders actually handed to the broker for this instrument — the
    honest counterpart to the ghost ledger. Fills/outcomes settle at the broker;
    this app never receives them, so no outcome is fabricated here."""
    key = inst or "__ALL__"
    now_mono = time.monotonic()
    with _MICRO_LIVE_ORDERS_LOCK:
        hit = _MICRO_LIVE_ORDERS_CACHE.get(key)
        if hit and (now_mono - hit["ts"]) < MICRO_LIVE_ORDERS_TTL:
            return hit["data"]
    out = {"db_ready": False, "orders": [], "total": 0, "total_sent": 0}
    if not MICRO_LIVE_DB_READY:
        _check_micro_live_db_ready()
    out["db_ready"] = bool(MICRO_LIVE_DB_READY)
    if not MICRO_LIVE_DB_READY:
        with _MICRO_LIVE_ORDERS_LOCK:
            _MICRO_LIVE_ORDERS_CACHE[key] = {"ts": now_mono, "data": out}
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    try:
        with conn.cursor() as cur:
            where = "WHERE instrument = %s" if inst else ""
            args  = (inst,) if inst else ()
            cur.execute(
                "SELECT instrument, direction, quantity, entry, stop, target, "
                "provider, status, sent_at "
                "FROM micro_scalp_live_orders %s "
                "ORDER BY id DESC LIMIT 8" % where, args)
            for r in cur.fetchall():
                out["orders"].append({
                    "instrument": r[0], "direction": r[1],
                    "quantity": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "target": float(r[5]) if r[5] is not None else None,
                    "provider": r[6], "status": r[7],
                    "sent_at": fmt_et(r[8]) if r[8] is not None else None})
            cur.execute("SELECT COUNT(*), "
                        "COUNT(*) FILTER (WHERE status = 'sent') "
                        "FROM micro_scalp_live_orders %s" % where, args)
            _tot, _sent = cur.fetchone()
            out["total"] = int(_tot)
            out["total_sent"] = int(_sent)
    except Exception as exc:
        logger.warning("micro live-order ledger read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    with _MICRO_LIVE_ORDERS_LOCK:
        _MICRO_LIVE_ORDERS_CACHE[key] = {"ts": now_mono, "data": out}
    return out


def compute_micro_scalp(result):
    """Full Micro Scalp Brain block for the CURRENT result — pure-engine read +
    ghost ledger summary. DISPLAY-ONLY; FAIL-OPEN to the neutral schema."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    inst = instrument_of(inst_label) if inst_label else None
    try:
        import micro_scalp as ms
    except Exception as exc:
        return {"enabled": True, "available": False, "instrument": inst_label,
                "verdict": "NO TRADE", "evidence": [],
                "summary": "Micro Scalp engine unavailable (%s)." % exc}
    l = _micro_scalp_live_ctx(result)
    if l is None:
        block = ms.neutral("Micro Scalp context unavailable.", inst_label,
                           enabled=True, generated_at=now_utc().isoformat())
    else:
        block = ms.evaluate(l)
    try:
        block["ghost"] = _micro_ghost_stats(inst)
    except Exception:
        block["ghost"] = {"db_ready": False, "open": [], "recent": [], "stats": {}}
    try:
        block["live_orders"] = _micro_live_orders(inst)
    except Exception:
        block["live_orders"] = {"db_ready": False, "orders": [], "total": 0, "total_sent": 0}
    return block


def _micro_ghost_open_insert(sim_key, inst, block):
    """Idempotently INSERT one OPEN ghost trade (ON CONFLICT sim_key DO NOTHING)
    with a one-open-per-instrument guard. Writes ONLY to micro_scalp_ghost_trades.
    Returns True if a row was actually opened."""
    if not MICRO_GHOST_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        entry = float(block["suggested_entry"])
        stop  = float(block["suggested_stop"])
        risk  = abs(entry - stop)
        if risk <= 0:
            return False
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM micro_scalp_ghost_trades "
                        "WHERE symbol=%s AND status='open' LIMIT 1", (inst,))
            if cur.fetchone():
                return False
            cur.execute(
                "INSERT INTO micro_scalp_ghost_trades "
                "(sim_key, symbol, direction, setup_type, entry, stop, tp1, tp2, "
                " runner_target, risk_points, entry_reason, entry_epoch) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) "
                "ON CONFLICT (sim_key) DO NOTHING",
                (sim_key, inst, block.get("direction"), block.get("setup_type"),
                 entry, stop, float(block["tp1"]), float(block["tp2"]),
                 (float(block["runner_target"]) if block.get("runner_target")
                  is not None else None),
                 risk, (block.get("entry_reason") or "")[:500],
                 int(now_utc().timestamp())))
            opened = (cur.rowcount == 1)
        conn.commit()
        return opened
    except Exception as exc:
        logger.warning("micro ghost open failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _maybe_open_micro_ghost(result, source="webhook"):
    """GHOST observer — logs the trade the Micro Scalp engine WOULD take. Runs
    ONLY from the webhook analysis path, only while the toggle is ON, only on a
    TAKE verdict. NEVER sends an order; the only side effect is an idempotent
    INSERT into micro_scalp_ghost_trades. Returns 1 if a ghost was opened."""
    if source != "webhook" or not _micro_scalp_on() or not MICRO_GHOST_DB_READY:
        return 0
    block = (result.get("main_brain") or {}).get("micro_scalp")
    if not isinstance(block, dict) or block.get("verdict") != "TAKE":
        return 0
    inst = instrument_of(result.get("active_ticker") or "")
    direction = block.get("direction")
    if not inst or direction not in ("Long", "Short"):
        return 0
    if any(block.get(k) is None for k in
           ("suggested_entry", "suggested_stop", "tp1", "tp2")):
        return 0
    try:
        if not market_session_status().get("open", True):
            return 0
    except Exception:
        pass
    now_mono = time.monotonic()
    ckey = (inst, direction)
    with _MICRO_GHOST_COOLDOWN_LOCK:
        last = _MICRO_GHOST_COOLDOWN.get(ckey)
        if last is not None and (now_mono - last) < MICRO_GHOST_OPEN_COOLDOWN_SECS:
            return 0
    et_day = now_utc().astimezone(ET_TZ).strftime("%Y%m%d")
    bucket = int(now_utc().timestamp() // 300)   # 5-min idempotency bucket
    try:
        anchor_px = int(round(float(block["suggested_entry"])))
    except (TypeError, ValueError, KeyError):
        anchor_px = 0
    sim_key = "micro|%s|%s|%s:%d:%d" % (inst, direction, et_day, bucket, anchor_px)
    if _micro_ghost_open_insert(sim_key, inst, block):
        with _MICRO_GHOST_COOLDOWN_LOCK:
            _MICRO_GHOST_COOLDOWN[ckey] = now_mono
        logger.info("micro scalp GHOST opened: %s %s @ %s (no order — ghost only)",
                    inst, direction, block.get("suggested_entry"))
        return 1
    return 0


def _watch_micro_ghost_trades():
    """Resolve OPEN ghost trades against the latest 1-minute bar (one fetch per
    instrument per cycle) using the PURE micro_scalp.ghost_bar_update resolver:
    stop-first worst-case, TP1 → BE, TP2 win, MFE/MAE tracking, max-hold expiry,
    SAME-BAR guard. Writes ONLY to micro_scalp_ghost_trades."""
    if not MICRO_GHOST_DB_READY:
        return
    try:
        import micro_scalp as ms
    except Exception:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, symbol, direction, entry, stop, tp1, tp2, risk_points, "
                "tp1_hit, mfe_points, mae_points, entry_epoch, opened_at "
                "FROM micro_scalp_ghost_trades WHERE status='open' "
                "ORDER BY id ASC LIMIT 200")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "symbol": r[1], "direction": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "tp1": float(r[5]) if r[5] is not None else None,
                    "tp2": float(r[6]) if r[6] is not None else None,
                    "risk_points": float(r[7]) if r[7] is not None else None,
                    "tp1_hit": bool(r[8]),
                    "mfe_points": float(r[9]) if r[9] is not None else 0.0,
                    "mae_points": float(r[10]) if r[10] is not None else 0.0,
                    "entry_epoch": float(r[11]) if r[11] is not None else None,
                    "opened_at": r[12]})
    except Exception as exc:
        logger.warning("micro ghost watcher read failed: %s", exc)
        try:
            conn.close()
        except Exception:
            pass
        return
    finally:
        if not open_rows:
            try:
                conn.close()
            except Exception:
                pass
    if not open_rows:
        return
    bars = {}
    for inst in {r["symbol"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    try:
        for row in open_rows:
            bar = bars.get(row["symbol"])
            if not bar:
                continue
            bar_start, entry_epoch = bar.get("start"), row.get("entry_epoch")
            if bar_start is not None and entry_epoch is not None \
                    and bar_start <= entry_epoch:
                continue                   # same-bar guard (no look-ahead self-fill)
            upd = ms.ghost_bar_update(row, bar)
            if upd is None:
                continue
            outcome = upd.get("outcome")
            if outcome is None:
                # Max-hold expiry: resolve a stranded ghost at the latest close.
                opened_at, cl = row.get("opened_at"), bar.get("close")
                risk = row.get("risk_points") or 0
                if opened_at is not None and cl is not None and risk > 0:
                    try:
                        oa = opened_at if opened_at.tzinfo else \
                            opened_at.replace(tzinfo=timezone.utc)
                        aged = ((now_utc() - oa).total_seconds()
                                > MICRO_GHOST_MAX_HOLD_MIN * 60)
                    except Exception:
                        aged = False
                    if aged:
                        r_mult = ((cl - row["entry"]) / risk
                                  if row["direction"] == "Long"
                                  else (row["entry"] - cl) / risk)
                        upd.update({"outcome": "expired",
                                    "exit_price": round(cl, 4),
                                    "result_r": round(r_mult, 4)})
                        outcome = "expired"
            with conn.cursor() as cur:
                if outcome is not None:
                    reason = {"win": "TP2 hit",
                              "loss": "Stopped out before TP1",
                              "breakeven": "BE stop hit after TP1 banked",
                              "expired": "Max hold reached — closed at market"}.get(
                                  outcome, outcome)
                    cur.execute(
                        "UPDATE micro_scalp_ghost_trades SET status='closed', "
                        "outcome=%s, outcome_reason=%s, result_r=%s, "
                        "mfe_points=%s, mae_points=%s, closed_at=now(), "
                        "time_to_exit_sec=GREATEST(0, EXTRACT(EPOCH FROM "
                        "(now()-opened_at)))::int "
                        "WHERE id=%s AND status='open'",
                        (outcome, reason, upd.get("result_r"),
                         upd["mfe_points"], upd["mae_points"], row["id"]))
                elif upd.get("tp1_hit") and not row.get("tp1_hit"):
                    cur.execute(
                        "UPDATE micro_scalp_ghost_trades SET tp1_hit=TRUE, "
                        "tp1_at=now(), be_armed=TRUE, stop=%s, "
                        "mfe_points=%s, mae_points=%s, "
                        "time_to_tp1_sec=GREATEST(0, EXTRACT(EPOCH FROM "
                        "(now()-opened_at)))::int "
                        "WHERE id=%s AND status='open'",
                        (upd.get("new_stop"), upd["mfe_points"],
                         upd["mae_points"], row["id"]))
                else:
                    if (upd["mfe_points"] != row["mfe_points"]
                            or upd["mae_points"] != row["mae_points"]):
                        cur.execute(
                            "UPDATE micro_scalp_ghost_trades SET mfe_points=%s, "
                            "mae_points=%s WHERE id=%s AND status='open'",
                            (upd["mfe_points"], upd["mae_points"], row["id"]))
            conn.commit()
    except Exception as exc:
        logger.warning("micro ghost watcher update failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _micro_ghost_watch_loop():
    """Ghost watcher on its own timer. Gated INSIDE the loop to the LIVE instance
    (DISCORD_LIVE_ENABLED) + DB ready — NOT on the toggle, so ghosts opened before
    a toggle-off still resolve. Single-flight; FAIL-OPEN; never the money path."""
    try:
        if MICRO_GHOST_DB_READY and DISCORD_LIVE_ENABLED:
            if MICRO_GHOST_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_micro_ghost_trades()
                finally:
                    MICRO_GHOST_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("micro ghost watch loop error: %s", exc)
    finally:
        threading.Timer(MICRO_GHOST_WATCH_INTERVAL, _micro_ghost_watch_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# DUAL-MODE SHADOW SIMULATOR — passive, ALWAYS-ON paper sim of BOTH rulebooks
# ════════════════════════════════════════════════════════════════════════════
# Faithfully replays the bot's REAL gate verdict for BOTH the SCALP and SWING
# rulebooks at once — regardless of the live TRADING_MODE / arming — and paper-
# trades each into its OWN ledger (dual_sim_trades) for a side-by-side comparison.
# It reuses the SAME mode-parameterized building blocks the live gate uses
# (evaluate_strict_setup(mode=) -> compute_swing_context -> build_strict_trade_plan(mode=)
# -> SCALP/SWING entry vetoes -> zone-broken/mitigated overrides), so a shadow
# verdict is byte-faithful to what the LIVE gate would decide in that mode.
#
# FULLY walled off from the money path: it NEVER sends a broker order, never calls
# the execution gateway / auto-trade, never writes strategy_trades / MANAGED_TRADES /
# learning, and never mutates the verdict / trade_plan / edge_score. App-side
# INSERT/SELECT ONLY (the table is created out-of-band — DB tool in dev, Publish
# schema-diff in prod). Gated behind DUAL_MODE_SHADOW_SIM_ENABLED (default 0) →
# flag OFF == byte-identical (the result key is never attached and the observer /
# watcher early-return). Everything is FAIL-OPEN except the verdict replay, which
# is FAIL-CLOSED to WAIT so a broken shadow can never fabricate a paper entry.
DUAL_MODE_SHADOW_SIM_ENABLED = os.environ.get(
    "DUAL_MODE_SHADOW_SIM_ENABLED", "0").strip().lower() in ("1", "true", "yes", "on")
DUAL_SIM_DB_READY           = False
DUAL_SIM_WATCH_LOCK         = threading.Lock()   # single-flight: one watcher cycle at a time
DUAL_SIM_WATCH_INTERVAL     = max(10, int(os.environ.get("DUAL_SIM_WATCH_INTERVAL", 15)))
DUAL_SIM_OPEN_COOLDOWN_SECS = max(60, int(os.environ.get("DUAL_SIM_COOLDOWN_SECS", 300)))
DUAL_SIM_MAX_HOLD_HOURS     = max(1, int(os.environ.get("DUAL_SIM_MAX_HOLD_HOURS", 12)))
DUAL_SIM_MODES              = ("SCALP", "SWING")
# TEST trigger (default 0 == OFF ⇒ byte-identical). When > 0, the shadow observer ALSO
# opens a paper trade for a mode whenever that mode's Edge Score clears this threshold,
# even if the live gate said WAIT (structure/VWAP/zone not fully aligned). Purely for
# generating test entries in the SIMULATOR — it shares NO code with the live money path
# (the only DB write is still _dual_sim_open_insert into dual_sim_trades).
DUAL_SIM_TEST_EDGE_MIN     = max(0, int(os.environ.get("DUAL_SIM_TEST_EDGE_MIN", 0)))
# DISPLAY-ONLY Edge-quality tiers for the dashboard: each tier RE-BUCKETS the SAME
# shadow paper trades by the edge_score stored at open (a >=90 setup also counts in
# the >=80 and >=70 cohorts), so the operator can compare how trades taken at each
# quality cutoff would perform. Nested/overlapping cohorts — NOT extra trades, NOT a
# schema change, NOT a money-path change. Only populated up to DUAL_SIM_TEST_EDGE_MIN.
DUAL_SIM_DISPLAY_TIERS     = (70, 80, 90)
_DUAL_SIM_COOLDOWN          = {}                  # (mode,inst,direction) -> monotonic ts
_DUAL_SIM_COOLDOWN_LOCK     = threading.Lock()


def _check_dual_sim_db_ready():
    """Probe dual_sim_trades (no DDL) and set DUAL_SIM_DB_READY. FAIL-OPEN: a
    missing table / unavailable DB disables the dual-sim layer and never touches
    the rest of the bot."""
    global DUAL_SIM_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM dual_sim_trades LIMIT 1")
            cur.fetchone()
        DUAL_SIM_DB_READY = True
        logger.info("dual-mode shadow sim table ready")
    except Exception as exc:
        logger.warning("dual-mode shadow sim table unavailable (dual sim disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _shadow_strict_verdict(mode, *, current_price, active_ticker, vwap_value,
                           vwap_status, nearest_supply, nearest_demand, bullish,
                           bearish, confidence, volatility, session_state, edge_score,
                           learning_score_influence, cooldown_active):
    """PURE, side-effect-free replay of full_analysis's verdict pipeline for an
    EXPLICIT `mode`. Mirrors the live gate (strict setup -> swing_ctx -> trade plan
    -> SCALP veto -> SWING veto -> zone-broken/mitigated overrides), routed through
    the already-mode-parameterized building blocks so the shadow decision is faithful
    to what the live gate would decide in that mode. Reads only module globals
    (ALERT_HISTORY, ZONE_BROKEN_AT, MITIGATED_FLAG_BY_TICKER) and NEVER mutates
    anything. FAIL-CLOSED to WAIT on any error so a broken shadow can't fabricate an
    entry. Returns {verdict, direction, label, score, edge_score, reason, trade_plan,
    actionable}."""
    try:
        strict = evaluate_strict_setup(
            current_price, active_ticker, vwap_value, vwap_status,
            nearest_supply, nearest_demand, bullish, bearish, confidence, ALERT_HISTORY,
            volatility=volatility, session=session_state, cooldown_active=cooldown_active,
            learning_score_influence=learning_score_influence, mode=mode,
        )
        strict_label     = strict["label"]
        strict_direction = strict["direction"]
        strict_score     = strict["score"]
        strict_reason    = strict.get("reason", "")
        confluences      = strict.get("confluences", {}) or {}

        # SWING higher-timeframe context — only under this mode + flag-on (None in
        # SCALP/flag-off → the plan builder falls through to its 1:1 path and the SWING
        # veto never runs), exactly like the live gate.
        swing_ctx = None
        if _swing_htf_enabled(mode):
            try:
                swing_ctx = compute_swing_context(active_ticker, current_price)
            except Exception:
                swing_ctx = None

        verdict = "WAIT"
        trade_plan = {"trade_plan": False, "reason": strict_reason, "direction": strict_direction}
        if strict_label in ("Strong Trade", "Possible Trade") and strict_direction:
            tp = build_strict_trade_plan(
                strict_direction, active_ticker, current_price, nearest_supply, nearest_demand,
                volatility=volatility, mode=mode, vwap=vwap_value, edge_score=edge_score,
                swing_context=swing_ctx,
            )
            if tp.get("trade_plan"):
                trade_plan = tp
                _early = strict.get("readiness") == "EARLY"
                if strict_direction == "Long":
                    verdict = "LONG EARLY READY" if _early else "LONG READY"
                else:
                    verdict = "SHORT EARLY READY" if _early else "SHORT READY"
            else:
                verdict       = "WAIT"
                strict_reason = tp.get("reason", strict_reason)
        elif strict_label == "Setup Building" and strict.get("candidate"):
            verdict = "SETUP BUILDING"     # informational, NON-actionable

        # ── SCALP dynamic-exit ENTRY VETOES (mode-scoped) ─────────────────────────
        if _scalp_dynamic_enabled(mode) and is_actionable(verdict) and strict_direction:
            try:
                _sq = compute_scalp_quality(
                    strict_direction, current_price, vwap_value, vwap_status,
                    nearest_supply, nearest_demand, trade_plan, edge_score,
                    instrument_of(active_ticker), (volatility or {}).get("atr_pts"))
                _veto = _scalp_entry_veto_reasons(_sq)
            except Exception as exc:       # FAIL-CLOSED
                _veto = [("unavailable", f"SCALP entry checks unavailable ({exc})")]
            if _veto:
                verdict       = "WAIT"
                strict_reason = "SCALP filter: " + "; ".join(m for _, m in _veto) + "."
                trade_plan    = {"trade_plan": False, "reason": strict_reason,
                                 "direction": strict_direction}

        # ── SWING entry MONEY-PATH vetoes (mode-scoped) ───────────────────────────
        if _swing_htf_enabled(mode) and is_actionable(verdict) and strict_direction:
            try:
                _sv = _swing_entry_veto_reasons(swing_ctx, trade_plan, strict_direction)
            except Exception as exc:       # FAIL-CLOSED
                _sv = [("unavailable", f"SWING entry checks unavailable ({exc})")]
            if _sv:
                verdict       = "WAIT"
                strict_reason = "SWING filter: " + "; ".join(m for _, m in _sv) + "."
                trade_plan    = {"trade_plan": False, "reason": strict_reason,
                                 "direction": strict_direction}

        # ── Zone-broken / zone-mitigated overrides (mode-aware via GATE_REQUIRE_ZONE)
        # Pure read-only mirror of the live overrides so the shadow matches the live
        # verdict during a zone-broken/mitigated window. SWING hard-gates on zone;
        # SCALP demotes zone (GATE_REQUIRE_ZONE False) so this never fires there.
        if bool(cfg_for(mode, "GATE_REQUIRE_ZONE")) and is_actionable(verdict):
            inst = instrument_of(active_ticker)
            zone_broken_active = (
                ZONE_BROKEN_AT is not None
                and ZONE_BROKEN_AT.get("instrument") in (None, inst))
            if zone_broken_active:
                verdict       = "WAIT"
                strict_reason = "Structure invalidated — zone broken."
                trade_plan    = {"trade_plan": False, "reason": strict_reason, "direction": None}
            else:
                mitig_confirmed = bool(confluences.get("zone_mitigated"))
                near_sup_mz, _  = is_near_mitigated_zone(nearest_supply, inst, mode=mode, prune=False)
                near_dem_mz, _  = is_near_mitigated_zone(nearest_demand, inst, mode=mode, prune=False)
                if (MITIGATED_FLAG_BY_TICKER.get(inst) and (near_sup_mz or near_dem_mz)
                        and not mitig_confirmed):
                    verdict       = "WAIT"
                    strict_reason = "Zone consumed — wait for fresh supply or demand zone."
                    trade_plan    = {"trade_plan": False, "reason": strict_reason, "direction": None}

        actionable = bool(is_actionable(verdict))
        return {
            "verdict":    verdict,
            "direction":  strict_direction if actionable else trade_plan.get("direction"),
            "label":      strict_label,
            "score":      strict_score,
            "edge_score": edge_score,
            "reason":     strict_reason,
            "trade_plan": trade_plan,
            "actionable": actionable,
        }
    except Exception as exc:
        logger.warning("dual-sim shadow verdict (%s) failed: %s", mode, exc)
        return {"verdict": "WAIT", "direction": None, "label": "WAIT", "score": 0,
                "edge_score": edge_score, "reason": f"shadow error ({exc})",
                "trade_plan": {"trade_plan": False}, "actionable": False}


def _dual_sim_open_insert(sim_key, setup_anchor, mode, inst, direction, verdict,
                          entry, stop, target, rr, session, regime, edge):
    """Idempotent INSERT of an OPEN shadow paper trade. Skips a duplicate sim_key
    (same setup re-fired) or an already open/resolving trade for this
    (mode,inst,direction) — one shadow position per rulebook/instrument/direction at
    a time. Writes ONLY dual_sim_trades. INSERT/SELECT ONLY, FAIL-OPEN (returns False
    on any error)."""
    if not DUAL_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        ctx_json = psycopg2.extras.Json({
            "verdict": verdict, "session": session,
            "market_regime": regime, "edge_score": edge})
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM dual_sim_trades "
                "WHERE mode=%s AND symbol=%s AND direction=%s "
                "AND status IN ('open','resolving') LIMIT 1",
                (mode, inst, direction))
            if cur.fetchone():
                return False
            cur.execute(
                "INSERT INTO dual_sim_trades "
                "(sim_key, mode, symbol, direction, status, entry, stop, target, rr, "
                " verdict, session, market_regime, edge_score, setup_anchor, opened_at, "
                " entry_epoch, context) "
                "VALUES (%s,%s,%s,%s,'open',%s,%s,%s,%s,%s,%s,%s,%s,%s, now(), %s, %s) "
                "ON CONFLICT (sim_key) DO NOTHING",
                (sim_key, mode, inst, direction, entry, stop, target, rr, verdict,
                 session, regime, edge, setup_anchor, now_utc().timestamp(), ctx_json))
            inserted = (cur.rowcount == 1)
        conn.commit()
        return inserted
    except Exception as exc:
        logger.warning("dual-sim open insert failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _maybe_observe_dual_mode_sim(result, source="webhook"):
    """Passive ALWAYS-ON dual shadow observer. Opens ONE idempotent paper trade per
    (mode,inst,direction) for BOTH rulebooks whenever that mode is actionable with a
    real plan. The ACTIVE (live) mode replays the REAL FINAL decision verbatim from
    `result` (verdict + trade_plan), so it inherits every post-assembly live layer —
    the default-ON Entry Quality veto AND the sanctioned ORB 1:4 retarget — and can
    NEVER diverge from what the bot actually decided. The OTHER (non-live) mode is a
    pure gate-level "what-if" replay via _shadow_strict_verdict from the stashed
    inputs; the display-assembled layers (Entry Quality / ORB) are intentionally NOT
    mirrored there since they require a fully-assembled per-mode result that only the
    live path produces. Writes ONLY dual_sim_trades. NEVER touches the gate / verdict /
    trade_plan / edge_score / strategy_trades / MANAGED_TRADES / broker / auto-execute.
    Default OFF → flag OFF == byte-identical. FAIL-OPEN. Returns trades opened (tests)."""
    if not DUAL_MODE_SHADOW_SIM_ENABLED or source not in ("webhook", "databento_scan") or not DUAL_SIM_DB_READY:
        return 0
    # Never open shadow trades while the futures session is closed.
    try:
        if not market_session_status().get("open", True):
            return 0
    except Exception:
        pass
    inp = result.get("_dual_sim_inputs")
    if not isinstance(inp, dict):
        return 0
    inst = instrument_of(inp.get("active_ticker") or "")
    if not inst:
        return 0
    now_mono = time.monotonic()
    et_day   = now_utc().astimezone(ET_TZ).strftime("%Y%m%d")
    bucket   = int(now_utc().timestamp() // 300)   # 5-min idempotency bucket
    atr      = (inp.get("volatility") or {}).get("atr_pts") or 0.0
    opened    = 0
    # Use the mode snapshotted at analysis time (falls back to the live global for
    # safety) so a /mode flip between full_analysis() and here can't misroute the
    # active rulebook through the gate-level shadow and bypass the live EQ/ORB layers.
    live_mode = result.get("_dual_sim_live_mode") or TRADING_MODE
    for mode in DUAL_SIM_MODES:
        try:
            if mode == live_mode:
                # ACTIVE (live) mode: replay the REAL, FINAL decision verbatim. This is
                # the authoritative post-assembly verdict (inherits the default-ON Entry
                # Quality veto AND the sanctioned ORB 1:4 retarget), so the active-mode
                # ledger can NEVER diverge from what the bot actually decided live.
                verdict   = result.get("verdict")
                tp        = result.get("trade_plan") or {}
                direction = result.get("strict_direction") or tp.get("direction")
                edge_sc   = result.get("edge_score")
            else:
                # OTHER ("what-if") mode: pure gate-level replay (strict -> plan -> SCALP
                # veto -> SWING veto -> zone overrides). The display-assembled layers
                # (Entry Quality veto / ORB retarget) are intentionally NOT mirrored here
                # — they require the fully-assembled per-mode result, which exists only on
                # the live path. This is the non-live rulebook's gate verdict, never a
                # live decision.
                sv        = _shadow_strict_verdict(mode, **inp)
                verdict   = sv.get("verdict")
                tp        = sv.get("trade_plan") or {}
                direction = sv.get("direction")
                edge_sc   = sv.get("edge_score")
        except Exception:
            continue
        mgmt = tp.get("management") or {}
        entry  = mgmt.get("entry")
        stop   = mgmt.get("stop")
        target = mgmt.get("tp1")
        rr = tp.get("rr_num")

        should_open = bool(
            is_actionable(verdict) and direction
            and entry is not None and stop is not None and target is not None)

        # ── TEST trigger (flag-gated, default OFF ⇒ byte-identical) ────────────────
        # Open a paper trade whenever this mode's Edge Score clears the test threshold,
        # even if the live gate said WAIT. Build entry/stop/target from the setup's own
        # direction (via the same plan builder the gate uses) so the sim has a real plan
        # to track. DISPLAY-ONLY: the only write is still _dual_sim_open_insert below.
        if (not should_open) and DUAL_SIM_TEST_EDGE_MIN > 0 \
                and not is_actionable(verdict) and (edge_sc or 0) >= DUAL_SIM_TEST_EDGE_MIN:
            test_dir = direction
            if not test_dir:
                if inp.get("bullish") and not inp.get("bearish"):
                    test_dir = "Long"
                elif inp.get("bearish") and not inp.get("bullish"):
                    test_dir = "Short"
            if test_dir:
                try:
                    _sctx = None
                    if _swing_htf_enabled(mode):
                        try:
                            _sctx = compute_swing_context(
                                inp.get("active_ticker"), inp.get("current_price"))
                        except Exception:
                            _sctx = None
                    _tp = build_strict_trade_plan(
                        test_dir, inp.get("active_ticker"), inp.get("current_price"),
                        inp.get("nearest_supply"), inp.get("nearest_demand"),
                        volatility=inp.get("volatility"), mode=mode,
                        vwap=inp.get("vwap_value"), edge_score=edge_sc,
                        swing_context=_sctx)
                except Exception:
                    _tp = None
                _m = (_tp.get("management") or {}) if isinstance(_tp, dict) else {}
                if _tp and _tp.get("trade_plan") and _m.get("entry") is not None \
                        and _m.get("stop") is not None and _m.get("tp1") is not None:
                    direction = test_dir
                    entry, stop, target = _m["entry"], _m["stop"], _m["tp1"]
                    rr = _tp.get("rr_num")
                    verdict = "%s READY" % test_dir.upper()
                    should_open = True

        if not should_open:
            continue
        ckey = (mode, inst, direction)
        with _DUAL_SIM_COOLDOWN_LOCK:
            last = _DUAL_SIM_COOLDOWN.get(ckey)
            if last is not None and (now_mono - last) < DUAL_SIM_OPEN_COOLDOWN_SECS:
                continue
        price_bucket = (int(round(entry / (0.5 * atr))) if atr else int(round(entry)))
        setup_anchor = "%s:%d:%d" % (et_day, bucket, price_bucket)
        sim_key = "%s|%s|%s|%s" % (mode, inst, direction, setup_anchor)
        if _dual_sim_open_insert(sim_key, setup_anchor, mode, inst, direction,
                                 verdict, entry, stop, target, rr,
                                 _learning_session_name(), None, edge_sc):
            opened += 1
            with _DUAL_SIM_COOLDOWN_LOCK:
                _DUAL_SIM_COOLDOWN[ckey] = now_mono
    if opened:
        logger.info("dual-mode sim: opened %d shadow paper trade(s) on %s", opened, inst)
    return opened


def _dual_sim_outcome(row, bar):
    """Pure stop-first / then-target resolver for ONE open shadow trade against the
    latest bar. Returns (result_label, exit_price, r_multiple) or None. Worst-case
    fill (stop before target), identical to the scalp live-sim resolver."""
    high, low = bar.get("high"), bar.get("low")
    entry, stop, target = row.get("entry"), row.get("stop"), row.get("target")
    if None in (high, low, entry, stop, target):
        return None
    risk = abs(entry - stop)
    if risk <= 0:
        return None
    if row.get("direction") == "Long":
        if low <= stop:
            return ("loss", stop, round((stop - entry) / risk, 4))
        if high >= target:
            return ("win", target, round((target - entry) / risk, 4))
    else:
        if high >= stop:
            return ("loss", stop, round((entry - stop) / risk, 4))
        if low <= target:
            return ("win", target, round((entry - target) / risk, 4))
    return None


def _dual_sim_close(row_id, result_label, exit_price, r_multiple):
    """Atomically resolve one open shadow trade. The conditional `WHERE status IN
    ('open','resolving')` IS the cross-instance status claim — only the first writer
    closes it. Writes ONLY dual_sim_trades. FAIL-OPEN."""
    if not DUAL_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE dual_sim_trades "
                "SET status='closed', result=%s, exit_price=%s, r_multiple=%s, closed_at=now() "
                "WHERE id=%s AND status IN ('open','resolving')",
                (result_label, exit_price, r_multiple, row_id))
            claimed = (cur.rowcount == 1)
        conn.commit()
        return claimed
    except Exception as exc:
        logger.warning("dual-sim close failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _watch_dual_sim_trades():
    """Resolve OPEN shadow trades against the latest 1-minute bar (one fetch per
    instrument per cycle) — stop-first then target, ±R only, with the SAME-BAR guard
    (skip a bar opened at/before entry so a fresh trade can't self-fill). A trade past
    DUAL_SIM_MAX_HOLD_HOURS resolves at the latest close as 'expired'. Writes ONLY
    dual_sim_trades — never MANAGED_TRADES, strategy_trades, or the money path.
    FAIL-OPEN."""
    if not DUAL_SIM_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, symbol, direction, entry, stop, target, rr, entry_epoch, opened_at "
                "FROM dual_sim_trades WHERE status IN ('open','resolving') "
                "ORDER BY id ASC LIMIT 500")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "symbol": r[1], "direction": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "target": float(r[5]) if r[5] is not None else None,
                    "rr": float(r[6]) if r[6] is not None else 1.0,
                    "entry_epoch": float(r[7]) if r[7] is not None else None,
                    "opened_at": r[8]})
    except Exception as exc:
        logger.warning("dual-sim watcher read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not open_rows:
        return
    bars = {}
    for inst in {r["symbol"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    for row in open_rows:
        bar = bars.get(row["symbol"])
        if not bar:
            continue
        bar_start, entry_epoch = bar.get("start"), row.get("entry_epoch")
        if bar_start is not None and entry_epoch is not None and bar_start <= entry_epoch:
            continue                       # same-bar guard (no look-ahead self-fill)
        outcome = _dual_sim_outcome(row, bar)
        if outcome is None:
            # max-hold expiry — resolve a stranded shadow trade at the latest close.
            opened_at, cl = row.get("opened_at"), bar.get("close")
            if opened_at is not None and cl is not None and row.get("stop") is not None:
                try:
                    oa = opened_at if opened_at.tzinfo else opened_at.replace(tzinfo=timezone.utc)
                    aged = (now_utc() - oa).total_seconds() > DUAL_SIM_MAX_HOLD_HOURS * 3600
                except Exception:
                    aged = False
                risk = abs(row["entry"] - row["stop"])
                if aged and risk > 0:
                    r = ((cl - row["entry"]) / risk if row["direction"] == "Long"
                         else (row["entry"] - cl) / risk)
                    outcome = ("expired", round(cl, 4), round(r, 4))
        if outcome is None:
            continue
        _dual_sim_close(row["id"], outcome[0], outcome[1], outcome[2])


def _dual_sim_watch_loop():
    """Parallel shadow watcher on its own timer. Gated to the LIVE instance
    (DISCORD_LIVE_ENABLED) + flag ON + DB ready, single-flight via DUAL_SIM_WATCH_LOCK.
    FAIL-OPEN — any error just skips this cycle. Never touches the money path."""
    try:
        if DUAL_MODE_SHADOW_SIM_ENABLED and DISCORD_LIVE_ENABLED and DUAL_SIM_DB_READY:
            if DUAL_SIM_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_dual_sim_trades()
                finally:
                    DUAL_SIM_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("dual-sim watch loop error: %s", exc)
    finally:
        threading.Timer(DUAL_SIM_WATCH_INTERVAL, _dual_sim_watch_loop).start()


def _dual_sim_stats():
    """Per-mode shadow paper-sim stats from dual_sim_trades. DISPLAY-ONLY, FAIL-OPEN
    (returns {} on any error). Win-rate / avgR are over CLOSED win|loss trades; an
    'expired' (max-hold) trade counts toward net_r but not the win-rate denominator.
    Max-DD is the worst running trough across closed R. Includes a per-(mode,symbol)
    split so the dashboard can compare SCALP vs SWING per instrument."""
    out = {}
    if not DUAL_SIM_DB_READY:
        _check_dual_sim_db_ready()
    if not DUAL_SIM_DB_READY:
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT mode, symbol, status, result, r_multiple, closed_at, edge_score "
                "FROM dual_sim_trades "
                "ORDER BY closed_at ASC NULLS LAST, id ASC")
            rows = cur.fetchall()
    except Exception as exc:
        logger.warning("dual-sim stats read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass

    def _blank():
        return {"open": 0, "closed": 0, "wins": 0, "losses": 0, "r_list": [], "last_at": None}

    agg = {}      # mode -> bucket
    per_sym = {}  # (mode,symbol) -> bucket
    per_tier = {} # (mode,tier) -> bucket (edge-quality cohorts; overlapping/nested, display-only)
    for mode, symbol, status, result_label, r_mult, closed_at, edge_score in rows:
        try:
            es = float(edge_score) if edge_score is not None else None
        except (TypeError, ValueError):
            es = None
        tier_buckets = [per_tier.setdefault((mode, t), _blank())
                        for t in DUAL_SIM_DISPLAY_TIERS if es is not None and es >= t]
        for bkt in [agg.setdefault(mode, _blank()),
                    per_sym.setdefault((mode, symbol), _blank())] + tier_buckets:
            if status in ("open", "resolving"):
                bkt["open"] += 1
                continue
            bkt["closed"] += 1
            if r_mult is not None:
                bkt["r_list"].append(float(r_mult))
            if result_label == "win":
                bkt["wins"] += 1
            elif result_label == "loss":
                bkt["losses"] += 1
            if closed_at is not None:
                iso = closed_at.isoformat() if hasattr(closed_at, "isoformat") else str(closed_at)
                if bkt["last_at"] is None or iso > bkt["last_at"]:
                    bkt["last_at"] = iso

    def _summ(a):
        decided  = a["wins"] + a["losses"]
        win_rate = round(100.0 * a["wins"] / decided, 1) if decided else None
        avg_r    = round(sum(a["r_list"]) / len(a["r_list"]), 3) if a["r_list"] else None
        net_r    = round(sum(a["r_list"]), 2) if a["r_list"] else (0.0 if a["closed"] else None)
        dd = None
        if a["r_list"]:
            cum = peak = mdd = 0.0
            for r in a["r_list"]:
                cum += r
                peak = max(peak, cum)
                mdd = min(mdd, cum - peak)
            dd = round(mdd, 2)
        return {"trades": a["closed"], "open": a["open"], "win_rate": win_rate,
                "avg_r": avg_r, "net_r": net_r, "max_dd_r": dd, "last_at": a["last_at"]}

    for mode in DUAL_SIM_MODES:
        d = _summ(agg.get(mode) or _blank())
        d["by_symbol"] = {sym: _summ(s) for (mo, sym), s in per_sym.items() if mo == mode}
        d["by_threshold"] = {str(t): _summ(per_tier.get((mode, t)) or _blank())
                             for t in DUAL_SIM_DISPLAY_TIERS}
        out[mode] = d
    out["enabled"] = bool(DUAL_MODE_SHADOW_SIM_ENABLED)
    out["thresholds"] = list(DUAL_SIM_DISPLAY_TIERS)
    return out


def _scalp_sim_stats():
    """Per-strategy LIVE paper-sim stats from scalp_strategy_sim_trades. DISPLAY-
    ONLY, FAIL-OPEN (returns {} on any error). Win-rate / avgR are over CLOSED
    win|loss trades; an 'expired' (max-hold) trade counts toward net_r but not the
    win-rate denominator. Max-DD is the worst running trough across closed R."""
    out = {}
    if not SCALP_SIM_DB_READY:
        _check_scalp_sim_db_ready()
    if not SCALP_SIM_DB_READY:
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT strategy_key, status, result, r_multiple, fidelity, closed_at "
                "FROM scalp_strategy_sim_trades "
                "ORDER BY closed_at ASC NULLS LAST, id ASC")
            rows = cur.fetchall()
    except Exception as exc:
        logger.warning("scalp live-sim stats read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    agg = {}
    for strategy_key, status, result_label, r_mult, fidelity, closed_at in rows:
        a = agg.setdefault(strategy_key, {"open": 0, "closed": 0, "expired": 0,
                                          "wins": 0, "losses": 0,
                                          "r_list": [], "fidelity": None,
                                          "last_at": None})
        if fidelity and not a["fidelity"]:
            a["fidelity"] = fidelity
        if status in ("open", "resolving"):
            a["open"] += 1
            continue
        # Expired trades (max-hold timeout — no stop/target hit) are tracked
        # separately and excluded from every expectancy metric so they cannot
        # distort win_rate, avg_r, net_r, or the promotion threshold.
        if result_label == "expired":
            a["expired"] += 1
            continue
        a["closed"] += 1
        if r_mult is not None:
            a["r_list"].append(float(r_mult))
        if result_label == "win":
            a["wins"] += 1
        elif result_label == "loss":
            a["losses"] += 1
        if closed_at is not None:
            iso = closed_at.isoformat() if hasattr(closed_at, "isoformat") else str(closed_at)
            if a["last_at"] is None or iso > a["last_at"]:
                a["last_at"] = iso
    for key, a in agg.items():
        decided = a["wins"] + a["losses"]
        win_rate = round(100.0 * a["wins"] / decided, 1) if decided else None
        avg_r = round(sum(a["r_list"]) / len(a["r_list"]), 3) if a["r_list"] else None
        net_r = round(sum(a["r_list"]), 2) if a["r_list"] else (0.0 if a["closed"] else None)
        dd = None
        if a["r_list"]:
            cum = peak = 0.0
            mdd = 0.0
            for r in a["r_list"]:
                cum += r
                peak = max(peak, cum)
                mdd = min(mdd, cum - peak)
            dd = round(mdd, 2)
        out[key] = {"live_trades": a["closed"], "live_open": a["open"],
                    "live_expired": a["expired"],
                    "live_win_rate": win_rate, "live_avg_r": avg_r,
                    "live_net_r": net_r, "live_max_dd_r": dd,
                    "live_last_at": a["last_at"], "live_fidelity": a["fidelity"]}
    return out


def _augment_scalp_view_live(payload):
    """Fold LIVE paper-sim stats into the /scalp-research response (DISPLAY-ONLY).
    Adds a per-strategy `live_sim` block to tested / library / best / worst entries
    and gates the promotion recommendation on LIVE PROOF (>= SCALP_SIM_MIN_LIVE_PROMO
    closed live trades with positive expectancy). FAIL-OPEN: any error leaves the
    payload untouched. Mutates only the deep-copied collections in `payload`, never
    the cached research view."""
    try:
        payload["live_sim_enabled"]      = bool(SCALP_LIVE_SIM_ENABLED)
        payload["live_sim_min_promote"]  = SCALP_SIM_MIN_LIVE_PROMO
        stats = _scalp_sim_stats()
        payload["live_sim_ready"] = bool(stats)
        if not stats:
            return payload
        for coll in ("tested", "library", "best", "worst"):
            for e in (payload.get(coll) or []):
                k = e.get("strategy_key")
                if k and k in stats:
                    e["live_sim"] = stats[k]
        promos = payload.get("promotions")
        if isinstance(promos, list):
            for p in promos:
                ls = stats.get(p.get("strategy_key")) or {}
                lt   = ls.get("live_trades") or 0
                lwin = ls.get("live_win_rate")
                lavg = ls.get("live_avg_r")
                proven = (lt >= SCALP_SIM_MIN_LIVE_PROMO
                          and (lavg or 0) > 0 and (lwin or 0) >= 50)
                p["live_sim"]     = ls
                p["live_proven"]  = bool(proven)
                if not proven:
                    need = max(0, SCALP_SIM_MIN_LIVE_PROMO - lt)
                    p["recommendation"] = "KEEP SIMULATING \u2014 needs live proof"
                    p["reason"] = ("Research looks promising, but live paper proof is "
                                   "required before a human promotes it (%d live trades, "
                                   "need %d more)." % (lt, need))
    except Exception as exc:
        logger.warning("scalp live-sim view augment failed: %s", exc)
    return payload


# ════════════════════════════════════════════════════════════════════════════
# TradeZella journal import + review (owner-only, REVIEW-ONLY)
# ────────────────────────────────────────────────────────────────────────────
# Upload a TradeZella (or generic broker) trades CSV, persist the parsed rows,
# and surface a journal review (win rate, profit factor, expectancy, best/worst
# session/symbol/setup, common failure pattern, entry/exit heuristics). Like the
# backtest tools these routes are owner-gated by the Express dashboard auth (they
# are NOT in OPEN_PATHS) and FAIL-OPEN. NOTHING here ever feeds the strict gate,
# scoring, sizing, dedupe, Discord, or the /traderspost money path. App-side
# INSERT/SELECT ONLY — the tables are created out-of-band (database tool in dev,
# Publish schema-diff in prod), matching the journal / learning-engine convention.
# ════════════════════════════════════════════════════════════════════════════
try:
    import tradezella_engine as tz
    TRADEZELLA_AVAILABLE = True
except Exception as _tz_import_exc:   # pragma: no cover - defensive
    tz = None
    TRADEZELLA_AVAILABLE = False
    logger.warning("tradezella engine import failed (review disabled): %s", _tz_import_exc)

TRADEZELLA_DB_READY = False


def _check_tradezella_db_ready():
    """Probe the tradezella_trades table (NO DDL) and set TRADEZELLA_DB_READY.
    FAIL-OPEN: a missing table / unavailable DB leaves the flag False and the
    review degrades to 'no data' (upload returns 503 rather than silently losing
    rows)."""
    global TRADEZELLA_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM tradezella_trades LIMIT 1")
            cur.fetchone()
        TRADEZELLA_DB_READY = True
        logger.info("tradezella_trades table ready")
    except Exception as exc:
        logger.warning("tradezella table unavailable (import disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _persist_tradezella_trades(trades, filename=None):
    """Insert parsed TradeZella rows (ON CONFLICT DO NOTHING on dedupe_key) plus
    a batch-metadata row. SYNCHRONOUS (owner on-demand action, not the hot
    webhook path) so the upload response reports accurate imported/skipped counts
    and the follow-up analysis reads fresh data. FAIL-OPEN."""
    if not TRADEZELLA_DB_READY:
        return {"ok": False, "error": "database not ready"}
    conn = _learning_conn()
    if conn is None:
        return {"ok": False, "error": "database unavailable"}
    batch_id = uuid.uuid4().hex
    imported = 0
    auto_reviewed = 0
    try:
        with conn.cursor() as cur:
            for t in trades:
                row = (
                    batch_id, t.get("source") or "tradezella", t.get("dedupe_key"),
                    t.get("symbol"), t.get("side"), t.get("entry_time"),
                    t.get("exit_time"), t.get("entry_price"), t.get("exit_price"),
                    t.get("quantity"), t.get("pnl"), t.get("fees"), t.get("setup"),
                    t.get("mistake"), t.get("notes"), t.get("screenshots"),
                    t.get("mfe"), t.get("mae"), t.get("r_multiple"), t.get("mode"),
                    t.get("session_bucket"), t.get("session_day"), t.get("outcome"),
                    psycopg2.extras.Json(t.get("raw_row") or {}),
                )
                cur.execute(
                    "INSERT INTO tradezella_trades "
                    "(import_batch_id, source, dedupe_key, symbol, side, "
                    "entry_time, exit_time, entry_price, exit_price, quantity, "
                    "pnl, fees, setup, mistake, notes, screenshots, mfe, mae, "
                    "r_multiple, mode, session_bucket, session_day, outcome, "
                    "raw_row_json) VALUES "
                    "(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,"
                    "%s,%s,%s,%s,%s,%s) "
                    "ON CONFLICT (dedupe_key) DO NOTHING RETURNING id",
                    row,
                )
                row_result = cur.fetchone()
                if row_result is not None:
                    imported += 1
                    # Auto-seed a journal_reviews row from the trade's CSV fields.
                    # ON CONFLICT … WHERE review_status='UNREVIEWED' means existing
                    # manual reviews are NEVER overwritten on re-import.
                    new_trade_id = row_result[0]
                    try:
                        import tradezella_auto_seed as _tas
                        seed = _tas.auto_seed_review(t)
                        cur.execute(
                            "INSERT INTO journal_reviews"
                            " (source, trade_id, review_status, followed_plan,"
                            "  mistake_tags, positive_tags, emotion_tags,"
                            "  pre_trade_notes, post_trade_review,"
                            "  discipline_quality, overall_quality,"
                            "  execution_quality, reviewed_at,"
                            "  reviewed_by, updated_at)"
                            " VALUES ('tradzella',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'auto_seed',NOW())"
                            " ON CONFLICT (source, trade_id) DO UPDATE SET"
                            "  review_status     = EXCLUDED.review_status,"
                            "  followed_plan     = EXCLUDED.followed_plan,"
                            "  mistake_tags      = EXCLUDED.mistake_tags,"
                            "  positive_tags     = EXCLUDED.positive_tags,"
                            "  emotion_tags      = EXCLUDED.emotion_tags,"
                            "  pre_trade_notes   = EXCLUDED.pre_trade_notes,"
                            "  post_trade_review = EXCLUDED.post_trade_review,"
                            "  discipline_quality= EXCLUDED.discipline_quality,"
                            "  overall_quality   = EXCLUDED.overall_quality,"
                            "  execution_quality = EXCLUDED.execution_quality,"
                            "  reviewed_at       = EXCLUDED.reviewed_at,"
                            "  reviewed_by       = EXCLUDED.reviewed_by,"
                            "  updated_at        = EXCLUDED.updated_at"
                            " WHERE journal_reviews.review_status = 'UNREVIEWED'",
                            (
                                new_trade_id,
                                seed["review_status"],
                                seed["followed_plan"],
                                psycopg2.extras.Json(seed["mistake_tags"]),
                                psycopg2.extras.Json(seed["positive_tags"]),
                                psycopg2.extras.Json(seed["emotion_tags"]),
                                seed["pre_trade_notes"],
                                seed["post_trade_review"],
                                seed["discipline_quality"],
                                seed["overall_quality"],
                                seed["execution_quality"],
                                seed["reviewed_at"],
                            ),
                        )
                        if seed["review_status"] == "REVIEWED":
                            auto_reviewed += 1
                    except Exception:
                        pass  # fail-open: review row is not critical
                    # Task 83: run snapshot matching at import time (fail-open wrapper inside)
                    _run_match_at_import(conn, new_trade_id, t)
            skipped_dupes = len(trades) - imported
            cur.execute(
                "INSERT INTO tradezella_import_batches "
                "(import_batch_id, filename, source, row_count, imported_count, "
                "skipped_count) VALUES (%s,%s,%s,%s,%s,%s)",
                (batch_id, filename, "tradezella", len(trades), imported,
                 skipped_dupes),
            )
        return {"ok": True, "import_batch_id": batch_id, "imported": imported,
                "auto_reviewed": auto_reviewed,
                "skipped_dupes": skipped_dupes, "submitted": len(trades)}
    except Exception as exc:
        logger.warning("tradezella persist failed: %s", exc)
        return {"ok": False, "error": "persist failed"}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _run_match_at_import(conn, trade_id, tz_row):
    """Run snapshot matching for a newly-inserted TZ trade row.

    Queries internal_trade_snapshots in a ±30-min window around entry_time,
    runs the five-priority matching algorithm, and UPDATEs the trade row with
    match_confidence, matched_snapshot_id, strategy_source, learning_status,
    is_external_manual, and the snapshot-mirror fields.

    Convention: FAIL-OPEN.  Any error is caught + logged; the trade row is left
    with NULL match columns rather than aborting the import.  This function may
    open additional cursors on `conn` while the caller's own cursor is still open —
    this is safe in psycopg2 (multiple cursors share one transaction).
    """
    if not SNAPSHOTS_DB_READY:
        return
    try:
        import tradezella_matching as _tzm
    except ImportError:
        logger.warning("tradezella_matching module unavailable — skipping match")
        return
    try:
        from datetime import datetime as _dt2, timezone as _tz2, timedelta as _td2

        # ── Parse entry_time ─────────────────────────────────────────────────
        entry_raw = tz_row.get("entry_time")
        entry_dt = None
        if entry_raw is not None:
            if isinstance(entry_raw, str):
                try:
                    entry_dt = _dt2.fromisoformat(entry_raw.replace("Z", "+00:00"))
                    if entry_dt.tzinfo is None:
                        entry_dt = entry_dt.replace(tzinfo=_tz2.utc)
                except Exception:
                    entry_dt = None
            elif hasattr(entry_raw, "tzinfo"):
                entry_dt = entry_raw
                if entry_dt.tzinfo is None:
                    entry_dt = entry_dt.replace(tzinfo=_tz2.utc)

        # ── Fetch candidate snapshots (±30-min window) ───────────────────────
        # 30 min covers the 5-min time-match tiers AND the 30-min external-manual check.
        snaps: list = []
        if entry_dt is not None:
            lo = entry_dt - _td2(minutes=30)
            hi = entry_dt + _td2(minutes=30)
            with conn.cursor() as _qcur:
                _qcur.execute(
                    "SELECT id, canonical_strategy_key, strategy_display_name,"
                    " thesis_direction, thesis_strength, thesis_alignment,"
                    " edge_score, grade, planned_entry, planned_stop, planned_risk,"
                    " planned_targets, planned_contracts, instrument, direction,"
                    " broker_order_id, execution_fingerprint, sent_at, created_at"
                    " FROM internal_trade_snapshots"
                    " WHERE (sent_at BETWEEN %s AND %s)"
                    "    OR (sent_at IS NULL AND created_at BETWEEN %s AND %s)"
                    " LIMIT 50",
                    (lo, hi, lo, hi),
                )
                _snap_cols = [d[0] for d in _qcur.description]
                for _r in _qcur.fetchall():
                    _sd = dict(zip(_snap_cols, _r))
                    for _k, _v in _sd.items():
                        if hasattr(_v, "isoformat"):
                            _sd[_k] = _v.isoformat()
                        elif _v is not None and type(_v).__name__ == "UUID":
                            _sd[_k] = str(_v)
                    snaps.append(_sd)

        # ── Run matching + external-manual detection ──────────────────────────
        match = _tzm.match_tradezella_trade(tz_row, snaps)
        is_ext = _tzm.is_external_manual(tz_row, snaps)

        # ── Determine strategy_source ────────────────────────────────────────
        if match.confidence in (_tzm.CONFIDENCE_EXACT, _tzm.CONFIDENCE_HIGH):
            _ss = _tzm.STRATEGY_SOURCE_SYSTEM
        elif is_ext:
            _ss = _tzm.STRATEGY_SOURCE_IMPORTED
        else:
            _ss = _tzm.STRATEGY_SOURCE_UNMATCHED

        # ── Compute learning_status ──────────────────────────────────────────
        _tz_ctx = dict(tz_row)
        _tz_ctx["strategy_source"] = _ss
        _ls = _tzm.compute_learning_status(match, _tz_ctx)

        # ── Write match results back to tradezella_trades ────────────────────
        with conn.cursor() as _ucur:
            _ucur.execute(
                "UPDATE tradezella_trades SET"
                "  matched_snapshot_id  = %s,"
                "  match_method         = %s,"
                "  match_confidence     = %s,"
                "  candidate_count      = %s,"
                "  match_notes          = %s,"
                "  strategy_source      = %s,"
                "  learning_status      = %s,"
                "  is_external_manual   = %s,"
                "  snap_strategy_key    = %s,"
                "  snap_strategy        = %s,"
                "  snap_thesis_direction = %s,"
                "  snap_thesis_strength  = %s,"
                "  snap_thesis_alignment = %s,"
                "  snap_edge_score      = %s,"
                "  snap_grade           = %s,"
                "  snap_planned_entry   = %s,"
                "  snap_planned_stop    = %s,"
                "  snap_planned_risk    = %s,"
                "  snap_planned_targets = %s"
                " WHERE id = %s",
                (
                    match.snapshot_id,
                    match.method,
                    match.confidence,
                    match.candidate_count,
                    (match.notes or "")[:500] or None,
                    _ss,
                    _ls,
                    is_ext,
                    match.snap_strategy_key,
                    match.snap_strategy,
                    match.snap_thesis_direction,
                    match.snap_thesis_strength,
                    match.snap_thesis_alignment,
                    match.snap_edge_score,
                    match.snap_grade,
                    match.snap_planned_entry,
                    match.snap_planned_stop,
                    match.snap_planned_risk,
                    psycopg2.extras.Json(match.snap_planned_targets)
                    if match.snap_planned_targets else None,
                    trade_id,
                ),
            )
    except Exception as _me:
        logger.warning("_run_match_at_import trade_id=%s: %s", trade_id, _me)


def _reset_tradezella_trades():
    """Delete ALL imported TradeZella journal rows + their import-batch metadata so
    the owner can start a clean review. REVIEW-ONLY DML: these are the app's OWN
    private journal tables, never live trading tables, so clearing them only affects
    the display review + the down-weighted 'tradezella' memory source (it never
    touches live trades, scoring, sizing, or the broker). Autocommit conn. FAIL-OPEN."""
    if not TRADEZELLA_DB_READY:
        return {"ok": False, "error": "database not ready"}
    conn = _learning_conn()
    if conn is None:
        return {"ok": False, "error": "database unavailable"}
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM tradezella_trades")
            deleted = cur.rowcount if (cur.rowcount and cur.rowcount > 0) else 0
            cur.execute("DELETE FROM tradezella_import_batches")
        return {"ok": True, "deleted": deleted}
    except Exception as exc:
        logger.warning("tradezella reset failed: %s", exc)
        return {"ok": False, "error": "reset failed"}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _load_tradezella_trades(limit=5000):
    """Load persisted TradeZella trades (newest-first) as canonical dicts for
    analyze_journal. FAIL-OPEN -> [] on any error."""
    if not TRADEZELLA_DB_READY:
        return []
    conn = _learning_conn()
    if conn is None:
        return []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT symbol, side, entry_time, exit_time, entry_price, "
                "exit_price, quantity, pnl, fees, setup, mistake, notes, "
                "screenshots, mfe, mae, r_multiple, mode, session_bucket, "
                "session_day, outcome FROM tradezella_trades "
                "ORDER BY entry_time DESC NULLS LAST, id DESC LIMIT %s",
                (int(limit),),
            )
            rows = cur.fetchall()
        keys = ("symbol", "side", "entry_time", "exit_time", "entry_price",
                "exit_price", "quantity", "pnl", "fees", "setup", "mistake",
                "notes", "screenshots", "mfe", "mae", "r_multiple", "mode",
                "session_bucket", "session_day", "outcome")
        out = []
        for r in rows:
            d = dict(zip(keys, r))
            for tk in ("entry_time", "exit_time", "session_day"):
                if d.get(tk) is not None and hasattr(d[tk], "isoformat"):
                    d[tk] = d[tk].isoformat()
            out.append(d)
        return out
    except Exception as exc:
        logger.warning("tradezella load failed: %s", exc)
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _tz_memory_records(max_rows=TRADEZELLA_MEMORY_MAX, start_rank=0):
    """Map imported TradeZella journal trades into the find_similar_trades record shape
    (DOWN-WEIGHTED 'tradezella' source). Decided (win/loss) trades only -- scratches are
    excluded so the weighted win-rate stays meaningful. The 'session' dim is RE-DERIVED
    with the LIVE _learning_session_name vocabulary (not the journal's display bucket) so
    it can actually match a live setup. Dimensions the journal lacks (strategy_key/regime/
    volatility/grade/edge/bias) stay None -> they simply never match. MFE/MAE are LEFT
    None: the journal's raw mfe/mae columns are of unknown units and must not pollute the
    R-based excursion averages. Ranks continue AFTER the live trades (start_rank) so the
    journal can never occupy the top recency tier ahead of the bot's own trades. The caller
    appends these AFTER the live cache, so they also never evict a live trade. FAIL-OPEN -> []."""
    if not TRADEZELLA_DB_READY:
        return []
    try:
        raw = _load_tradezella_trades(limit=max(int(max_rows) * 4, int(max_rows)))
    except Exception:
        return []

    def _ff(v):
        try:
            return float(v) if v is not None else None
        except Exception:
            return None

    decided = []
    for t in (raw or []):
        if t.get("outcome") not in ("win", "loss"):
            continue
        sym = instrument_of(t.get("symbol") or "") or (t.get("symbol") or "")
        if not sym:
            continue
        edt = xdt = None
        try:
            if t.get("entry_time"):
                edt = datetime.fromisoformat(t["entry_time"])
        except Exception:
            edt = None
        try:
            if t.get("exit_time"):
                xdt = datetime.fromisoformat(t["exit_time"])
        except Exception:
            xdt = None
        sess = _learning_session_name(edt) if edt is not None else None
        hold_min = None
        if edt is not None and xdt is not None:
            try:
                hm = (xdt - edt).total_seconds() / 60.0
                hold_min = round(hm, 1) if hm > 0 else None
            except Exception:
                hold_min = None
        mode = (t.get("mode") or "").strip().upper() or None
        rec = {
            "symbol":           sym,
            "direction":        _norm_dir(t.get("side")),
            "regime":           None,
            "session":          sess,
            "volatility_type":  None,
            "entry_efficiency": None,
            "strategy_key":     None,                     # never creates a scored strategy match
            "strategy":         t.get("setup"),           # display label only
            "result":           "Win" if t.get("outcome") == "win" else "Loss",
            "r_multiple":       _ff(t.get("r_multiple")),
            "mfe_r":            None,                      # unknown units -> excluded from R averages
            "mae_r":            None,
            "hold_minutes":     hold_min,
            "outcome_tag":      None,
            "edge_score":       None,
            "bias":             None,
            "grade":            None,
            "trading_mode":     mode if mode in ("SCALP", "SWING") else None,
            "strategy_version": None,                     # unknown logic version -> version weight 0.2
            "source":           "tradezella",             # external journal -> source weight 0.25
            "rank":             0,                         # assigned below (after the live trades)
        }
        decided.append((xdt, rec))

    def _key(p):
        try:
            return p[0].timestamp() if p[0] is not None else float("-inf")
        except Exception:
            return float("-inf")
    decided.sort(key=_key, reverse=True)        # most-recently CLOSED first; undated sink last

    out = []
    for i, (_xdt, rec) in enumerate(decided[:int(max_rows)]):
        rec["rank"] = int(start_rank) + i + 1
        out.append(rec)
    return out


def _tradezella_import_summary():
    """{imported_total, last_import_at, batch_count} from the batch table. FAIL-OPEN."""
    summary = {"imported_total": 0, "last_import_at": None, "batch_count": 0}
    if not TRADEZELLA_DB_READY:
        return summary
    conn = _learning_conn()
    if conn is None:
        return summary
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) FROM tradezella_trades")
            summary["imported_total"] = int(cur.fetchone()[0] or 0)
            cur.execute("SELECT COUNT(*), MAX(created_at) FROM tradezella_import_batches")
            row = cur.fetchone()
            summary["batch_count"] = int(row[0] or 0)
            summary["last_import_at"] = row[1].isoformat() if row and row[1] else None
    except Exception as exc:
        logger.warning("tradezella summary failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return summary


def _tradezella_scoreboard(trades):
    """Compact REAL-account scoreboard from imported TradeZella / broker trades for the
    dashboard 'Real Account Results' panel. DISPLAY-ONLY / fail-open -> safe empty shape.
    'today' is keyed on the ET session day. Decided (win/loss) rows drive win-rate; net
    P&L sums every row's net pnl. NEVER touches the gate, sizing, dedupe or the broker."""
    def _blank():
        return {"count": 0, "decided": 0, "wins": 0, "losses": 0,
                "win_rate": None, "net_pnl": 0.0}
    out = {"all_time": _blank(), "today": _blank(),
           "by_instrument": [], "by_instrument_today": [], "today_et": None}
    try:
        today_et = now_utc().astimezone(ET_TZ).date().isoformat()
        out["today_et"] = today_et

        def _accum(bucket, t):
            bucket["count"] += 1
            pnl = t.get("pnl")
            try:
                bucket["net_pnl"] += float(pnl) if pnl is not None else 0.0
            except (TypeError, ValueError):
                pass
            oc = (t.get("outcome") or "").strip().lower()
            if oc == "win":
                bucket["decided"] += 1
                bucket["wins"] += 1
            elif oc == "loss":
                bucket["decided"] += 1
                bucket["losses"] += 1

        # Per-instrument breakdown is built for BOTH scopes (all-time + today) so the
        # dashboard's Today / All-imported toggle switches the per-instrument list too,
        # not just the four summary stats. DISPLAY-ONLY.
        per = {}
        per_today = {}
        for t in (trades or []):
            if not isinstance(t, dict):
                continue
            _accum(out["all_time"], t)
            sym = ((t.get("symbol") or "?").strip().upper()) or "?"
            g = per.get(sym)
            if g is None:
                g = _blank()
                g["symbol"] = sym
                per[sym] = g
            _accum(g, t)
            sd = str(t.get("session_day") or "")[:10]
            if sd and sd == today_et:
                _accum(out["today"], t)
                gt = per_today.get(sym)
                if gt is None:
                    gt = _blank()
                    gt["symbol"] = sym
                    per_today[sym] = gt
                _accum(gt, t)

        for b in ([out["all_time"], out["today"]]
                  + list(per.values()) + list(per_today.values())):
            b["win_rate"] = (b["wins"] / b["decided"]) if b["decided"] else None
            b["net_pnl"] = round(b["net_pnl"], 2)
        out["by_instrument"] = sorted(per.values(), key=lambda g: g["net_pnl"])
        out["by_instrument_today"] = sorted(
            per_today.values(), key=lambda g: g["net_pnl"])
    except Exception as exc:
        logger.warning("tradezella scoreboard failed: %s", exc)
    return out


def _tz_guard():
    """None when TradeZella review is usable, else a (json, status) error tuple."""
    if not TRADEZELLA_AVAILABLE:
        return jsonify({"ok": False, "error": "TradeZella engine unavailable."}), 503
    if not LEARNING_DB_ENABLED:
        return jsonify({"ok": False, "error": "Database not configured — review disabled."}), 503
    return None


@app.route("/tradezella/upload", methods=["POST"])
def tradezella_upload():
    """Owner-only. Body = raw TradeZella trades CSV text; query: tz, filename."""
    guard = _tz_guard()
    if guard:
        return guard
    if not TRADEZELLA_DB_READY:
        _check_tradezella_db_ready()
    if not TRADEZELLA_DB_READY:
        return jsonify({"ok": False,
                        "error": "TradeZella table not provisioned yet."}), 503
    source_tz = request.args.get("tz") or "America/New_York"
    filename = request.args.get("filename") or None
    try:
        source_zone = ZoneInfo(source_tz)
    except Exception:
        return jsonify({"ok": False, "error": f"unknown timezone '{source_tz}'"}), 400
    raw = request.get_data(cache=False, as_text=True)
    if not raw or not raw.strip():
        return jsonify({"ok": False, "error": "empty upload body"}), 400
    try:
        parsed = tz.parse_tradezella_csv(raw, source_tz=source_zone)
    except Exception as exc:
        logger.warning("tradezella parse failed: %s", exc)
        return jsonify({"ok": False, "error": "could not parse CSV"}), 400
    if not parsed.get("ok"):
        return jsonify({"ok": False, "error": parsed.get("error", "parse error")}), 400
    if not parsed.get("trades"):
        return jsonify({"ok": False,
                        "error": "no usable trade rows found in CSV",
                        "columns": parsed.get("columns", [])}), 400
    stored = _persist_tradezella_trades(parsed["trades"], filename=filename)
    if not stored.get("ok"):
        return jsonify(stored), 500
    return jsonify({
        "ok": True,
        "import_batch_id": stored["import_batch_id"],
        "imported": stored["imported"],
        "skipped_dupes": stored["skipped_dupes"],
        "parsed_rows": parsed["row_count"],
        "parse_skipped": parsed["skipped"],
        "fields_present": parsed["fields_present"],
        "warnings": parsed.get("warnings", []),
    })


@app.route("/tradezella/analysis", methods=["GET"])
def tradezella_analysis():
    """Owner-only. Returns the journal review over all imported trades."""
    guard = _tz_guard()
    if guard:
        return guard
    if not TRADEZELLA_DB_READY:
        _check_tradezella_db_ready()
    trades = _load_tradezella_trades()
    try:
        analysis = tz.analyze_journal(trades)
    except Exception as exc:
        logger.warning("tradezella analyze failed: %s", exc)
        return jsonify({"ok": False, "error": "analysis failed"}), 500
    # DISPLAY-ONLY entry-quality + exit-management reviews folded off the analysis
    # (fail-open — a presenter error must never break the analysis payload).
    try:
        analysis["reviews"] = tz.build_reviews(analysis)
    except Exception as exc:
        logger.warning("tradezella reviews failed: %s", exc)
    return jsonify({
        "ok": True,
        "db_ready": TRADEZELLA_DB_READY,
        "import_summary": _tradezella_import_summary(),
        "scoreboard": _tradezella_scoreboard(trades),
        "analysis": analysis,
    })


