def _review_is_complete(row):
    """True when minimum required fields are set for REVIEWED status."""
    if not row.get("followed_plan"):
        return False
    if not row.get("overall_quality"):
        return False
    if not (row.get("post_trade_review") or "").strip():
        return False
    lesson   = (row.get("lesson_learned") or "").strip()
    pos_tags = row.get("positive_tags") or []
    mis_tags = row.get("mistake_tags") or []
    return bool(lesson or pos_tags or mis_tags)


def _review_needs_data(source, trade_id, conn):
    """True if trade is missing execution truth required before learning."""
    try:
        with conn.cursor() as cur:
            if source == "system":
                cur.execute(
                    "SELECT entry, strategy_key, result"
                    " FROM strategy_trades WHERE id = %s",
                    (trade_id,),
                )
                row = cur.fetchone()
                if row is None:
                    return True
                entry, sk, result = row
                return not entry or not sk or not result
            elif source == "tradzella":
                cur.execute(
                    "SELECT entry_price, outcome"
                    " FROM tradezella_trades WHERE id = %s",
                    (trade_id,),
                )
                row = cur.fetchone()
                if row is None:
                    return True
                entry_price, outcome = row
                return not entry_price or not outcome
    except Exception:
        pass  # fail-open
    return False


def _get_or_default_review(conn, source, trade_id):
    """Return the existing journal_reviews row or UNREVIEWED defaults dict."""
    _KEYS = (
        "review_status", "followed_plan", "plan_checklist", "mistake_tags",
        "positive_tags", "emotion_tags", "pre_trade_notes", "in_trade_notes",
        "post_trade_review", "lesson_learned", "what_differently", "what_repeat",
        "setup_quality", "execution_quality", "discipline_quality",
        "overall_quality", "exclude_reason", "reviewed_at", "reviewed_by",
        "updated_at",
    )
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT review_status, followed_plan, plan_checklist, mistake_tags,"
                " positive_tags, emotion_tags, pre_trade_notes, in_trade_notes,"
                " post_trade_review, lesson_learned, what_differently, what_repeat,"
                " setup_quality, execution_quality, discipline_quality, overall_quality,"
                " exclude_reason, reviewed_at, reviewed_by, updated_at"
                " FROM journal_reviews WHERE source = %s AND trade_id = %s",
                (source, trade_id),
            )
            row = cur.fetchone()
    except Exception:
        row = None
    if row is None:
        return {k: None for k in _KEYS} | {
            "review_status": "UNREVIEWED", "reviewed_by": "operator",
        }
    d = dict(zip(_KEYS, row))
    for k in ("reviewed_at", "updated_at"):
        if d.get(k) and hasattr(d[k], "isoformat"):
            d[k] = d[k].isoformat()
    return d


@app.route("/journal/trade/<source>/<int:trade_id>/review", methods=["GET"])
def journal_trade_review_get(source, trade_id):
    """Fetch the review row for a trade, or return UNREVIEWED defaults."""
    if source not in ("system", "tradzella"):
        return jsonify({"ok": False, "error": f"unknown source '{source}'"}), 400
    conn, err = _journal_db_guard()
    if err:
        return err
    try:
        review = _get_or_default_review(conn, source, trade_id)
        return jsonify({
            "ok": True,
            "review": review,
            "vocabulary": {
                "mistake_tags":   sorted(REVIEW_MISTAKE_TAGS),
                "positive_tags":  sorted(REVIEW_POSITIVE_TAGS),
                "emotion_tags":   sorted(REVIEW_EMOTION_TAGS),
                "followed_plan":  sorted(REVIEW_FOLLOWED_PLAN_VALUES),
                "plan_checklist": REVIEW_PLAN_CHECKLIST_ITEMS,
            },
        })
    except Exception as exc:
        logger.warning("journal_trade_review_get failed: %s", exc)
        return jsonify({"ok": False, "error": "query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/journal/trade/<source>/<int:trade_id>/review", methods=["PATCH"])
def journal_trade_review_patch(source, trade_id):
    """Upsert review fields. Validates controlled vocabulary. Auto-computes status."""
    if source not in ("system", "tradzella"):
        return jsonify({"ok": False, "error": f"unknown source '{source}'"}), 400
    conn, err = _journal_db_guard()
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}

    # ── Validate followed_plan ───────────────────────────────────────────────
    followed_plan = data.get("followed_plan")
    if followed_plan is not None and followed_plan not in REVIEW_FOLLOWED_PLAN_VALUES:
        return jsonify({"ok": False,
                        "error": f"invalid followed_plan '{followed_plan}'"}), 400

    # ── Validate tag arrays ──────────────────────────────────────────────────
    def _validate_tags(field, vocab):
        raw = data.get(field)
        if raw is None:
            return None, None
        if not isinstance(raw, list):
            return None, f"'{field}' must be a list"
        deduped = list(dict.fromkeys(raw))        # preserve order, remove dupes
        known   = [t for t in deduped if t in vocab]
        custom  = [t for t in deduped if t not in vocab and str(t).startswith("custom:")]
        unknown = [t for t in deduped if t not in vocab and not str(t).startswith("custom:")]
        if unknown:
            return None, f"unknown {field}: {unknown[:3]}"
        return known + custom, None

    mistake_tags,  err_mt = _validate_tags("mistake_tags",  REVIEW_MISTAKE_TAGS)
    if err_mt:
        return jsonify({"ok": False, "error": err_mt}), 400
    positive_tags, err_pt = _validate_tags("positive_tags", REVIEW_POSITIVE_TAGS)
    if err_pt:
        return jsonify({"ok": False, "error": err_pt}), 400

    # Emotion tags: list of str or {tag, intensity}
    emotion_tags_raw = data.get("emotion_tags")
    emotion_tags = None
    if emotion_tags_raw is not None:
        if not isinstance(emotion_tags_raw, list):
            return jsonify({"ok": False, "error": "'emotion_tags' must be a list"}), 400
        seen_tags: set = set()
        valid_et = []
        for et in emotion_tags_raw:
            tag = et if isinstance(et, str) else (et.get("tag") if isinstance(et, dict) else None)
            if not tag or tag not in REVIEW_EMOTION_TAGS:
                return jsonify({"ok": False,
                                "error": f"unknown emotion_tag '{tag}'"}), 400
            if tag in seen_tags:
                continue  # dedupe
            seen_tags.add(tag)
            intensity = None
            if isinstance(et, dict):
                intensity = et.get("intensity")
                if intensity is not None:
                    try:
                        intensity = int(intensity)
                        if not 1 <= intensity <= 5:
                            raise ValueError
                    except (TypeError, ValueError):
                        return jsonify({"ok": False,
                                        "error": "emotion intensity must be 1–5"}), 400
            valid_et.append({"tag": tag, "intensity": intensity})
        emotion_tags = valid_et

    # ── Validate ratings 1–5 ────────────────────────────────────────────────
    rating_vals = {}
    for field in ("setup_quality", "execution_quality",
                  "discipline_quality", "overall_quality"):
        v = data.get(field)
        if v is not None:
            try:
                v = int(v)
                if not 1 <= v <= 5:
                    raise ValueError
            except (TypeError, ValueError):
                return jsonify({"ok": False,
                                "error": f"'{field}' must be 1–5"}), 400
            rating_vals[field] = v

    # ── Validate plan_checklist ──────────────────────────────────────────────
    plan_checklist = data.get("plan_checklist")
    if plan_checklist is not None:
        if not isinstance(plan_checklist, dict):
            return jsonify({"ok": False, "error": "'plan_checklist' must be a dict"}), 400
        bad = [k for k in plan_checklist if k not in REVIEW_PLAN_CHECKLIST_ITEMS]
        if bad:
            return jsonify({"ok": False,
                            "error": f"unknown checklist items: {bad[:3]}"}), 400

    # ── Fetch current row; guard EXCLUDED ───────────────────────────────────
    existing = _get_or_default_review(conn, source, trade_id)
    if existing.get("review_status") == "EXCLUDED":
        return jsonify({"ok": False,
                        "error": "trade is EXCLUDED — use /exclude to change status"}), 409

    # ── Merge with existing ──────────────────────────────────────────────────
    def _merge(field, new_val, old_val):
        return new_val if new_val is not None else old_val

    def _merge_text(field):
        v = (data.get(field) or "").strip()
        return v if v else existing.get(field)

    merged = {
        "followed_plan":     followed_plan  if followed_plan  is not None else existing.get("followed_plan"),
        "plan_checklist":    plan_checklist if plan_checklist is not None else existing.get("plan_checklist"),
        "mistake_tags":      mistake_tags   if mistake_tags   is not None else existing.get("mistake_tags"),
        "positive_tags":     positive_tags  if positive_tags  is not None else existing.get("positive_tags"),
        "emotion_tags":      emotion_tags   if emotion_tags   is not None else existing.get("emotion_tags"),
        "pre_trade_notes":   _merge_text("pre_trade_notes"),
        "in_trade_notes":    _merge_text("in_trade_notes"),
        "post_trade_review": _merge_text("post_trade_review"),
        "lesson_learned":    _merge_text("lesson_learned"),
        "what_differently":  _merge_text("what_differently"),
        "what_repeat":       _merge_text("what_repeat"),
        "setup_quality":     rating_vals.get("setup_quality",     existing.get("setup_quality")),
        "execution_quality": rating_vals.get("execution_quality", existing.get("execution_quality")),
        "discipline_quality":rating_vals.get("discipline_quality",existing.get("discipline_quality")),
        "overall_quality":   rating_vals.get("overall_quality",   existing.get("overall_quality")),
    }

    # ── Auto-compute review_status ───────────────────────────────────────────
    explicit_status = data.get("review_status")
    if explicit_status == "REVIEWED":
        if not _review_is_complete(merged):
            return jsonify({"ok": False,
                            "error": "Cannot mark REVIEWED — set followed_plan, "
                                     "overall_quality, post_trade_review and at least "
                                     "one tag or lesson."}), 400
        new_status = "REVIEWED"
    elif explicit_status in REVIEW_STATUS_VALUES and explicit_status != "EXCLUDED":
        new_status = explicit_status
    elif _review_is_complete(merged):
        new_status = "REVIEWED"
    elif any(
        v is not None and v != [] and v != ""
        for v in merged.values()
    ):
        new_status = "IN_PROGRESS"
    else:
        new_status = "UNREVIEWED"

    # NEEDS_DATA overrides IN_PROGRESS/REVIEWED when execution truth is missing
    if new_status in ("IN_PROGRESS", "REVIEWED") and _review_needs_data(source, trade_id, conn):
        new_status = "NEEDS_DATA"

    now_ts      = datetime.now(timezone.utc)
    reviewed_at = now_ts.isoformat() if new_status == "REVIEWED" else (
        existing.get("reviewed_at") if existing.get("review_status") == "REVIEWED" else None
    )

    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO journal_reviews"
                " (source, trade_id, review_status, followed_plan, plan_checklist,"
                "  mistake_tags, positive_tags, emotion_tags, pre_trade_notes,"
                "  in_trade_notes, post_trade_review, lesson_learned, what_differently,"
                "  what_repeat, setup_quality, execution_quality, discipline_quality,"
                "  overall_quality, reviewed_at, reviewed_by, updated_at)"
                " VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)"
                " ON CONFLICT (source, trade_id) DO UPDATE SET"
                "  review_status    = EXCLUDED.review_status,"
                "  followed_plan    = EXCLUDED.followed_plan,"
                "  plan_checklist   = EXCLUDED.plan_checklist,"
                "  mistake_tags     = EXCLUDED.mistake_tags,"
                "  positive_tags    = EXCLUDED.positive_tags,"
                "  emotion_tags     = EXCLUDED.emotion_tags,"
                "  pre_trade_notes  = EXCLUDED.pre_trade_notes,"
                "  in_trade_notes   = EXCLUDED.in_trade_notes,"
                "  post_trade_review= EXCLUDED.post_trade_review,"
                "  lesson_learned   = EXCLUDED.lesson_learned,"
                "  what_differently = EXCLUDED.what_differently,"
                "  what_repeat      = EXCLUDED.what_repeat,"
                "  setup_quality    = EXCLUDED.setup_quality,"
                "  execution_quality= EXCLUDED.execution_quality,"
                "  discipline_quality=EXCLUDED.discipline_quality,"
                "  overall_quality  = EXCLUDED.overall_quality,"
                "  reviewed_at      = EXCLUDED.reviewed_at,"
                "  reviewed_by      = EXCLUDED.reviewed_by,"
                "  updated_at       = EXCLUDED.updated_at"
                " RETURNING id",
                (
                    source, trade_id, new_status,
                    merged["followed_plan"],
                    psycopg2.extras.Json(merged["plan_checklist"]),
                    psycopg2.extras.Json(merged["mistake_tags"]),
                    psycopg2.extras.Json(merged["positive_tags"]),
                    psycopg2.extras.Json(merged["emotion_tags"]),
                    merged["pre_trade_notes"], merged["in_trade_notes"],
                    merged["post_trade_review"], merged["lesson_learned"],
                    merged["what_differently"], merged["what_repeat"],
                    merged["setup_quality"], merged["execution_quality"],
                    merged["discipline_quality"], merged["overall_quality"],
                    reviewed_at, "operator", now_ts,
                ),
            )
        return jsonify({
            "ok": True, "review_status": new_status, "reviewed_at": reviewed_at,
        })
    except Exception as exc:
        logger.warning("journal_trade_review_patch failed: %s", exc)
        return jsonify({"ok": False, "error": "update failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/journal/trade/<source>/<int:trade_id>/exclude", methods=["POST"])
def journal_trade_exclude(source, trade_id):
    """Set a trade to EXCLUDED status with a mandatory reason."""
    if source not in ("system", "tradzella"):
        return jsonify({"ok": False, "error": f"unknown source '{source}'"}), 400
    conn, err = _journal_db_guard()
    if err:
        return err
    data   = request.get_json(force=True, silent=True) or {}
    reason = (data.get("reason") or "").strip()
    if not reason:
        return jsonify({"ok": False, "error": "reason required"}), 400
    now_ts = datetime.now(timezone.utc)
    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO journal_reviews"
                " (source, trade_id, review_status, exclude_reason, reviewed_by, updated_at)"
                " VALUES (%s,%s,'EXCLUDED',%s,'operator',%s)"
                " ON CONFLICT (source, trade_id) DO UPDATE SET"
                "  review_status  = 'EXCLUDED',"
                "  exclude_reason = EXCLUDED.exclude_reason,"
                "  reviewed_by    = 'operator',"
                "  updated_at     = EXCLUDED.updated_at"
                " RETURNING id",
                (source, trade_id, reason[:500], now_ts),
            )
        return jsonify({"ok": True, "review_status": "EXCLUDED"})
    except Exception as exc:
        logger.warning("journal_trade_exclude failed: %s", exc)
        return jsonify({"ok": False, "error": "update failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/journal/review-queue", methods=["GET"])
def journal_review_queue():
    """Unreviewed closed-trade count + oldest for 'Review Next Trade'."""
    conn, err = _journal_db_guard()
    if err:
        return err
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT COUNT(*) FROM strategy_trades st"
                " LEFT JOIN journal_reviews jr ON jr.source='system' AND jr.trade_id=st.id"
                " WHERE st.closed_at IS NOT NULL"
                "   AND st.result IS NOT NULL AND st.result != ''"
                "   AND COALESCE(jr.review_status,'UNREVIEWED')"
                "       NOT IN ('EXCLUDED','REVIEWED')"
            )
            sys_count = int((cur.fetchone() or (0,))[0])
            cur.execute(
                "SELECT COUNT(*) FROM tradezella_trades tt"
                " LEFT JOIN journal_reviews jr ON jr.source='tradzella' AND jr.trade_id=tt.id"
                " WHERE tt.exit_time IS NOT NULL AND tt.outcome IS NOT NULL"
                "   AND COALESCE(jr.review_status,'UNREVIEWED')"
                "       NOT IN ('EXCLUDED','REVIEWED')"
            )
            tz_count  = int((cur.fetchone() or (0,))[0])
            total     = sys_count + tz_count

            # Oldest unreviewed system trade
            cur.execute(
                "SELECT st.id, 'system' AS source,"
                " COALESCE(st.opened_at, st.created_at) AS date"
                " FROM strategy_trades st"
                " LEFT JOIN journal_reviews jr ON jr.source='system' AND jr.trade_id=st.id"
                " WHERE st.closed_at IS NOT NULL"
                "   AND st.result IS NOT NULL AND st.result != ''"
                "   AND COALESCE(jr.review_status,'UNREVIEWED')"
                "       NOT IN ('EXCLUDED','REVIEWED')"
                " ORDER BY COALESCE(st.opened_at,st.created_at) ASC NULLS LAST LIMIT 1"
            )
            sys_oldest = cur.fetchone()
            cur.execute(
                "SELECT tt.id, 'tradzella' AS source, tt.entry_time AS date"
                " FROM tradezella_trades tt"
                " LEFT JOIN journal_reviews jr ON jr.source='tradzella' AND jr.trade_id=tt.id"
                " WHERE tt.exit_time IS NOT NULL AND tt.outcome IS NOT NULL"
                "   AND COALESCE(jr.review_status,'UNREVIEWED')"
                "       NOT IN ('EXCLUDED','REVIEWED')"
                " ORDER BY tt.entry_time ASC NULLS LAST LIMIT 1"
            )
            tz_oldest = cur.fetchone()

        candidates = []
        if sys_oldest:
            candidates.append({
                "id": sys_oldest[0], "source": "system", "date": sys_oldest[2],
            })
        if tz_oldest:
            candidates.append({
                "id": tz_oldest[0], "source": "tradzella", "date": tz_oldest[2],
            })
        if candidates:
            candidates.sort(
                key=lambda x: (x["date"] or datetime.min.replace(tzinfo=timezone.utc))
            )
            nxt = candidates[0]
            if nxt.get("date") and hasattr(nxt["date"], "isoformat"):
                nxt["date"] = nxt["date"].isoformat()
        else:
            nxt = None

        return jsonify({
            "ok": True,
            "unreviewed_count": total,
            "next_trade": nxt,
            "all_reviewed": total == 0,
        })
    except Exception as exc:
        logger.warning("journal_review_queue failed: %s", exc)
        return jsonify({"ok": False, "error": "query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/journal/review-queue-full", methods=["GET"])
def journal_review_queue_full():
    """Full review queue — all open-review trades in 5 status buckets.

    Returns per-bucket lists for the Review Queue tab:
      UNREVIEWED, IN_PROGRESS, NEEDS_DATA, MISSING_STRATEGY, EXCLUDED.

    Supports filters: source, instrument, result, date_from, date_to.
    Ordering within each bucket: oldest trade first.
    """
    conn, err = _journal_db_guard()
    if err:
        return err

    flt_src  = (request.args.get("source") or "").strip().lower() or None
    flt_inst = (request.args.get("instrument") or "").strip().upper() or None
    flt_res  = (request.args.get("result") or "").strip().lower() or None
    date_from = (request.args.get("date_from") or "").strip() or None
    date_to   = (request.args.get("date_to") or "").strip() or None

    try:
        # Build per-source clauses
        sys_w, sys_p = ["1=1"], []
        tz_w,  tz_p  = ["1=1"], []

        if flt_inst:
            sys_w.append("UPPER(st.symbol) = %s"); sys_p.append(flt_inst)
            tz_w.append("UPPER(tt.symbol) = %s");  tz_p.append(flt_inst)
        if flt_res:
            sys_w.append("LOWER(COALESCE(st.result,'')) = %s");   sys_p.append(flt_res)
            tz_w.append("LOWER(COALESCE(tt.outcome,'')) = %s");   tz_p.append(flt_res)
        if date_from:
            sys_w.append("COALESCE(st.opened_at, st.created_at) >= %s"); sys_p.append(date_from)
            tz_w.append("tt.entry_time >= %s");  tz_p.append(date_from)
        if date_to:
            sys_w.append("COALESCE(st.opened_at, st.created_at) <= %s"); sys_p.append(date_to)
            tz_w.append("tt.entry_time <= %s");  tz_p.append(date_to)

        # Shared select columns
        _SYS_SEL = (
            "SELECT st.id, 'system' AS source,"
            " COALESCE(st.opened_at, st.created_at) AS date,"
            " st.symbol AS instrument, st.direction,"
            " COALESCE(st.strategy, st.strategy_key, '') AS strategy_name,"
            " COALESCE(st.strategy_key, '') AS strategy_key,"
            " COALESCE(st.result, '') AS result,"
            " COALESCE(CAST(st.r_multiple AS double precision), 0) AS r_multiple,"
            " COALESCE(jr.review_status, 'UNREVIEWED') AS review_status,"
            " COALESCE(CAST(st.edge_score AS double precision), 0) AS edge_score,"
            " COALESCE(st.trading_mode, 'SWING') AS trading_mode"
            " FROM strategy_trades st"
            " LEFT JOIN journal_reviews jr"
            "   ON jr.source = 'system' AND jr.trade_id = st.id"
            " WHERE st.closed_at IS NOT NULL"
            "   AND st.result IS NOT NULL AND st.result != ''"
        )
        _TZ_SEL = (
            "SELECT tt.id, 'tradzella' AS source,"
            " tt.entry_time AS date,"
            " tt.symbol AS instrument, tt.side AS direction,"
            " COALESCE(tt.setup, '') AS strategy_name,"
            " '' AS strategy_key,"
            " COALESCE(tt.outcome, '') AS result,"
            " COALESCE(tt.r_multiple, 0) AS r_multiple,"
            " COALESCE(jr.review_status, 'UNREVIEWED') AS review_status,"
            " 0 AS edge_score,"
            " COALESCE(tt.mode, 'UNKNOWN') AS trading_mode"
            " FROM tradezella_trades tt"
            " LEFT JOIN journal_reviews jr"
            "   ON jr.source = 'tradzella' AND jr.trade_id = tt.id"
            " WHERE tt.exit_time IS NOT NULL AND tt.outcome IS NOT NULL"
        )

        parts, all_params = [], []
        if flt_src in (None, "system"):
            parts.append(f"({_SYS_SEL} AND {' AND '.join(sys_w)})")
            all_params += sys_p
        if flt_src in (None, "tradzella"):
            parts.append(f"({_TZ_SEL} AND {' AND '.join(tz_w)})")
            all_params += tz_p

        if not parts:
            return jsonify({"ok": True, "buckets": {}, "counts": {}})

        union = " UNION ALL ".join(parts)
        full_sql = (
            f"SELECT * FROM ({union}) AS _t"
            f" ORDER BY date ASC NULLS LAST"
        )

        with conn.cursor() as cur:
            cur.execute(full_sql, all_params)
            cols = [d[0] for d in cur.description]
            rows = cur.fetchall()

        # Bucket all rows
        buckets: dict = {
            "UNREVIEWED": [], "IN_PROGRESS": [], "NEEDS_DATA": [],
            "MISSING_STRATEGY": [], "EXCLUDED": [],
        }
        for row in rows:
            d = dict(zip(cols, row))
            if d.get("date") and hasattr(d["date"], "isoformat"):
                d["date"] = d["date"].isoformat()
            for k in ("r_multiple", "edge_score"):
                try:
                    d[k] = float(d[k]) if d.get(k) is not None else 0.0
                except (TypeError, ValueError):
                    d[k] = 0.0

            # Missing strategy: system trades with no strategy_key (display-only filter)
            if d["source"] == "system" and not d.get("strategy_key"):
                buckets["MISSING_STRATEGY"].append(d)

            rs = d.get("review_status", "UNREVIEWED")
            if rs in buckets:
                buckets[rs].append(d)

        counts = {k: len(v) for k, v in buckets.items()}
        return jsonify({"ok": True, "buckets": buckets, "counts": counts})

    except Exception as exc:
        logger.warning("journal_review_queue_full failed: %s", exc)
        return jsonify({"ok": False, "error": "query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/journal/calendar-summary", methods=["GET"])
def journal_calendar_summary():
    """Daily review-progress calendar for the Journal Calendar view.

    Groups closed trades by calendar day (America/New_York) and returns:
      date, total, wins, losses, reviewed, unreviewed, all_reviewed,
      total_r (sum of r_multiple), pnl (sum; tradzella only).

    Params:
      from  — YYYY-MM-DD start date (inclusive, ET)
      to    — YYYY-MM-DD end date (inclusive, ET)
      source — 'system' | 'tradzella' | (both)
    """
    conn, err = _journal_db_guard()
    if err:
        return err

    flt_src   = (request.args.get("source") or "").strip().lower() or None
    date_from = (request.args.get("from") or "").strip() or None
    date_to   = (request.args.get("to") or "").strip() or None

    try:
        sys_dc, sys_dp = "", []
        tz_dc,  tz_dp  = "", []
        if date_from:
            sys_dc += " AND COALESCE(st.opened_at,st.created_at) AT TIME ZONE 'America/New_York' >= %s"
            sys_dp.append(date_from)
            tz_dc  += " AND tt.entry_time AT TIME ZONE 'America/New_York' >= %s"
            tz_dp.append(date_from)
        if date_to:
            sys_dc += " AND COALESCE(st.opened_at,st.created_at) AT TIME ZONE 'America/New_York' <= %s"
            sys_dp.append(date_to + " 23:59:59")
            tz_dc  += " AND tt.entry_time AT TIME ZONE 'America/New_York' <= %s"
            tz_dp.append(date_to + " 23:59:59")

        sys_sql = (
            "SELECT"
            "  TO_CHAR((COALESCE(st.opened_at,st.created_at)"
            "           AT TIME ZONE 'America/New_York'),'YYYY-MM-DD') AS day,"
            "  COUNT(*) AS n,"
            "  SUM(CASE WHEN LOWER(st.result)='win' THEN 1 ELSE 0 END) AS wins,"
            "  SUM(CASE WHEN LOWER(st.result)='loss' THEN 1 ELSE 0 END) AS losses,"
            "  COALESCE(SUM(CAST(st.r_multiple AS double precision)),0) AS total_r,"
            "  0 AS pnl,"
            "  SUM(CASE WHEN COALESCE(jr.review_status,'UNREVIEWED') IN ('REVIEWED','EXCLUDED') THEN 1 ELSE 0 END) AS reviewed"
            " FROM strategy_trades st"
            " LEFT JOIN journal_reviews jr ON jr.source='system' AND jr.trade_id=st.id"
            " WHERE st.closed_at IS NOT NULL"
            "   AND st.result IS NOT NULL AND st.result != ''" + sys_dc +
            " GROUP BY 1"
        ) if flt_src in (None, "system") else None

        tz_sql = (
            "SELECT"
            "  TO_CHAR((tt.entry_time AT TIME ZONE 'America/New_York'),'YYYY-MM-DD') AS day,"
            "  COUNT(*) AS n,"
            "  SUM(CASE WHEN LOWER(tt.outcome)='win' THEN 1 ELSE 0 END) AS wins,"
            "  SUM(CASE WHEN LOWER(tt.outcome)='loss' THEN 1 ELSE 0 END) AS losses,"
            "  COALESCE(SUM(tt.r_multiple),0) AS total_r,"
            "  COALESCE(SUM(tt.pnl),0) AS pnl,"
            "  SUM(CASE WHEN COALESCE(jr.review_status,'UNREVIEWED') IN ('REVIEWED','EXCLUDED') THEN 1 ELSE 0 END) AS reviewed"
            " FROM tradezella_trades tt"
            " LEFT JOIN journal_reviews jr ON jr.source='tradzella' AND jr.trade_id=tt.id"
            " WHERE tt.exit_time IS NOT NULL AND tt.outcome IS NOT NULL" + tz_dc +
            " GROUP BY 1"
        ) if flt_src in (None, "tradzella") else None

        # Merge per-day data
        day_data: dict = {}  # date_str → aggregated dict

        def _merge(cur_results, cols):
            for row in cur_results:
                d = dict(zip(cols, row))
                day = d["day"]
                if day not in day_data:
                    day_data[day] = {
                        "date": day, "total": 0, "wins": 0, "losses": 0,
                        "total_r": 0.0, "pnl": 0.0, "reviewed": 0,
                    }
                day_data[day]["total"]   += int(d["n"] or 0)
                day_data[day]["wins"]    += int(d["wins"] or 0)
                day_data[day]["losses"]  += int(d["losses"] or 0)
                day_data[day]["total_r"] += float(d["total_r"] or 0)
                day_data[day]["pnl"]     += float(d["pnl"] or 0)
                day_data[day]["reviewed"] += int(d["reviewed"] or 0)

        with conn.cursor() as cur:
            if sys_sql:
                cur.execute(sys_sql, sys_dp)
                cols = [d[0] for d in cur.description]
                _merge(cur.fetchall(), cols)
            if tz_sql:
                cur.execute(tz_sql, tz_dp)
                cols = [d[0] for d in cur.description]
                _merge(cur.fetchall(), cols)

        # Post-process: compute unreviewed + all_reviewed flag
        result_days = []
        for d in sorted(day_data.values(), key=lambda x: x["date"]):
            d["unreviewed"]   = max(0, d["total"] - d["reviewed"])
            d["all_reviewed"] = d["total"] > 0 and d["reviewed"] >= d["total"]
            d["total_r"]      = round(d["total_r"], 3)
            d["pnl"]          = round(d["pnl"], 2)
            result_days.append(d)

        return jsonify({"ok": True, "days": result_days, "count": len(result_days)})

    except Exception as exc:
        logger.warning("journal_calendar_summary failed: %s", exc)
        return jsonify({"ok": False, "error": "query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Phase 7N Batch C — Learning Eligibility & Review Analytics (DISPLAY-ONLY)
# ---------------------------------------------------------------------------
# Two read-only routes that surface per-trade learning eligibility and
# aggregate review-field analytics from journal_reviews.
#
# INVARIANT: Neither route reads LEARNING_ELIGIBILITY, calls any learning
# formula, modifies any weight, or writes to any table.  Both are pure
# SELECT aggregations from journal_reviews + strategy_trades +
# tradezella_trades.  The learning engine is never invoked.
# ---------------------------------------------------------------------------

# Valid outcome tokens (case-insensitive comparison used in route)
_ELIG_VALID_OUTCOMES = frozenset({
    "win", "loss", "be", "scratch", "breakeven", "b/e",
})


@app.route("/journal/learning-eligibility", methods=["GET"])
def journal_learning_eligibility():
    """Per-trade learning eligibility — DISPLAY-ONLY.

    Computes one of:
      ELIGIBLE             — all criteria met + REVIEWED
      REVIEW_REQUIRED      — trade not yet reviewed
      MISSING_RISK         — planned stop (risk) not recorded (system only)
      MISSING_STRATEGY     — strategy_key not resolved (system only)
      INVALID_OUTCOME      — result/outcome is null or unrecognised
      EXCLUDED_BY_OPERATOR — review_status = EXCLUDED
    for every closed trade in strategy_trades and tradezella_trades.

    Never writes to the learning engine or modifies any weight/threshold.
    """
    conn, err = _journal_db_guard()
    if err:
        return err
    try:
        with conn.cursor() as cur:
            # ── System trades ─────────────────────────────────────────────
            cur.execute(
                "SELECT st.id,"
                " st.result,"
                " st.strategy_key,"
                " st.stop,"
                " COALESCE(jr.review_status, 'UNREVIEWED') AS review_status"
                " FROM strategy_trades st"
                " LEFT JOIN journal_reviews jr"
                "   ON jr.source = 'system' AND jr.trade_id = st.id"
                " WHERE st.closed_at IS NOT NULL"
            )
            sys_cols = [d[0] for d in cur.description]
            sys_rows = cur.fetchall()

            # ── Tradezella trades ─────────────────────────────────────────
            # Task 83: include match_confidence + learning_status for attribution gate
            cur.execute(
                "SELECT tt.id,"
                " tt.outcome AS result,"
                " COALESCE(jr.review_status, 'UNREVIEWED') AS review_status,"
                " tt.match_confidence,"
                " tt.learning_status"
                " FROM tradezella_trades tt"
                " LEFT JOIN journal_reviews jr"
                "   ON jr.source = 'tradzella' AND jr.trade_id = tt.id"
                " WHERE tt.exit_time IS NOT NULL"
            )
            tz_cols = [d[0] for d in cur.description]
            tz_rows = cur.fetchall()

        records = []

        for row in sys_rows:
            d = dict(zip(sys_cols, row))
            result        = (d.get("result") or "").strip().lower()
            strategy_key  = d.get("strategy_key")
            stop          = d.get("stop")
            review_status = d.get("review_status", "UNREVIEWED")

            if review_status == "EXCLUDED":
                status = "EXCLUDED_BY_OPERATOR"
                reason = "Manually excluded by operator"
            elif result not in _ELIG_VALID_OUTCOMES:
                status = "INVALID_OUTCOME"
                reason = "Outcome not recorded or unrecognised"
            elif not strategy_key:
                status = "MISSING_STRATEGY"
                reason = "Strategy key not resolved for this trade"
            elif stop is None:
                status = "MISSING_RISK"
                reason = "Planned stop (risk) not recorded"
            elif review_status != "REVIEWED":
                status = "REVIEW_REQUIRED"
                reason = f"Review not complete (status: {review_status})"
            else:
                status = "ELIGIBLE"
                reason = ""

            records.append({
                "source":   "system",
                "trade_id": int(d["id"]),
                "status":   status,
                "reason":   reason,
            })

        for row in tz_rows:
            d = dict(zip(tz_cols, row))
            result        = (d.get("result") or "").strip().lower()
            review_status = d.get("review_status", "UNREVIEWED")
            match_conf    = d.get("match_confidence")
            db_learning   = d.get("learning_status")

            if review_status == "EXCLUDED":
                status = "EXCLUDED_BY_OPERATOR"
                reason = "Manually excluded by operator"
            elif match_conf in ("UNMATCHED", "AMBIGUOUS"):
                # Task 83: unmatched/ambiguous TZ trades cannot be learning-eligible
                status = "UNMATCHED"
                reason = (f"Not matched to an internal system snapshot "
                          f"({match_conf or 'no match data'}) — assign strategy manually")
            elif db_learning == "INELIGIBLE":
                status = "INELIGIBLE"
                reason = "Ineligible per match result (external trade or unresolved strategy)"
            elif result not in _ELIG_VALID_OUTCOMES:
                status = "INVALID_OUTCOME"
                reason = "Outcome not recorded or unrecognised"
            elif review_status != "REVIEWED":
                status = "REVIEW_REQUIRED"
                reason = f"Review not complete (status: {review_status})"
            else:
                status = "ELIGIBLE"
                reason = ""

            records.append({
                "source":        "tradzella",
                "trade_id":      int(d["id"]),
                "status":        status,
                "reason":        reason,
                "match_confidence": match_conf,
            })

        counts: dict = {}
        for r in records:
            counts[r["status"]] = counts.get(r["status"], 0) + 1

        return jsonify({
            "ok":      True,
            "records": records,
            "total":   len(records),
            "counts":  counts,
        })
    except Exception as exc:
        logger.warning("journal_learning_eligibility failed: %s", exc)
        return jsonify({"ok": False, "error": "query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/journal/review-analytics", methods=["GET"])
def journal_review_analytics():
    """Aggregate review-field analytics from journal_reviews — DISPLAY-ONLY.

    Returns:
      mistake_tag_counts         — [{tag, count}] sorted desc (REVIEWED only)
      positive_tag_counts        — [{tag, count}] sorted desc (REVIEWED only)
      followed_plan_distribution — {YES: n, PARTIALLY: n, NO: n, ...}
      rating_distributions       — {setup_quality: {1: n, ...}, ...}
      emotion_by_day             — [{day, emotion, count}]
      win_rate_by_discipline_quality — {1: pct, ..., 5: pct} (system only)
      coaching_summary           — top-3 mistakes, top-3 positives, reviewed_count

    Never writes to the learning engine or modifies any weight/threshold.
    """
    conn, err = _journal_db_guard()
    if err:
        return err
    try:
        with conn.cursor() as cur:

            # ── Mistake tag frequency ──────────────────────────────────────
            cur.execute(
                "SELECT tag, COUNT(*) AS n"
                " FROM journal_reviews,"
                "      jsonb_array_elements_text(mistake_tags) AS tag"
                " WHERE review_status = 'REVIEWED'"
                "   AND mistake_tags IS NOT NULL"
                " GROUP BY tag ORDER BY n DESC"
            )
            mistake_tag_counts = [
                {"tag": r[0], "count": int(r[1])} for r in cur.fetchall()
            ]

            # ── Positive tag frequency ─────────────────────────────────────
            cur.execute(
                "SELECT tag, COUNT(*) AS n"
                " FROM journal_reviews,"
                "      jsonb_array_elements_text(positive_tags) AS tag"
                " WHERE review_status = 'REVIEWED'"
                "   AND positive_tags IS NOT NULL"
                " GROUP BY tag ORDER BY n DESC"
            )
            positive_tag_counts = [
                {"tag": r[0], "count": int(r[1])} for r in cur.fetchall()
            ]

            # ── Followed-plan distribution ─────────────────────────────────
            cur.execute(
                "SELECT followed_plan, COUNT(*) AS n"
                " FROM journal_reviews"
                " WHERE review_status = 'REVIEWED'"
                "   AND followed_plan IS NOT NULL"
                " GROUP BY followed_plan"
            )
            followed_plan_distribution: dict = {}
            for r in cur.fetchall():
                followed_plan_distribution[r[0]] = int(r[1])

            # ── Rating distributions ───────────────────────────────────────
            rating_distributions: dict = {}
            for field in ("setup_quality", "execution_quality",
                          "discipline_quality", "overall_quality"):
                cur.execute(
                    f"SELECT {field}, COUNT(*) AS n"
                    f" FROM journal_reviews"
                    f" WHERE review_status = 'REVIEWED'"
                    f"   AND {field} IS NOT NULL"
                    f" GROUP BY {field} ORDER BY {field}"
                )
                rating_distributions[field] = {
                    int(r[0]): int(r[1]) for r in cur.fetchall()
                }

            # ── Emotion by day ─────────────────────────────────────────────
            cur.execute(
                "SELECT"
                "  TO_CHAR(COALESCE(reviewed_at, updated_at)"
                "          AT TIME ZONE 'America/New_York', 'YYYY-MM-DD') AS day,"
                "  elem->>'tag' AS emotion,"
                "  COUNT(*) AS n"
                " FROM journal_reviews,"
                "      jsonb_array_elements(emotion_tags) AS elem"
                " WHERE review_status = 'REVIEWED'"
                "   AND emotion_tags IS NOT NULL"
                "   AND jsonb_typeof(emotion_tags) = 'array'"
                " GROUP BY 1, 2"
                " ORDER BY 1, n DESC"
            )
            emotion_by_day = [
                {"day": r[0], "emotion": r[1], "count": int(r[2])}
                for r in cur.fetchall()
            ]

            # ── Win-rate by discipline quality (system trades only) ────────
            cur.execute(
                "SELECT jr.discipline_quality,"
                "  COUNT(*) AS n,"
                "  SUM(CASE WHEN LOWER(st.result)='win' THEN 1 ELSE 0 END) AS wins"
                " FROM journal_reviews jr"
                " JOIN strategy_trades st"
                "   ON jr.source = 'system' AND st.id = jr.trade_id"
                " WHERE jr.review_status = 'REVIEWED'"
                "   AND jr.discipline_quality IS NOT NULL"
                "   AND st.result IS NOT NULL"
                " GROUP BY jr.discipline_quality"
                " ORDER BY jr.discipline_quality"
            )
            win_rate_by_discipline_quality: dict = {}
            for r in cur.fetchall():
                q, n, wins = int(r[0]), int(r[1]), int(r[2])
                win_rate_by_discipline_quality[q] = (
                    round(wins / n * 100, 1) if n else None
                )

            # ── REVIEWED count ─────────────────────────────────────────────
            cur.execute(
                "SELECT COUNT(*) FROM journal_reviews WHERE review_status = 'REVIEWED'"
            )
            reviewed_count = int((cur.fetchone() or (0,))[0])

        coaching_summary = {
            "top_mistakes":   mistake_tag_counts[:3],
            "top_positives":  positive_tag_counts[:3],
            "reviewed_count": reviewed_count,
        }

        return jsonify({
            "ok":                           True,
            "mistake_tag_counts":           mistake_tag_counts,
            "positive_tag_counts":          positive_tag_counts,
            "followed_plan_distribution":   followed_plan_distribution,
            "rating_distributions":         rating_distributions,
            "emotion_by_day":               emotion_by_day,
            "win_rate_by_discipline_quality": win_rate_by_discipline_quality,
            "coaching_summary":             coaching_summary,
        })
    except Exception as exc:
        logger.warning("journal_review_analytics failed: %s", exc)
        return jsonify({"ok": False, "error": "analytics query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Phase 7O — Journal Coaching Dashboard (DISPLAY-ONLY analytics)
# ---------------------------------------------------------------------------
# Reads reviewed-trade data from journal_reviews + strategy_trades +
# tradezella_trades and converts it into actionable coaching insights.
#
# INVARIANTS:
#  • Never modifies learning weights, gate logic, or any execution path.
#  • All writes to journal_reviews happen only in the review PATCH route.
#  • No DDL.  SELECT only.
#
# CONFIDENCE THRESHOLDS (documented, not invented):
#  Aligned with the 50-sample learning-engine threshold.
#  INSUFFICIENT_DATA    < 5  — do not draw conclusions
#  EARLY_SIGNAL         5–19 — directional hint only
#  MODERATE_CONFIDENCE  20–49
#  STRONG_EVIDENCE      ≥ 50
#
# COACHING PRIORITY FORMULA (display-only, never feeds money path):
#  priority = (|net_R| × 2.0  +  frequency × 1.0) × min(1.0, n / 20.0)
#  Weights: net_R × 2 penalises costly mistakes; frequency × 1 penalises
#  recurring ones; sample weight scales down small-n results.
# ---------------------------------------------------------------------------

_COACHING_WIN_RESULTS_SQL = "('win','scratch','be','breakeven','b/e')"

_COACHING_CONFIDENCE_THRESHOLDS = [(50, "STRONG_EVIDENCE"),
                                   (20, "MODERATE_CONFIDENCE"),
                                   (5,  "EARLY_SIGNAL"),
                                   (0,  "INSUFFICIENT_DATA")]


def _coaching_confidence(n: int) -> str:
    for threshold, label in _COACHING_CONFIDENCE_THRESHOLDS:
        if n >= threshold:
            return label
    return "INSUFFICIENT_DATA"


def _coaching_pf(sum_pos: float, sum_neg_abs: float):
    """Profit factor; None when no losers."""
    if not sum_neg_abs:
        return None
    return round(sum_pos / sum_neg_abs, 2) if sum_pos else 0.0


# Base CTE — unified view of all closed trades that have a review row.
# Each section query prepends this string.
_COACHING_BASE_CTE = """\
WITH base AS (
  SELECT 'system'::text AS source, st.id AS trade_id,
    COALESCE(st.opened_at, st.created_at)
        AT TIME ZONE 'UTC' AT TIME ZONE 'America/New_York' AS trade_date,
    COALESCE(st.symbol,'')                                  AS instrument,
    LOWER(COALESCE(st.direction,''))                        AS direction,
    COALESCE(st.session,'')                                 AS session,
    EXTRACT(DOW FROM COALESCE(st.opened_at, st.created_at)
        AT TIME ZONE 'UTC' AT TIME ZONE 'America/New_York')::int AS dow,
    LOWER(COALESCE(st.result,''))                           AS result,
    st.r_multiple,
    NULL::float                                             AS pnl,
    COALESCE(st.strategy_key, st.strategy,'')              AS strategy_name,
    COALESCE(st.trading_mode,'')                            AS mode,
    jr.review_status, jr.followed_plan,
    jr.mistake_tags,  jr.positive_tags, jr.emotion_tags,
    jr.setup_quality, jr.execution_quality,
    jr.discipline_quality, jr.overall_quality, jr.reviewed_at
  FROM strategy_trades   st
  JOIN journal_reviews   jr ON jr.source = 'system'    AND jr.trade_id = st.id
  WHERE st.closed_at IS NOT NULL
  UNION ALL
  SELECT 'tradzella'::text, tt.id,
    COALESCE(tt.entry_time, tt.exit_time)
        AT TIME ZONE 'UTC' AT TIME ZONE 'America/New_York',
    COALESCE(tt.symbol,''), LOWER(COALESCE(tt.side,'')),
    COALESCE(tt.session_bucket,''),
    EXTRACT(DOW FROM COALESCE(tt.entry_time, tt.exit_time)
        AT TIME ZONE 'UTC' AT TIME ZONE 'America/New_York')::int,
    LOWER(COALESCE(tt.outcome,'')), tt.r_multiple, tt.pnl::float,
    COALESCE(tt.setup,''), COALESCE(tt.mode,''),
    jr.review_status, jr.followed_plan,
    jr.mistake_tags,  jr.positive_tags, jr.emotion_tags,
    jr.setup_quality, jr.execution_quality,
    jr.discipline_quality, jr.overall_quality, jr.reviewed_at
  FROM tradezella_trades tt
  JOIN journal_reviews   jr ON jr.source = 'tradzella' AND jr.trade_id = tt.id
  WHERE tt.exit_time IS NOT NULL
)"""

WIN_SQL  = _COACHING_WIN_RESULTS_SQL  # shorthand


@app.route("/journal/coaching", methods=["GET"])
def journal_coaching():
    """Journal Coaching Dashboard — DISPLAY-ONLY.

    Query params:
      date_from, date_to  YYYY-MM-DD (inclusive, America/New_York dates)
      instrument           partial match (ILIKE)
      mode                 exact (SCALP | SWING | MICRO_SCALP)
      source               system | tradzella | '' = all
    """
    conn, err = _journal_db_guard()
    if err:
        return err

    date_from    = (request.args.get("date_from") or "").strip()
    date_to      = (request.args.get("date_to")   or "").strip()
    f_instrument = (request.args.get("instrument") or "").strip()
    f_mode       = (request.args.get("mode")       or "").strip().upper()
    f_source     = (request.args.get("source")     or "").strip().lower()

    # Build filter clauses applied after the CTE (no user data in SQL text)
    f_clauses: list = []
    f_params:  list = []
    if date_from:
        f_clauses.append("trade_date::date >= %s")
        f_params.append(date_from)
    if date_to:
        f_clauses.append("trade_date::date <= %s")
        f_params.append(date_to)
    if f_instrument:
        f_clauses.append("instrument ILIKE %s")
        f_params.append(f"%{f_instrument}%")
    if f_mode:
        f_clauses.append("UPPER(mode) = %s")
        f_params.append(f_mode)
    if f_source in ("system", "tradzella"):
        f_clauses.append("source = %s")
        f_params.append(f_source)

    fa = (" AND " + " AND ".join(f_clauses)) if f_clauses else ""   # filter AND
    CTE = _COACHING_BASE_CTE

    def _run(cur, sql, extra_params=()):
        p = list(f_params) + list(extra_params)
        cur.execute(sql, p)
        cols = [d[0] for d in cur.description]
        return [dict(zip(cols, r)) for r in cur.fetchall()]

    def _run_one(cur, sql, extra_params=()):
        p = list(f_params) + list(extra_params)
        cur.execute(sql, p)
        r = cur.fetchone()
        return r[0] if r else 0

    try:
        with conn.cursor() as cur:

            # ── 1. Data coverage ─────────────────────────────────────────
            cur.execute(
                CTE + f"""
                SELECT
                  COUNT(*) FILTER (WHERE TRUE)                                AS total,
                  COUNT(*) FILTER (WHERE review_status = 'REVIEWED')          AS reviewed,
                  COUNT(*) FILTER (WHERE review_status = 'EXCLUDED')          AS excluded,
                  COUNT(*) FILTER (WHERE review_status IN ('IN_PROGRESS','NEEDS_DATA')) AS incomplete,
                  COUNT(*) FILTER (WHERE review_status = 'UNREVIEWED')        AS unreviewed,
                  COUNT(DISTINCT instrument)                                   AS instruments,
                  COUNT(DISTINCT source)                                       AS sources,
                  COUNT(DISTINCT mode)                                         AS modes
                FROM base WHERE TRUE {fa}""", f_params
            )
            cov_row = cur.fetchone()
            cov_cols = [d[0] for d in cur.description]
            cov = dict(zip(cov_cols, cov_row)) if cov_row else {}

            # ── 2. Costliest mistakes ────────────────────────────────────
            mistake_rows = _run(cur, CTE + f"""
                SELECT tag,
                  COUNT(*)::int                                                AS n,
                  SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int   AS wins,
                  SUM(CASE WHEN result='loss' THEN 1 ELSE 0 END)::int         AS losses,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(AVG(r_multiple)::numeric, 3)::float                   AS avg_r,
                  ROUND(SUM(COALESCE(pnl,0))::numeric, 2)::float             AS net_pnl,
                  ROUND(ABS(AVG(CASE WHEN result='loss' THEN r_multiple END))::numeric,3)::float
                                                                               AS avg_loss_r,
                  ROUND(SUM(CASE WHEN r_multiple>0 THEN r_multiple ELSE 0 END)::numeric,3)::float
                                                                               AS sum_pos_r,
                  ROUND(ABS(SUM(CASE WHEN r_multiple<0 THEN r_multiple ELSE 0 END))::numeric,3)::float
                                                                               AS sum_neg_r,
                  STRING_AGG(DISTINCT instrument, ', ' ORDER BY instrument)   AS instruments,
                  STRING_AGG(DISTINCT session,    ', ' ORDER BY session)       AS sessions
                FROM base,
                     jsonb_array_elements_text(mistake_tags) AS tag
                WHERE review_status='REVIEWED'
                  AND mistake_tags IS NOT NULL
                  AND jsonb_typeof(mistake_tags)='array' {fa}
                GROUP BY tag ORDER BY net_r ASC
            """)

            # ── 3. Best behaviors (positive tags) ────────────────────────
            behavior_rows = _run(cur, CTE + f"""
                SELECT tag,
                  COUNT(*)::int                                                AS n,
                  SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int   AS wins,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(AVG(r_multiple)::numeric, 3)::float                   AS avg_r,
                  ROUND(SUM(CASE WHEN r_multiple>0 THEN r_multiple ELSE 0 END)::numeric,3)::float
                                                                               AS sum_pos_r,
                  ROUND(ABS(SUM(CASE WHEN r_multiple<0 THEN r_multiple ELSE 0 END))::numeric,3)::float
                                                                               AS sum_neg_r,
                  ROUND(100.0 * SUM(CASE WHEN followed_plan='YES' THEN 1 ELSE 0 END)::numeric
                        / NULLIF(COUNT(*),0), 1)::float                        AS plan_follow_pct
                FROM base,
                     jsonb_array_elements_text(positive_tags) AS tag
                WHERE review_status='REVIEWED'
                  AND positive_tags IS NOT NULL
                  AND jsonb_typeof(positive_tags)='array' {fa}
                GROUP BY tag ORDER BY avg_r DESC NULLS LAST
            """)

            # ── 4. Followed-plan analytics ───────────────────────────────
            plan_rows = _run(cur, CTE + f"""
                SELECT followed_plan,
                  COUNT(*)::int                                                AS n,
                  SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int   AS wins,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(AVG(r_multiple)::numeric, 3)::float                   AS avg_r,
                  ROUND(SUM(CASE WHEN r_multiple>0 THEN r_multiple ELSE 0 END)::numeric,3)::float
                                                                               AS sum_pos_r,
                  ROUND(ABS(SUM(CASE WHEN r_multiple<0 THEN r_multiple ELSE 0 END))::numeric,3)::float
                                                                               AS sum_neg_r,
                  ROUND(AVG(setup_quality)::numeric, 2)::float                AS avg_setup,
                  ROUND(AVG(execution_quality)::numeric, 2)::float            AS avg_execution,
                  ROUND(AVG(discipline_quality)::numeric, 2)::float           AS avg_discipline
                FROM base
                WHERE review_status='REVIEWED'
                  AND followed_plan IS NOT NULL {fa}
                GROUP BY followed_plan
                ORDER BY CASE followed_plan WHEN 'YES' THEN 1 WHEN 'PARTIALLY' THEN 2
                                             WHEN 'NO' THEN 3 ELSE 4 END
            """)

            # ── 5. Emotion analytics ─────────────────────────────────────
            emotion_rows = _run(cur, CTE + f"""
                SELECT elem->>'tag'                                            AS emotion,
                  COUNT(*)::int                                                AS n,
                  ROUND(AVG((elem->>'intensity')::float)::numeric, 2)::float  AS avg_intensity,
                  SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int   AS wins,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(AVG(r_multiple)::numeric, 3)::float                   AS avg_r,
                  ROUND(100.0 * SUM(CASE WHEN followed_plan='YES' THEN 1 ELSE 0 END)::numeric
                        / NULLIF(COUNT(*),0), 1)::float                        AS plan_follow_pct,
                  STRING_AGG(DISTINCT session, ', ' ORDER BY session)         AS sessions
                FROM base,
                     jsonb_array_elements(emotion_tags) AS elem
                WHERE review_status='REVIEWED'
                  AND emotion_tags IS NOT NULL
                  AND jsonb_typeof(emotion_tags)='array' {fa}
                GROUP BY elem->>'tag'
                ORDER BY net_r ASC
            """)

            # ── 6. Rating analytics (4 quality fields) ───────────────────
            rating_analytics: dict = {}
            for field in ("setup_quality", "execution_quality",
                          "discipline_quality", "overall_quality"):
                rows = _run(cur, CTE + f"""
                    SELECT {field}::int                                        AS rating,
                      COUNT(*)::int                                            AS n,
                      SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int AS wins,
                      ROUND(AVG(r_multiple)::numeric, 3)::float               AS avg_r,
                      ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float   AS net_r
                    FROM base
                    WHERE review_status='REVIEWED'
                      AND {field} IS NOT NULL {fa}
                    GROUP BY {field} ORDER BY {field}
                """)
                rating_analytics[field] = rows

            # ── 7. Strategy coaching ─────────────────────────────────────
            strategy_rows = _run(cur, CTE + f"""
                SELECT strategy_name,
                  COUNT(*)::int                                                AS n,
                  SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int   AS wins,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(AVG(r_multiple)::numeric, 3)::float                   AS avg_r,
                  ROUND(SUM(CASE WHEN r_multiple>0 THEN r_multiple ELSE 0 END)::numeric,3)::float
                                                                               AS sum_pos_r,
                  ROUND(ABS(SUM(CASE WHEN r_multiple<0 THEN r_multiple ELSE 0 END))::numeric,3)::float
                                                                               AS sum_neg_r,
                  ROUND(100.0 * SUM(CASE WHEN followed_plan='YES' THEN 1 ELSE 0 END)::numeric
                        / NULLIF(COUNT(*),0), 1)::float                        AS plan_follow_pct,
                  STRING_AGG(DISTINCT session, ', ' ORDER BY session)         AS sessions
                FROM base
                WHERE review_status='REVIEWED' {fa}
                GROUP BY strategy_name ORDER BY avg_r DESC NULLS LAST
            """)

            # ── 8. Session analytics ─────────────────────────────────────
            session_rows = _run(cur, CTE + f"""
                SELECT COALESCE(NULLIF(session,''), 'unknown')                 AS session,
                  dow,
                  COUNT(*)::int                                                AS n,
                  SUM(CASE WHEN result IN {WIN_SQL} THEN 1 ELSE 0 END)::int   AS wins,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(AVG(r_multiple)::numeric, 3)::float                   AS avg_r,
                  ROUND(100.0 * SUM(CASE WHEN followed_plan='YES' THEN 1 ELSE 0 END)::numeric
                        / NULLIF(COUNT(*),0), 1)::float                        AS plan_follow_pct
                FROM base
                WHERE review_status='REVIEWED' {fa}
                GROUP BY session, dow ORDER BY session, dow
            """)

            # ── 9. Discipline trend (weekly) ─────────────────────────────
            trend_rows = _run(cur, CTE + f"""
                SELECT DATE_TRUNC('week', trade_date)::date                   AS week_start,
                  COUNT(*)::int                                                AS n,
                  ROUND(AVG(discipline_quality)::numeric, 2)::float           AS avg_discipline,
                  ROUND(AVG(execution_quality)::numeric, 2)::float            AS avg_execution,
                  ROUND(AVG(overall_quality)::numeric, 2)::float              AS avg_overall,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric, 3)::float       AS net_r,
                  ROUND(100.0 * SUM(CASE WHEN followed_plan='YES' THEN 1 ELSE 0 END)::numeric
                        / NULLIF(COUNT(*),0), 1)::float                        AS followed_plan_pct,
                  ROUND(100.0 * COUNT(*) FILTER (WHERE mistake_tags IS NOT NULL
                        AND jsonb_typeof(mistake_tags)='array'
                        AND jsonb_array_length(mistake_tags)>0)::numeric
                        / NULLIF(COUNT(*),0), 1)::float                        AS mistake_rate_pct
                FROM base
                WHERE review_status='REVIEWED' {fa}
                GROUP BY week_start ORDER BY week_start ASC
            """)

        # ── Post-process: convert SQL rows to dicts with computed fields ──

        def _augment_tag_row(r, total_key="n"):
            n = r.get(total_key) or 0
            wins = r.get("wins") or 0
            r["win_rate"]   = round(wins / n * 100, 1) if n else None
            r["confidence"] = _coaching_confidence(n)
            r["profit_factor"] = _coaching_pf(r.get("sum_pos_r") or 0,
                                               r.get("sum_neg_r") or 0)
            return r

        costliest_mistakes = [_augment_tag_row(r) for r in mistake_rows]
        best_behaviors     = [_augment_tag_row(r) for r in behavior_rows]

        followed_plan_analytics = []
        for r in plan_rows:
            n = r.get("n") or 0
            _augment_tag_row(r)
            r["plan_label"] = r.get("followed_plan", "")
            followed_plan_analytics.append(r)

        emotion_analytics = []
        for r in emotion_rows:
            n = r.get("n") or 0
            wins = r.get("wins") or 0
            r["win_rate"]   = round(wins / n * 100, 1) if n else None
            r["confidence"] = _coaching_confidence(n)
            emotion_analytics.append(r)

        for fld, rows in rating_analytics.items():
            for r in rows:
                n = r.get("n") or 0
                wins = r.get("wins") or 0
                r["win_rate"] = round(wins / n * 100, 1) if n else None

        strategy_coaching = []
        for r in strategy_rows:
            _augment_tag_row(r)
            strategy_coaching.append(r)

        session_analytics = []
        for r in session_rows:
            n = r.get("n") or 0
            wins = r.get("wins") or 0
            r["win_rate"]   = round(wins / n * 100, 1) if n else None
            r["confidence"] = _coaching_confidence(n)
            session_analytics.append(r)

        # ── Discipline trend label ───────────────────────────────────────
        disc_trend_label = "INSUFFICIENT_DATA"
        weeks_with_discipline = [w for w in trend_rows
                                  if w.get("avg_discipline") is not None]
        if len(weeks_with_discipline) >= 4:
            mid = len(weeks_with_discipline) // 2
            avg_first  = sum(w["avg_discipline"] for w in weeks_with_discipline[:mid]) / mid
            avg_second = sum(w["avg_discipline"] for w in weeks_with_discipline[mid:]) / (
                len(weeks_with_discipline) - mid)
            diff = avg_second - avg_first
            disc_trend_label = ("IMPROVING"  if diff >  0.2 else
                                "DECLINING"  if diff < -0.2 else
                                "STABLE")
        elif weeks_with_discipline:
            disc_trend_label = "INSUFFICIENT_DATA"

        # Serialise trend rows
        for row in trend_rows:
            if row.get("week_start"):
                row["week_start"] = str(row["week_start"])

        # ── Coaching summary (deterministic from section results) ─────────
        coaching_summary: dict = {}

        if costliest_mistakes:
            worst = costliest_mistakes[0]
            coaching_summary["biggest_leak"] = {
                "tag":   worst.get("tag"),
                "net_r": worst.get("net_r"),
                "count": worst.get("n"),
                "text":  (
                    f"{(worst.get('tag') or '').replace('_',' ').title()} "
                    f"cost {abs(worst.get('net_r') or 0):.1f}R across "
                    f"{worst.get('n')} reviewed trades."
                ),
            }

        if best_behaviors:
            best = best_behaviors[0]
            coaching_summary["best_habit"] = {
                "tag":   best.get("tag"),
                "avg_r": best.get("avg_r"),
                "count": best.get("n"),
                "text":  (
                    f"{(best.get('tag') or '').replace('_',' ').title()} "
                    f"produced {'+' if (best.get('avg_r') or 0) >= 0 else ''}"
                    f"{best.get('avg_r'):.2f}R average across {best.get('n')} trades."
                ),
            }

        eligible_strategies = [s for s in strategy_coaching
                                if (s.get("n") or 0) >= 5]
        if eligible_strategies:
            best_strat = max(eligible_strategies,
                             key=lambda s: s.get("avg_r") or 0)
            coaching_summary["best_setup"] = {
                "strategy": best_strat.get("strategy_name"),
                "avg_r":    best_strat.get("avg_r"),
                "count":    best_strat.get("n"),
            }

        eligible_sessions = [s for s in session_analytics
                              if (s.get("n") or 0) >= 3]
        if eligible_sessions:
            worst_s = min(eligible_sessions,
                          key=lambda s: s.get("avg_r") or 0)
            coaching_summary["worst_condition"] = {
                "session": worst_s.get("session"),
                "avg_r":   worst_s.get("avg_r"),
                "count":   worst_s.get("n"),
            }

        coaching_summary["discipline_trend"] = disc_trend_label

        # ── Priority list ────────────────────────────────────────────────
        # Formula: (|net_R|×2 + frequency×1) × min(1, n/20)   [display-only]
        priority_items = []
        for m in costliest_mistakes[:20]:
            n         = m.get("n") or 0
            net_r_abs = abs(m.get("net_r") or 0)
            freq      = n
            score     = (net_r_abs * 2.0 + freq * 1.0) * min(1.0, n / 20.0)
            priority_items.append({
                "type":        "mistake",
                "tag":         m.get("tag"),
                "score":       round(score, 2),
                "net_r":       m.get("net_r"),
                "count":       n,
                "confidence":  m.get("confidence"),
                "description": (
                    f"Tagged in {n} trade(s), "
                    f"{abs(m.get('net_r') or 0):.1f}R total cost."
                ),
            })

        priority_items.sort(key=lambda x: x["score"], reverse=True)

        if priority_items:
            coaching_summary["next_focus"] = {
                "type": priority_items[0]["type"],
                "tag":  priority_items[0]["tag"],
                "text": priority_items[0]["description"],
            }

        # ── Coverage object ──────────────────────────────────────────────
        reviewed_n = int(cov.get("reviewed") or 0)
        data_coverage = {
            "total":           int(cov.get("total") or 0),
            "reviewed":        reviewed_n,
            "excluded":        int(cov.get("excluded") or 0),
            "incomplete":      int(cov.get("incomplete") or 0),
            "unreviewed":      int(cov.get("unreviewed") or 0),
            "instrument_count": int(cov.get("instruments") or 0),
            "source_count":    int(cov.get("sources") or 0),
            "mode_count":      int(cov.get("modes") or 0),
            "confidence":      _coaching_confidence(reviewed_n),
        }

        return jsonify({
            "ok":                     True,
            "data_coverage":          data_coverage,
            "costliest_mistakes":     costliest_mistakes,
            "best_behaviors":         best_behaviors,
            "followed_plan_analytics": followed_plan_analytics,
            "emotion_analytics":      emotion_analytics,
            "rating_analytics":       rating_analytics,
            "strategy_coaching":      strategy_coaching,
            "session_analytics":      session_analytics,
            "discipline_trend":       {
                "label":   disc_trend_label,
                "weekly":  trend_rows,
            },
            "coaching_summary":       coaching_summary,
            "coaching_priority":      priority_items,
        })

    except Exception as exc:
        logger.warning("journal_coaching failed: %s", exc)
        return jsonify({"ok": False, "error": "coaching query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Phase 7O.2 — Intraday 30-Minute Block Coaching (display-only, SELECT only)
# ---------------------------------------------------------------------------

# Canonical entry timestamp per source (used by both this endpoint and
# journal_trades_list block filter — never changes the money path).
_WIN_SET      = {'win'}
_SCRATCH_SET  = {'scratch', 'be', 'breakeven', 'b/e'}
_LOSS_SET     = {'loss', 'stopped', 'stopped out', 'stop', 'sl', 'stop loss', 'stopped-out'}

# Base LEFT JOIN CTE for intraday analytics (includes unreviewed trades in counts).
_INTRADAY_BASE_CTE = """\
WITH base AS (
  SELECT 'system'::text AS source, st.id AS trade_id,
    COALESCE(st.opened_at, st.created_at)     AS entry_ts,
    COALESCE(st.symbol,'')                     AS instrument,
    LOWER(COALESCE(st.direction,''))           AS direction,
    LOWER(COALESCE(st.result,''))              AS result,
    st.r_multiple,
    NULL::float                                AS pnl,
    COALESCE(st.strategy_key, st.strategy,'') AS strategy_name,
    COALESCE(st.trading_mode,'')               AS mode,
    COALESCE(jr.review_status,'UNREVIEWED')    AS review_status,
    jr.followed_plan,
    jr.mistake_tags, jr.positive_tags, jr.emotion_tags,
    jr.setup_quality, jr.execution_quality,
    jr.discipline_quality, jr.overall_quality
  FROM strategy_trades   st
  LEFT JOIN journal_reviews jr ON jr.source = 'system'    AND jr.trade_id = st.id
  WHERE st.closed_at IS NOT NULL
  UNION ALL
  SELECT 'tradzella'::text, tt.id,
    tt.entry_time,
    COALESCE(tt.symbol,''),   LOWER(COALESCE(tt.side,'')),
    LOWER(COALESCE(tt.outcome,'')),
    tt.r_multiple, tt.pnl::float,
    COALESCE(tt.setup,''),    COALESCE(tt.mode,''),
    COALESCE(jr.review_status,'UNREVIEWED'),
    jr.followed_plan,
    jr.mistake_tags, jr.positive_tags, jr.emotion_tags,
    jr.setup_quality, jr.execution_quality,
    jr.discipline_quality, jr.overall_quality
  FROM tradezella_trades tt
  LEFT JOIN journal_reviews jr ON jr.source = 'tradzella' AND jr.trade_id = tt.id
  WHERE tt.exit_time IS NOT NULL
)"""


def _top_tag_from_jsonb_list(rows, field: str, *, is_emotion: bool = False) -> str | None:
    """Return the most-common tag from JSONB tag list across rows.

    Ties broken by alphabetical order for determinism.
    For emotion tags (JSONB array of objects with "tag" key), set is_emotion=True.
    """
    from collections import Counter
    counts: Counter = Counter()
    for r in rows:
        raw = r.get(field)
        if not raw:
            continue
        if isinstance(raw, list):
            items = raw
        else:
            try:
                import json as _json
                items = _json.loads(raw)
            except Exception:
                continue
        for item in items:
            if is_emotion:
                tag = (item.get("tag") or "") if isinstance(item, dict) else ""
            else:
                tag = str(item) if isinstance(item, str) else ""
            tag = tag.strip().lower()
            if tag:
                counts[tag] += 1
    if not counts:
        return None
    max_v = max(counts.values())
    # Deterministic tie-break: alphabetical
    return sorted(k for k, v in counts.items() if v == max_v)[0]


def _intraday_confidence(reviewed_count: int) -> str:
    """Return confidence label for an intraday block."""
    if reviewed_count < 5:
        return "INSUFFICIENT"
    if reviewed_count < 20:
        return "EARLY"
    if reviewed_count < 50:
        return "MODERATE"
    return "STRONG"


@app.route("/journal/coaching/intraday", methods=["GET"])
def journal_coaching_intraday():
    """Intraday 30-minute block coaching analytics — DISPLAY-ONLY (Phase 7O.2).

    Returns one block per 30-minute window that has at least one matching trade.
    Blocks with zero trades are omitted from the response.

    Query params (same subset as /journal/coaching):
      date_from, date_to, instrument, strategy, mode, session, source, review_status
    Additional:
      display_timezone  (IANA timezone string; default America/New_York)
    """
    conn, err = _journal_db_guard()
    if err:
        return err

    date_from     = (request.args.get("date_from")      or "").strip()
    date_to       = (request.args.get("date_to")        or "").strip()
    f_instrument  = (request.args.get("instrument")     or "").strip()
    f_mode        = (request.args.get("mode")           or "").strip().upper()
    f_source      = (request.args.get("source")         or "").strip().lower()
    f_strategy    = (request.args.get("strategy")       or "").strip()
    f_session     = (request.args.get("session")        or "").strip().lower()
    f_review      = (request.args.get("review_status")  or "").strip().upper()
    raw_tz        = (request.args.get("display_timezone") or "").strip() or "America/New_York"
    try:
        ZoneInfo(raw_tz)
        display_tz = raw_tz
    except Exception:
        display_tz = "America/New_York"

    # Build filter clauses applied after the CTE.
    # Date bounds compare the LOCAL calendar date in display_tz (not the UTC wall clock),
    # matching the convention in _COACHING_BASE_CTE where trade_date is pre-converted
    # to the display timezone before filtering.  entry_ts is a naive UTC timestamp
    # (importer contract), so AT TIME ZONE 'UTC' normalises it to timestamptz, then
    # AT TIME ZONE display_tz converts to the local day before the ::date cast.
    f_clauses: list = []
    f_params:  list = []
    if date_from:
        f_clauses.append(
            "(entry_ts AT TIME ZONE 'UTC' AT TIME ZONE %s)::date >= %s::date"
        )
        f_params += [display_tz, date_from]
    if date_to:
        # inclusive: local date in display_tz must be on or before date_to
        f_clauses.append(
            "(entry_ts AT TIME ZONE 'UTC' AT TIME ZONE %s)::date <= %s::date"
        )
        f_params += [display_tz, date_to]
    if f_instrument:
        f_clauses.append("instrument ILIKE %s")
        f_params.append(f"%{f_instrument}%")
    if f_mode:
        f_clauses.append("UPPER(mode) = %s")
        f_params.append(f_mode)
    if f_source in ("system", "tradzella"):
        f_clauses.append("source = %s")
        f_params.append(f_source)
    if f_strategy:
        f_clauses.append("strategy_name ILIKE %s")
        f_params.append(f"%{f_strategy}%")
    if f_review:
        f_clauses.append("review_status = %s")
        f_params.append(f_review)

    fa = (" WHERE " + " AND ".join(f_clauses)) if f_clauses else ""

    sql = f"{_INTRADAY_BASE_CTE} SELECT * FROM base{fa} ORDER BY entry_ts"

    try:
        with conn.cursor() as cur:
            cur.execute(sql, f_params)
            cols = [d[0] for d in cur.description]
            rows = [dict(zip(cols, r)) for r in cur.fetchall()]
    except Exception as exc:
        logger.warning("journal_coaching_intraday query failed: %s", exc)
        return jsonify({"ok": False, "error": "intraday query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass

    # ── Bucket rows in Python via _intraday_bucket() ──────────────────────
    from collections import defaultdict
    blocks: dict = defaultdict(list)
    for row in rows:
        ts  = row.get("entry_ts")
        bkt = _intraday_bucket(ts, display_tz)
        if bkt is None:
            continue
        block_start, block_end, label = bkt
        key = block_start  # HH:MM as dict key
        row["_block_start"] = block_start
        row["_block_end"]   = block_end
        row["_label"]       = label
        blocks[key].append(row)

    # ── Aggregate per block ────────────────────────────────────────────────
    result_blocks = []
    for block_start in sorted(blocks.keys()):
        brows = blocks[block_start]
        sample = brows[0]

        trade_count    = len(brows)
        reviewed_rows  = [r for r in brows if (r.get("review_status") or "") == "REVIEWED"]
        reviewed_count = len(reviewed_rows)
        confidence     = _intraday_confidence(reviewed_count)

        # P&L / R metrics (closed trades — i.e. all rows here, since CTE filters closed_at IS NOT NULL)
        wins      = sum(1 for r in brows if (r.get("result") or "") in _WIN_SET)
        losses    = sum(1 for r in brows if (r.get("result") or "") in _LOSS_SET)
        breakeven = sum(1 for r in brows if (r.get("result") or "") in _SCRATCH_SET)

        all_r     = [float(r["r_multiple"]) for r in brows if r.get("r_multiple") is not None]
        win_r     = [float(r["r_multiple"]) for r in brows
                     if (r.get("result") or "") in _WIN_SET and r.get("r_multiple") is not None]
        loss_r    = [abs(float(r["r_multiple"])) for r in brows
                     if (r.get("result") or "") in _LOSS_SET and r.get("r_multiple") is not None]

        net_r     = round(sum(all_r), 2)            if all_r    else 0.0
        avg_r     = round(sum(all_r) / len(all_r), 2) if all_r  else 0.0
        avg_win_r = round(sum(win_r) / len(win_r), 2) if win_r  else 0.0
        avg_loss_r= round(sum(loss_r) / len(loss_r), 2) if loss_r else 0.0
        win_rate  = round(wins / (wins + losses + breakeven), 3) if (wins + losses + breakeven) > 0 else 0.0
        pf        = _coaching_pf(sum(win_r), sum(loss_r))
        expectancy= round(avg_r, 3)

        # Discipline metrics (reviewed rows only)
        fp_yes    = sum(1 for r in reviewed_rows if (r.get("followed_plan") or "") == "YES")
        fp_partial= sum(1 for r in reviewed_rows if (r.get("followed_plan") or "") == "PARTIALLY")
        fp_no     = sum(1 for r in reviewed_rows if (r.get("followed_plan") or "") == "NO")
        fp_rate   = round(fp_yes / reviewed_count, 3) if reviewed_count else 0.0

        def _safe_avg(field):
            vals = [float(r[field]) for r in reviewed_rows if r.get(field) is not None]
            return round(sum(vals) / len(vals), 2) if vals else None

        avg_setup    = _safe_avg("setup_quality")
        avg_exec     = _safe_avg("execution_quality")
        avg_disc     = _safe_avg("discipline_quality")
        avg_overall  = _safe_avg("overall_quality")

        # Per-mistake/emotion/positive tag counts across reviewed rows
        n_tags = reviewed_count or 1
        top_mistake  = _top_tag_from_jsonb_list(reviewed_rows, "mistake_tags",  is_emotion=False)
        top_emotion  = _top_tag_from_jsonb_list(reviewed_rows, "emotion_tags",   is_emotion=True)
        top_positive = _top_tag_from_jsonb_list(reviewed_rows, "positive_tags",  is_emotion=False)

        # Mistake + positive concentration per trade (reviewed only)
        from collections import Counter as _Counter
        m_counts: _Counter = _Counter()
        e_counts: _Counter = _Counter()
        for r in reviewed_rows:
            for raw_f, is_em in [("mistake_tags", False), ("emotion_tags", True)]:
                raw = r.get(raw_f)
                if not raw:
                    continue
                items = raw if isinstance(raw, list) else []
                if not items:
                    try:
                        import json as _jj; items = _jj.loads(raw)
                    except Exception:
                        items = []
                for item in items:
                    tag = (item.get("tag") if isinstance(item, dict) and is_em else str(item) if isinstance(item, str) else "")
                    if tag:
                        m_counts[tag.lower()] += 1 if not is_em else 0
                        e_counts[tag.lower()] += 1 if is_em else 0
        mistake_per_trade = round(sum(m_counts.values()) / reviewed_count, 2) if reviewed_count else 0.0

        # Strategy breakdown: top by net R within block
        strat_r: dict = {}
        for r in brows:
            s = (r.get("strategy_name") or "UNKNOWN").strip() or "UNKNOWN"
            strat_r.setdefault(s, 0.0)
            strat_r[s] += float(r.get("r_multiple") or 0.0)
        top_strategy_by_r  = max(strat_r, key=strat_r.get, default=None) if strat_r else None
        worst_strategy_by_r= min(strat_r, key=strat_r.get, default=None) if strat_r else None

        # Instrument breakdown
        inst_r: dict = {}
        for r in brows:
            i = (r.get("instrument") or "UNKNOWN").strip().upper() or "UNKNOWN"
            inst_r.setdefault(i, 0.0)
            inst_r[i] += float(r.get("r_multiple") or 0.0)
        top_instrument    = max(inst_r, key=inst_r.get, default=None) if inst_r else None
        worst_instrument  = min(inst_r, key=inst_r.get, default=None) if inst_r else None

        # Long/Short split
        long_rows  = [r for r in brows if (r.get("direction") or "").lower() in ("long", "buy")]
        short_rows = [r for r in brows if (r.get("direction") or "").lower() in ("short", "sell")]
        long_net_r = round(sum(float(r.get("r_multiple") or 0) for r in long_rows), 2)
        short_net_r= round(sum(float(r.get("r_multiple") or 0) for r in short_rows), 2)

        result_blocks.append({
            "block_start":         block_start,
            "block_end":           sample["_block_end"],
            "label":               sample["_label"],
            "display_timezone":    display_tz,
            "trade_count":         trade_count,
            "reviewed_count":      reviewed_count,
            "confidence":          confidence,
            "wins":                wins,
            "losses":              losses,
            "breakeven":           breakeven,
            "win_rate":            win_rate,
            "net_r":               net_r,
            "avg_r":               avg_r,
            "avg_win_r":           avg_win_r,
            "avg_loss_r":          avg_loss_r,
            "expectancy":          expectancy,
            "profit_factor":       pf,
            "followed_plan_yes":   fp_yes,
            "followed_plan_partial": fp_partial,
            "followed_plan_no":    fp_no,
            "followed_plan_rate":  fp_rate,
            "avg_setup_quality":   avg_setup,
            "avg_exec_quality":    avg_exec,
            "avg_disc_quality":    avg_disc,
            "avg_overall_quality": avg_overall,
            "mistake_per_trade":   mistake_per_trade,
            "top_mistake":         top_mistake,
            "top_emotion":         top_emotion,
            "top_positive":        top_positive,
            "top_strategy_by_r":   top_strategy_by_r,
            "worst_strategy_by_r": worst_strategy_by_r,
            "top_instrument":      top_instrument,
            "worst_instrument":    worst_instrument,
            "long_count":          len(long_rows),
            "short_count":         len(short_rows),
            "long_net_r":          long_net_r,
            "short_net_r":         short_net_r,
        })

    # ── Deterministic coaching summary sentences ────────────────────────────
    moderate_plus = [b for b in result_blocks
                     if b["confidence"] in ("MODERATE", "STRONG") and b["reviewed_count"] >= 20]
    summary: list[str] = []
    if moderate_plus:
        # Best window: highest win_rate (tie-break: most reviewed trades)
        best_w = max(moderate_plus,
                     key=lambda b: (b["win_rate"], b["reviewed_count"]), default=None)
        if best_w and best_w["win_rate"] > 0:
            summary.append(
                f"Best window: {best_w['label']} produces a {best_w['win_rate']*100:.0f}% "
                f"win rate across {best_w['reviewed_count']} reviewed trades."
            )
        # Biggest time leak: most negative net_r (tie-break: most reviewed trades)
        neg_blocks = [b for b in moderate_plus if b["net_r"] < 0]
        if neg_blocks:
            leak = min(neg_blocks, key=lambda b: (b["net_r"], -b["reviewed_count"]))
            summary.append(
                f"Biggest time leak: {leak['label']} drains {abs(leak['net_r']):.1f}R "
                f"on average — consider sitting it out."
            )
        # Discipline peak: highest followed_plan_rate (tie-break: most reviewed)
        disc_blocks = [b for b in moderate_plus if b["reviewed_count"] > 0]
        if disc_blocks:
            disc = max(disc_blocks,
                       key=lambda b: (b["followed_plan_rate"], b["reviewed_count"]))
            if disc["followed_plan_rate"] > 0.5:
                summary.append(
                    f"Discipline peak: {disc['label']} is your most disciplined window "
                    f"({disc['followed_plan_rate']*100:.0f}% plan adherence)."
                )

    return jsonify({
        "ok":             True,
        "blocks":         result_blocks,
        "display_timezone": display_tz,
        "intraday_summary": summary[:3],
    })


# ---------------------------------------------------------------------------
# Phase 7O.3 — Rating × Mistake/Emotion Correlation Analytics (display-only)
# ---------------------------------------------------------------------------
# STRICT SCOPE: pure SELECT only. No learning, gate, scoring, execution, or
# TradersPost paths reachable. All SQL parameterised; rating_field validated
# against _RATING_FIELDS allowlist before interpolation.
# ---------------------------------------------------------------------------

@app.route("/journal/coaching/correlations", methods=["GET"])
def journal_coaching_correlations():
    """Journal Coaching — Rating × Mistake/Emotion Correlation Analytics.

    DISPLAY-ONLY. Pure SELECT. Never touches learning, gate, scoring, or
    execution. Inherits the same filter contract as /journal/coaching.

    Query params:
      date_from, date_to  YYYY-MM-DD (inclusive, America/New_York dates)
      instrument           partial match (ILIKE)
      mode                 exact (SCALP | SWING | MICRO_SCALP)
      source               system | tradzella | '' = all

    Response sections:
      coverage, rating_mistake, rating_emotion, setup_execution_matrix,
      discipline_outcomes, discipline_summary, high_quality_losses,
      low_quality_wins, expensive_combinations, correlation_summary
    """
    import itertools as _itools
    import json as _json

    conn, err = _journal_db_guard()
    if err:
        return err

    date_from    = (request.args.get("date_from") or "").strip()
    date_to      = (request.args.get("date_to")   or "").strip()
    f_instrument = (request.args.get("instrument") or "").strip()
    f_mode       = (request.args.get("mode")       or "").strip().upper()
    f_source     = (request.args.get("source")     or "").strip().lower()

    # Build filter clauses — same contract as /journal/coaching
    f_clauses: list = []
    f_params:  list = []
    if date_from:
        f_clauses.append("trade_date::date >= %s")
        f_params.append(date_from)
    if date_to:
        f_clauses.append("trade_date::date <= %s")
        f_params.append(date_to)
    if f_instrument:
        f_clauses.append("instrument ILIKE %s")
        f_params.append(f"%{f_instrument}%")
    if f_mode:
        f_clauses.append("UPPER(mode) = %s")
        f_params.append(f_mode)
    if f_source in ("system", "tradzella"):
        f_clauses.append("source = %s")
        f_params.append(f_source)

    fa  = (" AND " + " AND ".join(f_clauses)) if f_clauses else ""
    CTE = _COACHING_BASE_CTE
    WIN_SQL = _COACHING_WIN_RESULTS_SQL

    def _run(cur, sql, extra_params=()):
        p = list(f_params) + list(extra_params)
        cur.execute(sql, p)
        cols = [d[0] for d in cur.description]
        return [dict(zip(cols, r)) for r in cur.fetchall()]

    def _band(r) -> str | None:
        """Rating integer 1–5 → 'LOW' | 'MEDIUM' | 'HIGH'."""
        if r is None:
            return None
        if r <= 2:
            return "LOW"
        if r == 3:
            return "MEDIUM"
        return "HIGH"

    _CORR_RATING_FIELDS = ("setup_quality", "execution_quality",
                           "discipline_quality", "overall_quality")

    try:
        with conn.cursor() as cur:

            # ── 1. Coverage ──────────────────────────────────────────────────
            cov_rows = _run(cur, CTE + f"""
                SELECT
                  COUNT(*) FILTER (WHERE review_status='REVIEWED')
                    AS reviewed,
                  COUNT(*) FILTER (WHERE review_status='REVIEWED'
                    AND setup_quality IS NOT NULL)
                    AS with_setup,
                  COUNT(*) FILTER (WHERE review_status='REVIEWED'
                    AND execution_quality IS NOT NULL)
                    AS with_execution,
                  COUNT(*) FILTER (WHERE review_status='REVIEWED'
                    AND discipline_quality IS NOT NULL)
                    AS with_discipline,
                  COUNT(*) FILTER (WHERE review_status='REVIEWED'
                    AND overall_quality IS NOT NULL)
                    AS with_overall,
                  COUNT(*) FILTER (WHERE review_status='REVIEWED'
                    AND mistake_tags IS NOT NULL
                    AND jsonb_typeof(mistake_tags)='array'
                    AND jsonb_array_length(mistake_tags)>0)
                    AS with_mistakes,
                  COUNT(*) FILTER (WHERE review_status='REVIEWED'
                    AND emotion_tags IS NOT NULL
                    AND jsonb_typeof(emotion_tags)='array'
                    AND jsonb_array_length(emotion_tags)>0)
                    AS with_emotions,
                  COUNT(*) FILTER (WHERE review_status<>'REVIEWED')
                    AS excluded
                FROM base WHERE 1=1{fa}
            """)
            cov = cov_rows[0] if cov_rows else {}
            coverage = {
                "reviewed":        int(cov.get("reviewed")        or 0),
                "with_setup":      int(cov.get("with_setup")      or 0),
                "with_execution":  int(cov.get("with_execution")  or 0),
                "with_discipline": int(cov.get("with_discipline") or 0),
                "with_overall":    int(cov.get("with_overall")    or 0),
                "with_mistakes":   int(cov.get("with_mistakes")   or 0),
                "with_emotions":   int(cov.get("with_emotions")   or 0),
                "excluded":        int(cov.get("excluded")        or 0),
            }

            # ── 2. Rating × Mistake Matrix ───────────────────────────────────
            # For each rating field: aggregate (rating_value, mistake_tag) cells.
            # Percentage is relative to all trades in that band (not just those
            # with mistakes) to preserve the "x% of LOW-discipline trades" meaning.
            rating_mistake: list = []
            for field in _CORR_RATING_FIELDS:
                # Band totals — denominator for band_pct
                bt_rows = _run(cur, CTE + f"""
                    SELECT {field}::int AS rating, COUNT(*) AS n
                    FROM base
                    WHERE review_status='REVIEWED'
                      AND {field} IS NOT NULL{fa}
                    GROUP BY {field}::int
                """)
                band_totals = {row["rating"]: int(row["n"]) for row in bt_rows}

                mx_rows = _run(cur, CTE + f"""
                    SELECT {field}::int AS rating,
                      tag,
                      COUNT(*)::int                                              AS n,
                      SUM(CASE WHEN result IN {WIN_SQL}
                               THEN 1 ELSE 0 END)::int                          AS wins,
                      ROUND(SUM(COALESCE(r_multiple,0))::numeric,3)::float      AS net_r,
                      ROUND(AVG(r_multiple)::numeric,3)::float                  AS avg_r,
                      ROUND(100.0*SUM(CASE WHEN followed_plan='YES'
                               THEN 1 ELSE 0 END)::numeric
                            /NULLIF(COUNT(*),0),1)::float                        AS followed_plan_pct
                    FROM base,
                         jsonb_array_elements_text(mistake_tags) AS tag
                    WHERE review_status='REVIEWED'
                      AND {field} IS NOT NULL
                      AND mistake_tags IS NOT NULL
                      AND jsonb_typeof(mistake_tags)='array'{fa}
                    GROUP BY {field}::int, tag
                    ORDER BY {field}::int, net_r ASC
                """)
                for row in mx_rows:
                    rating = int(row["rating"])
                    n      = int(row["n"] or 0)
                    wins   = int(row["wins"] or 0)
                    bt     = band_totals.get(rating, 0)
                    row["rating_field"]    = field
                    row["band"]            = _band(rating)
                    row["band_pct"]        = round(n / bt * 100, 1) if bt else None
                    row["win_rate"]        = round(wins / n * 100, 1) if n else None
                    row["confidence"]      = _coaching_confidence(n)
                    rating_mistake.append(row)

            # ── 3. Rating × Emotion Matrix ───────────────────────────────────
            rating_emotion: list = []
            for field in _CORR_RATING_FIELDS:
                bt_rows = _run(cur, CTE + f"""
                    SELECT {field}::int AS rating, COUNT(*) AS n
                    FROM base
                    WHERE review_status='REVIEWED'
                      AND {field} IS NOT NULL{fa}
                    GROUP BY {field}::int
                """)
                band_totals = {row["rating"]: int(row["n"]) for row in bt_rows}

                em_rows = _run(cur, CTE + f"""
                    SELECT {field}::int AS rating,
                      elem->>'tag'                                                AS emotion,
                      COUNT(*)::int                                              AS n,
                      ROUND(AVG((elem->>'intensity')::float)::numeric,2)::float  AS avg_intensity,
                      SUM(CASE WHEN result IN {WIN_SQL}
                               THEN 1 ELSE 0 END)::int                          AS wins,
                      ROUND(SUM(COALESCE(r_multiple,0))::numeric,3)::float      AS net_r,
                      ROUND(AVG(r_multiple)::numeric,3)::float                  AS avg_r,
                      ROUND(100.0*SUM(CASE WHEN followed_plan='YES'
                               THEN 1 ELSE 0 END)::numeric
                            /NULLIF(COUNT(*),0),1)::float                        AS followed_plan_pct
                    FROM base,
                         jsonb_array_elements(emotion_tags) AS elem
                    WHERE review_status='REVIEWED'
                      AND {field} IS NOT NULL
                      AND emotion_tags IS NOT NULL
                      AND jsonb_typeof(emotion_tags)='array'{fa}
                    GROUP BY {field}::int, elem->>'tag'
                    ORDER BY {field}::int, net_r ASC
                """)

                # Mistake overlap: top mistake co-occurring with each (rating, emotion)
                ov_rows = _run(cur, CTE + f"""
                    SELECT {field}::int AS rating,
                      elem->>'tag' AS emotion, tag AS mistake,
                      COUNT(*)::int AS cnt
                    FROM base,
                         jsonb_array_elements(emotion_tags) AS elem,
                         jsonb_array_elements_text(mistake_tags) AS tag
                    WHERE review_status='REVIEWED'
                      AND {field} IS NOT NULL
                      AND emotion_tags IS NOT NULL
                      AND jsonb_typeof(emotion_tags)='array'
                      AND mistake_tags IS NOT NULL
                      AND jsonb_typeof(mistake_tags)='array'{fa}
                    GROUP BY {field}::int, elem->>'tag', tag
                """)
                # overlap_map: {(rating, emotion): sorted [(mistake, cnt), ...]}
                overlap_map: dict = {}
                for ov in ov_rows:
                    k = (int(ov["rating"]), ov["emotion"])
                    overlap_map.setdefault(k, []).append(
                        (ov["mistake"], int(ov["cnt"]))
                    )
                for k in overlap_map:
                    overlap_map[k].sort(key=lambda x: (-x[1], x[0]))

                for row in em_rows:
                    rating  = int(row["rating"])
                    n       = int(row["n"] or 0)
                    wins    = int(row["wins"] or 0)
                    bt      = band_totals.get(rating, 0)
                    top     = overlap_map.get((rating, row["emotion"]), [])
                    row["rating_field"]     = field
                    row["band"]             = _band(rating)
                    row["band_pct"]         = round(n / bt * 100, 1) if bt else None
                    row["win_rate"]         = round(wins / n * 100, 1) if n else None
                    row["confidence"]       = _coaching_confidence(n)
                    row["top_mistake"]      = top[0][0] if top else None
                    row["top_mistake_pct"]  = (
                        round(top[0][1] / n * 100, 1) if top and n else None
                    )
                    rating_emotion.append(row)

            # ── 4. Setup × Execution Matrix (5×5) ───────────────────────────
            matrix_rows = _run(cur, CTE + f"""
                SELECT setup_quality::int AS setup_q,
                  execution_quality::int  AS exec_q,
                  COUNT(*)::int                                              AS n,
                  ROUND(AVG(r_multiple)::numeric,3)::float                  AS avg_r,
                  SUM(CASE WHEN result IN {WIN_SQL}
                           THEN 1 ELSE 0 END)::int                          AS wins,
                  ROUND(100.0*SUM(CASE WHEN followed_plan='YES'
                           THEN 1 ELSE 0 END)::numeric
                        /NULLIF(COUNT(*),0),1)::float                        AS followed_plan_pct
                FROM base
                WHERE review_status='REVIEWED'
                  AND setup_quality IS NOT NULL
                  AND execution_quality IS NOT NULL{fa}
                GROUP BY setup_q, exec_q ORDER BY setup_q, exec_q
            """)

            # Top mistake per (setup_q, exec_q) cell — deterministic alphabetical tie-break
            cell_mx_rows = _run(cur, CTE + f"""
                SELECT setup_quality::int AS setup_q,
                  execution_quality::int  AS exec_q,
                  tag, COUNT(*)::int AS cnt
                FROM base,
                     jsonb_array_elements_text(mistake_tags) AS tag
                WHERE review_status='REVIEWED'
                  AND setup_quality IS NOT NULL
                  AND execution_quality IS NOT NULL
                  AND mistake_tags IS NOT NULL
                  AND jsonb_typeof(mistake_tags)='array'{fa}
                GROUP BY 1, 2, 3
            """)
            cell_mx_map: dict = {}  # {(sq, eq): (top_tag, cnt)}
            for r in cell_mx_rows:
                k = (int(r["setup_q"]), int(r["exec_q"]))
                existing = cell_mx_map.get(k)
                cnt = int(r["cnt"])
                if (existing is None
                        or cnt > existing[1]
                        or (cnt == existing[1] and r["tag"] < existing[0])):
                    cell_mx_map[k] = (r["tag"], cnt)

            setup_execution_matrix = []
            for row in matrix_rows:
                n    = int(row["n"] or 0)
                wins = int(row["wins"] or 0)
                k    = (int(row["setup_q"]), int(row["exec_q"]))
                top  = cell_mx_map.get(k)
                row["win_rate"]    = round(wins / n * 100, 1) if n else None
                row["confidence"]  = _coaching_confidence(n)
                row["top_mistake"] = top[0] if top else None
                setup_execution_matrix.append(row)

            # ── 5. Discipline Outcomes ───────────────────────────────────────
            disc_rows = _run(cur, CTE + f"""
                SELECT discipline_quality::int AS disc_rating,
                  COUNT(*)::int                                              AS n,
                  SUM(CASE WHEN result IN {WIN_SQL}
                           THEN 1 ELSE 0 END)::int                          AS wins,
                  ROUND(SUM(COALESCE(r_multiple,0))::numeric,3)::float      AS net_r,
                  ROUND(AVG(r_multiple)::numeric,3)::float                  AS avg_r,
                  ROUND(SUM(CASE WHEN r_multiple>0
                           THEN r_multiple ELSE 0 END)::numeric,3)::float   AS sum_pos_r,
                  ROUND(ABS(SUM(CASE WHEN r_multiple<0
                           THEN r_multiple ELSE 0 END))::numeric,3)::float  AS sum_neg_r,
                  ROUND(100.0*SUM(CASE WHEN followed_plan='YES'
                           THEN 1 ELSE 0 END)::numeric
                        /NULLIF(COUNT(*),0),1)::float                        AS followed_plan_pct,
                  ROUND(AVG(CASE
                    WHEN mistake_tags IS NOT NULL
                     AND jsonb_typeof(mistake_tags)='array'
                    THEN jsonb_array_length(mistake_tags) ELSE 0
                  END)::numeric,2)::float                                    AS avg_mistake_count,
                  ROUND(AVG(
                    CASE WHEN emotion_tags IS NOT NULL
                          AND jsonb_typeof(emotion_tags)='array'
                          AND jsonb_array_length(emotion_tags)>0
                    THEN (SELECT AVG((e->>'intensity')::float)
                          FROM jsonb_array_elements(emotion_tags) AS e)
                    END
                  )::numeric,2)::float                                       AS avg_emotion_intensity
                FROM base
                WHERE review_status='REVIEWED'
                  AND discipline_quality IS NOT NULL{fa}
                GROUP BY disc_rating ORDER BY disc_rating
            """)
            discipline_outcomes = []
            low_avg_r: float | None  = None
            high_avg_r: float | None = None
            for row in disc_rows:
                n    = int(row["n"] or 0)
                wins = int(row["wins"] or 0)
                row["win_rate"]     = round(wins / n * 100, 1) if n else None
                row["confidence"]   = _coaching_confidence(n)
                row["profit_factor"] = _coaching_pf(row.get("sum_pos_r") or 0,
                                                    row.get("sum_neg_r") or 0)
                disc = int(row.get("disc_rating") or 0)
                if disc <= 2 and n >= 5:
                    low_avg_r  = row.get("avg_r")
                if disc >= 4 and n >= 5:
                    high_avg_r = row.get("avg_r")
                discipline_outcomes.append(row)

            # Deterministic discipline summary sentence (only when ≥5 trades in each band)
            disc_summary: str | None = None
            if low_avg_r is not None and high_avg_r is not None:
                s_hi = "+" if (high_avg_r or 0) >= 0 else ""
                s_lo = "+" if (low_avg_r  or 0) >= 0 else ""
                disc_summary = (
                    f"Trades rated discipline 4–5 averaged {s_hi}{high_avg_r:.2f}R. "
                    f"Trades rated discipline 1–2 averaged {s_lo}{low_avg_r:.2f}R."
                )

            # ── 6. High-Quality Losses ───────────────────────────────────────
            # setup 4–5, execution 4–5, discipline 4–5, followed_plan=YES, R < 0
            hql_rows = _run(cur, CTE + f"""
                SELECT trade_id, source, instrument, strategy_name, session,
                  r_multiple, result,
                  setup_quality::int      AS setup_quality,
                  execution_quality::int  AS execution_quality,
                  discipline_quality::int AS discipline_quality,
                  overall_quality::int    AS overall_quality,
                  followed_plan,
                  reviewed_at::text AS reviewed_at
                FROM base
                WHERE review_status='REVIEWED'
                  AND setup_quality      BETWEEN 4 AND 5
                  AND execution_quality  BETWEEN 4 AND 5
                  AND discipline_quality BETWEEN 4 AND 5
                  AND followed_plan='YES'
                  AND r_multiple < 0{fa}
                ORDER BY r_multiple ASC
            """)
            hql_strats: list = []
            hql_insts:  list = []
            hql_total_r = 0.0
            for row in hql_rows:
                hql_total_r += float(row.get("r_multiple") or 0)
                s = row.get("strategy_name")
                if s and s not in hql_strats:
                    hql_strats.append(s)
                i = row.get("instrument")
                if i and i not in hql_insts:
                    hql_insts.append(i)
            hql_avg_r = round(hql_total_r / len(hql_rows), 3) if hql_rows else None

            high_quality_losses = {
                "count":       len(hql_rows),
                "avg_r":       hql_avg_r,
                "strategies":  hql_strats,
                "instruments": hql_insts,
                "trades":      hql_rows[:20],
                "confidence":  _coaching_confidence(len(hql_rows)),
            }

            # ── 7. Low-Quality Wins ──────────────────────────────────────────
            # R > 0 AND (disc 1–2 OR exec 1–2 OR followed_plan=NO OR any mistake)
            lqw_rows = _run(cur, CTE + f"""
                SELECT trade_id, source, instrument, strategy_name, session,
                  r_multiple, result,
                  setup_quality::int      AS setup_quality,
                  execution_quality::int  AS execution_quality,
                  discipline_quality::int AS discipline_quality,
                  followed_plan,
                  reviewed_at::text AS reviewed_at
                FROM base
                WHERE review_status='REVIEWED'
                  AND r_multiple > 0
                  AND (
                    (discipline_quality IS NOT NULL
                     AND discipline_quality BETWEEN 1 AND 2)
                    OR (execution_quality IS NOT NULL
                        AND execution_quality BETWEEN 1 AND 2)
                    OR followed_plan='NO'
                    OR (mistake_tags IS NOT NULL
                        AND jsonb_typeof(mistake_tags)='array'
                        AND jsonb_array_length(mistake_tags) > 0)
                  ){fa}
                ORDER BY r_multiple DESC
            """)
            # Aggregate mistake + emotion frequency for LQW
            lqw_mistake_counts: dict = {}
            lqw_emotion_counts: dict = {}
            lqw_total_r = 0.0
            for row in lqw_rows:
                lqw_total_r += float(row.get("r_multiple") or 0)
            # Fetch tag breakdowns for LQW trades separately (avoid JSONB in outer query)
            if lqw_rows:
                lqw_ids = [row["trade_id"] for row in lqw_rows]
                lqw_ids_placeholder = ",".join(["%s"] * len(lqw_ids))
                lqw_mt_rows = _run(cur, CTE + f"""
                    SELECT trade_id, mistake_tags, emotion_tags
                    FROM base
                    WHERE trade_id IN ({lqw_ids_placeholder})
                      AND review_status='REVIEWED'
                """, tuple(lqw_ids))
                for row in lqw_mt_rows:
                    mt = row.get("mistake_tags")
                    if mt:
                        try:
                            tags = _json.loads(mt) if isinstance(mt, str) else mt
                            if isinstance(tags, list):
                                for t in tags:
                                    lqw_mistake_counts[t] = (
                                        lqw_mistake_counts.get(t, 0) + 1
                                    )
                        except Exception:
                            pass
                    et = row.get("emotion_tags")
                    if et:
                        try:
                            elems = _json.loads(et) if isinstance(et, str) else et
                            if isinstance(elems, list):
                                for e in elems:
                                    tag = (e.get("tag") if isinstance(e, dict)
                                           else None)
                                    if tag:
                                        lqw_emotion_counts[tag] = (
                                            lqw_emotion_counts.get(tag, 0) + 1
                                        )
                        except Exception:
                            pass

            top_lqw_mistake = (
                max(lqw_mistake_counts, key=lambda k: (lqw_mistake_counts[k], k))
                if lqw_mistake_counts else None
            )
            top_lqw_emotion = (
                max(lqw_emotion_counts, key=lambda k: (lqw_emotion_counts[k], k))
                if lqw_emotion_counts else None
            )
            low_quality_wins = {
                "count":       len(lqw_rows),
                "net_r":       round(lqw_total_r, 3) if lqw_rows else None,
                "top_mistake": top_lqw_mistake,
                "top_emotion": top_lqw_emotion,
                "trades":      lqw_rows[:20],
                "confidence":  _coaching_confidence(len(lqw_rows)),
            }

            # ── 8. Expensive Combinations ────────────────────────────────────
            # Fetch all reviewed trades with tag/rating data for Python-side pairing
            combo_src = _run(cur, CTE + f"""
                SELECT r_multiple, result, followed_plan,
                  mistake_tags, emotion_tags,
                  discipline_quality::int AS discipline_quality,
                  execution_quality::int  AS execution_quality,
                  reviewed_at::text AS reviewed_at
                FROM base
                WHERE review_status='REVIEWED'
                  AND r_multiple IS NOT NULL{fa}
            """)

            from collections import defaultdict as _ddict
            combo_map: dict = _ddict(lambda: {
                "n": 0, "net_r": 0.0, "wins": 0, "dates": []
            })

            def _parse_tokens(row):
                """Extract all combination tokens from a reviewed trade row."""
                tokens: list = []
                mt = row.get("mistake_tags")
                if mt:
                    try:
                        tags = _json.loads(mt) if isinstance(mt, str) else mt
                        if isinstance(tags, list):
                            tokens += [f"MISTAKE:{t}" for t in tags]
                    except Exception:
                        pass
                et = row.get("emotion_tags")
                if et:
                    try:
                        elems = _json.loads(et) if isinstance(et, str) else et
                        if isinstance(elems, list):
                            tokens += [
                                f"EMOTION:{e['tag']}"
                                for e in elems
                                if isinstance(e, dict) and e.get("tag")
                            ]
                    except Exception:
                        pass
                disc = row.get("discipline_quality")
                exc  = row.get("execution_quality")
                if disc is not None and disc <= 2:
                    tokens.append("RATING:LOW_DISCIPLINE")
                if exc is not None and exc <= 2:
                    tokens.append("RATING:LOW_EXECUTION")
                if (row.get("followed_plan") or "") == "NO":
                    tokens.append("PLAN:NO")
                return list(dict.fromkeys(tokens))  # deduplicate, preserve order

            for row in combo_src:
                r_val   = float(row.get("r_multiple") or 0)
                is_win  = (row.get("result") or "") in {
                    "win", "scratch", "be", "breakeven", "b/e"
                }
                rev_date = str(row.get("reviewed_at") or "")[:10]
                tokens  = _parse_tokens(row)
                if len(tokens) < 2:
                    continue
                seen_pairs: set = set()
                for a, b in _itools.combinations(sorted(set(tokens)), 2):
                    pair_key = f"{a} + {b}"
                    if pair_key in seen_pairs:
                        continue
                    seen_pairs.add(pair_key)
                    c = combo_map[pair_key]
                    c["n"]      += 1
                    c["net_r"]  += r_val
                    c["wins"]   += int(is_win)
                    if rev_date:
                        c["dates"].append(rev_date)

            expensive_combinations = []
            for key, d in combo_map.items():
                n    = d["n"]
                if n < 2:
                    continue
                net_r = round(d["net_r"], 3)
                wins  = d["wins"]
                recent = sorted(set(d["dates"]), reverse=True)[:5]
                expensive_combinations.append({
                    "combo":      key,
                    "n":          n,
                    "net_r":      net_r,
                    "avg_r":      round(d["net_r"] / n, 3) if n else None,
                    "win_rate":   round(wins / n * 100, 1) if n else None,
                    "recent":     recent,
                    "confidence": _coaching_confidence(n),
                })
            # Sort by net_r ascending (most expensive / most negative first)
            expensive_combinations.sort(key=lambda x: (x["net_r"] or 0))
            expensive_combinations = expensive_combinations[:15]

            # ── 9. Coaching Summary (Part 14) ────────────────────────────────
            correlation_summary: list = []
            hql_n = high_quality_losses["count"]
            if hql_n >= 5:
                avg_r_str = (f" Average: {hql_avg_r:.2f}R."
                             if hql_avg_r is not None else "")
                correlation_summary.append(
                    f"PROCESS WIN: {hql_n} high-quality losses followed the "
                    f"plan despite negative outcomes.{avg_r_str}"
                )
            lqw_n = low_quality_wins["count"]
            if lqw_n >= 5:
                extra = (
                    f" Most often involved "
                    f"{top_lqw_emotion.replace('_',' ').title()}."
                    if top_lqw_emotion else ""
                )
                correlation_summary.append(
                    f"DANGEROUS WIN: {lqw_n} profitable trades showed "
                    f"low-quality process.{extra}"
                )
            if expensive_combinations and expensive_combinations[0]["n"] >= 5:
                c      = expensive_combinations[0]
                pretty = (
                    c["combo"]
                    .replace("MISTAKE:", "")
                    .replace("EMOTION:", "")
                    .replace("RATING:", "")
                    .replace("PLAN:NO", "NO PLAN")
                    .replace("_", " ")
                )
                correlation_summary.append(
                    f"BIGGEST COMBINATION LEAK: {pretty} was associated with "
                    f"{c['net_r']:.1f}R across {c['n']} trades."
                )

            return jsonify({
                "ok":                      True,
                "coverage":                coverage,
                "rating_mistake":          rating_mistake,
                "rating_emotion":          rating_emotion,
                "setup_execution_matrix":  setup_execution_matrix,
                "discipline_outcomes":     discipline_outcomes,
                "discipline_summary":      disc_summary,
                "high_quality_losses":     high_quality_losses,
                "low_quality_wins":        low_quality_wins,
                "expensive_combinations":  expensive_combinations,
                "correlation_summary":     correlation_summary,
            })

    except Exception as exc:
        logger.warning("journal_coaching_correlations failed: %s", exc)
        return jsonify({"ok": False, "error": "correlations query failed"}), 500
    finally:
        try:
            conn.close()
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Phase 7M — Directional Balance (READ-ONLY audit panel, owner-only)
# ---------------------------------------------------------------------------
# Aggregates Long vs Short signal counts from three in-memory sources:
#   1. EVAL_METRICS deque   — direction × verdict (last 24 h of scored alerts)
#   2. ALERT_HISTORY deque  — BOS/CHOCH structure event direction (last 24 h)
#   3. strategy_trades DB   — closed trade direction counts (last 7 days)
# NEVER touches the gate, scoring, sizing, or any money-path variable.
# FAIL-OPEN throughout: any read error yields zeroes, never raises into the caller.
# ---------------------------------------------------------------------------

@app.route("/directional-balance", methods=["GET"])
def directional_balance():
    """Read-only directional audit panel.  Owner-only, display-only."""
    from collections import Counter as _Counter
    now      = datetime.now(timezone.utc)
    cutoff   = now - timedelta(hours=24)

    # ── 1. EVAL_METRICS (last-100 scored alerts, in-memory) ─────────────────
    long_ready = short_ready = long_wait = short_wait = 0
    long_blockers:  "dict[str, int]" = {}
    short_blockers: "dict[str, int]" = {}
    try:
        with EVAL_METRICS_LOCK:
            em_snap = list(EVAL_METRICS)
        for r in em_snap:
            try:
                ts = datetime.fromisoformat(r.get("evaluationFinishedAt") or "")
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                if ts < cutoff:
                    continue
            except (ValueError, TypeError):
                continue
            d       = r.get("direction")
            verdict = str(r.get("verdict") or r.get("decision") or "")
            blocker = str(r.get("gateBlockers") or r.get("waitReason") or "")
            if d == "Long":
                if is_actionable(verdict):
                    long_ready += 1
                else:
                    long_wait += 1
                    if blocker and blocker not in ("READY", "-"):
                        long_blockers[blocker[:60]] = long_blockers.get(blocker[:60], 0) + 1
            elif d == "Short":
                if is_actionable(verdict):
                    short_ready += 1
                else:
                    short_wait += 1
                    if blocker and blocker not in ("READY", "-"):
                        short_blockers[blocker[:60]] = short_blockers.get(blocker[:60], 0) + 1
    except Exception:
        pass

    # ── 2. ALERT_HISTORY (last-1000 alerts, in-memory) ──────────────────────
    _BULLISH_STRUCT = {"BOS DEMAND", "CHOCH DEMAND"}
    _BEARISH_STRUCT = {"BOS SUPPLY", "CHOCH SUPPLY"}
    long_structure = short_structure = 0
    long_ready_alerts = short_ready_alerts = 0
    try:
        for a in list(ALERT_HISTORY):
            try:
                ts = datetime.fromisoformat(a.get("timestamp") or "")
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                if ts < cutoff:
                    continue
            except (ValueError, TypeError):
                continue
            at      = a.get("alert_type") or ""
            verdict = str(a.get("verdict") or "")
            if at in _BULLISH_STRUCT:
                long_structure += 1
            elif at in _BEARISH_STRUCT:
                short_structure += 1
            if "LONG READY" in verdict or "LONG STRONG" in verdict:
                long_ready_alerts += 1
            elif "SHORT READY" in verdict or "SHORT STRONG" in verdict:
                short_ready_alerts += 1
    except Exception:
        pass

    # ── 3. strategy_trades DB (last 7 days, read-only) ──────────────────────
    db_long_total = db_short_total = 0
    db_long_wins  = db_short_wins  = 0
    db_long_avg_r  = db_short_avg_r = None
    try:
        conn = _learning_conn()
        if conn:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT direction,"
                    " COUNT(*) AS cnt,"
                    " SUM(CASE WHEN LOWER(result)='win' THEN 1 ELSE 0 END) AS wins,"
                    " AVG(r_multiple::float) AS avg_r"
                    " FROM strategy_trades"
                    " WHERE opened_at >= NOW() - INTERVAL '7 days'"
                    "   AND direction IS NOT NULL"
                    " GROUP BY direction"
                )
                for row in cur.fetchall():
                    d, cnt, wins, avg_r = row
                    if d == "Long":
                        db_long_total  = int(cnt  or 0)
                        db_long_wins   = int(wins or 0)
                        db_long_avg_r  = round(float(avg_r), 3) if avg_r is not None else None
                    elif d == "Short":
                        db_short_total = int(cnt  or 0)
                        db_short_wins  = int(wins or 0)
                        db_short_avg_r = round(float(avg_r), 3) if avg_r is not None else None
            conn.close()
    except Exception:
        pass

    # ── 4. Candidate direction from strategy scan diagnostics ────────────────
    cand_long = cand_short = 0
    try:
        for _ticker, scan in dict(STRATEGY_SCAN_DIAGNOSTICS_BY_TICKER).items():
            for s in (scan.get("strategies") or []):
                if s.get("result") in ("candidate", "selected"):
                    if s.get("direction") == "Long":
                        cand_long += 1
                    elif s.get("direction") == "Short":
                        cand_short += 1
    except Exception:
        pass

    return jsonify({
        "ok":     True,
        "window": "last_24h (eval_metrics/alerts) / last_7d (trades)",
        "eval_metrics": {
            "long":  {
                "ready": long_ready, "wait": long_wait,
                "top_blockers": sorted(long_blockers.items(),  key=lambda x: -x[1])[:5],
            },
            "short": {
                "ready": short_ready, "wait": short_wait,
                "top_blockers": sorted(short_blockers.items(), key=lambda x: -x[1])[:5],
            },
            "note": ("EVAL_METRICS is an in-memory ring of the last %d scored alerts."
                     % EVAL_METRICS_MAX),
        },
        "structure_events": {
            "long":  long_structure,
            "short": short_structure,
            "note":  "BOS DEMAND + CHOCH DEMAND vs BOS SUPPLY + CHOCH SUPPLY from ALERT_HISTORY.",
        },
        "ready_alerts": {
            "long":  long_ready_alerts,
            "short": short_ready_alerts,
        },
        "scan_candidates": {
            "long":  cand_long,
            "short": cand_short,
            "note":  "Live candidate/selected count from STRATEGY_SCAN_DIAGNOSTICS_BY_TICKER.",
        },
        "trades_7d": {
            "long":  {"total": db_long_total,  "wins": db_long_wins,  "avg_r": db_long_avg_r},
            "short": {"total": db_short_total, "wins": db_short_wins, "avg_r": db_short_avg_r},
            "note":  "strategy_trades closed in the last 7 days.",
        },
    })


# ── ANALYSIS-BOT webhook mirror (opt-in; DEFAULT-OFF) ─────────────────────────
# When ANALYSIS_BOT_FORWARD_URL is set (only on the production VM), every inbound
# /webhook payload is mirrored verbatim to the separate ANALYSIS-ONLY bot so it
# can score the identical alert stream. UNSET (the default — all dev workspaces and
# every golden/parity check) => the mirror block inside webhook() is skipped
# entirely and this live bot is byte-identical to before this feature existed. The
# analysis bot has no forwarder of its own, so no loop is possible; the
# self-forward guard is a belt-and-suspenders backstop against a misconfigured
# loopback URL.
ANALYSIS_BOT_FORWARD_URL = (os.environ.get("ANALYSIS_BOT_FORWARD_URL") or "").strip()


def _is_self_forward(url):
    """True if `url` would route back to THIS live bot (a webhook->webhook loop).
    Catches BOTH the direct case (loopback host + our own PORT) and the proxied
    case (any host whose path is `/api/webhook`, the Express route that always
    proxies to this live bot). The legitimate analysis-bot targets —
    `localhost:8001/webhook` (direct) or `/api2/webhook` (via Express) — are never
    matched. Fail-open: on any parse error return False (treat as not-self) so a
    valid external target is never dropped."""
    try:
        from urllib.parse import urlparse
        u = urlparse(url)
        host = (u.hostname or "").lower()
        path = (u.path or "").rstrip("/").lower()
        # Proxied loop: the Express '/api/webhook' route always proxies to THIS bot,
        # so any host pointing at that path (loopback, the Express port, or the public
        # deployment host) is a loop. '/webhook' and '/api2/webhook' are NOT matched.
        if path == "/api/webhook":
            return True
        target_port = u.port or (443 if u.scheme == "https" else 80)
        my_port = int(os.environ.get("PORT", 8000))
        # Direct loop: same loopback host hitting our own listen port.
        return host in ("localhost", "127.0.0.1", "0.0.0.0", "::1") and target_port == my_port
    except Exception:
        return False


def _forward_to_analysis_bot(raw_body, content_type):
    """Fire-and-forget daemon-thread mirror of a raw webhook to the analysis bot.
    Best-effort and FULLY exception-isolated: it must NEVER block, delay, or alter
    the live webhook response. The caller guards on ANALYSIS_BOT_FORWARD_URL, so
    this is a no-op when the feature is off."""
    url = ANALYSIS_BOT_FORWARD_URL
    if not url or _is_self_forward(url):
        return

    def _task():
        try:
            requests.post(
                url,
                data=(raw_body if raw_body is not None else b""),
                headers={"Content-Type": content_type or "application/json"},
                timeout=5,
            )
        except Exception:
            pass   # the analysis mirror is best-effort; never surface to the live path

    try:
        threading.Thread(target=_task, daemon=True, name="analysis-fwd").start()
    except Exception:
        pass


# ════════════════════════════════════════════════════════════════════════════
# SWING MODE V2 ENGINE — display-only HTF swing scoring + lifecycle system
# ════════════════════════════════════════════════════════════════════════════
# Master flags (both default-OFF → goldens byte-identical):
#   SWING_MODE_V2_ENABLED=1   → activates scoring, lifecycle, dashboard panel
#   SWING_AUTO_EXEC_ENABLED=1 → (reserved) future auto-execution gate
#
# All paths are DISPLAY-ONLY and FAIL-OPEN. Money path (strict gate, sizing,
# execution) is completely untouched. Data sources:
#   Tier 1 (live): HTF_STATE_BY_INST, gate_debug, CVD, RVOL, zone data, VWAP.
#   Tier 2 (Pine): EMA20/50/200 D/4H/W, RSI-D, MACD-D, ADX-D via webhook.
#     Scores 0 honestly for Tier 2 categories until Pine script connected.
# ────────────────────────────────────────────────────────────────────────────

def _swing_v2_regime(inst, d, state):
    """Market regime from HTF bias + EMA + volatility data."""
    htf     = HTF_STATE_BY_INST.get(inst, {})
    d1_bias = str((htf.get("1D") or {}).get("bias", "")).lower()
    h4_bias = str((htf.get("4H") or {}).get("bias", "")).lower()
    daily_bull = state.get("daily_bullish")
    daily_bear = state.get("daily_bearish")
    vol_reg    = str(d.get("volatility") or d.get("vol_regime") or "").lower()
    atr_ratio  = 1.0
    try:
        atr_ratio = float(d.get("atr_ratio") or 1.0)
    except (TypeError, ValueError):
        pass
    bull = sum(1 for b in [d1_bias, h4_bias] if "bull" in b)
    bear = sum(1 for b in [d1_bias, h4_bias] if "bear" in b)
    if daily_bull is True:
        bull += 2
    elif daily_bear is True:
        bear += 2
    if "high" in vol_reg or atr_ratio > 2.5:
        return "HIGH-VOLATILITY RISK-OFF"
    if bull >= 4:
        return "STRONG BULL TREND"
    if bull >= 2:
        return "BULL TREND"
    if bear >= 4:
        return "STRONG BEAR TREND"
    if bear >= 2:
        return "BEAR TREND"
    if atr_ratio < 0.6:
        return "LOW-VOLATILITY COMPRESSION"
    if bull == 1 or bear == 1:
        return "TRANSITION/UNCERTAIN"
    return "NEUTRAL/RANGE"


def _swing_v2_extension(inst, d, state):
    """
    Chase-protection: extension from Daily EMA20 (Pine) or VWAP proxy.
    Returns {extensionInATR, label, blocked, proxy, at_htf_level, ref_price}.
    """
    try:
        price   = float(d.get("current_price") or d.get("price") or 0)
        atr_d   = float(state.get("atr_d") or d.get("atr") or 0)
        ema20_d = float(state.get("ema20_d") or 0)
        vwap    = float(d.get("vwap_value") or d.get("vwap") or 0)
        ref   = ema20_d if ema20_d > 0 else vwap
        proxy = "EMA20_D" if ema20_d > 0 else "VWAP_proxy"
        if not (ref and price and atr_d):
            return {"extensionInATR": None, "label": "unknown", "blocked": False,
                    "proxy": proxy, "at_htf_level": False}
        ext_atr = abs(price - ref) / atr_d
        if ext_atr <= 0.75:
            lbl = "healthy"
        elif ext_atr <= 1.25:
            lbl = "elevated"
        elif ext_atr <= 1.75:
            lbl = "extended"
        else:
            lbl = "do_not_chase"
        return {"extensionInATR": round(ext_atr, 2), "label": lbl,
                "blocked": lbl == "do_not_chase", "proxy": proxy,
                "at_htf_level": ext_atr <= 0.5,
                "ref_price": round(ref, 2)}
    except Exception:
        return {"extensionInATR": None, "label": "unknown", "blocked": False,
                "proxy": "error", "at_htf_level": False}


def _swing_v2_classify_setup(inst, d, state):
    """Classify into one of 5 swing setup types (spec Section 3)."""
    htf     = HTF_STATE_BY_INST.get(inst, {})
    d1_bias = str((htf.get("1D") or {}).get("bias", "")).lower()
    gd      = d.get("gate_debug") or {}
    has_bos   = bool(gd.get("bos"))
    has_choch = bool(gd.get("choch"))
    has_zone  = bool(d.get("nearest_demand") or d.get("nearest_supply"))
    vol_reg   = str(d.get("volatility") or "").lower()
    ext = _swing_v2_extension(inst, d, state)
    if has_choch and ext.get("at_htf_level"):
        return "HTF_REVERSAL"
    if ("low" in vol_reg or "quiet" in vol_reg or "compress" in vol_reg) and has_bos:
        return "COMPRESSION_BREAKOUT"
    if has_bos and not has_zone:
        return "BREAKOUT_RETEST"
    if has_zone and ("bull" in d1_bias or "bear" in d1_bias):
        return "TREND_PULLBACK"
    if has_bos:
        return "RANGE_EXPANSION"
    return "TREND_PULLBACK"


def _swing_v2_score(inst, d, state):
    """
    9-category 0-100 swing score (spec Sections 4-7). Scores 0 for missing
    data honestly — never fabricates certainty.
    Returns {total, max:100, grade, breakdown:{category:{pts,max,note}}}.
    """
    htf  = HTF_STATE_BY_INST.get(inst, {})
    gd   = d.get("gate_debug") or {}
    diag = d.get("alert_diagnostics") or {}
    price = vwap = 0.0
    try:
        price = float(d.get("current_price") or d.get("price") or 0)
        vwap  = float(d.get("vwap_value") or d.get("vwap") or 0)
    except (TypeError, ValueError):
        pass
    d1_bias = str((htf.get("1D") or {}).get("bias", "")).lower()
    h4_bias = str((htf.get("4H") or {}).get("bias", "")).lower()
    h1_bias = str((htf.get("1H") or {}).get("bias", "")).lower()
    bias_dir = "bull" if "bull" in d1_bias else ("bear" if "bear" in d1_bias else "")
    bd = {}

    # 1. HTF Trend (20 pts)
    htf_pts = 0
    if bias_dir:
        htf_pts += 4
        if state.get("daily_bullish") is True and bias_dir == "bull":
            htf_pts += 4
        elif state.get("daily_bearish") is True and bias_dir == "bear":
            htf_pts += 4
    if bias_dir and h4_bias and bias_dir in h4_bias:
        htf_pts += 6
    if bias_dir and h1_bias and bias_dir in h1_bias:
        htf_pts += 4
    ema20_d = ema50_d = ema200_d = 0.0
    try:
        ema20_d  = float(state.get("ema20_d")  or 0)
        ema50_d  = float(state.get("ema50_d")  or 0)
        ema200_d = float(state.get("ema200_d") or 0)
    except (TypeError, ValueError):
        pass
    if ema20_d and ema50_d and ema200_d:
        if (ema20_d > ema50_d > ema200_d) or (ema20_d < ema50_d < ema200_d):
            htf_pts += 2
    bd["htf_trend"] = {"pts": min(htf_pts, 20), "max": 20,
                       "note": "1H/4H/D bias + EMA stack"}

    # 2. Market Structure (15 pts)
    s_pts = 0
    if gd.get("bos"):      s_pts += 6
    if gd.get("choch"):    s_pts += 5
    if gd.get("structure"): s_pts += 4
    bd["market_structure"] = {"pts": min(s_pts, 15), "max": 15,
                               "note": "BOS/CHOCH/structure"}

    # 3. Entry Location (15 pts)
    loc_pts = 0
    if d.get("nearest_demand") or d.get("nearest_supply"):
        loc_pts += 7
    if price and vwap:
        if (bias_dir == "bull" and price > vwap) or (bias_dir == "bear" and price < vwap):
            loc_pts += 4
        else:
            loc_pts += 1
    ext = _swing_v2_extension(inst, d, state)
    ext_lbl = ext.get("label", "unknown")
    if ext_lbl == "healthy":
        loc_pts += 4
    elif ext_lbl == "elevated":
        loc_pts += 2
    bd["entry_location"] = {"pts": min(loc_pts, 15), "max": 15,
                             "note": "zone+VWAP+ext %.1fATR" % (ext.get("extensionInATR") or 0)}

    # 4. Momentum & Trend Strength (10 pts)
    mom_pts = 0
    rsi_d = macd_hist_d = adx_d = 0.0
    try:
        rsi_d       = float(state.get("rsi_d")       or 0)
        macd_hist_d = float(state.get("macd_hist_d") or 0)
        adx_d       = float(state.get("adx_d")       or 0)
    except (TypeError, ValueError):
        pass
    cvd_dir = str(diag.get("cvd_direction") or "").lower()
    if rsi_d:
        if bias_dir == "bull" and 40 <= rsi_d <= 72:
            mom_pts += 3
        elif bias_dir == "bear" and 28 <= rsi_d <= 60:
            mom_pts += 3
        else:
            mom_pts += 1
    if macd_hist_d:
        if (bias_dir == "bull" and macd_hist_d > 0) or (bias_dir == "bear" and macd_hist_d < 0):
            mom_pts += 3
    if adx_d >= 20:
        mom_pts += 2
    elif adx_d > 0:
        mom_pts += 1
    if cvd_dir and bias_dir and bias_dir in cvd_dir:
        mom_pts += 2
    bd["momentum"] = {"pts": min(mom_pts, 10), "max": 10,
                      "note": "RSI-D/MACD-D/ADX/CVD (Pine %s)" % ("ON" if rsi_d else "OFF")}

    # 5. Volume & Participation (10 pts)
    vol_pts = 0
    rvol = 0.0
    try:
        rvol = float((d.get("rvol") or (RVOL_BY_TICKER.get(inst) or {}).get("value")) or 0)
    except (TypeError, ValueError):
        pass
    has_vol_spike = bool(VOLUME_SPIKE_BY_TICKER.get(inst))
    if rvol >= 1.5:
        vol_pts += 5
    elif rvol >= 1.0:
        vol_pts += 3
    if has_vol_spike:
        vol_pts += 3
    if cvd_dir in ("bullish", "bearish"):
        vol_pts += 2
    bd["volume"] = {"pts": min(vol_pts, 10), "max": 10,
                    "note": "RVOL %.1f spike=%s" % (rvol, has_vol_spike)}

    # 6. Relative Strength & Correlation (10 pts)
    corr_pts = 5  # neutral default when no cross-market data
    cross = d.get("cross_market") or {}
    if cross:
        alignment = str(cross.get("alignment") or cross.get("status") or "").lower()
        if "aligned" in alignment:
            corr_pts = 10
        elif "conflict" in alignment or "diverge" in alignment:
            corr_pts = 0
        elif "partial" in alignment:
            corr_pts = 5
    bd["correlation"] = {"pts": min(corr_pts, 10), "max": 10,
                         "note": "cross-market index alignment"}

    # 7. Risk & Reward Quality (10 pts)
    rr_pts = 0
    rr_num = 0.0
    try:
        rr_num = float((d.get("trade_plan") or {}).get("rr_num") or d.get("rr_num") or 0)
    except (TypeError, ValueError):
        pass
    if rr_num >= 4.0:
        rr_pts = 10
    elif rr_num >= 3.0:
        rr_pts = 7
    elif rr_num >= 2.0:
        rr_pts = 4
    bd["risk_reward"] = {"pts": rr_pts, "max": 10,
                         "note": "R:R %.1f" % rr_num}

    # 8. Volatility Quality (5 pts)
    vq_pts = 0
    vol_reg = str(d.get("volatility") or d.get("vol_regime") or "").lower()
    if "normal" in vol_reg or not vol_reg:
        vq_pts = 5
    elif "low" in vol_reg or "quiet" in vol_reg:
        vq_pts = 3
    elif "elevated" in vol_reg or "caution" in vol_reg:
        vq_pts = 3
    elif "high" in vol_reg or "block" in vol_reg:
        vq_pts = 1
    bd["volatility_quality"] = {"pts": min(vq_pts, 5), "max": 5,
                                 "note": vol_reg or "normal"}

    # 9. Catalyst & Event Risk (5 pts)
    event_pts = 5
    news = d.get("news_events") or []
    if isinstance(news, list):
        for _ev in news:
            _imp = str(_ev.get("impact") or _ev.get("type") or "").lower()
            if "high" in _imp or "red" in _imp:
                event_pts = max(0, event_pts - 3)
                break
            elif "med" in _imp or "orange" in _imp:
                event_pts = max(2, event_pts - 1)
    import datetime as _sv2dt
    if _sv2dt.datetime.now().weekday() == 4:  # Friday
        event_pts = max(1, event_pts - 2)
    bd["event_risk"] = {"pts": event_pts, "max": 5, "note": "news + day-of-week"}

    total = min(sum(v["pts"] for v in bd.values()), 100)
    if total >= 85:
        grade = "HIGH CONVICTION"
    elif total >= 75:
        grade = "READY"
    elif total >= 65:
        grade = "WATCHING"
    elif total >= 50:
        grade = "WEAK"
    else:
        grade = "NO TRADE"
    return {"total": total, "max": 100, "grade": grade, "breakdown": bd}


def _swing_v2_hard_blocks(inst, d, state, score_data):
    """Hard-block conditions (spec Section 6). Returns list of active blocks."""
    blocks = []
    rr_num = 0.0
    try:
        rr_num = float((d.get("trade_plan") or {}).get("rr_num") or d.get("rr_num") or 0)
    except (TypeError, ValueError):
        pass
    if rr_num and rr_num < 2.0:
        blocks.append("R:R %.1fR below 2.0 minimum" % rr_num)
    gd = d.get("gate_debug") or {}
    if not gd.get("bos") and not gd.get("choch"):
        blocks.append("No BOS/CHOCH — no clear structural invalidation level")
    ext = _swing_v2_extension(inst, d, state)
    if ext.get("blocked"):
        blocks.append("Price excessively extended (%.1f ATR — do not chase)"
                      % (ext.get("extensionInATR") or 0))
    htf    = HTF_STATE_BY_INST.get(inst, {})
    d1_ts  = (htf.get("1D") or {}).get("ts")
    if d1_ts:
        try:
            age_min = (now_utc() - _parse_ts(d1_ts)).total_seconds() / 60.0
            if age_min > 2160:
                blocks.append("Daily HTF data stale (%dh)" % int(age_min / 60))
        except Exception:
            pass
    return blocks


def _swing_v2_lifecycle(inst, score_data, blocks, d, state):
    """Lifecycle state machine. Mutates SWING_V2_LIFECYCLE_BY_INST (DISPLAY-ONLY)."""
    total    = score_data.get("total", 0)
    grade    = score_data.get("grade", "NO TRADE")
    gd       = d.get("gate_debug") or {}
    confirms = sum([bool(gd.get("bos")), bool(gd.get("choch")),
                    bool(d.get("nearest_demand") or d.get("nearest_supply")),
                    bool(gd.get("structure"))])
    if blocks:
        status = "NO TRADE"
        reason = blocks[0]
    elif grade == "NO TRADE":
        status = "SCANNING"
        reason = "Score %d — below threshold" % total
    elif grade == "WEAK":
        status = "WATCHING"
        reason = "Score %d — building setup" % total
    elif grade == "WATCHING":
        status = "SETUP FORMING" if confirms >= 1 else "WATCHING"
        reason = "Score %d — %d confirmation(s)" % (total, confirms)
    else:
        status = "READY" if confirms >= 2 else "SETUP FORMING"
        reason = "Score %d — %d confirmations" % (total, confirms)
    prev  = SWING_V2_LIFECYCLE_BY_INST.get(inst, {})
    entry = {"status": status, "prev_status": prev.get("status", ""),
             "changed": status != prev.get("status", ""), "reason": reason,
             "score": total, "grade": grade, "ts": now_utc().isoformat()}
    SWING_V2_LIFECYCLE_BY_INST[inst] = entry
    return entry


def _swing_v2_entry_plan(inst, d, state, score_data):
    """Entry zone, structural stop, 3-target plan (spec Sections 9-11)."""
    price = atr_d = 0.0
    try:
        price = float(d.get("current_price") or d.get("price") or 0)
        atr_d = float(state.get("atr_d") or d.get("atr") or 0)
    except (TypeError, ValueError):
        pass
    htf     = HTF_STATE_BY_INST.get(inst, {})
    d1_bias = str((htf.get("1D") or {}).get("bias", "")).lower()
    direction = "LONG" if "bull" in d1_bias else ("SHORT" if "bear" in d1_bias else "NEUTRAL")
    tp_d = d.get("trade_plan") or {}
    stop = 0.0
    try:
        stop = float(tp_d.get("stop") or tp_d.get("stop_price") or 0)
    except (TypeError, ValueError):
        pass
    stop_reason = "Structural level"
    if not stop and atr_d and price:
        mult = 2.25
        stop = (price - mult * atr_d) if direction == "LONG" else (price + mult * atr_d)
        stop_reason = "ATR stop (%.1f x %.2f ATR-D)" % (mult, atr_d)
    stop_dist = abs(price - stop) if price and stop else 0.0
    stop_atr  = round(stop_dist / atr_d, 2) if atr_d and stop_dist else None
    zone_buf  = (atr_d * 0.25) if atr_d else (price * 0.001 if price else 1.0)
    no_chase_above = round(price + atr_d * 0.75, 2) if atr_d and price else None
    no_chase_below = round(price - atr_d * 0.75, 2) if atr_d and price else None
    t1 = float(tp_d.get("target1") or tp_d.get("target") or 0)
    t2 = float(tp_d.get("target2") or 0)
    t3 = float(tp_d.get("target3") or 0)
    if not t1 and stop_dist and price:
        if direction == "LONG":
            t1 = round(price + stop_dist * 2.0, 2)
            t2 = round(price + stop_dist * 3.0, 2)
            t3 = round(price + stop_dist * 5.0, 2)
        else:
            t1 = round(price - stop_dist * 2.0, 2)
            t2 = round(price - stop_dist * 3.0, 2)
            t3 = round(price - stop_dist * 5.0, 2)
    rr1 = round(abs(t1 - price) / stop_dist, 1) if t1 and stop_dist else None
    rr2 = round(abs(t2 - price) / stop_dist, 1) if t2 and stop_dist else None
    rr3 = round(abs(t3 - price) / stop_dist, 1) if t3 and stop_dist else None
    return {
        "direction": direction,
        "entryZoneLow":    round(price - zone_buf, 2) if price else None,
        "entryZoneHigh":   round(price + zone_buf, 2) if price else None,
        "preferredEntry":  round(price, 2) if price else None,
        "doNotChaseAbove": no_chase_above if direction == "LONG"  else None,
        "doNotChaseBelow": no_chase_below if direction == "SHORT" else None,
        "entryMethod": "Limit at pullback zone",
        "entryExpiration": "3-5 trading sessions",
        "structuralStop":  round(stop, 2) if stop else None,
        "stopReason":      stop_reason,
        "stopDistance":    round(stop_dist, 2) if stop_dist else None,
        "stopDistanceATR": stop_atr,
        "target1": round(t1, 2) if t1 else None, "target1Reason": "Prior 4H structure / 2R",
        "target2": round(t2, 2) if t2 else None, "target2Reason": "Supply/demand zone / 3R",
        "target3": round(t3, 2) if t3 else None, "target3Reason": "Weekly level / runner",
        "rewardRiskTarget1": rr1, "rewardRiskTarget2": rr2, "rewardRiskTarget3": rr3,
    }


def _swing_v2_overnight_risk(d, state):
    """Overnight / weekend hold risk (spec Section 18)."""
    import datetime as _ov_dt
    dow  = _ov_dt.datetime.now().weekday()
    hour = _ov_dt.datetime.now().hour
    vol_reg  = str(d.get("volatility") or "").lower()
    high_vol = ("high" in vol_reg or "block" in vol_reg)
    pre_wknd = (dow == 4 and hour >= 12)
    hold_on  = not high_vol
    if dow >= 5:
        action = "CLOSE BEFORE WEEKEND"
    elif pre_wknd:
        action = "HOLD REDUCED" if not high_vol else "CLOSE BEFORE WEEKEND"
    else:
        action = "HOLD FULL"
    return {
        "overnightRisk":          "HIGH" if high_vol else "LOW",
        "weekendRisk":            "HIGH" if high_vol else "MODERATE",
        "holdOvernightAllowed":   hold_on,
        "holdOverWeekendAllowed": hold_on and not pre_wknd and dow < 5,
        "weekendRecommendation":  action,
        "eventRiskLevel":         "HIGH" if high_vol else "LOW",
    }


def compute_swing_v2_analysis(inst, d):
    """
    Master Swing V2 orchestrator. DISPLAY-ONLY, FAIL-OPEN.
    Called in full_analysis when SWING_MODE_V2_ENABLED is True.
    Never touches gate / sizing / execution.
    """
    if not SWING_MODE_V2_ENABLED:
        return {"available": False, "reason": "flag_off"}
    try:
        state  = dict(SWING_V2_STATE_BY_INST.get(inst, {}))
        score  = _swing_v2_score(inst, d, state)
        blocks = _swing_v2_hard_blocks(inst, d, state, score)
        lc     = _swing_v2_lifecycle(inst, score, blocks, d, state)
        setup  = _swing_v2_classify_setup(inst, d, state)
        regime = _swing_v2_regime(inst, d, state)
        ext    = _swing_v2_extension(inst, d, state)
        plan   = _swing_v2_entry_plan(inst, d, state, score)
        risk   = _swing_v2_overnight_risk(d, state)
        htf    = HTF_STATE_BY_INST.get(inst, {})
        d1_b   = str((htf.get("1D") or {}).get("bias", "")).lower()
        h4_b   = str((htf.get("4H") or {}).get("bias", "")).lower()
        h1_b   = str((htf.get("1H") or {}).get("bias", "")).lower()
        br     = score["breakdown"]
        supporting  = []
        conflicting = []
        if br["htf_trend"]["pts"] >= 14:
            supporting.append("Weekly and Daily HTF trends aligned")
        if br["market_structure"]["pts"] >= 10:
            supporting.append("Strong BOS/CHOCH structure confirmed")
        if br["entry_location"]["pts"] >= 10:
            supporting.append("Price near key demand/supply zone")
        if ext.get("label") == "healthy":
            supporting.append("Price not extended from reference level")
        if br["momentum"]["pts"] >= 6:
            supporting.append("Momentum aligned with direction")
        if br["volume"]["pts"] >= 6:
            supporting.append("Volume participation confirmed")
        if ext.get("label") in ("elevated", "extended"):
            conflicting.append("Price %.1f ATR from key level" % (ext.get("extensionInATR") or 0))
        if br["momentum"]["pts"] < 3:
            conflicting.append("RSI/MACD/ADX unavailable — connect Pine script")
        if blocks:
            conflicting.extend(blocks[:2])
        gd = d.get("gate_debug") or {}
        next_conf = []
        if not gd.get("bos"):
            next_conf.append("4H BOS in the trade direction")
        if not (d.get("nearest_demand") or d.get("nearest_supply")):
            next_conf.append("Price at key demand/supply zone")
        if not state.get("rsi_d"):
            next_conf.append("Connect Pine EMA/Momentum script for full scoring")
        if not next_conf:
            next_conf.append("Confirm entry on 1H close")
        daily_trend = (
            "Bullish" if state.get("daily_bullish") else
            "Bearish" if state.get("daily_bearish") else
            "Bullish" if "bull" in d1_b else
            "Bearish" if "bear" in d1_b else "Neutral"
        )
        return {
            "available": True, "inst": inst, "ts": now_utc().isoformat(),
            "setupType": setup, "direction": plan["direction"],
            "lifecycle": lc, "score": score, "hardBlocks": blocks,
            "regime": regime, "extension": ext,
            "weeklyTrend": daily_trend, "dailyTrend": daily_trend,
            "h4Structure": h4_b.capitalize() if h4_b else "Unknown",
            "htfSummary":  {"1h": h1_b, "4h": h4_b, "1d": d1_b},
            "entryPlan": plan, "overnightRisk": risk,
            "supportingFactors": supporting, "conflictingFactors": conflicting,
            "nextConfirmation": next_conf,
            "expectedHoldMin": 2, "expectedHoldMax": 7,
            "dataFreshness": {
                "ema_data":      bool(state.get("ema20_d")),
                "rsi_data":      bool(state.get("rsi_d")),
                "macd_data":     bool(state.get("macd_hist_d")),
                "htf_data":      bool(htf),
                "pine_connected": bool(state.get("ts")),
            },
        }
    except Exception as _sv2e:
        return {"available": False, "reason": str(_sv2e)}


@app.route("/webhook", methods=["POST"])
def webhook():
    global CURRENT_PRICE, ZONE_BROKEN_AT, LAST_WEBHOOK_AT, LAST_ALERT_AT

    webhook_received_at = now_utc()   # T0 for the webhook->alert delay metric
    LAST_WEBHOOK_AT = webhook_received_at   # any inbound POST, before any early return
    with COUNTERS_LOCK:
        COUNTERS["webhooks_received"] += 1
        _WEBHOOK_TS.append(webhook_received_at)   # rolling last-hour window

    # ── ANALYSIS-BOT MIRROR (opt-in; DEFAULT-OFF) ────────────────────────────
    # Fire-and-forget a verbatim copy (raw bytes + original content-type) of this
    # inbound webhook to the separate ANALYSIS-ONLY bot. With ANALYSIS_BOT_FORWARD_URL
    # UNSET (the default) this whole block is skipped, so the live path is
    # byte-identical. The mirror runs on a daemon thread and is fully exception-
    # isolated — it can never block or change the response returned below.
    if ANALYSIS_BOT_FORWARD_URL:
        try:
            _forward_to_analysis_bot(request.get_data(), request.headers.get("Content-Type"))
        except Exception:
            pass

    try:
        data = request.get_json(force=True, silent=True) or {}
    except Exception:
        data = {}

    raw_body = request.get_data(as_text=True)
    if not data and raw_body:
        data = {"alert_type": raw_body.strip()}

    # ── Compatibility shim: alternate VWAP alert schema ──────────────────────
    # Some TradingView VWAP alerts post {"signal":"VWAP_BULLISH","symbol":"MNQ1!",
    # "instrument":"MGC",...} instead of the canonical
    # {"alert_type":"MNQ VWAP","ticker":"MNQ1!",...}. Map them onto the existing
    # data-only VWAP type so they are ingested (price refresh + ack) instead of
    # dropped as "unrecognized". The chart `symbol` is the authoritative
    # instrument (it is the literal {{ticker}} and matches the price level); the
    # free-text `instrument` field is only a fallback and is ignored when it
    # disagrees. No `vwap` value is invented, so the auto-fetched VWAP is never
    # corrupted — these alerts simply refresh the per-instrument price.
    if not (data.get("alert_type") or data.get("message") or data.get("text")):
        _sig = str(data.get("signal") or "").strip().upper()
        if _sig.startswith("VWAP"):
            _vw_inst = (_instrument_from_text(data.get("symbol"))
                        or _instrument_from_text(data.get("ticker"))
                        or _instrument_from_text(data.get("instrument")))
            if _vw_inst:
                _inst_field = _instrument_from_text(data.get("instrument"))
                if _inst_field is not None and _inst_field != _vw_inst:
                    logger.warning("VWAP alert symbol=%r disagrees with instrument=%r; "
                                   "using %s (chart symbol is authoritative)",
                                   data.get("symbol"), data.get("instrument"), _vw_inst)
                data["alert_type"] = f"{_vw_inst} VWAP"
                data.setdefault("ticker", data.get("symbol") or _vw_inst)
                logger.info("Normalized alternate VWAP alert (signal=%r) → %s",
                            _sig, data["alert_type"])

    # ── Compatibility shim: dual-TF 5s event schema ──────────────────────────
    # The new 5s indicator posts {"event":"BULLISH_SWEEP","ticker":"MNQ1!",...}
    # (the bare confirmation name lives in `event`, NOT `alert_type`). Map it onto
    # alert_type so the bare 5s names resolve through ALERT_TYPES instead of being
    # dropped as "unrecognized". GATED to flag-ON + SCALP so the engine's dormant
    # (flag-OFF) behavior stays byte-identical — with the flag OFF a stray new-type
    # `event` payload still reads as "unrecognized", exactly as before this change.
    if (DUAL_TF_ENGINE and TRADING_MODE == "SCALP"
            and not (data.get("alert_type") or data.get("message") or data.get("text"))):
        _evt = str(data.get("event") or "").strip()
        if _evt:
            data["alert_type"] = _evt.upper()
            data.setdefault("ticker", data.get("symbol") or data.get("ticker"))
            logger.info("Normalized dual-TF event alert (event=%r) → %s",
                        _evt, data["alert_type"])

    alert_type = (data.get("alert_type") or data.get("message") or data.get("text") or "")
    normalized = alert_type.strip().upper()

    # Bare 5s sweep names (BULLISH_SWEEP / BEARISH_SWEEP) are recognized ONLY when the
    # engine is live; with the flag OFF they are unknown to the system exactly as
    # before this engine shipped, so a direct (non-`event`) bare-sweep payload stays
    # "unrecognized" — keeping the dormant flag-OFF contract byte-identical.
    # ── Swing V2 EMA/Momentum data ingestion (DISPLAY-ONLY) ──────────────────
    # SWING_EMA_UPDATE payloads store Pine-sourced EMA/RSI/MACD/ADX data for the
    # swing v2 scoring engine. They bypass the ALERT_TYPES check and return early.
    # Flag-off → ack only (no state written). Never touches the money path.
    if normalized == "SWING_EMA_UPDATE":
        _sw_inst = (_instrument_from_text(data.get("ticker"))
                    or _instrument_from_text(data.get("instrument")))
        if _sw_inst and SWING_MODE_V2_ENABLED:
            _sw_prev = dict(SWING_V2_STATE_BY_INST.get(_sw_inst, {}))
            for _sk in ("ema20_d","ema50_d","ema200_d","ema20_4h","ema50_4h",
                        "ema20_w","ema50_w","atr_d","rsi_d","macd_hist_d",
                        "adx_d","daily_bullish","daily_bearish"):
                if _sk in data:
                    _sw_prev[_sk] = data[_sk]
            _sw_prev["ts"] = now_utc().isoformat()
            SWING_V2_STATE_BY_INST[_sw_inst] = _sw_prev
            logger.info("SWING_V2 EMA state updated: %s", _sw_inst)
        return jsonify({"status": "ok", "type": "swing_ema_update",
                        "inst": _sw_inst, "flag": SWING_MODE_V2_ENABLED}), 200

    _dormant_sweep = (normalized in DUAL_TF_SWEEP_TYPES
                      and not (DUAL_TF_ENGINE and TRADING_MODE == "SCALP"))
    # SWEEP_RECLAIM and MICRO_CHOCH are genuine Pine structure signals — always
    # pass them through to the structure bridge below regardless of ALERT_TYPES
    # state or FAST_ENTRY_TRIGGER flag. Without this, "Unrecognized alert type"
    # fires when the type is absent from ALERT_TYPES (e.g. older prod build),
    # the bridge never injects LH/HL/CHOCH, and structure_confirmed goes blind.
    _is_structure_bridge_type = (
        normalized in FAST_SWEEP_RECLAIM_LONG_TYPES
        or normalized in FAST_SWEEP_RECLAIM_SHORT_TYPES
        or normalized in FAST_MICRO_CHOCH_LONG_TYPES
        or normalized in FAST_MICRO_CHOCH_SHORT_TYPES
    )
    if (normalized not in ALERT_TYPES or _dormant_sweep) and not _is_structure_bridge_type:
        logger.warning("Unrecognized alert type: %r", alert_type)
        _record_diagnostic("%s | IGNORED — unrecognized/empty alert: %r" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), alert_type))
        return jsonify({"status": "ignored", "reason": "unrecognized alert type", "received": alert_type}), 200

    # ── Authoritative instrument resolution (ticker-first; never silently MGC) ──
    # The payload `ticker` field decides the instrument. The alert title is used
    # only when no ticker is present, and unresolvable/contradictory alerts are
    # rejected rather than misattributed (default-MGC) to the wrong instrument.
    res = resolve_instrument(data.get("ticker"), normalized)
    if not res["ok"]:
        logger.warning("Ticker resolution rejected %r (ticker=%r): %s",
                       normalized, data.get("ticker"), res["error"])
        _record_diagnostic("%s | REJECTED — %s — ticker resolution failed: %s" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), normalized, res["error"]))
        return jsonify({
            "status":     "error",
            "reason":     "ticker resolution failed",
            "detail":     res["error"],
            "alert_type": normalized,
            "ticker":     data.get("ticker"),
        }), 400
    resolved_inst = res["instrument"]
    if res["source"] == "title":
        logger.warning("Alert %r has no ticker field — resolved %s from the title; "
                       "add a `ticker` field to this TradingView alert.",
                       normalized, resolved_inst)

    raw_price = data.get("price")
    try:
        parsed_price = float(raw_price) if raw_price is not None else None
    except (ValueError, TypeError):
        parsed_price = None

    # ── ANALYST-ONLY signals (FVG / Order Blocks) — DISPLAY-ONLY short-circuit ──
    #    Recognized, but deliberately walled off from the money path. Store the
    #    record in ALERT_HISTORY (so the Analyst Reasoning Engine reads it on the
    #    NEXT full_analysis / dashboard poll) and return a read-only ack. This branch
    #    runs BEFORE the price stores, the intraday tracker, VWAP ingestion, the zone
    #    side-effects / zone-broken expiry, dedupe, journaling, Discord, and the
    #    _WEBHOOK_JOBS worker — so an FVG/OB alert can NEVER mutate a gate input,
    #    trigger a re-evaluation, or cause an auto-execution. They are advisory
    #    evidence only, consumed via _recent_smc_signals().
    if normalized in ANALYST_TYPES:
        LAST_ALERT_AT = datetime.now(timezone.utc)
        ALERT_HISTORY.append({
            "alert_type":        normalized,
            "ticker":            data.get("ticker"),
            "instrument":        resolved_inst,
            "instrument_source": res["source"],
            "price":             parsed_price,
            "timestamp":         now_utc().isoformat(),
            "raw":               data,
        })
        return jsonify({
            "status":     "analyst_signal_stored",
            "alert_type": normalized,
            "instrument": resolved_inst,
            "note":       "display-only smart-money evidence; no gate / money-path effect",
        }), 200

    if parsed_price is not None:
        CURRENT_PRICE = parsed_price
        CURRENT_PRICE_BY_TICKER[resolved_inst] = parsed_price
        CURRENT_PRICE_TS_BY_TICKER[resolved_inst] = now_utc().isoformat()
        # Feed the intraday tracker (opening range + per-session OHLC) for the
        # multi-strategy engine. FAIL-OPEN — never disrupts the webhook path.
        _update_intraday_tracker(resolved_inst, parsed_price)
        # Feed the DEDICATED 09:30 ET breakout opening-range tracker (flag-gated; a
        # no-op when BREAKOUT_MODE_ENABLED is OFF). FAIL-OPEN.
        _update_breakout_or_tracker(resolved_inst, parsed_price)

    # ── VWAP ingestion (required input for the strict price-vs-VWAP filter) ──
    raw_vwap = data.get("vwap")
    if raw_vwap is not None:
        try:
            vwap_val = float(raw_vwap)
        except (ValueError, TypeError):
            vwap_val = None
        if vwap_val is not None:
            vwap_key = resolved_inst
            _chart_ts = now_utc().isoformat()
            # CHART_VWAP_BY_TICKER: secondary store, always tracks the last TV push.
            # Used by get_vwap_diagnostics() to compare freshness against Databento.
            CHART_VWAP_BY_TICKER[vwap_key] = {"value": vwap_val, "ts": _chart_ts,
                                              "source": "chart"}
            # VWAP_BY_TICKER: authoritative store. TV/chart still writes here for
            # backward compat, but Databento will overwrite it within the next
            # completed 1m bar (~60 s). The old 10-min grace window that blocked
            # Databento was removed — Databento is now always primary.
            VWAP_BY_TICKER[vwap_key] = {"value": vwap_val, "ts": _chart_ts,
                                        "source": "chart"}

    # ── RVOL ingestion (optional `rvol` field on ANY alert) — SOFT Edge modifier ──
    #    There is no dedicated RVOL feed today, so any alert MAY carry a numeric
    #    `rvol` (relative volume) value. RVOL NEVER gates a trade (see
    #    _rvol_adjustment); it only nudges the Edge Score. Stored per instrument so
    #    the gate/display can read the latest reading.
    #    SOURCE OWNERSHIP: Databento is the canonical RVOL writer when active
    #    (source='databento' + fresh ts).  TV values are silently dropped in that
    #    case — they are less accurate than Databento's bar-computed RVOL.
    raw_rvol = data.get("rvol")
    if raw_rvol is not None:
        try:
            rvol_val = float(raw_rvol)
        except (ValueError, TypeError):
            rvol_val = None
        if rvol_val is not None:
            if _databento_is_canonical(RVOL_BY_TICKER.get(resolved_inst) or {}):
                logger.debug("RVOL [%s]: TV field (value=%.2f) received; "
                             "Databento is canonical — state write skipped",
                             resolved_inst, rvol_val)
            else:
                # Databento not active or stale — TV is the fallback RVOL writer.
                RVOL_BY_TICKER[resolved_inst] = {"value": rvol_val,
                                                 "ts": now_utc().isoformat(),
                                                 "source": "tradingview"}

    # ── Inbound HTF (1H/4H/1D) chart push (P3) — SWING display-only overlay ───────
    #    Recognised ONLY when the alert EXPLICITLY tags a higher-timeframe field
    #    (timeframe/interval/tf). A no-op in SCALP / flag-off (returns before any
    #    write). Additive + fail-open; never affects the gate (P4 reads the same
    #    compute_swing_context()). A bare 1m/5m alert is NEVER promoted to HTF.
    try:
        _ingest_htf_overlay(data, resolved_inst, normalized)
    except Exception:
        pass

    # ── Data-only stores (CVD / volume-spike) ingest FIRST — flag-independent ─────
    #    These run BEFORE the dual-TF convergence record/enqueue below so the CVD
    #    committed-state + volume-spike timestamp the triggering confirmation just
    #    wrote are already visible when the single-worker entry job re-derives a fresh
    #    full_analysis (the worker could otherwise race ahead of a same-request store
    #    write). The ack response is computed here and returned AFTER the dual-TF
    #    block. CVD/volume are deliberately NOT in DUAL_TF_FAST_TYPES so they ALWAYS
    #    reach this ingestion (flag ON or OFF) — the Edge gate's CVD filter needs it.
    _data_only_resp = None

    # ── CVD ingestion (CVD_BULLISH / CVD_BEARISH) — HARD confirmation filter ──
    #    Cumulative Volume Delta sign per instrument: bullish (delta > 0) confirms
    #    longs and vetoes shorts; bearish (delta < 0) confirms shorts and vetoes
    #    longs (enforced in evaluate_strict_setup). FAIL-OPEN: until a CVD alert
    #    arrives for an instrument, both sides stay allowed. The numeric `cvd`
    #    value is optional (display only); direction (rising/falling) is derived
    #    from its change vs the prior reading and left None when unmeasurable, so
    #    no label is fabricated. Data-only: store + ack, never scored.
    if normalized in CVD_TYPES:
        signaled_state = "bullish" if normalized in CVD_BULLISH_TYPES else "bearish"
        raw_cvd = data.get("cvd")
        if raw_cvd is None:
            raw_cvd = data.get("cvd_value")
        try:
            cvd_val = float(raw_cvd) if raw_cvd is not None else None
        except (ValueError, TypeError):
            cvd_val = None
        # ── Source ownership guard ────────────────────────────────────────────
        # When Databento has written CVD within the staleness window it is the
        # sole canonical writer.  TV alerts are acknowledged (shadow ack) but
        # must NOT modify CVD_BY_TICKER — they would overwrite Databento's more
        # reliable, tick-level-accurate state.  Fails open: if Databento is
        # absent or stale TV acts as the fallback writer.
        _tv_cvd_blocked = _databento_is_canonical(CVD_BY_TICKER.get(resolved_inst) or {})
        _prev_cvd = CVD_BY_TICKER.get(resolved_inst) or {}
        _prev_val = _prev_cvd.get("value")
        cvd_dir = None
        if cvd_val is not None and _prev_val is not None:
            if cvd_val > _prev_val:
                cvd_dir = "rising"
            elif cvd_val < _prev_val:
                cvd_dir = "falling"
            else:
                cvd_dir = _prev_cvd.get("direction")

        # ── 2-candle confirmation debounce on the COMMITTED state ───────────────
        #   The committed direction (the ONLY thing evaluate_strict_setup vetoes
        #   on, via cvd.get("state")) flips ONLY after the OPPOSITE direction is
        #   signaled on 2 DISTINCT 1-minute candles. Rules:
        #     • First-ever reading commits immediately (fail-open baseline).
        #     • A signal AGREEING with the committed state clears any pending flip
        #       (opposite_count -> 0).
        #     • An opposite signal increments opposite_count once per NEW 1-minute
        #       candle (same-minute repeats never double-count); a skipped minute
        #       with no signal does NOT reset the count.
        #     • opposite_count reaching 2 flips the committed state, then resets.
        _committed    = _prev_cvd.get("state")
        _pending      = _prev_cvd.get("pending_dir")
        _opp_count    = int(_prev_cvd.get("opposite_count") or 0)
        _last_opp_min = _prev_cvd.get("last_opposite_minute")
        _this_min     = int(now_utc().timestamp() // 60)   # 1-minute candle bucket

        if _committed is None:
            committed_state = signaled_state               # establish baseline
            pending_dir, opp_count, last_opp_min = None, 0, None
            _flip_note = "baseline"
        elif signaled_state == _committed:
            committed_state = _committed                    # reaffirmed -> clear pending
            pending_dir, opp_count, last_opp_min = None, 0, None
            _flip_note = "confirmed"
        else:
            # Opposite direction — count DISTINCT 1-minute candles toward a flip.
            _same_candle = (_pending == signaled_state
                            and _last_opp_min is not None
                            and _this_min == _last_opp_min)
            if _same_candle:
                opp_count, last_opp_min = _opp_count, _last_opp_min   # repeat in same candle
            else:
                opp_count    = (_opp_count if _pending == signaled_state else 0) + 1
                last_opp_min = _this_min
            if opp_count >= 2:
                committed_state = signaled_state            # 2 distinct candles -> FLIP
                pending_dir, opp_count, last_opp_min = None, 0, None
                _flip_note = "flip 2/2 -> %s" % signaled_state
            else:
                committed_state = _committed                # hold; watch only
                pending_dir = signaled_state
                _flip_note = "watch %d/2 -> %s" % (opp_count, signaled_state)

        if _tv_cvd_blocked:
            # Databento is canonical — acknowledge the TV alert without touching
            # CVD_BY_TICKER (state write skipped; raw alert NOT appended to history).
            logger.debug("CVD [%s]: TV alert received (signaled=%s value=%s); "
                         "Databento is canonical — state write skipped",
                         resolved_inst, signaled_state, cvd_val)
            _data_only_resp = jsonify({
                "status":       "cvd_tv_shadow",
                "ticker":       resolved_inst,
                "cvd_signaled": signaled_state,
                "cvd_value":    cvd_val,
                "canonical":    "databento",
                "price":        parsed_price if parsed_price is not None else CURRENT_PRICE,
            }), 200
        else:
            # Databento not active or stale — TV is the fallback canonical CVD writer.
            CVD_BY_TICKER[resolved_inst] = {
                "state":                committed_state,
                "value":                cvd_val,
                "direction":            cvd_dir,
                "ts":                   now_utc().isoformat(),
                "pending_dir":          pending_dir,
                "opposite_count":       opp_count,
                "last_opposite_minute": last_opp_min,
                "source":               "tradingview",
            }
            _save_market_state("cvd::" + resolved_inst, CVD_BY_TICKER[resolved_inst])
            logger.info("CVD update: %s signaled=%s committed=%s (%s, value=%s, dir=%s)",
                        resolved_inst, signaled_state, committed_state, _flip_note, cvd_val, cvd_dir)
            _record_diagnostic("%s | %s — CVD signaled %s, committed %s (%s) — data only, no scoring" % (
                fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"),
                resolved_inst, signaled_state, committed_state, _flip_note))
            _data_only_resp = jsonify({
                "status":             "cvd_updated",
                "ticker":             resolved_inst,
                "cvd_state":          committed_state,
                "cvd_signaled":       signaled_state,
                "cvd_pending":        pending_dir,
                "cvd_opposite_count": opp_count,
                "cvd_value":          cvd_val,
                "cvd_direction":      cvd_dir,
                "price":              parsed_price if parsed_price is not None else CURRENT_PRICE,
            }), 200

    # ── Volume-spike ingestion (VOLUME SPIKE) — one half of the +15 volume edge ──
    #    A volume spike is a momentary event, so we store only its arrival time and
    #    treat it as "fresh" for VOLUME_SPIKE_TTL_MIN minutes (see evaluate_strict
    #    _setup). Data-only: it stores + acks, never scores or biases. FAIL-OPEN —
    #    until a spike arrives, volume confirmation falls back to RVOL / no-data.
    if normalized in VOLUME_SPIKE_TYPES:
        VOLUME_SPIKE_BY_TICKER[resolved_inst] = {"ts": now_utc().isoformat()}
        _save_market_state("volume_spike::" + resolved_inst, VOLUME_SPIKE_BY_TICKER[resolved_inst])
        logger.info("Volume-spike update: %s", resolved_inst)
        _record_diagnostic("%s | %s — VOLUME SPIKE — data only, no scoring" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), resolved_inst))
        _data_only_resp = jsonify({
            "status": "volume_spike_updated",
            "ticker": resolved_inst,
            "price":  parsed_price if parsed_price is not None else CURRENT_PRICE,
        }), 200

    # ── Dual-timeframe (1m bias + 5s execution) SCALP engine — additive, gated ──
    #    Both helpers self-filter to no-ops unless DUAL_TF_ENGINE is ON + SCALP.
    #    The 1m BIAS lane consumes BOS/CHOCH/zone alerts; the 5s lane records the
    #    aligned confirmations (CVD / sweep / volume) and, when the CONVERGENCE rule
    #    is met (standing bias + >=2 distinct aligned confirmations within
    #    DUAL_TF_CONFIRM_WINDOW_SEC — no dedicated entry-trigger), ENQUEUES a single-
    #    worker entry job (it NEVER fires an order inline). The CVD/volume committed
    #    stores were already updated ABOVE, so by the time the worker re-derives a
    #    fresh full_analysis the triggering confirmation's data is visible (no race).
    _dual_tf_update_bias(normalized, resolved_inst)
    if DUAL_TF_ENGINE and TRADING_MODE == "SCALP":
        try:
            _dtf_dir = _dual_tf_record_5s_signal(normalized, resolved_inst)
            if _dtf_dir is not None:
                _ensure_webhook_worker()
                _WEBHOOK_JOBS.put({"job_type": "dual_tf_entry",
                                   "resolved_inst": resolved_inst,
                                   "direction": _dtf_dir,
                                   "trigger_price": parsed_price})
        except Exception as exc:
            logger.error("Dual-TF 5s record/enqueue error (non-fatal): %s", exc)

    # ── Fast Entry Trigger seconds micro-event ingestion — DISPLAY / STATE only ──
    #    Self-guards to a no-op unless FAST_ENTRY_TRIGGER + SCALP. Records the micro
    #    event into FAST_ENTRY_STATE_BY_TICKER so the aggregator (full_analysis) and
    #    the optional worker money path can read a fresh snapshot. It NEVER enqueues
    #    or fires here — the money decision lives in the single-threaded worker.
    _fast_entry_record(normalized, resolved_inst, data)

    # ── MICRO SCALP price-trail + micro-event recorder (DISPLAY/STATE only) ──
    #    Self-guards to a no-op unless the Micro Scalp toggle is ON. Separate
    #    store from Fast Entry (whose gate leaves it empty in prod). Never
    #    scores, never gates, never raises into the webhook path.
    _micro_scalp_record_event(normalized, resolved_inst, parsed_price)

    # Data-only CVD / volume-spike ack (store written ABOVE, before the enqueue).
    if _data_only_resp is not None:
        return _data_only_resp

    # Brand-new 5s execution types ack fast — recorded above, kept OUT of the heavy
    # scoring lane (no full_analysis). Unconditional so a stray new-type alert never
    # falls through to scoring even when the flag is OFF.
    if normalized in DUAL_TF_FAST_TYPES:
        return jsonify({"status": "dual_tf_signal", "alert_type": normalized,
                        "ticker": resolved_inst, "price": parsed_price}), 200

    # Fast Entry seconds micro-events ack fast — recorded above (display / state
    # only), kept OUT of the scoring lane (no full_analysis, no money decision here;
    # the optional money path is evaluated in the single-threaded webhook worker).
    #
    # ── Structure bridge ─────────────────────────────────────────────────────
    # MICRO_CHOCH and SWEEP_RECLAIM are genuine structure signals sent from the
    # TradingView Pine scripts. They were originally walled off from ALERT_HISTORY
    # (fast-side return-early) so structure_confirmed never saw them. The bridge
    # below injects an equivalent canonical structure record so the gate works:
    #   MICRO_CHOCH_SHORT / MICRO CHOCH SHORT  →  "CHOCH SUPPLY"  (bearish CHoCH)
    #   MICRO_CHOCH_LONG  / MICRO CHOCH LONG   →  "CHOCH DEMAND"  (bullish CHoCH)
    #   SWEEP_RECLAIM_SHORT / SWEEP RECLAIM SHORT → "LH"           (lower high structure)
    #   SWEEP_RECLAIM_LONG  / SWEEP RECLAIM LONG  → "HL"           (higher low structure)
    # DELTA_FLIP and MICRO_VWAP are NOT bridged — order-flow / price-level
    # context only, not price structure. 5-minute dedup per (inst, bridge_type)
    # prevents duplicate injections from duplicate TradingView webhook calls.
    if normalized in FAST_ENTRY_TYPES:
        _fe_bridge = (
            "CHOCH SUPPLY" if normalized in FAST_MICRO_CHOCH_SHORT_TYPES  else
            "CHOCH DEMAND" if normalized in FAST_MICRO_CHOCH_LONG_TYPES   else
            "LH"           if normalized in FAST_SWEEP_RECLAIM_SHORT_TYPES else
            "HL"           if normalized in FAST_SWEEP_RECLAIM_LONG_TYPES  else
            None
        )
        if _fe_bridge is not None:
            _now_fe   = now_utc()
            _fe_dedup = (resolved_inst, _fe_bridge)
            _fe_last  = _FE_BRIDGE_LAST.get(_fe_dedup)
            if _fe_last is None or (_now_fe - _fe_last).total_seconds() > 300:
                _FE_BRIDGE_LAST[_fe_dedup] = _now_fe
                LAST_ALERT_AT = _now_fe
                ALERT_HISTORY.append({
                    "alert_type":  _fe_bridge,
                    "ticker":      data.get("ticker"),
                    "instrument":  resolved_inst,
                    "price":       parsed_price,
                    "timestamp":   _now_fe.isoformat(),
                    "source":      "fast_entry_bridge",
                    "canonical":   True,   # bridge events are unique synthetic translations
                    "raw":         {"original_type": normalized},
                })
                logger.info("Fast-entry bridge: %s → %s (%s)",
                            normalized, _fe_bridge, resolved_inst)
        return jsonify({"status": "fast_entry_signal", "alert_type": normalized,
                        "ticker": resolved_inst, "price": parsed_price}), 200

    # ── Data-only VWAP push — store already updated above; ack without scoring ──
    if normalized in _DATA_ONLY_TYPES:
        _vk = resolved_inst
        _vv, _vs = get_vwap(_vk)
        logger.info("VWAP update: %s = %s (%s)", _vk, _vv, _vs)
        _record_diagnostic("%s | %s — VWAP update = %s (%s) — data only, no scoring" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), _vk, _vv, _vs))
        return jsonify({
            "status":      "vwap_updated",
            "ticker":      _vk,
            "vwap":        _vv,
            "vwap_status": _vs,
            "price":       parsed_price if parsed_price is not None else CURRENT_PRICE,
        }), 200

    # ── Command types: ENTER / CLOSE sent via TradingView webhook ─────────────
    #    Per user choice, the webhook stays OPEN (no shared-secret) so existing
    #    TradingView ENTER/CLOSE alerts work unmodified. Trade entry/exit is also
    #    available via the password-protected dashboard (/enter, /close).
    #    NOTE: this path is intentionally unauthenticated — anyone who knows the
    #    webhook URL can trigger ENTER/CLOSE here. The user accepted this tradeoff
    #    in favour of keeping their TradingView automation working as-is.
    if normalized in _COMMAND_TYPES:
        _resp = _handle_command_alert(normalized, data, parsed_price, resolved_inst)
        if _resp is not None:
            return _resp

    # ── Confirmation cooldown (TV + Databento) ────────────────────────────────
    #    Suppress same-direction CONFIRMATION re-fires within CONFIRM_COOLDOWN_MIN
    #    minutes per instrument, regardless of source (TradingView or Databento
    #    injection). Direction resets the cooldown automatically — a BULLISH
    #    CONFIRMATION after a BEARISH one is never suppressed.
    if normalized.endswith(" BULLISH CONFIRMATION") or normalized.endswith(" BEARISH CONFIRMATION"):
        _conf_side = "bull" if "BULLISH" in normalized else "bear"
        _conf_now  = datetime.now(timezone.utc)
        _conf_last = _CONFIRM_COOLDOWN_TS.get(resolved_inst, {}).get(_conf_side)
        if _conf_last is not None:
            _conf_age_min = (_conf_now - _conf_last).total_seconds() / 60.0
            if _conf_age_min < CONFIRM_COOLDOWN_MIN:
                logger.info(
                    "Confirm cooldown: %s suppressed (%.1f / %d min)",
                    normalized, _conf_age_min, CONFIRM_COOLDOWN_MIN,
                )
                return jsonify({
                    "status":       "suppressed",
                    "reason":       "confirmation cooldown",
                    "instrument":   resolved_inst,
                    "side":         _conf_side,
                    "age_min":      round(_conf_age_min, 1),
                    "cooldown_min": CONFIRM_COOLDOWN_MIN,
                }), 200
        _CONFIRM_COOLDOWN_TS.setdefault(resolved_inst, {})[_conf_side] = _conf_now

    record = {
        "alert_type":        normalized,
        "ticker":            data.get("ticker"),
        "instrument":        resolved_inst,
        "instrument_source": res["source"],
        "price":             parsed_price,
        "timestamp":         now_utc().isoformat(),
        "raw":               data,
    }
    # ── Structure-event source tagging + dedup ─────────────────────────────────
    # Explicitly tag every TV alert with source='tradingview'.  For structure
    # types (BOS/CHOCH/HH/HL/LH/LL), check whether a canonical Databento event
    # already exists in ALERT_HISTORY for the same logical break; if so, mark
    # this record as a shadow duplicate so gate consumers skip it.
    # Fail-open: any exception falls back to canonical=True (preserves existing
    # behaviour for all affected records).
    try:
        STRUCTURE_DEDUP.on_tv_event(record, list(ALERT_HISTORY))
    except Exception as _sde:
        logger.debug("structure_dedup.on_tv_event: %s", _sde)
        record.setdefault("source",    "tradingview")
        record.setdefault("canonical", True)
    LAST_ALERT_AT = datetime.now(timezone.utc)
    ALERT_HISTORY.append(record)

    # ── Zone event side-effects ──
    #    Registry-driven sets so every enabled instrument's zone events are handled
    #    (MGC/MNQ membership unchanged — same set plus MES/MYM).
    _zone_broken_set = _per_inst_alert_set("ZONE BROKEN")
    _zone_mitig_set  = _per_inst_alert_set("ZONE MITIGATED")
    _zone_neutral    = _zone_broken_set | _zone_mitig_set
    if normalized in _zone_broken_set:
        _zb_instrument = _instrument_from_text(normalized)
        if parsed_price is not None:
            _handle_zone_broken(parsed_price, _zb_instrument)
        else:
            ZONE_BROKEN_AT = {"price": None, "alerts_since": 0, "instrument": _zb_instrument}
    elif normalized in _zone_mitig_set:
        if parsed_price is not None:
            _handle_zone_mitigated(parsed_price, resolved_inst)
    elif ZONE_BROKEN_AT is not None and normalized not in _zone_neutral:
        # Count expiry only on same-instrument alerts so the other instrument's
        # activity can't prematurely clear this instrument's broken-zone blocker.
        # Untagged (legacy) breaks expire on any alert (global fallback).
        _zb_inst = ZONE_BROKEN_AT.get("instrument")
        if _zb_inst is None or _zb_inst == resolved_inst:
            ZONE_BROKEN_AT["alerts_since"] = ZONE_BROKEN_AT.get("alerts_since", 0) + 1
            if ZONE_BROKEN_AT["alerts_since"] >= ZONE_BROKEN_EXPIRY:
                ZONE_BROKEN_AT = None
                logger.info("Zone broken state expired after %d alerts", ZONE_BROKEN_EXPIRY)

    # ── Zone Mitigation: clear flag when fresh structure forms ──────────────────
    _STRUCTURE_RESET = (
        frozenset(("CHOCH SUPPLY", "CHOCH DEMAND", "BOS SUPPLY", "BOS DEMAND"))
        | _per_inst_alert_set("NEW SUPPLY ZONE")
        | _per_inst_alert_set("NEW DEMAND ZONE")
    )
    # SWING ONLY: a new structure alert clears the consumed-zone mitigation flag so a
    # fresh BOS/CHOCH re-opens the zone gate. SCALP must NOT clear here — doing so wiped
    # the flag every time required structure formed, so structure and a valid zone could
    # never coexist (the root cause of "nothing fires on trends"). In SCALP the
    # mitigation/consumed state persists and is reset ONLY by a new mitigation, a ZONE
    # BROKEN (price beyond the invalidation level) or TTL expiry (is_near_mitigated_zone
    # / MITIGATED_TTL_MIN), matching the zone state machine.
    if (cfg("GATE_REQUIRE_ZONE")
            and normalized in _STRUCTURE_RESET
            and MITIGATED_FLAG_BY_TICKER.get(resolved_inst)):
        MITIGATED_FLAG_BY_TICKER[resolved_inst] = False
        logger.info("Zone mitigation cleared (%s) — new structure alert: %s",
                    resolved_inst, normalized)

    # ── Account Profile selection ──
    profile_name = str(data.get("profile") or DEFAULT_PROFILE).strip()
    if profile_name in ACCOUNT_PROFILES:
        prof         = ACCOUNT_PROFILES[profile_name]
        account_size = prof["account_size"]
        risk_pct     = prof["risk_pct"]
    else:
        profile_name = "Custom"
        try:
            account_size = float(data.get("account_size") or DEFAULT_ACCOUNT_SIZE)
        except (ValueError, TypeError):
            account_size = DEFAULT_ACCOUNT_SIZE
        try:
            risk_pct = float(data.get("risk_pct") or DEFAULT_RISK_PCT)
        except (ValueError, TypeError):
            risk_pct = DEFAULT_RISK_PCT

    # ── Inbound signal de-dup (additive, DIAGNOSTIC only) ────────────────────────
    # Flag a repeat of the SAME (instrument, alert_type) seen within the cooldown so
    # the operator can SEE how many duplicates the 1-min TradingView repeats produce.
    # This NEVER skips the enqueue or full_analysis, and NEVER suppresses a dispatch
    # — the authoritative, zone-aware non-duplication already lives downstream. A
    # direction flip or different setup is a different key, so it's never a duplicate.
    is_duplicate          = False
    cooldown_remaining_ms = None
    try:
        _dedup_inst   = instrument_of(resolved_inst)
        _cooldown_sec = signal_dedup_cooldown_sec(_dedup_inst)
        sig_key = (_dedup_inst, normalized)
        with DEDUP_LOCK:
            _prev_seen = SIGNAL_DEDUP.get(sig_key)
            if _prev_seen is not None:
                _elapsed = (webhook_received_at - _prev_seen).total_seconds()
                if 0 <= _elapsed < _cooldown_sec:
                    is_duplicate          = True
                    cooldown_remaining_ms = round(
                        (_cooldown_sec - _elapsed) * 1000.0, 1)
            SIGNAL_DEDUP[sig_key] = webhook_received_at
        if is_duplicate:
            with COUNTERS_LOCK:
                COUNTERS["duplicates_ignored"] += 1
                COUNTERS["wait_reasons_breakdown"]["cooldown_duplicate"] = \
                    COUNTERS["wait_reasons_breakdown"].get("cooldown_duplicate", 0) + 1
                COUNTERS["rejection_reasons"]["cooldown_duplicate"] = \
                    COUNTERS["rejection_reasons"].get("cooldown_duplicate", 0) + 1
                _DUP_TS.append(webhook_received_at)
    except Exception as exc:
        logger.error("Signal dedup check failed (alert still processed): %s", exc)

    # ── Hand the heavy tail (analysis + journaling + Discord) to the background
    # worker and ack immediately so TradingView never times out. Every piece of
    # state the job needs has been committed synchronously above (ALERT_HISTORY,
    # zone flags, price/VWAP); the per-alert price is passed explicitly. ──
    _ensure_webhook_worker()
    _WEBHOOK_JOBS.put({
        "record":              record,
        "parsed_price":        parsed_price,
        "resolved_inst":       resolved_inst,
        "normalized":          normalized,
        "account_size":        account_size,
        "risk_pct":            risk_pct,
        "profile_name":        profile_name,
        "webhook_received_at": webhook_received_at,
        "is_duplicate":        is_duplicate,
        "cooldown_remaining_ms": cooldown_remaining_ms,
    })

    return jsonify({
        "status":       "accepted",
        "alert_type":   normalized,
        "ticker":       record.get("ticker"),
        "instrument":   resolved_inst,
        "queued":       True,
        "total_alerts": len(ALERT_HISTORY),
    }), 200


@app.route("/alerts", methods=["GET"])
def get_alerts():
    return jsonify({"alerts": list(ALERT_HISTORY), "count": len(ALERT_HISTORY)}), 200


@app.route("/diagnostics", methods=["GET"])
def get_diagnostics():
    """Owner-only (dashboard password, enforced by the Express proxy) plain-text
    view of the most recent per-webhook gate diagnostics — newest first. `?n=`
    limits the count (default 60). Shows EXACTLY why each alert was WAIT/READY."""
    try:
        n = int(request.args.get("n", 60))
    except (ValueError, TypeError):
        n = 60
    n = max(1, min(n, GATE_DIAGNOSTICS.maxlen))
    entries = list(GATE_DIAGNOSTICS)[-n:][::-1]
    header = ("Gate diagnostics — %d shown of %d buffered (newest first).\n"
              "Add ?n=N to show more (max %d). Each webhook the bot scores appears "
              "here with a per-gate PASS/FAIL breakdown.\n" % (
                  len(entries), len(GATE_DIAGNOSTICS), GATE_DIAGNOSTICS.maxlen))
    body = "\n\n".join(entries) if entries else "No webhooks received yet."
    return Response(header + "\n" + body + "\n", mimetype="text/plain")


# ── Live Diagnostics page ────────────────────────────────────────────────────
# Static HTML (no server-side templating: no %-formatting, no triple-quote
# collisions). All data is fetched client-side from /api/eval-metrics every 1s.
DIAGNOSTICS_LIVE_HTML = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Diagnostics - AI Trading Partner</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{background:#0a0a0f;color:#e8e8f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;padding:16px}
  a.back{color:#a0a8ff;text-decoration:none;font-size:13px}
  h1{font-size:18px;font-weight:700;color:#a0a8ff;letter-spacing:.5px;margin:8px 0 2px}
  .sub{font-size:12px;color:#666;margin-bottom:16px}
  .cards{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:18px}
  /* Verdict + Why/Reason share one row: 50/50, equal height, side by side on
     desktop & tablet; stacks only on small mobile. */
  .verdict-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px;align-items:stretch}
  .verdict-row .card{min-width:0}
  @media (max-width:560px){.verdict-row{grid-template-columns:1fr}}
  .card{background:#12121e;border:1px solid #1e1e32;border-radius:12px;padding:12px 14px;min-width:140px;flex:1}
  .card .k{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#666;margin-bottom:6px}
  .card .v{font-size:20px;font-weight:800}
  .card .v.sm{font-size:13px;font-weight:600;white-space:normal;word-break:break-word;line-height:1.3}
  .good{color:#22c55e}.warn{color:#f59e0b}.bad{color:#ef4444}.muted{color:#888}
  .wrap{overflow-x:auto;border:1px solid #1e1e32;border-radius:12px}
  table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}
  th,td{padding:8px 10px;text-align:right;border-bottom:1px solid #16162a}
  th{position:sticky;top:0;background:#16162a;color:#a0a8ff;font-size:10px;text-transform:uppercase;letter-spacing:.5px;text-align:right}
  th:nth-child(-n+4),td:nth-child(-n+4){text-align:left}
  tbody tr:hover{background:#12121e}
  .v-ready{color:#22c55e;font-weight:700}.v-wait{color:#888}
  .empty{padding:24px;text-align:center;color:#666}
</style>
</head>
<body>
<a class="back" href="/api/dashboard">&larr; Back to dashboard</a>
<h1>Diagnostics</h1>
<div class="sub">Per-evaluation timing &amp; volatility for the last <span id="cap">100</span> scored alerts &middot; auto-refresh 1s &middot; <span id="updated" class="muted"></span></div>
<div class="verdict-row" id="verdict-row"></div>
<div class="cards" id="summary"></div>
<div class="wrap">
<table>
<thead><tr>
<th>Webhook Recv (ET)</th><th>Instr</th><th>Verdict</th><th>Wait Reason</th>
<th>Dir</th><th>Setup</th><th>Dup</th>
<th>Eval Start</th><th>Eval Finish</th>
<th>Eval ms</th><th>Total ms</th><th>Indicator ms</th><th>Volatility ms</th><th>Scoring ms</th>
<th>AI Notes ms</th><th>Screenshot ms</th><th>Journal ms</th>
<th>Alert Sent</th><th>Alert Delay ms</th>
<th>ATR</th><th>Base ATR</th><th>Mult</th><th>Threshold</th><th>Vol Decision</th>
<th>Alert Level</th><th>Edge</th><th>Confirms</th><th>Gate Blockers</th>
<th>Sent?</th><th>Cooldown Left ms</th><th>Suppressed</th>
<th>Event Start</th><th>Sweep</th><th>CHOCH</th><th>Displacement</th>
<th>Early Alert</th><th>Ready Alert</th><th>Delay s</th><th>Waited Close</th>
<th>Trigger</th><th>Zone</th><th>VWAP</th><th>Struct</th><th>Candle</th><th>Liq</th><th>Vol</th><th>Conf</th>
</tr></thead>
<tbody id="rows"><tr><td class="empty" colspan="47">Loading...</td></tr></tbody>
</table>
</div>
<script>
var BASE='/api';
function ms(v){return (v===null||v===undefined)?'-':Number(v).toFixed(1);}
function num(v){return (v===null||v===undefined)?'-':Number(v).toFixed(2);}
function intOrDash(v){return (v===null||v===undefined)?'-':Number(v).toFixed(0);}
function confs(e){
  var p=e.confirmationsPassed,n=e.confirmationsNeeded;
  if(p===null||p===undefined) return '-';
  return p+'/'+((n===null||n===undefined)?'-':n);
}
function etTime(iso){
  if(!iso) return '-';
  var dt=new Date(iso);
  if(isNaN(dt.getTime())) return '-';
  var t=dt.toLocaleTimeString('en-US',{hour12:false,timeZone:'America/New_York'});
  return t+'.'+String(dt.getMilliseconds()).padStart(3,'0');
}
function delayClass(v){
  if(v===null||v===undefined) return 'muted';
  if(v<1000) return 'good';
  if(v<3000) return 'warn';
  return 'bad';
}
function card(k,v,cls){return '<div class="card"><div class="k">'+k+'</div><div class="v '+(cls||'')+'">'+v+'</div></div>';}
function setupStateTxt(s){
  if(!s) return '-';
  var ks=Object.keys(s); if(!ks.length) return '-';
  return ks.map(function(k){
    var v=s[k]||{}; var st=v.state||'-'; var d=v.direction?(' '+v.direction):'';
    return k+': '+st+d;
  }).join(' \u00b7 ');
}
function setupStateCls(s){
  if(!s) return 'muted';
  var vals=Object.keys(s).map(function(k){return (s[k]||{}).state;});
  if(vals.indexOf('ACTIVE')>=0||vals.indexOf('READY')>=0) return 'good';
  if(vals.indexOf('INVALIDATED')>=0) return 'warn';
  if(vals.indexOf('FORMING')>=0) return '';
  return 'muted';
}
function yn(v){return (v===true)?'<span class="good">Y</span>':((v===false)?'<span class="bad">N</span>':'<span class="muted">-</span>');}
function pct(v){return (v===null||v===undefined)?'-':Number(v).toFixed(0)+'%';}
function fmtAgo(sec){
  if(sec===null||sec===undefined) return 'never';
  if(sec<60) return Math.round(sec)+'s ago';
  if(sec<3600) return Math.round(sec/60)+'m ago';
  return Math.round(sec/3600)+'h ago';
}
function showError(msg){
  var u=document.getElementById('updated');
  if(u){ u.className='bad'; u.textContent='\u26a0 '+msg+' \u2014 retrying every second'; }
  var rows=document.getElementById('rows');
  if(rows && rows.querySelector('.empty')){
    rows.innerHTML='<tr><td class="empty" colspan="47">'+msg+' \u2014 retrying every second.</td></tr>';
  }
}
async function refresh(){
  var data;
  try{
    var r=await fetch(BASE+'/eval-metrics',{headers:{'Content-Type':'application/json'},cache:'no-store'});
    if(!r.ok){ showError('Server returned HTTP '+r.status); return; }
    data=await r.json();
  }catch(e){ showError('Cannot reach the metrics endpoint ('+((e&&e.message)||'network error')+')'); return; }
  var evals=data.evaluations||[];
  document.getElementById('cap').textContent=data.max||100;
  var u=document.getElementById('updated');
  u.className='muted';
  u.textContent='updated '+new Date().toLocaleTimeString('en-US',{hour12:false});
  var st=data.stats||{};
  var c=st.counters||{};
  var sess=st.session||{};
  var wrb=c.wait_reasons_breakdown||{};
  var wrbTop=Object.keys(wrb).sort(function(a,b){return wrb[b]-wrb[a];}).slice(0,5)
              .map(function(k){return k+' ('+wrb[k]+')';}).join(', ')||'-';
  var rr=c.rejection_reasons||{};
  var rrLabel={zone_valid:'zone_valid',vwap_confirmed:'vwap_confirmed',
    structure_confirmed:'structure_confirmed',location:'location',
    volume_unconfirmed:'volume',cvd_conflict:'cvd_conflict',
    volatility_block:'volatility_block',edge_score_low:'edge_score',
    conflicting_structure:'conflict',cooldown_duplicate:'cooldown_dup',
    session_filter:'session(bonus,n/a)'};
  var rrKeys=Object.keys(rrLabel).sort(function(a,b){return (rr[b]||0)-(rr[a]||0);});
  var rrTxt=rrKeys.map(function(k){return rrLabel[k]+' ('+(rr[k]||0)+')';}).join(', ');
  var sum=document.getElementById('summary');
  var vr=document.getElementById('verdict-row');
  var e=evals.length?evals[0]:null;
  var ready=!!(e&&(e.verdict||'').indexOf('READY')>=0);
  var sinceTxt=fmtAgo(st.timeSinceLastWebhookSec);
  var staleWh=(st.timeSinceLastWebhookSec==null||st.timeSinceLastWebhookSec>900);
  // Verdict (left) + Why/Reason (right) live in their own 50/50 row so the
  // trade decision and its explanation are always visible together.
  vr.innerHTML=
    card('Latest verdict', e?(e.verdict||'-'):'-', ready?'good':'muted')+
    card('Latest WAIT reason', e?(ready?'\u2014 ready \u2014':(e.waitReason||e.gateBlockers||'-')):'-', 'sm '+(ready?'good':'warn'));
  sum.innerHTML=
    card('Webhooks received', (c.webhooks_received!=null?c.webhooks_received:'-'), 'muted')+
    card('Evaluations run', (c.evaluations_run!=null?c.evaluations_run:'-'), 'muted')+
    card('READY setups', (c.ready_setups_detected!=null?c.ready_setups_detected:'-'), (c.ready_setups_detected>0?'good':'muted'))+
    card('Alerts sent', (c.alerts_sent!=null?c.alerts_sent:'-'), (c.alerts_sent>0?'good':'muted'))+
    card('Last webhook', sinceTxt, (staleWh?'warn':'good'))+
    card('Eval frequency', (st.evaluationFrequencySeconds!=null?('every '+st.evaluationFrequencySeconds+'s'):'-'), (st.evalHeartbeatEnabled?'good':'bad'))+
    card('Signals passed', (st.signalsPassedFilters!=null?st.signalsPassedFilters:'-'), (st.signalsPassedFilters>0?'good':'muted'))+
    card('Signals rejected', (st.signalsRejected!=null?st.signalsRejected:'-'), 'muted')+
    card('Duplicates ignored', (st.duplicatesIgnored!=null?st.duplicatesIgnored:'-')+(st.duplicatesIgnoredLastHour!=null?(' ('+st.duplicatesIgnoredLastHour+'/hr)'):''), (st.duplicatesIgnored>0?'warn':'muted'))+
    card('Alerts last hour', (st.alertsReceivedLastHour!=null?st.alertsReceivedLastHour:'-'), 'muted')+
    card('Avg processing', (st.averageProcessingTimeMs!=null?(Number(st.averageProcessingTimeMs).toFixed(1)+' ms'):'-'), 'muted')+
    card('Queue length', (st.currentQueueLength!=null?st.currentQueueLength:'-'), (st.currentQueueLength>5?'warn':'muted'))+
    card('Setup states', setupStateTxt(st.setupStates), 'sm '+(setupStateCls(st.setupStates)))+
    card('Dedup cooldown', (st.signalDedupCooldownSec!=null?(st.signalDedupCooldownSec+'s'):'-'), 'sm muted')+
    card('Session', (sess.window||'-'), 'sm '+(sess.preferred?'good':'muted'))+
    card('Top WAIT reasons', wrbTop, 'sm muted')+
    card('Rejection reasons (condition gaps)', rrTxt, 'sm muted');
  var rows=document.getElementById('rows');
  if(!evals.length){
    rows.innerHTML='<tr><td class="empty" colspan="47">No evaluations yet - waiting for the next webhook.</td></tr>';
    return;
  }
  // READY setups float to the top (they are the actionable rows); the heartbeat
  // re-evaluates constantly, so a strict newest-first order would bury them. The
  // sort is stable, so newest-first is preserved WITHIN the READY and non-READY
  // groups. Display-only - does not change evaluation order anywhere else.
  var ordered=evals.slice().sort(function(a,b){
    var ra=((a.verdict||'').indexOf('READY')>=0)?0:1;
    var rb=((b.verdict||'').indexOf('READY')>=0)?0:1;
    return ra-rb;
  });
  rows.innerHTML=ordered.map(function(e){
    var vc=(e.verdict||'').indexOf('READY')>=0?'v-ready':'v-wait';
    return '<tr>'+
      '<td>'+etTime(e.webhookReceivedAt)+'</td>'+
      '<td>'+(e.instrument||'-')+'</td>'+
      '<td class="'+vc+'">'+(e.verdict||'-')+'</td>'+
      '<td style="text-align:left">'+(e.waitReason||'-')+'</td>'+
      '<td>'+(e.direction||'-')+'</td>'+
      '<td style="text-align:left">'+(e.setupType||'-')+'</td>'+
      '<td class="'+(e.isDuplicate?'warn':'muted')+'">'+(e.isDuplicate?'dup':'-')+'</td>'+
      '<td>'+etTime(e.evaluationStartedAt)+'</td>'+
      '<td>'+etTime(e.evaluationFinishedAt)+'</td>'+
      '<td>'+ms(e.evaluationDurationMs)+'</td>'+
      '<td>'+ms(e.totalLatencyMs)+'</td>'+
      '<td>'+ms(e.indicatorCalcMs)+'</td>'+
      '<td>'+ms(e.volatilityCalcMs)+'</td>'+
      '<td>'+ms(e.scoringMs)+'</td>'+
      '<td>'+ms(e.aiNotesMs)+'</td>'+
      '<td>'+ms(e.screenshotMs)+'</td>'+
      '<td>'+ms(e.journalWriteMs)+'</td>'+
      '<td>'+etTime(e.alertSentAt)+'</td>'+
      '<td class="'+delayClass(e.totalAlertDelayMs)+'">'+ms(e.totalAlertDelayMs)+'</td>'+
      '<td>'+num(e.currentATR)+'</td>'+
      '<td>'+num(e.baselineATR)+'</td>'+
      '<td>'+num(e.volatilityMultiplier)+'</td>'+
      '<td>'+num(e.volatilityThreshold)+'</td>'+
      '<td style="text-align:left">'+(e.volatilityDecision||'-')+'</td>'+
      '<td class="'+(e.alertLevel==='READY'?'v-ready':(e.alertLevel?'warn':'muted'))+'">'+(e.alertLevel||'-')+'</td>'+
      '<td>'+intOrDash(e.edgeScore)+'</td>'+
      '<td>'+confs(e)+'</td>'+
      '<td style="text-align:left">'+(e.gateBlockers||'-')+'</td>'+
      '<td class="'+(e.alertSent?'good':'muted')+'">'+(e.alertSent?'yes':'no')+'</td>'+
      '<td>'+ms(e.cooldownRemainingMs)+'</td>'+
      '<td class="'+(e.suppressedByCooldown?'warn':'muted')+'">'+(e.suppressedByCooldown?'yes':'-')+'</td>'+
      '<td>'+etTime(e.eventStartTime)+'</td>'+
      '<td>'+etTime(e.sweepTime)+'</td>'+
      '<td>'+etTime(e.chochTime)+'</td>'+
      '<td>'+etTime(e.displacementTime)+'</td>'+
      '<td>'+etTime(e.earlyAlertTime)+'</td>'+
      '<td>'+etTime(e.readyAlertTime)+'</td>'+
      '<td>'+(e.alertDelaySeconds==null?'-':Number(e.alertDelaySeconds).toFixed(1))+'</td>'+
      '<td class="'+(e.waitedForCandleClose===true?'bad':(e.waitedForCandleClose===false?'good':'muted'))+'">'+(e.waitedForCandleClose===true?'yes':(e.waitedForCandleClose===false?'no':'-'))+'</td>'+
      '<td class="'+(e.trigger==='heartbeat'?'muted':'')+'">'+(e.trigger||'webhook')+'</td>'+
      '<td>'+yn(e.zoneValid)+'</td>'+
      '<td>'+yn(e.vwapConfirmed)+'</td>'+
      '<td>'+yn(e.structureConfirmed)+'</td>'+
      '<td>'+yn(e.candleConfirmed)+'</td>'+
      '<td>'+yn(e.liquidityConfirmed)+'</td>'+
      '<td>'+yn(e.volatilityConfirmed)+'</td>'+
      '<td>'+pct(e.confidenceScore)+'</td>'+
    '</tr>';
  }).join('');
}
refresh();
setInterval(refresh,1000);
</script>
</body>
</html>"""


