@app.route("/ping", methods=["GET", "POST", "HEAD"])
def ping():
    # Simple health/test endpoint — no alert logic. Used by UptimeRobot and for testing.
    return jsonify({"status": "ok", "trading_mode": TRADING_MODE}), 200


@app.route("/notify-test", methods=["POST"])
def notify_test():
    """Owner-only test of the READY phone-notification path.

    Fires a REAL Discord push (with the @everyone mention, so a phone set to "Only
    @mentions" still buzzes) to the exact channel this instrument's live READY card
    would use — letting the operator confirm end-to-end that the phone rings even
    when no setup is currently READY. Returns a clear diagnostic (sent / why-not) so
    a silent phone can be triaged: channel-not-configured vs muted vs delivered.

    Pure notification test: NEVER touches the gate, scoring, sizing, journaling,
    tracking or ANY broker/execution path. Owner-only (Basic Auth + CSRF via the
    Express proxy; deliberately NOT in OPEN_PATHS). Fail-open — a send failure is
    reported as {sent: false, reason}, never a 500."""
    data = request.get_json(silent=True) or {}
    inst = (_instrument_from_text(data.get("instrument") or data.get("inst")
                                  or data.get("ticker")) or "MGC")
    url = _discord_url(inst)
    if not url:
        return jsonify({"ok": False, "sent": False, "instrument": inst,
                        "reason": "No Discord webhook is configured for this "
                                  "instrument (set DISCORD_WEBHOOK_URL)."}), 200
    muted = _alerts_muted(inst)
    embed = {
        "title":       "🔔 Test Alert — notifications are working",
        "description": ("This is a **test** of your READY-setup phone alert for "
                        "**%s**. It is NOT a trade signal. If this reached your "
                        "phone, real READY alerts will too." % inst),
        "color":       0x22C55E,
        "footer":      {"text": "Manual test · %s · not a trade signal" % inst},
        "timestamp":   now_utc().isoformat(),
    }
    payload = {"embeds": [embed]}
    if DISCORD_ALERT_MENTION:
        payload["content"]          = DISCORD_ALERT_MENTION
        payload["allowed_mentions"] = {"parse": ["everyone", "users", "roles"]}
    try:
        resp = requests.post(url, json=payload, timeout=10)
        ok   = resp.status_code in (200, 204)
        return jsonify({
            "ok":         ok,
            "sent":       ok,
            "instrument": inst,
            "muted_note": (bool(muted) or None),
            "reason":     (None if ok else "Discord returned HTTP %s" % resp.status_code),
        }), 200
    except Exception as exc:
        # Never surface str(exc): a requests/urllib3 error can embed the full Discord
        # webhook URL (which carries the bearer token). Log the class only, and keep
        # the browser-facing reason generic so the secret can't leak via logs OR API.
        logger.error("notify-test send error (%s): %s", inst, type(exc).__name__)
        return jsonify({"ok": False, "sent": False, "instrument": inst,
                        "reason": "Send failed — check server logs."}), 200


@app.route("/mode", methods=["GET", "POST"])
def mode():
    """Read or switch the active trading mode (SCALP / SWING) at runtime."""
    global TRADING_MODE
    if request.method == "POST":
        data      = request.get_json(silent=True) or {}
        requested = str(data.get("mode", "")).upper()
        if requested not in MODES:
            return jsonify({"status": "error",
                            "reason": f"Unknown mode {requested!r}. Use one of {list(MODES)}."}), 400
        TRADING_MODE = requested
        _save_market_state("trading_mode_override", {"mode": requested})
        logger.info("Trading mode switched to %s (persisted)", TRADING_MODE)
    return jsonify({
        "status":          "ok",
        "trading_mode":    TRADING_MODE,
        "available_modes": list(MODES),
        "thresholds":      MODES[TRADING_MODE],
    }), 200


@app.route("/alerts/mute", methods=["GET", "POST"])
def alerts_mute():
    """Read or set the per-instrument alert mute flags (MGC / MNQ).

    Muting suppresses the Discord NEW-SETUP alerts for that instrument — the live
    READY card (incl. @everyone + A+ mirror), the EARLY teaser, the tiered
    WATCH/ARMED alerts, the new-entry journal embed and the zone-mitigated notice —
    while the engine keeps EVALUATING it, writing the journal record, and recording
    diagnostics/eval-metrics (no data gap). Active-position lifecycle / outcome /
    execution alerts are NEVER muted. State is in-memory and resets to unmuted on
    restart (fail-safe toward alerting). Owner-only (Basic Auth + CSRF via the
    Express proxy; deliberately NOT in OPEN_PATHS)."""
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        inst = _instrument_from_text(data.get("instrument") or data.get("inst"))
        if inst is None:
            return jsonify({"status": "error",
                            "reason": "instrument must be exactly 'MGC' or 'MNQ'."}), 400
        muted = bool(data.get("muted"))
        with ALERTS_MUTED_LOCK:
            ALERTS_MUTED[inst] = muted
        logger.info("Alerts %s for %s", "MUTED" if muted else "UNMUTED", inst)
    with ALERTS_MUTED_LOCK:
        snapshot = dict(ALERTS_MUTED)
    return jsonify({"status": "ok", "muted": snapshot}), 200



@app.route("/micro-scalp", methods=["GET", "POST"])
def micro_scalp_toggle():
    """Read or set the MICRO SCALP MODE toggle + the LIVE arm + the ghost ledger.

    Two independent switches, both in-memory and RESET OFF on restart (fail-safe):
      • "enabled" — the mode toggle. ON = the brain analyzes + logs GHOST trades.
      • "live"    — the LIVE arm (separate, explicit). ON = a TAKE additionally
        fires a REAL order through the SAME audited execute_trade_gateway
        (source="micro_scalp") the main bot uses; every shared safety layer
        applies. Arming requires the mode toggle ON; toggling the mode OFF
        force-disarms LIVE. Ghost logging continues regardless, so live results
        always have a ghost mirror.
    Owner-only (Basic Auth + CSRF via the Express proxy; NOT in OPEN_PATHS)."""
    global MICRO_SCALP_MODE, MICRO_LIVE_ARMED
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        if "enabled" in data:
            enabled = bool(data.get("enabled"))
            with MICRO_SCALP_LOCK:
                MICRO_SCALP_MODE = enabled
                if not enabled:
                    MICRO_LIVE_ARMED = False   # mode OFF force-disarms LIVE (fail-safe)
            if enabled and not MICRO_GHOST_DB_READY:
                _check_micro_ghost_db_ready()  # lazy no-DDL probe on first arm
            logger.info("MICRO SCALP MODE %s",
                        "ENABLED" if enabled else "DISABLED (LIVE force-disarmed)")
        if "live" in data:
            want = bool(data.get("live"))
            with MICRO_SCALP_LOCK:
                if want and not MICRO_SCALP_MODE:
                    want = False               # can't arm LIVE while the mode is OFF
                MICRO_LIVE_ARMED = want
            logger.warning("MICRO SCALP LIVE %s — real broker orders %s fire on TAKE "
                           "(%d contract(s), single %s exit).",
                           "ARMED" if want else "DISARMED",
                           "WILL" if want else "will NOT",
                           MICRO_LIVE_CONTRACTS, MICRO_LIVE_TARGET)
    return jsonify({
        "status":         "ok",
        "enabled":        _micro_scalp_on(),
        "live_armed":     _micro_live_armed(),
        "live_contracts": MICRO_LIVE_CONTRACTS,
        "live_target":    MICRO_LIVE_TARGET,
        "db_ready":       bool(MICRO_GHOST_DB_READY),
        "ghost":          _micro_ghost_stats(None),
    }), 200


@app.route("/auto-trade", methods=["GET", "POST"])
def auto_trade_toggle():
    """Read or set the per-instrument AUTO-TRADE flags (MGC / MNQ).

    When ON, a brand-new READY setup automatically routes a server-authoritative
    order through the SAME audited gateway as the manual button. OFF by default and
    RESET TO OFF on restart/republish (fail-safe toward NOT trading). Live
    (real-broker) auto execution additionally requires the live/prod instance.
    Owner-only (Basic Auth + CSRF via the Express proxy; deliberately NOT in
    OPEN_PATHS)."""
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        inst = _instrument_from_text(data.get("instrument") or data.get("inst"))
        if inst is None:
            return jsonify({"status": "error",
                            "reason": "instrument must be one of MGC, MNQ, MES, or MYM."}), 400
        # `enabled` arms/disarms auto-execution; `emergencyDisabled` flips the per-asset
        # kill switch. Both optional so a caller can set either independently (the
        # dashboard always sends `enabled`, so its existing behaviour is unchanged).
        if "enabled" in data:
            enabled = bool(data.get("enabled"))
            with AUTO_TRADE_LOCK:
                AUTO_TRADE[inst] = enabled
            logger.info("Auto-trade %s for %s", "ENABLED" if enabled else "DISABLED", inst)
        if "emergencyDisabled" in data:
            ed = bool(data.get("emergencyDisabled"))
            with AUTO_TRADE_LOCK:
                EMERGENCY_DISABLED[inst] = ed
            # Write-through to the persisted runtime overrides so a kill-switch
            # press survives restart/republish (fail-safe toward NOT trading).
            # FAIL-OPEN on DB error (the in-memory flip stands). Lock order:
            # SAFETY_LOCK taken AFTER (never inside) AUTO_TRADE_LOCK.
            with SAFETY_LOCK:
                _ov = dict(SAFETY_RUNTIME.get(inst) or {})
                _ov["emergencyDisable"] = ed
                SAFETY_RUNTIME[inst] = _ov
            _persist_safety_overrides(inst, _ov)
            logger.info("Emergency-disable %s for %s", "SET" if ed else "CLEARED", inst)
    with AUTO_TRADE_LOCK:
        snapshot = dict(AUTO_TRADE)
    mode = resolve_execution_mode()
    return jsonify({
        "status":                   "ok",
        "enabled":                  snapshot,
        "safety":                   {i: _safety_snapshot(i) for i in enabled_instruments()},
        "execution_mode":           mode,
        "execution_provider_label": _EXECUTION_PROVIDER_LABELS.get(mode, mode),
        "execution_live":           execution_is_live(mode) and execution_configured(mode),
        "is_live_instance":         DISCORD_LIVE_ENABLED,
        "max_per_day":              AUTO_TRADE_MAX_PER_DAY,
        "contracts":                AUTO_TRADE_CONTRACTS,
    }), 200


@app.route("/safety-settings", methods=["GET", "POST"])
def safety_settings():
    """Owner-only runtime per-asset safety controls (Basic Auth + CSRF via the
    Express proxy; deliberately NOT in OPEN_PATHS). GET returns each enabled
    instrument's EFFECTIVE safety config + which layer every value comes from
    (runtime override / registry / default) + a live status snapshot. POST
    {inst, overrides:{...}} FULL-REPLACES that instrument's runtime overrides
    (validated FAIL-CLOSED; absent key = no override; explicit null = unlimited,
    nullable keys only), then persists them (FAIL-OPEN: a DB error keeps the
    in-memory change and reports persisted=false). The gate keeps reading
    lock-free through safety_cfg — this endpoint never touches trade logic."""
    persisted = None
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        inst = _instrument_from_text(data.get("instrument") or data.get("inst"))
        if inst is None:
            return jsonify({"status": "error",
                            "reason": "instrument must be one of MGC, MNQ, MES, or MYM."}), 400
        clean, err = _validate_safety_overrides(data.get("overrides"))
        if err:
            return jsonify({"status": "error", "reason": err}), 400
        with SAFETY_LOCK:
            if clean:
                SAFETY_RUNTIME[inst] = clean
            else:
                SAFETY_RUNTIME.pop(inst, None)
        persisted = _persist_safety_overrides(inst, clean)
        # Keep the runtime kill-switch map in lockstep with the EFFECTIVE value
        # (override if present, else the registry seed). Lock order: AUTO_TRADE_LOCK
        # taken AFTER SAFETY_LOCK is released, never nested.
        _seed = bool((ASSETS[inst].get("safety") or {}).get("emergencyDisable", False))
        with AUTO_TRADE_LOCK:
            EMERGENCY_DISABLED[inst] = bool(clean.get("emergencyDisable", _seed))
        logger.info("Safety overrides for %s replaced with %s (persisted=%s)",
                    inst, clean, persisted)
    elif SAFETY_OVERRIDES_LOAD_FAILED:
        # Lazy retry after a failed boot load (fail-open; never blocks the request).
        _check_safety_overrides_db_ready()
        _load_safety_overrides_from_db()
    out = {}
    for i in enabled_instruments():
        ro = dict(SAFETY_RUNTIME.get(i) or {})
        reg = dict(ASSETS[i].get("safety") or {})
        eff, src = {}, {}
        for k in _SAFETY_OVERRIDE_KEYS:
            if k in ro:
                eff[k], src[k] = ro[k], "runtime"
            elif k in reg:
                eff[k], src[k] = reg[k], "registry"
            else:
                eff[k], src[k] = SAFETY_DEFAULTS.get(k), "default"
        out[i] = {"effective": eff, "source": src, "overrides": ro,
                  "snapshot": _safety_snapshot(i)}
    mode = resolve_execution_mode()
    resp = {
        "status":            "ok",
        "instruments":       out,
        "defaults":          {k: SAFETY_DEFAULTS.get(k) for k in _SAFETY_OVERRIDE_KEYS},
        "contracts_ceiling": TRADERSPOST_MAX_CONTRACTS,
        "db_ready":          SAFETY_OVERRIDES_DB_READY,
        "load_failed":       SAFETY_OVERRIDES_LOAD_FAILED,
        "execution_mode":    mode,
        "is_live_instance":  DISCORD_LIVE_ENABLED,
    }
    if persisted is not None:
        resp["persisted"] = persisted
    return jsonify(resp), 200


