@app.route("/ghost-research/ready-for-review", methods=["GET"])
def route_ghost_research_ready_for_review():
    """Experiments that have reached READY_FOR_REVIEW evidence state.
    Consumed by the GlobalAlertDock poller.  DISPLAY-ONLY.
    Auth handled by Express proxy. NOT in OPEN_PATHS.
    IMPORTANT: this endpoint reports a RESEARCH finding only — it NEVER
    auto-modifies OrbEngine config, live weights, or execution behaviour.
    Any application of research findings requires deliberate operator action.
    """
    if not GRE_DB_READY or not LEARNING_DB_ENABLED:
        return jsonify({"ok": True, "experiments": []})
    conn = _learning_conn()
    if not conn:
        return jsonify({"ok": True, "experiments": []})
    try:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT e.experiment_id, e.variant_name, e.evidence_state,
                       o.instrument, o.direction, o.trading_date,
                       r.net_r, r.entry_timestamp
                FROM ghost_experiments e
                JOIN ghost_opportunities o ON o.opportunity_id=e.opportunity_id
                LEFT JOIN ghost_experiment_results r ON r.experiment_id=e.experiment_id
                WHERE e.evidence_state='READY_FOR_REVIEW'
                ORDER BY r.entry_timestamp DESC NULLS LAST
                LIMIT 20
            """)
            rows = cur.fetchall()
            cols = [d[0] for d in cur.description]
            results = []
            for row in rows:
                d = dict(zip(cols, row))
                d["trading_date"] = d["trading_date"].isoformat() if d.get("trading_date") else None
                d["entry_timestamp"] = d["entry_timestamp"].isoformat() if d.get("entry_timestamp") else None
                results.append(d)
        return jsonify({"ok": True, "experiments": results, "count": len(results)})
    except Exception as exc:
        return jsonify({"ok": False, "error": str(exc)})
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/decision-state", methods=["GET"])
def route_decision_state():
    """Phase 3 Canonical Decision Contract — shadow state dashboard (DISPLAY-ONLY).
    SHADOW MODE ONLY: records are for audit and dashboard — NEVER gates, sizes,
    or sends broker orders.  All behaviour changes require deliberate operator action.
    Owner-only; auth enforced at Express /api edge (Basic Auth + CSRF).
    No @_owner_required here — the decorator is defined later in the file;
    Express-level auth is sufficient (same pattern as ghost-research routes).

    Query params:
      instrument=<MGC|MNQ|…>   — filter to a single instrument
      decision_id=<uuid>        — fetch one record by ID
      transitions=1             — include full transition history for each record
      mismatches=1              — return only records with parity_mismatch flag
    """
    if not DC_DB_READY:
        return jsonify({"ok": True, "shadow_mode": True, "ready": False,
                        "reason": "Decision contract DB not ready (tables may not exist yet)"})
    registry = globals().get("_DECISION_REGISTRY")
    if registry is None:
        return jsonify({"ok": True, "shadow_mode": True, "ready": False,
                        "reason": "DecisionRegistry not initialised (boot error or LEARNING_DB_ENABLED off)"})

    inst_filter    = request.args.get("instrument", "").strip().upper() or None
    decision_id    = request.args.get("decision_id", "").strip() or None
    want_trans     = request.args.get("transitions", "0") == "1"
    want_mismatch  = request.args.get("mismatches", "0") == "1"

    try:
        # get_all_states() returns Dict[str, Optional[Dict]] keyed by instrument
        states_by_inst = registry.get_all_states()
        records_list   = [v for v in states_by_inst.values() if v is not None]

        # Filter by decision_id (fetch one record's full history)
        if decision_id:
            matched = [s for s in records_list if s.get("decision_id") == decision_id]
            if not matched:
                return jsonify({"ok": False, "error": f"decision_id {decision_id!r} not found"}), 404
            out = matched[0]
            if want_trans:
                out["transitions"] = registry.get_history(out.get("instrument", ""), limit=50)
            return jsonify({"ok": True, "shadow_mode": True, "ready": True, "record": out})

        # Filter by instrument
        if inst_filter:
            records_list = [s for s in records_list if s.get("instrument") == inst_filter]

        # Filter to mismatches only
        if want_mismatch:
            records_list = [s for s in records_list if not s.get("parity_agree", True)]

        # Optionally attach transition history per record
        if want_trans:
            for s in records_list:
                s["transitions"] = registry.get_history(s.get("instrument", ""), limit=20)

        # Summary counters
        summary: dict = {}
        for s in records_list:
            state = s.get("state", "UNKNOWN")
            summary[state] = summary.get(state, 0) + 1

        return jsonify({
            "ok":          True,
            "shadow_mode": True,
            "ready":       True,
            "count":       len(records_list),
            "summary":     summary,
            "records":     records_list,
        })
    except Exception as exc:
        logger.warning("DecisionContract /decision-state error: %s", exc)
        return jsonify({"ok": False, "error": str(exc)}), 500


@app.route("/research-events", methods=["GET"])
def route_research_events():
    """Operations Readiness event feed — Phase 8B (DISPLAY-ONLY).

    Returns the newest-first ring-buffer of research events (max 500).
    Query params: limit (1-500, default 100), inst (uppercase), event_type.
    Auth handled by Express proxy.  NOT in OPEN_PATHS.
    NEVER touches gate, scoring, sizing, learning, or execution.
    """
    try:
        limit = min(500, max(1, int(request.args.get("limit", 100))))
    except (TypeError, ValueError):
        limit = 100
    inst_f = (request.args.get("inst", "").strip().upper() or None)
    type_f = (request.args.get("event_type", "").strip().lower() or None)

    with _RESEARCH_EVENTS_LOCK:
        events = list(_RESEARCH_EVENTS)  # already newest-first

    if inst_f:
        events = [e for e in events if e.get("instrument") == inst_f]
    if type_f:
        events = [e for e in events if e.get("event_type") == type_f]

    events = events[:limit]

    return jsonify({
        "ok":            True,
        "events":        events,
        "total":         len(events),
        "boot_ts":       _RESEARCH_BOOT_TS,
        "first_obs_key": _RESEARCH_FIRST_OBS_KEY,
        "error_count":   _RESEARCH_ERROR_COUNT,
        "note": (
            "Phase 8B Operations Readiness event feed — "
            "display-only, never touches gate or execution."
        ),
    })


