@app.route("/pro-review", methods=["GET", "POST"])
def pro_review_controls():
    """Read or set the Professional Review controls: per-instrument MODEL selection
    (SCALP / SWING — the two run separately per instrument) and the global money-path
    VETO toggle.

    The VETO is OFF by default and only DEMOTES an actionable verdict to WAIT (it can
    never promote / force a trade). The runtime toggle wins over the env seed and
    RESETS on restart (fail-safe toward NOT interfering). Model selection is
    per-instrument and in-memory. NEVER affects manual ENTER trades, the base strict
    gate, or scoring. Owner-only (Basic Auth + CSRF via the Express proxy;
    deliberately NOT in OPEN_PATHS)."""
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        if "model" in data:
            inst = instrument_of(data.get("instrument") or data.get("ticker") or "")
            if set_pro_review_model(inst, data.get("model")):
                logger.info("Pro Review model [%s] -> %s", inst, pro_review_model_for(inst))
        if "gate_enabled" in data:
            # Money-path toggle: parse strictly so a stray JSON string ("false") can
            # never arm the live veto. Real booleans (the dashboard) pass straight
            # through; recognised string/number tokens map explicitly; anything
            # ambiguous (null / "maybe" / {}) is IGNORED, leaving the gate unchanged
            # (fail-safe toward NOT interfering with live trading).
            _raw = data.get("gate_enabled")
            _parsed = None
            if isinstance(_raw, bool):
                _parsed = _raw
            elif isinstance(_raw, (int, float)):
                _parsed = bool(_raw)
            elif isinstance(_raw, str):
                _s = _raw.strip().lower()
                if _s in ("1", "true", "yes", "on"):
                    _parsed = True
                elif _s in ("0", "false", "no", "off"):
                    _parsed = False
            if _parsed is not None:
                set_pro_review_gate(_parsed)
                logger.info("Pro Review VETO %s", "ARMED" if _pro_review_gate_enabled() else "OFF")
    with PRO_REVIEW_LOCK:
        models = dict(PRO_REVIEW_MODEL_BY_INST)
    return jsonify({
        "status":           "ok",
        "engine_enabled":   _pro_review_engine_enabled(),
        "gate_enabled":     _pro_review_gate_enabled(),
        "available_models": list(PRO_REVIEW_MODELS),
        "default_model":    _PRO_REVIEW_DEFAULT_MODEL,
        "models":           models,
    }), 200


# ── Potential Trade Idea Review (DISPLAY-ONLY) ─────────────────────────────────
# Grades a trade idea the trader typed in by hand, like a second-opinion analyst.
# REVIEW-ONLY: reuses the read-only engines (full_analysis, find_similar_trades, the
# per-direction Edge cards) and NEVER touches the strict gate / scoring / auto-execute
# path, never contacts a broker, and never mutates TRADING_MODE or any state. The
# dashboard "execute" action only hands the trader a manual order ticket to place
# themselves (Option A) — there is deliberately NO broker transmit and NO /traderspost
# call. Owner-only (Basic Auth + same-origin CSRF via the Express proxy; NOT in
# OPEN_PATHS).
def _review_idea_num(v):
    """Parse a user-supplied price to a finite float, or None."""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    if f != f or f in (float("inf"), float("-inf")):
        return None
    return f


def _review_dir_norm(token):
    """Map any direction-ish token to 'Long' / 'Short' / None (self-contained, so the
    review never depends on another helper's exact casing)."""
    s = str(token or "").strip().lower()
    if "long" in s or "bull" in s or s == "buy":
        return "Long"
    if "short" in s or "bear" in s or s == "sell":
        return "Short"
    return None


def _review_user_risk_cap(mode):
    """Per-trade USD risk ceiling for the USER's reviewed mode (mirrors max_risk_cap()
    but honors the reviewed mode rather than the live TRADING_MODE). Env override wins."""
    env = os.environ.get("MAX_RISK_DOLLARS_PER_TRADE")
    if env is not None:
        try:
            return max(1, int(env))
        except (TypeError, ValueError):
            pass
    try:
        return max(1, int(MODES.get(mode, {}).get("MAX_RISK_DOLLARS", 200)))
    except (TypeError, ValueError):
        return 200


def _review_trade_idea(payload):
    payload = payload or {}

    # ── 1) Validate ────────────────────────────────────────────────────────────
    inst = _instrument_from_text(str(payload.get("symbol") or ""))
    if not inst:
        return {"ok": False, "error": "Unrecognized symbol — use MGC, MNQ, MES or MYM."}
    mode = str(payload.get("mode") or "").strip().upper()
    if mode not in ("SCALP", "SWING"):
        return {"ok": False, "error": "Mode must be SCALP or SWING."}
    direction = str(payload.get("direction") or "").strip().upper()
    if direction not in ("LONG", "SHORT"):
        return {"ok": False, "error": "Direction must be LONG or SHORT."}
    is_long = direction == "LONG"
    dir_cap = "Long" if is_long else "Short"

    entry = _review_idea_num(payload.get("entry"))
    stop  = _review_idea_num(payload.get("stop"))
    t1    = _review_idea_num(payload.get("t1"))
    t2    = _review_idea_num(payload.get("t2"))
    t3    = _review_idea_num(payload.get("t3"))
    if entry is None or stop is None or t1 is None:
        return {"ok": False, "error": "Entry, Stop and Target 1 must be numbers."}

    reason     = str(payload.get("reason") or "").strip()[:600]
    timeframe  = str(payload.get("timeframe") or "").strip()[:60]
    holdtime   = str(payload.get("holdtime") or "").strip()[:80]
    # Chart note / screenshot URL: echoed for display but NEVER logged (may carry a token).
    chart_note = str(payload.get("screenshot") or "").strip()[:500]

    pv = spec_for(inst)["point_value"]

    # ── 2) Risk / reward on the USER's own numbers ──────────────────────────────
    if is_long:
        risk = entry - stop
        rwd1 = t1 - entry
        rwd2 = (t2 - entry) if t2 is not None else None
        rwd3 = (t3 - entry) if t3 is not None else None
    else:
        risk = stop - entry
        rwd1 = entry - t1
        rwd2 = (entry - t2) if t2 is not None else None
        rwd3 = (entry - t3) if t3 is not None else None

    # Optional targets entered on the wrong side of entry are surfaced as a visible
    # warning (never silently dropped) — R:R then honestly falls back to Target 1.
    t2_invalid = t2 is not None and rwd2 is not None and rwd2 <= 0
    t3_invalid = t3 is not None and rwd3 is not None and rwd3 <= 0

    idea = {"symbol": inst, "mode": mode, "direction": direction,
            "entry": entry, "stop": stop, "t1": t1, "t2": t2, "t3": t3,
            "reason": reason, "timeframe": timeframe, "holdtime": holdtime,
            "chart_note": chart_note}

    def _fatal(msg):
        return {"ok": True, "fatal": True, "verdict": "REJECT",
                "confidence_score": 0, "entry_quality_score": 0,
                "idea": idea, "reasons_for": [], "reasons_against": [msg],
                "red_flags": [msg], "final_recommendation": "REJECT — " + msg,
                "sections": {}, "order_ticket": None}

    if risk <= 0:
        return _fatal("Stop is on the wrong side of entry — a %s stop must sit %s entry."
                      % (direction, "below" if is_long else "above"))
    if rwd1 is None or rwd1 <= 0:
        return _fatal("Target 1 is on the wrong side of entry for a %s." % direction)

    # ── 3) Market context (READ-ONLY) ───────────────────────────────────────────
    result = full_analysis(ticker_override=inst)
    cur = result.get("current_price")
    if cur is None:
        cur = result.get("display_price")
    vwap = result.get("vwap_value")
    bias = result.get("bias")
    strict_dir = _review_dir_norm(result.get("strict_direction"))
    dom_dir    = _review_dir_norm(result.get("dominant_direction"))
    bias_dir   = _review_dir_norm(bias)
    bot_dir    = strict_dir or dom_dir or bias_dir
    structure_label = result.get("structure_label")
    structure_class = (result.get("structure_class") or "").lower()
    nearest_supply  = result.get("nearest_supply")
    nearest_demand  = result.get("nearest_demand")
    volblk      = result.get("volatility") or {}
    vol_label   = volblk.get("label") or volblk.get("volatility_label")
    vol_blocked = bool(volblk.get("blocked"))
    session     = result.get("session") or {}
    sess_pref   = bool(session.get("preferred"))
    sess_window = session.get("window")
    dirs = result.get("directions") or {}
    dblk = dirs.get(dir_cap) or {}
    user_edge       = dblk.get("edge_score")
    user_edge_grade = dblk.get("edge_grade")
    conflict_flag   = bool(dblk.get("conflict"))
    bot_pp          = dblk.get("potential_plan") or None

    # ATR for entry-quality geometry (fallback to the trade's own risk distance).
    atrblk = get_volatility(inst) or {}
    atr = atrblk.get("atr_pts")
    atr_approx = False
    if not atr or atr <= 0:
        atr = abs(risk)
        atr_approx = True

    # ── 4) Entry quality ────────────────────────────────────────────────────────
    chasing = False
    dist_from_cur = None
    if cur is not None:
        if is_long:
            dist_from_cur = entry - cur
            chasing = entry > cur + 0.35 * atr
        else:
            dist_from_cur = cur - entry
            chasing = entry < cur - 0.35 * atr

    if is_long:
        opp_zone = nearest_supply if (nearest_supply is not None and nearest_supply > entry) else None
        sup_zone = nearest_demand
    else:
        opp_zone = nearest_demand if (nearest_demand is not None and nearest_demand < entry) else None
        sup_zone = nearest_supply
    dist_zone = None
    zone_blocks_t1 = False
    zone_too_close = False
    if opp_zone is not None:
        dist_zone = (opp_zone - entry) if is_long else (entry - opp_zone)
        zone_blocks_t1 = (opp_zone < t1) if is_long else (opp_zone > t1)
        zone_too_close = dist_zone < 0.30 * atr
    near_support = sup_zone is not None and abs(entry - sup_zone) <= 0.25 * atr
    near_vwap = vwap is not None and abs(entry - vwap) <= 0.25 * atr
    room_ok = (dist_zone is None or dist_zone >= risk) and (rwd1 >= risk)

    if chasing:
        timing = "LATE"
    elif zone_blocks_t1:
        timing = "BLOCKED"
    elif zone_too_close:
        timing = "LATE"
    elif near_support or near_vwap:
        timing = "IDEAL"
    elif cur is not None and ((is_long and cur < entry) or (not is_long and cur > entry)):
        timing = "EARLY"
    else:
        timing = "FAIR"

    eq = 100
    if chasing:
        eq -= 40
    if zone_too_close:
        eq -= 20
    if zone_blocks_t1:
        eq -= 50
    if not room_ok:
        eq -= 15
    if cur is not None and abs(entry - cur) > 1.0 * atr:
        eq -= 10
    if cur is None:
        eq -= 10
    eq = max(0, min(100, eq))

    # ── 5) Scoring (transparent; never fabricated) ───────────────────────────────
    rr1 = (rwd1 / risk) if risk > 0 else 0.0
    rr2 = (rwd2 / risk) if (rwd2 is not None and rwd2 > 0 and risk > 0) else None
    rr3 = (rwd3 / risk) if (rwd3 is not None and rwd3 > 0 and risk > 0) else None
    rr_score_val = rr2 if rr2 is not None else rr1
    if rr_score_val >= 2.0:
        rr_pts = 25
    elif rr_score_val >= 1.5:
        rr_pts = 20
    elif rr_score_val >= 1.0:
        rr_pts = 12
    else:
        rr_pts = 4

    # Market alignment (30)
    if bot_dir is None:
        dir_pts = 6
    elif bot_dir == dir_cap:
        dir_pts = 12
    else:
        dir_pts = 0
    if vwap is None or cur is None:
        vwap_pts = 3
    elif (is_long and cur > vwap) or (not is_long and cur < vwap):
        vwap_pts = 6
    else:
        vwap_pts = 0
    if "bull" in structure_class and is_long:
        struct_pts = 6
    elif "bear" in structure_class and not is_long:
        struct_pts = 6
    elif structure_class == "" or "neutral" in structure_class or "range" in structure_class:
        struct_pts = 3
    else:
        struct_pts = 0
    _vl = (vol_label or "").lower()
    if vol_blocked or "extreme" in _vl:
        vol_pts = 0
    elif "elevated" in _vl or "high" in _vl:
        vol_pts = 2
    elif "normal" in _vl or "calm" in _vl or "low" in _vl:
        vol_pts = 3
    else:
        vol_pts = 1.5
    sess_pts = 3 if sess_pref else 1.5
    market_pts = dir_pts + vwap_pts + struct_pts + vol_pts + sess_pts

    entry_pts = round(eq / 100.0 * 25)

    # Memory (10) — copy the result and force the user's direction. The mode dimension
    # inside find_similar_trades still reflects the live engine mode; matched_on reports
    # exactly which dimensions actually matched, so nothing is over-claimed.
    _copy = dict(result)
    _copy["strict_direction"] = dir_cap
    _se = dict(_copy.get("strategy_engine") or {})
    _se["direction"] = dir_cap
    _copy["strategy_engine"] = _se
    try:
        sim = find_similar_trades(_copy, inst) or {}
    except Exception:
        sim = {}
    mem_wr = sim.get("weighted_win_rate")
    if not sim.get("ready") or mem_wr is None:
        mem_pts = 5
    elif mem_wr >= 0.6:
        mem_pts = 10
    elif mem_wr >= 0.5:
        mem_pts = 8
    elif mem_wr >= 0.4:
        mem_pts = 6
    elif mem_wr >= 0.3:
        mem_pts = 4
    else:
        mem_pts = 2

    # Conviction (10)
    if conflict_flag:
        conv_pts = 0
    elif user_edge is not None:
        try:
            conv_pts = round(min(1.0, max(0.0, float(user_edge) / float(EDGE_SCORE_MAX))) * 10)
        except (TypeError, ValueError, ZeroDivisionError):
            conv_pts = 5
    else:
        conv_pts = 5

    total = int(round(max(0, min(100, rr_pts + market_pts + entry_pts + mem_pts + conv_pts))))

    # ── 6) Position size + red flags + verdict ──────────────────────────────────
    risk_per_contract = risk * pv
    cap = _review_user_risk_cap(mode)
    if risk_per_contract > 0:
        max_safe = int(cap // risk_per_contract)
    else:
        max_safe = 0
    suggested_size = 1 if max_safe >= 1 else 0

    severe_conflict = strict_dir is not None and strict_dir != dir_cap

    red_flags = []
    if max_safe < 1:
        red_flags.append("1 contract risks $%.0f — over the $%d per-trade cap." % (risk_per_contract, cap))
    if rr_score_val < 1.0:
        red_flags.append("Reward:risk is below 1:1 (%.2f)." % rr_score_val)
    if zone_blocks_t1:
        red_flags.append("An opposing zone sits before Target 1.")
    if severe_conflict:
        red_flags.append("The bot's gate currently favors the opposite side (%s)." % strict_dir)

    if max_safe < 1 or rr_score_val < 1.0 or zone_blocks_t1 or severe_conflict or total < 50:
        verdict = "REJECT"
    elif total >= 75 and eq >= 70 and rr_score_val >= 1.5 and max_safe >= 1 and not red_flags:
        verdict = "APPROVE"
    else:
        verdict = "MODIFY"

    # ── 7) Reasons ───────────────────────────────────────────────────────────────
    reasons_for, reasons_against = [], []
    _tgt = "T2" if rr2 is not None else "T1"
    if rr_score_val >= 1.5:
        reasons_for.append("Strong reward:risk of %.2f:1 to %s." % (rr_score_val, _tgt))
    if dir_pts == 12:
        reasons_for.append("Aligned with the bot's %s read." % dir_cap)
    if vwap_pts == 6:
        reasons_for.append("Price is on the correct side of VWAP.")
    if struct_pts == 6 and structure_label:
        reasons_for.append("Market structure agrees (%s)." % structure_label)
    if timing == "IDEAL":
        reasons_for.append("Entry is at a quality location (near support/VWAP, not chasing).")
    elif timing == "EARLY":
        reasons_for.append("Entering before the move — good location if your trigger confirms.")
    if sim.get("ready") and mem_wr is not None and mem_wr >= 0.5:
        reasons_for.append("Similar past trades won %d%% (%d matched)." % (round(mem_wr * 100), sim.get("matched") or 0))
    if conv_pts >= 7 and user_edge is not None:
        reasons_for.append("Bot conviction for this side is high (Edge %s)." % user_edge)

    if severe_conflict:
        reasons_against.append("Counter to the bot's current gate direction (%s)." % strict_dir)
    elif dir_pts == 0 and bot_dir is not None:
        reasons_against.append("Counter to the bot's %s lean." % bot_dir)
    if chasing and dist_from_cur is not None:
        reasons_against.append("Chasing — entry is %.1f pts beyond current price (> 0.35 ATR)." % abs(dist_from_cur))
    if zone_too_close and dist_zone is not None:
        reasons_against.append("Opposing zone only %.1f pts away (< 0.30 ATR)." % dist_zone)
    if zone_blocks_t1:
        reasons_against.append("Opposing zone sits before Target 1 — T1 may be hard to reach.")
    if not room_ok:
        reasons_against.append("Limited room — under 1R to the opposing zone or to Target 1.")
    if rr_score_val < 1.0:
        reasons_against.append("Reward:risk is below 1:1 (%.2f)." % rr_score_val)
    if max_safe < 1:
        reasons_against.append("1 contract risks $%.0f, above the $%d cap (size 0)." % (risk_per_contract, cap))
    if vol_blocked or "extreme" in _vl:
        reasons_against.append("Volatility is %s." % (vol_label or "extreme"))
    if sim.get("ready") and mem_wr is not None and mem_wr < 0.4:
        reasons_against.append("Similar past trades won only %d%%." % round(mem_wr * 100))
    if t2_invalid:
        reasons_against.append("Target 2 is on the wrong side of entry — ignored (R:R uses Target 1).")
    if t3_invalid:
        reasons_against.append("Target 3 is on the wrong side of entry — ignored.")

    # ── 8) Final recommendation ──────────────────────────────────────────────────
    if verdict == "APPROVE":
        final_rec = ("APPROVE — a well-aligned %s %s idea (score %d/100). 1 contract risks "
                     "$%.0f; suggested size %d (max safe %d)." %
                     (mode, dir_cap, total, risk_per_contract, suggested_size, max_safe))
    elif verdict == "REJECT":
        primary = red_flags[0] if red_flags else ("Overall score %d/100 is below the 50 threshold." % total)
        final_rec = "REJECT — " + primary
    else:
        fix = reasons_against[0] if reasons_against else "tighten the setup before entering."
        final_rec = "MODIFY — workable, but: " + fix

    # ── 9) Thesis (reuse the analyst engine; fail-open) ──────────────────────────
    analyst = result.get("analyst") or {}
    bull_case = list(analyst.get("bull_case") or [])[:6]
    bear_case = list(analyst.get("bear_case") or [])[:6]
    invalidation = analyst.get("invalidation") or "—"
    what_next = list(analyst.get("what_next") or [])[:5] if isinstance(analyst.get("what_next"), list) else []
    if not what_next:
        _trig = reason or timeframe or "your stated trigger"
        what_next = ["Wait for %s to confirm before entering." % _trig]
    story = analyst.get("story") or result.get("opportunity_reason") or "—"

    # ── 10) Sections ─────────────────────────────────────────────────────────────
    sections = {
        "risk_reward": {
            "valid": True,
            "risk_points": round(risk, 4),
            "reward1_points": round(rwd1, 4),
            "reward2_points": round(rwd2, 4) if rwd2 is not None else None,
            "reward3_points": round(rwd3, 4) if rwd3 is not None else None,
            "rr1": round(rr1, 2),
            "rr2": round(rr2, 2) if rr2 is not None else None,
            "rr3": round(rr3, 2) if rr3 is not None else None,
            "point_value": pv,
            "risk_per_contract": round(risk_per_contract, 2),
            "reward1_dollars": round(rwd1 * pv, 2),
            "reward2_dollars": round(rwd2 * pv, 2) if rwd2 is not None else None,
            "risk_cap": cap,
            "max_safe_size": max_safe,
            "suggested_size": suggested_size,
        },
        "market_alignment": {
            "user_direction": dir_cap,
            "bot_direction": bot_dir,
            "agreement": ("Aligned" if (bot_dir and bot_dir == dir_cap)
                          else ("Counter" if bot_dir else "Neutral")),
            "strict_direction": strict_dir,
            "bias": bias,
            "vwap_value": vwap,
            "vwap_side": (None if (vwap is None or cur is None) else ("above" if cur > vwap else "below")),
            "structure_label": structure_label,
            "nearest_supply": nearest_supply,
            "nearest_demand": nearest_demand,
            "volatility_label": vol_label,
            "volatility_blocked": vol_blocked,
            "session_window": sess_window,
            "session_preferred": sess_pref,
            "edge_score": user_edge,
            "edge_grade": user_edge_grade,
            "current_price": cur,
            "points": {"direction": dir_pts, "vwap": vwap_pts, "structure": struct_pts,
                       "volatility": vol_pts, "session": sess_pts, "total": market_pts},
        },
        "entry_quality": {
            "score": eq,
            "timing": timing,
            "chasing": chasing,
            "atr_points": round(atr, 2),
            "atr_approx": atr_approx,
            "distance_to_current": round(dist_from_cur, 2) if dist_from_cur is not None else None,
            "opposing_zone": opp_zone,
            "distance_to_zone": round(dist_zone, 2) if dist_zone is not None else None,
            "zone_blocks_t1": zone_blocks_t1,
            "zone_too_close": zone_too_close,
            "room_ok": room_ok,
            "near_support": near_support,
            "near_vwap": near_vwap,
        },
        "thesis": {
            "bull_case": bull_case,
            "bear_case": bear_case,
            "invalidation": invalidation,
            "what_next": what_next,
            "story": story,
        },
        "memory": {
            "ready": bool(sim.get("ready")),
            "matched": sim.get("matched"),
            "matched_on": sim.get("matched_on"),
            "weighted_win_rate": mem_wr,
            "weighted_avg_r": sim.get("weighted_avg_r"),
            "top_failure_label": sim.get("top_failure_label"),
            "best_exit_label": sim.get("best_exit_label"),
            "note": sim.get("reason"),
        },
        "score_breakdown": {
            "risk_reward": rr_pts, "market_alignment": market_pts,
            "entry_quality": entry_pts, "memory": mem_pts, "conviction": conv_pts,
            "total": total,
        },
    }

    # Bot's OWN suggested plan for this side (display-only comparison; reuses the
    # existing per-direction potential_plan — never recomputed here).
    if bot_pp:
        sections["bot_plan"] = {
            "available": True,
            "best_entry_zone": bot_pp.get("entry_zone"),
            "suggested_stop": bot_pp.get("stop_loss"),
            "suggested_target1": bot_pp.get("target1"),
            "suggested_target2": bot_pp.get("target2"),
            "rr": bot_pp.get("rr"),
        }
    else:
        sections["bot_plan"] = {"available": False,
                                "note": "No forming plan for this side right now."}

    # Manual order ticket (Option A): the trader places this themselves. Nothing is
    # ever sent to a broker and the /traderspost gateway is never called.
    order_ticket = {
        "symbol": inst, "direction": direction,
        "entry": entry, "stop": stop, "t1": t1, "t2": t2, "t3": t3,
        "contracts": suggested_size,
        "note": "Manual order — place this yourself. Nothing was sent to a broker.",
    }

    # Audit log WITHOUT any free text or the chart note / screenshot URL.
    logger.info("Trade idea review: %s %s %s entry=%s -> %s (score %d, entryQ %d)",
                inst, mode, direction, entry, verdict, total, eq)

    return {
        "ok": True,
        "verdict": verdict,
        "confidence_score": total,
        "entry_quality_score": eq,
        "reasons_for": reasons_for,
        "reasons_against": reasons_against,
        "red_flags": red_flags,
        "final_recommendation": final_rec,
        "idea": idea,
        "sections": sections,
        "order_ticket": order_ticket,
    }


@app.route("/dpv2-scorecard", methods=["GET"])
def dpv2_scorecard_route():
    """Decision Pipeline V2 agreement scorecard (DISPLAY-ONLY, shadow mode).
    Owner-only (Basic Auth + same-origin CSRF via the Express proxy;
    deliberately NOT in OPEN_PATHS). Returns the in-memory agreement history
    aggregated into a read-only scorecard. Never feeds the gate, gateway, or
    any money-path component."""
    try:
        card = _dpv2_compute_scorecard()
        history = list(_DPV2_AGREEMENT_HISTORY)[:50]   # last 50 evaluations
        shadows = dict(_DPV2_SHADOW_TRADES)             # current shadow trades
        return jsonify({
            "scorecard": card,
            "recent_evaluations": history,
            "shadow_trades": shadows,
            "total_in_history": len(list(_DPV2_AGREEMENT_HISTORY)),
            "shadow_mode_note": "SHADOW MODE — NO LIVE AUTHORITY",
        }), 200
    except Exception as _e:
        logger.warning("[DPv2 scorecard] error: %s", _e)
        return jsonify({"status": "error", "reason": str(_e)}), 500


@app.route("/review-idea", methods=["POST"])
def review_idea():
    """DISPLAY-ONLY analyst review of a trader-entered trade idea. REVIEW-ONLY: reuses
    the read-only engines, NEVER touches the gate / scoring / auto-execute path, never
    contacts a broker, and never mutates state. Owner-only (Basic Auth + same-origin
    CSRF via the Express proxy; deliberately NOT in OPEN_PATHS)."""
    data = request.get_json(silent=True) or {}
    try:
        out = _review_trade_idea(data)
    except Exception as e:
        logger.exception("review-idea failed")
        out = {"ok": False, "error": "Review failed: %s" % e}
    return jsonify(out), 200


@app.route("/failure-analysis", methods=["GET"])
def failure_analysis_route():
    """Owner-only (dashboard auth via Express /api; NOT in OPEN_PATHS). Returns the
    last N TFA records + failure-mode distribution summary. DISPLAY-ONLY — never feeds
    the gate, gateway, or any money-path component. Requires the
    trade_failure_analysis table (created via DB tool / Publish schema-diff)."""
    if not TFA_DB_READY:
        return jsonify({"status": "unavailable",
                        "reason": "trade_failure_analysis table not ready"}), 503
    try:
        limit = min(int(request.args.get("limit", 50)), 200)
        conn  = _learning_conn()
        if conn is None:
            return jsonify({"status": "error", "reason": "DB unavailable"}), 503
        cur = conn.cursor()
        cur.execute(
            """SELECT ready_id, instrument, direction, mode, edge_score,
                      entry_quality_score, strategy, bias, structure_ok, zone_ok,
                      vwap_ok, vol_regime, session, price_at_ready, ready_at,
                      triggered, trigger_source, trigger_lag_sec, entry_price,
                      exit_price, mfe_r, mae_r, r_multiple, duration_min, outcome,
                      failure_mode, failure_detail, completed_at
               FROM trade_failure_analysis
               ORDER BY ready_at DESC LIMIT %s""",
            (limit,),
        )
        cols    = [d[0] for d in cur.description]
        records = []
        for row in cur.fetchall():
            rec = dict(zip(cols, row))
            for k, v in list(rec.items()):
                if hasattr(v, "isoformat"):
                    rec[k] = v.isoformat()
            records.append(rec)
        cur.execute(
            """SELECT failure_mode, COUNT(*) AS cnt,
                      ROUND(AVG(r_multiple)::numeric, 2) AS avg_r,
                      ROUND(AVG(mfe_r)::numeric, 2)     AS avg_mfe,
                      SUM(CASE WHEN outcome='Win' THEN 1 ELSE 0 END) AS wins
               FROM trade_failure_analysis
               WHERE completed_at IS NOT NULL
               GROUP BY failure_mode ORDER BY cnt DESC""")
        summary = [
            {"failure_mode": r[0], "count": int(r[1]),
             "avg_r":   float(r[2] or 0),
             "avg_mfe": float(r[3] or 0),
             "wins":    int(r[4] or 0)}
            for r in cur.fetchall()
        ]
        cur.close()
        conn.close()
        total_completed = sum(s["count"] for s in summary)
        total_wins      = sum(s["wins"]  for s in summary)
        return jsonify({
            "status":  "ok",
            "records": records,
            "summary": summary,
            "totals":  {
                "completed":    total_completed,
                "wins":         total_wins,
                "win_rate_pct": round(100 * total_wins / total_completed, 1)
                                if total_completed else None,
            },
        })
    except Exception as exc:
        return jsonify({"status": "error", "reason": str(exc)}), 500


# ── AI Assistant (DISPLAY-ONLY chat; read-only Q&A over the live snapshot) ──────
#    Reuses full_analysis (the same read the dashboard /status poll uses) to ground
#    its answers. It NEVER touches the gate / scoring / auto-execute path, never
#    contacts a broker, and never mutates state. Owner-only (Basic Auth + same-origin
#    CSRF via the Express proxy; deliberately NOT in OPEN_PATHS). Powered by Replit AI
#    Integrations (OpenAI) — keys auto-provisioned, no API key handling here.
ASSISTANT_MODEL          = "gpt-5.4"
ASSISTANT_MAX_TOKENS     = 600
ASSISTANT_HISTORY_TURNS  = 10  # max conversation pairs forwarded per request

# In-memory session registry — lightweight metadata only; no message content stored
# server-side (history lives in the browser). Display-only; never touches money path.
_MB_CONV_SESSIONS      = {}        # sid -> {started_at, last_at, turns, instrument}
_MB_CONV_SESSIONS_LOCK = threading.Lock()
_MB_CONV_SESSIONS_MAX  = 200


def _assistant_live_context(ticker_override=None):
    """Build a compact, READ-ONLY snapshot of the current analysis for the assistant
    to ground its answers. Pulls every field defensively so a missing key can never
    break the chat. NEVER mutates state or touches the money path."""
    def _one(tk):
        a = full_analysis(ticker_override=tk)
        return {
            "instrument":         a.get("active_ticker"),
            "trading_mode":       TRADING_MODE,
            "verdict":            a.get("verdict"),
            "recommendation":     a.get("recommendation"),
            "why":                a.get("why"),
            "strict_label":       a.get("strict_label"),
            "strict_score":       a.get("strict_score"),
            "strict_direction":   a.get("strict_direction"),
            "strict_reason":      a.get("strict_reason"),
            "strict_missing":     a.get("strict_missing"),
            "gate_debug":         a.get("gate_debug"),
            "learning_score_influence": a.get("learning_score_influence"),
            "edge_score":         a.get("edge_score"),
            "edge_grade":         a.get("edge_grade"),
            "edge_breakdown":     a.get("edge_breakdown"),
            "long_score":         a.get("long_score"),
            "short_score":        a.get("short_score"),
            "conflict_gap":       a.get("conflict_gap"),
            "dominant_direction": a.get("dominant_direction"),
            "bias":               a.get("bias"),
            "strength":           a.get("strength"),
            "confidence":         a.get("confidence"),
            "current_price":      a.get("current_price"),
            "vwap_value":         a.get("vwap_value"),
            "vwap_status":        a.get("vwap_status"),
            "nearest_supply":     a.get("nearest_supply"),
            "nearest_demand":     a.get("nearest_demand"),
            "market_structure":   a.get("structure_label"),
            "structure_detail":   a.get("structure_detail"),
            "risk_zone":          a.get("risk_label"),
            "risk_detail":        a.get("risk_detail"),
            "overextended":       a.get("overextended"),
            "volatility":         a.get("volatility"),
            "current_atr":        a.get("current_atr"),
            "trade_opportunity":  a.get("trade_opportunity"),
            "opportunity_reason": a.get("opportunity_reason"),
            "setup_stage":        a.get("setup_stage"),
            "stage_next_step":    a.get("stage_next_step"),
            "stage_entry_rule":   a.get("stage_entry_rule"),
            "stage_invalidation": a.get("stage_invalidation"),
            "trade_plan":         a.get("trade_plan"),
            "alert_diagnostics":  a.get("alert_diagnostics"),
            "session":            a.get("session"),
            "market_open":        a.get("market_open"),
            "market_status":      a.get("market_status"),
            "market_reason":      a.get("market_reason"),
            "alert_counts":       a.get("counts"),
            "main_brain":         a.get("main_brain"),
            "analyst_memory":     (a.get("analyst") or {}).get("memory_review"),
        }

    primary = _one(ticker_override)
    sel_inst = primary.get("instrument")
    overview = [{
        "instrument": sel_inst,
        "verdict":    primary.get("verdict"),
        "edge_score": primary.get("edge_score"),
        "edge_grade": primary.get("edge_grade"),
        "bias":       primary.get("bias"),
    }]
    try:
        for tk in enabled_instruments():
            if tk == sel_inst:
                continue
            try:
                b = full_analysis(ticker_override=tk)
                overview.append({
                    "instrument": b.get("active_ticker") or tk,
                    "verdict":    b.get("verdict"),
                    "edge_score": b.get("edge_score"),
                    "edge_grade": b.get("edge_grade"),
                    "bias":       b.get("bias"),
                })
            except Exception:
                continue
    except Exception:
        pass
    # Open positions the owner is actively managing — READ-ONLY mirror so the
    # assistant can answer "manage my trade", "where's my stop", "take partials".
    # compute_manual_trade_management MUTATES the dict it is handed, so we pass COPIES
    # only. Manual (hand-entered) + bot (auto-managed) rows, exactly like the monitor
    # box. On-demand only (not the 3s poll); fully fail-open.
    open_trades = []
    _trade_keys = ("symbol", "direction", "mode", "contracts", "entry_price",
                   "stop_loss", "current_price", "current_r", "unrealized_pnl",
                   "thesis_status", "recommendation", "recommendation_reason",
                   "entry_assessment", "warnings", "what_improves",
                   "what_invalidates", "origin")
    try:
        with MANUAL_TRADES_LOCK:
            _mts = [dict(t) for t in MANUAL_TRADES.values()]
        _acache = {}
        for _t in _mts:
            _s = _t.get("symbol")
            if _s not in _acache:
                try:
                    _acache[_s] = full_analysis(ticker_override=_s)
                except Exception:
                    _acache[_s] = None
            try:
                _row = compute_manual_trade_management(_t, analysis=_acache.get(_s))
                _row["origin"] = "manual"
                open_trades.append({k: _row.get(k) for k in _trade_keys})
            except Exception:
                continue
        try:
            for _row in _bot_active_trade_monitor_items(_acache):
                open_trades.append({k: _row.get(k) for k in _trade_keys})
        except Exception:
            pass
    except Exception:
        open_trades = []

    # Per-asset risk rules / daily limits — READ-ONLY, for "risk check" questions.
    risk_rules = {}
    try:
        if sel_inst:
            risk_rules[sel_inst] = _safety_snapshot(sel_inst)
    except Exception:
        pass
    try:
        for tk in enabled_instruments():
            if tk == sel_inst or tk in risk_rules:
                continue
            try:
                risk_rules[tk] = _safety_snapshot(tk)
            except Exception:
                continue
    except Exception:
        pass

    # ── Data staleness: age of the last meaningful scored alert ──────────────
    _now = datetime.now(timezone.utc)
    _alt = LAST_ALERT_AT    # datetime of last scored signal, or None
    _wh  = LAST_WEBHOOK_AT  # datetime of any inbound webhook, or None
    if _alt:
        _age = (_now - _alt).total_seconds()
        _m, _s = divmod(int(_age), 60)
        _age_lbl = ("%dm %ds" % (_m, _s)) if _m else ("%ds" % _s)
        data_staleness = {
            "last_alert_at":        _alt.isoformat(),
            "age_secs":             int(_age),
            "age_label":            _age_lbl,
            "is_stale":             _age > 60,
            "stale_threshold_secs": 60,
        }
    elif _wh:
        _age = (_now - _wh).total_seconds()
        _m, _s = divmod(int(_age), 60)
        _age_lbl = ("%dm %ds" % (_m, _s)) if _m else ("%ds" % _s)
        data_staleness = {
            "last_webhook_at":      _wh.isoformat(),
            "age_secs":             int(_age),
            "age_label":            _age_lbl,
            "is_stale":             True,
            "note":                 "No scored alerts yet; last raw webhook was %s ago." % _age_lbl,
            "stale_threshold_secs": 60,
        }
    else:
        data_staleness = {
            "is_stale": True,
            "age_secs": None,
            "note":     "No webhooks received yet — bot just started or market is closed.",
        }

    # ── Prop firm protection status ──────────────────────────────────────────
    prop_status = {}
    try:
        prop_status = prop_firm_status_view()
    except Exception:
        prop_status = {"enabled": False, "error": "unavailable"}

    # ── AutoResearch top findings (read-only display-only cache) ─────────────
    auto_research_top = []
    try:
        with SCALP_RESEARCH_CACHE_LOCK:
            _src = SCALP_RESEARCH_CACHE
        if isinstance(_src, dict):
            _best = _src.get("best") or _src.get("tested") or []
            for _row in list(_best)[:3]:
                auto_research_top.append({
                    "strategy":    _row.get("strategy") or _row.get("name"),
                    "win_rate":    _row.get("win_rate"),
                    "avg_r":       _row.get("avg_r"),
                    "trades":      _row.get("trades") or _row.get("total_trades"),
                    "live_status": _row.get("live_status"),
                    "rec":         _row.get("recommendation") or _row.get("rec"),
                })
    except Exception:
        pass

    # ── Recent scored signals (last 5, newest first) ─────────────────────────
    recent_alerts = []
    try:
        for _r in reversed(list(ALERT_HISTORY)[-5:]):
            recent_alerts.append({
                "type":       _r.get("alert_type"),
                "instrument": _r.get("instrument"),
                "price":      _r.get("price"),
                "ts":         _r.get("timestamp"),
            })
    except Exception:
        pass

    return {
        "selected":          primary,
        "all_instruments":   overview,
        "open_trades":       open_trades,
        "risk_rules":        risk_rules,
        "data_staleness":    data_staleness,
        "prop_status":       prop_status,
        "auto_research_top": auto_research_top,
        "recent_alerts":     recent_alerts,
    }


def _assistant_follow_ups(ctx, verdict_key=""):
    """Return up to 3 context-appropriate follow-up questions. Deterministic —
    no additional AI call. Display-only; never touches the gate or money path."""
    has_pos = bool(ctx.get("open_trades"))
    vk = (verdict_key or "").upper()
    if "READY" in vk or "EARLY" in vk:
        return [
            "What needs to happen for this to stay valid?",
            "What would invalidate this setup right now?",
            "Walk me through the entry and stop.",
        ]
    if has_pos:
        return [
            "How is the current position tracking?",
            "When should I consider taking partials?",
            "What would tell you to exit early?",
        ]
    if any(x in vk for x in ("WAIT", "WATCHING", "BUILDING", "FORMING")):
        return [
            "What needs to happen next?",
            "What would move this to a trade-ready setup?",
            "What invalidates the current thesis?",
        ]
    return [
        "Summarize the current market read simply.",
        "What are you watching most closely right now?",
        "Is there anything interesting developing?",
    ]


def _assistant_answer(data):
    """Owner-only, DISPLAY-ONLY assistant. Answers questions about the live setup and
    general trading using the read-only snapshot. NEVER touches the gate, scoring,
    auto-execute, or any broker path; never mutates state."""
    base = (os.environ.get("AI_INTEGRATIONS_OPENAI_BASE_URL") or "").strip().rstrip("/")
    key  = (os.environ.get("AI_INTEGRATIONS_OPENAI_API_KEY") or "").strip()
    if not base or not key:
        return {"ok": False, "error": "The AI assistant is not configured on this server yet."}

    question = data.get("question")
    if not isinstance(question, str):
        question = "" if question is None else str(question)
    question = question.strip()
    if not question:
        return {"ok": False, "error": "Ask a question first."}
    if len(question) > 2000:
        question = question[:2000]

    # Detect "explain simply" / beginner mode requests
    _q_lower = question.lower()
    _explain_simple = any(phrase in _q_lower for phrase in (
        "explain simply", "explain like i", "what does that mean",
        "for a beginner", "simpler", "simple terms", "in plain english",
        "i don't understand", "i dont understand", "dumb it down",
    ))

    raw_tk = data.get("ticker")
    tk = _instrument_from_text(raw_tk.upper()) if isinstance(raw_tk, str) else None

    # ── Session tracking — lightweight metadata only; no content stored server-side ──
    sid = data.get("session_id")
    if not isinstance(sid, str) or not sid.strip():
        sid = None
    else:
        sid = sid.strip()[:64]
    if sid:
        _ts = datetime.now(timezone.utc).isoformat()
        with _MB_CONV_SESSIONS_LOCK:
            if sid not in _MB_CONV_SESSIONS:
                logger.info("assistant session created sid=...%s inst=%s", sid[-8:], tk or "?")
                _MB_CONV_SESSIONS[sid] = {
                    "started_at": _ts,
                    "last_at":    _ts,
                    "turns":      0,
                    "instrument": tk or "unknown",
                }
            _sess = _MB_CONV_SESSIONS[sid]
            _sess["last_at"] = _ts
            _sess["turns"]   = _sess.get("turns", 0) + 1
            if tk:
                _sess["instrument"] = tk
            # Prune oldest session when over cap
            if len(_MB_CONV_SESSIONS) > _MB_CONV_SESSIONS_MAX:
                _oldest = sorted(
                    _MB_CONV_SESSIONS.items(),
                    key=lambda kv: kv[1].get("last_at", ""),
                )[0][0]
                del _MB_CONV_SESSIONS[_oldest]

    try:
        ctx = _assistant_live_context(tk)
    except Exception as exc:
        logger.warning("assistant context build failed (non-fatal): %s", exc)
        ctx = {"selected": {}, "all_instruments": []}

    logger.info("assistant message received sid=...%s inst=%s q_len=%d",
                (sid or "anon")[-8:], tk or "?", len(question))

    # ── Conversation summary injected by the client (compact digest of older turns) ──
    raw_summary = data.get("conversation_summary")
    conv_summary = ""
    if isinstance(raw_summary, str):
        conv_summary = raw_summary.strip()[:800]

    # Sanitize optional multi-turn history from the client: only known roles + string
    # content, length-capped, most-recent turns. Defensive against a malformed body.
    history_msgs = []
    raw_hist = data.get("history")
    if isinstance(raw_hist, list):
        for item in raw_hist[-ASSISTANT_HISTORY_TURNS:]:
            if not isinstance(item, dict):
                continue
            role = item.get("role")
            content = item.get("content")
            if role not in ("user", "assistant") or not isinstance(content, str):
                continue
            content = content.strip()
            if not content:
                continue
            history_msgs.append({"role": role, "content": content[:1500]})

    _stale = ctx.get("data_staleness") or {}
    _age_secs = _stale.get("age_secs")
    _age_lbl  = _stale.get("age_label") or (str(_age_secs) + "s" if _age_secs else "unknown")
    _is_stale = bool(_stale.get("is_stale"))

    system_primer = (
        "You are the Main Brain — the AI trading partner embedded in this futures cockpit. "
        "You speak DIRECTLY and BRIEFLY, like a sharp trading partner, NOT like a report generator.\n\n"
        "RESPONSE LENGTH RULE — this is the most important rule:\n"
        "Answer in 1-3 SHORT sentences. Maximum. Never write a paragraph. Never use bullet points. "
        "Never use headers or labels like 'Answer:' or 'Why:'. Just talk.\n\n"
        "VOICE RULES:\n"
        "- Speak like a confident, experienced trader — direct, no fluff, slight personality.\n"
        "- Translate data into plain English. Do NOT quote JSON field names. "
        "Say 'volatility is 4.6x normal' not 'atr_ratio is 4.6'. "
        "Say 'structure is confirmed bullish' not 'gate_debug says BOS PASS'.\n"
        "- If the question is casual or personal (jokes, feelings, banter), just banter back naturally.\n\n"
        "CONVERSATION CONTINUITY:\n"
        "- This is a continuous session. Remember everything said earlier in this conversation.\n"
        "- If the user says 'that', 'it', 'this setup', 'the same thing', resolve the reference "
        "from the previous exchange — never ask the user to repeat context.\n"
        "- If you genuinely lack data, say exactly: "
        "'I do not currently have enough production data to answer that reliably.' "
        "Never guess a price, entry, stop, or verdict.\n\n"
        "DATA RULES (only when the question is about the live market):\n"
        "- Use the live snapshot to give the specific real answer — price, verdict, what is missing.\n"
        "- If data is stale (age > 60s), say 'My last read was [X] ago' and answer on that.\n"
        "- If no position is open, say so simply. If one is open, give the key numbers concisely.\n"
        "- Read-only: never imply you placed, modified, or closed a trade."
    )
    if _explain_simple:
        system_primer += (
            "\n\nEXPLAIN SIMPLY MODE: The user asked for a simpler explanation. "
            "Use plain everyday language. No jargon or field names. "
            "Explain as if to a new trader who just opened their first chart. "
            "Stay accurate — just cut the vocabulary. 2-3 plain sentences max."
        )

    _inst_label = (ctx.get("selected") or {}).get("instrument") or "unknown"
    _mode_label = TRADING_MODE
    _fresh_line  = (
        "DATA FRESHNESS: last scored signal was %s ago (age_secs=%d, is_stale=%s)."
        % (_age_lbl, _age_secs or 0, _is_stale)
    ) if _age_secs is not None else (
        "DATA FRESHNESS: %s" % (_stale.get("note") or "no data yet")
    )
    snapshot_msg = (
        "LIVE DASHBOARD SNAPSHOT — read-only, injected at question time.\n"
        "Instrument: %s | Mode: %s\n"
        "%s\n\n"
        "Live snapshot (use this to ground your answer in real numbers):\n```json\n%s\n```"
        % (
            _inst_label,
            _mode_label,
            _fresh_line,
            json.dumps(ctx, default=str)[:14000],
        )
    )

    messages = [{"role": "system", "content": system_primer}]
    # Inject conversation summary before recent turns for cross-turn continuity
    if conv_summary:
        messages.append({
            "role": "system",
            "content": "CONVERSATION SUMMARY (older turns, for continuity):\n" + conv_summary,
        })
    messages.extend(history_msgs)
    messages.append({"role": "system", "content": snapshot_msg})
    messages.append({"role": "user", "content": question})

    payload = {
        "model": ASSISTANT_MODEL,
        "messages": messages,
        "max_completion_tokens": ASSISTANT_MAX_TOKENS,
    }

    logger.info("assistant context attached sid=...%s history_turns=%d has_summary=%s",
                (sid or "anon")[-8:], len(history_msgs), bool(conv_summary))

    try:
        resp = requests.post(
            base + "/chat/completions",
            headers={"Authorization": "Bearer " + key, "Content-Type": "application/json"},
            json=payload,
            timeout=60,
        )
    except Exception as exc:
        logger.warning("assistant upstream request failed: %s", exc)
        return {"ok": False, "error": "Could not reach the AI service. Try again in a moment."}

    if resp.status_code != 200:
        logger.warning("assistant upstream non-200: %s %s", resp.status_code, (resp.text or "")[:300])
        return {"ok": False, "error": "AI request failed (HTTP %s)." % resp.status_code}

    try:
        j = resp.json()
        answer = ((j.get("choices") or [{}])[0].get("message") or {}).get("content") or ""
        answer = answer.strip()
    except Exception as exc:
        logger.warning("assistant parse failed: %s", exc)
        return {"ok": False, "error": "Could not parse the AI response."}

    if not answer:
        return {"ok": False, "error": "The AI returned an empty answer. Try rephrasing."}

    _verdict_key = (ctx.get("selected") or {}).get("verdict") or ""
    follow_ups   = _assistant_follow_ups(ctx, _verdict_key)

    logger.info("assistant response generated sid=...%s ans_len=%d follow_ups=%d",
                (sid or "anon")[-8:], len(answer), len(follow_ups))

    return {
        "ok":         True,
        "answer":     answer,
        "model":      ASSISTANT_MODEL,
        "instrument": _inst_label,
        "session_id": sid,
        "follow_ups": follow_ups,
    }


@app.route("/assistant", methods=["POST"])
def assistant():
    """DISPLAY-ONLY AI assistant chat. Answers questions about the live setup and
    general trading using the read-only full_analysis snapshot. REVIEW-ONLY: it NEVER
    touches the gate / scoring / auto-execute path, never contacts a broker, and never
    mutates state. Owner-only (Basic Auth + same-origin CSRF via the Express proxy;
    deliberately NOT in OPEN_PATHS)."""
    data = request.get_json(silent=True) or {}
    try:
        out = _assistant_answer(data)
    except Exception as e:
        logger.exception("assistant failed")
        out = {"ok": False, "error": "Assistant error: %s" % e}
    return jsonify(out), 200


@app.route("/entry-quality", methods=["GET", "POST"])
def entry_quality_controls():
    """Read or set the Entry Quality money-path VETO toggle.

    The Entry Quality Engine scores WHETHER THIS IS A GOOD LOCATION to enter
    (separate from the strict IF-valid gate). The VETO is OFF by default and, when
    armed, only DEMOTES an actionable verdict to WAIT when the entry location is poor
    (score < ENTRY_QUALITY_MIN_SCORE) AND confidence is not extremely high (Edge <
    ENTRY_QUALITY_OVERRIDE_EDGE). It can never promote / force a trade. The runtime
    toggle wins over the env seed and RESETS on restart (fail-safe toward NOT
    interfering). NEVER affects manual ENTER trades, the base strict gate, or
    scoring. Owner-only (Basic Auth + CSRF via the Express proxy; deliberately NOT
    in OPEN_PATHS)."""
    if request.method == "POST":
        data = request.get_json(silent=True) or {}
        if "gate_enabled" in data:
            # Money-path toggle: parse strictly so a stray JSON string ("false") can
            # never arm the live veto. Real booleans (the dashboard) pass straight
            # through; recognised string/number tokens map explicitly; anything
            # ambiguous (null / "maybe" / {}) is IGNORED, leaving the gate unchanged
            # (fail-safe toward NOT interfering with live trading).
            _raw = data.get("gate_enabled")
            _parsed = None
            if isinstance(_raw, bool):
                _parsed = _raw
            elif isinstance(_raw, (int, float)):
                _parsed = bool(_raw)
            elif isinstance(_raw, str):
                _s = _raw.strip().lower()
                if _s in ("1", "true", "yes", "on"):
                    _parsed = True
                elif _s in ("0", "false", "no", "off"):
                    _parsed = False
            if _parsed is not None:
                set_entry_quality_gate(_parsed)
                logger.info("Entry Quality VETO %s", "ARMED" if _entry_quality_gate_enabled() else "OFF")
    return jsonify({
        "status":         "ok",
        "engine_enabled": _entry_quality_engine_enabled(),
        "gate_enabled":   _entry_quality_gate_enabled(),
        "min_score":      ENTRY_QUALITY_MIN_SCORE,
        "override_edge":  ENTRY_QUALITY_OVERRIDE_EDGE,
    }), 200


