# ======================================================================================
# TRADING ACADEMY / AI TRADING LIBRARY  (LEARNING-ONLY — walled off from the money path)
# --------------------------------------------------------------------------------------
# A knowledge system: knowledge sources -> AI extraction -> strategy playbook cards ->
# validation lifecycle -> honest backtest links -> trade-management library + Q&A.
# HARD SAFETY INVARIANT: nothing in this section may touch the gate / scoring /
# auto-execute / broker / sizing / dedupe / live-management path. It only does
# INSERT/SELECT on the academy_* tables (NO DDL) and makes outbound read-only AI calls.
# Wiring an APPROVED strategy into live execution is intentionally OUT OF SCOPE here.
# Owner-only: every route is proxied but kept OUT of dashboard-auth OPEN_PATHS.
# ======================================================================================
ACADEMY_STATUSES        = ("UNTESTED", "BACKTESTING", "PAPER_TESTING", "APPROVED", "REJECTED")
ACADEMY_LIFECYCLES      = ("active", "testing", "archived")
ACADEMY_APPLIES         = ("scalp", "swing", "both")
ACADEMY_SOURCE_KINDS    = ("youtube", "book", "article", "recap", "screenshot", "backtest", "tradezella", "other")
ACADEMY_MODEL           = ASSISTANT_MODEL          # reuse the same Replit AI Integrations model
ACADEMY_EXTRACT_TOKENS  = 1800
ACADEMY_ASK_TOKENS      = 900
ACADEMY_SCHEMA_VERSION  = 1
ACADEMY_TABLES          = ("academy_sources", "academy_strategies", "academy_management_rules", "academy_validation_events")

ACADEMY_DB_READY        = False
_ACADEMY_PROBE_LOCK     = threading.Lock()
_ACADEMY_PROBE_TS       = 0.0
_ACADEMY_PROBE_RETRY_SEC = 30.0


def _check_academy_db_ready():
    """Probe the academy_* tables (NO DDL). FAIL-OPEN: on any failure the flag stays
    False and the feature degrades to 'unavailable' instead of erroring."""
    global ACADEMY_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            for t in ACADEMY_TABLES:               # fixed tuple — no user input in the identifier
                cur.execute("SELECT 1 FROM " + t + " LIMIT 1")
                cur.fetchone()
        ACADEMY_DB_READY = True
        logger.info("academy_* tables ready (Trading Academy)")
    except Exception as exc:
        logger.warning("academy tables unavailable (Trading Academy persistence disabled): %s", exc)
    finally:
        try: conn.close()
        except Exception: pass


def _ensure_academy_probe():
    """Lazily run the readiness probe if boot didn't (boot probes live under
    __main__, so a WSGI import would never set the flag). Cheap, idempotent, throttled."""
    global _ACADEMY_PROBE_TS
    if ACADEMY_DB_READY:
        return
    nowm = time.monotonic()
    with _ACADEMY_PROBE_LOCK:
        if ACADEMY_DB_READY:
            return
        if (nowm - _ACADEMY_PROBE_TS) < _ACADEMY_PROBE_RETRY_SEC:
            return
        _ACADEMY_PROBE_TS = nowm
    _check_academy_db_ready()


# ---- small value helpers (defensive; never raise) ------------------------------------
def _academy_clip(s, n=2000):
    if s is None:
        return ""
    if not isinstance(s, str):
        s = str(s)
    s = s.strip()
    return s[:n] if len(s) > n else s


def _academy_clamp_int(v, lo, hi, default=0):
    try:
        iv = int(v)
    except Exception:
        return default
    return max(lo, min(hi, iv))


def _academy_enum(v, allowed, default):
    try:
        s = str(v).strip().lower()
    except Exception:
        return default
    return s if s in allowed else default


def _academy_status(v, default=""):
    """Status enums are UPPERCASE — must NOT be lowercased like the other enums."""
    try:
        s = str(v).strip().upper()
    except Exception:
        return default
    return s if s in ACADEMY_STATUSES else default


def _academy_str_list(v, max_items=12, item_len=400):
    out = []
    if isinstance(v, str):
        v = [p.strip(" -*\t") for p in v.splitlines()]
    if isinstance(v, (list, tuple)):
        for item in v:
            if isinstance(item, dict):
                item = " ".join(str(x) for x in item.values() if x is not None)
            s = _academy_clip(item, item_len)
            if s:
                out.append(s)
            if len(out) >= max_items:
                break
    return out


def _academy_jsonable(row):
    """RealDict row -> JSON-safe dict (datetimes -> ISO). jsonb already comes back as
    dict/list from psycopg2; INT columns are plain ints (no Decimal in this schema)."""
    out = {}
    try:
        items = dict(row).items()
    except Exception:
        return {}
    for k, v in items:
        if isinstance(v, (datetime, date)):
            try: out[k] = v.isoformat()
            except Exception: out[k] = str(v)
        else:
            out[k] = v
    return out


def _academy_json_param(obj):
    try:
        return psycopg2.extras.Json(obj)
    except Exception:
        return None


def _academy_unavailable_resp():
    return jsonify({"ok": False, "error": "The Trading Academy database is not available yet."}), 503


# ---- AI extraction / normalization ---------------------------------------------------
def _academy_ai_chat(messages, max_tokens):
    """One read-only chat completion via the Replit AI Integrations OpenAI proxy.
    Returns (content, error). NEVER touches the money path."""
    base = (os.environ.get("AI_INTEGRATIONS_OPENAI_BASE_URL") or "").strip().rstrip("/")
    key  = (os.environ.get("AI_INTEGRATIONS_OPENAI_API_KEY") or "").strip()
    if not base or not key:
        return None, "The AI service is not configured on this server yet."
    payload = {"model": ACADEMY_MODEL, "messages": messages, "max_completion_tokens": max_tokens}
    try:
        resp = requests.post(
            base + "/chat/completions",
            headers={"Authorization": "Bearer " + key, "Content-Type": "application/json"},
            json=payload,
            timeout=90,
        )
    except Exception as exc:
        logger.warning("academy AI request failed: %s", exc)
        return None, "Could not reach the AI service."
    if resp.status_code != 200:
        logger.warning("academy AI non-200: %s %s", resp.status_code, (resp.text or "")[:300])
        return None, "AI request failed (HTTP %s)." % resp.status_code
    try:
        j = resp.json()
        content = ((j.get("choices") or [{}])[0].get("message") or {}).get("content") or ""
        return content.strip(), None
    except Exception as exc:
        logger.warning("academy AI parse failed: %s", exc)
        return None, "Could not parse the AI response."


def _academy_parse_json(text):
    """Best-effort JSON extraction from a model reply (handles ```json fences and
    surrounding prose). Returns a dict or None."""
    if not text:
        return None
    t = text.strip()
    if t.startswith("```"):
        inner = t[3:]
        if inner[:4].lower() == "json":
            inner = inner[4:]
        if "```" in inner:
            inner = inner.split("```", 1)[0]
        t = inner.strip()
    try:
        obj = json.loads(t)
        return obj if isinstance(obj, dict) else None
    except Exception:
        pass
    try:
        i = text.index("{")
        j = text.rindex("}")
        obj = json.loads(text[i:j + 1])
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None


def _academy_normalize_extraction(raw):
    """Schema-stable contract so the dashboard never breaks on a missing key:
    fixed keys, arrays always present, scalars default to '', enums allowlisted."""
    raw = raw if isinstance(raw, dict) else {}
    pt = raw.get("professional_thinking")
    pt = pt if isinstance(pt, dict) else {}
    applies_raw = _academy_clip(raw.get("applicability"), 60).lower()
    applies = applies_raw if applies_raw in ACADEMY_APPLIES else (applies_raw or "")
    return {
        "schema_version":   ACADEMY_SCHEMA_VERSION,
        "core_concept":     _academy_clip(raw.get("core_concept"), 1500),
        "market_condition": _academy_clip(raw.get("market_condition"), 900),
        "entry_rules":      _academy_str_list(raw.get("entry_rules")),
        "exit_rules":       _academy_str_list(raw.get("exit_rules")),
        "stop_rules":       _academy_str_list(raw.get("stop_rules")),
        "trade_management": _academy_str_list(raw.get("trade_management")),
        "best_session":     _academy_clip(raw.get("best_session"), 400),
        "when_to_avoid":    _academy_str_list(raw.get("when_to_avoid")),
        "failure_signs":    _academy_str_list(raw.get("failure_signs")),
        "example_setup":    _academy_clip(raw.get("example_setup"), 1300),
        "applies_to_mgc_mnq": _academy_clip(raw.get("applies_to_mgc_mnq"), 900),
        "applicability":    applies,
        "professional_thinking": {
            "market_intent":  _academy_clip(pt.get("market_intent"), 600),
            "liquidity":      _academy_clip(pt.get("liquidity"), 600),
            "who_is_trapped": _academy_clip(pt.get("who_is_trapped"), 600),
            "best_location":  _academy_clip(pt.get("best_location"), 600),
            "confirms":       _academy_clip(pt.get("confirms"), 600),
            "invalidates":    _academy_clip(pt.get("invalidates"), 600),
            "management":     _academy_clip(pt.get("management"), 600),
        },
    }


def _academy_empty_extraction():
    return _academy_normalize_extraction({})


_ACADEMY_EXTRACT_PRIMER = (
    "You are a professional futures-trading analyst building a structured trading "
    "knowledge library for a private bot that trades MGC (Micro Gold futures) and MNQ "
    "(Micro Nasdaq-100 futures). You are given a raw knowledge source (a video transcript, "
    "book notes, an article, a trade recap, a chart/screenshot study, a backtest write-up, "
    "or a journal export). Extract ONLY what the source actually teaches. Do NOT invent "
    "rules the source does not state; if something is absent, return an empty string or an "
    "empty list for it.\n\n"
    "Return STRICT JSON (a single JSON object, no prose, no markdown fences) with EXACTLY "
    "these keys:\n"
    "{\n"
    '  \"summary\": \"2-4 sentence plain-English summary of the lesson\",\n'
    '  \"core_concept\": \"the single core idea\",\n'
    '  \"market_condition\": \"the market regime/condition it works in\",\n'
    '  \"entry_rules\": [\"...\"],\n'
    '  \"exit_rules\": [\"...\"],\n'
    '  \"stop_rules\": [\"...\"],\n'
    '  \"trade_management\": [\"...\"],\n'
    '  \"best_session\": \"best time/session to use it\",\n'
    '  \"when_to_avoid\": [\"...\"],\n'
    '  \"failure_signs\": [\"common signs it is failing\"],\n'
    '  \"example_setup\": \"a concrete example setup\",\n'
    '  \"applicability\": \"scalp | swing | both\",\n'
    '  \"applies_to_mgc_mnq\": \"how this would specifically apply to MGC and/or MNQ\",\n'
    '  \"professional_thinking\": {\n'
    '    \"market_intent\": \"what is the market trying to do\",\n'
    '    \"liquidity\": \"where is liquidity\",\n'
    '    \"who_is_trapped\": \"who is trapped / on the wrong side\",\n'
    '    \"best_location\": \"where is the best trade location\",\n'
    '    \"confirms\": \"what confirms the idea\",\n'
    '    \"invalidates\": \"what proves it wrong\",\n'
    '    \"management\": \"how it should be managed\"\n'
    "  }\n"
    "}\n"
    "Keep each field concise. Output JSON only."
)


def _academy_extract(source):
    """Run ONE AI extraction over a source dict. Returns (normalized_extraction, summary,
    error). FAIL-OPEN: on any error returns (empty_extraction, '', error_message)."""
    notes = _academy_clip(source.get("raw_notes"), 14000)
    if not notes:
        return _academy_empty_extraction(), "", "No notes/transcript to extract from."
    user = (
        "SOURCE TITLE: %s\nKIND: %s\nMARKET: %s\nSTRATEGY TYPE: %s\n\nRAW NOTES / TRANSCRIPT:\n%s"
        % (
            _academy_clip(source.get("title"), 300),
            _academy_clip(source.get("source_kind"), 40) or "other",
            _academy_clip(source.get("market_type"), 120),
            _academy_clip(source.get("strategy_type"), 120),
            notes,
        )
    )
    content, err = _academy_ai_chat(
        [{"role": "system", "content": _ACADEMY_EXTRACT_PRIMER},
         {"role": "user", "content": user}],
        ACADEMY_EXTRACT_TOKENS,
    )
    if err:
        return _academy_empty_extraction(), "", err
    parsed = _academy_parse_json(content)
    if not isinstance(parsed, dict):
        return _academy_empty_extraction(), "", "The AI did not return valid JSON."
    norm = _academy_normalize_extraction(parsed)
    summary = _academy_clip(parsed.get("summary") or norm.get("core_concept"), 1500)
    return norm, summary, None


def _academy_apply_extraction(sid, source_row):
    """AI-extract + persist into the source row. Returns the refreshed row dict or None."""
    norm, summary, err = _academy_extract(source_row)
    conn = _learning_conn()
    if conn is None:
        return None
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(
                "UPDATE academy_sources SET extraction = %s, ai_summary = %s, "
                "extracted_at = now(), last_error = %s, updated_at = now() "
                "WHERE id = %s RETURNING *",
                (_academy_json_param(norm), (summary or None), err, int(sid)),
            )
            row = cur.fetchone()
        return _academy_jsonable(row) if row else None
    except Exception as exc:
        logger.warning("academy extraction persist failed: %s", exc)
        return None
    finally:
        try: conn.close()
        except Exception: pass


def _academy_log_event(cur, entity_type, entity_id, from_status, to_status, reason, reviewer="owner"):
    try:
        cur.execute(
            "INSERT INTO academy_validation_events (entity_type, entity_id, from_status, to_status, reason, reviewer) "
            "VALUES (%s,%s,%s,%s,%s,%s)",
            (entity_type, int(entity_id), from_status, to_status, _academy_clip(reason, 800) or None, reviewer),
        )
    except Exception as exc:
        logger.warning("academy event log failed (non-fatal): %s", exc)


# ---- SOURCES -------------------------------------------------------------------------
@app.route("/academy/sources", methods=["GET", "POST"])
def academy_sources():
    """Knowledge Library. GET = list (filters: status, source_kind, q). POST = add a
    source and (by default) run AI extraction immediately. Owner-only, learning-only."""
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()

    if request.method == "POST":
        d = request.get_json(silent=True) or {}
        title = _academy_clip(d.get("title"), 300)
        if not title:
            return jsonify({"ok": False, "error": "A title is required."}), 400
        notes = _academy_clip(d.get("raw_notes"), 16000)
        kind  = _academy_enum(d.get("source_kind"), ACADEMY_SOURCE_KINDS, "other")
        import hashlib
        shash = hashlib.sha1((title + "|" + notes).encode("utf-8", "ignore")).hexdigest() if notes else None
        conn = _learning_conn()
        if conn is None:
            return _academy_unavailable_resp()
        try:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute(
                    "INSERT INTO academy_sources "
                    "(title, author, link, market_type, strategy_type, source_kind, raw_notes, "
                    " trust_rating, status, source_hash, schema_version) "
                    "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING *",
                    (
                        title,
                        _academy_clip(d.get("author"), 200) or None,
                        _academy_clip(d.get("link"), 500) or None,
                        _academy_clip(d.get("market_type"), 120) or None,
                        _academy_clip(d.get("strategy_type"), 120) or None,
                        kind,
                        notes or None,
                        _academy_clamp_int(d.get("trust_rating"), 0, 5, 0),
                        "UNTESTED",
                        shash,
                        ACADEMY_SCHEMA_VERSION,
                    ),
                )
                row = cur.fetchone()
        except Exception as exc:
            logger.warning("academy source insert failed: %s", exc)
            return jsonify({"ok": False, "error": "Could not save the source."}), 500
        finally:
            try: conn.close()
            except Exception: pass

        out = _academy_jsonable(row)
        do_extract = d.get("extract", True) and bool(notes)
        if do_extract:
            refreshed = _academy_apply_extraction(out["id"], out)
            if refreshed:
                out = refreshed
        return jsonify({"ok": True, "source": out}), 200

    # GET list
    status = _academy_status(request.args.get("status"))
    kind   = _academy_enum(request.args.get("source_kind"), ACADEMY_SOURCE_KINDS, "")
    q      = _academy_clip(request.args.get("q"), 120)
    where, params = [], []
    if status:
        where.append("status = %s"); params.append(status)
    if kind:
        where.append("source_kind = %s"); params.append(kind)
    if q:
        where.append("(title ILIKE %s OR author ILIKE %s OR strategy_type ILIKE %s OR market_type ILIKE %s)")
        like = "%" + q + "%"; params.extend([like, like, like, like])
    sql = ("SELECT id, title, author, link, market_type, strategy_type, source_kind, "
           "ai_summary, trust_rating, status, extracted_at, last_error, created_at, updated_at "
           "FROM academy_sources")
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY created_at DESC LIMIT 500"
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, params)
            rows = [_academy_jsonable(r) for r in (cur.fetchall() or [])]
        return jsonify({"ok": True, "sources": rows}), 200
    except Exception as exc:
        logger.warning("academy source list failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load sources."}), 500
    finally:
        try: conn.close()
        except Exception: pass


@app.route("/academy/sources/<int:sid>", methods=["GET", "DELETE"])
def academy_source_detail(sid):
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            if request.method == "DELETE":
                cur.execute("DELETE FROM academy_strategy_sources WHERE source_id = %s", (sid,))
                cur.execute("DELETE FROM academy_sources WHERE id = %s RETURNING id", (sid,))
                gone = cur.fetchone()
                if not gone:
                    return jsonify({"ok": False, "error": "Not found."}), 404
                return jsonify({"ok": True, "deleted": sid}), 200
            cur.execute("SELECT * FROM academy_sources WHERE id = %s", (sid,))
            row = cur.fetchone()
            if not row:
                return jsonify({"ok": False, "error": "Not found."}), 404
            return jsonify({"ok": True, "source": _academy_jsonable(row)}), 200
    except Exception as exc:
        logger.warning("academy source detail failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load the source."}), 500
    finally:
        try: conn.close()
        except Exception: pass


@app.route("/academy/sources/<int:sid>/extract", methods=["POST"])
def academy_source_extract(sid):
    """Re-run AI extraction for an existing source."""
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("SELECT * FROM academy_sources WHERE id = %s", (sid,))
            row = cur.fetchone()
        if not row:
            return jsonify({"ok": False, "error": "Not found."}), 404
    except Exception as exc:
        logger.warning("academy extract reload failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load the source."}), 500
    finally:
        try: conn.close()
        except Exception: pass
    refreshed = _academy_apply_extraction(sid, _academy_jsonable(row))
    if not refreshed:
        return jsonify({"ok": False, "error": "Extraction failed."}), 500
    err = refreshed.get("last_error")
    return jsonify({"ok": not bool(err), "source": refreshed, "error": err}), 200


@app.route("/academy/sources/<int:sid>/status", methods=["POST"])
def academy_source_status(sid):
    return _academy_set_status("source", "academy_sources", sid)


