@app.route("/academy/rules", methods=["GET", "POST"])
def academy_rules():
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()
    if request.method == "POST":
        d = request.get_json(silent=True) or {}
        rule_text = _academy_clip(d.get("rule_text"), 1000)
        if not rule_text:
            return jsonify({"ok": False, "error": "Rule text is required."}), 400
        conn = _learning_conn()
        if conn is None:
            return _academy_unavailable_resp()
        try:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute(
                    "INSERT INTO academy_management_rules "
                    "(rule_text, trigger_condition, action, applies_to, source_id, status, notes) "
                    "VALUES (%s,%s,%s,%s,%s,%s,%s) RETURNING *",
                    (
                        rule_text,
                        _academy_clip(d.get("trigger_condition"), 1000) or None,
                        _academy_clip(d.get("action"), 1000) or None,
                        _academy_enum(d.get("applies_to"), ACADEMY_APPLIES, "both"),
                        (int(d["source_id"]) if str(d.get("source_id")).isdigit() else None),
                        "UNTESTED",
                        _academy_clip(d.get("notes"), 1000) or None,
                    ),
                )
                row = cur.fetchone()
            return jsonify({"ok": True, "rule": _academy_jsonable(row)}), 200
        except Exception as exc:
            logger.warning("academy rule insert failed: %s", exc)
            return jsonify({"ok": False, "error": "Could not save the rule."}), 500
        finally:
            try: conn.close()
            except Exception: pass

    status  = _academy_status(request.args.get("status"))
    applies = _academy_enum(request.args.get("applies_to"), ACADEMY_APPLIES, "")
    where, params = [], []
    if status:
        where.append("status = %s"); params.append(status)
    if applies:
        where.append("applies_to = %s"); params.append(applies)
    sql = "SELECT * FROM academy_management_rules"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY created_at DESC LIMIT 500"
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, params)
            rows = [_academy_jsonable(r) for r in (cur.fetchall() or [])]
        return jsonify({"ok": True, "rules": rows}), 200
    except Exception as exc:
        logger.warning("academy rule list failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load rules."}), 500
    finally:
        try: conn.close()
        except Exception: pass


